  private static func run(_ name: String, _ test: () throws -> Void) throws {
    if let testNameFilter,
      name.range(of: testNameFilter, options: [.caseInsensitive, .diacriticInsensitive]) == nil
    {
      return
    }
    executedTestCount += 1
    do {
      try test()
      print("ok - \(name)")
    } catch {
      print("not ok - \(name): \(error)")
      throw error
    }
  }

  private static func liveKeychainUserDataPath(_ environment: [String: String], testName: String)
    -> String?
  {
    guard environment[liveKeychainOptInEnvironmentKey] == "1" else {
      print(
        "skipped - \(testName): set \(liveKeychainOptInEnvironmentKey)=1 and \(liveUserDataPathEnvironmentKey) to run against the real Keychain"
      )
      return nil
    }
    guard let dataPath = nonEmpty(environment[liveUserDataPathEnvironmentKey]) else {
      print(
        "skipped - \(testName): set \(liveUserDataPathEnvironmentKey) to the explicit Relay Console user data path"
      )
      return nil
    }
    return dataPath
  }

  private static func testCanonicalGuardReasonCodes() throws {
    let context = context(roles: [.member])

    let roleDenied = try unwrap(
      ServiceGuard.requireAnyRole([.owner, .admin], context: context),
      "member mutation should be denied"
    )
    try expect(roleDenied.stateKind == .readOnly, "unexpected role-denied state")
    try expect(roleDenied.reasonCode == .authorityRoleRequired, "unexpected role-denied reason")
    try expect(roleDenied.auditRequired, "role-denied mutation should require audit")

    let invalid = ServiceGuard.invalidInput(context: context, message: "Name is required.")
    try expect(invalid.stateKind == .disabled, "unexpected invalid-input state")
    try expect(invalid.reasonCode == .inputInvalid, "unexpected invalid-input reason")

    let decision = ServiceGuard.decisionRequired(
      context: context, decisionId: "D-0004", message: "Cloud mode requires a decision.")
    try expect(decision.stateKind == .decisionGated, "unexpected decision state")
    try expect(decision.reasonCode == .decisionRequired, "unexpected decision reason")
    try expect(decision.decisionId == "D-0004", "decision id was not preserved")

    let unavailable = ServiceGuard.unavailable(
      context: context,
      reasonCode: .featureMissingService,
      message: "Service is not ready."
    )
    try expect(unavailable.stateKind == .unavailable, "unexpected unavailable state")
    try expect(unavailable.reasonCode == .featureMissingService, "unexpected unavailable reason")
  }

  private static func testLockedRecoveryDataPersistsWithoutGrantingAccess() throws {
    let root = FileManager.default.temporaryDirectory
      .appendingPathComponent("RelayConsoleLockedRecoveryContract", isDirectory: true)
      .appendingPathComponent(UUID().uuidString, isDirectory: true)
    defer { try? FileManager.default.removeItem(at: root) }

    var workspaceId = ""
    var agentId = ""
    var threadId = ""
    var harnessId = ""
    do {
      let services = try makeServices(root: root, seedActiveEntitlement: false)
      let workspace = try unwrap(
        services.data.getAppState().activeWorkspace, "missing recovery workspace")
      workspaceId = workspace.id
      let harness = try services.data.upsertHarness(
        runtimeType: .hermes,
        displayName: "User-managed Hermes Agent",
        mode: .userManaged,
        config: [
          "kind": .string("external_harness_install"),
          "installPath": .string("/Users/example/hermes-agent"),
          "lifecycleState": .string(HarnessLifecycleState.connected.rawValue),
        ])
      harnessId = harness.id
      let agent = try services.data.createAgent(
        workspaceId: workspace.id,
        name: "Recovery Agent",
        harnessId: harness.id)
      agentId = agent.id
      let thread = try services.data.createThread(
        workspaceId: workspace.id,
        title: "Recovery Conversation",
        selectedAgentId: agent.id,
        threadType: .direct)
      threadId = thread.id
      _ = try services.data.createMessage(
        threadId: thread.id,
        senderType: .user,
        senderName: "You",
        content: "This message stays on this Mac.")
      try services.data.setAppSetting("recovery.contractSetting", value: "retained")

      try expect(
        sqliteInteger(
          try services.database.get("SELECT COUNT(*) AS count FROM cloud_accounts")?["count"])
          == 0,
        "recovery fixture unexpectedly created a cloud account")
      try expect(
        sqliteInteger(
          try services.database.get("SELECT COUNT(*) AS count FROM workspace_sync_links")?["count"])
          == 0,
        "recovery fixture unexpectedly created a cloud sync link")
      services.database.close()
    }

    do {
      let relaunched = try makeServices(root: root, seedActiveEntitlement: false)
      try expect(
        try relaunched.data.getWorkspace(workspaceId).id == workspaceId,
        "recovery workspace did not survive relaunch")
      try expect(
        try relaunched.data.getAgent(agentId).binding.harnessId == harnessId,
        "recovery agent/runtime binding did not survive relaunch")
      let harness = try relaunched.data.getHarness(harnessId)
      try expect(harness.mode == .userManaged, "user-managed runtime state did not survive relaunch")
      try expect(
        harness.config["installPath"] == .string("/Users/example/hermes-agent"),
        "user-managed runtime path did not survive relaunch")
      let messages = try relaunched.data.listMessages(threadId: threadId)
      try expect(
        messages.map(\.content) == ["This message stays on this Mac."],
        "recovery conversation did not survive relaunch")
      let setting: String = try relaunched.data.getAppSetting(
        "recovery.contractSetting", fallback: "missing")
      try expect(setting == "retained", "recovery setting did not survive relaunch")
      try expect(
        try relaunched.entitlement.currentAccess().state == .accountRequired,
        "persisted recovery data incorrectly granted ordinary Relay access")
      relaunched.database.close()
    }
  }

  private static func testCloudFailurePreservesExistingRecoveryData() throws {
    let services = try makeServices()
    let workspace = try unwrap(
      services.data.getAppState().activeWorkspace, "missing recovery workspace")
    let manifest = try JSONDecoder().decode(
      CloudDeploymentManifest.self,
      from: Data(
        #"{"deploymentId":"relay-production","deploymentKey":"relay-production","displayName":"Relay Cloud","ownershipType":"relay_managed","apiVersion":"v1","syncContractVersion":"2026-07-21.agent-parity.v2","runtimeContractVersion":"v1","marketplaceContractVersion":"v1","minimumClients":{"relayConsoleSwift":"0.1.0","ios":"1.0.0","web":"0.0.1"},"origins":{"api":"https://your-backend.up.railway.app/api/v1","websocket":"wss://your-backend.up.railway.app"},"features":{}}"#.utf8))
    let deploymentId = try services.cloudConnections.saveDeployment(manifest: manifest)
    let accountId = try services.cloudConnections.saveAccount(
      deploymentId: deploymentId,
      remoteUserId: "remote-user",
      displayName: "Relay User",
      email: "relay-user@example.com",
      accessToken: "test-access-token",
      refreshToken: "test-refresh-token",
      accessExpiresAt: nil)
    let linkId = try services.cloudSync.createLocalLink(
      localWorkspaceId: workspace.id,
      deploymentId: deploymentId,
      accountId: accountId,
      remoteInstallationId: "remote-installation",
      remoteWorkspaceId: "remote-workspace",
      remoteSyncLinkId: "remote-link",
      attachmentPolicy: .metadataOnly,
      offlineRetention: true)
    let agent = try createCloudSyncTestAgent(services: services, workspaceId: workspace.id)
    let thread = try services.data.createThread(
      workspaceId: workspace.id,
      title: "Retained local conversation",
      selectedAgentId: agent.id,
      threadType: .direct)
    _ = try services.data.createMessage(
      threadId: thread.id,
      senderType: .user,
      senderName: "You",
      content: "Written before Railway became unavailable.")

    let syncResult = waitForAsync {
      try await services.cloudSync.syncOnce(
        syncLinkId: linkId,
        transport: UnavailableRelayCloudTransport())
    }
    guard case .failure = syncResult else {
      throw ServiceTestFailure("unavailable Relay Cloud sync unexpectedly succeeded")
    }
    try expect(
      try services.cloudSync.status(syncLinkId: linkId).state == .offline,
      "failed Relay Cloud sync did not enter an explicit offline state")

    let messages = try services.data.listMessages(threadId: thread.id)
    try expect(
      messages.map(\.content) == ["Written before Railway became unavailable."],
      "Relay Cloud failure changed existing local recovery data")
    try expect(
      try services.data.getAgent(agent.id).id == agent.id,
      "Relay Cloud failure removed the local agent")
  }

  private static func testRelayCloudLaunchAcceptsOnlyConfiguredRailwayDeployment() throws {
    let services = try makeServices()
    var manifest = try JSONDecoder().decode(
      CloudDeploymentManifest.self,
      from: Data(
        #"{"deploymentId":"relay-production","deploymentKey":"relay-production","displayName":"Relay Cloud","ownershipType":"relay_managed","apiVersion":"v1","syncContractVersion":"2026-07-21.agent-parity.v2","runtimeContractVersion":"bridge.v1","marketplaceContractVersion":"swift-marketplace.v1","minimumClients":{"relayConsoleSwift":"0.1.0","ios":"1.0.0","web":"0.0.1"},"origins":{"api":"https://your-backend.up.railway.app/api/v1","websocket":"wss://your-backend.up.railway.app"},"features":{"workspaceSync":true}}"#.utf8))

    let deploymentId = try services.cloudConnections.saveDeployment(manifest: manifest)
    try expect(deploymentId == "relay-production", "configured Railway deployment was rejected")
    try expect(try services.cloudConnections.listDeployments().map(\.id) == [deploymentId], "configured Railway deployment was not retained as the only launch deployment")

    manifest.minimumClients[RelayCloudLaunchContract.clientKind] = "0.2.0"
    do {
      _ = try services.cloudConnections.saveDeployment(manifest: manifest)
      throw ServiceTestFailure("an obsolete Mac client accepted a newer Relay Cloud minimum")
    } catch let error as RelayError {
      try expect(error.code == .unsupported, "obsolete Mac rejection used the wrong error")
    }
    manifest.minimumClients[RelayCloudLaunchContract.clientKind] = RelayConsoleReleaseMetadata.current.version

    manifest.ownershipType = "self_hosted"
    do {
      _ = try services.cloudConnections.saveDeployment(manifest: manifest)
      throw ServiceTestFailure("customer-owned Railway deployment was accepted")
    } catch let error as RelayError {
      try expect(error.code == .permissionDenied, "customer-owned Railway rejection used the wrong error")
    }

    manifest.ownershipType = RelayCloudLaunchContract.deploymentOwnership
    manifest.origins.api = "https://customer.example/api/v1"
    manifest.origins.websocket = "wss://customer.example"
    do {
      _ = try services.cloudConnections.saveDeployment(manifest: manifest)
      throw ServiceTestFailure("an unconfigured control plane was accepted")
    } catch let error as RelayError {
      try expect(error.code == .permissionDenied, "unconfigured origin rejection used the wrong error")
    }
  }

  private static func testSignedInMacAutomaticallyRegistersAndLinksWorkspace() throws {
    let services = try makeServices()
    let workspace = try unwrap(services.data.getAppState().activeWorkspace, "missing workspace")
    let importedAgent = try createCloudSyncTestAgent(
      services: services,
      workspaceId: workspace.id
    )
    let importedCronJobs = """
      {
        "jobs": [
          {
            "id": "cron-verbatim",
            "name": "Verbatim JSON",
            "schedule": {
              "kind": "interval",
              "minutes": 15
            }
          }
        ]
      }
      """
    let importedCronJobsURL = URL(
      fileURLWithPath: try unwrap(
        importedAgent.binding.hermesHomePath,
        "cloud sync test agent has no Hermes home"
      ),
      isDirectory: true
    )
    .appendingPathComponent("cron", isDirectory: true)
    .appendingPathComponent("jobs.json", isDirectory: false)
    try FileManager.default.createDirectory(
      at: importedCronJobsURL.deletingLastPathComponent(),
      withIntermediateDirectories: true
    )
    try importedCronJobs.write(
      to: importedCronJobsURL,
      atomically: true,
      encoding: .utf8
    )
    let importedCronJobsHash = SHA256.hash(data: Data(importedCronJobs.utf8))
      .map { String(format: "%02x", $0) }
      .joined()
    try services.database.run(
      """
      INSERT INTO agent_documents(
        id,workspace_id,agent_id,runtime_type,root,folder,filename,document_kind,
        content,content_hash,created_at,updated_at
      ) VALUES(?,?,?,?,?,?,?,?,?,?,?,?)
      """,
      [
        .text("cron-verbatim-document"),
        .text(workspace.id),
        .text(importedAgent.id),
        .text("hermes"),
        .text("agent"),
        .text("cron"),
        .text("jobs.json"),
        .text("cron"),
        .text(importedCronJobs),
        .text(importedCronJobsHash),
        .text("2026-07-29T14:30:00.000Z"),
        .text("2026-07-29T14:30:00.000Z"),
      ]
    )
    let importedThread = try services.data.createThread(
      workspaceId: workspace.id,
      title: "Imported identity conversation",
      selectedAgentId: importedAgent.id,
      threadType: .direct
    )
    let canonicalImportedAgentId = "canonical-imported-agent"
    let canonicalImportedThreadId = "canonical-imported-thread"
    let account = try unwrap(
      services.cloudConnections.listAccounts().first,
      "paid entitlement fixture did not retain its signed-in account"
    )
    let manifest = try JSONDecoder().decode(
      CloudDeploymentManifest.self,
      from: Data(
        #"{"deploymentId":"relay-production","deploymentKey":"relay-production","displayName":"Relay","ownershipType":"relay_managed","apiVersion":"v1","syncContractVersion":"2026-07-21.agent-parity.v2","runtimeContractVersion":"bridge.v1","marketplaceContractVersion":"swift-marketplace.v1","minimumClients":{"relayConsoleSwift":"0.1.0","ios":"1.0.0","web":"0.0.1"},"origins":{"api":"https://your-backend.up.railway.app/api/v1","websocket":"wss://your-backend.up.railway.app"},"features":{}}"#
          .utf8
      )
    )
    let transport = AutomaticWorkspaceLinkRelayCloudTransport(changes: [
      [
        "objectType": "agent",
        "objectId": "railway-agent",
        "serverVersion": "1",
        "changeType": "upsert",
        "payload": [
          "id": "railway-agent",
          "canonicalObjectId": "railway-agent",
          "name": "Railway change-feed agent",
          "externalId": "hermes:railway-agent",
          "runtimeType": "hermes",
          "lifecycleStatus": "active",
        ],
      ],
      [
        "objectType": "agent",
        "objectId": canonicalImportedAgentId,
        "serverVersion": "1",
        "changeType": "upsert",
        "payload": [
          "id": canonicalImportedAgentId,
          "canonicalObjectId": canonicalImportedAgentId,
          "name": importedAgent.name,
          "externalId": "imported-identity-agent",
          "runtimeType": "hermes",
          "lifecycleStatus": "active",
        ],
      ],
      [
        "objectType": "thread",
        "objectId": canonicalImportedThreadId,
        "serverVersion": "1",
        "changeType": "upsert",
        "payload": [
          "id": canonicalImportedThreadId,
          "canonicalObjectId": canonicalImportedThreadId,
          "title": "Imported identity conversation",
          "agentIds": [canonicalImportedAgentId],
          "type": "direct",
          "status": "active",
        ],
      ],
      [
        "objectType": "agent_document",
        "objectId": "railway-document-one",
        "serverVersion": "1",
        "changeType": "upsert",
        "payload": [
          "canonicalObjectId": "shared-legacy-document-id",
          "agentId": "railway-agent",
          "root": "agent",
          "folder": "memory",
          "filename": "one.md",
          "content": "First document",
          "documentKind": "memory",
        ],
      ],
      [
        "objectType": "agent_document",
        "objectId": "railway-document-two",
        "serverVersion": "1",
        "changeType": "upsert",
        "payload": [
          "canonicalObjectId": "shared-legacy-document-id",
          "agentId": "railway-agent",
          "root": "agent",
          "folder": "memory",
          "filename": "two.md",
          "content": "Second document",
          "documentKind": "memory",
        ],
      ],
    ], canonicalObjectIds: [
      importedAgent.id: canonicalImportedAgentId,
      importedThread.id: canonicalImportedThreadId,
    ])

    let link = try awaitResult {
      try await services.cloudSync.ensureAutomaticWorkspaceLink(
        localWorkspaceId: workspace.id,
        accountId: account.id,
        remoteWorkspaceId: "remote-workspace",
        manifest: manifest,
        transport: transport
      )
    }

    try expect(link.localWorkspaceId == workspace.id, "automatic link used the wrong local workspace")
    try expect(
      link.remoteWorkspaceId == "remote-workspace",
      "automatic link used the wrong Railway workspace"
    )
    try expect(
      link.remoteInstallationId == "installation-auto",
      "automatic link did not persist the registered installation"
    )
    try expect(
      link.attachmentPolicy == .metadataOnly && link.offlineRetention,
      "automatic link did not use the launch-safe local-first policy"
    )
    try expect(
      transport.recordedPaths().filter { $0 == "client-installations" }.count == 1,
      "automatic link did not register exactly one installation"
    )
    try expect(
      transport.recordedBodies(for: "client-installations").first?["workspaceId"] as? String
        == "remote-workspace",
      "automatic link did not identify its Railway workspace while registering the Mac"
    )
    try expect(
      transport.recordedPaths().contains("workspace-sync-links"),
      "automatic link did not create a Railway workspace link"
    )
    try expect(
      transport.recordedPaths().contains("workspace-imports"),
      "automatic link did not perform its initial bounded import"
    )
    let importedCronPayload = transport
      .recordedBodies(for: "workspace-imports/workspace-import-auto/batches")
      .compactMap { $0["records"] as? [[String: Any]] }
      .flatMap { $0 }
      .first {
        ($0["objectType"] as? String) == "agent_document"
          && (($0["payload"] as? [String: Any])?["filename"] as? String) == "jobs.json"
          && (($0["payload"] as? [String: Any])?["agentId"] as? String) == importedAgent.id
      }?["payload"] as? [String: Any]
    try expect(
      importedCronPayload?["content"] as? String == importedCronJobs,
      "JSON agent document content changed wire type instead of remaining verbatim text"
    )
    try expect(
      (try services.data.listAgents(workspaceId: workspace.id)).contains {
        $0.name == "Railway change-feed agent"
      },
      "a Railway agent change could not be materialized in the local workspace"
    )
    try expect(
      sqliteInteger(try services.database.get(
        "SELECT COUNT(*) AS count FROM agents WHERE workspace_id=? AND name=?",
        [.text(workspace.id), .text(importedAgent.name)]
      )?["count"]) == 1,
      "an imported Railway agent snapshot created a second local agent"
    )
    try expect(
      sqliteInteger(try services.database.get(
        "SELECT COUNT(*) AS count FROM threads WHERE workspace_id=? AND title='Imported identity conversation'",
        [.text(workspace.id)]
      )?["count"]) == 1,
      "an imported Railway thread snapshot created a second local conversation"
    )
    try expect(
      sqliteText(try services.database.get(
        "SELECT selected_agent_id FROM threads WHERE id=?",
        [.text(importedThread.id)]
      )?["selected_agent_id"]) == importedAgent.id,
      "the imported Railway thread lost its original local agent identity"
    )
    let railwayAgentId = try unwrap(
      (try services.data.listAgents(workspaceId: workspace.id)).first {
        $0.name == "Railway change-feed agent"
      }?.id,
      "Railway change-feed agent id was unavailable"
    )
    let documentCountRow = try services.database.get(
        "SELECT COUNT(*) AS count FROM agent_documents WHERE agent_id=? AND folder='memory'",
        [.text(railwayAgentId)]
      )
    guard case .integer(let documentCount)? = documentCountRow?["count"] else {
      throw ServiceTestFailure("Railway document count was unavailable")
    }
    try expect(
      documentCount == 2,
      "Railway documents with a shared legacy canonical id collided locally"
    )

    let agent = try createCloudSyncTestAgent(services: services, workspaceId: workspace.id)
    try expect(
      try services.cloudSync.status(syncLinkId: link.id).pendingMutationCount > 0,
      "an agent created after the initial import was not queued for prompt synchronization"
    )
    try awaitResult {
      try await services.cloudSync.syncOnce(syncLinkId: link.id, transport: transport)
    }
    try expect(
      try services.cloudSync.remoteMarketplaceAgentId(
        localWorkspaceId: workspace.id,
        localAgentId: agent.id
      ) == agent.id,
      "a newly created agent did not receive its Railway identity on the next synchronization"
    )
    try expect(
      try services.cloudSync.status(syncLinkId: link.id).pendingMutationCount == 0,
      "the newly created agent remained queued after a successful synchronization"
    )

    _ = try awaitResult {
      try await services.cloudSync.ensureAutomaticWorkspaceLink(
        localWorkspaceId: workspace.id,
        accountId: account.id,
        remoteWorkspaceId: "remote-workspace",
        manifest: manifest,
        transport: transport
      )
    }
    try expect(
      transport.recordedPaths().filter { $0 == "client-installations" }.count == 1,
      "retrying automatic connection created a duplicate installation"
    )

    do {
      _ = try awaitResult {
        try await services.cloudSync.ensureAutomaticWorkspaceLink(
          localWorkspaceId: workspace.id,
          accountId: "different-account",
          remoteWorkspaceId: "different-workspace",
          manifest: manifest,
          transport: transport
        )
      }
      throw ServiceTestFailure("a different account reused the existing local workspace link")
    } catch let error as RelayError {
      try expect(
        error.code == .permissionDenied,
        "cross-account local workspace reuse returned the wrong error"
      )
    }

    let malformedCronAgentId = "malformed-cron-local-agent"
    try services.database.run(
      """
      INSERT INTO remote_object_versions(
        sync_link_id,object_type,local_object_id,canonical_object_id,server_version,updated_at
      ) VALUES(?,'agent',?,?,?,?)
      ON CONFLICT(sync_link_id,object_type,local_object_id) DO UPDATE SET
        canonical_object_id=excluded.canonical_object_id,
        server_version=excluded.server_version,
        updated_at=excluded.updated_at
      """,
      [
        .text(link.id),
        .text(importedAgent.id),
        .text(malformedCronAgentId),
        .text("1"),
        .text("2026-07-29T14:31:00.000Z"),
      ]
    )
    let malformedCronTransport = AutomaticWorkspaceLinkRelayCloudTransport(changes: [
      [
        "objectType": "agent_document",
        "objectId": "malformed-cron-document",
        "serverVersion": "2",
        "changeType": "upsert",
        "payload": [
          "canonicalObjectId": "malformed-cron-document",
          "agentId": malformedCronAgentId,
          "root": "agent",
          "folder": "cron",
          "filename": "jobs.json",
          "content": ["jobs": []],
          "documentKind": "cron",
        ],
      ]
    ])
    do {
      try awaitResult {
        try await services.cloudSync.syncOnce(
          syncLinkId: link.id,
          transport: malformedCronTransport
        )
      }
      throw ServiceTestFailure("structured cron content was accepted as a text document")
    } catch let error as RelayError {
      try expect(
        error.code == .invalidInput,
        "structured cron content rejection used the wrong error: \(error.code.rawValue) \(error.message)"
      )
    }
    try expect(
      try String(contentsOf: importedCronJobsURL, encoding: .utf8) == importedCronJobs,
      "malformed cloud cron content overwrote the valid local jobs.json"
    )
  }

  private static func testStalledInitialImportResumesWithNewAgents() throws {
    let services = try makeServices()
    let workspace = try unwrap(services.data.getAppState().activeWorkspace, "missing workspace")
    let account = try unwrap(
      services.cloudConnections.listAccounts().first,
      "paid entitlement fixture did not retain its signed-in account"
    )
    let manifest = try JSONDecoder().decode(
      CloudDeploymentManifest.self,
      from: Data(
        #"{"deploymentId":"relay-production","deploymentKey":"relay-production","displayName":"Relay","ownershipType":"relay_managed","apiVersion":"v1","syncContractVersion":"2026-07-21.agent-parity.v2","runtimeContractVersion":"bridge.v1","marketplaceContractVersion":"swift-marketplace.v1","minimumClients":{"relayConsoleSwift":"0.1.0","ios":"1.0.0","web":"0.0.1"},"origins":{"api":"https://your-backend.up.railway.app/api/v1","websocket":"wss://your-backend.up.railway.app"},"features":{}}"#
          .utf8
      )
    )
    let transport = AutomaticWorkspaceLinkRelayCloudTransport(workspaceImportFailures: 1)

    do {
      _ = try awaitResult {
        try await services.cloudSync.ensureAutomaticWorkspaceLink(
          localWorkspaceId: workspace.id,
          accountId: account.id,
          remoteWorkspaceId: "remote-workspace",
          manifest: manifest,
          transport: transport
        )
      }
      throw ServiceTestFailure("interrupted initial import unexpectedly succeeded")
    } catch let error as RelayError {
      try expect(
        error.code == .internalError,
        "interrupted initial import returned the wrong error"
      )
    }

    let link = try unwrap(
      services.cloudSync.listLinks().first { $0.localWorkspaceId == workspace.id },
      "interrupted import did not retain its workspace link"
    )
    try expect(
      try services.cloudSync.status(syncLinkId: link.id).state == .offline,
      "interrupted initial import remained silently importing instead of becoming retryable"
    )

    let agent = try createServiceAgent(services: services, workspaceId: workspace.id)
    try expect(
      try services.cloudSync.status(syncLinkId: link.id).pendingMutationCount > 0,
      "an agent created during the import interruption was not queued"
    )

    let resumed = try awaitResult {
      try await services.cloudSync.ensureAutomaticWorkspaceLink(
        localWorkspaceId: workspace.id,
        accountId: account.id,
        remoteWorkspaceId: "remote-workspace",
        manifest: manifest,
        transport: transport
      )
    }
    try expect(resumed.state == .linked, "resumed initial import did not finish linking")
    try expect(
      try services.cloudSync.remoteMarketplaceAgentId(
        localWorkspaceId: workspace.id,
        localAgentId: agent.id
      ) == agent.id,
      "agent created during the interruption was not included when the import resumed"
    )
    try expect(
      try services.cloudSync.status(syncLinkId: link.id).pendingMutationCount == 0,
      "resumed import left the new agent pending"
    )
    try expect(
      transport.recordedPaths().filter { $0 == "workspace-imports" }.count == 2,
      "resuming the prepared import did not retry the interrupted Railway request exactly once"
    )
  }

  private static func testConcurrentAccessChecksShareTokenRefresh() throws {
    let services = try makeServices()
    let account = try unwrap(
      services.cloudConnections.listAccounts().first,
      "paid entitlement fixture did not retain its signed-in account"
    )
    try services.database.run(
      "UPDATE cloud_accounts SET access_expires_at=? WHERE id=?",
      [.text("2026-01-01T00:00:00.000Z"), .text(account.id)]
    )
    let transport = RotatingRefreshRelayCloudTransport()

    let tokens = try awaitResult {
      try await withThrowingTaskGroup(of: String.self) { group in
        for _ in 0..<8 {
          group.addTask {
            try await services.cloudConnections.validAccessToken(
              accountId: account.id,
              transport: transport
            )
          }
        }
        var values: [String] = []
        for try await value in group {
          values.append(value)
        }
        return values
      }
    }

    try expect(
      tokens.count == 8 && tokens.allSatisfy { $0 == "rotated-access-token" },
      "concurrent access checks did not share the rotated access token"
    )
    try expect(
      transport.refreshCount() == 1,
      "concurrent access checks reused a one-time Railway refresh credential"
    )
    try expect(
      try services.cloudConnections.listAccounts().first?.id == account.id,
      "a successful coordinated token refresh signed the account out"
    )
  }

  private static func testHermesMarketplaceBridgeInstallsVerifiedManagedSkillFiles() throws {
    let root = FileManager.default.temporaryDirectory
      .appendingPathComponent(UUID().uuidString, isDirectory: true)
    try FileManager.default.createDirectory(at: root, withIntermediateDirectories: true)
    defer { try? FileManager.default.removeItem(at: root) }
    let content = "# Jotform\n"
    let hash = SHA256.hash(data: Data(content.utf8))
      .map { String(format: "%02x", $0) }
      .joined()
    let roleManifest = #"{"roles":[{"role":"worker"}]}"#
    let roleManifestHash = SHA256.hash(data: Data(roleManifest.utf8))
      .map { String(format: "%02x", $0) }
      .joined()

    let result = try MarketplaceHermesSkillInstaller.install(
      payload: [
        "runtimeFormat": "hermes",
        "agentId": "profile:paige",
        "appSlug": "jotform",
        "skillName": "jotform-router",
        "targetRoot": "skills/jotform-router",
        "files": [
          [
            "relativePath": "SKILL.md",
            "content": content,
            "sha256": hash,
          ],
          [
            "relativePath": "references/roles_manifest.json",
            "content": roleManifest,
            "sha256": roleManifestHash,
          ],
        ],
      ],
      profileRoot: root
    )

    try expect(
      result.installedFiles == [
        "skills/jotform-router/SKILL.md",
        "skills/jotform-router/references/roles_manifest.json",
      ],
      "The bridge should report the complete generated Hermes skill file set")
    try expect(
      String(
        contentsOf: root.appendingPathComponent("skills/jotform-router/SKILL.md"),
        encoding: .utf8
      ) == content,
      "The bridge should write verified skill content beneath the selected profile")
    try expect(
      String(
        contentsOf: root.appendingPathComponent(
          "skills/jotform-router/references/roles_manifest.json"),
        encoding: .utf8
      ) == roleManifest,
      "The bridge should install Railway's generated role manifest")
  }

  private static func testHermesMarketplaceBridgeRejectsUnsafeOrCorruptedSkillFiles() throws {
    let root = FileManager.default.temporaryDirectory
      .appendingPathComponent(UUID().uuidString, isDirectory: true)
    try FileManager.default.createDirectory(at: root, withIntermediateDirectories: true)
    defer { try? FileManager.default.removeItem(at: root) }
    let base: [String: Any] = [
      "runtimeFormat": "hermes",
      "agentId": "profile:paige",
      "appSlug": "jotform",
      "skillName": "jotform-router",
      "targetRoot": "skills/jotform-router",
    ]
    var traversal = base
    traversal["files"] = [[
      "relativePath": "../SOUL.md",
      "content": "unsafe",
      "sha256": String(repeating: "0", count: 64),
    ]]
    do {
      _ = try MarketplaceHermesSkillInstaller.install(payload: traversal, profileRoot: root)
      throw ServiceTestFailure("The bridge accepted a traversing Marketplace path")
    } catch let error as ServiceTestFailure {
      throw error
    } catch {}

    var mismatch = base
    mismatch["files"] = [[
      "relativePath": "SKILL.md",
      "content": "changed",
      "sha256": String(repeating: "0", count: 64),
    ]]
    do {
      _ = try MarketplaceHermesSkillInstaller.install(payload: mismatch, profileRoot: root)
      throw ServiceTestFailure("The bridge accepted a corrupted Marketplace file")
    } catch let error as ServiceTestFailure {
      throw error
    } catch {}

    let arbitraryJSON = #"{"unsafe":true}"#
    let arbitraryJSONHash = SHA256.hash(data: Data(arbitraryJSON.utf8))
      .map { String(format: "%02x", $0) }
      .joined()
    var unexpectedJSON = base
    unexpectedJSON["files"] = [[
      "relativePath": "references/arbitrary.json",
      "content": arbitraryJSON,
      "sha256": arbitraryJSONHash,
    ]]
    do {
      _ = try MarketplaceHermesSkillInstaller.install(
        payload: unexpectedJSON,
        profileRoot: root
      )
      throw ServiceTestFailure("The bridge accepted an unrecognized JSON file")
    } catch let error as ServiceTestFailure {
      throw error
    } catch {}
  }

  private static func testHermesCloudMarketplaceToolsUseAuthenticatedRailwayBridge() throws {
    let transport = RecordingMarketplaceToolCloudTransport()
    let proxy = CloudMarketplaceRuntimeToolProxy()
    proxy.register(
      localDispatchId: "local-dispatch",
      cloudDispatchId: "railway-dispatch",
      workspaceId: "workspace-1",
      agentId: "agent-1",
      tools: [[
        "name": .string("jotform.manage"),
        "functionName": .string("jotform_manage"),
        "aliases": .array([.string("jotform.manage"), .string("jotform_manage")]),
        "execution": .object([
          "transport": .string("clawchat_bridge_marketplace_tool"),
          "endpointBasePath": .string(
            "/api/v1/bridge/runtime-dispatches/{dispatchId}/marketplace-tools/jotform"
          ),
          "requiresBridgeAccessToken": .bool(true),
        ]),
      ]],
      transport: transport,
      accessToken: "bridge-access-token"
    )
    defer { proxy.unregister(localDispatchId: "local-dispatch") }

    let result = try proxy.execute(
      localDispatchId: "local-dispatch",
      toolName: "jotform_manage",
      payload: [
        "operation": .string("form_create"),
        "form": .object(["title": .string("Relay Console Integration Test")]),
      ],
      runtime: MarketplaceRuntimeToolExecutionContext(
        agentId: "agent-1",
        workspaceId: "workspace-1",
        runtimeType: .hermes,
        dispatchId: "local-dispatch"
      )
    )

    try expect(result["ok"] == .bool(true), "Railway Marketplace proxy should return the broker result")
    let request = try unwrap(transport.lastRequest, "Railway Marketplace proxy did not issue a request")
    try expect(
      request.path
        == "bridge/runtime-dispatches/railway-dispatch/marketplace-tools/jotform/jotform_manage",
      "Railway Marketplace proxy used the wrong fixed bridge route"
    )
    try expect(
      request.accessToken == "bridge-access-token",
      "Railway Marketplace proxy did not use the authenticated bridge token"
    )
    try expect(
      request.body?["operation"] as? String == "form_create",
      "Railway Marketplace proxy did not preserve the tool payload"
    )
  }

