  private static func testHermesApprovedMarketplaceActionRebindsStaleGatewayDispatchContext()
    throws
  {
    let transport = RecordingMarketplaceToolCloudTransport()
    let proxy = CloudMarketplaceRuntimeToolProxy()
    proxy.configureBridgeSession(
      transport: transport,
      accessToken: "bridge-access-token",
      remoteAgentIds: ["local-agent": "railway-agent"]
    )
    _ = try awaitResult {
      try await proxy.prepareLocalDispatch(
        localDispatchId: "approval-request-dispatch",
        workspaceId: "local-workspace",
        localAgentId: "local-agent"
      )
    }
    proxy.unregister(localDispatchId: "approval-request-dispatch")
    _ = try awaitResult {
      try await proxy.prepareLocalDispatch(
        localDispatchId: "approved-action-dispatch",
        workspaceId: "local-workspace",
        localAgentId: "local-agent"
      )
    }
    defer {
      proxy.unregister(localDispatchId: "approved-action-dispatch")
      proxy.clearBridgeSession()
    }

    let staleGatewayRuntime = MarketplaceRuntimeToolExecutionContext(
      agentId: "local-agent",
      workspaceId: "local-workspace",
      runtimeType: .hermes,
      dispatchId: "approval-request-dispatch"
    )
    try expect(
      proxy.hasTool(
        localDispatchId: "approval-request-dispatch",
        toolName: "jotform_create_form",
        runtime: staleGatewayRuntime
      ),
      "approved action should find the single current Jotform context despite Hermes retaining the prior dispatch id"
    )
    let result = try proxy.execute(
      localDispatchId: "approval-request-dispatch",
      toolName: "jotform_create_form",
      payload: [
        "title": .string("Relay Console Integration Test"),
        "approvalId": .string("3a134619-206e-413e-a18d-fb12e50ee95a"),
      ],
      runtime: staleGatewayRuntime
    )

    try expect(
      result["ok"] == .bool(true),
      "approved Jotform action should execute through the current Railway context"
    )
    let request = try unwrap(
      transport.lastRequest,
      "approved Jotform action did not issue a Railway request"
    )
    try expect(
      request.body?["localDispatchId"] as? String == "approved-action-dispatch",
      "approved Jotform action should correlate execution to the current dispatch, not the stale Hermes environment"
    )
    let arguments = request.body?["arguments"] as? [String: Any]
    try expect(
      arguments?["approvalId"] as? String == "3a134619-206e-413e-a18d-fb12e50ee95a",
      "approved Jotform action should preserve the Relay approval id"
    )
  }

  private static func testMarketplaceRequestsUseAuthenticatedSavedDeployment() throws {
    for method in ["GET", "POST", "DELETE"] {
      try expect(
        CloudRelaySyncService.isSupportedRailwayMarketplaceMethod(method),
        "Marketplace transport rejected the supported \(method) request method"
      )
    }
    try expect(
      !CloudRelaySyncService.isSupportedRailwayMarketplaceMethod("PATCH"),
      "Marketplace transport accepted an unsupported request method"
    )
    let resolved = try CloudRelaySyncService.authenticatedMarketplaceAPIURL(
      savedOrigin: "  \(RelayCloudLaunchContract.apiOrigin)/  "
    )
    try expect(
      resolved.absoluteString == RelayCloudLaunchContract.apiOrigin,
      "Marketplace transport should use the authenticated saved production API origin")

    for unsafeOrigin in [
      "http://api.relayconsole.work/api/v1",
      "https://api.relayconsole.work.evil.example/api/v1",
      "https://api.relayconsole.work/api/v1/extra",
      "https://user@api.relayconsole.work/api/v1",
    ] {
      do {
        _ = try CloudRelaySyncService.authenticatedMarketplaceAPIURL(
          savedOrigin: unsafeOrigin)
        throw ServiceTestFailure(
          "Marketplace transport accepted an unapproved saved origin: \(unsafeOrigin)")
      } catch let error as RelayError {
        try expect(
          error.code == .permissionDenied,
          "unapproved Marketplace origins should fail with permission denied")
      }
    }
  }

