  private static func testRelayCloudAccountExportIsAuthenticatedUnwrappedAndOwnerOnly() throws {
    let root = FileManager.default.temporaryDirectory.appendingPathComponent(
      "relay-cloud-account-export-\(UUID().uuidString)",
      isDirectory: true)
    try FileManager.default.createDirectory(at: root, withIntermediateDirectories: true)
    defer { try? FileManager.default.removeItem(at: root) }
    let destination = root.appendingPathComponent("account-export.json")
    let service = RelayCloudAccountExportService(
      transport: AccountExportRelayCloudTransport())
    let now = Date(timeIntervalSince1970: 1_784_118_896)

    let artifact = try awaitResult {
      try await service.export(
        accessToken: "current-cloud-access-token",
        to: destination,
        now: now)
    }
    try expect(
      artifact.suggestedFileName == "relay-console-cloud-account-export-2026-07-15-123456.json",
      "Relay Cloud export filename is not deterministic or UTC-based")
    let payload = try unwrap(
      JSONSerialization.jsonObject(with: artifact.data) as? [String: Any],
      "Relay Cloud export is not a JSON object")
    try expect(
      payload["schemaVersion"] as? String == "relay.account-export.v1",
      "Relay Cloud export lost the unwrapped server document")
    try expect(payload["data"] == nil, "Relay Cloud export retained a transport envelope")
    let rendered = try unwrap(
      String(data: artifact.data, encoding: .utf8),
      "Relay Cloud export is not UTF-8")
    try expect(rendered.contains("\n"), "Relay Cloud export is not human-readable JSON")
    try expect(!rendered.contains("current-cloud-access-token"), "access token leaked into export")
    try expect(!rendered.contains("refreshToken"), "refresh-token material leaked into export")
    let attributes = try FileManager.default.attributesOfItem(atPath: destination.path)
    let mode = (attributes[.posixPermissions] as? NSNumber)?.intValue
    try expect(mode == 0o600, "Relay Cloud account export was not written with mode 0600")

    do {
      _ = try awaitResult {
        try await service.prepare(accessToken: "   ", now: now)
      }
      throw ServiceTestFailure("Relay Cloud export accepted an empty access token")
    } catch let error as RelayError {
      try expect(error.code == .permissionDenied, "empty-token export used the wrong error")
    }
  }

  private static func testRelayCloudAccountDeletionRequiresPasswordConfirmationAndAuthentication()
    throws
  {
    let service = RelayCloudAccountDeletionService(
      transport: AccountDeletionRelayCloudTransport())
    try awaitResult {
      try await service.delete(
        accessToken: "current-cloud-access-token",
        currentPassword: "correct horse battery staple",
        confirmation: "DELETE")
    }

    for invalid in [
      (token: "", password: "correct horse battery staple", confirmation: "DELETE"),
      (token: "current-cloud-access-token", password: "", confirmation: "DELETE"),
      (token: "current-cloud-access-token", password: "correct horse battery staple", confirmation: "delete"),
    ] {
      do {
        try awaitResult {
          try await service.delete(
            accessToken: invalid.token,
            currentPassword: invalid.password,
            confirmation: invalid.confirmation)
        }
        throw ServiceTestFailure("Relay Cloud account deletion accepted invalid confirmation input")
      } catch let error as RelayError {
        try expect(
          [.permissionDenied, .invalidInput].contains(error.code),
          "invalid account-deletion input used the wrong error")
      }
    }
  }

  private static func testRelayCloudSessionSecurityUsesCanonicalAuthenticatedRoutes() throws {
    let service = RelayCloudSessionSecurityService(
      transport: SessionSecurityRelayCloudTransport())

    try awaitResult {
      try await service.logout(accessToken: "current-cloud-access-token")
      try await service.changePassword(
        currentPassword: "current-password",
        newPassword: "new-password",
        accessToken: "current-cloud-access-token")
      try await service.revokeNativeSession(
        id: "native-session_1",
        accessToken: "current-cloud-access-token")
      try await service.revokeBrowserSession(
        id: "browser-session_1",
        accessToken: "current-cloud-access-token")
    }

    do {
      try awaitResult {
        try await service.logout(accessToken: "   ")
      }
      throw ServiceTestFailure("Relay Cloud logout accepted an empty access token")
    } catch let error as RelayError {
      try expect(error.code == .permissionDenied, "empty-token logout used the wrong error")
    }

    do {
      try awaitResult {
        try await service.changePassword(
          currentPassword: "current-password",
          newPassword: "short",
          accessToken: "current-cloud-access-token")
      }
      throw ServiceTestFailure("Relay Cloud password change accepted a short new password")
    } catch let error as RelayError {
      try expect(error.code == .invalidInput, "short password used the wrong error")
    }

    for invalidID in ["../other-user", "session/other", String(repeating: "a", count: 129)] {
      do {
        try awaitResult {
          try await service.revokeNativeSession(
            id: invalidID,
            accessToken: "current-cloud-access-token")
        }
        throw ServiceTestFailure("Relay Cloud session revocation accepted an invalid identifier")
      } catch let error as RelayError {
        try expect(error.code == .invalidInput, "invalid session identifier used the wrong error")
      }
    }
  }

