    _ = try services.providerActionPolicies.compilePolicyMap(
      context: owner, appIdOrSlug: app.id, preset: .approvalRequired,
      connectionId: connection.id, installId: install.id, agentId: agent.id)

    let checkpoint = try services.cloudSync.createBackupCheckpoint(workspaceId: workspace.id)
    defer { try? FileManager.default.removeItem(at: checkpoint.url) }
    let lines = try String(contentsOf: checkpoint.url, encoding: .utf8)
      .split(separator: "\n")
    let records = try lines.compactMap { line -> [String: Any]? in
      let object = try JSONSerialization.jsonObject(with: Data(line.utf8)) as? [String: Any]
      return object?["recordType"] as? String == "workspace_record" ? object : nil
    }
    let marketplaceRecords = records.filter {
      ["application_connection", "application_install", "application_policy"]
        .contains($0["objectType"] as? String ?? "")
    }
    try expect(
      Set(marketplaceRecords.compactMap { $0["objectType"] as? String })
        == ["application_connection", "application_install", "application_policy"],
      "cloud export must include connection, install, and policy visibility records")

    for record in marketplaceRecords {
      let payload = try unwrap(
        record["payload"] as? [String: Any], "missing Marketplace export payload")
      try expect(
        payload["executionAuthority"] as? String == "swift"
          && payload["executionAuthorityVersion"] as? String
            == MarketplaceExecutionAuthority.contractVersion
          && payload["executionAvailability"] as? String == "device_runtime_required"
          && payload["secretMaterialSynchronized"] as? Bool == false,
        "each Marketplace visibility record must carry the exact device authority and no-secret marker")
      let serialized = String(
        data: try JSONSerialization.data(withJSONObject: payload, options: [.sortedKeys]),
        encoding: .utf8)?.lowercased() ?? ""
      for forbidden in [
        secretValue.lowercased(), secret.id.lowercased(), "secretreference",
        "credentialrequirements", "keychain", "password", "accesstoken",
        "refreshtoken",
      ] {
        try expect(
          !serialized.contains(forbidden),
          "Marketplace cloud export leaked forbidden secret material or field: \(forbidden)")
      }
    }
  }

