  private static func testAllowedMutationPublishesEvent() throws {
    let services = try makeServices()
    let workspace = try unwrap(services.data.getAppState().activeWorkspace, "missing workspace")
    let counter = EventCounter()
    let subscription = services.eventBus.on(.threadUpdated) { _ in
      counter.increment()
    }
    defer {
      services.eventBus.off(.threadUpdated, id: subscription)
    }

    let denied = try guardedCreateThread(
      services: services, workspaceId: workspace.id,
      context: context(roles: [.viewer], workspaceId: workspace.id))
    try expect(
      denied?.reasonCode == .authorityRoleRequired, "viewer thread create should be denied")
    try expect(counter.value == 0, "denied thread create emitted an event")

    let allowed = try guardedCreateThread(
      services: services, workspaceId: workspace.id,
      context: context(roles: [.owner], workspaceId: workspace.id))
    try expect(allowed == nil, "owner thread create should be allowed")
    try expect(counter.value == 1, "allowed thread create did not publish an event")
    try expect(
      try services.data.listThreads(workspaceId: workspace.id).count == 1,
      "allowed thread create did not persist")
  }

  private static func testDeniedActionWritesRedactedAuditDetail() throws {
    let services = try makeServices()
    let workspace = try unwrap(services.data.getAppState().activeWorkspace, "missing workspace")
    let sensitive = "service-sensitive-value-001"

    let denied = try unwrap(
      ServiceGuard.requireAnyRole(
        [.owner], context: context(roles: [.viewer], workspaceId: workspace.id)),
      "viewer high-risk action should be denied"
    )
    _ = try writeDeniedAudit(services: services, result: denied, rawDetail: "token=\(sensitive)")

    let event = try unwrap(
      services.data.queryEventLog().first { $0.correlationId == denied.correlationId },
      "missing denied audit event"
    )
    try expect(event.message.contains("[REDACTED]"), "audit message was not redacted")
    try expect(
      (event.detail["rawDetail"]?.string ?? "").contains("[REDACTED]"),
      "audit detail was not redacted")
    try expect(!event.message.contains(sensitive), "audit message leaked sensitive value")
    try expect(
      !(event.detail["rawDetail"]?.string ?? "").contains(sensitive),
      "audit detail leaked sensitive value")
  }

