  private static func testChatHistoryStableCursorPagination() throws {
    let services = try makeServices()
    let workspace = try unwrap(services.data.getAppState().activeWorkspace, "missing workspace")
    let thread = try services.data.createThread(
      workspaceId: workspace.id, title: "Cursor Pagination Thread")
    for index in 0..<123 {
      _ = try services.data.createMessage(
        threadId: thread.id,
        senderType: index.isMultiple(of: 2) ? .user : .agent,
        senderName: index.isMultiple(of: 2) ? "You" : "Agent",
        content: "Cursor message \(index)"
      )
    }
    let all = try services.data.listMessagesInThreadOrder(
      threadId: thread.id, sessionId: thread.activeSessionId)
    let latest = try services.data.listMessagePage(
      threadId: thread.id, sessionId: thread.activeSessionId, limit: 50)
    try expect(latest.messages == Array(all.suffix(50)), "initial history page must contain the newest 50 messages")
    try expect(latest.hasOlder && !latest.hasNewer, "initial history page should advertise older history only")

    let older = try services.data.listMessagePage(
      threadId: thread.id,
      sessionId: thread.activeSessionId,
      limit: 50,
      before: latest.messages.first.map { MessageCursor(message: $0) }
    )
    try expect(older.messages == Array(all.dropLast(50).suffix(50)), "older cursor page skipped or reordered messages")
    try expect(Set(older.messages.map(\.id)).isDisjoint(with: Set(latest.messages.map(\.id))), "adjacent history pages overlap")

    let newer = try services.data.listMessagePage(
      threadId: thread.id,
      sessionId: thread.activeSessionId,
      limit: 50,
      after: older.messages.last.map { MessageCursor(message: $0) }
    )
    try expect(newer.messages == latest.messages, "newer cursor did not return to the latest page")
    try expect(
      try services.data.countMessages(
        threadId: thread.id,
        sessionId: thread.activeSessionId,
        after: older.messages.last.map { MessageCursor(message: $0) }) == 50,
      "newer-message count must use the same stable cursor ordering"
    )
  }

  private static func testChatReadStateAndArchiveGuardsAreDurable() throws {
    let services = try makeServices()
    let workspace = try unwrap(services.data.getAppState().activeWorkspace, "missing workspace")
    let thread = try services.data.createThread(
      workspaceId: workspace.id, title: "Archive Guard Thread")

    _ = try services.data.createMessage(
      threadId: thread.id,
      senderType: .user,
      senderName: "You",
      content: "Read state starts as read"
    )
    let systemMessage = try services.data.createMessage(
      threadId: thread.id,
      senderType: .system,
      senderName: "Relay Console",
      content: "Service notification for unread state.",
      metadata: ["fixture": .string("chat-read-state")]
    )
    var reloaded = try services.data.getThread(thread.id)
    try expect(reloaded.readState == .unread, "system message should mark thread unread")
    try expect(reloaded.unreadCount == 1, "system message should increment unread count")

    let readState = try services.data.markThreadRead(
      threadId: thread.id, lastReadMessageId: systemMessage.id)
    try expect(readState.unreadCount == 0, "mark read should clear durable read-state row")
    reloaded = try services.data.getThread(thread.id)
    try expect(reloaded.readState == .read, "mark read should update thread read state")
    try expect(reloaded.unreadCount == 0, "mark read should clear thread unread count")

    let archived = try services.data.archiveThread(threadId: thread.id)
    try expect(archived.isArchived, "archive should persist archive state")
    try expect(archived.activeSessionId == nil, "archive should clear active session")
    try expect(archived.sessions.first?.status == .archived, "archive should close active session")
    try expect(archived.sessions.first?.isReadOnly == true, "archived session should be read-only")
    let sessionCountBefore = archived.sessions.count
    do {
      _ = try services.data.createChatSession(threadId: thread.id)
      throw ServiceTestFailure("archived session create unexpectedly succeeded")
    } catch let denied as ServiceGuardResult {
      try expect(
        denied.stateKind == .readOnly, "archived session create should return read-only state")
      try expect(
        denied.reasonCode == .authorityReadOnly,
        "archived session create should return authority read-only reason")
    }
    try expect(
      try services.data.getThread(thread.id).sessions.count == sessionCountBefore,
      "denied session create mutated sessions")
    let messageCountBefore = try services.data.listMessages(threadId: thread.id).count
    do {
      _ = try services.data.createMessage(
        threadId: thread.id,
        senderType: .user,
        senderName: "You",
        content: "This write must be denied"
      )
      throw ServiceTestFailure("archived write unexpectedly succeeded")
    } catch let denied as ServiceGuardResult {
      try expect(denied.stateKind == .readOnly, "archived write should return read-only state")
      try expect(
        denied.reasonCode == .authorityReadOnly,
        "archived write should return authority read-only reason")
    }
    try expect(
      try services.data.listMessages(threadId: thread.id).count == messageCountBefore,
      "denied archived write mutated messages")
  }

  private static func testChatServicePublishesLocalEventsForSubscribers() throws {
    let services = try makeServices()
    let workspace = try unwrap(services.data.getAppState().activeWorkspace, "missing workspace")
    let profile = try unwrap(services.data.getAppState().activeProfile, "missing profile")
    let agent = try createServiceAgent(services: services, workspaceId: workspace.id)
    let context = context(
      roles: [.owner], workspaceId: workspace.id, correlationId: "corr-chat-events-001")
    let collector = ChatEventCollector()
    let subscriptions = [
      services.eventBus.on(.chatThreadUpdate) { collector.capture($0) },
      services.eventBus.on(.chatMessageNew) { collector.capture($0) },
      services.eventBus.on(.chatReadStateUpdate) { collector.capture($0) },
      services.eventBus.on(.chatWrapUpUpdate) { collector.capture($0) },
      services.eventBus.on(.chatThreadArchived) { collector.capture($0) },
    ]
    defer {
      for (event, id) in zip(
        [
          RelayEventName.chatThreadUpdate, .chatMessageNew, .chatReadStateUpdate, .chatWrapUpUpdate,
          .chatThreadArchived,
        ],
        subscriptions
      ) {
        services.eventBus.off(event, id: id)
      }
    }

    let thread = try services.chat.createOrReuseDirectThread(
      context: context,
      selectedAgentId: agent.id,
      title: "Event Boundary Thread"
    )
    let message = try services.chat.createMessage(
      context: context,
      threadId: thread.id,
      senderType: .user,
      senderId: profile.id,
      senderName: "You",
      content: "Service boundary message"
    )
    let runtimeSession = try services.data.createRuntimeSession(
      threadId: thread.id,
      agentId: agent.id,
      runtimeBindingId: agent.binding.id
    )
    _ = try services.data.updateRuntimeSessionExternalSessionId(
      runtimeSession.id,
      externalSessionId: "hermes-polluted-session",
      metadata: ["fixture": .string("wrap-up-runtime-reset")]
    )
    let readState = try services.chat.markThreadRead(
      context: context,
      threadId: thread.id,
      profileId: profile.id,
      lastReadMessageId: message.id
    )
    let report = try services.chat.requestWrapUpReport(context: context, threadId: thread.id)
    let resetThread = try services.chat.getThread(thread.id, context: context)
    try expect(
      resetThread.activeSessionId != message.threadSessionId,
      "wrap-up reset should open a new active chat session")
    let wrappedSession = try unwrap(
      resetThread.sessions.first { $0.id == message.threadSessionId },
      "source session should still exist after wrap-up reset"
    )
    try expect(
      wrappedSession.status == .wrapped && wrappedSession.isReadOnly,
      "source session should become a read-only wrapped cycle")
    let activeSession = try unwrap(
      resetThread.sessions.first { $0.id == resetThread.activeSessionId },
      "reset thread should expose the new active session"
    )
    try expect(
      activeSession.status == .active && !activeSession.isReadOnly,
      "reset session should be writable and active")
    try expect(
      try services.data.listMessages(threadId: thread.id, sessionId: activeSession.id).isEmpty,
      "new active cycle should start empty")
    let wrappedRuntimeSession = try services.data.getRuntimeSession(runtimeSession.id)
    try expect(
      wrappedRuntimeSession.status == "wrapped",
      "wrap-up reset should close active runtime sessions")
    try expect(
      wrappedRuntimeSession.externalSessionId == "hermes-polluted-session",
      "wrapped runtime session should preserve old Hermes session reference for history")
    let freshRuntimeSession = try services.data.createRuntimeSession(
      threadId: thread.id,
      agentId: agent.id,
      runtimeBindingId: agent.binding.id
    )
    try expect(
      freshRuntimeSession.id != runtimeSession.id,
      "new chat cycle should allocate a fresh runtime session")
    try expect(freshRuntimeSession.status == "active", "fresh runtime session should be active")
    try expect(
      freshRuntimeSession.externalSessionId == nil,
      "fresh runtime session should not reuse old Hermes session id")
    let archived = try services.chat.archiveThread(context: context, threadId: thread.id)

    try expect(archived.isArchived, "chat service archive should persist")
    try expect(
      collector.payloads(for: .chatThreadUpdate).count >= 4,
      "thread update events were not published")
    let messagePayload = try unwrap(
      collector.payloads(for: .chatMessageNew).first, "missing message.new payload")
    try expect(
      messagePayload.eventName == RelayEventName.chatMessageNew.rawValue,
      "message event name should preserve web meaning")
    try expect(messagePayload.threadId == thread.id, "message event should include thread id")
    try expect(
      messagePayload.messageId == message.id, "message event should include source message id")
    try expect(
      messagePayload.sessionId == message.threadSessionId, "message event should include session id"
    )
    try expect(
      messagePayload.sourceRecordIds["messageId"] == .string(message.id),
      "message event source ids should include message")
    let readPayload = try unwrap(
      collector.payloads(for: .chatReadStateUpdate).first, "missing read-state event")
    try expect(
      readPayload.readStateId == readState.id, "read-state event should include read state id")
    let wrapPayload = try unwrap(
      collector.payloads(for: .chatWrapUpUpdate).first, "missing wrap-up event")
    try expect(wrapPayload.wrapUpReportId == report.id, "wrap-up event should include report id")
    let archivePayload = try unwrap(
      collector.payloads(for: .chatThreadArchived).first, "missing archive event")
    try expect(archivePayload.threadId == thread.id, "archive event should include thread id")
  }

  private static func testChatServiceCreatesTeamThreadsWithSelectedParticipants() throws {
    let services = try makeServices()
    let workspace = try unwrap(services.data.getAppState().activeWorkspace, "missing workspace")
    let owner = context(
      roles: [.owner], workspaceId: workspace.id, correlationId: "corr-team-chat-create")
    let lead = try createServiceAgent(services: services, workspaceId: workspace.id)
    let peer = try createServiceAgent(services: services, workspaceId: workspace.id)
    let outside = try createServiceAgent(services: services, workspaceId: workspace.id)
    let company = try services.data.createAgentOrgCompany(
      workspaceId: workspace.id, name: "Team Chat Company")
    let department = try services.data.createAgentOrgDepartment(
      workspaceId: workspace.id,
      companyId: company.id,
      name: "Team Chat Department",
      headAgentId: lead.id
    )
    let otherDepartment = try services.data.createAgentOrgDepartment(
      workspaceId: workspace.id,
      companyId: company.id,
      name: "Other Department"
    )
    _ = try services.data.updateAgentOrgPlacement(
      agentId: lead.id,
      groupType: .business,
      familyLabel: nil,
      companyId: company.id,
      departmentId: department.id,
      teamId: nil,
      managerAgentId: nil,
      classification: "lead"
    )
    _ = try services.data.updateAgentOrgPlacement(
      agentId: peer.id,
      groupType: .business,
      familyLabel: nil,
      companyId: company.id,
      departmentId: department.id,
      teamId: nil,
      managerAgentId: nil,
      classification: "peer"
    )
    _ = try services.data.updateAgentOrgPlacement(
      agentId: outside.id,
      groupType: .business,
      familyLabel: nil,
      companyId: company.id,
      departmentId: otherDepartment.id,
      teamId: nil,
      managerAgentId: nil,
      classification: "outside"
    )

    let thread = try services.chat.createTeamThread(
      context: owner,
      departmentId: department.id,
      title: "  Launch Team  ",
      selectedAgentIds: [lead.id, peer.id, outside.id, lead.id]
    )
    try expect(thread.threadType == .team, "team chat should persist team thread type")
    try expect(thread.title == "Launch Team", "team chat title should be trimmed")
    try expect(
      thread.selectedAgentId == lead.id,
      "team chat should use first selected agent as dispatch agent")
    try expect(
      Set(thread.participants.compactMap(\.participantId)) == Set([lead.id, peer.id, outside.id]),
      "team chat should persist selected participants once")
    let leadParticipant = try unwrap(
      thread.participants.first { $0.participantId == lead.id }, "missing lead participant")
    try expect(
      leadParticipant.role == .manager && leadParticipant.isManager,
      "department head should be marked manager in team participants")

    let departmentlessThread = try services.chat.createTeamThread(
      context: owner,
      departmentId: nil,
      title: "Independent Team Chat",
      selectedAgentIds: [peer.id, outside.id]
    )
    try expect(
      departmentlessThread.threadType == .team,
      "team chats without departments should retain the team thread type")
    try expect(
      Set(departmentlessThread.participants.compactMap(\.participantId)) == Set([peer.id, outside.id]),
      "team chats without departments should persist their selected participants")
    try expect(
      departmentlessThread.participants.allSatisfy { !$0.isManager },
      "departmentless team chat participants should not gain an implicit manager role")

    let beforeDeniedCount = try services.data.listThreads(workspaceId: workspace.id).count
    do {
      _ = try services.chat.createTeamThread(
        context: owner,
        departmentId: department.id,
        title: "Empty Team",
        selectedAgentIds: []
      )
      throw ServiceTestFailure("empty team chat unexpectedly succeeded")
    } catch let denied as ServiceGuardResult {
      try expect(denied.reasonCode == .inputInvalid, "empty team chat should be invalid input")
    }
    try expect(
      try services.data.listThreads(workspaceId: workspace.id).count == beforeDeniedCount,
      "denied team chat mutated threads")
  }

