      context: context, threadId: thread.id, profileId: profile.id)
    try expect(
      try services.chat.getComposerDraft(
        context: context, threadId: thread.id, profileId: profile.id) == nil,
      "clear draft should delete scoped row"
    )

    let directMention = try services.chat.mentionAvailability(context: context, threadId: thread.id)
    try expect(!directMention.isAvailable, "direct thread mentions should stay unavailable")
    try expect(
      directMention.reasonCode == .featureUnavailable,
      "direct thread mention reason should be feature unavailable")

    let emptyTeamThread = try services.data.createThread(
      workspaceId: workspace.id,
      title: "Empty Team Mention Thread",
      selectedAgentId: nil,
      threadType: .team
    )
    let emptyTeamMention = try services.chat.mentionAvailability(
      context: context, threadId: emptyTeamThread.id)
    try expect(
      !emptyTeamMention.isAvailable, "empty team mention suggestions should require participants")
    try expect(
      emptyTeamMention.reasonCode == .dependencyMissing,
      "empty team mention reason should cite missing participants")

    let company = try services.data.createAgentOrgCompany(
      workspaceId: workspace.id, name: "Mention Company")
    let department = try services.data.createAgentOrgDepartment(
      workspaceId: workspace.id,
      companyId: company.id,
      name: "Mention Department",
      headAgentId: agent.id
    )
    let teamThread = try services.chat.createTeamThread(
      context: context,
      departmentId: department.id,
      title: "Team Mention Thread",
      selectedAgentIds: [agent.id]
    )
    let teamMention = try services.chat.mentionAvailability(
      context: context, threadId: teamThread.id)
    try expect(
      teamMention.isAvailable,
      "team mention suggestions should be available when active participants exist")
    try expect(
      teamMention.reasonCode == nil,
      "available team mentions should not carry an unavailable reason")
  }

  private static func testDispatchLocalFailureMarksSourceMessageWithoutFakeOutput() throws {
    let services = try makeServices()
    services.registry.register(UnhealthyRuntimeBridge())
    let workspace = try unwrap(services.data.getAppState().activeWorkspace, "missing workspace")
    let agent = try createServiceAgent(services: services, workspaceId: workspace.id)
    let thread = try services.data.createThread(
      workspaceId: workspace.id,
      title: "Local Failure Thread",
      selectedAgentId: agent.id,
      threadType: .direct
    )
    let beforeMessages = try services.data.listMessages(threadId: thread.id).count
    let sendError = waitForAsync {
      _ = try await services.dispatch.sendMessage(
        threadId: thread.id,
        agentId: agent.id,
        content: "Retained failed send"
      )
    }

    guard case .failure(let error) = sendError else {
      throw ServiceTestFailure("unhealthy bridge send unexpectedly succeeded")
    }
    try expect(relayError(error).code == .harnessUnhealthy, "send should report harness unhealthy")
    let messages = try services.data.listMessages(threadId: thread.id)
    try expect(
      messages.count == beforeMessages + 1, "failed local send should persist one user message")
    let failed = try unwrap(messages.last, "missing failed local-send message")
    try expect(failed.senderType == .user, "failed local send should be a user message")
    try expect(
      failed.metadata["localSendState"] == .string(LocalSendState.failed.rawValue),
      "failed message should carry local send failure state")
    try expect(
      failed.metadata["retrySourceMessageId"] == .string(failed.id),
      "failed message should be retry keyed to source message")
    try expect(
      failed.metadata["localErrorCode"] == .string(RelayErrorCode.harnessUnhealthy.rawValue),
      "failed message should preserve redacted error code")
    try expect(
      try services.data.listDispatchesForThread(thread.id).isEmpty,
      "unhealthy pre-routing failure should not create dispatch rows")
    try expect(
      !messages.contains { $0.senderType == .agent },
      "failed local send must not fabricate an agent reply")
    let record = try services.harnessInstall.getRecord(.hermes)
    try expect(record.lifecycleState == .error, "live unhealthy send should update stored harness readiness")
    try expect(
      record.lastError == "Harness unavailable for local-send failure test.",
      "live unhealthy send should retain the health diagnostic")
  }

  private static func testDispatchLiveAuthFailureUpdatesHarnessReadiness() throws {
    let services = try makeServices()
    services.registry.register(
      UnhealthyRuntimeBridge(
        status: .authRequired,
        message: "Hermes Agent authentication is unavailable: refresh_token_reused."
      )
    )
    let workspace = try unwrap(services.data.getAppState().activeWorkspace, "missing workspace")
    let agent = try createServiceAgent(services: services, workspaceId: workspace.id)
    let thread = try services.data.createThread(
      workspaceId: workspace.id,
      title: "Live Auth Failure Thread",
      selectedAgentId: agent.id,
      threadType: .direct
    )
    let sendError = waitForAsync {
      _ = try await services.dispatch.sendMessage(
        threadId: thread.id,
        agentId: agent.id,
        content: "Auth failure should be actionable"
      )
    }

    guard case .failure(let error) = sendError else {
      throw ServiceTestFailure("auth-required bridge send unexpectedly succeeded")
    }
    let relay = relayError(error)
    try expect(relay.code == .harnessUnhealthy, "auth failure should retain the harness error code")
    try expect(
      relay.message.contains("authentication is required")
        && relay.message.contains("refresh_token_reused"),
      "auth failure should retain an actionable runtime diagnostic")
    let record = try services.harnessInstall.getRecord(.hermes)
    try expect(record.lifecycleState == .authRequired, "live auth failure should mark the harness auth-required")
    try expect(record.modelAuthStatus == .notConfigured, "live auth failure should clear connected auth state")
    try expect(
      record.lastError?.contains("refresh_token_reused") == true,
      "stored harness state should retain the auth diagnostic")
  }

  private static func testRuntimeDispatchTerminalMessagesRetainDocumentReferences() throws {
    let services = try makeServices()
    let references: JSONValue = .array([
      .object([
        "id": .string("ref-soul"),
        "title": .string("SOUL.md"),
        "referenceKind": .string("document"),
        "displayPath": .string("profiles/cool-dude/SOUL.md"),
        "tokenCount": .number(420),
        "isSensitive": .bool(false),
        "isRedacted": .bool(false),
      ]),
      .object([
        "id": .string("ref-skill"),
        "title": .string("SKILL.md"),
        "referenceKind": .string("skill"),
        "displayPath": .string("skills/research/exa-search/SKILL.md"),
        "tokenCount": .number(780),
        "isSensitive": .bool(false),
        "isRedacted": .bool(false),
      ]),
    ])
    services.registry.register(
      ScriptedRuntimeBridge(
        runtimeType: .hermes,
        supportsCancellation: true,
        results: [
          RuntimeDispatchTerminalResult(
            status: "completed",
            finalText: "I read the relevant documents.",
            contentFormat: .markdown,
            metadata: [
              "harness": .string("hermes"),
              "documentReferences": references,
            ]
          )
        ]
      ))
    let workspace = try unwrap(services.data.getAppState().activeWorkspace, "missing workspace")
    let agent = try createServiceAgent(services: services, workspaceId: workspace.id)
    let thread = try services.data.createThread(
      workspaceId: workspace.id,
      title: "Runtime References Thread",
      selectedAgentId: agent.id,
      threadType: .direct
    )

    let sendResult = try awaitResult {
      try await services.dispatch.sendMessage(
        threadId: thread.id,
        agentId: agent.id,
        content: "Use your installed docs."
      )
    }
    try waitUntil("runtime reference dispatch should complete") {
      try services.data.getDispatch(sendResult.dispatch.id).status == .completed
    }
    let agentMessage = try unwrap(
      try services.data.listMessages(threadId: thread.id).first { $0.senderType == .agent },
      "missing completed agent message")
    try expect(
      agentMessage.metadata["documentReferences"] == references,
      "terminal message should retain runtime document references for the disclosure")
    try expect(
      agentMessage.metadata["dispatchId"] == .string(sendResult.dispatch.id),
      "terminal message should keep dispatch identity")
    try expect(
      agentMessage.metadata["runtimeType"] == .string(RuntimeType.hermes.rawValue),
      "terminal message should keep runtime type")
  }

  private static func testRuntimeDispatchCreatesRelayArtifactContract() throws {
    let services = try makeServices()
    let bridge = ScriptedRuntimeBridge(
      runtimeType: .hermes,
      supportsCancellation: true,
      results: [
        RuntimeDispatchTerminalResult(
          status: "completed",
          finalText: "Artifact contract output",
          contentFormat: .markdown,
          metadata: ["fixture": .string("artifact-contract")]
        )
      ]
    )
    services.registry.register(bridge)
    let workspace = try unwrap(services.data.getAppState().activeWorkspace, "missing workspace")
    let agent = try createServiceAgent(services: services, workspaceId: workspace.id)
    let thread = try services.data.createThread(
      workspaceId: workspace.id,
      title: "Artifact Contract Thread",
      selectedAgentId: agent.id,
      threadType: .direct
    )

    let sendResult = try awaitResult {
      try await services.dispatch.sendMessage(
        threadId: thread.id,
        agentId: agent.id,
        content: "Create a durable report"
      )
    }
    try waitUntil("artifact contract dispatch should complete") {
      try services.data.getDispatch(sendResult.dispatch.id).status == .completed
    }
    let request = try unwrap(
      bridge.lastRequest(), "scripted bridge did not receive a dispatch request")
    let contract = try unwrap(
      request.artifactContract, "dispatch request missing artifact contract")
    try expect(
      contract.rootPath == services.paths.artifactsDir.path,
      "artifact root should use Relay-owned artifact directory")
    try expect(
      contract.runDirectoryPath.hasPrefix(services.paths.artifactsDir.path + "/runs/"),
      "run artifact directory should live under Relay artifact runs")
    try expect(
      contract.cronDirectoryRootPath
        == services.paths.artifactsDir.appendingPathComponent("cron", isDirectory: true).path,
      "cron artifact root should be under Relay artifacts")
    try expect(
      FileManager.default.fileExists(atPath: contract.runDirectoryPath),
      "run artifact directory should be created before dispatch")
    let prompt = artifactContractPrompt("Create a durable report", contract: contract)
    try expect(
      prompt.contains(contract.runDirectoryPath), "artifact prompt should include run directory")
    try expect(
      prompt.contains(RuntimeArtifactContract.pointerManifestSuffix),
      "artifact prompt should describe external pointer manifests")
    try expect(
      prompt.contains("absolute HTTPS URL without embedded credentials"),
      "artifact prompt should state the external URL security contract")
    try expect(
      prompt.contains("If the user specifies an output location"),
      "cron artifact guidance should honor an explicit user-selected location")
    try expect(
      prompt.contains("This specifies artifact discoverability only"),
      "cron artifact guidance should separate discoverability from file retention")
    try expect(
      prompt.contains(RuntimeArtifactContract.cronOutputMarker)
        && prompt.contains("Directory: <absolute output directory>")
        && prompt.contains(RuntimeArtifactContract.cronOutputEndMarker),
      "cron artifact guidance should require the machine-readable output block")
    try expect(
      prompt.contains("macOS, web, and iOS")
        && prompt.contains("file bytes remain on that Mac"),
      "cron artifact guidance should disclose cross-platform catalogue and local-content behavior")
    try expect(
      prompt.contains("explicitly say the file will not appear in Artifacts"),
      "cron artifact guidance should require a truthful registration failure warning")
    try expect(
      !prompt.contains("stable maintained output directory"),
      "cron artifact guidance must not imply an overwrite-oriented retention strategy")

    let completed = try services.data.getDispatch(sendResult.dispatch.id)
    try expect(
      completed.inputSnapshot["artifactDirectoryPath"] == .string(contract.runDirectoryPath),
      "input snapshot should retain artifact directory")
    try expect(
      completed.resultSnapshot?["artifactDirectoryPath"] == .string(contract.runDirectoryPath),
      "result snapshot should retain artifact directory")
    let agentMessage = try unwrap(
      try services.data.listMessages(threadId: thread.id).first { $0.senderType == .agent },
      "missing completed agent message")
    try expect(
      agentMessage.metadata["artifactDirectoryPath"] == .string(contract.runDirectoryPath),
      "terminal message should retain artifact directory")
  }

  private static func testArtifactLibraryIndexesRelayOutputsAndExternalPointers() throws {
    let services = try makeServices()
    let workspace = try unwrap(services.data.getAppState().activeWorkspace, "missing workspace")
    let harness = try services.data.upsertHarness(
      runtimeType: .hermes, displayName: "Hermes Agent", mode: .appManaged, config: [:])
    let hermesHome = services.paths.hermesHomeDir.appendingPathComponent(
      "profiles/artifact-index", isDirectory: true)
    let agent = try services.data.createAgent(
      workspaceId: workspace.id,
      name: "Artifact Index Agent",
      harnessId: harness.id,
      hermesProfileSlug: "artifact-index",
      hermesHomePath: hermesHome.path
    )
    let runDir = services.paths.artifactsDir
      .appendingPathComponent("runs", isDirectory: true)
      .appendingPathComponent("2026-06-27", isDirectory: true)
      .appendingPathComponent("run-index-001", isDirectory: true)
    try FileManager.default.createDirectory(at: runDir, withIntermediateDirectories: true)
    try "# Report\n\nDurable Relay artifact.".write(
      to: runDir.appendingPathComponent("report.md"),
      atomically: true,
      encoding: .utf8
    )
    try """
    {
      "title": "Google Strategy Doc",
      "kind": "document",
      "external_url": "https://docs.google.com/document/d/example",
      "provider": "google_docs",
      "description": "External document pointer."
    }
    """.write(
      to: runDir.appendingPathComponent("google-strategy.artifact.json"),
      atomically: true,
      encoding: .utf8
    )
    try """
    {
      "title": "Unsafe External Pointer",
      "kind": "document",
      "external_url": "http://docs.example.test/private",
      "provider": "untrusted"
    }
    """.write(
      to: runDir.appendingPathComponent("unsafe.artifact.json"),
      atomically: true,
      encoding: .utf8
    )

    let cronOutput =
      hermesHome
      .appendingPathComponent("cron/output/job-001", isDirectory: true)
    try FileManager.default.createDirectory(at: cronOutput, withIntermediateDirectories: true)
    try """
    # Cron Job: Debug wrapper

    **Job ID:** job-001

    ## Prompt

    Instructions

    ## Response

    Summary
    """.write(
      to: cronOutput.appendingPathComponent("run-record.md"),
      atomically: true,
      encoding: .utf8
    )
    try "# Result\n\nThis is a real cron deliverable.".write(
      to: cronOutput.appendingPathComponent("result.md"),
      atomically: true,
      encoding: .utf8
    )
    let declaredOutput = FileManager.default.temporaryDirectory
      .appendingPathComponent("RelayConsoleDeclaredArtifacts", isDirectory: true)
      .appendingPathComponent(UUID().uuidString, isDirectory: true)
      .appendingPathComponent("competitive-research", isDirectory: true)
    try FileManager.default.createDirectory(at: declaredOutput, withIntermediateDirectories: true)
    try "# Declared report\n\nFound from jobs.json, not process cwd.".write(
      to: declaredOutput.appendingPathComponent("declared-report.md"),
      atomically: true,
      encoding: .utf8
    )
    let markedOutput = FileManager.default.temporaryDirectory
      .appendingPathComponent("RelayConsoleUserSelectedArtifacts", isDirectory: true)
      .appendingPathComponent(UUID().uuidString, isDirectory: true)
      .appendingPathComponent("user-selected", isDirectory: true)
    try FileManager.default.createDirectory(at: markedOutput, withIntermediateDirectories: true)
    try "# User-selected report".write(
      to: markedOutput.appendingPathComponent("user-selected.md"),
      atomically: true,
      encoding: .utf8
    )
    let legacyOutput = services.paths.artifactsDir
      .appendingPathComponent("cron", isDirectory: true)
      .appendingPathComponent("legacy-meaning-of-life", isDirectory: true)
    try FileManager.default.createDirectory(at: legacyOutput, withIntermediateDirectories: true)
    try "One sentence.".write(
      to: legacyOutput.appendingPathComponent("meaning-of-life.md"),
      atomically: true,
      encoding: .utf8
    )
    let jobsURL =
      hermesHome
      .appendingPathComponent("cron", isDirectory: true)
      .appendingPathComponent("jobs.json")
    try FileManager.default.createDirectory(
      at: jobsURL.deletingLastPathComponent(), withIntermediateDirectories: true)
    try """
    {
      "jobs": [
        {
          "id": "declared-output-job",
          "name": "Declared output job",
          "enabled": true,
          "schedule": { "kind": "interval", "minutes": 240 },
          "workdir": "\(services.paths.root.path)",
          "prompt": "Documentation output directory: \(declaredOutput.path)\\nMaintain this report set."
        },
        {
          "id": "marked-output-job",
          "name": "User-selected output job",
          "enabled": true,
          "schedule": { "kind": "interval", "minutes": 15 },
          "prompt": "\(RuntimeArtifactContract.cronOutputMarker)\\nDirectory: \(markedOutput.path)\\n\(RuntimeArtifactContract.cronOutputEndMarker)\\nMaintain the requested file."
        },
        {
          "id": "legacy-output-job",
          "name": "Legacy output job",
          "enabled": true,
          "schedule": { "kind": "interval", "minutes": 15 },
          "prompt": "Create or update this durable Relay Console artifact on every run: \(legacyOutput.appendingPathComponent("meaning-of-life.md").path). Keep exactly one sentence."
        },
        {
          "id": "unsafe-broad-output-job",
          "name": "Unsafe broad output job",
          "enabled": true,
          "schedule": { "kind": "interval", "minutes": 15 },
          "prompt": "\(RuntimeArtifactContract.cronOutputMarker)\\nDirectory: \(FileManager.default.homeDirectoryForCurrentUser.path)\\n\(RuntimeArtifactContract.cronOutputEndMarker)"
        }
      ]
    }
    """.write(to: jobsURL, atomically: true, encoding: .utf8)

    let repairedCount = try services.artifacts.reconcileCronArtifactDirectories(
      agents: [agent]
    )
    try expect(
      repairedCount == 3,
      "all explicit, marked, and Relay-owned legacy cron outputs should gain structured metadata")
    let repairedRoot = try JSONSerialization.jsonObject(
      with: Data(contentsOf: jobsURL)
    ) as? [String: Any]
    let repairedJobs = repairedRoot?["jobs"] as? [[String: Any]] ?? []
    let repairedOutputById = Dictionary(
      uniqueKeysWithValues: repairedJobs.compactMap { job -> (String, String)? in
        guard let id = job["id"] as? String,
              let outputDirectory = job["output_directory"] as? String
        else { return nil }
        return (id, outputDirectory)
      }
    )
    try expect(
      repairedOutputById["declared-output-job"] == declaredOutput.path
        && repairedOutputById["marked-output-job"] == markedOutput.path
        && repairedOutputById["legacy-output-job"] == legacyOutput.path
        && repairedOutputById["unsafe-broad-output-job"] == nil,
      "cron output reconciliation should preserve exact user-selected directories and reject broad roots")

    let snapshot = try services.artifacts.artifactsSnapshot(agents: [agent])
    try expect(
      snapshot.artifacts.contains { $0.title == "report.md" && $0.sourceKind == .relayManaged },
      "Relay artifact root document should be indexed")
    try expect(
      snapshot.artifacts.contains {
        $0.title == "declared-report.md" && $0.sourceKind == .cronDocument
      }, "job-declared output directory should be indexed even when it is outside the app cwd")
    try expect(
      snapshot.artifacts.contains {
        $0.title == "user-selected.md" && $0.sourceKind == .cronDocument
      }, "machine-readable user-selected output should be indexed outside Relay-owned storage")
    try expect(
      snapshot.artifacts.contains {
        $0.title == "meaning-of-life.md" && $0.sourceKind == .cronDocument
      }, "legacy Relay-owned cron output wording should remain discoverable")
    let external = try unwrap(
      snapshot.artifacts.first { $0.title == "Google Strategy Doc" },
      "external pointer artifact should be indexed")
    try expect(external.sourceKind == .external, "external pointer should use external source kind")
    try expect(
      external.externalURL == "https://docs.google.com/document/d/example",
      "external URL should be retained")
    try expect(external.externalProvider == "google_docs", "external provider should be retained")
    let unsafeExternal = try unwrap(
      snapshot.artifacts.first { $0.title == "Unsafe External Pointer" },
      "unsafe pointer should remain visible as unavailable"
    )
    try expect(unsafeExternal.externalURL == nil, "unsafe pointer URL must not be retained")
    try expect(
      unsafeExternal.effectivePresentationState == .unavailable,
      "unsafe pointer must be unavailable"
    )
    try expect(
      unsafeExternal.presentationReason == ExternalArtifactURLPolicy.blockedReason,
      "unsafe pointer must use the fixed security reason"
    )
    try expect(
      unsafeExternal.preview?.contains("http://") != true,
      "unsafe pointer URL must not reach preview text"
    )
    try expect(
      snapshot.artifacts.contains { $0.title == "result.md" && $0.sourceKind == .cronOutput },
      "real cron output deliverable should still be indexed")
    try expect(
      !snapshot.artifacts.contains { $0.title == "run-record.md" },
      "Hermes cron run record should not be shown as an artifact")

    let accountIsolatedSnapshot = try services.artifacts.artifactsSnapshot(
      agents: [agent],
      includeUnownedLocalArtifacts: false
    )
    try expect(
      !accountIsolatedSnapshot.artifacts.contains { $0.title == "report.md" },
      "an account-isolated workspace exposed a global Relay artifact"
    )
    try expect(
      accountIsolatedSnapshot.artifacts.contains {
        $0.title == "result.md" && $0.agentId == agent.id
      },
      "an account-isolated workspace hid an artifact owned by its agent"
    )
    try expect(
      accountIsolatedSnapshot.artifacts.contains {
        $0.title == "user-selected.md" && $0.agentId == agent.id
      },
      "an account-isolated workspace hid a structured user-selected cron artifact"
    )

    let originalWorkingDirectory = FileManager.default.currentDirectoryPath
    let unrelatedWorkingDirectory = FileManager.default.temporaryDirectory
      .appendingPathComponent("RelayConsoleUnrelatedWorkingDirectory", isDirectory: true)
      .appendingPathComponent(UUID().uuidString, isDirectory: true)
    try FileManager.default.createDirectory(
      at: unrelatedWorkingDirectory, withIntermediateDirectories: true)
    try expect(
      FileManager.default.changeCurrentDirectoryPath(unrelatedWorkingDirectory.path),
      "test should move to an unrelated launch working directory")
    let cwdIndependentArtifacts = ArtifactLibraryService(paths: services.paths)
    let cwdIndependentSnapshot = try cwdIndependentArtifacts.artifactsSnapshot(agents: [agent])
    _ = FileManager.default.changeCurrentDirectoryPath(originalWorkingDirectory)
    try expect(
      cwdIndependentSnapshot.artifacts.contains {
        $0.relativePath == "docs/competitive-research/index.md"
      },
      "source-build artifact discovery must not depend on the app launch working directory")
    let competitiveResearchIndex = try unwrap(
      cwdIndependentSnapshot.artifacts.first {
        $0.relativePath == "docs/competitive-research/index.md"
      },
      "competitive research index should be present")
    try expect(
      competitiveResearchIndex.agentName == "Max Radical"
        && competitiveResearchIndex.cronJobName == "Relay Console competitive research docs"
        && competitiveResearchIndex.harnessType == "hermes",
      "checked-in artifact ownership must survive missing local cron and agent records")
    // Hermes can temporarily leave jobs.json at zero bytes during an atomic
    // rewrite. Optional cron metadata must not break the app-wide refresh.
    try Data().write(to: jobsURL, options: .atomic)
    let emptyJobsArtifactSnapshot = try services.artifacts.artifactsSnapshot(agents: [agent])
    let emptyJobsCronSnapshot = try services.artifacts.cronJobsSnapshot(agents: [agent])
    try expect(
      emptyJobsArtifactSnapshot.artifacts.contains { $0.title == "report.md" },
      "an empty jobs file must not hide unrelated artifacts")
    try expect(
      !emptyJobsCronSnapshot.jobs.contains {
        $0.agentId == agent.id && $0.sourceKind == .hermesJobsFile
      },
      "an empty jobs file should behave as no Hermes scheduler jobs for that agent")
  }

  private static func testLocalArtifactsRemainVisibleWithoutRelayWorkspaceLink() throws {
    let services = try makeServices()
    let workspace = try unwrap(services.data.getAppState().activeWorkspace, "missing workspace")
    let localArtifact = AgentArtifactRecord(
      id: "artifact-local-only",
      title: "Local cron result",
      kind: .document,
      sourceKind: .cronOutput,
      path: services.paths.artifactsDir.appendingPathComponent("cron/local/result.md").path,
      relativePath: "cron/local/result.md",
      fileExtension: "md",
      updatedAt: "2026-07-28T09:13:26Z",
      content: "# Local result",
      preview: "Local result",
      isReadableText: true,
      storedLocally: true
    )

