  private static func testRuntimeDispatchRequestsUseOneHourChatTimeout() throws {
    let services = try makeServices()
    let bridge = ScriptedRuntimeBridge(
      runtimeType: .hermes,
      supportsCancellation: true,
      results: [
        failedResult("route_probe", "Recorded timeout request.", recoverable: false)
      ]
    )
    services.registry.register(bridge)
    let workspace = try unwrap(services.data.getAppState().activeWorkspace, "missing workspace")
    let agent = try createServiceAgent(services: services, workspaceId: workspace.id)
    let thread = try services.data.createThread(
      workspaceId: workspace.id,
      title: "Timeout Contract Thread",
      selectedAgentId: agent.id,
      threadType: .direct
    )

    _ = try awaitResult {
      try await services.dispatch.sendMessage(
        threadId: thread.id,
        agentId: agent.id,
        content: "Record dispatch timeout"
      )
    }
    try waitUntil("runtime bridge should record dispatch request") {
      !bridge.recordedRequests().isEmpty
    }
    try waitUntil("runtime dispatch should settle before service teardown") {
      try services.data.listDispatchesForThread(thread.id).allSatisfy { !$0.isActive }
    }
    let request = try unwrap(bridge.recordedRequests().first, "missing recorded runtime request")
    try expect(
      request.timeoutMs == RuntimeDispatchTimeouts.chatTurnMs,
      "chat dispatch timeout should be one hour")
    try expect(
      request.timeoutMs == 3_600_000,
      "chat dispatch timeout should not regress to the old short timeout")
  }

  private static func testNativeImageAttachmentsReachHermesDispatchesAndRetries() throws {
    let services = try makeServices()
    let bridge = ScriptedRuntimeBridge(
      runtimeType: .hermes,
      supportsCancellation: true,
      results: [
        failedResult("fixture_failure", "First fixture turn failed.", recoverable: true),
        failedResult("fixture_failure", "Retry fixture turn failed.", recoverable: true),
      ]
    )
    services.registry.register(bridge)
    let state = try services.data.getAppState()
    let workspace = try unwrap(state.activeWorkspace, "missing workspace")
    let profile = try unwrap(state.activeProfile, "missing profile")
    let agent = try createServiceAgent(services: services, workspaceId: workspace.id)
    let thread = try services.data.createThread(
      workspaceId: workspace.id,
      title: "Native Image Dispatch Thread",
      selectedAgentId: agent.id,
      threadType: .direct
    )
    let bytes = Data("native-image-fixture".utf8)
    let digest = SHA256.hash(data: bytes)
      .map { String(format: "%02x", $0) }
      .joined()
    var attachment = try services.chat.stageAttachment(
      context: context(roles: [.owner], workspaceId: workspace.id),
      threadId: thread.id,
      profileId: profile.id,
      fileName: "fixture.png",
      mimeType: "image/png",
      byteSize: bytes.count,
      sha256: digest,
      kind: .image,
      status: .importing,
      progress: 0,
      provenance: [
        "source": .string("native-file-picker"),
        "storage": .string("local-authorized"),
        "pathRedacted": .bool(true),
      ]
    )
    let attachmentStore = NativeChatAttachmentStore(appDataRoot: services.paths.root)
    let retainedPath = try attachmentStore.persist(data: bytes, attachment: attachment)
    attachment = try services.chat.updateAttachmentStatus(
      context: context(roles: [.owner], workspaceId: workspace.id),
      threadId: thread.id,
      attachmentId: attachment.id,
      status: .uploaded,
      progress: 100
    )

    let sent = try awaitResult {
      try await services.dispatch.sendMessage(
        threadId: thread.id,
        agentId: agent.id,
        content: "Read this image",
        metadata: [
          "attachments": .array([.object(attachment.metadataSummary)]),
          "attachmentCount": .number(1),
        ],
        approvalMode: .fullAccess
      )
    }
    _ = try services.chat.assignAttachmentsToMessage(
      context: context(roles: [.owner], workspaceId: workspace.id),
      threadId: thread.id,
      profileId: profile.id,
      messageId: sent.userMessage.id,
      attachmentIds: [attachment.id]
    )
    try waitUntil("Hermes bridge should receive the native image path") {
      bridge.recordedRequests().count == 1
    }
    try waitUntil("first image dispatch should settle") {
      try services.data.getDispatch(sent.dispatch.id).status == .failed
    }
    let firstRequest = try unwrap(bridge.recordedRequests().first, "missing first image request")
    try expect(
      firstRequest.attachmentPaths == [retainedPath],
      "native image path should be included in the Hermes request"
    )
    try expect(
      try Data(contentsOf: URL(fileURLWithPath: retainedPath)) == bytes,
      "retained native image bytes should remain readable"
    )

    let retry = try awaitResult {
      try await services.dispatch.retry(dispatchId: sent.dispatch.id)
    }
    try waitUntil("Hermes retry should receive the retained native image path") {
      bridge.recordedRequests().count == 2
    }
    try waitUntil("image retry should settle") {
      try services.data.getDispatch(retry.id).status == .failed
    }
    try expect(
      bridge.recordedRequests()[1].attachmentPaths == [retainedPath],
      "retry should preserve the retained image path"
    )
  }

  private static func testTeamUserMessagesUseSingleRelayRouting() throws {
    let services = try makeServices()
    services.registry.register(
      ScriptedRuntimeBridge(
        runtimeType: .hermes,
        supportsCancellation: true,
        results: [
          failedResult(
            "route_probe", "Hermes route probe stopped before posting output.", recoverable: false),
          failedResult(
            "route_probe", "Hermes route probe stopped before posting output.", recoverable: false),
        ]
      ))
    services.registry.register(
      ScriptedRuntimeBridge(
        runtimeType: .openclaw,
        supportsCancellation: false,
        results: [
          failedResult(
            "route_probe", "OpenClaw route probe stopped before posting output.", recoverable: false
          ),
          failedResult(
            "route_probe", "OpenClaw route probe stopped before posting output.", recoverable: false
          ),
        ]
      ))
    let workspace = try unwrap(services.data.getAppState().activeWorkspace, "missing workspace")
    let hermesHarness = try services.data.upsertHarness(
      runtimeType: .hermes, displayName: "Hermes Agent", mode: .appManaged, config: [:])
    let openClawHarness = try services.data.upsertHarness(
      runtimeType: .openclaw, displayName: "OpenClaw", mode: .appManaged, config: [:])
    let chan = try services.data.createAgent(
      workspaceId: workspace.id,
      name: "Chan Hermes",
      harnessId: hermesHarness.id,
      externalAgentId: "chan_hermes",
      hermesProfileSlug: "chan_hermes"
    )
    let designer = try services.data.createAgent(
      workspaceId: workspace.id,
      name: "Designer Claw",
      harnessId: openClawHarness.id,
      externalAgentId: "designer_claw"
    )
    let company = try services.data.createAgentOrgCompany(
      workspaceId: workspace.id, name: "Routing Company")
    let department = try services.data.createAgentOrgDepartment(
      workspaceId: workspace.id,
      companyId: company.id,
      name: "Routing Department",
      headAgentId: chan.id
    )
    let owner = context(
      roles: [.owner], workspaceId: workspace.id, correlationId: "corr-team-dispatch-mentioned")
    let thread = try services.chat.createTeamThread(
      context: owner,
      departmentId: department.id,
      title: "Routing Team",
      selectedAgentIds: [chan.id, designer.id]
    )

    let unmentionedResult = try awaitResult {
      try await services.dispatch.sendMessage(
        threadId: thread.id,
        agentId: chan.id,
        content: "Hey guys"
      )
    }
    try waitUntil("unmentioned team user message should settle") {
      let dispatches = try services.data.listDispatchesForThread(thread.id)
      return dispatches.contains {
        $0.messageId == unmentionedResult.userMessage.id && !$0.isActive
      }
    }
    let unmentionedDispatches = try services.data.listDispatchesForThread(thread.id)
      .filter { $0.messageId == unmentionedResult.userMessage.id }
    try expect(
      unmentionedDispatches.count == 1,
      "unmentioned team user message should create exactly one dispatch")
    let unmentionedTarget = try unwrap(
      unmentionedDispatches.first?.agentId, "missing unmentioned target agent")
    try expect(
      [chan.id, designer.id].contains(unmentionedTarget),
      "unmentioned team user message should choose one eligible agent")
    try expect(
      unmentionedResult.userMessage.metadata["dispatchRoutingMode"]
        == .string("team_single_random"),
      "unmentioned user source message should record random single-relay routing")
    try expect(
      unmentionedResult.userMessage.metadata["dispatchTargetAgentIds"]
        == .array([.string(unmentionedTarget)]),
      "unmentioned user source message should record one target agent")
    try expect(
      unmentionedResult.userMessage.metadata["mentionedAgentIds"] == .array([]),
      "unmentioned user source message should not record mentioned agent ids")

    let mentionedResult = try awaitResult {
      try await services.dispatch.sendMessage(
        threadId: thread.id,
        agentId: chan.id,
        content: "@designer_claw @chan_hermes please start with the first mention only"
      )
    }
    try waitUntil("mentioned team user message should settle") {
      let dispatches = try services.data.listDispatchesForThread(thread.id)
      return dispatches.contains { $0.messageId == mentionedResult.userMessage.id && !$0.isActive }
    }
    let mentionedDispatches = try services.data.listDispatchesForThread(thread.id)
      .filter { $0.messageId == mentionedResult.userMessage.id }
    try expect(
      mentionedDispatches.count == 1,
      "mentioned team user message should create exactly one dispatch")
    try expect(
      mentionedDispatches.first?.agentId == designer.id,
      "multiple mentions should route only to the first eligible mentioned agent")
    try expect(
      mentionedResult.userMessage.metadata["dispatchRoutingMode"] == .string("team_single_mention"),
      "mentioned user source message should record single mention routing")
    try expect(
      mentionedResult.userMessage.metadata["dispatchTargetAgentIds"]
        == .array([.string(designer.id)]),
      "mentioned user source message should record one mentioned target agent")
    try expect(
      mentionedResult.userMessage.metadata["mentionedAgentIds"] == .array([.string(designer.id)]),
      "mentioned user source message should record selected mentioned agent id")
    try expect(
      mentionedDispatches.first?.inputSnapshot["mentionTokens"]
        == .array([.string("designer_claw"), .string("chan_hermes")]),
      "mention tokens should preserve message order for first-mention routing")
  }

  private static func testTeamRuntimePublicationIsToolOnlyStructuredAndIdempotent() throws {
    let services = try makeServices()
    let coordinatorBridge = ScriptedRuntimeBridge(
      runtimeType: .hermes,
      supportsCancellation: true,
      results: [
        RuntimeDispatchTerminalResult(
          status: "completed",
          finalText: "This ordinary final must stay hidden.",
          contentFormat: .markdown,
          error: nil,
          metadata: ["fixture": .string("hidden-team-final")]
        )
      ],
      responseDelayMilliseconds: 300
    )
    let workerBridge = ScriptedRuntimeBridge(
      runtimeType: .openclaw,
      supportsCancellation: false,
      results: [
        failedResult("route_probe", "Structured mention routing recorded.", recoverable: false)
      ]
    )
    services.registry.register(coordinatorBridge)
    services.registry.register(workerBridge)
    let workspace = try unwrap(services.data.getAppState().activeWorkspace, "missing workspace")
    let hermesHarness = try services.data.upsertHarness(
      runtimeType: .hermes, displayName: "Hermes Agent", mode: .appManaged, config: [:])
    let openClawHarness = try services.data.upsertHarness(
      runtimeType: .openclaw, displayName: "OpenClaw", mode: .appManaged, config: [:])
    let coordinator = try services.data.createAgent(
      workspaceId: workspace.id,
      name: "Coordinator Hermes",
      harnessId: hermesHarness.id,
      externalAgentId: "coordinator_hermes",
      hermesProfileSlug: "coordinator_hermes"
    )
    let worker = try services.data.createAgent(
      workspaceId: workspace.id,
      name: "Worker Claw",
      harnessId: openClawHarness.id,
      externalAgentId: "worker_claw"
    )
    let company = try services.data.createAgentOrgCompany(
      workspaceId: workspace.id, name: "Tool Publication Company")
    let department = try services.data.createAgentOrgDepartment(
      workspaceId: workspace.id,
      companyId: company.id,
      name: "Tool Publication Department",
      headAgentId: coordinator.id
    )
    let thread = try services.chat.createTeamThread(
      context: context(roles: [.owner], workspaceId: workspace.id),
      departmentId: department.id,
      title: "Tool Publication Team",
      selectedAgentIds: [coordinator.id, worker.id]
    )

    let send = try awaitResult {
      try await services.dispatch.sendMessage(
        threadId: thread.id,
        agentId: coordinator.id,
        content: "@coordinator_hermes delegate this"
      )
    }
    try waitUntil("team coordinator request should reach the runtime") {
      coordinatorBridge.dispatchCallCount() == 1
    }
    let runtime = MarketplaceRuntimeToolExecutionContext(
      agentId: coordinator.id,
      workspaceId: workspace.id,
      runtimeType: .hermes,
      dispatchId: send.dispatch.id,
      threadId: thread.id,
      runtimeSessionId: send.dispatch.sessionId,
      actorId: "relay-runtime-tool",
      correlationId: send.dispatch.correlationId
    )
    let payload: JSONRecord = [
      "content": .string("Worker, calculate the requested value."),
      "mentions": .array([.object(["agentId": .string(worker.id)])]),
      "callId": .string("publish-delegation-1")
    ]
    let published = try services.marketplaceRuntimeToolBridge.execute(
      toolName: "relay_publish_message",
      payload: payload,
      runtime: runtime
    )
    let duplicate = try services.marketplaceRuntimeToolBridge.execute(
      toolName: "relay_publish_message",
      payload: payload,
      runtime: runtime
    )
    try expect(published["success"] == .bool(true), "team publication should succeed")
    try expect(published["duplicate"] == .bool(false), "first publication should not be duplicate")
    try expect(duplicate["duplicate"] == .bool(true), "repeated call id should deduplicate")
    try expect(
      duplicate["messageId"] == published["messageId"],
      "duplicate publication should return the original message")

    try waitUntil("structured team publication should route only to the mentioned worker") {
      try services.data.listDispatchesForThread(thread.id).contains {
        $0.messageId == published["messageId"]?.string && $0.agentId == worker.id
      }
    }
    try waitUntil("team publication dispatches should settle") {
      try services.data.listDispatchesForThread(thread.id).allSatisfy { !$0.isActive }
    }
    let messages = try services.data.listMessagesInThreadOrder(threadId: thread.id)
    let agentMessages = messages.filter { $0.senderType == .agent }
    try expect(agentMessages.count == 1, "ordinary team finals must not create visible messages")
    let visible = try unwrap(agentMessages.first, "missing published team message")
    try expect(visible.senderId == coordinator.id, "Relay should control the publishing sender")
    try expect(
      visible.content == "@worker_claw\n\nWorker, calculate the requested value.",
      "structured team mentions should also be visible in the published message")
    try expect(
      visible.metadata["mentionedAgentIds"] == .array([.string(worker.id)]),
      "published message should retain only structured mention ids")
    try expect(
      visible.metadata["runtimeToolCallId"] == .string("publish-delegation-1"),
      "published message should retain duplicate-call identity")
    let routed = try services.data.listDispatchesForThread(thread.id).filter {
      $0.messageId == visible.id
    }
    try expect(
      routed.count == 1 && routed.first?.agentId == worker.id,
      "only explicitly mentioned agents should receive another turn")

    let request = try unwrap(coordinatorBridge.lastRequest(), "missing coordinator request")
    try expect(request.isTeamChat, "team request should carry tool-only publication mode")
    try expect(
      request.cloudMarketplaceTools.contains {
        $0["functionName"] == .string("relay_publish_message")
      },
      "team request should mount relay_publish_message")
    try expect(
      request.inputContent.contains("[Relay team-chat instructions]")
        && request.inputContent.contains("Never publish a bare acknowledgement")
        && request.inputContent.contains(worker.id),
      "team request should carry the Buzz callback and no-acknowledgement rules")
    let completed = try services.data.getDispatch(send.dispatch.id)
    try expect(
      completed.resultSnapshot?["finalResponsePublication"]
        == .string("suppressed_team_tool_only"),
      "team dispatch should explicitly record ordinary-final suppression")
  }

