      headAgentId: chan.id
    )
    let owner = context(
      roles: [.owner], workspaceId: workspace.id, correlationId: "corr-team-agent-no-broadcast")
    let thread = try services.chat.createTeamThread(
      context: owner,
      departmentId: department.id,
      title: "Agent Broadcast Team",
      selectedAgentIds: [chan.id, designer.id]
