    try expect(
      designerFollowUp.inputSnapshot["dispatchRoutingMode"] == .string("team_single_random"),
      "unmentioned agent follow-up should record random single-relay routing")
    try expect(
      designerFollowUp.inputSnapshot["dispatchTargetAgentIds"] == .array([.string(designer.id)]),
      "unmentioned agent follow-up should record one target agent")
    try waitUntil("unmentioned baton follow-up should settle") {
      let dispatches = try services.data.listDispatchesForThread(thread.id)
      return dispatches.count >= 2 && dispatches.allSatisfy { !$0.isActive }
    }
  }

