    let openClawHarness = try services.data.upsertHarness(
      runtimeType: .openclaw, displayName: "OpenClaw", mode: .appManaged, config: [:])
    let chan = try services.data.createAgent(
      workspaceId: workspace.id,
      name: "Chan Hermes",
      harnessId: hermesHarness.id,
      externalAgentId: "chan_hermes",
      hermesProfileSlug: "chan_hermes"
    )
    let designer = try services.data.createAgent(
      workspaceId: workspace.id,
      name: "Designer Claw",
      harnessId: openClawHarness.id,
      externalAgentId: "designer_claw"
    )
    let company = try services.data.createAgentOrgCompany(
      workspaceId: workspace.id, name: "Catch-up Company")
    let department = try services.data.createAgentOrgDepartment(
      workspaceId: workspace.id,
      companyId: company.id,
      name: "Catch-up Department",
      headAgentId: chan.id
    )
    let owner = context(
      roles: [.owner], workspaceId: workspace.id, correlationId: "corr-team-catch-up")
    let thread = try services.chat.createTeamThread(
      context: owner,
      departmentId: department.id,
      title: "Catch-up Team",
      selectedAgentIds: [chan.id, designer.id]
    )

    let sendResult = try awaitResult {
      try await services.dispatch.sendMessage(
        threadId: thread.id,
        agentId: chan.id,
        content: "@chan_hermes First human instruction"
      )
    }
    try waitUntil("team catch-up dispatch chain should settle") {
      let dispatches = try services.data.listDispatchesForThread(thread.id)
      return dispatches.count >= 3 && dispatches.allSatisfy { !$0.isActive }
    }
    let messages = try services.data.listMessagesInThreadOrder(threadId: thread.id)
    let chanMessage = try unwrap(
      messages.first { $0.senderType == .agent && $0.senderId == chan.id },
      "missing Chan proposal message"
    )
    let designerMessage = try unwrap(
      messages.first { $0.senderType == .agent && $0.senderId == designer.id },
      "missing Designer response message"
    )
    let dispatches = try services.data.listDispatchesForThread(thread.id)
    let designerDispatch = try unwrap(
      dispatches.first { $0.messageId == chanMessage.id && $0.agentId == designer.id },
      "missing Designer catch-up dispatch"
    )
    try expect(
      designerDispatch.inputSnapshot["teamCatchUpMessageCount"] == .number(1),
      "Designer should receive exactly one catch-up message")
    try expect(
      designerDispatch.inputSnapshot["teamCatchUpMessageIds"]
        == .array([.string(sendResult.userMessage.id)]),
      "Designer catch-up should include the prior user message")
    try expect(
      designerDispatch.inputSnapshot["sourceContent"] == .string("Chan proposal for Designer."),
      "Designer dispatch should keep Chan's message as the source prompt")
    let designerRequest = try unwrap(
      openClawBridge.recordedRequests().first, "missing recorded Designer request")
    try expect(
      designerRequest.inputContent.contains(
        "[Relay Console team catch-up since your last routed turn]"),
      "Designer prompt should include the catch-up packet")
    try expect(
      designerRequest.inputContent.contains("First human instruction"),
      "Designer prompt should include unseen human context")
    try expect(
      designerRequest.inputContent.contains(
        "[Current routed message - respond to this]\nChan proposal for Designer."),
      "Designer prompt should preserve the current routed message")

    let chanReturnDispatch = try unwrap(
      dispatches.first { $0.messageId == designerMessage.id && $0.agentId == chan.id },
      "missing Chan return dispatch"
    )
    try expect(
      chanReturnDispatch.inputSnapshot["teamCatchUpMessageCount"] == .number(0),
      "Chan should not receive already-seen context again")
    let chanRequests = hermesBridge.recordedRequests()
    try expect(chanRequests.count >= 2, "Hermes should record the initial and return dispatches")
    try expect(
      !chanRequests[1].inputContent.contains("First human instruction"),
      "Chan return prompt should not resend the original user message")
    try expect(
      chanRequests[1].inputContent.contains("@chan_hermes Designer response after seeing Chan."),
      "Chan return prompt should contain Designer's current routed message")
  }

  private static func testTeamRelayManualPauseStopsBatonUntilContinue() throws {
    let services = try makeServices()
    services.registry.register(
      ScriptedRuntimeBridge(
        runtimeType: .hermes,
        supportsCancellation: true,
        results: [
          RuntimeDispatchTerminalResult(
            status: "completed",
            finalText: "Chan reply while the team relay is paused.",
            contentFormat: .markdown,
            error: nil,
            metadata: ["fixture": .string("chan-paused-reply")]
          )
        ],
        responseDelayMilliseconds: 100
      ))
    services.registry.register(
      ScriptedRuntimeBridge(
        runtimeType: .openclaw,
        supportsCancellation: false,
        results: [
          failedResult(
            "route_probe", "Designer route probe stopped after continue.", recoverable: false)
        ]
      ))
    let workspace = try unwrap(services.data.getAppState().activeWorkspace, "missing workspace")
    let hermesHarness = try services.data.upsertHarness(
      runtimeType: .hermes, displayName: "Hermes Agent", mode: .appManaged, config: [:])
    let openClawHarness = try services.data.upsertHarness(
      runtimeType: .openclaw, displayName: "OpenClaw", mode: .appManaged, config: [:])
    let chan = try services.data.createAgent(
      workspaceId: workspace.id,
      name: "Chan Hermes",
      harnessId: hermesHarness.id,
      externalAgentId: "chan_hermes",
      hermesProfileSlug: "chan_hermes"
    )
    let designer = try services.data.createAgent(
      workspaceId: workspace.id,
      name: "Designer Claw",
      harnessId: openClawHarness.id,
      externalAgentId: "designer_claw"
    )
    let company = try services.data.createAgentOrgCompany(
      workspaceId: workspace.id, name: "Relay Pause Company")
    let department = try services.data.createAgentOrgDepartment(
      workspaceId: workspace.id,
      companyId: company.id,
      name: "Relay Pause Department",
      headAgentId: chan.id
    )
    let owner = context(
      roles: [.owner], workspaceId: workspace.id, correlationId: "corr-team-relay-pause")
    let thread = try services.chat.createTeamThread(
      context: owner,
      departmentId: department.id,
      title: "Relay Pause Team",
      selectedAgentIds: [chan.id, designer.id]
    )

    let sendResult = try awaitResult {
      try await services.dispatch.sendMessage(
        threadId: thread.id,
        agentId: chan.id,
        content: "@chan_hermes start while I pause"
      )
    }
    try waitUntil("initial team dispatch should become active") {
      try services.data.listDispatchesForThread(thread.id).contains {
        $0.messageId == sendResult.userMessage.id && $0.agentId == chan.id && $0.isActive
      }
    }
    _ = try services.dispatch.pauseTeamRelay(threadId: thread.id)

    try waitUntil("paused team relay should not route the next baton") {
      let dispatches = try services.data.listDispatchesForThread(thread.id)
      let messages = try services.data.listMessagesInThreadOrder(threadId: thread.id)
      guard
        let chanMessage = messages.first(where: {
          $0.senderType == .agent && $0.senderId == chan.id
        })
      else {
        return false
      }
      return dispatches.contains {
        $0.messageId == sendResult.userMessage.id && $0.agentId == chan.id
          && $0.status == .completed
      }
        && !dispatches.contains { $0.messageId == chanMessage.id && $0.agentId == designer.id }
    }
    let pausedThread = try services.data.getThread(thread.id)
    let pausedSession = try unwrap(
      pausedThread.sessions.first { $0.id == pausedThread.activeSessionId },
      "missing paused active session")
    try expect(
      pausedSession.relayRunState == .paused, "manual pause should set the relay state to paused")
    try expect(
      pausedSession.relayPauseReason == .manual, "manual pause should retain a manual reason")

    _ = try awaitResult {
      try await services.dispatch.continueTeamRelay(threadId: thread.id)
    }
    try waitUntil("continue should resume the pending baton") {
      try services.data.listDispatchesForThread(thread.id).contains {
        $0.agentId == designer.id && $0.status == .failed
      }
    }
    let runningThread = try services.data.getThread(thread.id)
    let runningSession = try unwrap(
      runningThread.sessions.first { $0.id == runningThread.activeSessionId },
      "missing resumed active session")
    try expect(
      runningSession.relayRunState == .running, "continue should set the relay state to running")
    try expect(runningSession.relayPauseReason == nil, "continue should clear the pause reason")
  }

  private static func testTeamRelayReplyLimitPausesAndContinueBumpsLimit() throws {
    let services = try makeServices()
    services.registry.register(
      ScriptedRuntimeBridge(
        runtimeType: .hermes,
        supportsCancellation: true,
        results: [
          RuntimeDispatchTerminalResult(
            status: "completed",
            finalText: "Chan reaches the custom reply cap.",
            contentFormat: .markdown,
