  private static func testRuntimeDispatchCancelHonorsCapabilityAndTerminalState() throws {
    let services = try makeServices()
    let cancellable = WaitingRuntimeBridge(runtimeType: .hermes, supportsCancellation: true)
    services.registry.register(cancellable)
    let workspace = try unwrap(services.data.getAppState().activeWorkspace, "missing workspace")
    let agent = try createServiceAgent(services: services, workspaceId: workspace.id)
    let thread = try services.data.createThread(
      workspaceId: workspace.id,
      title: "Cancel Dispatch Thread",
      selectedAgentId: agent.id,
      threadType: .direct
    )
    let owner = context(
      roles: [.owner], workspaceId: workspace.id, correlationId: "corr-runtime-cancel-owner")

    let sendResult = waitForAsync {
      _ = try await services.dispatch.sendMessage(
        threadId: thread.id,
        agentId: agent.id,
        content: "Cancel this real bridge request"
      )
    }
    guard case .success = sendResult else {
      throw ServiceTestFailure("cancel dispatch send failed before dispatch creation")
    }
    try waitUntil("dispatch should become active") {
      try services.data.listDispatchesForThread(thread.id).first?.isActive == true
    }
    let active = try unwrap(
      try services.data.listDispatchesForThread(thread.id).first, "missing active dispatch")
    let cancelled = try awaitResult {
      try await services.dispatch.cancel(dispatchId: active.id, context: owner)
    }
    try expect(cancelled.status == .cancelled, "supported cancel should mark dispatch cancelled")
    try waitUntil("late bridge result should not overwrite cancellation") {
      try services.data.getDispatch(active.id).status == .cancelled
    }
    Thread.sleep(forTimeInterval: 0.05)
    try expect(
      try services.data.getDispatch(active.id).status == .cancelled,
      "late bridge terminal result overwrote cancelled state")
    try expect(
      try services.data.listMessages(threadId: thread.id).filter { $0.senderType == .agent }
        .isEmpty, "cancelled dispatch must not create terminal agent output")

    let openClawHarness = try services.data.upsertHarness(
      runtimeType: .openclaw,
      displayName: "OpenClaw",
      mode: .appManaged,
      config: [:]
    )
    let openClawAgent = try services.data.createAgent(
      workspaceId: workspace.id,
      name: "OpenClaw Cancel Guard",
      harnessId: openClawHarness.id
    )
    let unsupportedThread = try services.data.createThread(
      workspaceId: workspace.id,
      title: "Unsupported Cancel Thread",
      selectedAgentId: openClawAgent.id,
      threadType: .direct
    )
    let sourceMessage = try services.data.createMessage(
      threadId: unsupportedThread.id,
      senderType: .user,
      senderName: "You",
      content: "OpenClaw cancel remains guarded"
    )
    let session = try services.data.createRuntimeSession(
      threadId: unsupportedThread.id,
      agentId: openClawAgent.id,
      runtimeBindingId: openClawAgent.binding.id
    )
    let openClawDispatch = try services.data.createDispatch(
      threadId: unsupportedThread.id,
      messageId: sourceMessage.id,
      agentId: openClawAgent.id,
      harnessId: openClawHarness.id,
      sessionId: session.id,
      correlationId: "corr-openclaw-cancel-guard",
      inputSnapshot: [
        "content": .string(sourceMessage.content),
        "runtimeType": .string(RuntimeType.openclaw.rawValue),
        "attempt": .number(1),
        "retrySourceMessageId": .string(sourceMessage.id),
      ]
    )
    do {
      _ = try awaitResult {
        try await services.dispatch.cancel(dispatchId: openClawDispatch.id, context: owner)
      }
      throw ServiceTestFailure("unsupported OpenClaw cancel unexpectedly succeeded")
    } catch let denied as ServiceGuardResult {
      try expect(
        denied.reasonCode == .capabilityMissing, "unsupported cancel should cite missing capability"
      )
    }
    try expect(
      try services.data.getDispatch(openClawDispatch.id).status == .queued,
      "unsupported cancel should not mutate dispatch state")
  }

