      try await services.harnessInstall.ensureOpenClawAgentProvisioned(agent)
    }

    try expect(
      provisioned.binding.externalAgentId == "claw_man", "OpenClaw external id should stay bound")
    try expect(
      runner.openClawAddCount(for: "claw_man") == 0,
      "existing top-level OpenClaw agent should not be added again")
  }

