  private static func testOpenClawProvisioningRepairsCopiedMainAgentDatabase() throws {
    let runner = ScriptedProvisioningRunner(initialOpenClawAgents: ["claw_man"])
    let services = try makeServices(runner: runner)
    let workspace = try unwrap(services.data.getAppState().activeWorkspace, "missing workspace")
