    let mainAuth =
      #"{"version":1,"profiles":{"openai:main@example.com":{"type":"oauth","provider":"openai","email":"main@example.com"}}}"#
    let copiedAuth =
      #"{"version":1,"profiles":{"openai:copied@example.com":{"type":"oauth","provider":"openai","email":"copied@example.com"}}}"#
    try writeOpenClawAgentDatabase(
      services: services, slug: "main", owner: "main", storeJSON: mainAuth)
