  private static func testOpenClawGatewayRemainsUserManagedOnLaunchAndKeepalive() throws {
    let root = FileManager.default.temporaryDirectory
      .appendingPathComponent("RelayConsoleServiceTests", isDirectory: true)
      .appendingPathComponent(UUID().uuidString, isDirectory: true)
    do {
      let seed = try makeServices(root: root)
      _ = try prepareInstalledHarness(services: seed, key: .openclaw)
    }

    let runner = OpenClawGatewayLifecycleRunner()
    let services = try makeServices(
      root: root, runner: runner, refreshInstalledHarnessesOnLaunch: true)
    Thread.sleep(forTimeInterval: 0.2)
    try expect(runner.gatewayInstallCount() == 0, "launch must not install a user-owned gateway service")
    try expect(runner.gatewayStartCount() == 0, "launch must not start a user-owned gateway service")

    runner.setGatewayReady(false)
    try awaitResult { await services.harnessInstall.maintainOpenClawGateway() }
    try expect(runner.gatewayInstallCount() == 0, "legacy keepalive must not install the user-owned gateway")
    try expect(runner.gatewayStartCount() == 0, "legacy keepalive must not start the user-owned gateway")
    try expect(runner.gatewayRestartCount() == 0, "legacy keepalive must not restart the user-owned gateway")
  }

  private static func testOpenClawHealthReportsStoppedUserManagedGateway() throws {
    let runner = OpenClawGatewayLifecycleRunner(readinessDelayChecks: 1)
    let services = try makeServices(runner: runner)
    let harness = try prepareInstalledHarness(services: services, key: .openclaw)

    let health = try awaitResult {
      await services.harnessInstall.getHealthFromHarnessConfig(
        harnessId: harness.id,
        config: harness.config
      )
    }

    try expect(health.status == .degraded, "health should report the stopped gateway")
    try expect(runner.gatewayStartCount() == 0, "health must not start the user-owned gateway")
    try expect(runner.gatewayStatusCount() == 1, "health should perform one read-only status probe")
  }

  private static func testOpenClawExpiredChatGPTAuthStaysAuthRequired() throws {
    let runner = ExpiredOpenClawAuthRunner()
