  private static func testHermesSchedulerIsolatesServiceTestLaunchAgents() throws {
    let root = FileManager.default.temporaryDirectory
      .appendingPathComponent("RelayConsoleServiceTests", isDirectory: true)
      .appendingPathComponent(UUID().uuidString, isDirectory: true)
    let paths = try AppPathsService(basePath: root).ensure()
    let harnessPath = paths.harnessesDir.appendingPathComponent("hermes-agent", isDirectory: true)
    let python = harnessPath.appendingPathComponent("venv/bin/python")
    let hermesHome = paths.hermesHomeDir.appendingPathComponent(
      "profiles/test-agent", isDirectory: true)
    try FileManager.default.createDirectory(
      at: python.deletingLastPathComponent(), withIntermediateDirectories: true)
    try FileManager.default.createDirectory(at: hermesHome, withIntermediateDirectories: true)
    try Data("#!/bin/sh\nexit 0\n".utf8).write(to: python)
    try FileManager.default.setAttributes(
      [.posixPermissions: 0o700],
      ofItemAtPath: python.path
    )

    let scheduler = HermesCronSchedulerService(
      paths: paths, runner: HermesSchedulerIsolationRunner())
    let status = try awaitResult {
      try await scheduler.ensureInstalledAndStarted(
        harnessPath: harnessPath,
        hermesHome: hermesHome,
        environment: ["PATH": "/usr/bin:/bin"]
      )
    }

    try expect(
      status.plistPath.hasPrefix(root.path),
      "service-test Hermes LaunchAgent should be isolated under the test root")
    try expect(
      FileManager.default.fileExists(atPath: status.plistPath),
      "isolated Hermes LaunchAgent plist should be written")
    try expect(
      !status.plistPath.hasPrefix(
        FileManager.default.homeDirectoryForCurrentUser.path + "/Library/LaunchAgents"),
      "service-test Hermes LaunchAgent must not write to real user LaunchAgents")
  }

  private static func testOpenClawDispatchRunsCLIFromHarnessInstallPath() throws {
    let runner = ScriptedProvisioningRunner(initialOpenClawAgents: ["claw_man"])
    let services = try makeServices(runner: runner)
    let workspace = try unwrap(services.data.getAppState().activeWorkspace, "missing workspace")
    let harness = try prepareInstalledHarness(services: services, key: .openclaw)
    let agent = try services.data.createAgent(
      workspaceId: workspace.id,
      name: "Claw Man",
      harnessId: harness.id,
      externalAgentId: "claw_man"
    )
    let thread = try services.data.createThread(
      workspaceId: workspace.id,
      title: "OpenClaw Dispatch CWD",
      selectedAgentId: agent.id,
      threadType: .direct
    )

    _ = try awaitResult {
      try await services.dispatch.sendMessage(
        threadId: thread.id,
        agentId: agent.id,
        content: "Check dispatch cwd"
      )
    }

    try waitUntil("OpenClaw dispatch should invoke the agent command") {
      runner.openClawAgentRunCwd() != nil
    }
    let harnessPath = services.paths.harnessesDir.appendingPathComponent(
      "openclaw", isDirectory: true
    ).path
    try expect(
      runner.openClawAgentRunCwd() == harnessPath,
      "OpenClaw dispatch should run from the harness install path")
    try expect(
      runner.openClawAgentRunTimeoutMs() == RuntimeDispatchTimeouts.chatTurnMs + 60_000,
      "OpenClaw dispatch should preserve a diagnostic grace period beyond the agent turn timeout")
    try expect(
      (runner.openClawAgentRunTimeoutMs() ?? Int.max) <= CommandResourceLimits.maximumTimeoutMs,
      "OpenClaw dispatch command timeout must stay within ProcessCommandRunner's accepted maximum")
    try expect(
      runner.openClawAgentRunEnvValue("EXA_API_KEY") == nil,
      "OpenClaw dispatch should not expose Exa credentials to the agent process")
    try expect(
      runner.openClawAgentRunEnvValue("X_ACCESS_TOKEN") == nil,
      "OpenClaw dispatch should not expose X credentials to the agent process")
    try expect(
      runner.openClawAgentRunEnvValue("LINKEDIN_ACCESS_TOKEN") == nil,
      "OpenClaw dispatch should not expose LinkedIn credentials to the agent process")
    try waitUntil("OpenClaw dispatch should complete") {
      try services.data.listDispatchesForThread(thread.id).first?.status == .completed
    }
    try waitUntil("OpenClaw dispatch should persist the scripted agent reply") {
      try services.data.listMessages(threadId: thread.id).contains {
        $0.senderType == .agent && $0.content == "OpenClaw reply from scripted runner."
      }
    }
  }

  private static func testAgentProvisioningGuardsMissingAuthAndDuplicateStates() throws {
    let missingServices = try makeServices()
    let missingWorkspace = try unwrap(
      missingServices.data.getAppState().activeWorkspace, "missing workspace")
    do {
      _ = try awaitResult {
        try await missingServices.provisioning.createProvisionedAgent(
          CreateProvisionedAgentRequest(
            workspaceId: missingWorkspace.id,
            harnessId: nil,
            runtimeType: .hermes,
            name: "Missing Harness Agent",
            externalAgentId: "missing_harness_agent"
          ))
      }
      throw ServiceTestFailure("missing harness provisioning unexpectedly succeeded")
    } catch let error as RelayError {
      try expect(error.code == .harnessMissing, "missing harness should throw harness_missing")
    }
    let missingJobs = try missingServices.data.listAgentProvisioningJobs(
      workspaceId: missingWorkspace.id)
    try expect(
      missingJobs.first?.status == .missingHarness,
      "missing harness job should persist missing_harness")
    try expect(
      try missingServices.data.listAgents(workspaceId: missingWorkspace.id).isEmpty,
      "missing harness should not create agents")

    let authRunner = ScriptedProvisioningRunner(authConnected: false)
    let authServices = try makeServices(runner: authRunner)
    let authWorkspace = try unwrap(
      authServices.data.getAppState().activeWorkspace, "missing auth workspace")
    let authHarness = try prepareInstalledHarness(services: authServices, key: .hermes)
    do {
      _ = try awaitResult {
        try await authServices.provisioning.createProvisionedAgent(
          CreateProvisionedAgentRequest(
            workspaceId: authWorkspace.id,
            harnessId: authHarness.id,
            runtimeType: .hermes,
            name: "Auth Required Agent",
            externalAgentId: "auth_required_agent"
          ))
      }
      throw ServiceTestFailure("auth-required provisioning unexpectedly succeeded")
    } catch let error as RelayError {
      try expect(
        error.code == .harnessUnhealthy, "auth-required provisioning should throw harness_unhealthy"
      )
    }
    let authJobs = try authServices.data.listAgentProvisioningJobs(workspaceId: authWorkspace.id)
    try expect(
      authJobs.first?.status == .authRequired, "auth-required job should persist auth_required")
    try expect(
      try authServices.data.listAgents(workspaceId: authWorkspace.id).isEmpty,
      "auth-required harness should not create agents")

    let duplicateRunner = ScriptedProvisioningRunner()
    let duplicateServices = try makeServices(runner: duplicateRunner)
    let duplicateWorkspace = try unwrap(
      duplicateServices.data.getAppState().activeWorkspace, "missing duplicate workspace")
    let duplicateHarness = try prepareInstalledHarness(services: duplicateServices, key: .openclaw)
    _ = try awaitResult {
      try await duplicateServices.provisioning.createProvisionedAgent(
        CreateProvisionedAgentRequest(
          workspaceId: duplicateWorkspace.id,
          harnessId: duplicateHarness.id,
          runtimeType: .openclaw,
          name: "Duplicate Base",
          externalAgentId: "duplicate_agent"
        ))
    }
    do {
      _ = try awaitResult {
        try await duplicateServices.provisioning.createProvisionedAgent(
          CreateProvisionedAgentRequest(
            workspaceId: duplicateWorkspace.id,
            harnessId: duplicateHarness.id,
            runtimeType: .openclaw,
            name: "Duplicate Attempt",
            externalAgentId: "duplicate_agent"
          ))
      }
      throw ServiceTestFailure("duplicate provisioning unexpectedly succeeded")
    } catch let error as RelayError {
      try expect(error.code == .invalidInput, "duplicate provisioning should throw invalid_input")
    }
    let duplicateJobs = try duplicateServices.data.listAgentProvisioningJobs(
      workspaceId: duplicateWorkspace.id)
    try expect(
      duplicateJobs.first?.status == .duplicateId, "duplicate job should persist duplicate_id")
    try expect(
      try duplicateServices.data.listAgents(workspaceId: duplicateWorkspace.id).count == 1,
      "duplicate provisioning should not create a second agent")
  }

