    try expect(
      runtimeSnapshot.mountedToolNames.contains("relay_console_google_docs_open_setup"),
      "resident agent should mount Google Docs setup browser tool")
    try expect(
      !runtimeSnapshot.mountedToolNames.contains(
        "relay_console_google_docs_oauth_authorization_url"),
      "resident agent should not mount the retired local Google Docs OAuth authorization URL tool")
    try expect(
      !runtimeSnapshot.mountedToolNames.contains("relay_console_google_docs_exchange_auth_code"),
      "resident agent should not mount the retired local Google Docs OAuth code exchange tool")
    try expect(
      !runtimeSnapshot.mountedToolNames.contains("relay_console_google_docs_save_oauth_credentials"),
      "resident agent should not mount the retired local Google Docs credential save tool")
    var openedSetupUrls: [String] = []
    let residentBridge = MarketplaceRuntimeToolBridgeService(
      data: services.data,
      runtimeMounts: services.marketplaceRuntimeMounts,
      broker: services.providerActionBroker,
      openExternal: { openedSetupUrls.append($0) }
    )
    let openedResult = try residentBridge.execute(
      toolName: "relay_console_google_docs_open_setup",
      payload: ["targets": .array([.string("docsApi")])],
      runtime: MarketplaceRuntimeToolExecutionContext(
        agentId: agent.id,
        workspaceId: workspace.id,
        runtimeType: agent.binding.runtimeType,
        dispatchId: "rtd-resident-google-docs-open-setup"
      )
    )
    try expect(
      openedResult["toolName"] == .string("relay_console_google_docs_open_setup"),
      "resident bridge should execute Google Docs setup opener")
    try expect(
      openedSetupUrls == ["https://console.cloud.google.com/apis/library/docs.googleapis.com"],
      "resident setup opener should open requested Google setup page")
    do {
      _ = try residentBridge.execute(
        toolName: "relay_console_google_docs_oauth_authorization_url",
        payload: ["clientId": .string("desktop-client.apps.googleusercontent.com")],
        runtime: MarketplaceRuntimeToolExecutionContext(
          agentId: agent.id,
          workspaceId: workspace.id,
          runtimeType: agent.binding.runtimeType,
          dispatchId: "rtd-resident-google-docs-oauth-url"
        )
      )
      throw ServiceTestFailure("retired local Google Docs OAuth URL tool unexpectedly executed")
    } catch let denied as ServiceGuardResult {
      try expect(
        denied.reasonCode == .inputInvalid,
        "retired local Google Docs OAuth URL tool should fail closed")
      try expect(
        denied.message.contains("authenticated Railway broker"),
        "retired local Google Docs OAuth URL tool should direct callers to Railway")
    }
    try expect(
      openedSetupUrls.count == 1,
      "retired local Google Docs OAuth URL tool should not open a consent URL")

    _ = try services.runtimeWorkspace.saveMarkdown(
      agent: agent,
      rootId: RuntimeWorkspaceRootKind.hermesProfile.rawValue,
      folderRelativePath: "memories",
      filename: "memory.md",
      markdown: "# Pinned Memory\n\nUser edit survives."
    )
    let second = try awaitResult {
      try await services.residentAgents.ensureDefaultResidentAgent(
        workspaceId: workspace.id,
        requestedByProfileId: profile.id
      )
    }
    try expect(second.agent?.id == agent.id, "resident bootstrap should be idempotent")
    try expect(second.thread?.id == thread.id, "resident direct thread should be reused")
    let editedMemory = try services.runtimeWorkspace.readFile(
      agent: agent,
      rootId: RuntimeWorkspaceRootKind.hermesProfile.rawValue,
      relativePath: "memories/memory.md"
    )
    try expect(
      editedMemory.markdown.contains("User edit survives."),
      "resident bootstrap should not overwrite user-edited memory")
    try expect(
      try services.data.listAgents(workspaceId: workspace.id).filter {
        $0.binding.externalAgentId == "relay_console"
      }.count == 1, "resident bootstrap should not create duplicate agents")
  }

  private static func testAgentOrganizationServiceEnforcesAuthorityAndManagerRules() throws {
    let services = try makeServices()
    let workspace = try unwrap(services.data.getAppState().activeWorkspace, "missing org workspace")
    let owner = context(
      roles: [.owner], workspaceId: workspace.id, correlationId: "corr-org-owner-001")
    let admin = context(
      roles: [.admin], workspaceId: workspace.id, correlationId: "corr-org-admin-001")
    let member = context(
      roles: [.member], workspaceId: workspace.id, correlationId: "corr-org-member-001")
    let eventCounter = EventCounter()
    let subscription = services.eventBus.on(.agentOrganizationUpdated) { _ in
      eventCounter.increment()
    }
    defer {
      services.eventBus.off(.agentOrganizationUpdated, id: subscription)
    }

    do {
      _ = try services.organization.createCompany(
        context: member,
        name: "Denied Organization",
        metadata: ["rawDetail": .string("credential=org-sensitive-value-001")]
      )
      throw ServiceTestFailure("member org mutation unexpectedly succeeded")
    } catch let denied as ServiceGuardResult {
      try expect(
        denied.reasonCode == .authorityRoleRequired,
        "member org mutation should require owner/admin")
    }
    try expect(
      try services.data.listAgentOrgCompanies(workspaceId: workspace.id).isEmpty,
      "denied org mutation should not persist company")
    let deniedAudit = try unwrap(
      services.data.queryEventLog().first { $0.correlationId == member.correlationId },
      "denied org mutation should write audit event"
    )
    try expect(
      deniedAudit.category == "authority", "denied org audit should use authority category")
    try expect(
      deniedAudit.detail["reasonCode"] == .string(GuardReasonCode.authorityRoleRequired.rawValue),
      "denied audit should include role reason")
    try expect(
      (deniedAudit.detail["rawDetail"]?.string ?? "").contains("[REDACTED]"),
      "denied org audit should redact sensitive detail")
    try expect(
      !(deniedAudit.detail["rawDetail"]?.string ?? "").contains("org-sensitive-value-001"),
      "denied org audit leaked sensitive detail")

    let company = try services.organization.createCompany(
      context: owner, name: "Operations", industry: "Support")
    try expect(company.status == "active", "created company should be active")
    try expect(eventCounter.value > 0, "allowed org mutation should publish event")

    let lead = try createServiceAgent(services: services, workspaceId: workspace.id)
    let manager = try services.data.createAgent(
      workspaceId: workspace.id,
      name: "Org Manager Agent",
      harnessId: lead.harness.id,
      externalAgentId: "org_manager_agent"
    )
    let report = try services.data.createAgent(
      workspaceId: workspace.id,
      name: "Org Report Agent",
      harnessId: lead.harness.id,
      externalAgentId: "org_report_agent"
    )

    let department = try services.organization.createDepartment(
      context: admin,
      companyId: company.id,
      name: "Support",
      colorHex: "#3366CC",
      headAgentId: manager.id
    )
    try expect(department.companyId == company.id, "department should belong to selected company")
    try expect(department.headAgentId == manager.id, "department head should persist")
    try expect(
      try services.data.getAgent(manager.id).departmentId == department.id,
      "department head placement should sync")

    let explicitTeam = try services.organization.createTeam(
      context: admin,
      departmentId: department.id,
      name: "Escalations",
      leadAgentId: nil,
      inheritDepartmentHeadAsLead: false
    )
    try expect(
      explicitTeam.leadAgentId == nil, "team should not inherit department head unless requested")
    try expect(
      explicitTeam.metadata["leadProvenance"] == .string("explicit_or_empty"),
      "non-inherited team should record provenance")

    let inheritedTeam = try services.organization.createTeam(
      context: admin,
      departmentId: department.id,
      name: "Coverage",
      leadAgentId: nil,
      inheritDepartmentHeadAsLead: true
    )
    try expect(
      inheritedTeam.leadAgentId == manager.id,
      "team should inherit department head only when requested")
    try expect(
      inheritedTeam.metadata["leadProvenance"] == .string("inherited_from_department_head"),
      "inherited team should record provenance")

    let roomedDepartment = try services.organization.setDepartmentAgentOpsRoom(
      context: owner,
      departmentId: department.id,
      agentOpsRoomId: "thr-agentops-department-001"
    )
    try expect(
      roomedDepartment.agentOpsRoomId == "thr-agentops-department-001",
      "department AgentOps room should persist")
    let roomedTeam = try services.organization.setTeamAgentOpsRoom(
      context: owner,
      teamId: inheritedTeam.id,
      agentOpsRoomId: "thr-agentops-team-001"
    )
    try expect(
      roomedTeam.agentOpsRoomId == "thr-agentops-team-001", "team AgentOps room should persist")

    let secondCompany = try services.organization.createCompany(context: owner, name: "Product")
    let secondDepartment = try services.organization.createDepartment(
      context: owner, companyId: secondCompany.id, name: "Product Team")
    do {
      _ = try services.organization.updateAgentPlacement(
        context: owner,
        agentId: report.id,
        groupType: .business,
        companyId: secondCompany.id,
        departmentId: secondDepartment.id,
        teamId: inheritedTeam.id,
        classification: "operations"
      )
      throw ServiceTestFailure("mismatched team placement unexpectedly succeeded")
    } catch let denied as ServiceGuardResult {
      try expect(
        denied.reasonCode == .inputInvalid, "mismatched team placement should be invalid input")
    }
    try expect(
      try services.data.getAgent(report.id).teamId == nil,
      "invalid placement should not mutate report agent")

    do {
      _ = try services.organization.assignDepartmentManager(
        context: owner,
        departmentId: department.id,
        managerAgentId: lead.id,
        replaceExisting: false
      )
      throw ServiceTestFailure("manager replacement without confirmation unexpectedly succeeded")
    } catch let denied as ServiceGuardResult {
      try expect(
        denied.reasonCode == .decisionRequired, "manager replacement should require confirmation")
      try expect(
        denied.decisionId == "agent.department.manager.replace",
        "manager replacement decision id should be stable")
    }
    try expect(
      try services.data.getAgentOrgDepartment(department.id).headAgentId == manager.id,
      "unconfirmed manager replacement should not mutate head")

    let replaced = try services.organization.assignDepartmentManager(
      context: owner,
      departmentId: department.id,
      managerAgentId: lead.id,
      replaceExisting: true
    )
    try expect(
      replaced.headAgentId == lead.id, "confirmed manager replacement should update department head"
    )
    try expect(
      replaced.metadata["managerReplacementConfirmed"] == .bool(true),
      "manager replacement confirmation should be recorded")

    let managedReport = try services.organization.setAgentManager(
      context: owner,
      reportAgentId: report.id,
      managerAgentId: lead.id
    )
    try expect(
      managedReport.managerAgentId == lead.id, "manager relationship should update report agent")
    let relationships = try services.data.listAgentManagerRelationships(workspaceId: workspace.id)
    try expect(
      relationships.contains { $0.managerAgentId == lead.id && $0.reportAgentId == report.id },
      "manager relationship row should persist")

    let counts = try services.organization.dashboardCounts(context: owner)
    try expect(counts.companyCount == 2, "dashboard counts should include active companies")
    try expect(counts.departmentCount == 2, "dashboard counts should include active departments")
    try expect(counts.teamCount == 2, "dashboard counts should include active teams")
    try expect(
      counts.managerRelationshipCount == 1, "dashboard counts should include manager relationships")
    try expect(counts.businessAgentCount >= 2, "dashboard counts should include business agents")
    try expect(
      counts.agentsByDepartment[department.id, default: 0] >= 2,
      "dashboard counts should group agents by department")

    do {
      _ = try services.organization.deleteDepartment(context: owner, departmentId: department.id)
      throw ServiceTestFailure("guarded department delete unexpectedly succeeded")
    } catch let denied as ServiceGuardResult {
      try expect(
        denied.reasonCode == .policyBlocked, "department with teams/agents should be policy blocked"
      )
    }
    try expect(
      try services.data.getAgentOrgDepartment(department.id).status == "active",
      "denied department delete should not change status")

    let cascade = try services.organization.cascadeDeleteCompany(
      context: owner, companyId: company.id)
    try expect(cascade.company.status == "deleted", "cascade should mark company deleted")
    try expect(
      cascade.departments.contains { $0.id == department.id },
      "cascade should include company department")
    try expect(
      cascade.teams.contains { $0.id == explicitTeam.id }, "cascade should include explicit team")
    try expect(
      cascade.teams.contains { $0.id == inheritedTeam.id }, "cascade should include inherited team")
    try expect(
      cascade.unassignedAgents.contains { $0.id == lead.id },
      "cascade should unassign current department head")
    try expect(
      cascade.unassignedAgents.contains { $0.id == manager.id },
      "cascade should unassign previous department head")
    try expect(
      try services.data.getAgentOrgCompany(company.id).status == "deleted",
      "cascade should persist deleted company")
    try expect(
      try services.data.getAgentOrgDepartment(department.id).status == "deleted",
      "cascade should persist deleted department")
    try expect(
      try services.data.getAgentOrgTeam(explicitTeam.id).status == "deleted",
      "cascade should persist deleted explicit team")
    try expect(
      try services.data.getAgentOrgTeam(inheritedTeam.id).status == "deleted",
      "cascade should persist deleted inherited team")
    for agentId in [lead.id, manager.id] {
      let agent = try services.data.getAgent(agentId)
      try expect(agent.groupType == .unassigned, "cascade should move affected agent to unassigned")
      try expect(agent.companyId == nil, "cascade should clear affected agent company")
      try expect(agent.departmentId == nil, "cascade should clear affected agent department")
      try expect(agent.teamId == nil, "cascade should clear affected agent team")
    }
    try expect(
      try services.data.getAgentOrgCompany(secondCompany.id).status == "active",
      "cascade should not delete other companies")
    try expect(
      try services.data.getAgentOrgDepartment(secondDepartment.id).status == "active",
      "cascade should not delete other departments")
  }

  private static func testAgentWorkDashboardsUseDurableRecordsWithoutFakeRows() throws {
    let services = try makeServices()
    let workspace = try unwrap(
      services.data.getAppState().activeWorkspace, "missing work workspace")
    let owner = context(
      roles: [.owner], workspaceId: workspace.id, correlationId: "corr-work-owner-001")
    let viewer = context(
      roles: [.viewer], workspaceId: workspace.id, correlationId: "corr-work-viewer-001")
    let fixtureNow = try unwrap(
      ISO8601DateFormatter.relayConsole.date(from: "2026-06-23T12:00:00.000Z"),
      "invalid fixture date"
    )
    let eventCounter = EventCounter()
    let subscription = services.eventBus.on(.agentWorkUpdated) { _ in
      eventCounter.increment()
    }
    defer {
      services.eventBus.off(.agentWorkUpdated, id: subscription)
    }

    let emptyDashboard = try services.work.structureDashboard(context: owner)
    try expect(
      emptyDashboard.totalRunningTasks == 0, "empty dashboard should not invent running tasks")
    try expect(emptyDashboard.totalMemoryItems == 0, "empty dashboard should not invent memory")
    let emptyCalendar = try services.work.workCalendar(
      context: owner,
      groupType: .business,
      dayCount: 7,
      now: fixtureNow,
      timeZone: TimeZone(secondsFromGMT: 0) ?? .current
    )
    try expect(emptyCalendar.rows.isEmpty, "empty business calendar should not invent agent rows")

    do {
      _ = try services.work.structureDashboard(context: viewer)
      throw ServiceTestFailure("viewer work dashboard unexpectedly succeeded")
    } catch let denied as ServiceGuardResult {
      try expect(
        denied.reasonCode == .authorityRoleRequired,
        "viewer work dashboard should require workspace member access")
    }

    let company = try services.organization.createCompany(context: owner, name: "Work Ops")
    let department = try services.organization.createDepartment(
      context: owner, companyId: company.id, name: "Work Dispatch")
    let team = try services.organization.createTeam(
      context: owner, departmentId: department.id, name: "Work Queue")
    let agent = try createServiceAgent(services: services, workspaceId: workspace.id)
    let placedAgent = try services.organization.updateAgentPlacement(
      context: owner,
      agentId: agent.id,
      groupType: .business,
      companyId: company.id,
      departmentId: department.id,
      teamId: team.id,
      classification: "work-dashboard-fixture"
    )

    let now = ISO8601DateFormatter.relayConsole.string(from: fixtureNow)
    let runningTask = try services.data.createAgentTask(
      workspaceId: workspace.id,
      title: "Retained scheduled work",
      message: "Use persisted task read model only.",
      assignedAgentId: placedAgent.id,
      targetAgentId: placedAgent.id,
      priority: .high,
      targetType: .direct,
      status: .running,
      requiresApproval: false,
      scheduledAt: now,
      timeZone: "UTC"
    )
    _ = try services.data.createAgentTask(
      workspaceId: workspace.id,
      title: "Retained approval block",
      message: "Approval state is sourced from the durable task row.",
      assignedAgentId: placedAgent.id,
      targetAgentId: placedAgent.id,
      priority: .critical,
      targetType: .direct,
      status: .blocked,
      requiresApproval: true,
      scheduledAt: now,
      timeZone: "UTC"
    )
    _ = try services.data.createAgentTask(
      workspaceId: workspace.id,
      title: "Retained failed task",
      message: "Incident count is sourced from failed task state.",
      assignedAgentId: placedAgent.id,
      targetTeamId: team.id,
      priority: .normal,
      targetType: .team,
      status: .failed,
      scheduledAt: now,
      timeZone: "UTC"
    )
    _ = try services.data.createAgentTaskRun(
      workspaceId: workspace.id,
      taskId: runningTask.id,
      agentId: placedAgent.id,
      status: .completed,
      tokensUsed: 12,
      startedAt: now,
      completedAt: now
    )
    let memory = try services.data.createAgentTeamMemoryEntry(
      workspaceId: workspace.id,
      teamId: team.id,
      title: "Sensitive queue rule",
      memoryType: .rule,
      content: "service-sensitive-memory-value-001",
      isSensitive: true,
      createdByAgentId: placedAgent.id
    )
    let handover = try services.data.createAgentTeamHandover(
      workspaceId: workspace.id,
      teamId: team.id,
      fromAgentId: placedAgent.id,
      title: "Sensitive handover",
      content: "service-sensitive-handover-value-001",
      isSensitive: true
    )

    let dashboard = try services.work.structureDashboard(context: owner)
    try expect(dashboard.totalRunningTasks == 1, "dashboard should count one running task")
    try expect(dashboard.totalBlockedTasks == 1, "dashboard should count one blocked task")
    try expect(dashboard.totalPendingApprovals == 1, "dashboard should count one pending approval")
    try expect(dashboard.totalOpenIncidents == 1, "dashboard should count one failed task incident")
    try expect(dashboard.totalMemoryItems == 1, "dashboard should count persisted team memory")
    try expect(dashboard.totalHandovers == 1, "dashboard should count persisted handovers")
    let teamSnapshot = try unwrap(
      dashboard.teams.first { $0.teamId == team.id }, "missing team snapshot")
    try expect(teamSnapshot.memoryCount == 1, "team dashboard should count memory by team")
    try expect(teamSnapshot.handoverCount == 1, "team dashboard should count handovers by team")

    let calendar = try services.work.workCalendar(
      context: owner,
      groupType: .business,
      dayCount: 7,
      now: fixtureNow,
      timeZone: TimeZone(secondsFromGMT: 0) ?? .current
    )
    let calendarRow = try unwrap(
      calendar.rows.first { $0.agentId == placedAgent.id },
      "calendar should include the placed business agent")
    try expect(
      calendarRow.totalActivityCount == 0,
      "calendar should not invent chat activity without source agent messages")
    try expect(
      calendarRow.totalScheduledTaskCount == 3,
      "calendar should derive scheduled work from persisted tasks")
    try expect(
      calendarRow.totalCompletedRunCount == 1,
      "calendar should derive completed work from persisted task runs")
    try expect(
      calendarRow.totalActiveMinutes == 0,
      "calendar should not invent active hours without source chat messages")

    let personalAgent = try createServiceAgent(services: services, workspaceId: workspace.id)
    let allCalendar = try services.work.workCalendar(
      context: owner,
      groupType: nil,
      dayCount: 7,
      now: fixtureNow,
      timeZone: TimeZone(secondsFromGMT: 0) ?? .current
    )
    try expect(
      allCalendar.rows.contains { $0.agentId == placedAgent.id },
      "all calendar should include business agents")
    try expect(
      allCalendar.rows.contains { $0.agentId == personalAgent.id },
      "all calendar should include personal agents")

    let activeThread = try services.data.createThread(
      workspaceId: workspace.id,
      title: "Retained active hours",
      selectedAgentId: placedAgent.id
    )
    _ = try services.data.createMessage(
      threadId: activeThread.id,
      senderType: .user,
      senderName: "Local user",
      content: "Start the active work window."
    )
    let activeCalendar = try services.work.workCalendar(
      context: owner,
      groupType: .business,
      dayCount: 1,
      now: Date(),
      timeZone: .current,
      activeGapMinutes: 20
    )
    let activeCalendarRow = try unwrap(
      activeCalendar.rows.first { $0.agentId == placedAgent.id },
      "calendar should include active direct-chat agent")
    try expect(
      activeCalendarRow.totalActiveMinutes == 20,
      "single chat message should create a 20-minute active work window")

    do {
      _ = try services.work.createTask(
        context: viewer,
        title: "Viewer task",
        message: "Viewer should not create this task.",
        priority: .normal,
        targetType: .direct,
        targetAgentId: placedAgent.id,
        targetTeamId: nil,
        scheduledAt: now,
        timeZone: "UTC",
        recurrence: nil,
        requiresApproval: false
      )
      throw ServiceTestFailure("viewer task creation unexpectedly succeeded")
    } catch let denied as ServiceGuardResult {
      try expect(
        denied.reasonCode == .authorityRoleRequired,
        "viewer task create should require owner/admin access")
    }

    let createdTask = try services.work.createTask(
      context: owner,
      title: "UI scheduled task",
      message: "Created through the agent work service.",
      priority: .normal,
      targetType: .direct,
      targetAgentId: placedAgent.id,
      targetTeamId: nil,
      scheduledAt: now,
      timeZone: "UTC",
      recurrence: nil,
      requiresApproval: false
    )
    try expect(
      createdTask.targetAgentId == placedAgent.id, "created task should target selected agent")
    try expect(
      createdTask.assignedAgentId == placedAgent.id, "created task should assign selected agent")
    try expect(createdTask.threadId != nil, "created task should link a chat thread")
    try expect(
      createdTask.threadId == activeThread.id,
      "created task should reuse the agent's existing direct chat")
    try expect(
      try services.data.listThreads(workspaceId: workspace.id).filter {
        $0.threadType == .direct && $0.selectedAgentId == placedAgent.id
      }.count == 1,
      "scheduling should not create a duplicate direct chat")
    let nextQuarterHour = AgentTaskRecurrenceSchedule.nextRun(
      after: fixtureNow,
      recurrence: "Every 15 minutes",
      timeZoneIdentifier: "UTC",
      now: fixtureNow.addingTimeInterval(31 * 60)
    )
    try expect(
      nextQuarterHour == fixtureNow.addingTimeInterval(45 * 60),
      "recurring schedules should advance to the next future interval")

    let existingTeamThread = try services.chat.createTeamThread(
      context: owner,
      departmentId: department.id,
      title: "Existing work team chat",
      selectedAgentIds: [placedAgent.id]
    )
    let teamTask = try services.work.createTask(
      context: owner,
      title: "UI team scheduled task",
      message: "Inject into the existing team conversation.",
      priority: .normal,
      targetType: .team,
      targetAgentId: nil,
      targetTeamId: team.id,
      preferredThreadId: existingTeamThread.id,
      scheduledAt: now,
      timeZone: "UTC",
      recurrence: nil,
      requiresApproval: false
    )
    try expect(
      teamTask.threadId == existingTeamThread.id,
      "created team task should reuse the selected existing team chat")
    try expect(
      try services.data.listThreads(workspaceId: workspace.id).filter { $0.threadType == .team }.count == 1,
      "scheduling should not create a duplicate team chat")

    let tasks = try services.work.tasksForAgent(context: owner, agentId: placedAgent.id)
    try expect(
      tasks.count == 5,
      "selected agent tasks should load from durable rows and service-created rows")
    try expect(
      tasks.contains { $0.id == createdTask.id },
      "selected agent tasks should include service-created task")
    let personalTask = try services.data.createAgentTask(
      workspaceId: workspace.id,
      title: "Personal agent scheduled task",
      message: "This task verifies that the schedule is not scoped to the agent picker.",
      assignedAgentId: personalAgent.id,
      targetAgentId: personalAgent.id,
      priority: .normal,
      targetType: .direct,
      status: .cancelled,
      requiresApproval: false,
      scheduledAt: now,
      timeZone: "UTC"
    )
    let workspaceTasks = try services.work.tasksForWorkspace(context: owner)
    try expect(
      workspaceTasks.contains { $0.id == createdTask.id }
        && workspaceTasks.contains { $0.id == personalTask.id },
      "workspace task schedule should include tasks belonging to different agents")
    let runs = try services.work.taskRuns(context: owner, taskId: runningTask.id)
    try expect(runs.count == 1, "task run history should load from durable rows")
    try expect(
      try services.work.teamMemory(context: owner, teamId: team.id).first?.id == memory.id,
      "team memory should load through service")
    try expect(
      try services.work.teamHandovers(context: owner, teamId: team.id).first?.id == handover.id,
      "team handover should load through service")
    let claimedTasks = try services.data.claimDueAgentTasks(now: now)
    try expect(
      Set(claimedTasks.map(\.id)) == Set([createdTask.id, teamTask.id]),
      "the scheduler should atomically claim due direct and team tasks")
    try expect(eventCounter.value >= 6, "agent work mutations should publish update events")
  }

  private static func testAgentOpsLiveStateUsesRetainedRecordsAndRedactsRuntimeOverview() throws {
    let services = try makeServices()
    let workspace = try unwrap(services.data.getAppState().activeWorkspace, "missing workspace")
    let owner = context(
      roles: [.owner], workspaceId: workspace.id, correlationId: "agentops-owner-001")
    let member = context(
      roles: [.member], workspaceId: workspace.id, correlationId: "agentops-member-001")
    do {
      _ = try services.agentOps.liveStateSnapshot(context: member)
      throw ServiceTestFailure("member AgentOps runtime overview unexpectedly succeeded")
    } catch let denied as ServiceGuardResult {
      try expect(
        denied.reasonCode == .authorityRoleRequired,
        "AgentOps runtime overview should require owner/admin access")
    }

    let workingAgent = try createServiceAgent(services: services, workspaceId: workspace.id)
    let approvalAgent = try services.data.createAgent(
      workspaceId: workspace.id,
      name: "Approval Agent",
      harnessId: workingAgent.harness.id
    )
    let messageAgent = try services.data.createAgent(
      workspaceId: workspace.id,
      name: "Message Agent",
      harnessId: workingAgent.harness.id
    )
    let offlineAgent = try services.data.createAgent(
      workspaceId: workspace.id,
      name: "Offline Agent",
      harnessId: workingAgent.harness.id
    )
    _ = try services.data.updateAgent(agentId: offlineAgent.id, status: "paused")
    let idleAgent = try services.data.createAgent(
      workspaceId: workspace.id,
      name: "Idle Agent",
      harnessId: workingAgent.harness.id
    )

    let sensitive = "agentops-sensitive-runtime-text-001"
    let thread = try services.data.createThread(
      workspaceId: workspace.id,
      title: "AgentOps Runtime Thread",
      selectedAgentId: workingAgent.id,
      threadType: .direct
    )
    let userMessage = try services.data.createMessage(
      threadId: thread.id,
      senderType: .user,
      senderName: "Local user",
      content: sensitive
    )
    let session = try services.data.createRuntimeSession(
      threadId: thread.id,
      agentId: workingAgent.id,
      runtimeBindingId: workingAgent.binding.id
    )
    let dispatch = try services.data.createDispatch(
      threadId: thread.id,
      messageId: userMessage.id,
      agentId: workingAgent.id,
      harnessId: workingAgent.harness.id,
      sessionId: session.id,
      correlationId: "agentops-dispatch-001",
      inputSnapshot: [
        "content": .string(sensitive),
        "runtimeType": .string(RuntimeType.hermes.rawValue),
      ]
    )
    _ = try services.data.updateDispatch(dispatchId: dispatch.id, status: .streaming)
    let approvalTask = try services.data.createAgentTask(
      workspaceId: workspace.id,
      title: "Approval gate",
      message: sensitive,
      assignedAgentId: approvalAgent.id,
      targetAgentId: approvalAgent.id,
      priority: .critical,
      targetType: .direct,
      status: .blocked,
      requiresApproval: true
    )
    let messageThread = try services.data.createThread(
      workspaceId: workspace.id,
      title: "AgentOps Message Thread",
      selectedAgentId: messageAgent.id,
      threadType: .direct
    )
    let agentMessage = try services.data.createMessage(
      threadId: messageThread.id,
      senderType: .agent,
      senderId: messageAgent.id,
      senderName: messageAgent.name,
      content: sensitive,
      metadata: ["taskId": .string(approvalTask.id)]
    )

    let snapshot = try services.agentOps.liveStateSnapshot(context: owner)
    let working = try unwrap(
      snapshot.agents.first { $0.agentId == workingAgent.id }, "missing working AgentOps state")
    try expect(working.visibleState == .working, "streaming dispatch should map to working")
    try expect(
      working.source == .runtimeDispatch, "streaming dispatch should use runtime_dispatch source")
    try expect(working.dispatchId == dispatch.id, "AgentOps state should link retained dispatch")

    let waiting = try unwrap(
      snapshot.agents.first { $0.agentId == approvalAgent.id }, "missing approval AgentOps state")
    try expect(
      waiting.visibleState == .waitingForApproval,
      "blocked approval task should map to waiting_for_approval")
    try expect(waiting.source == .approval, "approval block should use approval source")
    try expect(waiting.taskId == approvalTask.id, "AgentOps state should link retained task")

    let completed = try unwrap(
      snapshot.agents.first { $0.agentId == messageAgent.id }, "missing message AgentOps state")
    try expect(completed.visibleState == .completed, "latest agent message should map to completed")
    try expect(completed.source == .message, "agent message should use message source")
    try expect(
      completed.messageId == agentMessage.id, "AgentOps state should link retained message")

    let offline = try unwrap(
      snapshot.agents.first { $0.agentId == offlineAgent.id }, "missing offline AgentOps state")
    try expect(offline.visibleState == .offline, "non-active agent should map to offline")
    try expect(offline.source == .agentStatus, "non-active agent should use agent_status source")

    let idle = try unwrap(
      snapshot.agents.first { $0.agentId == idleAgent.id }, "missing idle AgentOps state")
    try expect(idle.visibleState == .idle, "no signal agent should map to weak idle")
    try expect(idle.source == .none, "no signal agent should use none source")
    try expect(
      idle.visualFallbackOnly, "idle no-signal state should be marked visual fallback only")

    let encoded = String(data: try JSONEncoder().encode(snapshot), encoding: .utf8) ?? ""
    try expect(!encoded.contains(sensitive), "AgentOps snapshot leaked sensitive operator text")
    try expect(
      snapshot.events.contains { $0.redactionStatus.contains("redacted") },
      "AgentOps feed should mark redacted events")
    try expect(
      snapshot.runtimeOverview.adminGuard == "owner_admin_only",
      "runtime overview should carry admin guard marker")
  }

  private static func testAgentOpsVisualSceneUsesLiveStateRecordsAndDeterministicFallbacks() throws
  {
    let services = try makeServices()
    let workspace = try unwrap(services.data.getAppState().activeWorkspace, "missing workspace")
    let owner = context(
      roles: [.owner], workspaceId: workspace.id, correlationId: "agentops-visual-owner-001")
    let workingAgent = try createServiceAgent(services: services, workspaceId: workspace.id)
    let idleAgent = try services.data.createAgent(
      workspaceId: workspace.id,
      name: "Visual Idle Agent",
      harnessId: workingAgent.harness.id
    )
    let sensitive = "agentops-visual-sensitive-text-001"
    let thread = try services.data.createThread(
      workspaceId: workspace.id,
      title: "AgentOps Visual Scene Thread",
      selectedAgentId: workingAgent.id,
      threadType: .direct
    )
    let message = try services.data.createMessage(
      threadId: thread.id,
      senderType: .user,
      senderName: "Local user",
      content: sensitive
    )
    let session = try services.data.createRuntimeSession(
      threadId: thread.id,
      agentId: workingAgent.id,
      runtimeBindingId: workingAgent.binding.id
    )
    let dispatch = try services.data.createDispatch(
      threadId: thread.id,
      messageId: message.id,
      agentId: workingAgent.id,
      harnessId: workingAgent.harness.id,
      sessionId: session.id,
      correlationId: "agentops-visual-dispatch-001",
      inputSnapshot: ["content": .string(sensitive)]
    )
    _ = try services.data.updateDispatch(dispatchId: dispatch.id, status: .streaming)

    let snapshot = try services.agentOps.liveStateSnapshot(
      context: owner, selectedAgentIds: [workingAgent.id, idleAgent.id])
    let scene = services.agentOps.visualSceneSnapshot(
      from: snapshot, selectedEntityId: workingAgent.id)
    let workingEntity = try unwrap(
      scene.entities.first { $0.agentId == workingAgent.id }, "missing working visual entity")
    let idleEntity = try unwrap(
      scene.entities.first { $0.agentId == idleAgent.id }, "missing idle visual entity")

    try expect(
      scene.selectedEntityId == "agent-\(workingAgent.id)",
      "scene should normalize selected agent id to selected visual entity")
    try expect(
      workingEntity.state == .working, "streaming retained dispatch should render as working")
    try expect(
      workingEntity.source == .runtimeDispatch,
      "working entity should preserve runtime_dispatch source")
    try expect(
      workingEntity.sourceRecordIds.contains("dispatch:\(dispatch.id)"),
      "working entity should link retained dispatch record")
    try expect(
      workingEntity.sourceRecordIds.contains("message:\(message.id)"),
      "working entity should link source message id without content")
    try expect(
      !workingEntity.visualFallbackOnly, "dispatch-backed entity should not be visual fallback only"
    )
    try expect(idleEntity.state == .idle, "missing live state should render weak idle")
    try expect(idleEntity.visualFallbackOnly, "missing live state should stay visual fallback only")
    try expect(
      idleEntity.sourceRecordIds == ["agent:\(idleAgent.id)", "source:none"],
      "visual fallback should only cite the retained agent row and none source")
    try expect(
      scene.rooms.contains { $0.id == workingEntity.roomId }, "scene should include entity room")
    try expect(
      scene.connections.contains {
        $0.fromEntityId == workingEntity.id
          && $0.sourceRecordIds.contains("dispatch:\(dispatch.id)")
          && ($0.waypoints?.count ?? 0) >= 2
      }, "scene path should be source-record backed")
    try expect(
      scene.assetStrategy == "bundled_web_agentops_floor_worker_assets",
      "scene should record bundled AgentOps asset strategy")
    try expect(
      scene.layoutPersistenceStatus == "web_default_operations_floor_layout_source_record_backed",
      "scene should record bundled web floor layout source")
    try expect(
      scene.floors.contains {
        $0.id == "floor_01_operations"
          && $0.backgroundResourceName == "agentops-tower-main-operations-floor"
          && Int($0.bounds.width) == 1586 && Int($0.bounds.height) == 992
      }, "scene should expose the bundled operations floor asset")
    try expect(scene.rooms.count >= 25, "scene should load the web operations floor rooms")
    try expect(
      scene.rooms.contains {
        $0.id == "agent_monitoring_room" && $0.deterministicFallback == false
          && ($0.workstationAnchors?.isEmpty == false)
      }, "scene should expose layout workstation anchors")
    try expect(
      scene.entities.contains { $0.kind == .room && $0.id == "room-agent_monitoring_room" },
      "scene should include selectable room entities")
    try expect(
      workingEntity.spriteResourceName?.hasPrefix("office-worker-") == true,
      "working entity should carry a bundled worker sprite")
    try expect(
      workingEntity.placementReason == "assigned_layout_workstation",
      "working entity should use a layout workstation")
    try expect(
      scene.unavailableReasons.contains { $0.contains("visual-only fallbacks") },
      "scene should disclose weak visual fallback reason")

    let encoded = String(data: try JSONEncoder().encode(scene), encoding: .utf8) ?? ""
    try expect(!encoded.contains(sensitive), "AgentOps visual scene leaked sensitive operator text")
    try expect(
      !encoded.lowercased().contains("mock"),
      "AgentOps visual scene should not cite mock event product state")
  }

  private static func testRuntimeDashboardSnapshotsAreDurableReadOnlyAndRedacted() throws {
    let root = FileManager.default.temporaryDirectory
      .appendingPathComponent("RelayConsoleRuntimeDashboardTests", isDirectory: true)
      .appendingPathComponent(UUID().uuidString, isDirectory: true)
    let sensitivePath = root.appendingPathComponent("runtime-dashboard-private-root").path
    let workspaceId: String
    let context: ServiceRequestContext

    do {
      let services = try makeServices(root: root)
      let workspace = try unwrap(services.data.getAppState().activeWorkspace, "missing workspace")
      workspaceId = workspace.id
      context = Self.context(roles: [.owner], workspaceId: workspace.id)

      do {
        _ = try services.runtimeDashboard.refreshSnapshot(
          context: Self.context(roles: [.viewer], workspaceId: workspace.id))
        throw ServiceTestFailure("viewer unexpectedly read runtime dashboard snapshot")
      } catch let denied as ServiceGuardResult {
        try expect(
          denied.reasonCode == .authorityRoleRequired,
          "viewer runtime dashboard read should require workspace access")
      }

      let empty = try services.runtimeDashboard.refreshSnapshot(
        context: context, now: fixedDate("2026-01-01T00:00:00Z"))
      try expect(empty.state == .empty, "empty runtime dashboard should be explicit")
      try expect(
        empty.connectedAppCount == 0, "empty runtime dashboard must not fabricate connected apps")
      try expect(empty.readOnly, "runtime dashboard snapshots should be read-only")
      try expect(
        empty.localStatusState == .disabled, "local host-control status should be disabled")
      try expect(
        empty.localStatusReason.contains("host-control"),
        "local host-control exclusion should be explicit")

      let loading = try services.runtimeDashboard.beginRefresh(
        context: context, now: fixedDate("2026-01-01T00:00:01Z"))
      try expect(loading.state == .loading, "runtime dashboard should persist loading state")

      let disabled = try services.runtimeDashboard.markLocalStatusDisabled(
        context: context, now: fixedDate("2026-01-01T00:00:02Z"))
      try expect(
        disabled.state == .disabled,
        "runtime dashboard should persist disabled local-status fallback")
      try expect(
        disabled.disabledReason?.contains("host-control") == true,
        "disabled state should name host-control exclusion")

      let harness = try services.data.upsertHarness(
        runtimeType: .hermes,
        displayName: "Hermes Agent",
        mode: .appManaged,
        config: [
          "lifecycleState": .string(HarnessLifecycleState.connected.rawValue),
          "modelAuthStatus": .string(HarnessModelAuthStatus.connected.rawValue),
          "installPath": .string(sensitivePath),
          "commandEnv": .object(["MODEL_AUTH_REFERENCE": .string("[REDACTED]")]),
        ]
      )
      let agent = try services.data.createAgent(
        workspaceId: workspace.id,
        name: "Runtime Dashboard Agent",
        harnessId: harness.id
      )
      let thread = try services.data.createThread(
        workspaceId: workspace.id, title: "Runtime Dashboard Thread", selectedAgentId: agent.id)
      let message = try services.data.createMessage(
        threadId: thread.id,
        senderType: .user,
        senderName: "You",
        content: "Runtime dashboard source message"
      )
      let session = try services.data.createRuntimeSession(
        threadId: thread.id, agentId: agent.id, runtimeBindingId: agent.binding.id)
      let dispatch = try services.data.createDispatch(
        threadId: thread.id,
        messageId: message.id,
        agentId: agent.id,
        harnessId: harness.id,
        sessionId: session.id,
        correlationId: "corr-runtime-dashboard-001",
        inputSnapshot: [
          "runtimeType": .string(RuntimeType.hermes.rawValue),
          "attempt": .number(1),
          "retrySourceMessageId": .string(message.id),
          "retryable": .bool(false),
        ]
      )
      _ = try services.data.updateDispatch(
        dispatchId: dispatch.id,
        status: .failed,
        errorSnapshot: [
          "message": .string("credential=runtime-dashboard-sensitive-001"),
          "retryable": .bool(true),
          "retrySafetyEvidenceId": .string("dispatch.retry.runtime-dashboard-001"),
          "runtimeType": .string(RuntimeType.hermes.rawValue),
          "attempt": .number(1),
        ]
      )
      _ = try services.data.log(
        severity: "warn",
        category: "runtime.dashboard",
        message: "Runtime dashboard source event.",
        dispatchId: dispatch.id,
        harnessId: harness.id,
        threadId: thread.id,
        detail: ["path": .string(sensitivePath)]
      )

      let retry = try services.runtimeDashboard.refreshSnapshot(
        context: context, now: fixedDate("2026-01-01T00:00:10Z"), staleAfterSeconds: 1)
      try expect(retry.state == .retry, "retryable failed dispatch should map to retry state")
      try expect(retry.rows.count == 1, "runtime dashboard should have one retained harness row")
      try expect(retry.runtimeRowCount == 1, "runtime dashboard should count retained runtime row")
      try expect(
        retry.connectedAppCount == 0, "runtime dashboard must not invent connected app rows")
      try expect(
        retry.rows[0].assignedAgents.map(\.agentId) == [agent.id],
        "runtime dashboard row should list assigned agent")
      try expect(
        retry.rows[0].retryableDispatchCount == 1,
        "runtime dashboard row should count retryable failure")
      try expect(
        retry.rows[0].latestDispatchId == dispatch.id,
        "runtime dashboard row should link latest dispatch")

      let stored = try services.database.all(
        "SELECT snapshot_json FROM runtime_dashboard_snapshots"
      )
      .compactMap { sqliteText($0["snapshot_json"]) }
      .joined(separator: "\n")
      let storedRows = try services.database.all("SELECT row_json FROM runtime_dashboard_rows")
        .compactMap { sqliteText($0["row_json"]) }
        .joined(separator: "\n")
      try expect(!stored.contains(sensitivePath), "snapshot JSON leaked private path")
      try expect(!storedRows.contains(sensitivePath), "row JSON leaked private path")
      try expect(
        !stored.contains("runtime-dashboard-sensitive-001"),
        "snapshot JSON leaked sensitive error text")
      try expect(
        !storedRows.contains("runtime-dashboard-sensitive-001"),
        "row JSON leaked sensitive error text")
    }

    let reopened = try makeServices(root: root)
    let stale = try unwrap(
      reopened.runtimeDashboard.latestSnapshot(
        context: Self.context(roles: [.owner], workspaceId: workspaceId),
        now: fixedDate("2026-01-01T00:00:20Z"),
        staleAfterSeconds: 1
      ),
      "missing persisted runtime dashboard snapshot after relaunch"
    )
    try expect(
      stale.state == .stale,
      "persisted runtime dashboard snapshot should surface stale state after relaunch")
    try expect(stale.retryAvailable, "stale runtime dashboard should expose retry availability")
    try expect(
      stale.connectedAppCount == 0, "reloaded snapshot must still not invent connected apps")
  }

  private static func testRuntimeActionRunsAreIdempotentReadOnlyAndRetained() throws {
    let root = FileManager.default.temporaryDirectory
      .appendingPathComponent("RelayConsoleRuntimeActionTests", isDirectory: true)
      .appendingPathComponent(UUID().uuidString, isDirectory: true)
    let sensitivePath = root.appendingPathComponent("runtime-action-private-root").path
    let workspaceId: String
    let context: ServiceRequestContext

    do {
      let services = try makeServices(root: root)
      let workspace = try unwrap(services.data.getAppState().activeWorkspace, "missing workspace")
      workspaceId = workspace.id
      context = Self.context(roles: [.owner], workspaceId: workspace.id)

      do {
        _ = try services.runtimeActions.refreshCapabilities(
          context: Self.context(roles: [.viewer], workspaceId: workspace.id))
        throw ServiceTestFailure("viewer unexpectedly read runtime action capabilities")
      } catch let denied as ServiceGuardResult {
        try expect(
          denied.reasonCode == .authorityRoleRequired,
          "viewer runtime action read should require workspace access")
      }

      let harness = try services.data.upsertHarness(
        runtimeType: .hermes,
        displayName: "Hermes Agent",
        mode: .appManaged,
        config: [
          "lifecycleState": .string(HarnessLifecycleState.connected.rawValue),
          "modelAuthStatus": .string(HarnessModelAuthStatus.connected.rawValue),
        ]
      )
      let agent = try services.data.createAgent(
        workspaceId: workspace.id,
        name: "Runtime Action Agent",
        harnessId: harness.id
      )
      let thread = try services.data.createThread(
        workspaceId: workspace.id, title: "Runtime Action Thread", selectedAgentId: agent.id)
      let message = try services.data.createMessage(
        threadId: thread.id,
        senderType: .user,
        senderName: "You",
        content: "Retry this retained runtime action source"
      )
      let session = try services.data.createRuntimeSession(
        threadId: thread.id, agentId: agent.id, runtimeBindingId: agent.binding.id)
      let dispatch = try services.data.createDispatch(
        threadId: thread.id,
        messageId: message.id,
        agentId: agent.id,
        harnessId: harness.id,
        sessionId: session.id,
        correlationId: "corr-runtime-action-001",
        inputSnapshot: [
          "runtimeType": .string(RuntimeType.hermes.rawValue),
          "attempt": .number(1),
          "retrySourceMessageId": .string(message.id),
          "retryable": .bool(false),
        ]
      )
      _ = try services.data.updateDispatch(
        dispatchId: dispatch.id,
        status: .failed,
        errorSnapshot: [
          "message": .string("credential=runtime-action-sensitive-001"),
          "retryable": .bool(true),
          "retrySafetyEvidenceId": .string("dispatch.retry.runtime-action-001"),
          "runtimeType": .string(RuntimeType.hermes.rawValue),
          "attempt": .number(1),
          "retrySourceMessageId": .string(message.id),
        ]
      )

      let capabilities = try services.runtimeActions.refreshCapabilities(
        context: context,
        dispatchId: dispatch.id,
        now: fixedDate("2026-01-01T00:00:00Z")
      )
      let retry = try unwrap(
        capabilities.first { $0.kind == .retryDispatch }, "missing retry action capability")
      let cancel = try unwrap(
        capabilities.first { $0.kind == .cancelDispatch }, "missing cancel action capability")
      let hostControl = try unwrap(
        capabilities.first { $0.kind == .hostControl }, "missing host-control exclusion capability")
      let localCommand = try unwrap(
        capabilities.first { $0.kind == .localAppCommand },
        "missing local command blocked capability")
      try expect(
        retry.availability == .available, "retry capability should be inspectable as available")
      try expect(
        retry.readOnly && !retry.executionSupported,
        "retry capability should not expose active write controls")
      try expect(
        cancel.availability == .cancelled,
        "terminal dispatch cancel capability should stay terminal")
      try expect(
        hostControl.availability == .unsupported, "host-control capability must stay unsupported")
      try expect(
        localCommand.availability == .destructiveBlocked,
        "destructive local commands must be blocked")

      let activeMessage = try services.data.createMessage(
        threadId: thread.id,
        senderType: .user,
        senderName: "You",
        content: "Active dispatch for missing capability"
      )
      let activeSession = try services.data.createRuntimeSession(
        threadId: thread.id, agentId: agent.id, runtimeBindingId: agent.binding.id)
      let activeDispatch = try services.data.createDispatch(
        threadId: thread.id,
        messageId: activeMessage.id,
        agentId: agent.id,
        harnessId: harness.id,
        sessionId: activeSession.id,
        correlationId: "corr-runtime-action-active-001",
        inputSnapshot: [
          "runtimeType": .string(RuntimeType.hermes.rawValue),
          "attempt": .number(1),
          "retrySourceMessageId": .string(activeMessage.id),
          "retryable": .bool(false),
        ]
      )
      let activeCapabilities = try services.runtimeActions.refreshCapabilities(
        context: context,
        dispatchId: activeDispatch.id,
        now: fixedDate("2026-01-01T00:00:00Z")
      )
      let activeCancel = try unwrap(
        activeCapabilities.first { $0.kind == .cancelDispatch },
        "missing active cancel action capability")
      try expect(
        activeCancel.availability == .missingCapability,
        "active cancel capability should require explicit runtime support")

      let dryRun = try services.runtimeActions.recordDryRun(
        context: context,
        kind: .retryDispatch,
        idempotencyKey: "runtime-action-retry-001",
        scopeType: .dispatch,
        runtimeType: .hermes,
        harnessId: harness.id,
        dispatchId: dispatch.id,
        agentId: agent.id,
        request: [
          "path": .string(sensitivePath),
          "commandEnv": .object(["credential": .string("credential=runtime-action-sensitive-001")]),
        ],
        now: fixedDate("2026-01-01T00:00:01Z")
      )
      let duplicate = try services.runtimeActions.recordDryRun(
        context: context,
        kind: .retryDispatch,
        idempotencyKey: "runtime-action-retry-001",
        scopeType: .dispatch,
        runtimeType: .hermes,
        harnessId: harness.id,
        dispatchId: dispatch.id,
        agentId: agent.id,
        request: ["path": .string("/tmp/runtime-action-duplicate")],
        now: fixedDate("2026-01-01T00:00:02Z")
      )
      try expect(
        duplicate.id == dryRun.id, "idempotency key should reuse the original dry-run record")
      try expect(!dryRun.executionAttempted, "dry run must not execute runtime action")

      _ = try services.runtimeActions.rejectUnsupported(
        context: context,
        kind: .hostControl,
        idempotencyKey: "runtime-action-host-control-001",
        scopeType: .workspace,
        message: RuntimeActionService.hostControlExclusionReason,
        now: fixedDate("2026-01-01T00:00:03Z")
      )
      _ = try services.runtimeActions.blockDestructive(
        context: context,
        kind: .localAppCommand,
        idempotencyKey: "runtime-action-local-command-001",
        scopeType: .workspace,
        message: "Local app command would be destructive.",
        now: fixedDate("2026-01-01T00:00:04Z")
      )
      _ = try services.runtimeActions.recordFailure(
        context: context,
        kind: .retryDispatch,
        idempotencyKey: "runtime-action-failure-001",
        scopeType: .dispatch,
        runtimeType: .hermes,
        harnessId: harness.id,
        dispatchId: dispatch.id,
        agentId: agent.id,
        message: "credential=runtime-action-sensitive-001 \(sensitivePath)",
        now: fixedDate("2026-01-01T00:00:05Z")
      )

      let runs = try services.runtimeActions.listRuns(context: context, limit: 10)
      try expect(runs.count == 4, "duplicate idempotency key should not create an extra action run")
      try expect(
        Set(runs.map(\.status)).isSuperset(of: [.dryRun, .unsupported, .rejected, .failed]),
        "action-run statuses should cover dry-run, unsupported, rejected, and failed")
      try expect(
        runs.allSatisfy { !$0.executionAttempted }, "ITC-0030 action runs must not execute commands"
      )

      let stored = try services.database.all(
        "SELECT action_run_json, request_json, failure_json FROM runtime_action_runs"
      )
      .flatMap { row in
        [
          sqliteText(row["action_run_json"]),
          sqliteText(row["request_json"]),
          sqliteText(row["failure_json"]),
        ].compactMap { $0 }
      }
      .joined(separator: "\n")
      try expect(!stored.contains(sensitivePath), "action-run storage leaked private path")
      try expect(
        !stored.contains("runtime-action-sensitive-001"),
        "action-run storage leaked sensitive command text")

      let trimmed = try services.runtimeActions.trimHistory(context: context, keepLatest: 2)
      try expect(trimmed == 2, "runtime action history should trim older rows")
      try expect(
        try services.runtimeActions.listRuns(context: context, limit: 10).count == 2,
        "runtime action history should retain only the latest rows")
    }

    let reopened = try makeServices(root: root)
    let recovered = try reopened.runtimeActions.listRuns(
      context: Self.context(roles: [.owner], workspaceId: workspaceId),
      limit: 10
    )
    try expect(recovered.count == 2, "terminal action-run history should survive relaunch")
    try expect(
      recovered.allSatisfy { !$0.executionAttempted },
      "relaunch must not execute retained action runs")
    try expect(
      recovered.allSatisfy { [.failed, .rejected].contains($0.status) },
      "relaunch should preserve terminal retained statuses")
  }

  private static func testRuntimeRecoveryRecordsAreInspectableRedactedAndEvented() throws {
    let root = FileManager.default.temporaryDirectory
      .appendingPathComponent("RelayConsoleRuntimeRecoveryTests", isDirectory: true)
      .appendingPathComponent(UUID().uuidString, isDirectory: true)
    let sensitivePath = root.appendingPathComponent("runtime-recovery-private-root").path
    let workspaceId: String

    do {
      let services = try makeServices(root: root)
      let workspace = try unwrap(services.data.getAppState().activeWorkspace, "missing workspace")
      workspaceId = workspace.id
      let context = Self.context(roles: [.owner], workspaceId: workspace.id)
      let structuredJobEvents = EventCounter()
      let missingToolEvents = EventCounter()
      let recoveryEvents = EventCounter()
      _ = services.eventBus.on(.runtimeStructuredJobUpdated) { _ in structuredJobEvents.increment()
      }
      _ = services.eventBus.on(.runtimeMissingToolUpdated) { _ in missingToolEvents.increment() }
      _ = services.eventBus.on(.runtimeRecoveryUpdated) { _ in recoveryEvents.increment() }

      do {
        _ = try services.runtimeRecovery.structuredJobs(
          context: Self.context(roles: [.viewer], workspaceId: workspace.id))
        throw ServiceTestFailure("viewer unexpectedly read runtime recovery records")
      } catch let denied as ServiceGuardResult {
        try expect(
          denied.reasonCode == .authorityRoleRequired,
          "viewer recovery read should require workspace access")
      }

      let harness = try services.data.upsertHarness(
        runtimeType: .hermes, displayName: "Hermes Agent", mode: .appManaged, config: [:])
      let agent = try services.data.createAgent(
        workspaceId: workspace.id, name: "Runtime Recovery Agent", harnessId: harness.id)
      let thread = try services.data.createThread(
        workspaceId: workspace.id, title: "Runtime Recovery Thread", selectedAgentId: agent.id)
      let message = try services.data.createMessage(
        threadId: thread.id, senderType: .user, senderName: "You",
        content: "Runtime recovery source")
      let session = try services.data.createRuntimeSession(
        threadId: thread.id, agentId: agent.id, runtimeBindingId: agent.binding.id)
      let dispatch = try services.data.createDispatch(
        threadId: thread.id,
        messageId: message.id,
        agentId: agent.id,
        harnessId: harness.id,
        sessionId: session.id,
        correlationId: "corr-runtime-recovery-001",
        inputSnapshot: ["runtimeType": .string(RuntimeType.hermes.rawValue), "attempt": .number(1)]
      )
      let contextUsage = RuntimeRecoveryService.contextUsage(
        dispatchId: dispatch.id,
        percentUsed: 0.72,
        tokenCount: 7200,
        maxTokens: 10000,
        level: "warning",
        isEstimate: true,
        referencesCount: 3
      )
      let health = RuntimeRecoveryService.participantHealth(
        agentId: agent.id,
        runtimeType: .hermes,
        status: .degraded,
        message: "credential=runtime-recovery-sensitive-001",
        updatedAt: "2026-01-01T00:00:00Z"
      )

      _ = try services.runtimeRecovery.recordStructuredJob(
        context: context, jobType: "tool_recovery", status: .queued, title: "Queued recovery",
        dispatchId: dispatch.id, now: fixedDate("2026-01-01T00:00:00Z"))
      _ = try services.runtimeRecovery.recordStructuredJob(
        context: context, jobType: "tool_recovery", status: .running, title: "Running recovery",
        dispatchId: dispatch.id, now: fixedDate("2026-01-01T00:00:01Z"))
      _ = try services.runtimeRecovery.recordStructuredJob(
        context: context, jobType: "tool_recovery", status: .completed, title: "Completed recovery",
        dispatchId: dispatch.id, retryable: false, contextUsage: contextUsage,
        participantHealth: [health], now: fixedDate("2026-01-01T00:00:02Z"))
      let failedJob = try services.runtimeRecovery.recordStructuredJob(
        context: context,
        jobType: "missing_tool",
        status: .failed,
        title: "Failed recovery",
        dispatchId: dispatch.id,
        retryable: true,
        contextUsage: contextUsage,
        participantHealth: [health],
        followUpFailure: [
          "message": .string("credential=runtime-recovery-sensitive-001"),
          "path": .string(sensitivePath),
        ],
        recovery: ["sourceHostPath": .string(sensitivePath)],
        metadata: [
          "commandEnv": .object(["credential": .string("credential=runtime-recovery-sensitive-001")]
          )
        ],
        now: fixedDate("2026-01-01T00:00:03Z")
      )
      let missingTool = try services.runtimeRecovery.recordMissingTool(
        context: context,
        toolName: "calendar.search",
        status: .requested,
        dispatchId: dispatch.id,
        agentId: agent.id,
        request: [
          "path": .string(sensitivePath),
          "credential": .string("credential=runtime-recovery-sensitive-001"),
        ],
        now: fixedDate("2026-01-01T00:00:04Z")
      )
      _ = try services.runtimeRecovery.recordRecovery(
        context: context,
        state: .retryable,
        retryable: true,
        reasonCode: .errorRetryable,
        message: "Recovery can retry after missing tool approval.",
        dispatchId: dispatch.id,
        jobId: failedJob.id,
        followUpAction: "request_tool",
        recovery: ["path": .string(sensitivePath)],
        now: fixedDate("2026-01-01T00:00:05Z")
      )
      _ = try services.runtimeRecovery.recordRecovery(
        context: context,
        state: .terminal,
        retryable: false,
        reasonCode: .errorTerminal,
        message: "credential=runtime-recovery-sensitive-001",
        dispatchId: dispatch.id,
        jobId: failedJob.id,
        followUpAction: nil,
        recovery: ["sourceHostExcluded": .bool(true)],
        now: fixedDate("2026-01-01T00:00:06Z")
      )

      let jobs = try services.runtimeRecovery.structuredJobs(context: context)
      let tools = try services.runtimeRecovery.missingTools(context: context)
      let recoveries = try services.runtimeRecovery.recoveryRecords(context: context)
      try expect(
        Set(jobs.map(\.status)).isSuperset(of: [.queued, .running, .completed, .failed]),
        "structured jobs should cover all required states")
      try expect(
        jobs.allSatisfy(\.sourceHostExcluded), "structured jobs must preserve source-host exclusion"
      )
      try expect(
        missingTool.autoInstallAttempted == false && missingTool.fakeGrantCreated == false,
        "missing tool must not auto-install or fake grants")
      try expect(
        tools.count == 1 && tools[0].status == .requested,
        "missing tool request should be inspectable")
      try expect(
        recoveries.contains { $0.retryable && $0.state == .retryable },
        "retryable recovery record missing")
      try expect(
        recoveries.contains { !$0.retryable && $0.state == .terminal },
        "terminal non-retryable recovery record missing")
      try expect(structuredJobEvents.value == 4, "structured-job typed events should publish")
      try expect(missingToolEvents.value == 1, "missing-tool typed event should publish")
      try expect(recoveryEvents.value == 2, "recovery typed events should publish")

      let stored = try services.database.all(
        "SELECT structured_job_json FROM runtime_structured_jobs UNION ALL SELECT missing_tool_json FROM runtime_missing_tool_events UNION ALL SELECT recovery_record_json FROM runtime_recovery_records"
      )
      .compactMap {
        sqliteText($0["structured_job_json"]) ?? sqliteText($0["missing_tool_json"])
          ?? sqliteText($0["recovery_record_json"])
      }
      .joined(separator: "\n")
      try expect(!stored.contains(sensitivePath), "runtime recovery storage leaked private path")
      try expect(
        !stored.contains("runtime-recovery-sensitive-001"),
        "runtime recovery storage leaked sensitive text")
    }

    let reopened = try makeServices(root: root)
    let context = Self.context(roles: [.owner], workspaceId: workspaceId)
    try expect(
      try reopened.runtimeRecovery.structuredJobs(context: context).count == 4,
      "structured jobs should survive relaunch")
    try expect(
      try reopened.runtimeRecovery.missingTools(context: context).allSatisfy {
        !$0.autoInstallAttempted && !$0.fakeGrantCreated
      }, "missing tools should relaunch without fake grants")
    try expect(
      try reopened.runtimeRecovery.recoveryRecords(context: context).allSatisfy(
        \.sourceHostExcluded), "recovery records should retain source-host exclusion")
  }

  private static func testHermesContextUsageMapperUsesGatewayContextFieldsOnly() throws {
    let mapped = try unwrap(
      RuntimeContextUsageMapper.hermesContextUsage(
        from: [
          "model": .string("gpt-5-test"),
          "context_percent": .number(25),
          "context_used": .number(50_000),
          "context_max": .number(200_000),
          "calls": .number(3),
          "total": .number(150_000),
          "prompt": .number(120_000),
          "output": .number(30_000),
        ],
        dispatchId: "rtd-hermes-context-test",
        source: "unit_test"
      ),
      "Hermes usage with context fields should map to a runtime context record"
    )
    guard case .number(let percent)? = mapped["percentUsed"] else {
      throw ServiceTestFailure("mapped Hermes usage should include percentUsed")
    }
    guard case .number(let tokenCount)? = mapped["tokenCount"] else {
      throw ServiceTestFailure("mapped Hermes usage should include tokenCount")
    }
    guard case .number(let maxTokens)? = mapped["maxTokens"] else {
      throw ServiceTestFailure("mapped Hermes usage should include maxTokens")
    }
    guard case .bool(let isEstimate)? = mapped["isEstimate"] else {
      throw ServiceTestFailure("mapped Hermes usage should include isEstimate")
    }
    guard case .string(let source)? = mapped["source"] else {
      throw ServiceTestFailure("mapped Hermes usage should include source")
    }

    try expect(percent == 25, "Hermes context_percent should become percentUsed")
    try expect(tokenCount == 50_000, "Hermes context_used should become tokenCount")
    try expect(maxTokens == 200_000, "Hermes context_max should become maxTokens")
    try expect(!isEstimate, "Hermes context fields should be treated as gateway-reported usage")
    try expect(source == "unit_test", "Hermes context mapper should preserve source")

    let sessionTotalsOnly = RuntimeContextUsageMapper.hermesContextUsage(
      from: [
        "model": .string("gpt-5-test"),
        "prompt": .number(120_000),
        "total": .number(150_000),
        "calls": .number(3),
      ],
      dispatchId: "rtd-hermes-context-test",
      source: "unit_test"
    )
    try expect(
      sessionTotalsOnly == nil, "session totals alone should not masquerade as context usage")
  }

  private static func testWorkSafetyTaskAndApprovalRecordsAreDurableRedactedAndInert() throws {
    let root = FileManager.default.temporaryDirectory
      .appendingPathComponent("RelayConsoleWorkSafetyTests", isDirectory: true)
      .appendingPathComponent(UUID().uuidString, isDirectory: true)
    let workspaceId: String
    let taskId = "task-work-safety-001"
    let runId = "task-run-work-safety-001"
    let approvalId = "approval-work-safety-001"
    let stepId = "approval-step-work-safety-001"
    let noteId = "approval-note-work-safety-001"
    let sensitivePath = "/private/tmp/work-safety-sensitive-value"

    do {
      let services = try makeServices(root: root)
      let workspace = try unwrap(services.data.getAppState().activeWorkspace, "missing workspace")
      workspaceId = workspace.id
      let owner = Self.context(
        roles: [.owner], workspaceId: workspace.id, correlationId: "work-safety-owner-001")
      let taskEvents = EventCounter()
      let approvalEvents = EventCounter()
      let taskSubscription = services.eventBus.on(.workSafetyTaskUpdated) { _ in
        taskEvents.increment()
      }
      let approvalSubscription = services.eventBus.on(.workSafetyApprovalUpdated) { _ in
        approvalEvents.increment()
      }
      defer {
        services.eventBus.off(.workSafetyTaskUpdated, id: taskSubscription)
        services.eventBus.off(.workSafetyApprovalUpdated, id: approvalSubscription)
      }

      let agent = try createServiceAgent(services: services, workspaceId: workspace.id)
      let thread = try services.data.createThread(
        workspaceId: workspace.id,
        title: "Work Safety Thread",
        selectedAgentId: agent.id,
        threadType: .direct
      )
      let references = WorkSafetyLinkedReferences(
        actionRunId: nil,
        dispatchId: nil,
        structuredJobId: nil,
        sourceHostRecordId: sensitivePath,
        scheduledMessageId: "scheduled-message-001"
      )

      let task = try services.data.saveWorkSafetyTask(
        WorkSafetyTaskRecord(
          id: taskId,
          workspaceId: workspace.id,
          title: "Review high-risk task",
          message: "Await approval for credential=work-safety-sensitive-value \(sensitivePath)",
          status: .blockedByApproval,
          targetType: .agent,
          targetId: agent.id,
          assignedAgentId: agent.id,
          threadId: thread.id,
          runtimeBindingId: agent.binding.id,
          linkedReferences: references,
          approvalRequired: true,
          approvalId: approvalId,
          scheduledAt: "2026-01-01T00:05:00Z",
          recurrenceRule: "FREQ=DAILY;X-PATH=\(sensitivePath)",
          priority: 50,
          riskLevel: .high,
          metadata: [
            "transportStatus": .string("blocked-by-approval"),
            "webStatusVocabulary": .string("pending"),
            "sourceHostPath": .string(sensitivePath),
            "credential": .string("credential=work-safety-sensitive-value"),
          ],
          createdAt: "2026-01-01T00:00:00Z",
          updatedAt: "2026-01-01T00:01:00Z",
          completedAt: nil,
          redactionStatus: "unreviewed"
        )
      )
      try expect(
        task.message?.contains("[REDACTED]") == true, "task message should redact private state")
      try expect(
        task.linkedReferences.sourceHostRecordId == "[REDACTED]",
        "task source-host reference should redact")
      try expect(
        task.redactionStatus == "private-state-excluded", "task should mark private-state exclusion"
      )

      let run = try services.data.saveWorkSafetyTaskRun(
        WorkSafetyTaskRunRecord(
          id: runId,
          workspaceId: workspace.id,
          taskId: taskId,
          status: .blockedByApproval,
          linkedReferences: references,
          attempt: 1,
          startedAt: nil,
          completedAt: nil,
          failureMessage: "blocked until token=work-safety-sensitive-value at \(sensitivePath)",
          metadata: [
            "dispatchState": .string("blocked-by-approval"),
            "sourceHostPath": .string(sensitivePath),
          ],
          createdAt: "2026-01-01T00:02:00Z",
          updatedAt: "2026-01-01T00:03:00Z",
          redactionStatus: "unreviewed"
        )
      )
      try expect(
        run.failureMessage?.contains("[REDACTED]") == true,
        "task run failure should redact private state")

      let step = WorkSafetyApprovalStepRecord(
        id: stepId,
        workspaceId: workspace.id,
        approvalId: approvalId,
        label: "Review requested credential",
        value: "token=work-safety-sensitive-value \(sensitivePath)",
        status: .pending,
        sortIndex: 0,
        redactionStatus: "unreviewed"
      )
      let note = WorkSafetyApprovalNoteRecord(
        id: noteId,
        workspaceId: workspace.id,
        approvalId: approvalId,
        authorAgentId: agent.id,
        note: "Do not execute until manual approval reviews \(sensitivePath)",
        createdAt: "2026-01-01T00:04:00Z",
        redactionStatus: "unreviewed"
      )
      let approval = try services.data.saveWorkSafetyApproval(
        WorkSafetyApprovalRecord(
          id: approvalId,
          workspaceId: workspace.id,
          taskId: taskId,
          title: "Approval required for high-risk task",
          description:
            "Review credential=work-safety-sensitive-value before dispatching \(sensitivePath)",
          status: .pending,
          riskLevel: .high,
          requestedByAgentId: agent.id,
          resolverAgentId: nil,
          expiresAt: "2026-01-02T00:00:00Z",
          resolvedAt: nil,
          steps: [step],
          notes: [note],
          metadata: [
            "requiredState": .string("pending"),
            "path": .string(sensitivePath),
            "credential": .string("token=work-safety-sensitive-value"),
          ],
          createdAt: "2026-01-01T00:04:00Z",
          updatedAt: "2026-01-01T00:04:30Z",
          redactionStatus: "unreviewed"
        )
      )
      try expect(
        approval.description?.contains("[REDACTED]") == true,
        "approval description should redact private state")
      try expect(
        approval.steps.first?.value?.contains("[REDACTED]") == true,
        "approval step value should redact private state")
      try expect(
        approval.notes.first?.note.contains("[REDACTED]") == true,
        "approval note should redact private state")

      let event = try services.data.saveWorkSafetyTaskEvent(
        WorkSafetyTaskEventRecord(
          id: "task-event-work-safety-001",
          workspaceId: workspace.id,
          taskId: taskId,
          runId: runId,
          approvalId: approvalId,
          eventType: .approvalRequested,
          status: WorkSafetyTaskStatus.blockedByApproval.rawValue,
          detail: [
            "source": .string("migration-foundation-test"),
            "path": .string(sensitivePath),
            "credential": .string("token=work-safety-sensitive-value"),
          ],
          occurredAt: "2026-01-01T00:05:00Z",
          redactionStatus: "unreviewed"
        )
      )
      try expect(
        event.detail["path"]?.string == "[REDACTED]",
        "task event detail should redact private state")
      try expect(
        try services.runtimeActions.listRuns(context: owner).isEmpty,
        "task and approval foundations must not execute runtime actions")

      let stored = try services.database.all(
        """
        SELECT task_json AS value FROM work_safety_tasks
        UNION ALL SELECT run_json AS value FROM work_safety_task_runs
        UNION ALL SELECT event_json AS value FROM work_safety_task_events
        UNION ALL SELECT approval_json AS value FROM work_safety_approvals
        UNION ALL SELECT step_json AS value FROM work_safety_approval_steps
        UNION ALL SELECT note_json AS value FROM work_safety_approval_notes
        """
      ).compactMap { sqliteText($0["value"]) }.joined(separator: "\n")
      try expect(
        !stored.contains(sensitivePath), "work-safety storage leaked private source-host path")
      try expect(
        !stored.contains("work-safety-sensitive-value"), "work-safety storage leaked sensitive text"
      )
      try expect(
        stored.contains("[REDACTED]"), "work-safety storage should retain redaction sentinel")
      try expect(
        taskEvents.value >= 3,
        "work-safety task events should publish for task run and event records")
      try expect(
        approvalEvents.value >= 3,
        "work-safety approval events should publish for approval step note and record")
    }

    let reopened = try makeServices(root: root)
    let context = Self.context(roles: [.owner], workspaceId: workspaceId)
    let tasks = try reopened.data.listWorkSafetyTasks(workspaceId: workspaceId)
    let runs = try reopened.data.listWorkSafetyTaskRuns(workspaceId: workspaceId, taskId: taskId)
    let events = try reopened.data.listWorkSafetyTaskEvents(
      workspaceId: workspaceId, taskId: taskId)
    let approvals = try reopened.data.listWorkSafetyApprovals(
      workspaceId: workspaceId, taskId: taskId)
    let steps = try reopened.data.listWorkSafetyApprovalSteps(
      workspaceId: workspaceId, approvalId: approvalId)
    let notes = try reopened.data.listWorkSafetyApprovalNotes(
      workspaceId: workspaceId, approvalId: approvalId)
    try expect(
      tasks.count == 1 && tasks[0].status == .blockedByApproval,
      "work-safety task should survive relaunch")
    try expect(
      runs.count == 1 && runs[0].status == .blockedByApproval,
      "work-safety task run should survive relaunch")
    try expect(
      events.count == 1 && events[0].eventType == .approvalRequested,
      "work-safety task event should survive relaunch")
    try expect(
      approvals.count == 1 && approvals[0].status == .pending,
      "work-safety approval should survive relaunch")
    try expect(
      steps.count == 1 && steps[0].value?.contains("[REDACTED]") == true,
      "work-safety approval step should relaunch redacted")
    try expect(
      notes.count == 1 && notes[0].note.contains("[REDACTED]"),
      "work-safety approval note should relaunch redacted")
    try expect(
      try reopened.runtimeActions.listRuns(context: context).isEmpty,
      "relaunch should not synthesize runtime action runs")
  }

  private static func testWorkSafetyTaskServiceResolvesTargetsSchedulesAndGuardsAuthority() throws {
    let services = try makeServices()
    let workspace = try unwrap(services.data.getAppState().activeWorkspace, "missing workspace")
    let owner = Self.context(
      roles: [.owner], workspaceId: workspace.id, correlationId: "work-safety-target-owner-001")
    let member = Self.context(
      roles: [.member], workspaceId: workspace.id, correlationId: "work-safety-target-member-001")
    let lead = try createServiceAgent(services: services, workspaceId: workspace.id)
    let peer = try createServiceAgent(services: services, workspaceId: workspace.id)
    let company = try services.data.createAgentOrgCompany(
      workspaceId: workspace.id, name: "Work Safety Co")
    let department = try services.data.createAgentOrgDepartment(
      workspaceId: workspace.id,
      companyId: company.id,
      name: "Operations",
      headAgentId: lead.id
    )
    let team = try services.data.createAgentOrgTeam(
      workspaceId: workspace.id,
      departmentId: department.id,
      name: "Dispatch",
      leadAgentId: lead.id
    )
    _ = try services.data.updateAgentOrgPlacement(
      agentId: lead.id,
      groupType: .business,
      familyLabel: nil,
      companyId: company.id,
      departmentId: department.id,
      teamId: team.id,
      managerAgentId: nil,
      classification: "operator"
    )
    _ = try services.data.updateAgentOrgPlacement(
      agentId: peer.id,
      groupType: .business,
      familyLabel: nil,
      companyId: company.id,
      departmentId: department.id,
      teamId: team.id,
      managerAgentId: nil,
      classification: "reviewer"
    )

    do {
      _ = try services.workSafetyTasks.createTask(
        context: member,
        request: WorkSafetyTaskServiceRequest(
          title: "Member mutation",
          targetType: .agent,
          targetId: lead.id
        )
      )
      throw ServiceTestFailure("member task creation unexpectedly succeeded")
    } catch let denied as ServiceGuardResult {
      try expect(
        denied.reasonCode == .authorityRoleRequired, "member task create should require owner/admin"
      )
    }
    try expect(
      try services.data.listWorkSafetyTasks(workspaceId: workspace.id).isEmpty,
      "denied task create should not persist rows")

    let direct = try services.workSafetyTasks.createTask(
      context: owner,
      request: WorkSafetyTaskServiceRequest(
        title: "Scheduled direct task",
        message: "Run retained direct task",
        targetType: .agent,
        targetId: lead.id,
        scheduledAt: "2026-01-02T10:00:00Z",
        recurrenceRule: "FREQ=DAILY",
        priority: 10,
        riskLevel: .medium
      ),
      now: fixedDate("2026-01-01T00:00:00Z")
    )
    try expect(direct.status == .queued, "direct task should start queued")
    try expect(direct.assignedAgentId == lead.id, "direct task should assign target agent")
    try expect(
      direct.runtimeBindingId == lead.binding.id, "direct task should link target runtime binding")
    try expect(
      direct.linkedReferences.scheduledMessageId != nil,
      "scheduled direct task should record scheduled-message reference")
    try expect(direct.recurrenceRule == "FREQ=DAILY", "direct task should retain recurrence")
    try expect(
      try services.data.getThread(try unwrap(direct.threadId, "missing direct task thread"))
        .threadType == .direct, "direct task should create direct thread")

    let teamTask = try services.workSafetyTasks.createTask(
      context: owner,
      request: WorkSafetyTaskServiceRequest(
        title: "Team task",
        targetType: .team,
        targetId: team.id
      )
    )
    try expect(teamTask.assignedAgentId == lead.id, "team task should pick team lead")
    try expect(
      try services.data.getThread(try unwrap(teamTask.threadId, "missing team task thread"))
        .threadType == .team, "team task should create team thread")

    let departmentTask = try services.workSafetyTasks.createTask(
      context: owner,
      request: WorkSafetyTaskServiceRequest(
        title: "Department task",
        targetType: .department,
        targetId: department.id
      )
    )
    try expect(
      departmentTask.assignedAgentId == lead.id, "department task should pick department head")
    try expect(
      try services.data.getThread(
        try unwrap(departmentTask.threadId, "missing department task thread")
      ).threadType == .direct, "department task should link a supported direct thread")

    let pairTask = try services.workSafetyTasks.createTask(
      context: owner,
      request: WorkSafetyTaskServiceRequest(
        title: "Agent pair task",
        targetType: .agentToAgent,
        targetId: peer.id,
        assignedAgentId: lead.id
      )
    )
    try expect(
      pairTask.assignedAgentId == lead.id && pairTask.targetId == peer.id,
      "agent-to-agent task should preserve pair ids")
    try expect(
      try services.data.getThread(try unwrap(pairTask.threadId, "missing pair task thread"))
        .threadType == .direct, "agent-to-agent task should link a supported direct thread")

    let updated = try services.workSafetyTasks.updateSchedule(
      context: owner,
      taskId: direct.id,
      scheduledAt: "2026-01-03T11:30:00Z",
      recurrenceRule: "FREQ=WEEKLY",
      now: fixedDate("2026-01-01T00:05:00Z")
    )
    try expect(updated.status == .queued, "schedule update should requeue task")
    try expect(
      updated.scheduledAt == "2026-01-03T11:30:00Z", "schedule update should persist next time")
    try expect(updated.recurrenceRule == "FREQ=WEEKLY", "schedule update should persist recurrence")

    do {
      _ = try services.workSafetyTasks.createTask(
        context: owner,
        request: WorkSafetyTaskServiceRequest(
          title: "Unsupported target",
          targetType: .runtimeBinding,
          targetId: lead.binding.id
        )
      )
      throw ServiceTestFailure("unsupported target unexpectedly persisted")
    } catch let denied as ServiceGuardResult {
      try expect(
        denied.reasonCode == .featureUnavailable,
        "unsupported runtime-binding target should be unavailable")
    }
    try expect(
      try services.runtimeActions.listRuns(context: owner).isEmpty,
      "task service target resolution should not execute runtime actions")
  }

  private static func testWorkSafetyApprovalGatesBlockDispatchAfterRelaunchAndKeepRunsInert() throws
  {
    let root = FileManager.default.temporaryDirectory
      .appendingPathComponent("RelayConsoleWorkSafetyTaskServiceTests", isDirectory: true)
      .appendingPathComponent(UUID().uuidString, isDirectory: true)
    let workspaceId: String
    let taskId: RelayId
    let approvalId: RelayId
    let approverAgentId: RelayId
    let sensitivePath = "/private/tmp/work-safety-task-service-sensitive-value"

    do {
      let services = try makeServices(root: root)
      let workspace = try unwrap(services.data.getAppState().activeWorkspace, "missing workspace")
      workspaceId = workspace.id
      let owner = Self.context(
        roles: [.owner], workspaceId: workspace.id, correlationId: "work-safety-gate-owner-001")
      let agent = try createServiceAgent(services: services, workspaceId: workspace.id)
      approverAgentId = agent.id
      let taskEvents = EventCounter()
      let approvalEvents = EventCounter()
      let taskSubscription = services.eventBus.on(.workSafetyTaskUpdated) { _ in
        taskEvents.increment()
      }
      let approvalSubscription = services.eventBus.on(.workSafetyApprovalUpdated) { _ in
        approvalEvents.increment()
      }
      defer {
        services.eventBus.off(.workSafetyTaskUpdated, id: taskSubscription)
        services.eventBus.off(.workSafetyApprovalUpdated, id: approvalSubscription)
      }

      let task = try services.workSafetyTasks.createTask(
        context: owner,
        request: WorkSafetyTaskServiceRequest(
          title: "Approval-gated task",
          message: "Dispatch only after approval.",
          targetType: .agent,
          targetId: agent.id,
          approvalRequired: true,
          scheduledAt: "2026-01-02T10:00:00Z",
          riskLevel: .high,
          metadata: ["sourceHostPath": .string(sensitivePath)]
        ),
        now: fixedDate("2026-01-01T00:00:00Z")
      )
      taskId = task.id
      approvalId = try unwrap(task.approvalId, "approval-required task should link approval")
      try expect(task.status == .blockedByApproval, "approval-required task should start blocked")
      try expect(
        try services.data.listWorkSafetyApprovals(workspaceId: workspace.id, taskId: task.id).count
          == 1, "approval-required task should create open approval")

      do {
        _ = try services.workSafetyTasks.dispatchTask(
          context: owner,
          taskId: task.id,
          denialDetail: [
            "path": .string(sensitivePath),
            "credential": .string("token=work-safety-task-service-sensitive-value"),
          ],
          now: fixedDate("2026-01-01T00:01:00Z")
        )
        throw ServiceTestFailure("approval-required dispatch unexpectedly succeeded")
      } catch let denied as ServiceGuardResult {
        try expect(
          denied.stateKind == .approvalRequired, "dispatch should return approval-required state")
        try expect(
          denied.reasonCode == .approvalRequired, "dispatch should return approval-required reason")
        try expect(denied.decisionId == approvalId, "dispatch denial should link approval id")
      }

      let blockedRuns = try services.workSafetyTasks.listRuns(context: owner, taskId: task.id)
      let blockedEvents = try services.workSafetyTasks.listEvents(context: owner, taskId: task.id)
      try expect(
        blockedRuns.count == 1 && blockedRuns[0].status == .blockedByApproval,
        "blocked dispatch should record one blocked run")
      try expect(
        blockedEvents.contains {
          $0.eventType == .approvalRequested && $0.detail["path"]?.string == "[REDACTED]"
        }, "blocked dispatch should record redacted denial event")
      try expect(
        try services.runtimeActions.listRuns(context: owner).isEmpty,
        "blocked dispatch should not create runtime action rows")
      try expect(taskEvents.value >= 4, "task service should publish task update events")
      try expect(approvalEvents.value >= 2, "task service should publish approval update events")
    }

    do {
      let reopened = try makeServices(root: root)
      let owner = Self.context(
        roles: [.owner], workspaceId: workspaceId, correlationId: "work-safety-gate-relaunch-001")
      do {
        _ = try reopened.workSafetyTasks.dispatchTask(
          context: owner,
          taskId: taskId,
          denialDetail: [
            "path": .string(sensitivePath),
            "credential": .string("token=work-safety-task-service-sensitive-value"),
          ],
          now: fixedDate("2026-01-01T00:02:00Z")
        )
        throw ServiceTestFailure("relaunch approval-required dispatch unexpectedly succeeded")
      } catch let denied as ServiceGuardResult {
        try expect(
          denied.reasonCode == .approvalRequired, "relaunch dispatch should preserve approval block"
        )
      }
      try expect(
        try reopened.workSafetyTasks.listRuns(context: owner, taskId: taskId).count == 1,
        "relaunch blocked dispatch should reuse blocked run")
      let storedEvents = try reopened.database.all(
        "SELECT event_json AS value FROM work_safety_task_events"
      )
      .compactMap { sqliteText($0["value"]) }
      .joined(separator: "\n")
      try expect(
        !storedEvents.contains(sensitivePath), "work-safety event storage leaked private path")
      try expect(
        !storedEvents.contains("work-safety-task-service-sensitive-value"),
        "work-safety event storage leaked sensitive text")

      var approval = try reopened.data.getWorkSafetyApproval(approvalId)
      approval.status = .approved
      approval.resolverAgentId = approverAgentId
      approval.resolvedAt = "2026-01-01T00:03:00Z"
      approval.updatedAt = "2026-01-01T00:03:00Z"
      _ = try reopened.data.saveWorkSafetyApproval(approval)

      let dispatch = try reopened.workSafetyTasks.dispatchTask(
        context: owner,
        taskId: taskId,
        now: fixedDate("2026-01-01T00:04:00Z")
      )
      try expect(
        dispatch.task.status == .dispatched, "approved task should record dispatched state")
      try expect(dispatch.run.status == .dispatched, "approved task should record dispatched run")
      try expect(
        try reopened.runtimeActions.listRuns(context: owner).isEmpty,
        "approved task dispatch should remain retained-service-only")

      let cancelled = try reopened.workSafetyTasks.cancelTask(
        context: owner,
        taskId: taskId,
        now: fixedDate("2026-01-01T00:05:00Z")
      )
      try expect(cancelled.task.status == .cancelled, "cancel should set terminal cancelled state")
      try expect(cancelled.run.status == .cancelled, "cancel should record cancelled run")
      let retried = try reopened.workSafetyTasks.retryTask(
        context: owner,
        taskId: taskId,
        now: fixedDate("2026-01-01T00:06:00Z")
      )
      try expect(retried.status == .queued, "approved cancelled task should retry to queued")
      let runs = try reopened.workSafetyTasks.listRuns(context: owner, taskId: taskId)
      try expect(
        runs.filter { $0.status == .dispatched }.count == 1,
        "retry should not duplicate dispatched run")
      try expect(
        runs.filter { $0.status == .cancelled }.count == 1,
        "retry should not duplicate cancelled run")
    }
  }

  private static func testWorkSafetyApprovalDecisionsAreAuthorityCheckedAndTransitionLinkedTasks()
    throws
  {
    let root = FileManager.default.temporaryDirectory
      .appendingPathComponent("RelayConsoleWorkSafetyApprovalDecisionTests", isDirectory: true)
      .appendingPathComponent(UUID().uuidString, isDirectory: true)
    let services = try makeServices(root: root)
    let workspace = try unwrap(services.data.getAppState().activeWorkspace, "missing workspace")
    let owner = ServiceRequestContext(
      actorId: "usr-owner-approval-001",
      workspaceId: workspace.id,
      roles: [.owner],
      correlationId: "work-safety-decision-owner-001"
    )
    let admin = ServiceRequestContext(
      actorId: "usr-admin-approval-001",
      workspaceId: workspace.id,
      roles: [.admin],
      correlationId: "work-safety-decision-admin-001"
    )
    let member = ServiceRequestContext(
      actorId: "usr-member-approval-001",
      workspaceId: workspace.id,
      roles: [.member],
      correlationId: "work-safety-decision-member-001"
    )
    let approver = ServiceRequestContext(
      actorId: "usr-approver-approval-001",
      workspaceId: workspace.id,
      roles: [.approver],
      correlationId: "work-safety-decision-approver-001"
    )
    let otherWorkspace = try services.data.createWorkspace(
      profileId: try unwrap(services.data.getActiveProfile(), "missing profile").id,
      name: "Other Approval Workspace",
      defaultFolderPath: nil
    )
    let crossWorkspace = ServiceRequestContext(
      actorId: "usr-owner-approval-001",
      workspaceId: otherWorkspace.id,
      roles: [.owner],
      correlationId: "work-safety-decision-cross-001"
    )
    let agent = try createServiceAgent(services: services, workspaceId: workspace.id)
    let sensitivePath = "/private/tmp/work-safety-approval-decision-sensitive-value"

    let explicitTask = try services.workSafetyTasks.createTask(
      context: owner,
      request: WorkSafetyTaskServiceRequest(
        title: "Explicit approver task",
        message: "Resolve with named approver only.",
        targetType: .agent,
        targetId: agent.id,
        approvalRequired: true,
        riskLevel: .high,
        metadata: [
          "approverActorIds": .array([.string(approver.actorId)]),
          "adminFallbackAllowed": .bool(false),
          "privatePath": .string(sensitivePath),
        ]
      ),
      now: fixedDate("2026-01-01T00:00:00Z")
    )
    let explicitApprovalId = try unwrap(explicitTask.approvalId, "explicit task missing approval")
    try expect(
      try services.workSafetyTasks.pendingApprovalCount(
        context: owner, now: fixedDate("2026-01-01T00:00:10Z")) == 1,
      "pending approval count should include explicit approval")

    do {
      _ = try services.workSafetyTasks.approveApproval(
        context: member,
        approvalId: explicitApprovalId,
        note: "member should not resolve \(sensitivePath)",
        now: fixedDate("2026-01-01T00:01:00Z")
      )
      throw ServiceTestFailure("non-approver member unexpectedly resolved approval")
    } catch let denied as ServiceGuardResult {
      try expect(
        denied.reasonCode == .authorityRoleRequired, "non-approver member should be denied")
      try expect(denied.decisionId == explicitApprovalId, "denial should link approval id")
    }
    do {
      _ = try services.workSafetyTasks.rejectApproval(
        context: admin,
        approvalId: explicitApprovalId,
        note: "admin fallback is disabled",
        now: fixedDate("2026-01-01T00:02:00Z")
      )
      throw ServiceTestFailure("admin fallback unexpectedly resolved explicit approval")
    } catch let denied as ServiceGuardResult {
      try expect(
        denied.reasonCode == .authorityRoleRequired, "admin fallback should respect explicit policy"
      )
    }
    try expect(
      try services.workSafetyTasks.getApproval(context: owner, approvalId: explicitApprovalId)
        .status == .pending, "denied decisions should not mutate approval")
    try expect(
      try services.data.getWorkSafetyTask(explicitTask.id).status == .blockedByApproval,
      "denied decisions should not mutate linked task")

    let approved = try services.workSafetyTasks.approveApproval(
      context: approver,
      approvalId: explicitApprovalId,
      note:
        "Approve after review token=work-safety-approval-decision-sensitive-value \(sensitivePath)",
      now: fixedDate("2026-01-01T00:03:00Z")
    )
    try expect(approved.approval.status == .approved, "explicit approver should approve")
    try expect(
      approved.approval.metadata["resolvedByActorId"]?.string == approver.actorId,
      "approval should record resolver actor")
    try expect(
      approved.note?.note.contains("[REDACTED]") == true, "decision note should be redacted")
    try expect(approved.task?.status == .queued, "approved approval should queue linked task")
    try expect(
      approved.event?.eventType == .approvalResolved, "approval decision should publish task event")
    try expect(
      try services.runtimeActions.listRuns(context: owner).isEmpty,
      "approval decision should not create runtime action rows")
    let resolvedEventCount = try services.workSafetyTasks
      .listEvents(context: owner, taskId: explicitTask.id)
      .filter { $0.eventType == .approvalResolved }
      .count
    do {
      _ = try services.workSafetyTasks.rejectApproval(
        context: approver,
        approvalId: explicitApprovalId,
        note: "duplicate decision should fail",
        now: fixedDate("2026-01-01T00:04:00Z")
      )
      throw ServiceTestFailure("duplicate approval decision unexpectedly succeeded")
    } catch let denied as ServiceGuardResult {
      try expect(denied.reasonCode == .inputInvalid, "duplicate decision should be invalid")
    }
    let afterDuplicateEventCount = try services.workSafetyTasks
      .listEvents(context: owner, taskId: explicitTask.id)
      .filter { $0.eventType == .approvalResolved }
      .count
    try expect(
      afterDuplicateEventCount == resolvedEventCount,
      "duplicate decision should not publish another resolved event")

    let fallbackTask = try services.workSafetyTasks.createTask(
      context: owner,
      request: WorkSafetyTaskServiceRequest(
        title: "Admin fallback rejection",
        targetType: .agent,
        targetId: agent.id,
        approvalRequired: true,
        riskLevel: .medium
      ),
      now: fixedDate("2026-01-01T00:05:00Z")
    )
    let fallbackApprovalId = try unwrap(fallbackTask.approvalId, "fallback task missing approval")
    let rejected = try services.workSafetyTasks.rejectApproval(
      context: admin,
      approvalId: fallbackApprovalId,
      note: "Reject retained task",
      now: fixedDate("2026-01-01T00:06:00Z")
    )
    try expect(
      rejected.approval.status == .rejected,
      "admin fallback should reject approval without explicit resolver")
    try expect(rejected.task?.status == .failed, "rejected approval should fail linked task")

    let expiredTask = try services.workSafetyTasks.createTask(
      context: owner,
      request: WorkSafetyTaskServiceRequest(
        title: "Expired approval task",
        targetType: .agent,
        targetId: agent.id,
        approvalRequired: true,
        riskLevel: .high
      ),
      now: fixedDate("2026-01-01T00:07:00Z")
    )
    let expiredApprovalId = try unwrap(expiredTask.approvalId, "expired task missing approval")
    var expiredApproval = try services.data.getWorkSafetyApproval(expiredApprovalId)
    expiredApproval.expiresAt = "2026-01-01T00:08:00Z"
    expiredApproval.updatedAt = "2026-01-01T00:07:30Z"
    _ = try services.data.saveWorkSafetyApproval(expiredApproval)
    do {
      _ = try services.workSafetyTasks.approveApproval(
        context: owner,
        approvalId: expiredApprovalId,
        note: "too late",
        now: fixedDate("2026-01-01T00:09:00Z")
      )
      throw ServiceTestFailure("expired approval unexpectedly resolved")
    } catch let denied as ServiceGuardResult {
      try expect(
        denied.reasonCode == .inputInvalid, "expired approval should be invalid to resolve")
    }
    try expect(
      try services.workSafetyTasks.getApproval(context: owner, approvalId: expiredApprovalId).status
        == .expired, "expired decision attempt should persist expired state")
    try expect(
      try services.data.getWorkSafetyTask(expiredTask.id).status == .blockedByApproval,
      "expired approval should keep task blocked")

    do {
      _ = try services.workSafetyTasks.getApproval(
        context: crossWorkspace, approvalId: explicitApprovalId)
      throw ServiceTestFailure("cross-workspace approval read unexpectedly succeeded")
    } catch let denied as ServiceGuardResult {
      try expect(
        denied.reasonCode == .inputInvalid, "cross-workspace approval read should be denied")
    }

    let stored = try services.database.all(
      """
      SELECT approval_json AS value FROM work_safety_approvals
      UNION ALL SELECT note_json AS value FROM work_safety_approval_notes
      UNION ALL SELECT event_json AS value FROM work_safety_task_events
      UNION ALL SELECT detail_json AS value FROM event_log
      """
    )
    .compactMap { sqliteText($0["value"]) }
    .joined(separator: "\n")
    try expect(!stored.contains(sensitivePath), "approval decision storage leaked private path")
    try expect(
      !stored.contains("work-safety-approval-decision-sensitive-value"),
      "approval decision storage leaked sensitive token")
    try expect(
      stored.contains("[REDACTED]"), "approval decision storage should include redaction sentinel")
  }

  private static func testPermissionPolicyServiceEnforcesLocalAuthorityAndWorkspaceIsolation()
    throws
  {
    let root = FileManager.default.temporaryDirectory
      .appendingPathComponent("RelayConsolePermissionPolicyTests", isDirectory: true)
      .appendingPathComponent(UUID().uuidString, isDirectory: true)
    let services = try makeServices(
      root: root,
      providerActionAdapter: RoutingMarketplaceProviderActionAdapter(
        xAdapter: XProviderActionAdapter(client: FakeXProviderActionClient()),
        gmailAdapter: GmailProviderActionAdapter(client: FakeGmailProviderActionClient())
      )
    )
    let workspace = try unwrap(services.data.getAppState().activeWorkspace, "missing workspace")
    let owner = Self.context(
      roles: [.owner], workspaceId: workspace.id, correlationId: "permissions-owner-001")
    let admin = Self.context(
      roles: [.admin], workspaceId: workspace.id, correlationId: "permissions-admin-001")
    let member = Self.context(
      roles: [.member], workspaceId: workspace.id, correlationId: "permissions-member-001")
    let viewer = Self.context(
      roles: [.viewer], workspaceId: workspace.id, correlationId: "permissions-viewer-001")
    let sensitivePath = "/private/tmp/permission-policy-sensitive-value"
    let policyEvents = EventCounter()
    let subscription = services.eventBus.on(.permissionPolicyUpdated) { _ in
      policyEvents.increment()
    }
    defer { services.eventBus.off(.permissionPolicyUpdated, id: subscription) }

    let defaultPolicies = try services.permissions.listPolicies(context: viewer)
    try expect(
      defaultPolicies.contains { $0.roleTargets.contains("admin") && $0.action == "*" },
      "default owner/admin wildcard policy missing")
    try expect(
      defaultPolicies.contains { $0.roleTargets.contains("viewer") && $0.action == "read" },
      "default viewer/member read policy missing")

    let ownerWildcard = try services.permissions.evaluate(
      context: owner,
      resourceType: "work_safety_task",
      resourceId: "wst-permission-wildcard",
      action: "dispatch",
      now: fixedDate("2026-01-01T00:00:00Z")
    )
    try expect(ownerWildcard.allowed, "owner wildcard policy should allow retained action")

    let viewerRead = try services.permissions.evaluate(
      context: viewer,
      resourceType: "work_safety_task",
      action: "read",
      now: fixedDate("2026-01-01T00:00:01Z")
    )
    try expect(viewerRead.allowed, "viewer read policy should allow inspection")

    let viewerWrite = try services.permissions.evaluate(
      context: viewer,
      resourceType: "work_safety_task",
      action: "create",
      now: fixedDate("2026-01-01T00:00:02Z")
    )
    try expect(
      !viewerWrite.allowed && viewerWrite.decision == .noMatch,
      "viewer write should fail closed without a policy")

    do {
      _ = try services.permissions.createPolicy(
        context: member,
        request: PermissionPolicyRequest(
          name: "Member policy mutation should fail",
          effect: .allow,
          roleTargets: ["member"],
          resourceType: "*",
          action: "*",
          message: "member denied"
        )
      )
      throw ServiceTestFailure("member unexpectedly created permission policy")
    } catch let denied as ServiceGuardResult {
      try expect(
        denied.reasonCode == .authorityRoleRequired,
        "member policy mutation should require owner/admin")
    }

    let agent = try createServiceAgent(services: services, workspaceId: workspace.id)
    let task = try services.workSafetyTasks.createTask(
      context: owner,
      request: WorkSafetyTaskServiceRequest(
        title: "Policy guarded task",
        message: "Dispatch should be policy-denied for admin.",
        targetType: .agent,
        targetId: agent.id,
        approvalRequired: false,
        riskLevel: .high
      ),
      now: fixedDate("2026-01-01T00:00:03Z")
    )

    let deny = try services.permissions.createPolicy(
      context: owner,
      request: PermissionPolicyRequest(
        name: "Deny admin dispatch \(sensitivePath)",
        effect: .deny,
        roleTargets: ["admin"],
        resourceType: "work_safety_task",
        resourceId: task.id,
        action: "dispatch",
        priority: 100,
        reasonCode: .policyBlocked,
        message: "Dispatch denied by retained policy \(sensitivePath)",
        metadata: ["privatePath": .string(sensitivePath)]
      ),
      now: fixedDate("2026-01-01T00:00:04Z")
    )
    try expect(
      deny.name.contains("[REDACTED]"), "permission policy name should redact private path")
    try expect(
      deny.message.contains("[REDACTED]"), "permission policy message should redact private path")

    do {
      _ = try services.workSafetyTasks.dispatchTask(
        context: admin,
        taskId: task.id,
        denialDetail: ["rawDetail": .string("admin attempted \(sensitivePath)")],
        now: fixedDate("2026-01-01T00:00:05Z")
      )
      throw ServiceTestFailure("admin dispatch unexpectedly bypassed deny policy")
    } catch let denied as ServiceGuardResult {
      try expect(denied.reasonCode == .policyBlocked, "dispatch should be policy blocked")
      try expect(denied.decisionId == deny.id, "policy denial should link matched policy id")
    }
    try expect(
      try services.data.getWorkSafetyTask(task.id).status == .queued,
      "policy-denied dispatch should not mutate task")
    try expect(
      try services.workSafetyTasks.listRuns(context: owner, taskId: task.id).isEmpty,
      "policy-denied dispatch should not create task run")
    let storedBeforeDelete = try services.database.all(
      """
      SELECT policy_json AS value FROM permission_policies
      UNION ALL SELECT metadata_json AS value FROM permission_policies
      UNION ALL SELECT detail_json AS value FROM event_log
      WHERE category IN ('permission.denied', 'permission.policy')
      """
    ).compactMap { sqliteText($0["value"]) }.joined(separator: "\n")
    try expect(
      !storedBeforeDelete.contains(sensitivePath), "permission policy storage leaked private path")
    try expect(
      storedBeforeDelete.contains("[REDACTED]"),
      "permission policy records should include redaction sentinel before delete")

    let allowedForOwner = try services.permissions.evaluate(
      context: owner,
      resourceType: "work_safety_task",
      resourceId: task.id,
      action: "dispatch",
      now: fixedDate("2026-01-01T00:00:06Z")
    )
    try expect(allowedForOwner.allowed, "admin-only deny should not block owner wildcard policy")

    let otherWorkspace = try services.data.createWorkspace(
      profileId: try unwrap(services.data.getActiveProfile(), "missing profile").id,
      name: "Permission Policy Other Workspace",
      defaultFolderPath: nil
    )
    let otherOwner = Self.context(
      roles: [.owner], workspaceId: otherWorkspace.id, correlationId: "permissions-other-owner-001")
    let otherEvaluation = try services.permissions.evaluate(
      context: otherOwner,
      resourceType: "work_safety_task",
      resourceId: task.id,
      action: "dispatch",
      now: fixedDate("2026-01-01T00:00:07Z")
    )
    try expect(otherEvaluation.allowed, "policy deny should not cross workspace boundaries")
    try expect(
      otherEvaluation.matchedPolicyId != deny.id, "cross-workspace evaluation reused wrong policy")

    let updated = try services.permissions.updatePolicy(
      context: admin,
      policyId: deny.id,
      request: PermissionPolicyRequest(
        name: "Disable deny policy",
        effect: .deny,
        status: .disabled,
        roleTargets: ["admin"],
        resourceType: "work_safety_task",
        resourceId: task.id,
        action: "dispatch",
        priority: 100,
        reasonCode: .policyBlocked,
        message: "disabled"
      ),
      now: fixedDate("2026-01-01T00:00:08Z")
    )
    try expect(updated.status == .disabled, "admin should update permission policy")
    let deleted = try services.permissions.deletePolicy(context: owner, policyId: deny.id)
    try expect(deleted.id == deny.id, "owner should delete permission policy")
    try expect(policyEvents.value >= 3, "policy create/update/delete should publish events")

    let stored = try services.database.all(
      """
      SELECT policy_json AS value FROM permission_policies
      UNION ALL SELECT metadata_json AS value FROM permission_policies
      UNION ALL SELECT detail_json AS value FROM event_log
      WHERE category IN ('permission.denied', 'permission.policy')
      """
    ).compactMap { sqliteText($0["value"]) }.joined(separator: "\n")
    try expect(!stored.contains(sensitivePath), "permission policy storage leaked private path")
    try expect(
      try services.runtimeActions.listRuns(context: owner).isEmpty,
      "permission policy flow should not create runtime action rows")
  }

  private static func testAuditSecurityServiceRecordsRedactedAdminGatedMetrics() throws {
    let root = FileManager.default.temporaryDirectory
      .appendingPathComponent("RelayConsoleAuditSecurityTests", isDirectory: true)
      .appendingPathComponent(UUID().uuidString, isDirectory: true)
    let sensitive = "audit-sensitive-value-001"
    let sensitivePath = "/private/tmp/audit-sensitive-value-001"
    let workspaceId: RelayId
    let commandAuditId: RelayId

    do {
      let services = try makeServices(root: root)
      let workspace = try unwrap(
        services.data.getAppState().activeWorkspace, "missing audit workspace")
      workspaceId = workspace.id
      let owner = Self.context(
        roles: [.owner], workspaceId: workspace.id, correlationId: "audit-owner-001")
      let admin = Self.context(
        roles: [.admin], workspaceId: workspace.id, correlationId: "audit-admin-001")
      let member = Self.context(
        roles: [.member], workspaceId: workspace.id, correlationId: "audit-member-001")
      let viewer = Self.context(
        roles: [.viewer], workspaceId: workspace.id, correlationId: "audit-viewer-001")
      let auditEvents = EventCounter()
      let metricEvents = EventCounter()
      let auditSubscription = services.eventBus.on(.auditLogUpdated) { _ in auditEvents.increment()
      }
      let metricSubscription = services.eventBus.on(.securityMetricsUpdated) { _ in
        metricEvents.increment()
      }
      defer {
        services.eventBus.off(.auditLogUpdated, id: auditSubscription)
        services.eventBus.off(.securityMetricsUpdated, id: metricSubscription)
      }

      let commandAudit = try unwrap(
        services.auditSecurity.record(
          context: admin,
          request: AuditLogRecordRequest(
            eventType: "command.rejected",
            resourceType: "command",
            resourceId: "cmd-audit-001",
            severity: "warning",
            message: "Rejected command token=\(sensitive) at \(sensitivePath)",
            source: "service-test",
            context: [
              "commandLine": .string("deploy --token \(sensitive) \(sensitivePath)"),
              "environment": .object([
                "API_TOKEN": .string(sensitive),
                "WORKSPACE_PATH": .string(sensitivePath),
              ]),
              "riskLevel": .string("high"),
            ]
          ),
          now: fixedDate("2026-01-01T00:00:00Z")
        ),
        "command rejection audit should be recorded"
      )
      commandAuditId = commandAudit.id
      try expect(
        commandAudit.message.contains("[REDACTED]"),
        "audit message should redact sensitive command data")
      try expect(
        commandAudit.context["commandLine"] == .string("[REDACTED]"),
        "audit commandLine should be fully redacted")
      if case .object(let environment)? = commandAudit.context["environment"] {
        try expect(
          environment["API_TOKEN"] == .string("[REDACTED]"),
          "audit environment token should be redacted")
        try expect(
          environment["WORKSPACE_PATH"]?.string?.contains("[REDACTED]") == true,
          "audit environment path should be redacted")
      } else {
        throw ServiceTestFailure("audit environment metadata was not preserved as object")
      }

      _ = services.auditSecurity.record(
        context: admin,
        request: AuditLogRecordRequest(
          eventType: "permission.denied",
          resourceType: "work_safety_task",
          resourceId: "wst-audit-001",
          severity: "warning",
          message: "Permission denied by retained policy.",
          source: "service-test",
          context: ["reasonCode": .string(GuardReasonCode.policyBlocked.rawValue)]
        ),
        now: fixedDate("2026-01-01T00:00:00Z")
      )
      _ = services.auditSecurity.record(
        context: admin,
        request: AuditLogRecordRequest(
          eventType: "tool_request.transition",
          resourceType: "tool_request",
          resourceId: "treq-audit-001",
          severity: "info",
          message: "Needed tool request moved to unavailable.",
          source: "service-test"
        ),
        now: fixedDate("2026-01-01T00:00:01Z")
      )
      _ = services.auditSecurity.record(
        context: admin,
        request: AuditLogRecordRequest(
          eventType: "file_permission.changed",
          resourceType: "file_permission",
          resourceId: "fperm-audit-001",
          severity: "warning",
          message: "File permission denied for \(sensitivePath)",
          source: "service-test",
          context: ["localPath": .string(sensitivePath)]
        ),
        now: fixedDate("2026-01-01T00:00:02Z")
      )
      _ = services.auditSecurity.record(
        context: admin,
        request: AuditLogRecordRequest(
          eventType: "export_reset.attempt",
          resourceType: "export_reset",
          resourceId: "exp-audit-001",
          severity: "warning",
          message: "Export/reset attempt recorded.",
          source: "service-test"
        ),
        now: fixedDate("2026-01-01T00:00:03Z")
      )
      _ = services.auditSecurity.record(
        context: admin,
        request: AuditLogRecordRequest(
          eventType: "recovery.event",
          resourceType: "runtime_recovery",
          resourceId: "rrr-audit-001",
          severity: "info",
          message: "Relaunch recovery restored audit state.",
          source: "service-test"
        ),
        now: fixedDate("2026-01-01T00:00:04Z")
      )
      _ = services.auditSecurity.record(
        context: admin,
        request: AuditLogRecordRequest(
          eventType: "task.transition",
          resourceType: "work_safety_task",
          resourceId: "wst-audit-001",
          severity: "info",
          message: "Task transitioned without runtime output.",
          source: "service-test"
        ),
        now: fixedDate("2026-01-01T00:00:05Z")
      )
      _ = services.auditSecurity.record(
        context: admin,
        request: AuditLogRecordRequest(
          eventType: "approval.decision",
          resourceType: "work_safety_approval",
          resourceId: "wsa-audit-001",
          severity: "info",
          message: "Approval decision recorded.",
          approvalId: "wsa-audit-001",
          source: "service-test"
        ),
        now: fixedDate("2026-01-01T00:00:06Z")
      )
      _ = services.auditSecurity.record(
        context: admin,
        request: AuditLogRecordRequest(
          eventType: "high_risk.execution_attempt",
          resourceType: "runtime_action",
          resourceId: "rar-audit-001",
          severity: "warning",
          message: "High-risk action attempt was blocked.",
          actionRunId: "rar-audit-001",
          source: "service-test",
          context: ["riskLevel": .string("destructive")]
        ),
        now: fixedDate("2026-01-01T00:00:07Z")
      )

      let policy = try services.permissions.createPolicy(
        context: owner,
        request: PermissionPolicyRequest(
          name: "Audit mirrored deny",
          effect: .deny,
          roleTargets: ["admin"],
          resourceType: "work_safety_task",
          resourceId: "wst-audit-001",
          action: "dispatch",
          priority: 50,
          reasonCode: .policyBlocked,
          message: "Dispatch denied",
          metadata: ["localPath": .string(sensitivePath)]
        ),
        now: fixedDate("2026-01-01T00:00:08Z")
      )
      try expect(
        policy.redactionStatus == "private-state-excluded",
        "permission policy fixture should stay redacted")

      let page = try services.auditSecurity.list(context: admin, query: AuditLogQuery(limit: 2))
      try expect(page.records.count == 2, "audit list should page records")
      try expect(page.nextOffset == 2, "audit list should expose next offset")
      try expect(page.totalCount >= 10, "audit total should include direct and mirrored records")
      let commandPage = try services.auditSecurity.list(
        context: admin, query: AuditLogQuery(limit: 10, eventType: "command.rejected"))
      try expect(
        commandPage.records.map(\.id).contains(commandAudit.id),
        "audit filter should find command rejection")
      let policyPage = try services.auditSecurity.list(
        context: admin, query: AuditLogQuery(limit: 10, eventType: "permission_policy.created"))
      try expect(
        policyPage.records.contains { $0.resourceId == policy.id },
        "permission policy event should mirror into audit log")

      do {
        _ = try services.auditSecurity.list(context: viewer)
        throw ServiceTestFailure("viewer unexpectedly listed audit records")
      } catch let denied as ServiceGuardResult {
        try expect(
          denied.reasonCode == .authorityRoleRequired,
          "viewer audit list should require owner/admin")
      }
      do {
        _ = try services.auditSecurity.securitySummary(context: member)
        throw ServiceTestFailure("member unexpectedly read security summary")
      } catch let denied as ServiceGuardResult {
        try expect(
          denied.reasonCode == .authorityRoleRequired, "member summary should require owner/admin")
      }
      let deniedReadPage = try services.auditSecurity.list(
        context: admin, query: AuditLogQuery(limit: 10, eventType: "audit.read.denied"))
      try expect(deniedReadPage.records.count >= 2, "denied audit reads should be audited")

      let otherWorkspace = try services.data.createWorkspace(
        profileId: try unwrap(services.data.getActiveProfile(), "missing profile").id,
        name: "Audit Other Workspace",
        defaultFolderPath: nil
      )
      let otherAdmin = Self.context(
        roles: [.admin], workspaceId: otherWorkspace.id, correlationId: "audit-other-001")
      _ = services.auditSecurity.record(
        context: otherAdmin,
        request: AuditLogRecordRequest(
          eventType: "permission.denied",
          resourceType: "work_safety_task",
          resourceId: "wst-other-audit-001",
          severity: "warning",
          message: "Other workspace denial.",
          source: "service-test"
        ),
        now: fixedDate("2026-01-01T00:00:09Z")
      )
      let isolated = try services.auditSecurity.list(
        context: admin, query: AuditLogQuery(limit: 100))
      try expect(
        !isolated.records.contains { $0.workspaceId == otherWorkspace.id },
        "audit list crossed workspace boundary")

      let summary = try services.auditSecurity.securitySummary(
        context: admin,
        query: AuditLogQuery(limit: 100),
        now: fixedDate("2026-01-01T00:01:00Z")
      )
      try expect(
        summary.auditEventCount >= 12, "security summary should count durable audit records")
      try expect(summary.deniedActionCount >= 3, "security summary should count denied actions")
      try expect(
        summary.permissionDeniedCount == 1, "security summary should count permission denials")
      try expect(
        summary.approvalDecisionCount == 1, "security summary should count approval decisions")
      try expect(summary.policyMutationCount == 1, "security summary should count policy mutations")
      try expect(summary.taskTransitionCount == 1, "security summary should count task transitions")
      try expect(
        summary.toolRequestTransitionCount == 1,
        "security summary should count tool-request transitions")
      try expect(
        summary.commandRejectionCount == 1, "security summary should count command rejections")
      try expect(
        summary.highRiskExecutionCount >= 2, "security summary should count high-risk attempts")
      try expect(
        summary.filePermissionChangeCount == 1,
        "security summary should count file permission changes")
      try expect(
        summary.exportResetAttemptCount == 1, "security summary should count export/reset attempts")
      try expect(summary.recoveryEventCount == 1, "security summary should count recovery events")
      try expect(
        summary.redactionAppliedCount >= 2, "security summary should count redacted records")
      try expect(
        try services.auditSecurity.latestPersistedSummary(context: admin)?.id == summary.id,
        "security summary should persist snapshot")
      try expect(auditEvents.value >= 10, "audit records should publish audit events")
      try expect(metricEvents.value >= 1, "security summary should publish metric event")

      let stored = try services.database.all(
        """
        SELECT record_json AS value FROM audit_log_records
        UNION ALL SELECT context_json AS value FROM audit_log_records
        UNION ALL SELECT snapshot_json AS value FROM security_metric_snapshots
        UNION ALL SELECT detail_json AS value FROM event_log
        WHERE category IN ('permission.policy', 'audit.writer')
        """
      ).compactMap { sqliteText($0["value"]) }.joined(separator: "\n")
      try expect(!stored.contains(sensitive), "audit/security storage leaked sensitive token")
      try expect(!stored.contains(sensitivePath), "audit/security storage leaked private path")
      try expect(
        stored.contains("[REDACTED]"), "audit/security storage should retain redaction markers")
      try expect(
        services.auditSecurity.redactEvidenceSnippet("token=\(sensitive) \(sensitivePath)")
          .contains("[REDACTED]"), "evidence snippet redaction should hide sensitive data")
      services.database.close()
    }

    let reopened = try makeServices(root: root)
    let reopenedAdmin = Self.context(
      roles: [.admin], workspaceId: workspaceId, correlationId: "audit-reopen-001")
    let reopenedPage = try reopened.auditSecurity.list(
      context: reopenedAdmin, query: AuditLogQuery(limit: 100))
    try expect(
      reopenedPage.records.map(\.id).contains(commandAuditId),
      "audit records should survive relaunch")
    let reopenedSummary = try reopened.auditSecurity.securitySummary(
      context: reopenedAdmin, query: AuditLogQuery(limit: 100))
    try expect(
      reopenedSummary.commandRejectionCount == 1, "security metrics should recompute after relaunch"
    )
    try expect(
      reopenedSummary.auditEventCount == reopenedPage.records.count,
      "relaunch summary should derive from durable audit rows")
  }

  private static func testNativeFilePermissionServiceFailsClosedAndRedactsRetainedRecords() throws {
    let root = FileManager.default.temporaryDirectory
      .appendingPathComponent("RelayConsoleNativeFilePermissionTests", isDirectory: true)
      .appendingPathComponent(UUID().uuidString, isDirectory: true)
    let rawPath = "/private/tmp/native-file-permission-sensitive-value/Project"
    let workspaceId: RelayId
    let retainedPermissionId: RelayId

    do {
      let services = try makeServices(root: root)
      let workspace = try unwrap(
        services.data.getAppState().activeWorkspace, "missing native file permission workspace")
      workspaceId = workspace.id
      let owner = Self.context(
        roles: [.owner], workspaceId: workspace.id, correlationId: "native-file-owner-001")
      let admin = Self.context(
        roles: [.admin], workspaceId: workspace.id, correlationId: "native-file-admin-001")
      let member = Self.context(
        roles: [.member], workspaceId: workspace.id, correlationId: "native-file-member-001")
      let viewer = Self.context(
        roles: [.viewer], workspaceId: workspace.id, correlationId: "native-file-viewer-001")
      let updateEvents = EventCounter()
      let subscription = services.eventBus.on(.nativeFilePermissionUpdated) { _ in
        updateEvents.increment()
      }
      defer {
        services.eventBus.off(.nativeFilePermissionUpdated, id: subscription)
      }

      let readOnlyFile = try services.nativeFilePermissions.linkPermission(
        context: owner,
        request: NativeFilePermissionRequest(
          targetKind: .file,
          displayName: "Quarterly plan",
          rawPath: "\(rawPath)/plan.md",
          bookmarkRef: "fixture-bookmark-native-file-sensitive-value",
          accessLevel: .readOnly,
          status: .readOnly,
          metadata: [
            "localPath": .string(rawPath),
            "relatedTaskId": .string("wst-native-file-001"),
            "requestedState": .string("first link"),
          ]
        ),
        now: fixedDate("2026-01-01T00:00:00Z")
      )
      try expect(
        readOnlyFile.displayPath.contains("[REDACTED]"),
        "display path should be redacted/summarized")
      try expect(!readOnlyFile.displayPath.contains(rawPath), "display path leaked raw path")
      try expect(
        readOnlyFile.bookmarkRef?.hasPrefix("bookmark-") == true,
        "bookmark reference should be opaque")
      try expect(
        readOnlyFile.metadata["rawPathPersisted"] == .bool(false),
        "metadata should record no raw-path persistence")
      _ = try services.nativeFilePermissions.requireAccess(
        context: owner,
        permissionId: readOnlyFile.id,
        requiredAccess: .readOnly,
        now: fixedDate("2026-01-01T00:00:01Z")
      )
      do {
        _ = try services.nativeFilePermissions.requireAccess(
          context: owner,
          permissionId: readOnlyFile.id,
          requiredAccess: .readWrite,
          now: fixedDate("2026-01-01T00:00:02Z")
        )
        throw ServiceTestFailure(
          "read-only native file permission unexpectedly allowed write access")
      } catch let denied as ServiceGuardResult {
        try expect(
          denied.reasonCode == .authorityReadOnly,
          "read-only write attempt should fail as read-only")
      }

      let readWriteFolder = try services.nativeFilePermissions.linkPermission(
        context: owner,
        request: NativeFilePermissionRequest(
          targetKind: .folder,
          displayName: "Project export",
          rawPath: rawPath,
          bookmarkRef: "fixture-bookmark-native-file-rw",
          accessLevel: .readWrite,
          status: .readWriteGranted,
          metadata: [
            "mode": .string("controlled write target"),
            "relatedActionRunId": .string("rar-native-file-001"),
          ]
        ),
        now: fixedDate("2026-01-01T00:00:03Z")
      )
      retainedPermissionId = readWriteFolder.id
      _ = try services.nativeFilePermissions.requireAccess(
        context: owner,
        permissionId: readWriteFolder.id,
        requiredAccess: .readWrite,
        now: fixedDate("2026-01-01T00:00:04Z")
      )
      let memberVisible = try services.nativeFilePermissions.listPermissions(context: member)
      try expect(
        memberVisible.contains { $0.id == readWriteFolder.id },
        "member should inspect retained permission records through read policy")
      do {
        _ = try services.nativeFilePermissions.updateStatus(
          context: member,
          permissionId: readWriteFolder.id,
          status: .stale,
          now: fixedDate("2026-01-01T00:00:05Z")
        )
        throw ServiceTestFailure("member unexpectedly updated native file permission")
      } catch let denied as ServiceGuardResult {
        try expect(
          denied.reasonCode == .authorityRoleRequired,
          "member status update should require owner/admin")
      }

      for (index, status) in [
        NativeFilePermissionStatus.permissionNeeded,
        .revoked,
        .unavailable,
        .stale,
        .syncFailed,
        .notLinked,
      ].enumerated() {
        let permission = try services.nativeFilePermissions.linkPermission(
          context: admin,
          request: NativeFilePermissionRequest(
            targetKind: .folder,
            displayName: "State fixture \(index)",
            rawPath: "\(rawPath)/state-\(index)",
            bookmarkRef: "fixture-bookmark-state-\(index)",
            accessLevel: .readWrite,
            status: status,
            metadata: ["stateFixture": .string(status.rawValue)]
          ),
          now: fixedDate("2026-01-01T00:00:\(10 + index)Z")
        )
        do {
          _ = try services.nativeFilePermissions.requireAccess(
            context: owner,
            permissionId: permission.id,
            requiredAccess: .readWrite,
            now: fixedDate("2026-01-01T00:00:\(20 + index)Z")
          )
          throw ServiceTestFailure("\(status.rawValue) unexpectedly allowed file access")
        } catch let denied as ServiceGuardResult {
          try expect(
            denied.stateKind == .permissionNeeded || denied.stateKind == .retryableError,
            "\(status.rawValue) should fail closed"
          )
        }
      }

      let synced = try services.nativeFilePermissions.updateStatus(
        context: owner,
        permissionId: readWriteFolder.id,
        status: .synced,
        now: fixedDate("2026-01-01T00:01:00Z")
      )
      try expect(
        synced.lastSyncedAt?.contains("2026-01-01T00:01:00") == true,
        "synced state should stamp lastSyncedAt")
      _ = try services.nativeFilePermissions.requireAccess(
        context: owner,
        permissionId: synced.id,
        requiredAccess: .readWrite,
        now: fixedDate("2026-01-01T00:01:01Z")
      )
      let syncFailed = try services.nativeFilePermissions.updateStatus(
        context: owner,
        permissionId: readWriteFolder.id,
        status: .syncFailed,
        failureReason: "\(rawPath)/sync failure",
        now: fixedDate("2026-01-01T00:01:02Z")
      )
      try expect(
        syncFailed.failureReason?.contains("[REDACTED]") == true, "sync failure should be redacted")
      do {
        _ = try services.nativeFilePermissions.requireAccess(
          context: owner,
          permissionId: syncFailed.id,
          requiredAccess: .readWrite,
          now: fixedDate("2026-01-01T00:01:03Z")
        )
        throw ServiceTestFailure(
          "sync-failed native file permission unexpectedly allowed write access")
      } catch let denied as ServiceGuardResult {
        try expect(denied.retryable, "sync-failed state should be retryable but fail closed")
      }

      let restored = try services.nativeFilePermissions.updateStatus(
        context: owner,
        permissionId: readWriteFolder.id,
        status: .readWriteGranted,
        accessLevel: .readWrite,
        failureReason: nil,
        now: fixedDate("2026-01-01T00:01:04Z")
      )
      _ = try services.nativeFilePermissions.requireAccess(
        context: owner,
        permissionId: restored.id,
        requiredAccess: .readWrite,
        now: fixedDate("2026-01-01T00:01:05Z")
      )
      let revoked = try services.nativeFilePermissions.revokePermission(
        context: owner,
        permissionId: readOnlyFile.id,
        now: fixedDate("2026-01-01T00:01:06Z")
      )
      try expect(
        revoked.status == .revoked && revoked.bookmarkRef == nil,
        "revoked permission should clear bookmark reference")
      do {
        _ = try services.nativeFilePermissions.requireAccess(
          context: owner,
          permissionId: revoked.id,
          requiredAccess: .readOnly,
          now: fixedDate("2026-01-01T00:01:07Z")
        )
        throw ServiceTestFailure("revoked native file permission unexpectedly allowed read access")
      } catch let denied as ServiceGuardResult {
        try expect(
          denied.reasonCode == .permissionNeeded, "revoked access should require permission")
      }
      let unlinked = try services.nativeFilePermissions.unlinkPermission(
        context: owner,
        permissionId: revoked.id,
        now: fixedDate("2026-01-01T00:01:08Z")
      )
      try expect(
        unlinked.status == .notLinked && unlinked.pathHash == nil,
        "unlink should clear target hash and mark not linked")

      let beforeDeniedLink = try services.nativeFilePermissions.listPermissions(context: owner)
        .count
      _ = try services.permissions.createPolicy(
        context: owner,
        request: PermissionPolicyRequest(
          name: "Deny native file link",
          effect: .deny,
          roleTargets: ["owner"],
          resourceType: "native_file_permission",
          resourceId: nil,
          action: "link",
          priority: 100,
          reasonCode: .policyBlocked,
          message: "Native file permission link denied by fixture.",
          metadata: ["localPath": .string(rawPath)]
        ),
        now: fixedDate("2026-01-01T00:01:09Z")
      )
      do {
        _ = try services.nativeFilePermissions.linkPermission(
          context: owner,
          request: NativeFilePermissionRequest(
            targetKind: .file,
            displayName: "Denied link",
            rawPath: "\(rawPath)/denied.md",
            bookmarkRef: "fixture-bookmark-denied",
            accessLevel: .readOnly
          ),
          now: fixedDate("2026-01-01T00:01:10Z")
        )
        throw ServiceTestFailure("policy-denied native file permission link unexpectedly persisted")
      } catch let denied as ServiceGuardResult {
        try expect(
          denied.reasonCode == .policyBlocked, "policy-denied link should return policy blocked")
      }
      let afterDeniedLink = try services.nativeFilePermissions.listPermissions(context: viewer)
        .count
      try expect(
        afterDeniedLink == beforeDeniedLink,
        "policy-denied native file permission link mutated persistence")

      let stored = try services.database.all(
        """
        SELECT display_name AS value FROM native_file_permissions
        UNION ALL SELECT display_path AS value FROM native_file_permissions
        UNION ALL SELECT bookmark_ref AS value FROM native_file_permissions
        UNION ALL SELECT metadata_json AS value FROM native_file_permissions
        UNION ALL SELECT permission_json AS value FROM native_file_permissions
        UNION ALL SELECT context_json AS value FROM audit_log_records
        WHERE event_type LIKE 'file_permission.%'
        """
      ).compactMap { sqliteText($0["value"]) }.joined(separator: "\n")
      try expect(
        !stored.contains(rawPath), "native file permission storage leaked raw private path")
      try expect(
        !stored.contains("native-file-permission-sensitive-value"),
        "native file permission storage leaked sensitive path segment")
      try expect(
        stored.contains("[REDACTED]"),
        "native file permission storage should contain redaction markers")

      let audits = try services.data.listAuditLogRecords(workspaceId: workspace.id, limit: 200)
      let auditTypes = Set(audits.map(\.eventType))
      try expect(
        auditTypes.contains("file_permission.linked"),
        "native file permission link should be audited")
      try expect(
        auditTypes.contains("file_permission.denied"),
        "native file permission denial should be audited")
      try expect(
        auditTypes.contains("file_permission.revoked"),
        "native file permission revoke should be audited")
      try expect(
        auditTypes.contains("file_permission.sync_failed"),
        "native file permission sync failure should be audited")
      try expect(
        auditTypes.contains("file_permission.unlinked"),
        "native file permission unlink should be audited")

      let summary = try services.auditSecurity.securitySummary(
        context: owner,
        query: AuditLogQuery(limit: 200),
        now: fixedDate("2026-01-01T00:01:11Z")
      )
      try expect(
        summary.filePermissionChangeCount >= 10,
        "security summary should count native file permission changes")
      try expect(
        updateEvents.value >= beforeDeniedLink,
        "native file permission updates should publish events")
      services.database.close()
    }

    let reopened = try makeServices(root: root)
    let reopenedOwner = Self.context(
      roles: [.owner], workspaceId: workspaceId, correlationId: "native-file-reopen-001")
    let recovered = try unwrap(
      try reopened.nativeFilePermissions.getPermission(
        context: reopenedOwner, permissionId: retainedPermissionId),
      "native file permission should survive relaunch"
    )
    try expect(
      recovered.status == .readWriteGranted,
      "relaunch should recover latest retained file permission state")
    _ = try reopened.nativeFilePermissions.requireAccess(
      context: reopenedOwner,
      permissionId: retainedPermissionId,
      requiredAccess: .readWrite,
      now: fixedDate("2026-01-01T00:02:00Z")
    )
    let reopenedStored = try reopened.database.all(
      "SELECT permission_json AS value FROM native_file_permissions WHERE id = ?",
      [.text(retainedPermissionId)]
    ).compactMap { sqliteText($0["value"]) }.joined(separator: "\n")
    try expect(!reopenedStored.contains(rawPath), "relaunch storage leaked raw native file path")
  }

