    let exported = try services.runtimeWorkspace.exportFile(
      agent: openClawAgent, rootId: openWorkspaceRoot.rootId, relativePath: "plans/fixture.png")
    try expect(
      exported.filename == "fixture.png" && exported.data.count == 4,
