          context: owner, connection: localConnection)
        throw ServiceTestFailure("local app provider connection unexpectedly saved")
      } catch let denied as ServiceGuardResult {
        try expect(
          denied.reasonCode == .inputInvalid, "local app provider connection should remain excluded"
        )
      }

      let sqliteDump = try services.database.all(
        """
        SELECT connection_json AS value FROM applications_provider_connections
        UNION ALL
        SELECT flow_json AS value FROM applications_provider_authorization_flows
        UNION ALL
        SELECT snapshot_json AS value FROM applications_provider_connection_snapshots
        """
      ).compactMap { sqliteText($0["value"]) }.joined(separator: "\n")
      try expect(
        !sqliteDump.contains("provider-contract-sensitive-value"),
        "raw provider secret leaked into SQLite JSON")
      try expect(
        !sqliteDump.contains("linkedin-access-token-provider-contract-sensitive-value"),
        "raw LinkedIn access token leaked into SQLite JSON")
      try expect(
        !sqliteDump.contains("linkedin-refresh-token-provider-contract-sensitive-value"),
        "raw LinkedIn refresh token leaked into SQLite JSON")
      try expect(
        !sqliteDump.contains("gmail-client-id-provider-contract-sensitive-value"),
        "raw Gmail client ID leaked into SQLite JSON")
      try expect(
        !sqliteDump.contains("gmail-client-secret-provider-contract-sensitive-value"),
        "raw Gmail client secret leaked into SQLite JSON")
      try expect(
        !sqliteDump.contains("gmail-refresh-token-provider-contract-sensitive-value"),
        "raw Gmail refresh token leaked into SQLite JSON")
      try expect(
        !sqliteDump.contains("gmail-access-token-provider-contract-sensitive-value"),
        "raw Gmail access token leaked into SQLite JSON")
      try expect(
        !sqliteDump.contains("google-docs-client-id-provider-contract-sensitive-value"),
        "raw Google Docs client ID leaked into SQLite JSON")
      try expect(
        !sqliteDump.contains("google-docs-client-secret-provider-contract-sensitive-value"),
        "raw Google Docs client secret leaked into SQLite JSON")
      try expect(
        !sqliteDump.contains("google-docs-refresh-token-provider-contract-sensitive-value"),
        "raw Google Docs refresh token leaked into SQLite JSON")
      try expect(
        !sqliteDump.contains("google-docs-access-token-provider-contract-sensitive-value"),
        "raw Google Docs access token leaked into SQLite JSON")
      try expect(
        !sqliteDump.contains("google-calendar-client-id-provider-contract-sensitive-value"),
        "raw Google Calendar client ID leaked into SQLite JSON")
      try expect(
        !sqliteDump.contains("google-calendar-client-secret-provider-contract-sensitive-value"),
        "raw Google Calendar client secret leaked into SQLite JSON")
      try expect(
        !sqliteDump.contains("google-calendar-refresh-token-provider-contract-sensitive-value"),
        "raw Google Calendar refresh token leaked into SQLite JSON")
      try expect(
        !sqliteDump.contains("google-calendar-access-token-provider-contract-sensitive-value"),
        "raw Google Calendar access token leaked into SQLite JSON")
      try expect(
        !sqliteDump.contains("google-drive-client-id-provider-contract-sensitive-value"),
        "raw Google Drive client ID leaked into SQLite JSON")
      try expect(
        !sqliteDump.contains("google-drive-client-secret-provider-contract-sensitive-value"),
        "raw Google Drive client secret leaked into SQLite JSON")
      try expect(
        !sqliteDump.contains("google-drive-refresh-token-provider-contract-sensitive-value"),
        "raw Google Drive refresh token leaked into SQLite JSON")
      try expect(
        !sqliteDump.contains("google-drive-access-token-provider-contract-sensitive-value"),
        "raw Google Drive access token leaked into SQLite JSON")
      try expect(
        !sqliteDump.contains("google-search-console-client-id-provider-contract-sensitive-value"),
        "raw Google Search Console client ID leaked into SQLite JSON")
      try expect(
        !sqliteDump.contains(
          "google-search-console-client-secret-provider-contract-sensitive-value"),
        "raw Google Search Console client secret leaked into SQLite JSON")
      try expect(
        !sqliteDump.contains(
          "google-search-console-refresh-token-provider-contract-sensitive-value"),
        "raw Google Search Console refresh token leaked into SQLite JSON")
      try expect(
        !sqliteDump.contains(
          "google-search-console-access-token-provider-contract-sensitive-value"),
        "raw Google Search Console access token leaked into SQLite JSON")
      try expect(
        !sqliteDump.contains("google-analytics-client-id-provider-contract-sensitive-value"),
        "raw Google Analytics client ID leaked into SQLite JSON")
      try expect(
        !sqliteDump.contains("google-analytics-client-secret-provider-contract-sensitive-value"),
        "raw Google Analytics client secret leaked into SQLite JSON")
      try expect(
        !sqliteDump.contains("google-analytics-refresh-token-provider-contract-sensitive-value"),
        "raw Google Analytics refresh token leaked into SQLite JSON")
      try expect(
        !sqliteDump.contains("google-analytics-access-token-provider-contract-sensitive-value"),
        "raw Google Analytics access token leaked into SQLite JSON")
      try expect(
        !sqliteDump.contains(rawMicrosoftClarityToken),
        "raw Microsoft Clarity token leaked into SQLite JSON")
      try expect(!sqliteDump.contains(rawNotionToken), "raw Notion token leaked into SQLite JSON")
      try expect(
        !sqliteDump.localizedCaseInsensitiveContains("bearer provider-contract-sensitive-value"),
        "raw bearer token leaked into SQLite JSON")
      try expect(
        sqliteDump.contains("[REDACTED]"), "provider flow should persist redacted evidence")
      try expect(
        events.value >= 3,
        "provider connection events should publish for save/flow/snapshot updates")
    }

    let reopened = try makeServices(root: root)
    let reopenedSnapshot = try reopened.providerConnections.snapshot(
      context: Self.context(roles: [.owner], workspaceId: workspaceId),
      appIdOrSlug: appId,
      now: fixedDate("2026-01-01T00:00:03Z")
    )
    try expect(
      reopenedSnapshot.connections.count == 1, "provider connection should survive relaunch")
    try expect(
      reopenedSnapshot.authorizationFlows.count == 1,
      "provider authorization flow should survive relaunch")
    try expect(
      try reopened.providerConnections.latestSnapshot(
        context: Self.context(roles: [.owner], workspaceId: workspaceId), appId: appId) != nil,
      "latest provider snapshot should be durable")
  }

  private static func testGoogleDocsProviderConnectionIsKeychainBackedAndHealthChecked() throws {
    actor StubGoogleDocsOAuthCredentialValidator: GoogleOAuthCredentialValidating {
      private var responses: [GoogleOAuthCredentialValidationResult]

      init(responses: [GoogleOAuthCredentialValidationResult]) {
        self.responses = responses
      }

      func validateCalendarCredentials(
        clientId: String,
        clientSecret: String,
        refreshToken: String,
        requiredScopes: [String]
      ) async -> GoogleOAuthCredentialValidationResult {
        GoogleOAuthCredentialValidationResult(
          status: .serviceUnavailable,
          message: "Google Calendar is not part of this Google Docs test.",
          missingScopes: requiredScopes
        )
      }

      func validateDocsCredentials(
        clientId: String,
        clientSecret: String,
        refreshToken: String,
        requiredScopes: [String]
      ) async -> GoogleOAuthCredentialValidationResult {
        guard !responses.isEmpty else {
          return GoogleOAuthCredentialValidationResult(
            status: .serviceUnavailable,
            message: "Stub Google Docs validator has no response.",
            missingScopes: requiredScopes
          )
        }
        return responses.removeFirst()
      }

      func validateSearchConsoleCredentials(
        clientId: String,
        clientSecret: String,
        refreshToken: String,
        selectedSiteUrl: String?,
        requiredScopes: [String]
      ) async -> GoogleOAuthCredentialValidationResult {
        GoogleOAuthCredentialValidationResult(
          status: .serviceUnavailable,
          message: "Google Search Console is not part of this Google Docs test.",
          missingScopes: requiredScopes,
          selectedResourceId: selectedSiteUrl
        )
      }
    }

    let root = FileManager.default.temporaryDirectory
      .appendingPathComponent("RelayConsoleGoogleDocsProviderConnectionTests", isDirectory: true)
      .appendingPathComponent(UUID().uuidString, isDirectory: true)
    let services = try makeServices(root: root)
    let workspace = try unwrap(services.data.getAppState().activeWorkspace, "missing workspace")
    let owner = Self.context(
      roles: [.owner], workspaceId: workspace.id, correlationId: "google-docs-connection-owner-001")
    let admin = Self.context(
      roles: [.admin], workspaceId: workspace.id, correlationId: "google-docs-connection-admin-001")

    let googleDocsApp = marketplaceApp(
      workspaceId: workspace.id,
      slug: "google-docs",
      name: "Google Docs",
      summary: "User-owned Google Docs OAuth connection.",
      category: "Documents",
      riskLevel: .high,
      connectionState: .none,
      installState: .notInstalled
    )
    _ = try services.applications.saveCatalogApps(context: owner, apps: [googleDocsApp])

    let validationService = ProviderConnectionService(
      data: services.data,
      secrets: services.secrets,
      googleOAuthValidator: StubGoogleDocsOAuthCredentialValidator(responses: [
        GoogleOAuthCredentialValidationResult(
          status: .ready,
          message:
            "Google Docs OAuth credentials verified with a bounded OAuth refresh and Docs scope check.",
          grantedScopes: ProviderConnectionService.googleDocsOAuthScopes,
          httpStatusCode: 200
        ),
        GoogleOAuthCredentialValidationResult(
          status: .invalidCredentials,
          message:
            "Google rejected the OAuth credentials (invalid_grant). Reconnect Google Docs with current user-owned credentials.",
          missingScopes: ProviderConnectionService.googleDocsOAuthScopes,
          httpStatusCode: 400
        ),
      ])
    )
    let reconnectValidationService = ProviderConnectionService(
      data: services.data,
      secrets: services.secrets,
      googleOAuthValidator: StubGoogleDocsOAuthCredentialValidator(responses: [
        GoogleOAuthCredentialValidationResult(
          status: .ready,
          message:
            "Google Docs OAuth credentials verified with a bounded OAuth refresh and Docs scope check.",
          grantedScopes: ProviderConnectionService.googleDocsOAuthScopes,
          httpStatusCode: 200
        )
      ])
    )

    let connection = try services.providerConnections.saveGoogleDocsOAuthCredentials(
      context: owner,
      appIdOrSlug: googleDocsApp.slug,
      clientId: "google-docs-client-id-provider-contract-sensitive-value",
      clientSecret: "google-docs-client-secret-provider-contract-sensitive-value",
      refreshToken: "google-docs-refresh-token-provider-contract-sensitive-value",
      accessToken: "google-docs-access-token-provider-contract-sensitive-value",
      accountEmail: "relay.docs@example.com",
      projectId: "relay-docs-project",
      displayName: "Relay Google Docs Account",
      now: fixedDate("2026-01-01T00:00:00Z")
    )
    try expect(
      connection.status == .connected,
      "Google Docs OAuth credentials should create an assignable connection")
    try expect(
      connection.authorizationState == .completed,
      "Google Docs OAuth credentials should not wait for Relay callback authorization")
    try expect(
      connection.credentialOwnership == .userOwned,
      "Google Docs OAuth credentials should record user-owned ownership")
    try expect(
      connection.secretReferenceIds.count == 4,
      "Google Docs OAuth fields should each use Keychain references when supplied")
    try expect(
      connection.requiredScopes == ProviderConnectionService.googleDocsOAuthScopes,
      "Google Docs required scopes should be explicit")
    try expect(
      connection.grantedScopes == ProviderConnectionService.googleDocsOAuthScopes,
      "Google Docs granted scopes should be recorded")
    try expect(
      connection.callbackURL == nil,
      "Google Docs credential mode must not retain a Relay, Railway, or web callback URL")
    try expect(
      connection.health.diagnostics["callbackURLRequired"] == .bool(false),
      "Google Docs diagnostics should state no callback URL is required")
    try expect(
      connection.health.diagnostics["relayOwnedGoogleApp"] == .bool(false),
      "Google Docs connection must not represent a shared Relay-owned Google app")
    try expect(
      connection.health.diagnostics["docsOnlyV1"] == .bool(true),
      "Google Docs diagnostics should retain Docs-only V1 evidence")
    try expect(
      connection.health.diagnostics["driveSearchEnabled"] == .bool(false),
      "Google Docs diagnostics should not enable Drive search")
    try expect(
      connection.health.diagnostics["projectId"] == .string("relay-docs-project"),
      "Google Docs project id should be retained as non-secret metadata")
    try expect(
      connection.health.diagnostics["scopePreset"] == .string("docs_readonly_documents"),
      "Google Docs diagnostics should retain the V1 scope preset")

    let credentialByKey = Dictionary(
      uniqueKeysWithValues: connection.credentialRequirements.map { ($0.fieldKey, $0) })
    try expect(
      credentialByKey["google_docs_oauth_client_id"]?.required == true,
      "Google Docs client ID should be required")
    try expect(
      credentialByKey["google_docs_oauth_client_secret"]?.required == true,
      "Google Docs client secret should be required")
    try expect(
      credentialByKey["google_docs_oauth_refresh_token"]?.required == true,
      "Google Docs refresh token should be required")
    try expect(
      credentialByKey["google_docs_oauth_access_token"]?.required == false,
      "Google Docs access token should remain optional")
    try expect(
      credentialByKey["google_cloud_project_id"]?.required == false,
      "Google Docs project id should remain optional")
    try expect(
      credentialByKey["google_cloud_project_id"]?.secretReferenceId == nil,
      "Google Docs project id should be non-secret metadata")
    let savedSecrets = try connection.secretReferenceIds.map {
      try services.secrets.getSecretValue($0)
    }
    try expect(
      savedSecrets.contains("google-docs-client-id-provider-contract-sensitive-value"),
      "Google Docs client ID should be retrievable only through SecretService")
    try expect(
      savedSecrets.contains("google-docs-client-secret-provider-contract-sensitive-value"),
      "Google Docs client secret should be retrievable only through SecretService")
    try expect(
      savedSecrets.contains("google-docs-refresh-token-provider-contract-sensitive-value"),
      "Google Docs refresh token should be retrievable only through SecretService")
    try expect(
      savedSecrets.contains("google-docs-access-token-provider-contract-sensitive-value"),
      "Google Docs access token should be retrievable only through SecretService")

    let snapshot = try services.providerConnections.snapshot(
      context: admin, appIdOrSlug: googleDocsApp.id, now: fixedDate("2026-01-01T00:00:00Z"))
    try expect(
      snapshot.selectedConnection?.status == .connected,
      "Google Docs OAuth snapshot should stay connected")
    try expect(
      snapshot.authorizationFlows.isEmpty,
      "Google Docs OAuth credential mode should not create an OAuth authorization flow")

    let checked = try awaitResult {
      try await validationService.validateSavedGoogleDocsConnection(
        context: owner,
        connectionId: connection.id,
        now: fixedDate("2026-01-01T00:00:01Z")
      )
    }
    try expect(
      checked.status == .connected,
      "Google Docs health check should keep readable valid credentials connected")
    try expect(
      checked.health.state == .ready,
      "Google Docs health check should mark validated credentials ready")
    try expect(
      checked.health.diagnostics["validation"]
        == .string(GoogleOAuthCredentialValidationStatus.ready.rawValue),
      "Google Docs ready health should retain validation status")
    try expect(
      checked.health.diagnostics["healthCheck"] == .string("google_oauth_refresh_docs_scope"),
      "Google Docs health should name the bounded token/scope check")
    try expect(
      checked.health.diagnostics["httpStatusCode"] == .number(200),
      "Google Docs health should retain redacted HTTP evidence")
    try expect(
      checked.health.diagnostics["driveSearchEnabled"] == .bool(false),
      "Google Docs health should continue to disable Drive search")
    try expect(
      checked.health.missingScopes.isEmpty,
      "Google Docs ready health should not report missing scopes")
    try expect(
      !checked.reauthorizeRequired, "Google Docs ready health should not require reauthorization")

    var missingSecret = checked
    missingSecret.credentialRequirements = missingSecret.credentialRequirements.map { requirement in
      var copy = requirement
      if copy.fieldKey == "google_docs_oauth_refresh_token" {
        copy.secretReferenceId = nil
        copy.status = .missing
      }
      return copy
    }
    missingSecret.secretReferenceIds = missingSecret.credentialRequirements.compactMap(
      \.secretReferenceId)
    _ = try services.data.saveProviderConnection(missingSecret)
    let missing = try awaitResult {
      try await validationService.validateSavedGoogleDocsConnection(
        context: owner,
        connectionId: checked.id,
        now: fixedDate("2026-01-01T00:00:02Z")
      )
    }
    let missingCredentialByKey = Dictionary(
      uniqueKeysWithValues: missing.credentialRequirements.map { ($0.fieldKey, $0) })
    try expect(
      missing.status == .authRequired,
      "Missing Google Docs OAuth reference should require reconnect")
    try expect(
      missing.reauthorizeRequired,
      "Missing Google Docs OAuth reference should request reauthorization")
    try expect(
      missing.health.diagnostics["validation"]
        == .string(GoogleOAuthCredentialValidationStatus.missingSecret.rawValue),
      "Missing Google Docs OAuth reference should retain validation status")
    try expect(
      missingCredentialByKey["google_docs_oauth_refresh_token"]?.status == .missing,
      "Missing Google Docs refresh token should mark the credential field missing")

    _ = try services.data.saveProviderConnection(checked)
    var unreadableSecret = checked
    unreadableSecret.credentialRequirements = unreadableSecret.credentialRequirements.map {
      requirement in
      var copy = requirement
      if copy.fieldKey == "google_docs_oauth_client_secret" {
        copy.secretReferenceId = "sec-google-docs-unreadable-001"
        copy.status = .unavailable
      }
      return copy
    }
    unreadableSecret.secretReferenceIds = unreadableSecret.credentialRequirements.compactMap(
      \.secretReferenceId)
    _ = try services.data.saveProviderConnection(unreadableSecret)
    let unreadable = try awaitResult {
      try await validationService.validateSavedGoogleDocsConnection(
        context: owner,
        connectionId: checked.id,
        now: fixedDate("2026-01-01T00:00:03Z")
      )
    }
    let unreadableCredentialByKey = Dictionary(
      uniqueKeysWithValues: unreadable.credentialRequirements.map { ($0.fieldKey, $0) })
    try expect(
      unreadable.status == .authRequired,
      "Unreadable Google Docs OAuth reference should require reconnect")
    try expect(
      unreadable.reauthorizeRequired,
      "Unreadable Google Docs OAuth reference should request reauthorization")
    try expect(
      unreadable.health.diagnostics["validation"]
        == .string(GoogleOAuthCredentialValidationStatus.secretUnavailable.rawValue),
      "Unreadable Google Docs OAuth reference should retain validation status")
    try expect(
      unreadableCredentialByKey["google_docs_oauth_client_secret"]?.status == .unavailable,
      "Unreadable Google Docs client secret should mark the credential field unavailable")

    _ = try services.data.saveProviderConnection(checked)
    let invalid = try awaitResult {
      try await validationService.validateSavedGoogleDocsConnection(
        context: owner,
        connectionId: checked.id,
        now: fixedDate("2026-01-01T00:00:04Z")
      )
    }
    try expect(
      invalid.status == .authRequired,
      "Invalid Google Docs OAuth credentials should require reconnect")
    try expect(
      invalid.reauthorizeRequired,
      "Invalid Google Docs OAuth credentials should request reauthorization")
    try expect(
      invalid.health.diagnostics["validation"]
        == .string(GoogleOAuthCredentialValidationStatus.invalidCredentials.rawValue),
      "Invalid Google Docs OAuth credentials should retain validation status")
    try expect(
      invalid.health.diagnostics["httpStatusCode"] == .number(400),
      "Invalid Google Docs OAuth credentials should retain redacted HTTP status")
    try expect(
      invalid.lastError?.contains("invalid_grant") == true,
      "Invalid Google Docs OAuth credentials should retain actionable redacted error")

    let reconnected = try services.providerConnections.saveGoogleDocsOAuthCredentials(
      context: owner,
      appIdOrSlug: googleDocsApp.slug,
      clientId: "google-docs-reconnected-client-id-provider-contract-sensitive-value",
      clientSecret: "google-docs-reconnected-client-secret-provider-contract-sensitive-value",
      refreshToken: "google-docs-reconnected-refresh-token-provider-contract-sensitive-value",
      accessToken: "google-docs-reconnected-access-token-provider-contract-sensitive-value",
      accountEmail: "relay.docs.reconnected@example.com",
      projectId: "relay-docs-project",
      displayName: "Relay Google Docs Account",
      now: fixedDate("2026-01-01T00:00:05Z")
    )
    let rechecked = try awaitResult {
      try await reconnectValidationService.validateSavedGoogleDocsConnection(
        context: owner,
        connectionId: reconnected.id,
        now: fixedDate("2026-01-01T00:00:06Z")
      )
    }
    try expect(
      rechecked.status == .connected,
      "Reconnected Google Docs OAuth credentials should validate as connected")
    try expect(
      rechecked.health.diagnostics["validation"]
        == .string(GoogleOAuthCredentialValidationStatus.ready.rawValue),
      "Reconnected Google Docs OAuth credentials should retain ready validation")
    try expect(
      !rechecked.reauthorizeRequired,
      "Reconnected Google Docs OAuth credentials should clear reauthorization")

    let retained = try services.database.all(
      """
      SELECT connection_json AS value FROM applications_provider_connections
      UNION ALL
      SELECT snapshot_json AS value FROM applications_provider_connection_snapshots
      UNION ALL
      SELECT label AS value FROM secret_references
      """
    ).compactMap { sqliteText($0["value"]) }.joined(separator: "\n")
    for raw in [
      "google-docs-client-id-provider-contract-sensitive-value",
      "google-docs-client-secret-provider-contract-sensitive-value",
      "google-docs-refresh-token-provider-contract-sensitive-value",
      "google-docs-access-token-provider-contract-sensitive-value",
      "google-docs-reconnected-client-id-provider-contract-sensitive-value",
      "google-docs-reconnected-client-secret-provider-contract-sensitive-value",
      "google-docs-reconnected-refresh-token-provider-contract-sensitive-value",
      "google-docs-reconnected-access-token-provider-contract-sensitive-value",
    ] {
      try expect(
        !retained.contains(raw), "raw Google Docs OAuth secret leaked into retained provider data")
    }
    try expect(
      retained.contains("[REDACTED]"), "Google Docs provider data should retain redacted evidence")
  }

