  private static func testGoogleSearchConsoleRailwayOwnedOAuthLifecycleIsExactScopeAndRotationSafe()
    throws
  {
    let root = FileManager.default.temporaryDirectory
      .appendingPathComponent("RelayConsoleSearchConsoleRailwayOAuthTests", isDirectory: true)
      .appendingPathComponent(UUID().uuidString, isDirectory: true)
    let services = try makeServices(root: root)
    let workspace = try unwrap(services.data.getAppState().activeWorkspace, "missing workspace")
    let owner = Self.context(
      roles: [.owner], workspaceId: workspace.id,
      correlationId: "google-search-console-railway-oauth-001")
    var app = marketplaceApp(
      workspaceId: workspace.id, slug: "google-search-console", name: "Google Search Console",
      summary: "Railway-owned exact-scope Search Console OAuth.", category: "Search Performance",
      riskLevel: .high, connectionState: .none, installState: .notInstalled)
    _ = try services.applications.saveCatalogApps(context: owner, apps: [app])
    app = try canonicalMarketplaceApp(services: services, context: owner, app: app)

    let connection = try services.providerConnections.saveGoogleSearchConsoleRelayOwnedOAuthConnection(
      context: owner, appIdOrSlug: app.slug, accessToken: "search-console-access-v1",
      refreshToken: "search-console-refresh-v1", accountEmail: "owner@example.com",
      selectedSiteUrl: "sc-domain:example.com",
      grantedScopes: ProviderConnectionService.googleSearchConsoleRelayOwnedOAuthScopes,
      expiresAt: "2026-07-12T05:00:00Z")
    try expect(connection.credentialOwnership == .relayOwned, "Search Console must be Relay-owned")
    try expect(connection.userOwnedCredentialsRequired == false, "desktop credentials must be disabled")
    try expect(connection.secretReferenceIds.count == 2, "access and refresh tokens must use separate references")
    try expect(connection.grantedScopes == ["https://www.googleapis.com/auth/webmasters.readonly"], "scope must be exact")
    try expect(connection.health.diagnostics["selectedSiteUrl"] == .string("sc-domain:example.com"), "property binding must be explicit")
    try expect(connection.health.diagnostics["writesEnabled"] == .bool(false), "writes must be disabled")
    try expect(connection.health.diagnostics["automaticPagination"] == .bool(false), "automatic pagination must be disabled")
    let originalRefresh = connection.credentialRequirements.first {
      $0.fieldKey == "google_search_console_oauth_refresh_token"
    }?.secretReferenceId

    let rotated = try services.providerConnections.rotateGoogleSearchConsoleRelayOwnedOAuthTokens(
      context: owner, connectionId: connection.id, accessToken: "search-console-access-v2",
      refreshToken: nil, expiresAt: "2026-07-12T06:00:00Z")
    let retainedRefresh = rotated.credentialRequirements.first {
      $0.fieldKey == "google_search_console_oauth_refresh_token"
    }?.secretReferenceId
    try expect(retainedRefresh == originalRefresh, "access rotation must retain the durable refresh token")
    try expect(rotated.secretReferenceIds.count == 2, "rotation must preserve exactly two token references")

    var rejectedBroadScope = false
    do {
      _ = try services.providerConnections.saveGoogleSearchConsoleRelayOwnedOAuthConnection(
        context: owner, appIdOrSlug: app.slug, accessToken: "bad-access",
        refreshToken: "bad-refresh", accountEmail: "owner@example.com",
        selectedSiteUrl: "sc-domain:example.com",
        grantedScopes: ["https://www.googleapis.com/auth/webmasters"], expiresAt: nil)
    } catch { rejectedBroadScope = true }
    try expect(rejectedBroadScope, "broad Search Console scope must fail closed")
  }

