      missingScope.health.missingScopes == ProviderConnectionService.googleSearchConsoleOAuthScopes,
      "Missing scope health should retain webmasters.readonly")
    try expect(
      missingScope.health.unavailableTools.contains("google_search_console_search_analytics_query"),
      "Missing scope should suppress Search Console read tools")

    _ = try services.data.saveProviderConnection(checked)
    let noProperties = try awaitResult {
      try await validationService.validateSavedGoogleSearchConsoleConnection(
        context: owner,
        connectionId: checked.id,
        now: fixedDate("2026-01-01T00:00:06Z")
      )
    }
    try expect(
      noProperties.status == .healthError,
      "No accessible Search Console properties should be a health error")
    try expect(
      !noProperties.reauthorizeRequired,
      "No accessible Search Console properties should not request OAuth reauthorization")
    try expect(
      noProperties.health.diagnostics["validation"]
        == .string(GoogleOAuthCredentialValidationStatus.noProperties.rawValue),
      "No properties health should retain validation status")
    try expect(
      noProperties.health.diagnostics["accessiblePropertyCount"] == .number(0),
      "No properties health should retain zero property count")

    _ = try services.data.saveProviderConnection(checked)
    let selectedUnavailable = try awaitResult {
      try await validationService.validateSavedGoogleSearchConsoleConnection(
        context: owner,
        connectionId: checked.id,
        now: fixedDate("2026-01-01T00:00:07Z")
      )
    }
    let selectedUnavailableCredentialByKey = Dictionary(
      uniqueKeysWithValues: selectedUnavailable.credentialRequirements.map { ($0.fieldKey, $0) })
    try expect(
      selectedUnavailable.status == .healthError,
      "Inaccessible selected Search Console property should be a health error")
    try expect(
      !selectedUnavailable.reauthorizeRequired,
      "Inaccessible selected Search Console property should not request OAuth reauthorization")
    try expect(
      selectedUnavailable.health.diagnostics["validation"]
        == .string(GoogleOAuthCredentialValidationStatus.selectedPropertyUnavailable.rawValue),
      "Selected property health should retain validation status")
    try expect(
      selectedUnavailableCredentialByKey["google_search_console_default_site_url"]?.status
        == .unavailable,
      "Inaccessible selected Search Console property should mark property metadata unavailable")

    let reconnected = try services.providerConnections.saveGoogleSearchConsoleOAuthCredentials(
      context: owner,
      appIdOrSlug: googleSearchConsoleApp.slug,
      clientId: "google-search-console-reconnected-client-id-provider-contract-sensitive-value",
      clientSecret:
        "google-search-console-reconnected-client-secret-provider-contract-sensitive-value",
      refreshToken:
        "google-search-console-reconnected-refresh-token-provider-contract-sensitive-value",
      accessToken:
        "google-search-console-reconnected-access-token-provider-contract-sensitive-value",
      accountEmail: "relay.search.console.reconnected@example.com",
      projectId: "relay-search-console-project",
      defaultSiteUrl: "https://reconnected.example.com/",
      displayName: "Relay Search Console Account",
      now: fixedDate("2026-01-01T00:00:08Z")
    )
    let rechecked = try awaitResult {
      try await reconnectValidationService.validateSavedGoogleSearchConsoleConnection(
        context: owner,
        connectionId: reconnected.id,
        now: fixedDate("2026-01-01T00:00:09Z")
      )
    }
    try expect(
      rechecked.status == .connected,
      "Reconnected Google Search Console OAuth credentials should validate as connected")
    try expect(
      rechecked.health.diagnostics["validation"]
        == .string(GoogleOAuthCredentialValidationStatus.ready.rawValue),
      "Reconnected Google Search Console credentials should retain ready validation")
    try expect(
      rechecked.health.diagnostics["selectedSiteUrl"]
        == .string("https://reconnected.example.com/"),
      "Reconnected Google Search Console credentials should retain the new selected property")
    try expect(
      !rechecked.reauthorizeRequired,
      "Reconnected Google Search Console credentials should clear reauthorization")

    let relayOwnedConnection = try services.providerConnections
      .saveGoogleSearchConsoleOAuthCredentials(
        context: owner,
        appIdOrSlug: googleSearchConsoleApp.slug,
        clientId: "google-search-console-relay-client-id-provider-contract-sensitive-value",
        clientSecret: "google-search-console-relay-client-secret-provider-contract-sensitive-value",
        refreshToken: "google-search-console-relay-refresh-token-provider-contract-sensitive-value",
        accessToken: "google-search-console-relay-access-token-provider-contract-sensitive-value",
        accountEmail: nil,
        projectId: nil,
        defaultSiteUrl: "sc-domain:relay-owned-example.com",
        displayName: "Relay-Owned Search Console",
        credentialOwnership: .relayOwned,
        userOwnedCredentialsRequired: false,
        relayOwnedGoogleApp: true,
        providerKey: "google-search-console-relay-oauth",
        scopes: ProviderConnectionService.googleSearchConsoleOAuthScopes,
        now: fixedDate("2026-01-01T00:00:10Z")
      )
    try expect(
      relayOwnedConnection.providerKey == "google-search-console-relay-oauth",
      "Relay-owned Google Search Console connection should record the Relay provider key")
    try expect(
      relayOwnedConnection.credentialOwnership == .relayOwned,
      "Relay-owned Google Search Console connection should record Relay ownership")
    try expect(
      !relayOwnedConnection.userOwnedCredentialsRequired,
      "Relay-owned Google Search Console connection should not require user-owned developer credentials"
    )
    try expect(
      relayOwnedConnection.requiredScopes
        == ProviderConnectionService.googleSearchConsoleOAuthScopes,
      "Relay-owned Google Search Console should keep the read-only scope")
    try expect(
      relayOwnedConnection.health.diagnostics["authMethod"]
        == .string("google_oauth_relay_owned_search_console"),
      "Relay-owned Google Search Console diagnostics should record Relay OAuth")
    try expect(
      relayOwnedConnection.health.diagnostics["relayOwnedGoogleApp"] == .bool(true),
      "Relay-owned Google Search Console diagnostics should mark Relay-owned Google app support")
    try expect(
      relayOwnedConnection.health.diagnostics["selectedSiteUrl"]
        == .string("sc-domain:relay-owned-example.com"),
      "Relay-owned Google Search Console should retain selected property metadata")
    let relayOwnedCredentialByKey = Dictionary(
      uniqueKeysWithValues: relayOwnedConnection.credentialRequirements.map { ($0.fieldKey, $0) })
    try expect(
      relayOwnedCredentialByKey["google_search_console_oauth_client_id"]?.userOwnedRequired
        == false, "Relay-owned Google Search Console client ID should not be user-owned required")
    try expect(
      relayOwnedCredentialByKey["google_search_console_oauth_client_secret"]?.userOwnedRequired
        == false,
      "Relay-owned Google Search Console client secret should not be user-owned required")
    try expect(
      relayOwnedCredentialByKey["google_search_console_oauth_refresh_token"]?.userOwnedRequired
        == false,
      "Relay-owned Google Search Console refresh token should not be user-owned required")

    let retained = try services.database.all(
      """
      SELECT connection_json AS value FROM applications_provider_connections
      UNION ALL
      SELECT snapshot_json AS value FROM applications_provider_connection_snapshots
      UNION ALL
      SELECT label AS value FROM secret_references
      """
    ).compactMap { sqliteText($0["value"]) }.joined(separator: "\n")
    for rawSecret in [
      "google-search-console-client-id-provider-contract-sensitive-value",
      "google-search-console-client-secret-provider-contract-sensitive-value",
      "google-search-console-refresh-token-provider-contract-sensitive-value",
      "google-search-console-access-token-provider-contract-sensitive-value",
      "google-search-console-reconnected-client-id-provider-contract-sensitive-value",
      "google-search-console-reconnected-client-secret-provider-contract-sensitive-value",
      "google-search-console-reconnected-refresh-token-provider-contract-sensitive-value",
      "google-search-console-reconnected-access-token-provider-contract-sensitive-value",
      "google-search-console-relay-client-id-provider-contract-sensitive-value",
      "google-search-console-relay-client-secret-provider-contract-sensitive-value",
      "google-search-console-relay-refresh-token-provider-contract-sensitive-value",
      "google-search-console-relay-access-token-provider-contract-sensitive-value",
    ] {
      try expect(
        !retained.contains(rawSecret),
        "raw Google Search Console credential leaked into retained provider data")
    }
    try expect(
      retained.contains("[REDACTED]"),
      "Google Search Console provider data should retain redacted evidence")
#endif
    let services = try makeServices()
    let workspace = try unwrap(services.data.getAppState().activeWorkspace, "missing workspace")
    let owner = Self.context(
      roles: [.owner], workspaceId: workspace.id,
      correlationId: "google-search-console-desktop-denial-001")
    var app = marketplaceApp(
      workspaceId: workspace.id,
      slug: "google-search-console",
      name: "Google Search Console",
      summary: "Railway-owned Google Search Console OAuth connection.",
      category: "Search Performance",
      riskLevel: .high,
      connectionState: .none,
      installState: .notInstalled
    )
    _ = try services.applications.saveCatalogApps(context: owner, apps: [app])
    app = try canonicalMarketplaceApp(services: services, context: owner, app: app)
    do {
      _ = try services.providerConnections.saveGoogleSearchConsoleOAuthCredentials(
        context: owner,
        appIdOrSlug: app.slug,
        clientId: "must-not-persist-client-id",
        clientSecret: "must-not-persist-client-secret",
        refreshToken: "must-not-persist-refresh-token",
        accessToken: nil,
        accountEmail: nil,
        projectId: nil,
        defaultSiteUrl: "sc-domain:example.com",
        displayName: "Rejected desktop connection"
      )
      throw ServiceTestFailure("desktop Search Console credentials unexpectedly succeeded")
    } catch let denied as ServiceGuardResult {
      try expect(
        denied.reasonCode == .inputInvalid,
        "desktop Search Console credentials should fail closed")
    }
    let snapshot = try services.providerConnections.snapshot(context: owner, appIdOrSlug: app.slug)
    try expect(
      snapshot.selectedConnection == nil && snapshot.connections.isEmpty,
      "rejected desktop Search Console credentials should not persist connection state")
    let retained = try services.database.all(
      "SELECT connection_json AS value FROM applications_provider_connections"
    ).compactMap { sqliteText($0["value"]) }.joined(separator: "\n")
    try expect(
      !retained.contains("must-not-persist"),
      "rejected desktop Search Console credentials should not reach the database")
  }

  private static func testGoogleSearchConsoleProviderFoundationEnforcesReadOnlySearchPolicy() throws
  {
    let services = try makeServices()
    let workspace = try unwrap(services.data.getAppState().activeWorkspace, "missing workspace")
    let owner = Self.context(
      roles: [.owner], workspaceId: workspace.id,
      correlationId: "google-search-console-foundation-owner-001")
    let member = Self.context(
      roles: [.member], workspaceId: workspace.id,
      correlationId: "google-search-console-foundation-member-001")

    do {
      _ = try services.providerFoundations.registerGoogleSearchConsoleFoundation(
        context: member,
        now: fixedDate("2026-01-01T00:00:00Z")
      )
      throw ServiceTestFailure(
        "member unexpectedly registered Google Search Console provider foundation")
    } catch let denied as ServiceGuardResult {
      try expect(
        denied.reasonCode == .authorityRoleRequired,
        "Google Search Console foundation registration should require owner/admin authority")
    }

    let snapshot = try services.providerFoundations.registerGoogleSearchConsoleFoundation(
      context: owner,
      now: fixedDate("2026-01-01T00:00:01Z")
    )
    try expect(
      snapshot.appSlug == "google-search-console",
      "Google Search Console foundation should target the canonical app")
    try expect(
      snapshot.providerName == "Google Search Console",
      "Google Search Console foundation should retain the canonical provider name")
    try expect(
      snapshot.providerFamily == "search-performance",
      "Google Search Console foundation should mark search-performance provider family")
    try expect(
      snapshot.connectionMode == "relay-owned-google-oauth-search-console",
      "Google Search Console foundation should use Relay-owned OAuth mode")
    try expect(
      snapshot.credentialOwnership == .relayOwned,
      "Google Search Console foundation should record Relay-owned credentials")
    try expect(
      !snapshot.userOwnedCredentialsRequired,
      "Google Search Console foundation should not require user-owned credential entry for Relay-owned OAuth"
    )
    try expect(
      snapshot.supportedPolicyPresets == [.readOnly, .blocked],
      "Google Search Console V1 should advertise only read-only and blocked policies")
    try expect(
      snapshot.defaultPolicyPreset == .readOnly,
      "Google Search Console foundation should default to read-only policy")
    try expect(
      snapshot.adapterBoundary == "brokered-native-google-search-console-api-adapter",
      "Google Search Console foundation should keep API access behind the broker boundary")
    try expect(
      snapshot.actionMapVersion == "google-search-console-v1",
      "Google Search Console foundation should identify the V1 action map")
    try expect(
      !snapshot.rawProviderToolExposure,
      "Google Search Console foundation should not expose raw provider tools")
    try expect(
      snapshot.suppressedRawProviderToolCount == 13,
      "Google Search Console foundation should count read and blocked V1 provider actions as suppressed raw tools"
    )
    try expect(
      snapshot.budgetPolicy["maxWrapperTools"] == .number(6),
      "Google Search Console foundation should budget six wrapper tools")
    try expect(
      snapshot.budgetPolicy["maxSearchAnalyticsRows"] == .number(25),
      "Google Search Console foundation should bound Search Analytics rows")
    try expect(
      snapshot.budgetPolicy["maxSearchAnalyticsLookbackDays"] == .number(28),
      "Google Search Console foundation should bound Search Analytics lookback")
    try expect(
      snapshot.privacyPolicy["writes"] == .string("blocked"),
      "Google Search Console writes should be blocked in V1")
    try expect(
      snapshot.privacyPolicy["sitemapSubmissionAndDeletion"] == .string("blocked"),
      "Google Search Console sitemap writes should be blocked")
    try expect(
      snapshot.privacyPolicy["propertyAdministration"] == .string("blocked"),
      "Google Search Console property admin should be blocked")
    try expect(
      snapshot.privacyPolicy["broadExports"] == .string("blocked"),
      "Google Search Console broad exports should be blocked")
    try expect(
      snapshot.privacyPolicy["testingToolsAPI"] == .string("blocked"),
      "Google Search Console Testing Tools API should be out of V1")
    try expect(
      snapshot.privacyPolicy["rawAPIExposure"] == .string("blocked"),
      "Google Search Console raw API exposure should be blocked")
    try expect(
      snapshot.privacyPolicy["relayOwnedGoogleApp"] == .string("supported"),
      "Google Search Console Relay-owned Google OAuth should be supported")
    try expect(
      snapshot.privacyPolicy["rawCredentials"] == .string("secret-reference-only"),
      "Google Search Console raw credentials should stay behind secret references")

    let app = try unwrap(
      try services.data.getMarketplaceCatalogApp(
        workspaceId: workspace.id, appIdOrSlug: snapshot.appId),
      "missing Google Search Console app"
    )
    try expect(
      app.slug == "google-search-console",
      "Google Search Console catalog app should retain the intended slug")
    try expect(
      app.name == "Google Search Console",
      "Google Search Console catalog app should retain the canonical app name")
    try expect(
      app.websiteURL == "https://search.google.com/search-console",
      "Google Search Console app should retain the official website")
    try expect(
      app.docsURL == "https://developers.google.com/webmaster-tools",
      "Google Search Console app should retain official developer docs")
    try expect(
      app.connectionTypes?.contains("relay_owned_global_oauth") == true,
      "Google Search Console app should use Relay-owned Google OAuth")
    try expect(app.readOnly, "Google Search Console app should be read-only in V1")
    let roleDefinitions = app.roleManifest.roleDefinitions ?? []
    try expect(
      roleDefinitions.allSatisfy { !$0.canWrite && $0.readOnly },
      "Google Search Console role manifest should not grant write authority")
    try expect(
      roleDefinitions.contains {
        $0.blockedActions.contains("google_search_console_sitemap_submit")
      }, "Google Search Console role manifest should block sitemap submit")
    try expect(
      roleDefinitions.contains { $0.blockedActions.contains("google_search_console_site_delete") },
      "Google Search Console role manifest should block site delete")
    try expect(
      !app.capabilities.contains { $0.localizedCaseInsensitiveContains("submit sitemap") },
      "Google Search Console capabilities should not advertise sitemap writes")

    try expect(
      snapshot.credentials.map(\.fieldKey) == [
        "google_search_console_oauth_client_id",
        "google_search_console_oauth_client_secret",
        "google_search_console_oauth_refresh_token",
        "google_search_console_oauth_access_token",
        "google_search_console_project_id",
        "google_search_console_default_site_url",
      ],
      "Google Search Console foundation should list OAuth secrets plus project/property metadata"
    )
    let credentialByKey = Dictionary(
      uniqueKeysWithValues: snapshot.credentials.map { ($0.fieldKey, $0) })
    try expect(
      credentialByKey["google_search_console_oauth_client_id"]?.secretStorage
        == "keychain-reference-only",
      "Google Search Console client ID should be Keychain-reference only")
    try expect(
      credentialByKey["google_search_console_oauth_client_id"]?.userOwnedRequired == false,
      "Google Search Console client ID should not be user-owned required for Relay-owned OAuth")
    try expect(
      credentialByKey["google_search_console_oauth_client_secret"]?.secretStorage
        == "keychain-reference-only",
      "Google Search Console client secret should be Keychain-reference only")
    try expect(
      credentialByKey["google_search_console_oauth_client_secret"]?.userOwnedRequired == false,
      "Google Search Console client secret should not be user-owned required for Relay-owned OAuth")
    try expect(
      credentialByKey["google_search_console_oauth_refresh_token"]?.required == true,
      "Google Search Console refresh token should be required")
    try expect(
      credentialByKey["google_search_console_oauth_refresh_token"]?.userOwnedRequired == false,
      "Google Search Console refresh token should not be user-owned required for Relay-owned OAuth")
    try expect(
      credentialByKey["google_search_console_oauth_access_token"]?.required == false,
      "Google Search Console access token should be optional")
    try expect(
      credentialByKey["google_search_console_project_id"]?.secretStorage == "metadata-only",
      "Google Search Console project ID should be non-secret metadata")
    try expect(
      credentialByKey["google_search_console_default_site_url"]?.required == true,
      "Google Search Console selected property should be required before assignment")
    try expect(
      credentialByKey["google_search_console_default_site_url"]?.secretStorage == "metadata-only",
      "Google Search Console selected property should be non-secret metadata")

    let expectedReadActions: Set<String> = [
      "google_search_console_properties_list",
      "google_search_console_property_get",
      "google_search_console_search_analytics_query",
      "google_search_console_url_inspect",
      "google_search_console_sitemaps_list",
      "google_search_console_sitemap_get",
    ]
    let expectedBlockedActions: Set<String> = [
      "google_search_console_sitemap_submit",
      "google_search_console_sitemap_delete",
      "google_search_console_site_add",
      "google_search_console_site_delete",
      "google_search_console_broad_export",
      "google_search_console_testing_tools_api",
      "google_search_console_raw_api_call",
    ]
    let expectedWrapperNames: Set<String> = [
      "relay_google_search_console_list_properties",
      "relay_google_search_console_get_property",
      "relay_google_search_console_query_search_analytics",
      "relay_google_search_console_inspect_url",
      "relay_google_search_console_list_sitemaps",
      "relay_google_search_console_get_sitemap",
    ]
    let actionByKey = Dictionary(uniqueKeysWithValues: snapshot.actions.map { ($0.actionKey, $0) })
    try expect(
      Set(actionByKey.keys) == expectedReadActions.union(expectedBlockedActions),
      "Google Search Console foundation should register the complete V1 action map")
    for actionKey in expectedReadActions {
      try expect(
        actionByKey[actionKey]?.policyPermission == .allowed,
        "Google Search Console read action \(actionKey) should be allowed by read-only policy")
      try expect(
        actionByKey[actionKey]?.requiredScopes == [
          "https://www.googleapis.com/auth/webmasters.readonly"
        ], "Google Search Console read action \(actionKey) should require only webmasters.readonly")
      try expect(
        actionByKey[actionKey]?.wrapperToolName.map { expectedWrapperNames.contains($0) } == true,
        "Google Search Console read action \(actionKey) should expose the documented Relay wrapper")
    }
    for actionKey in expectedBlockedActions {
      try expect(
        actionByKey[actionKey]?.policyPermission == .blocked,
        "Google Search Console blocked action \(actionKey) should stay blocked")
      try expect(
        actionByKey[actionKey]?.requiredScopes.isEmpty == true,
        "Google Search Console blocked action \(actionKey) should not request broader scopes")
      try expect(
        actionByKey[actionKey]?.wrapperToolName == nil,
        "Google Search Console blocked action \(actionKey) should not have an agent-facing wrapper")
    }
    try expect(
      Set(snapshot.agentFacingWrapperToolNames) == expectedWrapperNames,
      "Google Search Console foundation should expose the six documented wrapper names")
    try expect(
      snapshot.blockedActionKeys == expectedBlockedActions.sorted(),
      "Google Search Console foundation should expose all blocked/deferred actions")

    let connection = try services.providerConnections.saveGoogleSearchConsoleRelayOwnedOAuthConnection(
      context: owner,
      appIdOrSlug: app.id,
      accessToken: "google-search-console-foundation-access-token-sensitive-value",
      refreshToken: "google-search-console-foundation-refresh-token-sensitive-value",
      accountEmail: "relay.search.console.foundation@example.com",
      selectedSiteUrl: "sc-domain:foundation.example.com",
      grantedScopes: ProviderConnectionService.googleSearchConsoleRelayOwnedOAuthScopes,
      expiresAt: "2026-01-01T01:00:02Z"
    )
    let agent = try createServiceAgent(services: services, workspaceId: workspace.id)
    let install = try services.marketplaceInstalls.createInstall(
      context: owner,
      request: installRequest(
        id: "minreq-google-search-console-foundation-001",
        workspaceId: workspace.id,
        app: app,
        connectionId: connection.id,
        agent: agent,
        roleId: app.roleManifest.primaryRole,
        selectedCapabilities: app.capabilities,
        riskAcknowledged: true
      ),
      now: fixedDate("2026-01-01T00:00:03Z")
    )
    let readOnly = try services.providerActionPolicies.compilePolicyMap(
      context: owner,
      appIdOrSlug: app.id,
      preset: .readOnly,
      connectionId: connection.id,
      installId: install.id,
      agentId: agent.id,
      now: fixedDate("2026-01-01T00:00:04Z")
    )
    for actionKey in expectedReadActions {
      try expect(
        readOnly.permissions[actionKey] == .allowed,
        "Google Search Console read-only policy should allow \(actionKey)")
    }
    for actionKey in expectedBlockedActions {
      try expect(
        readOnly.permissions[actionKey] == .blocked,
        "Google Search Console read-only policy should block \(actionKey)")
    }
    let directAttempt = try services.providerActionPolicies.compilePolicyMap(
      context: owner,
      appIdOrSlug: app.id,
      preset: .allowDirectWrites, acknowledgeDangerousPolicy: true,
      connectionId: connection.id,
      installId: install.id,
      agentId: agent.id,
      now: fixedDate("2026-01-01T00:00:05Z")
    )
    try expect(
      !directAttempt.permissions.values.contains(.autoExecute),
      "Google Search Console direct-write attempt should not create auto-execute actions")
    for actionKey in expectedBlockedActions {
      try expect(
        directAttempt.permissions[actionKey] == .blocked,
        "Google Search Console direct-write attempt should keep \(actionKey) blocked")
    }
    let blockedMap = try services.providerActionPolicies.compilePolicyMap(
      context: owner,
      appIdOrSlug: app.id,
      preset: .blocked,
      connectionId: connection.id,
      installId: install.id,
      agentId: agent.id,
      now: fixedDate("2026-01-01T00:00:06Z")
    )
    try expect(
      blockedMap.permissions.values.allSatisfy { $0 == .blocked },
      "Google Search Console No access policy should block every action")

    _ = try services.providerActionPolicies.compilePolicyMap(
      context: owner,
      appIdOrSlug: app.id,
      preset: .readOnly,
      connectionId: connection.id,
      installId: install.id,
      agentId: agent.id,
      now: fixedDate("2026-01-01T00:00:07Z")
    )
    let surface = try services.providerWrapperTools.compileSurface(
      context: member,
      appIdOrSlug: app.id,
      installId: install.id,
      agentId: agent.id,
      now: fixedDate("2026-01-01T00:00:08Z")
    )
    try expect(
      surface.tools.count == 6,
      "Google Search Console wrapper surface should expose exactly six read tools")
    try expect(
      Set(surface.tools.map(\.toolName)) == expectedWrapperNames,
      "Google Search Console wrapper surface should expose documented tool names")
    try expect(
      surface.tools.allSatisfy(\.readOnly),
      "Google Search Console wrapper surface should be read-only")
    try expect(
      surface.tools.allSatisfy { !$0.requiresApproval && !$0.autoExecutes },
      "Google Search Console read tools should not require approval or auto-execute writes")
    try expect(
      !surface.tools.contains { $0.displayName == "Submit sitemap" },
      "Google Search Console sitemap submit should not become agent-facing")
    try expect(
      surface.diagnostics.blockedActionCount == expectedBlockedActions.count,
      "Google Search Console wrapper diagnostics should count blocked/deferred actions")
    try expect(
      !surface.diagnostics.rawProviderToolExposure,
      "Google Search Console wrapper diagnostics should flag raw provider exposure as false")

    let retained = try services.database.all(
      """
      SELECT connection_json AS value FROM applications_provider_connections
      UNION ALL SELECT install_json AS value FROM applications_marketplace_installs
      """
    ).compactMap { sqliteText($0["value"]) }.joined(separator: "\n")
    for rawSecret in [
      "google-search-console-foundation-client-id-sensitive-value",
      "google-search-console-foundation-client-secret-sensitive-value",
      "google-search-console-foundation-refresh-token-sensitive-value",
      "google-search-console-foundation-access-token-sensitive-value",
    ] {
      try expect(
        !retained.contains(rawSecret), "Google Search Console storage leaked raw OAuth credential")
    }
    try expect(
      !retained.contains("relay-console://oauth/google-search-console/callback"),
      "Google Search Console user-owned OAuth mode should not persist a Relay callback URL")
    try expect(
      retained.contains("[REDACTED]"),
      "Google Search Console connection persistence should retain redaction markers")
  }

  private static func testGoogleSearchConsoleProviderActionAdapterRoutesBrokeredSafeReads() throws {
    final class StubGoogleSearchConsoleHTTPClient: GoogleSearchConsoleProviderHTTPClient,
      @unchecked Sendable
    {
      private let accessToken: String
      private let refreshToken: String

      init(accessToken: String, refreshToken: String) {
        self.accessToken = accessToken
        self.refreshToken = refreshToken
      }

      func send(_ request: GoogleSearchConsoleProviderHTTPRequest) throws
        -> GoogleSearchConsoleProviderHTTPResponse
      {
        if request.url.host == "oauth2.googleapis.com" {
          let body = String(data: request.body ?? Data(), encoding: .utf8) ?? ""
          guard request.method == "POST", body.contains(refreshToken) else {
            return GoogleSearchConsoleProviderHTTPResponse(
              statusCode: 400,
              body: Data(
                #"{"error":"invalid_grant","error_description":"missing refresh token"}"#.utf8)
            )
          }
          return GoogleSearchConsoleProviderHTTPResponse(
            statusCode: 200,
            body: Data(
              #"{"access_token":"\#(accessToken)","expires_in":3600,"scope":"https://www.googleapis.com/auth/webmasters.readonly","token_type":"Bearer"}"#
                .utf8)
          )
        }
        guard request.headers["Authorization"] == "Bearer \(accessToken)" else {
          return GoogleSearchConsoleProviderHTTPResponse(
            statusCode: 401,
            body: Data(#"{"error":{"message":"missing bearer"}}"#.utf8)
          )
        }
        guard request.method == "GET",
          request.url.host == "www.googleapis.com",
          request.url.path == "/webmasters/v3/sites"
        else {
          return GoogleSearchConsoleProviderHTTPResponse(
            statusCode: 404,
            body: Data(#"{"error":{"message":"unexpected Search Console request"}}"#.utf8)
          )
        }
        return GoogleSearchConsoleProviderHTTPResponse(
          statusCode: 200,
          body: Data(
            #"""
            {
              "siteEntry": [
                { "siteUrl": "https://example.com/", "permissionLevel": "siteOwner" },
                { "siteUrl": "sc-domain:example.org", "permissionLevel": "siteRestrictedUser" }
              ]
            }
            """#.utf8
          )
        )
      }
    }

    struct TimeoutGoogleSearchConsoleHTTPClient: GoogleSearchConsoleProviderHTTPClient {
      func send(_ request: GoogleSearchConsoleProviderHTTPRequest) throws
        -> GoogleSearchConsoleProviderHTTPResponse
      {
        throw MarketplaceProviderActionAdapterFailure(
          code: "google_search_console_http_timeout",
          message: "Google Search Console API request timed out.",
          detail: ["urlHost": .string(request.url.host ?? "google")]
        )
      }
    }

    let services = try makeServices()
    let workspace = try unwrap(services.data.getAppState().activeWorkspace, "missing workspace")
    let owner = Self.context(
      roles: [.owner], workspaceId: workspace.id,
      correlationId: "google-search-console-adapter-owner-001")

    let foundation = try services.providerFoundations.registerGoogleSearchConsoleFoundation(
      context: owner,
      now: fixedDate("2026-01-01T00:00:00Z")
    )
    let app = try unwrap(
      try services.data.getMarketplaceCatalogApp(
        workspaceId: workspace.id, appIdOrSlug: foundation.appId),
      "missing Google Search Console app"
    )
    let definitions = try services.data.listMarketplaceProviderActionDefinitions(
      workspaceId: workspace.id,
      appId: app.id
    )
    let definitionsByKey = Dictionary(uniqueKeysWithValues: definitions.map { ($0.actionKey, $0) })
    func definition(_ key: String) throws -> MarketplaceProviderActionDefinition {
      try unwrap(definitionsByKey[key], "missing Google Search Console action definition \(key)")
    }

    let auditIdentity = ProviderExecutionAuditIdentity(
      workspaceId: workspace.id,
      actorId: owner.actorId,
      actorRole: "owner",
      agentId: nil,
      appId: app.id,
      appSlug: app.slug,
      connectionId: nil,
      installId: nil,
      approvalId: nil,
      dispatchId: nil,
      threadId: nil,
      source: "google-search-console-adapter-boundary-test",
      redactionStatus: "private-state-excluded"
    )
    let fakeAdapter = GoogleSearchConsoleProviderActionAdapter(
      client: FakeGoogleSearchConsoleProviderActionClient())
    let directSearch = try fakeAdapter.execute(
      request: MarketplaceProviderActionAdapterRequest(
        context: owner,
        app: app,
        definition: definition("google_search_console_search_analytics_query"),
        permission: .allowed,
        payload: [
          "siteUrl": .string("https://example.com/"),
          "startDate": .string("2026-01-01"),
          "endDate": .string("2026-01-07"),
          "dimensions": .array([.string("query"), .string("page")]),
