              accessToken: accessToken, refreshToken: refreshToken)
          )
        )
      )
    )
    let liveList = try liveBroker.execute(
      context: owner,
      request: MarketplaceProviderActionBrokerRequest(
        appIdOrSlug: app.id,
        actionKey: "google_search_console_properties_list",
        payload: ["maxResults": .number(2)],
        connectionId: liveConnection.id,
        idempotencyKey: "google-search-console-live-properties-list-001",
        dispatchId: "rtd-google-search-console-live-properties-001"
      ),
      now: fixedDate("2026-01-01T00:00:11Z")
    )
    try expect(
      liveList.adapterExecuted,
      "Live Google Search Console read should execute through the routed adapter")
    try expect(
      liveList.execution.status == .succeeded,
