    let liveResult = try unwrap(
      liveList.execution.providerResult, "missing live Google Search Console provider result")
    try expect(
      liveResult["clientMode"] == .string("live-google-search-console-api"),
      "Live Google Search Console read should identify the live API client")
    try expect(
      liveResult["fakeAdapter"] == .bool(false),
      "Live Google Search Console read should not be marked fake")
    try expect(
      liveResult["liveCredentialsUsed"] == .bool(true),
      "Live Google Search Console read should use Relay-held credentials")
    try expect(
      liveResult["rawProviderToolExposure"] == .bool(false),
      "Live Google Search Console read should not expose raw provider tools")
    let liveProperties = arrayValue(liveResult["properties"]).compactMap(objectValue)
    try expect(
      liveProperties.count == 2,
      "Live Google Search Console read should return normalized properties")
    try expect(
      liveProperties.first?["permissionLevel"] == .string("siteOwner"),
      "Live Google Search Console read should retain permission level")

    let timeoutBroker = MarketplaceProviderActionBrokerService(
      data: services.data,
      approvals: services.providerActionApprovals,
      auditSecurity: services.auditSecurity,
      adapter: RoutingMarketplaceProviderActionAdapter(
        googleSearchConsoleAdapter: GoogleSearchConsoleProviderActionAdapter(
          client: LiveGoogleSearchConsoleProviderActionClient(
            data: services.data,
            secrets: services.secrets,
            httpClient: TimeoutGoogleSearchConsoleHTTPClient()
          )
        )
      )
    )
    let timeout = try timeoutBroker.execute(
      context: owner,
      request: MarketplaceProviderActionBrokerRequest(
        appIdOrSlug: app.id,
        actionKey: "google_search_console_properties_list",
        payload: ["maxResults": .number(1)],
        connectionId: liveConnection.id,
        idempotencyKey: "google-search-console-live-timeout-001",
        dispatchId: "rtd-google-search-console-live-timeout-001"
      ),
      now: fixedDate("2026-01-01T00:00:12Z")
    )
    try expect(
      timeout.adapterExecuted,
      "Google Search Console timeout should still attempt the routed adapter")
    try expect(
      timeout.execution.status == .failed,
      "Google Search Console timeout should persist failed execution")
    try expect(
      timeout.execution.providerError?["providerErrorCode"]
        == .string("google_search_console_http_timeout"),
      "Google Search Console timeout should map a fast-failure error code")

    let retained = try services.database.all(
      """
      SELECT connection_json AS value FROM applications_provider_connections
      UNION ALL SELECT execution_json AS value FROM marketplace_provider_action_executions
      UNION ALL SELECT context_json AS value FROM audit_log_records
      """
    ).compactMap { sqliteText($0["value"]) }.joined(separator: "\n")
    for secret in [refreshToken, accessToken] {
      try expect(
        !retained.contains(secret),
        "Google Search Console broker storage leaked raw OAuth credential")
    }
    try expect(
      !retained.localizedCaseInsensitiveContains("bearer "),
      "Google Search Console broker storage leaked bearer authorization material")
    try expect(
      retained.contains("[REDACTED]"),
      "Google Search Console broker storage should retain redaction markers")
  }

  private static func testGoogleSearchConsoleRuntimeMountExposesConfirmedBrokeredTools() throws {
    let root = FileManager.default.temporaryDirectory
      .appendingPathComponent("RelayConsoleGoogleSearchConsoleRuntimeMountTests", isDirectory: true)
      .appendingPathComponent(UUID().uuidString, isDirectory: true)
    let services = try makeServices(
      root: root,
      providerActionAdapter: RoutingMarketplaceProviderActionAdapter(
        googleSearchConsoleAdapter: GoogleSearchConsoleProviderActionAdapter(
          client: FakeGoogleSearchConsoleProviderActionClient())
      )
    )
    let workspace = try unwrap(services.data.getAppState().activeWorkspace, "missing workspace")
    let owner = Self.context(
      roles: [.owner], workspaceId: workspace.id,
      correlationId: "google-search-console-runtime-owner-001")
    let member = Self.context(
      roles: [.member], workspaceId: workspace.id,
      correlationId: "google-search-console-runtime-member-001")
    let hermesHarness = try prepareInstalledHarness(services: services, key: .hermes)
    let openClawHarness = try prepareInstalledHarness(services: services, key: .openclaw)
    let hermesHome = root.appendingPathComponent(
      "google-search-console-runtime-hermes-profile", isDirectory: true)
    let unrelatedHermesHome = root.appendingPathComponent(
      "google-search-console-runtime-unrelated-profile", isDirectory: true)
    let openClawStateDir = root.appendingPathComponent(
      "google-search-console-runtime-openclaw-home", isDirectory: true)
    let openClawAgentDir = openClawStateDir.appendingPathComponent(
      "agents/google-search-console-runtime-openclaw/agent", isDirectory: true)
    let openClawWorkspaceDir = openClawStateDir.appendingPathComponent(
      "workspace-google-search-console-runtime-openclaw", isDirectory: true)
    let hermesAgent = try services.data.createAgent(
      workspaceId: workspace.id,
      name: "Google Search Console Runtime Hermes",
      harnessId: hermesHarness.id,
      externalAgentId: "google-search-console-runtime-hermes",
      hermesProfileSlug: "google-search-console-runtime-hermes",
      hermesHomePath: hermesHome.path,
      hermesIdentityFilePath: hermesHome.appendingPathComponent("identity.json").path
    )
    let unrelatedAgent = try services.data.createAgent(
      workspaceId: workspace.id,
      name: "Google Search Console Runtime Unrelated",
      harnessId: hermesHarness.id,
      externalAgentId: "google-search-console-runtime-unrelated",
      hermesProfileSlug: "google-search-console-runtime-unrelated",
      hermesHomePath: unrelatedHermesHome.path,
      hermesIdentityFilePath: unrelatedHermesHome.appendingPathComponent("identity.json").path
    )
    let openClawAgent = try services.data.createAgent(
      workspaceId: workspace.id,
      name: "Google Search Console Runtime OpenClaw",
      harnessId: openClawHarness.id,
      externalAgentId: "google-search-console-runtime-openclaw",
      workspaceFolderPath: openClawWorkspaceDir.path,
      config: [
        "openclawAgentDir": .string(openClawAgentDir.path),
        "openclawStateDir": .string(openClawStateDir.path),
      ]
    )

    let foundation = try services.providerFoundations.registerGoogleSearchConsoleFoundation(
      context: owner,
      now: fixedDate("2026-01-01T00:00:00Z")
    )
    let app = try unwrap(
      try services.data.getMarketplaceCatalogApp(
        workspaceId: workspace.id, appIdOrSlug: foundation.appId),
      "missing Google Search Console app"
    )
    let connection = try services.providerConnections.saveGoogleSearchConsoleRelayOwnedOAuthConnection(
      context: owner,
      appIdOrSlug: app.id,
      accessToken: "google-search-console-runtime-access-token",
      refreshToken: "google-search-console-runtime-refresh-token",
      accountEmail: "runtime.search.console@example.com",
      selectedSiteUrl: "https://example.com/",
      grantedScopes: ProviderConnectionService.googleSearchConsoleRelayOwnedOAuthScopes,
      expiresAt: "2026-01-01T01:00:01Z"
    )
    let expectedToolNames: Set<String> = [
      "relay_google_search_console_list_properties",
      "relay_google_search_console_get_property",
      "relay_google_search_console_query_search_analytics",
      "relay_google_search_console_inspect_url",
      "relay_google_search_console_list_sitemaps",
      "relay_google_search_console_get_sitemap",
    ]
    try expect(
      Set(foundation.agentFacingWrapperToolNames) == expectedToolNames,
      "Google Search Console foundation should advertise the runtime wrapper tools")

    func install(agent: AgentWithBinding, suffix: String, now: String) throws
      -> MarketplaceInstallRecord
    {
      try services.marketplaceInstalls.createInstall(
        context: owner,
        request: installRequest(
          id: "minreq-google-search-console-runtime-\(suffix)",
          workspaceId: workspace.id,
          app: app,
          connectionId: connection.id,
          agent: agent,
          roleId: app.roleManifest.primaryRole,
          selectedCapabilities: app.capabilities,
          riskAcknowledged: true
        ),
        now: fixedDate(now)
      )
    }

    let hermesInstall = try install(
      agent: hermesAgent, suffix: "hermes", now: "2026-01-01T00:00:02Z")
    let openClawInstall = try install(
      agent: openClawAgent, suffix: "openclaw", now: "2026-01-01T00:00:03Z")
    _ = try services.providerActionPolicies.compilePolicyMap(
      context: owner,
      appIdOrSlug: app.id,
      preset: .readOnly,
      connectionId: connection.id,
      installId: hermesInstall.id,
      agentId: hermesAgent.id,
      now: fixedDate("2026-01-01T00:00:04Z")
    )
    _ = try services.providerActionPolicies.compilePolicyMap(
      context: owner,
      appIdOrSlug: app.id,
      preset: .readOnly,
      connectionId: connection.id,
      installId: openClawInstall.id,
      agentId: openClawAgent.id,
      now: fixedDate("2026-01-01T00:00:05Z")
    )

    let hermesSnapshot = try services.marketplaceRuntimeMounts.snapshot(
      context: member,
      agent: hermesAgent,
      now: fixedDate("2026-01-01T00:00:06Z")
    )
    let hermesMounted = try assertGoogleSearchConsoleRuntimeSnapshot(
      hermesSnapshot,
      runtimeType: .hermes,
      mounts: services.marketplaceRuntimeMounts,
      expectedToolNames: expectedToolNames
    )
    let openClawSnapshot = try services.marketplaceRuntimeMounts.snapshot(
      context: member,
      agent: openClawAgent,
      now: fixedDate("2026-01-01T00:00:07Z")
    )
    _ = try assertGoogleSearchConsoleRuntimeSnapshot(
      openClawSnapshot,
      runtimeType: .openclaw,
      mounts: services.marketplaceRuntimeMounts,
      expectedToolNames: expectedToolNames
    )
    let unrelatedSnapshot = try services.marketplaceRuntimeMounts.snapshot(
      context: member,
      agent: unrelatedAgent,
      now: fixedDate("2026-01-01T00:00:08Z")
    )
    try expect(
      unrelatedSnapshot.apps.isEmpty && unrelatedSnapshot.toolCount == 0,
      "unrelated agents should not inherit Google Search Console runtime tools")

    var confirmedNames = expectedToolNames
    confirmedNames.remove("relay_google_search_console_get_sitemap")
    let confirmedSnapshot = hermesSnapshot.confirmedRegisteredToolSnapshot(
      registeredToolNames: confirmedNames)
    try expect(
      confirmedSnapshot.toolCount == 5,
      "confirmed Google Search Console snapshot should retain only harness-registered tools")
    let confirmedPrompt = try unwrap(
      services.marketplaceRuntimeMounts.renderPromptBlock(confirmedSnapshot),
      "missing confirmed Google Search Console prompt")
    try expect(
      confirmedPrompt.contains("5 brokered callable Relay tool"),
      "confirmed Google Search Console prompt should count only registered tools")
    try expect(
      !confirmedPrompt.contains("relay_google_search_console_get_sitemap"),
      "confirmed Google Search Console prompt should not name unregistered tools")
    try expect(
      !confirmedPrompt.contains("google_search_console_raw_api_call"),
      "confirmed Google Search Console prompt should not mention blocked raw actions")

    func runtimeRequest(agent: AgentWithBinding, suffix: String) -> RuntimeDispatchRequest {
      RuntimeDispatchRequest(
        dispatchId: "rtd-google-search-console-runtime-harness-\(suffix)",
        correlationId: "corr-google-search-console-runtime-harness-\(suffix)",
        threadId: "thr-google-search-console-runtime-harness-\(suffix)",
        messageId: "msg-google-search-console-runtime-harness-\(suffix)",
        sessionId: "rts-google-search-console-runtime-harness-\(suffix)",
        attempt: 1,
        agent: agent,
        runtimeBinding: agent.binding,
        harness: agent.harness,
        inputContent: "summarize search performance",
        inputFormat: .plain,
        recentMessages: [],
        timeoutMs: 30_000,
        createdAt: "2026-01-01T00:00:09Z"
      )
    }

    let hermesHarnessPath = URL(
      fileURLWithPath: try unwrap(
        hermesHarness.config["installPath"]?.string, "missing Hermes harness path"))
    let hermesHarnessInstall = try services.harnessInstall.prepareMarketplaceRuntimeToolBridge(
      for: hermesAgent,
      request: runtimeRequest(agent: hermesAgent, suffix: "hermes"),
      harnessPath: hermesHarnessPath,
      mount: hermesSnapshot
    )
    try expect(
      hermesHarnessInstall.registeredToolNames == expectedToolNames,
      "Hermes adapter should confirm every Google Search Console wrapper tool as registered")
    try expect(
      FileManager.default.fileExists(
        atPath: hermesHarnessPath.appendingPathComponent("tools/relay_marketplace_tools.py").path),
      "Hermes adapter should write the Relay Marketplace runtime tool module"
    )
    try expect(
      !hermesHarnessInstall.env.values.joined(separator: "\n").contains(
        "google-search-console-runtime-refresh-token"),
      "Hermes runtime bridge env should not leak Search Console refresh tokens")

    let openClawHarnessInstall = try services.harnessInstall.prepareMarketplaceRuntimeToolBridge(
      for: openClawAgent,
      request: runtimeRequest(agent: openClawAgent, suffix: "openclaw"),
      harnessPath: URL(
        fileURLWithPath: try unwrap(
          openClawHarness.config["installPath"]?.string, "missing OpenClaw harness path")),
      mount: openClawSnapshot
    )
    try expect(
      openClawHarnessInstall.registeredToolNames == expectedToolNames,
      "OpenClaw adapter should confirm every Google Search Console wrapper tool as registered")
    let openClawPluginDir = services.paths.root
      .appendingPathComponent("marketplace-runtime", isDirectory: true)
      .appendingPathComponent("openclaw-relay-marketplace-plugin", isDirectory: true)
    let openClawManifestData = try Data(
      contentsOf: openClawPluginDir.appendingPathComponent("openclaw.plugin.json"))
    guard
      let openClawManifest = try JSONSerialization.jsonObject(with: openClawManifestData)
        as? [String: Any],
      let contracts = openClawManifest["contracts"] as? [String: Any],
      let contractTools = contracts["tools"] as? [String]
    else {
      throw ServiceTestFailure(
        "OpenClaw Google Search Console marketplace plugin manifest was not valid JSON")
    }
    try expect(
      Set(contractTools) == expectedToolNames,
      "OpenClaw manifest should declare the exact Google Search Console wrapper contracts")
    try expect(
      !contractTools.contains("google_search_console_raw_api_call"),
      "OpenClaw manifest should not declare blocked raw Search Console actions")

    let searchAnalyticsTool = try unwrap(
      hermesMounted.tools.first {
        $0.toolName == "relay_google_search_console_query_search_analytics"
      },
      "missing Google Search Console Search Analytics runtime tool"
    )
    let searchAnalytics = try services.marketplaceRuntimeToolBridge.execute(
      toolName: searchAnalyticsTool.toolName,
      payload: [
        "siteUrl": .string("https://example.com/"),
        "startDate": .string("2026-01-01"),
        "endDate": .string("2026-01-07"),
        "dimensions": .array([.string("query"), .string("page")]),
        "rowLimit": .number(2),
      ],
      runtime: MarketplaceRuntimeToolExecutionContext(
        agentId: hermesAgent.id,
        workspaceId: workspace.id,
        runtimeType: .hermes,
        dispatchId: "rtd-google-search-console-runtime-search-001",
        threadId: "thr-google-search-console-runtime-search-001",
        runtimeSessionId: "rts-google-search-console-runtime-search-001",
        correlationId: "google-search-console-runtime-search-001"
      ),
      now: fixedDate("2026-01-01T00:00:10Z")
    )
    try expect(
      searchAnalytics["toolName"] == .string(searchAnalyticsTool.toolName),
      "Google Search Console runtime bridge should echo the Search Analytics wrapper name")
    try expect(
      searchAnalytics["appSlug"] == .string("google-search-console"),
      "Google Search Console runtime bridge should resolve app slug")
    try expect(
      searchAnalytics["actionKey"] == .string("google_search_console_search_analytics_query"),
      "Google Search Console runtime bridge should map wrapper to Search Analytics action")
    try expect(
      searchAnalytics["adapterExecuted"] == .bool(true),
      "Google Search Console runtime Search Analytics should execute through the broker adapter")
    try expect(
      searchAnalytics["rawProviderToolExposure"] == .bool(false),
      "Google Search Console runtime bridge should suppress raw provider tools")
    let searchProviderResult = try unwrap(
      objectValue(searchAnalytics["providerResult"]),
      "Google Search Console Search Analytics runtime read should return provider result")
    try expect(
      searchProviderResult["semanticReadContract"]
        == .string("google-search-console-search-analytics-v1"),
      "Google Search Console runtime read should preserve semantic read contract")
    try expect(
      searchProviderResult["fakeAdapter"] == .bool(true),
      "Google Search Console runtime test should use the deterministic fake adapter")
    try expect(
      arrayValue(searchProviderResult["rows"]).count == 2,
      "Google Search Console runtime Search Analytics should return bounded rows")

    let openClawSitemap = try services.marketplaceRuntimeToolBridge.execute(
      toolName: "relay_google_search_console_list_sitemaps",
      payload: [
        "siteUrl": .string("https://example.com/"),
        "maxResults": .number(1),
      ],
      runtime: MarketplaceRuntimeToolExecutionContext(
        agentId: openClawAgent.id,
        workspaceId: workspace.id,
        runtimeType: .openclaw,
        dispatchId: "rtd-google-search-console-runtime-openclaw-sitemaps-001",
        threadId: "thr-google-search-console-runtime-openclaw-sitemaps-001",
        runtimeSessionId: "rts-google-search-console-runtime-openclaw-sitemaps-001",
        correlationId: "google-search-console-runtime-openclaw-sitemaps-001"
      ),
      now: fixedDate("2026-01-01T00:00:11Z")
    )
    try expect(
      openClawSitemap["appSlug"] == .string("google-search-console"),
      "OpenClaw Google Search Console runtime bridge should resolve app slug")
    try expect(
      openClawSitemap["actionKey"] == .string("google_search_console_sitemaps_list"),
      "OpenClaw Google Search Console runtime bridge should map sitemap wrapper action")
    try expect(
      openClawSitemap["adapterExecuted"] == .bool(true),
      "OpenClaw Google Search Console sitemap wrapper should execute through the broker")
    let sitemapProviderResult = try unwrap(
      objectValue(openClawSitemap["providerResult"]),
      "OpenClaw Google Search Console sitemap read should return provider result")
    try expect(
      arrayValue(sitemapProviderResult["sitemaps"]).count == 1,
      "OpenClaw Google Search Console sitemap read should return bounded sitemap rows")

    try assertGoogleSearchConsoleRuntimeStorageDoesNotLeakSecrets(services: services)
  }

  private static func assertGoogleSearchConsoleRuntimeSnapshot(
    _ snapshot: MarketplaceRuntimeCapabilitySnapshot,
    runtimeType: RuntimeType,
    mounts: MarketplaceRuntimeMountService,
    expectedToolNames: Set<String>
  ) throws -> MarketplaceRuntimeMountedApp {
    try expect(
      snapshot.runtimeType == runtimeType,
      "Google Search Console runtime snapshot should record runtime type")
    try expect(
      snapshot.apps.map(\.appSlug) == ["google-search-console"],
      "Google Search Console runtime snapshot should contain only the assigned app")
    try expect(
      snapshot.toolCount == 6,
      "Google Search Console runtime snapshot should expose six V1 wrapper tools")
    try expect(
      !snapshot.rawProviderToolExposure,
      "Google Search Console runtime snapshot should not expose raw provider tools")
    try expect(
      snapshot.redactionStatus == "private-state-excluded",
      "Google Search Console runtime snapshot should retain redaction evidence")

    let mounted = try unwrap(snapshot.apps.first, "missing mounted Google Search Console app")
    try expect(
      mounted.connected && mounted.assignedAgentReady,
      "Google Search Console runtime mount should be connected and assigned")
    try expect(
      mounted.instructions.count <= 1200,
      "Google Search Console runtime instructions should stay within prompt summary budget")
    try expect(
      mounted.instructions.contains("bounded Search Analytics"),
      "Google Search Console runtime instructions should mention bounded Search Analytics reads")
    try expect(
      mounted.instructions.contains("URL Inspection"),
      "Google Search Console runtime instructions should mention URL Inspection reads")
    try expect(
      mounted.instructions.contains("webmasters.readonly"),
      "Google Search Console runtime instructions should restrict scope to webmasters.readonly")
    try expect(
      mounted.instructions.contains("raw REST calls"),
      "Google Search Console runtime instructions should block raw REST calls")
    try expect(
      mounted.instructions.contains("sitemap submission or deletion"),
      "Google Search Console runtime instructions should block sitemap writes")
    try expect(
      Set(mounted.tools.map(\.toolName)) == expectedToolNames,
      "Google Search Console runtime should expose the documented wrapper names")
    try expect(
      mounted.tools.allSatisfy(\.readOnly),
      "Google Search Console runtime tools should all be read-only")
    try expect(
      mounted.tools.allSatisfy { !$0.requiresApproval && !$0.autoExecutes },
      "Google Search Console runtime read tools should not require approval or auto-execute writes")
    try expect(
      mounted.tools.allSatisfy { $0.toolName.hasPrefix("relay_google_search_console_") },
      "Google Search Console runtime tools should use app-specific Relay wrapper names")
    try expect(
      mounted.tools.allSatisfy { !$0.toolName.contains(".") },
      "Google Search Console runtime tool names should not expose dotted provider actions")
    try expect(
      mounted.diagnostics.blockedActionCount == 7,
      "Google Search Console runtime diagnostics should count blocked V1 actions")
    try expect(
      mounted.diagnostics.suppressedRawProviderToolCount == 13,
      "Google Search Console runtime diagnostics should count suppressed raw provider actions")
    try expect(
      !mounted.diagnostics.rawProviderToolExposure,
      "Google Search Console runtime diagnostics should suppress raw provider tools")

    let toolsByDisplayName = Dictionary(
      uniqueKeysWithValues: mounted.tools.map { ($0.displayName, $0) })
    for displayName in [
      "List properties", "Get property", "Query Search Analytics", "Inspect URL", "List sitemaps",
      "Get sitemap",
    ] {
      try expect(
        toolsByDisplayName[displayName] != nil,
        "Google Search Console runtime should expose \(displayName)")
    }
    for blockedName in [
      "Submit sitemap", "Delete sitemap", "Add site", "Delete site", "Broad export",
      "Testing Tools API", "Raw API call",
    ] {
      try expect(
        toolsByDisplayName[blockedName] == nil,
        "Google Search Console runtime should not expose blocked action \(blockedName)")
    }

    let prompt = try unwrap(
      mounts.renderPromptBlock(snapshot), "missing Google Search Console runtime prompt")
    try expect(
      prompt.contains("App: Google Search Console (google-search-console)"),
      "Google Search Console runtime prompt should include the app")
    try expect(
      prompt.contains("6 brokered callable Relay tool"),
      "Google Search Console runtime prompt should count registered tools")
    for leaked in [
      "google-search-console-runtime-client-id",
      "google-search-console-runtime-client-secret",
      "google-search-console-runtime-refresh-token",
      "google_search_console_raw_api_call",
      "google_search_console_sitemap_submit",
      "google_search_console_sitemap_delete",
      "google_search_console_site_add",
      "google_search_console_site_delete",
      "google_search_console_broad_export",
      "google_search_console_testing_tools_api",
      "https://www.googleapis.com/auth/webmasters\"",
      "Bearer ",
    ] {
      try expect(
        !prompt.contains(leaked),
        "Google Search Console runtime prompt leaked raw provider state or blocked surface \(leaked)"
      )
    }
    return mounted
  }

  private static func assertGoogleSearchConsoleRuntimeStorageDoesNotLeakSecrets(
    services: RelayConsoleServices
  ) throws {
    let rows = try services.database.all(
      """
      SELECT connection_json AS value FROM applications_provider_connections
      UNION ALL SELECT install_json AS value FROM applications_marketplace_installs
      UNION ALL SELECT execution_json AS value FROM marketplace_provider_action_executions
      UNION ALL SELECT context_json AS value FROM audit_log_records
      """
    )
    let retained = rows.compactMap { sqliteText($0["value"]) }.joined(separator: "\n")
    for secret in [
      "google-search-console-runtime-client-id",
      "google-search-console-runtime-client-secret",
      "google-search-console-runtime-refresh-token",
    ] {
      try expect(
        !retained.contains(secret),
        "Google Search Console runtime storage leaked raw OAuth credential \(secret)")
    }
    try expect(
      !retained.localizedCaseInsensitiveContains("bearer "),
      "Google Search Console runtime storage leaked bearer authorization material")
    try expect(
      retained.contains("[REDACTED]"),
      "Google Search Console runtime storage should retain redaction markers")
  }

  private static func testGoogleSearchConsoleAssignmentHydratesReadOnlyAuthorityControls() throws {
    let services = try makeServices()
    let workspace = try unwrap(services.data.getAppState().activeWorkspace, "missing workspace")
    let owner = Self.context(
      roles: [.owner], workspaceId: workspace.id,
      correlationId: "google-search-console-assignment-owner-001")
    let member = Self.context(
      roles: [.member], workspaceId: workspace.id,
      correlationId: "google-search-console-assignment-member-001")
    let foundation = try services.providerFoundations.registerGoogleSearchConsoleFoundation(
      context: owner,
      now: fixedDate("2026-01-01T00:00:00Z")
    )
    let app = try unwrap(
      try services.data.getMarketplaceCatalogApp(
        workspaceId: workspace.id, appIdOrSlug: foundation.appId),
      "missing Google Search Console app"
    )
    let connection = try services.providerConnections.saveGoogleSearchConsoleRelayOwnedOAuthConnection(
      context: owner,
      appIdOrSlug: app.id,
      accessToken: "google-search-console-assignment-access-token",
      refreshToken: "google-search-console-assignment-refresh-token",
      accountEmail: "assignment.search.console@example.com",
      selectedSiteUrl: "https://example.com/",
      grantedScopes: ProviderConnectionService.googleSearchConsoleRelayOwnedOAuthScopes,
      expiresAt: "2026-01-01T01:00:01Z"
    )
    let agent = try createServiceAgent(services: services, workspaceId: workspace.id)
    let install = try services.marketplaceInstalls.createInstall(
      context: owner,
      request: installRequest(
        id: "minreq-google-search-console-assignment-001",
        workspaceId: workspace.id,
        app: app,
        connectionId: connection.id,
        agent: agent,
        roleId: app.roleManifest.primaryRole,
        selectedCapabilities: app.capabilities,
        riskAcknowledged: true
      ),
      now: fixedDate("2026-01-01T00:00:02Z")
    )
    let storedInstall = try unwrap(
      try services.data.getMarketplaceInstall(workspaceId: workspace.id, installId: install.id),
      "missing hydrated Google Search Console install"
    )
    try expect(
      storedInstall.metadata["providerActionFrameworkHydrated"] == .bool(true),
      "Google Search Console assignment should hydrate provider action framework")
    try expect(
      storedInstall.metadata["providerActionPolicyPreset"]
        == .string(MarketplaceActionPolicyPreset.readOnly.rawValue),
      "Google Search Console assignment should default to read-only authority")
    try expect(
      storedInstall.metadata["providerActionDefinitionCount"] == .number(13),
      "Google Search Console assignment should retain full provider action definition count")
    try expect(
      storedInstall.metadata["providerActionFrameworkSource"]
        == .string("marketplace-install-migration"),
      "Google Search Console assignment should record framework hydration source")
    let policyMapId = try unwrap(
      storedInstall.metadata["providerActionPolicyMapId"]?.string,
      "missing Google Search Console policy map id")
    let permissionMap = try unwrap(
      try services.data.listMarketplaceActionPermissionMaps(
        workspaceId: workspace.id, appId: app.id
      ).first { $0.id == policyMapId },
      "missing Google Search Console permission map"
    )
    try expect(
      permissionMap.policyPreset == .readOnly,
      "Google Search Console assignment permission map should be read-only")
    try expect(
      permissionMap.connectionId == connection.id,
      "Google Search Console permission map should be scoped to selected connection")
    try expect(
      permissionMap.installId == storedInstall.id,
      "Google Search Console permission map should be scoped to install")
    try expect(
      permissionMap.agentId == agent.id,
      "Google Search Console permission map should be scoped to assigned agent")
    for actionKey in [
      "google_search_console_properties_list",
      "google_search_console_property_get",
      "google_search_console_search_analytics_query",
      "google_search_console_url_inspect",
      "google_search_console_sitemaps_list",
      "google_search_console_sitemap_get",
    ] {
      try expect(
        permissionMap.permissions[actionKey] == .allowed,
        "Google Search Console assignment should allow read action \(actionKey)")
    }
    for actionKey in [
      "google_search_console_sitemap_submit",
      "google_search_console_sitemap_delete",
      "google_search_console_site_add",
      "google_search_console_site_delete",
      "google_search_console_broad_export",
      "google_search_console_testing_tools_api",
      "google_search_console_raw_api_call",
    ] {
      try expect(
        permissionMap.permissions[actionKey] == .blocked,
        "Google Search Console assignment should block deferred action \(actionKey)")
    }

    let snapshot = try services.marketplaceRuntimeMounts.snapshot(
      context: member,
      agent: agent,
      now: fixedDate("2026-01-01T00:00:03Z")
    )
    let mounted = try unwrap(
      snapshot.apps.first { $0.appSlug == "google-search-console" },
      "missing Google Search Console runtime mount after assignment")
    try expect(
      mounted.permissionMapId == permissionMap.id,
      "Google Search Console runtime mount should use the assignment-scoped permission map")
    try expect(
      mounted.policyPreset == .readOnly,
      "Google Search Console runtime mount should expose read-only authority")
    try expect(
      mounted.tools.count == 6,
      "Google Search Console read-only assignment should mount six wrapper tools")

    _ = try services.marketplaceInstalls.removeInstall(
      context: owner,
      installId: storedInstall.id,
      now: fixedDate("2026-01-01T00:00:04Z")
    )
    let removedSnapshot = try services.marketplaceRuntimeMounts.snapshot(
      context: member,
      agent: agent,
      now: fixedDate("2026-01-01T00:00:05Z")
    )
    try expect(
      removedSnapshot.toolCount == 0,
      "Google Search Console removal should refresh runtime mount scope for the affected agent")
  }

  private static func testPostHogProviderConnectionIsKeychainBackedAndHealthChecked() throws {
    actor StubPostHogTokenValidator: PostHogTokenValidating {
      private var responsesByToken: [String: [PostHogTokenValidationResult]]

      init(responsesByToken: [String: [PostHogTokenValidationResult]]) {
        self.responsesByToken = responsesByToken
      }

      func validate(personalAPIKey: String, baseURL: String, projectId: String?) async
        -> PostHogTokenValidationResult
      {
        let token = personalAPIKey.trimmingCharacters(in: .whitespacesAndNewlines)
        guard var responses = responsesByToken[token], !responses.isEmpty else {
          return PostHogTokenValidationResult(
            status: .invalidToken,
            message: "Stub PostHog validator has no response for this key.",
            httpStatusCode: 401,
            baseURL: baseURL,
            projectId: projectId
          )
        }
        let response = responses.removeFirst()
        responsesByToken[token] = responses
        return response
      }
    }

    let root = FileManager.default.temporaryDirectory
      .appendingPathComponent("RelayConsolePostHogProviderConnectionTests", isDirectory: true)
      .appendingPathComponent(UUID().uuidString, isDirectory: true)
    let services = try makeServices(root: root)
    let workspace = try unwrap(services.data.getAppState().activeWorkspace, "missing workspace")
    let owner = Self.context(
      roles: [.owner], workspaceId: workspace.id, correlationId: "posthog-connection-owner-001")
    let admin = Self.context(
      roles: [.admin], workspaceId: workspace.id, correlationId: "posthog-connection-admin-001")
    let rawPersonalAPIKey = "phx_posthog_provider_contract_sensitive_value"
    let postHogApp = marketplaceApp(
      workspaceId: workspace.id,
      slug: "posthog",
      name: "PostHog",
      summary: "User-owned PostHog personal API key.",
      category: "Analytics",
      riskLevel: .high,
      connectionState: .none,
      installState: .notInstalled
    )
    _ = try services.applications.saveCatalogApps(context: owner, apps: [postHogApp])

    let unverified = try services.providerConnections.savePostHogPersonalAPIKeyConnection(
      context: owner,
      appIdOrSlug: postHogApp.slug,
      baseURL: "us.posthog.com",
      personalAPIKey: rawPersonalAPIKey,
      organizationId: "org-posthog-001",
      organizationName: "Relay Product Org",
      projectId: "12345",
      projectName: "Relay Product Analytics",
      displayName: "Relay PostHog",
      now: fixedDate("2026-01-01T00:00:00Z")
    )
    try expect(
      unverified.appSlug == "posthog", "PostHog connection should target the canonical app slug")
    try expect(unverified.providerName == "PostHog", "PostHog provider name should be explicit")
    try expect(
      unverified.status == .connected, "PostHog saved key should create an assignable connection")
    try expect(
      unverified.health.state == .degraded,
      "PostHog saved key should stay unverified until an explicit check or bounded read")
    try expect(unverified.lastCheckedAt == nil, "PostHog save should not consume a live API check")
    try expect(
      unverified.authorizationState == .completed,
      "PostHog personal-key mode should not wait for OAuth callback authorization")
    try expect(
      unverified.credentialOwnership == .userOwned, "PostHog key should record user-owned ownership"
    )
    try expect(
      unverified.secretReferenceIds.count == 1,
      "PostHog personal API key should use one Keychain reference")
    try expect(
      unverified.requiredScopes == ProviderConnectionService.postHogReadScopes,
      "PostHog required scopes should be explicit")
    try expect(
      unverified.grantedScopes == ProviderConnectionService.postHogReadScopes,
      "PostHog granted scopes should be recorded")
    try expect(
      unverified.callbackURL == nil,
      "PostHog key mode must not retain a Relay, Railway, or web callback URL")
    try expect(
      unverified.health.diagnostics["apiBaseURL"] == .string("https://us.posthog.com"),
      "PostHog diagnostics should normalize the private API base URL")
    try expect(
      unverified.health.diagnostics["projectId"] == .string("12345"),
      "PostHog diagnostics should retain non-secret project id")
    try expect(
      unverified.health.diagnostics["projectName"] == .string("Relay Product Analytics"),
      "PostHog diagnostics should retain non-secret project label")
    try expect(
      unverified.health.diagnostics["callbackURLRequired"] == .bool(false),
      "PostHog diagnostics should state no callback URL is required")
    try expect(
      unverified.health.diagnostics["relayOwnedPostHogApp"] == .bool(false),
      "PostHog connection must not represent a shared Relay-owned app")
    try expect(
      unverified.health.diagnostics["rawTokenStoredInDatabase"] == .bool(false),
      "PostHog diagnostics should state raw tokens are not stored in the database")
    try expect(
      unverified.health.diagnostics["rawMCPExposure"] == .bool(false),
      "PostHog diagnostics should suppress raw MCP exposure")
    try expect(
      try services.secrets.getSecretValue(unverified.secretReferenceIds[0]) == rawPersonalAPIKey,
      "PostHog key should be retrievable only through SecretService")
    let credentialByKey = Dictionary(
      uniqueKeysWithValues: unverified.credentialRequirements.map { ($0.fieldKey, $0) })
    try expect(
      credentialByKey["posthog_api_base_url"]?.secretReferenceId == nil,
      "PostHog base URL should be non-secret metadata")
    try expect(
      credentialByKey["posthog_personal_api_key"]?.secretReferenceId
        == unverified.secretReferenceIds[0],
      "PostHog key requirement should reference the Keychain secret")
    try expect(
      credentialByKey["posthog_organization_id"]?.secretReferenceId == nil,
      "PostHog organization id should be non-secret metadata")
    try expect(
      credentialByKey["posthog_project_id"]?.secretReferenceId == nil,
      "PostHog project id should be non-secret metadata")

    let snapshot = try services.providerConnections.snapshot(
      context: admin,
      appIdOrSlug: postHogApp.id,
      now: fixedDate("2026-01-01T00:00:00Z")
    )
    try expect(
      snapshot.selectedConnection?.status == .connected,
      "PostHog key snapshot should stay assignable")
    try expect(
      snapshot.authorizationFlows.isEmpty,
      "PostHog personal-key mode should not create an OAuth authorization flow")
    let syncedApp = try unwrap(
      try services.data.getMarketplaceCatalogApp(
        workspaceId: workspace.id, appIdOrSlug: postHogApp.slug),
      "missing synced PostHog app"
    )
    try expect(
      syncedApp.connectionState == .connected,
      "PostHog key should sync the catalog connection state")

    let validator = StubPostHogTokenValidator(responsesByToken: [
      rawPersonalAPIKey: [
        PostHogTokenValidationResult(
          status: .ready,
          message: "PostHog personal API key verified with a bounded project read.",
          httpStatusCode: 200,
          baseURL: "https://us.posthog.com",
          organizationId: "org-posthog-001",
          organizationName: "Relay Product Org",
          projectId: "12345",
          projectName: "Relay Product Analytics",
          projectCount: 2
        ),
        PostHogTokenValidationResult(
          status: .invalidToken,
          message: "PostHog rejected this personal API key.",
          httpStatusCode: 401,
          baseURL: "https://us.posthog.com",
          projectId: "12345"
        ),
      ]
    ])
    let connectionService = ProviderConnectionService(
      data: services.data,
      secrets: services.secrets,
      postHogValidator: validator
    )
    let validated = try awaitResult {
      try await connectionService.validateSavedPostHogConnection(
        context: owner,
        connectionId: unverified.id,
        now: fixedDate("2026-01-01T00:00:01Z")
      )
    }
    try expect(
      validated.status == .connected,
      "Readable PostHog key should stay connected after explicit check")
    try expect(validated.health.state == .ready, "PostHog explicit check should mark health ready")
    try expect(
      validated.health.diagnostics["validation"]
        == .string(PostHogTokenValidationStatus.ready.rawValue),
      "PostHog diagnostics should retain validation status")
    try expect(
      validated.health.diagnostics["httpStatusCode"] == .number(200),
      "PostHog diagnostics should retain health-check status code")
    try expect(
      validated.health.diagnostics["projectCount"] == .number(2),
      "PostHog diagnostics should retain project discovery evidence")
    try expect(
      !validated.reauthorizeRequired, "Ready PostHog health should not request reauthorization")

    var missingSecret = validated
    missingSecret.id = "mpc-posthog-missing-secret-001"
    missingSecret.credentialRequirements = missingSecret.credentialRequirements.map { requirement in
      var copy = requirement
      if copy.fieldKey == "posthog_personal_api_key" {
        copy.secretReferenceId = nil
        copy.status = .missing
      }
      return copy
    }
    missingSecret.secretReferenceIds = missingSecret.credentialRequirements.compactMap(
      \.secretReferenceId)
    _ = try services.data.saveProviderConnection(missingSecret)
    let missing = try awaitResult {
      try await connectionService.validateSavedPostHogConnection(
        context: owner,
        connectionId: missingSecret.id,
        now: fixedDate("2026-01-01T00:00:02Z")
      )
    }
    let missingCredentialByKey = Dictionary(
      uniqueKeysWithValues: missing.credentialRequirements.map { ($0.fieldKey, $0) })
    try expect(
      missing.status == .authRequired, "Missing PostHog key reference should require reconnect")
    try expect(
      missing.health.diagnostics["validation"]
        == .string(PostHogTokenValidationStatus.invalidToken.rawValue),
      "Missing PostHog key reference should retain validation status")
    try expect(
      missing.reauthorizeRequired, "Missing PostHog key reference should request reauthorization")
    try expect(
      missingCredentialByKey["posthog_personal_api_key"]?.status == .missing,
      "Missing PostHog key should mark the credential field missing")

    var unreadableSecret = validated
    unreadableSecret.id = "mpc-posthog-unreadable-secret-001"
    unreadableSecret.credentialRequirements = unreadableSecret.credentialRequirements.map {
      requirement in
      var copy = requirement
      if copy.fieldKey == "posthog_personal_api_key" {
        copy.secretReferenceId = "sec-posthog-unreadable-001"
        copy.status = .unavailable
      }
      return copy
    }
    unreadableSecret.secretReferenceIds = unreadableSecret.credentialRequirements.compactMap(
      \.secretReferenceId)
    _ = try services.data.saveProviderConnection(unreadableSecret)
    let unreadable = try awaitResult {
      try await connectionService.validateSavedPostHogConnection(
        context: owner,
        connectionId: unreadableSecret.id,
        now: fixedDate("2026-01-01T00:00:03Z")
      )
    }
    let unreadableCredentialByKey = Dictionary(
      uniqueKeysWithValues: unreadable.credentialRequirements.map { ($0.fieldKey, $0) })
    try expect(
      unreadable.status == .authRequired,
      "Unreadable PostHog key reference should require reconnect")
    try expect(
      unreadable.health.diagnostics["validation"]
        == .string(PostHogTokenValidationStatus.invalidToken.rawValue),
      "Unreadable PostHog key reference should retain validation status")
    try expect(
      unreadable.reauthorizeRequired,
      "Unreadable PostHog key reference should request reauthorization")
    try expect(
      unreadableCredentialByKey["posthog_personal_api_key"]?.status == .unavailable,
      "Unreadable PostHog key should mark the credential field unavailable")

    _ = try services.data.saveProviderConnection(validated)
    let invalid = try awaitResult {
      try await connectionService.validateSavedPostHogConnection(
        context: owner,
        connectionId: validated.id,
        now: fixedDate("2026-01-01T00:00:04Z")
      )
    }
    try expect(
      invalid.status == .authRequired, "Invalid PostHog key recheck should require reconnect")
    try expect(
      invalid.health.diagnostics["validation"]
        == .string(PostHogTokenValidationStatus.invalidToken.rawValue),
      "Invalid PostHog key should retain validation status")
    try expect(
      invalid.health.diagnostics["httpStatusCode"] == .number(401),
      "Invalid PostHog key should retain redacted HTTP status")
    try expect(invalid.reauthorizeRequired, "Invalid PostHog key should request reauthorization")

    let sqliteDump = try services.database.all(
      """
      SELECT connection_json AS value FROM applications_provider_connections
      UNION ALL
      SELECT snapshot_json AS value FROM applications_provider_connection_snapshots
      UNION ALL
      SELECT label AS value FROM secret_references
      """
    ).compactMap { sqliteText($0["value"]) }.joined(separator: "\n")
    try expect(
      !sqliteDump.contains(rawPersonalAPIKey),
      "raw PostHog personal API key leaked into SQLite JSON")
    try expect(
      !sqliteDump.contains("relay-console://oauth/posthog/callback"),
      "PostHog personal-key mode should not persist a Relay callback URL")
    try expect(
      !sqliteDump.localizedCaseInsensitiveContains("posthog mcp tool"),
      "PostHog persistence should not expose raw MCP tools")
    try expect(
      sqliteDump.contains("[REDACTED]"),
      "PostHog connection persistence should retain redacted evidence")
  }

  private static func testPostHogRelayOwnedOAuthStoresAndRotatesExactReadOnlyPair() throws {
    let services = try makeServices()
    let workspace = try unwrap(services.data.getAppState().activeWorkspace, "missing workspace")
    let owner = Self.context(
      roles: [.owner], workspaceId: workspace.id, correlationId: "posthog-oauth-owner-001")
    let app = marketplaceApp(
      workspaceId: workspace.id, slug: "posthog", name: "PostHog",
      summary: "Relay-owned PostHog OAuth.", category: "Analytics", riskLevel: .high,
      connectionState: .none, installState: .notInstalled)
    _ = try services.applications.saveCatalogApps(context: owner, apps: [app])
    let access = "pha_posthog_oauth_access_sensitive"
    let refresh = "phr_posthog_oauth_refresh_sensitive"
    let validation = PostHogTokenValidationResult(
      status: .ready, message: "PostHog OAuth token verified with a bounded project read.",
      httpStatusCode: 200, baseURL: "https://us.posthog.com", organizationId: "org_oauth_1",
      organizationName: "Relay Product", projectId: "12345", projectName: "Relay Analytics",
      projectCount: 1)
    var connection = try services.providerConnections.savePostHogRelayOwnedOAuthConnection(
      context: owner, appIdOrSlug: app.id, apiBaseURL: "https://us.posthog.com",
      accessToken: access, refreshToken: refresh,
      clientMetadataURL: "https://relay.example/oauth/posthog/client-metadata",
      redirectURI: "http://127.0.0.1:8767/oauth/posthog/callback",
      grantedScopes: ProviderConnectionService.postHogReadScopes, expiresAt: "2026-07-11T15:00:00Z",
      organizationId: "org_oauth_1", organizationName: "Relay Product", projectId: "12345",
      projectName: "Relay Analytics",
      displayName: "Relay Analytics", validationResult: validation,
      now: fixedDate("2026-07-11T14:00:00Z")
    )
    let oldRefs = connection.secretReferenceIds
    try expect(
      connection.credentialOwnership == .relayOwned && !connection.userOwnedCredentialsRequired,
      "PostHog OAuth should be Relay-owned")
    try expect(
      connection.requiredScopes == ProviderConnectionService.postHogReadScopes
        && connection.grantedScopes == ProviderConnectionService.postHogReadScopes,
      "PostHog OAuth should preserve exact read scopes")
    try expect(
      oldRefs.count == 2 && connection.health.diagnostics["pkceMethod"] == .string("S256")
        && connection.health.diagnostics["rawMCPExposure"] == .bool(false),
      "PostHog OAuth should retain separate token references and the PKCE/raw-MCP boundary")
    let storedAccess = try services.secrets.getSecretValue(oldRefs[0])
    let storedRefresh = try services.secrets.getSecretValue(oldRefs[1])
    try expect(
      storedAccess == access && storedRefresh == refresh,
      "PostHog OAuth tokens should exist only through their Keychain references")
    connection = try services.providerConnections.rotatePostHogOAuthTokens(
      context: owner, connectionId: connection.id, accessToken: "pha_replacement_access_sensitive",
      refreshToken: "phr_replacement_refresh_sensitive", expiresAt: "2026-07-11T16:00:00Z",
      now: fixedDate("2026-07-11T15:00:00Z"))
    try expect(
      Set(connection.secretReferenceIds).isDisjoint(with: Set(oldRefs)),
      "PostHog OAuth rotation should completely replace both token references")
    try expect(
      oldRefs.allSatisfy { (try? services.secrets.getSecretValue($0)) == nil },
      "PostHog OAuth rotation should delete superseded token references")
    let retained = try services.database.all(
      "SELECT connection_json AS value FROM applications_provider_connections UNION ALL SELECT snapshot_json AS value FROM applications_provider_connection_snapshots"
    ).compactMap { sqliteText($0["value"]) }.joined(separator: "\n")
    for secret in [
      access, refresh, "pha_replacement_access_sensitive", "phr_replacement_refresh_sensitive",
    ] { try expect(!retained.contains(secret), "PostHog OAuth token leaked into persistence") }
  }

  private static func testTelemetryDeckProviderConnectionIsKeychainBackedAndHealthChecked() throws {
    actor StubTelemetryDeckPATValidator: TelemetryDeckPATValidating {
      private var responsesByToken: [String: [TelemetryDeckPATValidationResult]]

      init(responsesByToken: [String: [TelemetryDeckPATValidationResult]]) {
        self.responsesByToken = responsesByToken
      }

      func validate(personalAccessToken: String) async -> TelemetryDeckPATValidationResult {
        let token = personalAccessToken.trimmingCharacters(in: .whitespacesAndNewlines)
        guard var responses = responsesByToken[token], !responses.isEmpty else {
          return TelemetryDeckPATValidationResult(
            status: .invalidToken,
            message: "Stub TelemetryDeck validator has no response for this PAT.",
            httpStatusCode: 401
          )
        }
        let response = responses.removeFirst()
        responsesByToken[token] = responses
        return response
      }
    }

    let root = FileManager.default.temporaryDirectory
      .appendingPathComponent("RelayConsoleTelemetryDeckProviderConnectionTests", isDirectory: true)
      .appendingPathComponent(UUID().uuidString, isDirectory: true)
    let services = try makeServices(root: root)
    let workspace = try unwrap(services.data.getAppState().activeWorkspace, "missing workspace")
    let owner = Self.context(
      roles: [.owner], workspaceId: workspace.id,
      correlationId: "telemetrydeck-connection-owner-001")
    let admin = Self.context(
      roles: [.admin], workspaceId: workspace.id,
      correlationId: "telemetrydeck-connection-admin-001")
    let rawPAT = "td_pat_provider_contract_sensitive_value"
    let replacementPAT = "td_pat_provider_contract_replacement_sensitive_value"
    let telemetryDeckApp = marketplaceApp(
      workspaceId: workspace.id,
      slug: "telemetrydeck",
      name: "TelemetryDeck",
      summary: "User-owned TelemetryDeck Personal Access Token.",
      category: "Analytics",
      riskLevel: .high,
      connectionState: .none,
      installState: .notInstalled
    )
    _ = try services.applications.saveCatalogApps(context: owner, apps: [telemetryDeckApp])

    let validator = StubTelemetryDeckPATValidator(responsesByToken: [
      rawPAT: [
        TelemetryDeckPATValidationResult(
          status: .ready,
          message: "TelemetryDeck Personal Access Token verified.",
          httpStatusCode: 200,
          userId: "td-user-001",
          userEmail: "relay.telemetry@example.com",
          organizationName: "Relay Telemetry Org"
        ),
        TelemetryDeckPATValidationResult(
          status: .invalidToken,
          message: "TelemetryDeck rejected this Personal Access Token.",
          httpStatusCode: 401
        ),
      ]
    ])
    let connectionService = ProviderConnectionService(
      data: services.data,
      secrets: services.secrets,
      telemetryDeckValidator: validator
    )
    let connected = try awaitResult {
      try await connectionService.connectTelemetryDeckPAT(
        context: owner,
        appIdOrSlug: telemetryDeckApp.slug,
        personalAccessToken: rawPAT,
        namespace: "relay-org",
        telemetryDeckAppId: "td-app-123",
        appDisplayName: "Relay iOS App",
        defaultInsightId: "insight-456",
        displayName: "Relay TelemetryDeck",
        now: fixedDate("2026-01-01T00:00:00Z")
      )
    }
    try expect(
      connected.appSlug == "telemetrydeck",
      "TelemetryDeck connection should target the canonical app slug")
    try expect(
      connected.providerName == "TelemetryDeck", "TelemetryDeck provider name should be explicit")
    try expect(
      connected.status == .connected,
      "TelemetryDeck PAT should create a connected provider connection")
    try expect(
      connected.health.state == .ready, "TelemetryDeck ready validation should mark health ready")
    try expect(
      connected.authorizationState == .completed,
