    }
    try expect(
      reconnected.status == .connected,
      "TelemetryDeck reconnect should restore connected status with a valid replacement PAT")
    try expect(
      reconnected.health.state == .ready, "TelemetryDeck reconnect should restore ready health")
    try expect(
      reconnected.health.diagnostics["validation"]
        == .string(TelemetryDeckPATValidationStatus.ready.rawValue),
      "TelemetryDeck reconnect should retain ready validation")
    try expect(
      try services.secrets.getSecretValue(reconnected.secretReferenceIds[0]) == replacementPAT,
      "TelemetryDeck replacement PAT should be retrievable only through SecretService")

    let sqliteDump = try services.database.all(
      """
      SELECT connection_json AS value FROM applications_provider_connections
      UNION ALL
      SELECT snapshot_json AS value FROM applications_provider_connection_snapshots
      UNION ALL
      SELECT label AS value FROM secret_references
      """
    ).compactMap { sqliteText($0["value"]) }.joined(separator: "\n")
    try expect(!sqliteDump.contains(rawPAT), "raw TelemetryDeck PAT leaked into SQLite JSON")
    try expect(
      !sqliteDump.contains(replacementPAT),
      "raw replacement TelemetryDeck PAT leaked into SQLite JSON")
    try expect(
      !sqliteDump.contains("relay-console://oauth/telemetrydeck/callback"),
      "TelemetryDeck PAT mode should not persist a Relay callback URL")
    try expect(
      !sqliteDump.localizedCaseInsensitiveContains("telemetrydeck mcp tool"),
      "TelemetryDeck persistence should not expose raw MCP tools")
    try expect(
      sqliteDump.contains("keychain-reference-only"),
      "TelemetryDeck connection persistence should retain secret-reference redaction evidence")
  }

  private static func testTelemetryDeckProviderFoundationEnforcesReadOnlyAnalyticsPolicy() throws {
    let services = try makeServices()
    let workspace = try unwrap(services.data.getAppState().activeWorkspace, "missing workspace")
    let owner = Self.context(
      roles: [.owner], workspaceId: workspace.id,
      correlationId: "telemetrydeck-foundation-owner-001")
    let member = Self.context(
      roles: [.member], workspaceId: workspace.id,
      correlationId: "telemetrydeck-foundation-member-001")
    let token = "td_pat_foundation_sensitive_value"

    do {
      _ = try services.providerFoundations.registerTelemetryDeckFoundation(
        context: member,
        now: fixedDate("2026-01-01T00:00:00Z")
      )
      throw ServiceTestFailure("member unexpectedly registered TelemetryDeck provider foundation")
    } catch let denied as ServiceGuardResult {
      try expect(
        denied.reasonCode == .authorityRoleRequired,
        "TelemetryDeck foundation registration should require owner/admin authority")
    }

    let snapshot = try services.providerFoundations.registerTelemetryDeckFoundation(
      context: owner,
      now: fixedDate("2026-01-01T00:00:01Z")
    )
    try expect(
      snapshot.appSlug == "telemetrydeck",
      "TelemetryDeck foundation should target the canonical app")
    try expect(
      snapshot.providerName == "TelemetryDeck",
      "TelemetryDeck foundation should retain the canonical provider name")
    try expect(
      snapshot.providerFamily == "app-analytics",
      "TelemetryDeck foundation should mark the provider as app analytics")
    try expect(
      snapshot.connectionMode == "user-owned-telemetrydeck-pat",
      "TelemetryDeck foundation should use the PAT mode")
    try expect(
      snapshot.credentialOwnership == .userOwned,
      "TelemetryDeck foundation should require user-owned credentials")
    try expect(
      snapshot.userOwnedCredentialsRequired,
      "TelemetryDeck foundation should require user-owned credential entry")
    try expect(
      snapshot.supportedPolicyPresets == [.readOnly, .blocked],
      "TelemetryDeck foundation should advertise only read-only and blocked policies")
    try expect(
      snapshot.defaultPolicyPreset == .readOnly,
      "TelemetryDeck foundation should default to read-only policy")
    try expect(
      snapshot.adapterBoundary == "brokered-native-telemetrydeck-api-adapter",
      "TelemetryDeck foundation should keep API access behind the broker boundary")
    try expect(
      snapshot.actionMapVersion == "telemetrydeck-v1",
      "TelemetryDeck foundation should identify the V1 action map")
    try expect(
      !snapshot.rawProviderToolExposure,
      "TelemetryDeck foundation should not expose raw provider tools")
    try expect(
      snapshot.suppressedRawProviderToolCount == 10,
      "TelemetryDeck foundation should count safe and blocked V1 provider actions as suppressed raw tools"
    )
    try expect(
      snapshot.budgetPolicy["maxWrapperTools"] == .number(3),
      "TelemetryDeck foundation should budget three wrapper tools")
    try expect(
      snapshot.budgetPolicy["maxQueryRows"] == .number(100),
      "TelemetryDeck foundation should cap bounded query rows")
    try expect(
      snapshot.privacyPolicy["signalIngest"] == .string("blocked"),
      "TelemetryDeck signal ingest should be blocked")
    try expect(
      snapshot.privacyPolicy["rawScanExport"] == .string("blocked"),
      "TelemetryDeck raw scan export should be blocked")
    try expect(
      snapshot.privacyPolicy["appAdministration"] == .string("blocked"),
      "TelemetryDeck app admin should be blocked")
    try expect(
      snapshot.privacyPolicy["organizationAdministration"] == .string("blocked"),
      "TelemetryDeck org admin should be blocked")
    try expect(
      snapshot.privacyPolicy["unboundedQueries"] == .string("blocked"),
      "TelemetryDeck unbounded queries should be blocked")
    try expect(
      snapshot.privacyPolicy["scheduledPolling"] == .string("blocked"),
      "TelemetryDeck scheduled polling should be blocked")
    try expect(
      snapshot.privacyPolicy["rawMCPExposure"] == .string("blocked"),
      "TelemetryDeck raw MCP exposure should be blocked")
    try expect(
      snapshot.privacyPolicy["rawCredentials"] == .string("secret-reference-only"),
      "TelemetryDeck raw credentials should stay behind secret references")

    let app = try unwrap(
      try services.data.getMarketplaceCatalogApp(
        workspaceId: workspace.id, appIdOrSlug: snapshot.appId),
      "missing TelemetryDeck app"
    )
    try expect(
      app.slug == "telemetrydeck", "TelemetryDeck catalog app should retain the intended slug")
    try expect(
      app.name == "TelemetryDeck", "TelemetryDeck catalog app should retain the canonical app name")
    try expect(
      app.websiteURL == "https://telemetrydeck.com/",
      "TelemetryDeck catalog app should retain the official website")
    try expect(
      app.docsURL == "https://telemetrydeck.com/docs/",
      "TelemetryDeck catalog app should retain official developer docs")
    try expect(
      app.connectionTypes?.contains("user_owned_telemetrydeck_pat") == true,
      "TelemetryDeck app should use user-owned PATs")
    try expect(app.readOnly, "TelemetryDeck app should be read-only in V1")
    let roleDefinitions = app.roleManifest.roleDefinitions ?? []
    try expect(
      roleDefinitions.allSatisfy { !$0.canWrite && $0.readOnly },
      "TelemetryDeck role manifest should not grant write authority")
    try expect(
      roleDefinitions.contains { $0.blockedActions.contains("telemetrydeck_ingest_signal") },
      "TelemetryDeck role manifest should block signal ingest")
    try expect(
      roleDefinitions.contains { $0.blockedActions.contains("telemetrydeck_raw_scan_export") },
      "TelemetryDeck role manifest should block raw scan export")
    try expect(
      roleDefinitions.contains { $0.blockedActions.contains("telemetrydeck_mcp_beta") },
      "TelemetryDeck role manifest should block beta MCP exposure")

    try expect(
      snapshot.credentials.map(\.fieldKey) == [
        "telemetrydeck_personal_access_token",
        "telemetrydeck_namespace",
        "telemetrydeck_app_id",
        "telemetrydeck_app_display_name",
        "telemetrydeck_default_insight_id",
      ],
      "TelemetryDeck foundation should list PAT, namespace, selected app, and optional display/insight metadata"
    )
    let credentialByKey = Dictionary(
      uniqueKeysWithValues: snapshot.credentials.map { ($0.fieldKey, $0) })
    try expect(
      credentialByKey["telemetrydeck_personal_access_token"]?.required == true,
      "TelemetryDeck PAT should be required")
    try expect(
      credentialByKey["telemetrydeck_personal_access_token"]?.secretStorage
        == "keychain-reference-only", "TelemetryDeck PAT should be Keychain-reference only")
    try expect(
      credentialByKey["telemetrydeck_namespace"]?.required == true,
      "TelemetryDeck namespace should be required")
    try expect(
      credentialByKey["telemetrydeck_namespace"]?.secretStorage == "metadata-only",
      "TelemetryDeck namespace should be non-secret metadata")
    try expect(
      credentialByKey["telemetrydeck_app_id"]?.required == true,
      "TelemetryDeck app ID should be required")
    try expect(
      credentialByKey["telemetrydeck_app_id"]?.secretStorage == "metadata-only",
      "TelemetryDeck app ID should be non-secret metadata")
    try expect(
      credentialByKey["telemetrydeck_default_insight_id"]?.secretStorage == "metadata-only",
      "TelemetryDeck saved insight id should be non-secret metadata")

    let expectedReadActions: Set<String> = [
      "telemetrydeck_user_info_read",
      "telemetrydeck_tql_query_read",
      "telemetrydeck_saved_insight_read",
    ]
    let expectedBlockedActions: Set<String> = [
      "telemetrydeck_ingest_signal",
      "telemetrydeck_raw_scan_export",
      "telemetrydeck_app_admin",
      "telemetrydeck_org_admin",
      "telemetrydeck_unbounded_query",
      "telemetrydeck_scheduled_polling",
      "telemetrydeck_mcp_beta",
    ]
    let actionByKey = Dictionary(uniqueKeysWithValues: snapshot.actions.map { ($0.actionKey, $0) })
    try expect(
      Set(actionByKey.keys) == expectedReadActions.union(expectedBlockedActions),
      "TelemetryDeck foundation should register the complete V1 action map")
    for actionKey in expectedReadActions.subtracting(["telemetrydeck_tql_query_read"]) {
      try expect(
        actionByKey[actionKey]?.policyPermission == .allowed,
        "TelemetryDeck read action \(actionKey) should be allowed by read-only policy")
      try expect(
        actionByKey[actionKey]?.wrapperToolName?.hasPrefix("relay_provider_telemetrydeck_") == true,
        "TelemetryDeck read action \(actionKey) should expose a Relay wrapper")
    }
    try expect(
      actionByKey["telemetrydeck_tql_query_read"]?.policyPermission == .approvalRequired,
      "TelemetryDeck bounded TQL query should stay approval-gated")
    try expect(
      actionByKey["telemetrydeck_tql_query_read"]?.wrapperToolName?.hasPrefix(
        "relay_provider_telemetrydeck_") == true,
      "TelemetryDeck bounded TQL should expose only a Relay wrapper")
    for actionKey in expectedBlockedActions {
      try expect(
        actionByKey[actionKey]?.policyPermission == .blocked,
        "TelemetryDeck blocked action \(actionKey) should stay blocked")
      try expect(
        actionByKey[actionKey]?.wrapperToolName == nil,
        "TelemetryDeck blocked action \(actionKey) should not have an agent-facing wrapper")
    }
    try expect(
      snapshot.agentFacingWrapperToolNames.count == 3,
      "TelemetryDeck foundation should expose three safe wrapper names")
    try expect(
      snapshot.agentFacingWrapperToolNames.allSatisfy {
        $0.hasPrefix("relay_provider_telemetrydeck_")
      }, "TelemetryDeck wrapper names should use Relay provider namespace")
    try expect(
      snapshot.blockedActionKeys == expectedBlockedActions.sorted(),
      "TelemetryDeck foundation should expose all blocked unsupported actions")

    let connection = try services.providerConnections.saveTelemetryDeckPATConnection(
      context: owner,
      appIdOrSlug: app.id,
      personalAccessToken: token,
      namespace: "relay-org",
      telemetryDeckAppId: "td-app-foundation-001",
      appDisplayName: "Relay iOS App",
      defaultInsightId: "td-insight-foundation-001",
      displayName: "Relay TelemetryDeck",
      validationResult: TelemetryDeckPATValidationResult(
        status: .ready,
        message: "TelemetryDeck Personal Access Token verified.",
        httpStatusCode: 200,
        userId: "td-user-foundation-001",
        userEmail: "relay.telemetry.foundation@example.com",
        organizationName: "Relay Telemetry Org"
      ),
      now: fixedDate("2026-01-01T00:00:02Z")
    )
    let agent = try createServiceAgent(services: services, workspaceId: workspace.id)
    let timestamp = "2026-01-01T00:00:03Z"
    let install = try services.data.saveMarketplaceInstall(
      MarketplaceInstallRecord(
        id: "minst-telemetrydeck-foundation-001",
        workspaceId: workspace.id,
        appId: app.id,
        appSlug: app.slug,
        connectionId: connection.id,
        agentId: agent.id,
        agentName: agent.name,
        runtimeBindingId: agent.binding.id,
        harnessId: agent.harness.id,
        runtimeType: agent.binding.runtimeType,
        roleId: app.roleManifest.primaryRole,
        roleLabel: "Analyst",
        selectedCapabilities: app.capabilities,
        approvalProfileId: "approval-telemetrydeck-foundation-default",
        runtimeFormat: agent.binding.runtimeType,
        targetMode: .existingAgent,
        riskAcknowledged: true,
        installStatus: .installed,
        driftStatus: .current,
        lastInstalledAt: timestamp,
        removedAt: nil,
        failureMessage: nil,
        metadata: [
          "providerActionFrameworkHydrated": .bool(true),
          "runtimeWriteDeferredReason": .string("telemetrydeck-read-only-v1"),
          "source": .string("telemetrydeck-foundation-test"),
        ],
        createdByActorId: owner.actorId,
        createdAt: timestamp,
        updatedAt: timestamp,
        redactionStatus: "private-state-excluded"
      ))
    let readOnly = try services.providerActionPolicies.compilePolicyMap(
      context: owner,
      appIdOrSlug: app.id,
      preset: .readOnly,
      connectionId: connection.id,
      installId: install.id,
      agentId: agent.id,
      now: fixedDate("2026-01-01T00:00:04Z")
    )
    try expect(
      readOnly.permissions["telemetrydeck_user_info_read"] == .allowed,
      "TelemetryDeck read-only policy should allow user-info reads")
    try expect(
      readOnly.permissions["telemetrydeck_saved_insight_read"] == .allowed,
      "TelemetryDeck read-only policy should allow saved insight reads")
    try expect(
      readOnly.permissions["telemetrydeck_tql_query_read"] == .approvalRequired,
      "TelemetryDeck read-only policy should keep bounded TQL approval-gated")
    try expect(
      readOnly.permissions["telemetrydeck_ingest_signal"] == .blocked,
      "TelemetryDeck read-only policy should block signal ingest")
    try expect(
      readOnly.permissions["telemetrydeck_raw_scan_export"] == .blocked,
      "TelemetryDeck read-only policy should block raw scan export")
    try expect(
      readOnly.permissions["telemetrydeck_app_admin"] == .blocked,
      "TelemetryDeck read-only policy should block app admin")
    try expect(
      readOnly.permissions["telemetrydeck_mcp_beta"] == .blocked,
      "TelemetryDeck read-only policy should block beta MCP exposure")
    let directAttempt = try services.providerActionPolicies.compilePolicyMap(
      context: owner,
      appIdOrSlug: app.id,
      preset: .allowDirectWrites, acknowledgeDangerousPolicy: true,
      connectionId: connection.id,
      installId: install.id,
      agentId: agent.id,
      now: fixedDate("2026-01-01T00:00:05Z")
    )
    try expect(
      !directAttempt.permissions.values.contains(.autoExecute),
      "TelemetryDeck direct-write attempt should not create auto-execute actions")
    try expect(
      directAttempt.permissions["telemetrydeck_tql_query_read"] == .approvalRequired,
      "TelemetryDeck direct-write attempt should keep bounded TQL approval-gated")

    let surface = try services.providerWrapperTools.compileSurface(
      context: member,
      appIdOrSlug: app.id,
      installId: install.id,
      agentId: agent.id,
      now: fixedDate("2026-01-01T00:00:06Z")
    )
    try expect(
      surface.tools.count == 3, "TelemetryDeck wrapper surface should expose exactly three tools")
    try expect(
      surface.tools.allSatisfy { $0.toolName.hasPrefix("relay_provider_telemetrydeck_") },
      "TelemetryDeck wrapper surface should expose only Relay wrapper names")
    try expect(
      surface.tools.contains { $0.displayName == "Run bounded TQL query" && $0.requiresApproval },
      "TelemetryDeck bounded TQL wrapper should require approval")
    try expect(
      surface.tools.contains { $0.displayName == "Read saved insight" && $0.readOnly },
      "TelemetryDeck saved insight wrapper should compile as read-only")
    try expect(
      !surface.tools.contains { $0.displayName == "Ingest signal" },
      "TelemetryDeck signal ingest should not become agent-facing")
    try expect(
      surface.diagnostics.blockedActionCount == 7,
      "TelemetryDeck wrapper diagnostics should count blocked unsupported actions")
    try expect(
      !surface.diagnostics.rawProviderToolExposure,
      "TelemetryDeck wrapper diagnostics should flag raw provider exposure as false")

    let retained = try services.database.all(
      """
      SELECT connection_json AS value FROM applications_provider_connections
      UNION ALL SELECT install_json AS value FROM applications_marketplace_installs
      """
    ).compactMap { sqliteText($0["value"]) }.joined(separator: "\n")
    try expect(!retained.contains(token), "TelemetryDeck storage leaked raw Personal Access Token")
    try expect(
      !retained.contains("relay-console://oauth/telemetrydeck/callback"),
      "TelemetryDeck PAT mode should not persist a Relay callback URL")
    try expect(
      retained.contains("[REDACTED]"),
      "TelemetryDeck connection persistence should retain redaction markers for sensitive metadata")
  }

  private static func testTelemetryDeckProviderAdapterRoutesThroughBrokerAndLiveClient() throws {
    final class StubTelemetryDeckHTTPClient: TelemetryDeckProviderHTTPClient, @unchecked Sendable {
      private let lock = NSLock()
      private var responses: [TelemetryDeckProviderHTTPResponse]
      private var requests: [TelemetryDeckProviderHTTPRequest] = []

      init(responses: [TelemetryDeckProviderHTTPResponse]) {
        self.responses = responses
      }

      func send(_ request: TelemetryDeckProviderHTTPRequest) throws
        -> TelemetryDeckProviderHTTPResponse
      {
        lock.lock()
        defer { lock.unlock() }
        requests.append(request)
        guard request.url.host == "api.telemetrydeckapi.com" else {
          throw MarketplaceProviderActionAdapterFailure(
            code: "stub_telemetrydeck_wrong_host",
            message: "TelemetryDeck stub expected the official API host."
          )
        }
        guard request.headers["Authorization"] == "Bearer td_pat_broker_sensitive_value" else {
          throw MarketplaceProviderActionAdapterFailure(
            code: "stub_telemetrydeck_missing_authorization",
            message: "TelemetryDeck stub expected the saved PAT only as an Authorization header."
          )
        }
        guard !responses.isEmpty else {
          throw MarketplaceProviderActionAdapterFailure(
            code: "stub_telemetrydeck_response_missing",
            message: "No stubbed TelemetryDeck response remained."
          )
        }
        return responses.removeFirst()
      }

      func capturedRequests() -> [TelemetryDeckProviderHTTPRequest] {
        lock.lock()
        defer { lock.unlock() }
        return requests
      }
    }

    func response(_ text: String, status: Int = 200) -> TelemetryDeckProviderHTTPResponse {
      TelemetryDeckProviderHTTPResponse(statusCode: status, body: Data(text.utf8))
    }

    let services = try makeServices()
    let workspace = try unwrap(services.data.getAppState().activeWorkspace, "missing workspace")
    let owner = Self.context(
      roles: [.owner], workspaceId: workspace.id, correlationId: "telemetrydeck-broker-owner-001")
    let token = "td_pat_broker_sensitive_value"
    _ = try services.providerFoundations.registerTelemetryDeckFoundation(
      context: owner,
      now: fixedDate("2026-01-01T00:00:00Z")
    )
    let app = try unwrap(
      try services.data.getMarketplaceCatalogApp(
        workspaceId: workspace.id, appIdOrSlug: "telemetrydeck"),
      "missing TelemetryDeck app"
    )
    let connection = try services.providerConnections.saveTelemetryDeckPATConnection(
      context: owner,
      appIdOrSlug: app.id,
      personalAccessToken: token,
      namespace: "relay-org",
      telemetryDeckAppId: "td-app-broker-001",
      appDisplayName: "Relay iOS App",
      defaultInsightId: "td-insight-default-001",
      displayName: "Relay TelemetryDeck",
      validationResult: TelemetryDeckPATValidationResult(
        status: .ready,
        message: "TelemetryDeck Personal Access Token verified.",
        httpStatusCode: 200,
        userId: "td-user-broker-001",
        userEmail: "relay.telemetry.broker@example.com",
        organizationName: "Relay Telemetry Org"
      ),
      now: fixedDate("2026-01-01T00:00:01Z")
    )
    let agent = try createServiceAgent(services: services, workspaceId: workspace.id)
    let install = try services.marketplaceInstalls.createInstall(
      context: owner,
      request: installRequest(
        id: "minreq-telemetrydeck-broker-001",
        workspaceId: workspace.id,
        app: app,
        connectionId: connection.id,
        agent: agent,
        roleId: app.roleManifest.primaryRole,
        selectedCapabilities: app.capabilities,
        riskAcknowledged: true
      ),
      now: fixedDate("2026-01-01T00:00:02Z")
    )
    _ = try services.providerActionPolicies.compilePolicyMap(
      context: owner,
      appIdOrSlug: app.id,
      preset: .readOnly,
      connectionId: connection.id,
      installId: install.id,
      agentId: agent.id,
      now: fixedDate("2026-01-01T00:00:03Z")
    )

    let tqlPayload: JSONRecord = [
      "query": .object([
        "queryType": .string("topN"),
        "dimension": .string("eventName"),
      ]),
      "relativeDays": .number(30),
      "maxRows": .number(2),
    ]
    let stub = StubTelemetryDeckHTTPClient(responses: [
      response(
        #"{"id":"td-user-broker-001","email":"relay.telemetry.broker@example.com","organizationName":"Relay Telemetry Org"}"#
      ),
      response(
        #"{"result":{"type":"topNResult","rows":[{"label":"App Open","result":[{"date":"2026-01-01","value":42},{"date":"2026-01-02","value":51}]},{"label":"Purchase","result":[{"date":"2026-01-01","value":7}]}]},"calculationDuration":0.42,"calculationFinishedAt":"2026-01-01T00:00:10Z"}"#
      ),
      response(#"{"queryType":"topN","dimension":"eventName","threshold":50}"#),
      response(
        #"{"result":{"type":"topNResult","rows":[{"label":"Saved Insight Event","result":[{"date":"2026-01-01","value":12}]}]},"calculationDuration":0.21,"calculationFinishedAt":"2026-01-01T00:00:11Z"}"#
      ),
      response(#"{"error":"rate limited"}"#, status: 429),
    ])
    let broker = MarketplaceProviderActionBrokerService(
      data: services.data,
      approvals: services.providerActionApprovals,
      auditSecurity: services.auditSecurity,
      adapter: RoutingMarketplaceProviderActionAdapter(
        telemetryDeckAdapter: TelemetryDeckProviderActionAdapter(
          client: LiveTelemetryDeckProviderActionClient(
            data: services.data,
            secrets: services.secrets,
            httpClient: stub
          )
        )
      )
    )

    let userInfo = try broker.execute(
      context: owner,
      request: MarketplaceProviderActionBrokerRequest(
        appIdOrSlug: app.id,
        actionKey: "telemetrydeck_user_info_read",
        payload: [:],
        connectionId: connection.id,
        installId: install.id,
        agentId: agent.id,
        idempotencyKey: "telemetrydeck-user-info-broker-001"
      ),
      now: fixedDate("2026-01-01T00:00:04Z")
    )
    try expect(
      userInfo.adapterExecuted,
      "TelemetryDeck user-info read should execute through the broker adapter")
    try expect(
      userInfo.execution.status == .succeeded,
      "TelemetryDeck user-info read should persist a succeeded execution")
    try expect(
      userInfo.execution.providerResult?["clientMode"] == .string("live-telemetrydeck-api"),
      "TelemetryDeck user-info result should identify the live adapter")
    try expect(
      userInfo.execution.providerResult?["fakeAdapter"] == .bool(false),
      "TelemetryDeck user-info result should not use fake adapter evidence")

    let pendingTQL = try broker.execute(
      context: owner,
      request: MarketplaceProviderActionBrokerRequest(
        appIdOrSlug: app.id,
        actionKey: "telemetrydeck_tql_query_read",
        payload: tqlPayload,
        connectionId: connection.id,
        installId: install.id,
        agentId: agent.id,
        idempotencyKey: "telemetrydeck-tql-broker-001"
      ),
      now: fixedDate("2026-01-01T00:00:05Z")
    )
    try expect(
      !pendingTQL.adapterExecuted,
      "TelemetryDeck bounded TQL should wait for approval before adapter execution")
    try expect(
      pendingTQL.execution.status == .pendingApproval,
      "TelemetryDeck bounded TQL should create a pending approval execution")
    let approval = try unwrap(
      pendingTQL.approval, "TelemetryDeck bounded TQL should create an approval")
    let approved = try services.providerActionApprovals.approve(
      context: owner,
      approvalId: approval.id,
      approvedPayload: tqlPayload,
      now: fixedDate("2026-01-01T00:00:06Z")
    )
    let executedTQL = try broker.execute(
      context: owner,
      request: MarketplaceProviderActionBrokerRequest(
        appIdOrSlug: app.id,
        actionKey: "telemetrydeck_tql_query_read",
        payload: tqlPayload,
        connectionId: connection.id,
        installId: install.id,
        agentId: agent.id,
        approvalId: approved.id,
        idempotencyKey: "telemetrydeck-tql-broker-approved-001"
      ),
      now: fixedDate("2026-01-01T00:00:07Z")
    )
    try expect(
      executedTQL.adapterExecuted,
      "Approved TelemetryDeck bounded TQL should execute through the broker adapter")
    try expect(
      executedTQL.execution.status == .succeeded,
      "Approved TelemetryDeck bounded TQL should persist a succeeded execution")
    let tqlResult = try unwrap(
      executedTQL.execution.providerResult, "missing TelemetryDeck TQL provider result")
    try expect(
      tqlResult["queryType"] == .string("topN"), "TelemetryDeck TQL result should retain query type"
    )
    try expect(
      tqlResult["namespace"] == .string("relay-org"),
      "TelemetryDeck TQL result should retain namespace context")
    try expect(
      tqlResult["telemetryDeckAppId"] == .string("td-app-broker-001"),
      "TelemetryDeck TQL result should retain app context")
    try expect(
      tqlResult["resultType"] == .string("topNResult"),
      "TelemetryDeck TQL result should retain result type")
    try expect(
      tqlResult["rowCount"] == .number(3), "TelemetryDeck TQL result should count source rows")
    try expect(
      tqlResult["returnedRowCount"] == .number(2),
      "TelemetryDeck TQL result should cap returned rows")
    try expect(
      tqlResult["truncated"] == .bool(true), "TelemetryDeck TQL result should report truncation")
    guard case .array(let rows)? = tqlResult["rows"],
      let firstRow = rows.compactMap(objectValue).first
    else {
      throw ServiceTestFailure("TelemetryDeck TQL result should include semantic rows")
    }
    try expect(
      firstRow["label"] == .string("App Open"), "TelemetryDeck TQL rows should retain labels")

    let savedInsight = try broker.execute(
      context: owner,
      request: MarketplaceProviderActionBrokerRequest(
        appIdOrSlug: app.id,
        actionKey: "telemetrydeck_saved_insight_read",
        payload: [
          "insightId": .string("td-insight-default-001"),
          "relativeDays": .number(7),
          "maxRows": .number(5),
        ],
        connectionId: connection.id,
        installId: install.id,
        agentId: agent.id,
        idempotencyKey: "telemetrydeck-saved-insight-broker-001"
      ),
      now: fixedDate("2026-01-01T00:00:08Z")
    )
    try expect(
      savedInsight.adapterExecuted,
      "TelemetryDeck saved insight should execute through the broker adapter")
    try expect(
      savedInsight.execution.status == .succeeded,
      "TelemetryDeck saved insight should persist a succeeded execution")
    let insightResult = try unwrap(
      savedInsight.execution.providerResult, "missing TelemetryDeck saved-insight result")
    try expect(
      objectValue(insightResult["insight"])?["id"] == .string("td-insight-default-001"),
      "TelemetryDeck saved insight should retain insight id")
    try expect(
      insightResult["rowCount"] == .number(1),
      "TelemetryDeck saved insight should return bounded semantic rows")

    let blockedIngest = try broker.execute(
      context: owner,
      request: MarketplaceProviderActionBrokerRequest(
        appIdOrSlug: app.id,
        actionKey: "telemetrydeck_ingest_signal",
        payload: ["signal": .object(["event": .string("blocked")])],
        connectionId: connection.id,
        installId: install.id,
        agentId: agent.id,
        idempotencyKey: "telemetrydeck-ingest-blocked-001"
      ),
      now: fixedDate("2026-01-01T00:00:09Z")
    )
    try expect(
      !blockedIngest.adapterExecuted,
      "TelemetryDeck ingest should be blocked before adapter execution")
    try expect(
      blockedIngest.execution.status == .blocked,
      "TelemetryDeck ingest should persist blocked execution")

    let providerError = try broker.execute(
      context: owner,
      request: MarketplaceProviderActionBrokerRequest(
        appIdOrSlug: app.id,
        actionKey: "telemetrydeck_saved_insight_read",
        payload: [
          "insightId": .string("td-insight-rate-limited-001"),
          "relativeDays": .number(7),
        ],
        connectionId: connection.id,
        installId: install.id,
        agentId: agent.id,
        idempotencyKey: "telemetrydeck-rate-limit-001"
      ),
      now: fixedDate("2026-01-01T00:00:10Z")
    )
    try expect(
      providerError.adapterExecuted,
      "TelemetryDeck provider error should still execute through adapter")
    try expect(
      providerError.execution.status == .failed,
      "TelemetryDeck provider error should persist failed execution")
    try expect(
      providerError.execution.providerError?["providerErrorCode"]
        == .string("telemetrydeck_rate_limited"),
      "TelemetryDeck 429 should map to rate-limited error")

    let captured = stub.capturedRequests()
    try expect(
      captured.count == 5,
      "TelemetryDeck stub should receive user-info, TQL, saved-insight generation, saved-insight TQL, and rate-limit generation requests"
    )
    try expect(
      captured[0].method == "GET" && captured[0].url.path == "/api/v3/users/info",
      "TelemetryDeck user-info read should call official user-info endpoint")
    try expect(
      captured[1].method == "POST" && captured[1].url.path == "/api/v4/query/tql",
      "TelemetryDeck bounded TQL should call official TQL endpoint")
    try expect(
      captured[2].method == "POST"
        && captured[2].url.absoluteString.hasSuffix(
          "/api/v3/insights/td-insight-default-001/query/"),
      "TelemetryDeck saved insight should request generated TQL")
    try expect(
      captured[3].method == "POST" && captured[3].url.path == "/api/v4/query/tql",
      "TelemetryDeck saved insight should execute generated TQL")
    let tqlBody = try unwrap(
      captured[1].body.flatMap { String(data: $0, encoding: .utf8) },
      "missing TelemetryDeck TQL request body")
    try expect(
      tqlBody.contains("\"dataSource\":\"relay-org\""),
      "TelemetryDeck TQL body should enforce saved namespace")
    try expect(
      tqlBody.contains("td-app-broker-001"), "TelemetryDeck TQL body should enforce saved app ID")
    try expect(
      !tqlBody.localizedCaseInsensitiveContains("scan"),
      "TelemetryDeck TQL body should not contain raw scan query")

    let retained = try services.database.all(
      """
      SELECT connection_json AS value FROM applications_provider_connections
      UNION ALL SELECT execution_json AS value FROM marketplace_provider_action_executions
      UNION ALL SELECT install_json AS value FROM applications_marketplace_installs
      """
    ).compactMap { sqliteText($0["value"]) }.joined(separator: "\n")
    try expect(!retained.contains(token), "TelemetryDeck broker evidence leaked raw PAT")
    try expect(
      !retained.contains("Authorization: Bearer"),
      "TelemetryDeck broker evidence leaked Authorization header")
    try expect(
      retained.contains("[REDACTED]"),
      "TelemetryDeck broker evidence should retain redaction markers")
  }

  private static func testTelemetryDeckRuntimeMountExposesBrokeredReadTools() throws {
    let root = FileManager.default.temporaryDirectory
      .appendingPathComponent("RelayConsoleTelemetryDeckRuntimeMountTests", isDirectory: true)
      .appendingPathComponent(UUID().uuidString, isDirectory: true)
    let token = "td_pat_runtime_mount_sensitive_value"
    let services = try makeServices(
      root: root,
      providerActionAdapter: RoutingMarketplaceProviderActionAdapter(
        telemetryDeckAdapter: TelemetryDeckProviderActionAdapter(
          client: FakeTelemetryDeckProviderActionClient())
      )
    )
    let workspace = try unwrap(services.data.getAppState().activeWorkspace, "missing workspace")
    let owner = Self.context(
      roles: [.owner], workspaceId: workspace.id, correlationId: "telemetrydeck-runtime-owner-001")
    let member = Self.context(
      roles: [.member], workspaceId: workspace.id, correlationId: "telemetrydeck-runtime-member-001"
    )
    let hermesHarness = try prepareInstalledHarness(services: services, key: .hermes)
    let openClawHarness = try prepareInstalledHarness(services: services, key: .openclaw)
    let hermesHome = root.appendingPathComponent(
      "telemetrydeck-runtime-hermes-profile", isDirectory: true)
    let openClawStateDir = root.appendingPathComponent(
      "telemetrydeck-runtime-openclaw-home", isDirectory: true)
    let openClawAgentDir = openClawStateDir.appendingPathComponent(
      "agents/telemetrydeck-runtime-openclaw/agent", isDirectory: true)
    let openClawWorkspaceDir = openClawStateDir.appendingPathComponent(
      "workspace-telemetrydeck-runtime-openclaw", isDirectory: true)
    let hermesAgent = try services.data.createAgent(
      workspaceId: workspace.id,
      name: "TelemetryDeck Runtime Hermes",
      harnessId: hermesHarness.id,
      externalAgentId: "telemetrydeck-runtime-hermes",
      hermesProfileSlug: "telemetrydeck-runtime-hermes",
      hermesHomePath: hermesHome.path,
      hermesIdentityFilePath: hermesHome.appendingPathComponent("identity.json").path
    )
    let openClawAgent = try services.data.createAgent(
      workspaceId: workspace.id,
      name: "TelemetryDeck Runtime OpenClaw",
      harnessId: openClawHarness.id,
      externalAgentId: "telemetrydeck-runtime-openclaw",
      workspaceFolderPath: openClawWorkspaceDir.path,
      config: [
        "openclawAgentDir": .string(openClawAgentDir.path),
        "openclawStateDir": .string(openClawStateDir.path),
      ]
    )
    _ = try services.providerFoundations.registerTelemetryDeckFoundation(
      context: owner,
      now: fixedDate("2026-01-01T00:00:00Z")
    )
    let app = try unwrap(
      try services.data.getMarketplaceCatalogApp(
        workspaceId: workspace.id, appIdOrSlug: "telemetrydeck"),
      "missing TelemetryDeck app"
    )
    let connection = try services.providerConnections.saveTelemetryDeckPATConnection(
      context: owner,
      appIdOrSlug: app.id,
      personalAccessToken: token,
      namespace: "relay-runtime-org",
      telemetryDeckAppId: "td-runtime-app-001",
      appDisplayName: "Runtime iOS App",
      defaultInsightId: "td-runtime-insight-001",
      displayName: "Runtime TelemetryDeck",
      validationResult: TelemetryDeckPATValidationResult(
        status: .ready,
        message: "TelemetryDeck Personal Access Token verified.",
        httpStatusCode: 200,
        userId: "td-runtime-user-001",
        userEmail: "runtime.telemetry@example.com",
        organizationName: "Runtime Telemetry Org"
      ),
      now: fixedDate("2026-01-01T00:00:01Z")
    )

    func install(agent: AgentWithBinding, suffix: String, now: String) throws
      -> MarketplaceInstallRecord
    {
      try services.marketplaceInstalls.createInstall(
        context: owner,
        request: installRequest(
          id: "minreq-telemetrydeck-runtime-\(suffix)",
          workspaceId: workspace.id,
          app: app,
          connectionId: connection.id,
          agent: agent,
          roleId: app.roleManifest.primaryRole,
          selectedCapabilities: app.capabilities,
          riskAcknowledged: true
        ),
        now: fixedDate(now)
      )
    }

    let hermesInstall = try install(
      agent: hermesAgent, suffix: "hermes", now: "2026-01-01T00:00:02Z")
    let openClawInstall = try install(
      agent: openClawAgent, suffix: "openclaw", now: "2026-01-01T00:00:03Z")
    _ = try services.providerActionPolicies.compilePolicyMap(
      context: owner,
      appIdOrSlug: app.id,
      preset: .readOnly,
      connectionId: connection.id,
      installId: hermesInstall.id,
      agentId: hermesAgent.id,
      now: fixedDate("2026-01-01T00:00:04Z")
    )
    _ = try services.providerActionPolicies.compilePolicyMap(
      context: owner,
      appIdOrSlug: app.id,
      preset: .readOnly,
      connectionId: connection.id,
      installId: openClawInstall.id,
      agentId: openClawAgent.id,
      now: fixedDate("2026-01-01T00:00:05Z")
    )

    func assertTelemetryDeckRuntime(
      snapshot: MarketplaceRuntimeCapabilitySnapshot, agent: AgentWithBinding, suffix: String
    ) throws {
      try expect(
        snapshot.apps.map(\.appSlug) == ["telemetrydeck"],
        "TelemetryDeck runtime mount should include only the installed TelemetryDeck app")
      try expect(
        snapshot.toolCount == 3,
        "TelemetryDeck runtime mount should expose the three V1 wrapper tools")
      try expect(
        !snapshot.rawProviderToolExposure,
        "TelemetryDeck runtime mount must not expose raw provider tools")
      let mounted = try unwrap(snapshot.apps.first, "missing TelemetryDeck mounted app")
      try expect(
        mounted.connected && mounted.assignedAgentReady,
        "TelemetryDeck runtime mount should be connected and assigned")
      try expect(
        mounted.instructions.contains("read-only app analytics"),
        "TelemetryDeck runtime instructions should be provider-specific")
      try expect(
        mounted.instructions.contains("bounded approved TQL"),
        "TelemetryDeck runtime instructions should explain approval-gated TQL")
      try expect(
        mounted.instructions.contains("Do not ingest signals"),
        "TelemetryDeck runtime instructions should block ingest writes")
      try expect(
        mounted.tools.allSatisfy { $0.toolName.hasPrefix("relay_provider_telemetrydeck_") },
        "TelemetryDeck runtime tools should use Relay wrapper names")
      try expect(
        mounted.tools.contains {
          $0.displayName == "Read user info" && $0.readOnly && !$0.requiresApproval
        }, "TelemetryDeck runtime should expose user-info read")
      try expect(
        mounted.tools.contains {
          $0.displayName == "Read saved insight" && $0.readOnly && !$0.requiresApproval
        }, "TelemetryDeck runtime should expose saved-insight read")
      try expect(
        mounted.tools.contains {
          $0.displayName == "Run bounded TQL query" && $0.readOnly && $0.requiresApproval
        }, "TelemetryDeck runtime should expose approval-gated bounded TQL")
      try expect(
        !mounted.tools.contains { $0.displayName == "Ingest signal" },
        "TelemetryDeck ingest must not become a runtime tool")
      let prompt = try unwrap(
        services.marketplaceRuntimeMounts.renderPromptBlock(snapshot),
        "missing TelemetryDeck runtime prompt")
      try expect(
        prompt.contains("App: TelemetryDeck (telemetrydeck)"),
        "TelemetryDeck runtime prompt should name the mounted app")
      try expect(
        !prompt.contains("relay_provider_telemetrydeck_"),
        "TelemetryDeck runtime prompt should not render wrapper names as fake text tools")
      for leaked in [
        token,
        "td_pat_runtime_mount_sensitive_value",
        "Authorization",
        "telemetrydeck_ingest_signal",
        "telemetrydeck_raw_scan_export",
        "telemetrydeck_app_admin",
        "telemetrydeck_org_admin",
        "official_mcp",
        "community_mcp",
      ] {
        try expect(
          !prompt.contains(leaked),
          "TelemetryDeck runtime prompt leaked raw provider state or blocked tool \(leaked)")
      }

      let userInfoTool = try unwrap(
        mounted.tools.first { $0.displayName == "Read user info" },
        "missing TelemetryDeck user-info wrapper")
      let userInfo = try services.marketplaceRuntimeToolBridge.execute(
        toolName: userInfoTool.toolName,
        payload: [:],
        runtime: MarketplaceRuntimeToolExecutionContext(
          agentId: agent.id,
          workspaceId: workspace.id,
          runtimeType: snapshot.runtimeType,
          dispatchId: "rtd-telemetrydeck-runtime-user-info-\(suffix)",
          threadId: "thr-telemetrydeck-runtime-user-info-\(suffix)",
          runtimeSessionId: "rts-telemetrydeck-runtime-user-info-\(suffix)",
          correlationId: "telemetrydeck-runtime-user-info-\(suffix)"
        ),
        now: fixedDate("2026-01-01T00:00:06Z")
      )
      try expect(
        userInfo["toolName"] == .string(userInfoTool.toolName),
        "TelemetryDeck runtime bridge should echo user-info wrapper name")
      try expect(
        userInfo["appSlug"] == .string("telemetrydeck"),
        "TelemetryDeck runtime bridge should map user-info back to TelemetryDeck")
      try expect(
        userInfo["actionKey"] == .string("telemetrydeck_user_info_read"),
        "TelemetryDeck runtime bridge should resolve user-info action")
      try expect(
        userInfo["adapterExecuted"] == .bool(true),
        "TelemetryDeck runtime user-info read should execute through the broker adapter")
      let userInfoProviderResult = try unwrap(
        objectValue(userInfo["providerResult"]),
        "TelemetryDeck runtime user-info should return provider result")
      try expect(
        userInfoProviderResult["clientMode"] == .string("fake-telemetrydeck-client"),
        "TelemetryDeck runtime test should use fake TelemetryDeck client")
      try expect(
        userInfoProviderResult["fakeAdapter"] == .bool(true),
        "TelemetryDeck runtime user-info should mark fake adapter evidence")

      let savedInsightTool = try unwrap(
        mounted.tools.first { $0.displayName == "Read saved insight" },
        "missing TelemetryDeck saved-insight wrapper")
      let savedInsight = try services.marketplaceRuntimeToolBridge.execute(
        toolName: savedInsightTool.toolName,
        payload: [
          "insightId": .string("td-runtime-insight-001"),
          "maxRows": .number(3),
        ],
        runtime: MarketplaceRuntimeToolExecutionContext(
          agentId: agent.id,
          workspaceId: workspace.id,
          runtimeType: snapshot.runtimeType,
          dispatchId: "rtd-telemetrydeck-runtime-insight-\(suffix)",
          threadId: "thr-telemetrydeck-runtime-insight-\(suffix)",
          runtimeSessionId: "rts-telemetrydeck-runtime-insight-\(suffix)",
          correlationId: "telemetrydeck-runtime-insight-\(suffix)"
        ),
        now: fixedDate("2026-01-01T00:00:06Z")
      )
      try expect(
        savedInsight["actionKey"] == .string("telemetrydeck_saved_insight_read"),
        "TelemetryDeck runtime bridge should resolve saved-insight action")
      try expect(
        savedInsight["adapterExecuted"] == .bool(true),
        "TelemetryDeck runtime saved insight should execute through the broker adapter")
      let insightProviderResult = try unwrap(
        objectValue(savedInsight["providerResult"]),
        "TelemetryDeck runtime saved insight should return provider result")
      try expect(
        objectValue(insightProviderResult["insight"])?["id"] == .string("td-runtime-insight-001"),
        "TelemetryDeck runtime saved insight should retain insight id")

      let tqlTool = try unwrap(
        mounted.tools.first { $0.displayName == "Run bounded TQL query" },
        "missing TelemetryDeck TQL wrapper")
      let tqlPayload: JSONRecord = [
        "query": .object([
          "queryType": .string("topN"),
          "dimension": .string("eventName"),
        ]),
        "relativeDays": .number(14),
        "maxRows": .number(5),
      ]
      let pendingTQL = try services.marketplaceRuntimeToolBridge.execute(
        toolName: tqlTool.toolName,
        payload: tqlPayload,
        runtime: MarketplaceRuntimeToolExecutionContext(
          agentId: agent.id,
          workspaceId: workspace.id,
          runtimeType: snapshot.runtimeType,
          dispatchId: "rtd-telemetrydeck-runtime-tql-\(suffix)",
          threadId: "thr-telemetrydeck-runtime-tql-\(suffix)",
          runtimeSessionId: "rts-telemetrydeck-runtime-tql-\(suffix)",
          correlationId: "telemetrydeck-runtime-tql-\(suffix)"
        ),
        now: fixedDate("2026-01-01T00:00:06Z")
      )
      try expect(
        pendingTQL["appSlug"] == .string("telemetrydeck"),
        "TelemetryDeck runtime TQL wrapper should map back to TelemetryDeck")
      try expect(
        pendingTQL["actionKey"] == .string("telemetrydeck_tql_query_read"),
        "TelemetryDeck runtime TQL wrapper should resolve bounded TQL action")
      try expect(
        pendingTQL["executionStatus"]
          == .string(ProviderActionExecutionStatus.pendingApproval.rawValue),
        "TelemetryDeck runtime TQL should create a pending approval execution")
      try expect(
        pendingTQL["adapterExecuted"] == .bool(false),
        "TelemetryDeck runtime TQL must not execute before approval")
      try expect(
        pendingTQL["requiresApproval"] == .bool(true),
        "TelemetryDeck runtime TQL wrapper should be approval-required")
      let approval = try unwrap(
        objectValue(pendingTQL["approval"]),
        "TelemetryDeck runtime TQL should return approval metadata")
      let approvalId = try unwrap(
        approval["approvalId"]?.string, "TelemetryDeck runtime TQL should include approval id")
      let approvalRecord = try services.providerActionApprovals.getApproval(
        context: owner, approvalId: approvalId)
      try expect(
        approvalRecord.status == .pending,
        "TelemetryDeck runtime TQL should create a pending provider-action approval")
    }

    let hermesSnapshot = try services.marketplaceRuntimeMounts.snapshot(
      context: member,
      agent: hermesAgent,
      now: fixedDate("2026-01-01T00:00:06Z")
    )
    try expect(
      hermesSnapshot.runtimeType == .hermes,
      "TelemetryDeck Hermes snapshot should record Hermes runtime")
    try assertTelemetryDeckRuntime(snapshot: hermesSnapshot, agent: hermesAgent, suffix: "hermes")

    let openClawSnapshot = try services.marketplaceRuntimeMounts.snapshot(
      context: member,
      agent: openClawAgent,
      now: fixedDate("2026-01-01T00:00:07Z")
    )
    try expect(
      openClawSnapshot.runtimeType == .openclaw,
      "TelemetryDeck OpenClaw snapshot should record OpenClaw runtime")
    try assertTelemetryDeckRuntime(
      snapshot: openClawSnapshot, agent: openClawAgent, suffix: "openclaw")

    let retained = try services.database.all(
      """
      SELECT connection_json AS value FROM applications_provider_connections
      UNION ALL SELECT execution_json AS value FROM marketplace_provider_action_executions
      UNION ALL SELECT approval_json AS value FROM marketplace_provider_action_approvals
      UNION ALL SELECT install_json AS value FROM applications_marketplace_installs
      """
    ).compactMap { sqliteText($0["value"]) }.joined(separator: "\n")
    try expect(!retained.contains(token), "TelemetryDeck runtime evidence leaked raw PAT")
    try expect(
      !retained.contains("Authorization: Bearer"),
      "TelemetryDeck runtime evidence leaked Authorization header")
    try expect(
      retained.contains("[REDACTED]"),
      "TelemetryDeck runtime evidence should retain redaction markers")
  }

  private static func testTelemetryDeckAssignmentHydratesReadOnlyAuthorityControls() throws {
