      roles: [.owner], workspaceId: workspace.id,
      correlationId: "telemetrydeck-assignment-owner-001")
    let member = Self.context(
      roles: [.member], workspaceId: workspace.id,
      correlationId: "telemetrydeck-assignment-member-001")
    let token = "td_pat_assignment_sensitive_value"

