    try expect(
      hydratedMap.permissions["telemetrydeck_saved_insight_read"] == .allowed,
      "Read only TelemetryDeck authority should allow saved-insight reads")
    try expect(
      hydratedMap.permissions["telemetrydeck_tql_query_read"] == .approvalRequired,
      "Read only TelemetryDeck authority should keep bounded TQL approval-gated")
    try expect(
      hydratedMap.permissions["telemetrydeck_ingest_signal"] == .blocked,
      "Read only TelemetryDeck authority should block ingest writes")

    let readOnlySurface = try services.providerWrapperTools.compileSurface(
      context: member,
      appIdOrSlug: app.id,
      installId: install.id,
      agentId: agent.id,
      now: fixedDate("2026-01-01T00:00:04Z")
    )
    try expect(
      readOnlySurface.tools.count == 3,
      "Read only TelemetryDeck assignment should expose three wrapper tools")
    try expect(
      readOnlySurface.policyPreset == .readOnly,
      "TelemetryDeck wrapper surface should report Read only authority")
    try expect(
      readOnlySurface.tools.allSatisfy { $0.toolName.hasPrefix("relay_provider_telemetrydeck_") },
      "TelemetryDeck assignment should expose only Relay wrapper tools")

    let blockedMap = try services.providerActionPolicies.compilePolicyMap(
      context: owner,
      appIdOrSlug: app.id,
      preset: .blocked,
      connectionId: primaryConnection.id,
      installId: install.id,
      agentId: agent.id,
      now: fixedDate("2026-01-01T00:00:05Z")
    )
    try expect(
      blockedMap.policyPreset == .blocked,
      "TelemetryDeck No access authority should compile as blocked")
    let blockedSurface = try services.providerWrapperTools.compileSurface(
      context: member,
      appIdOrSlug: app.id,
      installId: install.id,
      agentId: agent.id,
      now: fixedDate("2026-01-01T00:00:06Z")
    )
    try expect(
      blockedSurface.tools.isEmpty, "TelemetryDeck No access authority should remove wrapper tools")
    try expect(
      blockedSurface.policyPreset == .blocked,
      "TelemetryDeck blocked wrapper surface should report No access authority")

    let selectedOtherSnapshot = try services.providerConnections.snapshot(
      context: member,
      appIdOrSlug: app.id,
      selectedConnectionId: otherConnection.id,
      now: fixedDate("2026-01-01T00:00:07Z")
    )
    try expect(
      selectedOtherSnapshot.selectedConnection?.id == otherConnection.id,
      "TelemetryDeck active connection selection should be visible in provider snapshots")
    let storedInstall = try unwrap(
      try services.data.getMarketplaceInstall(workspaceId: workspace.id, installId: install.id),
      "missing stored TelemetryDeck install"
    )
    try expect(
      storedInstall.connectionId == primaryConnection.id,
      "Selecting another TelemetryDeck app connection must not silently retarget assigned agents")

    let retained = try services.database.all(
      """
      SELECT connection_json AS value FROM applications_provider_connections
      UNION ALL SELECT install_json AS value FROM applications_marketplace_installs
      UNION ALL SELECT map_json AS value FROM marketplace_action_permission_maps
      """
    ).compactMap { sqliteText($0["value"]) }.joined(separator: "\n")
    try expect(!retained.contains(token), "TelemetryDeck assignment persistence leaked raw PAT")
    try expect(
      !retained.contains("td_pat_assignment_second_sensitive_value"),
      "TelemetryDeck second connection persistence leaked raw PAT")
    try expect(
      retained.contains("[REDACTED]"),
      "TelemetryDeck assignment evidence should retain redaction markers")
  }

  private static func testSentryProviderConnectionIsKeychainBackedAndHealthChecked() throws {
    actor StubSentryTokenValidator: SentryTokenValidating {
      private var responsesByToken: [String: [SentryTokenValidationResult]]

      init(responsesByToken: [String: [SentryTokenValidationResult]]) {
        self.responsesByToken = responsesByToken
      }

      func validate(authToken: String, organizationSlug: String, baseURL: String?) async
        -> SentryTokenValidationResult
      {
        let token = authToken.trimmingCharacters(in: .whitespacesAndNewlines)
        guard var responses = responsesByToken[token], !responses.isEmpty else {
          return SentryTokenValidationResult(
            status: .invalidToken,
            message: "Stub Sentry validator has no response for this token.",
            httpStatusCode: 401,
            organizationSlug: organizationSlug,
            baseURL: baseURL
          )
        }
        let response = responses.removeFirst()
        responsesByToken[token] = responses
        return response
      }
    }

    let root = FileManager.default.temporaryDirectory
      .appendingPathComponent("RelayConsoleSentryProviderConnectionTests", isDirectory: true)
      .appendingPathComponent(UUID().uuidString, isDirectory: true)
    let services = try makeServices(root: root)
    let workspace = try unwrap(services.data.getAppState().activeWorkspace, "missing workspace")
    let owner = Self.context(
      roles: [.owner], workspaceId: workspace.id, correlationId: "sentry-connection-owner-001")
    let admin = Self.context(
      roles: [.admin], workspaceId: workspace.id, correlationId: "sentry-connection-admin-001")
    let rawAuthToken = "sentry-auth-token-provider-contract-sensitive-value"
    let rawReconnectToken = "sentry-auth-token-reconnected-sensitive-value"
    let sentryApp = marketplaceApp(
      workspaceId: workspace.id,
      slug: "sentry",
      name: "Sentry",
      summary: "User-owned Sentry auth token.",
      category: "Observability",
      riskLevel: .high,
      connectionState: .none,
      installState: .notInstalled
    )
    _ = try services.applications.saveCatalogApps(context: owner, apps: [sentryApp])

    let validator = StubSentryTokenValidator(responsesByToken: [
      rawAuthToken: [
        SentryTokenValidationResult(
          status: .ready,
          message: "Sentry auth token verified with a bounded organization projects request.",
          httpStatusCode: 200,
          organizationSlug: "relay-org",
          organizationName: "Relay Org",
          projectCount: 2,
          baseURL: "https://sentry.io"
        ),
        SentryTokenValidationResult(
          status: .ready,
          message: "Sentry auth token verified with a bounded organization projects request.",
          httpStatusCode: 200,
          organizationSlug: "relay-org",
          organizationName: "Relay Org",
          projectCount: 3,
          baseURL: "https://sentry.io"
        ),
        SentryTokenValidationResult(
          status: .insufficientScope,
          message: "Sentry accepted the token but denied organization/project access.",
          httpStatusCode: 403,
          organizationSlug: "relay-org",
          organizationName: "Relay Org",
          baseURL: "https://sentry.io"
        ),
      ],
      rawReconnectToken: [
        SentryTokenValidationResult(
          status: .ready,
          message: "Sentry auth token verified with a bounded organization projects request.",
          httpStatusCode: 200,
          organizationSlug: "relay-org-reconnected",
          organizationName: "Relay Org Reconnected",
          projectCount: 1,
          baseURL: "https://sentry.io"
        )
      ],
    ])
    let connectionService = ProviderConnectionService(
      data: services.data,
      secrets: services.secrets,
      sentryValidator: validator
    )

    let connected = try awaitResult {
      try await connectionService.connectSentryAuthToken(
        context: owner,
        appIdOrSlug: sentryApp.slug,
        authToken: rawAuthToken,
        organizationSlug: "relay-org",
        baseURL: "https://sentry.io",
        defaultProjectSlug: "web-app",
        defaultEnvironment: "production",
        displayName: "Relay Sentry",
        now: fixedDate("2026-01-01T00:00:00Z")
      )
    }
    try expect(
      connected.appSlug == "sentry", "Sentry connection should target the canonical app slug")
    try expect(connected.providerName == "Sentry", "Sentry provider name should be explicit")
    try expect(connected.status == .connected, "Sentry auth token should mark the connection ready")
    try expect(
      connected.health.state == .ready,
      "Sentry auth token should save ready health after validation")
    try expect(
      connected.authorizationState == .completed,
      "Sentry auth-token mode should not wait for OAuth callback authorization")
    try expect(
      connected.credentialOwnership == .userOwned, "Sentry token should record user-owned ownership"
    )
    try expect(
      connected.secretReferenceIds.count == 1, "Sentry auth token should use one Keychain reference"
    )
    try expect(
      connected.requiredScopes == ProviderConnectionService.sentryAuthTokenScopes,
      "Sentry required scopes should be explicit")
    try expect(
      connected.grantedScopes == ProviderConnectionService.sentryAuthTokenScopes,
      "Sentry granted scopes should be recorded")
    try expect(
      connected.callbackURL == nil,
      "Sentry token mode must not retain a Relay, Railway, or web callback URL")
    try expect(
      connected.health.diagnostics["callbackURLRequired"] == .bool(false),
      "Sentry diagnostics should state no callback URL is required")
    try expect(
      connected.health.diagnostics["relayOwnedSentryApp"] == .bool(false),
      "Sentry connection must not represent a shared Relay-owned Sentry app")
    try expect(
      connected.health.diagnostics["rawTokenStoredInDatabase"] == .bool(false),
      "Sentry diagnostics should state raw tokens are not stored in the database")
    try expect(
      connected.health.diagnostics["validation"]
        == .string(SentryTokenValidationStatus.ready.rawValue),
      "Sentry diagnostics should retain successful validation evidence")
    try expect(
      connected.health.diagnostics["httpStatusCode"] == .number(200),
      "Sentry diagnostics should retain health-check HTTP status")
    try expect(
      connected.health.diagnostics["organizationSlug"] == .string("relay-org"),
      "Sentry diagnostics should retain non-secret organization slug")
    try expect(
      connected.health.diagnostics["organizationName"] == .string("Relay Org"),
      "Sentry diagnostics should retain non-secret organization label")
    try expect(
      connected.health.diagnostics["baseURL"] == .string("https://sentry.io"),
      "Sentry diagnostics should retain normalized base URL")
    try expect(
      connected.health.diagnostics["defaultProjectSlug"] == .string("web-app"),
      "Sentry diagnostics should retain optional default project")
    try expect(
      connected.health.diagnostics["defaultEnvironment"] == .string("production"),
      "Sentry diagnostics should retain optional default environment")
    try expect(
      connected.health.diagnostics["projectCountSampled"] == .number(2),
      "Sentry diagnostics should retain bounded project sample evidence")
    try expect(
      try services.secrets.getSecretValue(connected.secretReferenceIds[0]) == rawAuthToken,
      "Sentry auth token should be retrievable only through SecretService")
    let credentialByKey = Dictionary(
      uniqueKeysWithValues: connected.credentialRequirements.map { ($0.fieldKey, $0) })
    try expect(
      credentialByKey["sentry_auth_token"]?.secretReferenceId == connected.secretReferenceIds[0],
      "Sentry token requirement should reference the Keychain secret")
    try expect(
      credentialByKey["sentry_organization_slug"]?.secretReferenceId == nil,
      "Sentry organization slug should be non-secret metadata")
    try expect(
      credentialByKey["sentry_base_url"]?.secretReferenceId == nil,
      "Sentry base URL should be non-secret metadata")
    try expect(
      credentialByKey["sentry_default_project_slug"]?.secretReferenceId == nil,
      "Sentry default project should be non-secret metadata")
    try expect(
      credentialByKey["sentry_default_environment"]?.secretReferenceId == nil,
      "Sentry default environment should be non-secret metadata")

    let snapshot = try services.providerConnections.snapshot(
      context: admin,
      appIdOrSlug: sentryApp.id,
      now: fixedDate("2026-01-01T00:00:00Z")
    )
    try expect(
      snapshot.selectedConnection?.status == .connected,
      "Sentry token snapshot should stay connected")
    try expect(
      snapshot.authorizationFlows.isEmpty,
      "Sentry auth-token mode should not create an OAuth authorization flow")
    let syncedApp = try unwrap(
      try services.data.getMarketplaceCatalogApp(
        workspaceId: workspace.id, appIdOrSlug: sentryApp.slug),
      "missing synced Sentry app"
    )
    try expect(
      syncedApp.connectionState == .connected,
      "Sentry token should sync the catalog connection state")

    let rechecked = try awaitResult {
      try await connectionService.validateSavedSentryConnection(
        context: owner,
        connectionId: connected.id,
        now: fixedDate("2026-01-01T00:00:01Z")
      )
    }
    try expect(
      rechecked.status == .connected,
      "Readable Sentry token should stay connected after explicit check")
    try expect(rechecked.health.state == .ready, "Sentry explicit check should mark health ready")
    try expect(
      rechecked.health.diagnostics["validation"]
        == .string(SentryTokenValidationStatus.ready.rawValue),
      "Sentry recheck should retain validation status")
    try expect(
      rechecked.health.diagnostics["projectCountSampled"] == .number(3),
      "Sentry recheck should retain bounded project sample evidence")
    try expect(
      !rechecked.reauthorizeRequired, "Ready Sentry health should not request reauthorization")

    var missingSecret = rechecked
    missingSecret.id = "mpc-sentry-missing-secret-001"
    missingSecret.credentialRequirements = missingSecret.credentialRequirements.map { requirement in
      var copy = requirement
      if copy.fieldKey == "sentry_auth_token" {
        copy.secretReferenceId = nil
        copy.status = .missing
      }
      return copy
    }
    missingSecret.secretReferenceIds = missingSecret.credentialRequirements.compactMap(
      \.secretReferenceId)
    _ = try services.data.saveProviderConnection(missingSecret)
    let missing = try awaitResult {
      try await connectionService.validateSavedSentryConnection(
        context: owner,
        connectionId: missingSecret.id,
        now: fixedDate("2026-01-01T00:00:02Z")
      )
    }
    let missingCredentialByKey = Dictionary(
      uniqueKeysWithValues: missing.credentialRequirements.map { ($0.fieldKey, $0) })
    try expect(
      missing.status == .authRequired, "Missing Sentry token reference should require reconnect")
    try expect(
      missing.health.diagnostics["validation"]
        == .string(SentryTokenValidationStatus.missingSecret.rawValue),
      "Missing Sentry token reference should retain validation status")
    try expect(
      missing.reauthorizeRequired, "Missing Sentry token reference should request reauthorization")
    try expect(
      missingCredentialByKey["sentry_auth_token"]?.status == .missing,
      "Missing Sentry token should mark the credential field missing")

    var unreadableSecret = rechecked
    unreadableSecret.id = "mpc-sentry-unreadable-secret-001"
    unreadableSecret.credentialRequirements = unreadableSecret.credentialRequirements.map {
      requirement in
      var copy = requirement
      if copy.fieldKey == "sentry_auth_token" {
        copy.secretReferenceId = "sec-sentry-unreadable-001"
        copy.status = .unavailable
      }
      return copy
    }
    unreadableSecret.secretReferenceIds = unreadableSecret.credentialRequirements.compactMap(
      \.secretReferenceId)
    _ = try services.data.saveProviderConnection(unreadableSecret)
    let unreadable = try awaitResult {
      try await connectionService.validateSavedSentryConnection(
        context: owner,
        connectionId: unreadableSecret.id,
        now: fixedDate("2026-01-01T00:00:03Z")
      )
    }
    let unreadableCredentialByKey = Dictionary(
      uniqueKeysWithValues: unreadable.credentialRequirements.map { ($0.fieldKey, $0) })
    try expect(
      unreadable.status == .authRequired,
      "Unreadable Sentry token reference should require reconnect")
    try expect(
      unreadable.health.diagnostics["validation"]
        == .string(SentryTokenValidationStatus.secretUnavailable.rawValue),
      "Unreadable Sentry token reference should retain validation status")
    try expect(
      unreadable.reauthorizeRequired,
      "Unreadable Sentry token reference should request reauthorization")
    try expect(
      unreadableCredentialByKey["sentry_auth_token"]?.status == .unavailable,
      "Unreadable Sentry token should mark the credential field unavailable")

    _ = try services.data.saveProviderConnection(rechecked)
    let insufficientScope = try awaitResult {
      try await connectionService.validateSavedSentryConnection(
        context: owner,
        connectionId: rechecked.id,
        now: fixedDate("2026-01-01T00:00:04Z")
      )
    }
    try expect(
      insufficientScope.status == .authRequired,
      "Sentry insufficient scopes should require reconnect")
    try expect(
      insufficientScope.health.diagnostics["validation"]
        == .string(SentryTokenValidationStatus.insufficientScope.rawValue),
      "Sentry insufficient scopes should retain validation status")
    try expect(
      insufficientScope.health.diagnostics["httpStatusCode"] == .number(403),
      "Sentry insufficient scopes should retain redacted HTTP status")
    try expect(
      insufficientScope.health.missingScopes == ["org:read", "project:read"],
      "Sentry insufficient scopes should list missing read scopes")
    try expect(
      insufficientScope.health.unavailableTools.contains("sentry_update_issue"),
      "Sentry insufficient scopes should suppress write-capable issue tools")
    try expect(
      insufficientScope.reauthorizeRequired,
      "Sentry insufficient scopes should request reauthorization")

    let reconnected = try awaitResult {
      try await connectionService.connectSentryAuthToken(
        context: owner,
        appIdOrSlug: sentryApp.slug,
        authToken: rawReconnectToken,
        organizationSlug: "relay-org-reconnected",
        baseURL: nil,
        defaultProjectSlug: nil,
        defaultEnvironment: nil,
        displayName: "Relay Sentry Reconnected",
        now: fixedDate("2026-01-01T00:00:05Z")
      )
    }
    try expect(
      reconnected.status == .connected, "Reconnected Sentry token should prove usable credentials")
    try expect(
      reconnected.health.state == .ready, "Reconnected Sentry token should have ready health")
    try expect(
      reconnected.health.diagnostics["organizationSlug"] == .string("relay-org-reconnected"),
      "Reconnected Sentry diagnostics should retain the new organization")

    let sqliteDump = try services.database.all(
      """
      SELECT connection_json AS value FROM applications_provider_connections
      UNION ALL
      SELECT snapshot_json AS value FROM applications_provider_connection_snapshots
      UNION ALL
      SELECT label AS value FROM secret_references
      """
    ).compactMap { sqliteText($0["value"]) }.joined(separator: "\n")
    try expect(!sqliteDump.contains(rawAuthToken), "raw Sentry auth token leaked into SQLite JSON")
    try expect(
      !sqliteDump.contains(rawReconnectToken),
      "raw reconnected Sentry auth token leaked into SQLite JSON")
    try expect(
      !sqliteDump.contains("relay-console://oauth/sentry/callback"),
      "Sentry auth-token mode should not persist a Relay callback URL")
    try expect(
      !sqliteDump.localizedCaseInsensitiveContains("sentry mcp tool"),
      "Sentry persistence should not expose raw MCP tools")
  }

  private static func testSentryRelayOwnedDeviceOAuthStoresAndRotatesExactScopedPair() throws {
    actor Validator: SentryTokenValidating {
      func validate(authToken: String, organizationSlug: String, baseURL: String?) async
        -> SentryTokenValidationResult
      {
        SentryTokenValidationResult(
          status: .ready, message: "Sentry OAuth verified.", httpStatusCode: 200,
          organizationSlug: organizationSlug, organizationName: "Relay Org", projectCount: 1,
          baseURL: baseURL ?? "https://sentry.io")
      }
    }
    let root = FileManager.default.temporaryDirectory.appendingPathComponent(
      "RelayConsoleSentryOAuthTests-\(UUID().uuidString)")
    let services = try makeServices(root: root)
    let workspace = try unwrap(services.data.getAppState().activeWorkspace, "missing workspace")
    let owner = Self.context(
      roles: [.owner], workspaceId: workspace.id, correlationId: "sentry-oauth-owner")
    let app = marketplaceApp(
      workspaceId: workspace.id, slug: "sentry", name: "Sentry", summary: "OAuth",
      category: "Observability", riskLevel: .high, connectionState: .none,
      installState: .notInstalled)
    _ = try services.applications.saveCatalogApps(context: owner, apps: [app])
    let connectionService = ProviderConnectionService(
      data: services.data, secrets: services.secrets, sentryValidator: Validator())
    var connection = try awaitResult {
      try await connectionService.connectSentryRelayOwnedOAuth(
        context: owner, appIdOrSlug: app.id, accessToken: "sentry_oauth_access_sensitive",
        refreshToken: "sentry_oauth_refresh_sensitive", clientId: "relay-client-id",
        organizationSlug: "relay-org", baseURL: "https://sentry.io", defaultProjectSlug: "web",
        defaultEnvironment: "production",
        grantedScopes: ProviderConnectionService.sentryAuthTokenScopes,
        expiresAt: "2026-08-10T00:00:00Z", displayName: "Relay Sentry")
    }
    let old = connection.secretReferenceIds
    try expect(
      connection.credentialOwnership == .relayOwned && !connection.userOwnedCredentialsRequired
        && old.count == 2, "Sentry OAuth ownership/pair failed")
    try expect(
      connection.grantedScopes == ProviderConnectionService.sentryAuthTokenScopes
        && connection.health.diagnostics["authMethod"]
          == .string("oauth2_device_authorization_rotating_pair"),
      "Sentry OAuth scope/method failed")
    connection = try connectionService.rotateSentryOAuthTokens(
      context: owner, connectionId: connection.id, accessToken: "sentry_next_access_sensitive",
      refreshToken: "sentry_next_refresh_sensitive", expiresAt: "2026-09-09T00:00:00Z")
    try expect(
      Set(connection.secretReferenceIds).isDisjoint(with: Set(old)),
      "Sentry OAuth pair rotation failed")
    try expect(
      old.allSatisfy { (try? services.secrets.getSecretValue($0)) == nil },
      "Sentry old OAuth refs survived")
  }

  private static func testDatadogRelayOwnedOAuthStoresAndRotatesExactScopedPair() throws {
    let root = FileManager.default.temporaryDirectory.appendingPathComponent(
      "RelayConsoleDatadogOAuthTests-\(UUID().uuidString)")
    let services = try makeServices(root: root)
    let workspace = try unwrap(services.data.getAppState().activeWorkspace, "missing workspace")
    let owner = Self.context(
      roles: [.owner], workspaceId: workspace.id, correlationId: "datadog-oauth-owner")
    let app = marketplaceApp(
      workspaceId: workspace.id, slug: "datadog", name: "Datadog", summary: "OAuth",
      category: "Observability", riskLevel: .high, connectionState: .none,
      installState: .notInstalled)
    _ = try services.applications.saveCatalogApps(context: owner, apps: [app])
    var connection = try services.providerConnections.saveDatadogRelayOwnedOAuthConnection(
      context: owner, appIdOrSlug: app.id, accessToken: "datadog_access_sensitive",
      refreshToken: "datadog_refresh_sensitive", apiOrigin: "https://api.datadoghq.eu",
      organizationName: "Relay EU", grantedScopes: ProviderConnectionService.datadogReadScopes,
      expiresAt: "2026-07-11T10:00:00Z", displayName: "Relay Datadog")
    let old = connection.secretReferenceIds
    try expect(
      connection.credentialOwnership == .relayOwned && !connection.userOwnedCredentialsRequired
        && old.count == 2, "Datadog OAuth ownership/pair failed")
    try expect(
      connection.grantedScopes == ProviderConnectionService.datadogReadScopes
        && connection.health.diagnostics["apiOrigin"] == .string("https://api.datadoghq.eu"),
      "Datadog exact scopes/site failed")
    try expect(
      connection.health.diagnostics["clientSecretLocation"]
        == .string("secure-railway-broker-only"), "Datadog client secret must remain broker-only")
    connection = try services.providerConnections.rotateDatadogOAuthTokens(
      context: owner, connectionId: connection.id, accessToken: "datadog_next_access_sensitive",
      refreshToken: "datadog_next_refresh_sensitive", expiresAt: "2026-07-11T11:00:00Z")
    try expect(
      Set(connection.secretReferenceIds).isDisjoint(with: Set(old)),
      "Datadog complete pair rotation failed")
    try expect(
      old.allSatisfy { (try? services.secrets.getSecretValue($0)) == nil },
      "Datadog old OAuth refs survived rotation")
    var rejectedArbitraryHost = false
    do {
      _ = try services.providerConnections.saveDatadogRelayOwnedOAuthConnection(
        context: owner, appIdOrSlug: app.id, accessToken: "a", refreshToken: "r",
        apiOrigin: "https://tenant.datadoghq.com", organizationName: nil,
        grantedScopes: ProviderConnectionService.datadogReadScopes, expiresAt: nil)
    } catch { rejectedArbitraryHost = true }
    try expect(rejectedArbitraryHost, "Datadog must reject arbitrary callback subdomains")
  }

  private static func testDatadogProviderFoundationEnforcesBoundedObservabilityPolicy() throws {
    let services = try makeServices()
    let workspace = try unwrap(services.data.getAppState().activeWorkspace, "missing workspace")
    let owner = Self.context(
      roles: [.owner], workspaceId: workspace.id, correlationId: "datadog-foundation-owner")
    let snapshot = try services.providerFoundations.registerDatadogFoundation(
      context: owner, now: fixedDate("2026-07-11T00:00:00Z"))
    try expect(
      snapshot.appSlug == "datadog" && snapshot.providerFamily == "observability",
      "Datadog foundation identity failed")
    try expect(
      snapshot.connectionMode == "relay-owned-datadog-oauth-pkce-confidential-hosted"
        && snapshot.credentialOwnership == .relayOwned, "Datadog hosted OAuth contract failed")
    try expect(
      snapshot.supportedPolicyPresets == [.readOnly, .blocked]
        && snapshot.defaultPolicyPreset == .readOnly, "Datadog must remain read-only")
    try expect(
      Set(snapshot.actions.map(\.actionKey))
        == Set(["datadog_list_services", "datadog_search_incidents", "datadog_search_monitors"])
        && snapshot.agentFacingWrapperToolNames.count == 3, "Datadog exact wrapper set failed")
    try expect(
      Set(snapshot.actions.flatMap(\.requiredScopes))
        == Set(ProviderConnectionService.datadogReadScopes), "Datadog exact action scopes failed")
    try expect(
      snapshot.credentials.map(\.fieldKey) == [
        "datadog_oauth_access_token", "datadog_oauth_refresh_token", "datadog_api_origin",
      ], "Datadog credential semantic contract failed")
    try expect(
      snapshot.budgetPolicy["maxWrapperTools"] == .number(3)
        && snapshot.budgetPolicy["maxListResults"] == .number(25), "Datadog bounds failed")
    try expect(
      snapshot.privacyPolicy["logsTracesEventsMetricsExport"] == .string("blocked")
        && !snapshot.rawProviderToolExposure, "Datadog privacy boundary failed")
    try expect(
      DatadogProviderActionSupport.fakeMonitor()["name"] == .string("API latency high")
        && DatadogProviderActionSupport.fakeIncident()["title"]
          == .string("Checkout latency regression")
        && DatadogProviderActionSupport.fakeService()["owner"] == .string("Commerce Platform"),
