      installState: .notInstalled)
    _ = try services.applications.saveCatalogApps(context: owner, apps: [app])
    do {
      _ = try services.providerConnections.saveGoogleCalendarRelayOwnedOAuthConnection(
        context: owner, appIdOrSlug: app.id, accessToken: "bad", refreshToken: "bad",
        accountEmail: "relay.calendar@example.com", defaultCalendarId: "primary",
        grantedScopes: ProviderConnectionService.googleCalendarRelayOwnedOAuthScopes + [
          "https://www.googleapis.com/auth/calendar.events.readonly"
        ], expiresAt: nil)
      throw ServiceTestFailure("Redundant Google Calendar readonly scope accepted")
    } catch is ServiceTestFailure {
      throw ServiceTestFailure("Redundant Google Calendar readonly scope accepted")
    } catch {}
    let connection = try services.providerConnections.saveGoogleCalendarRelayOwnedOAuthConnection(
      context: owner, appIdOrSlug: app.id, accessToken: "calendar-access-sensitive",
      refreshToken: "calendar-refresh-sensitive", accountEmail: "relay.calendar@example.com",
      defaultCalendarId: "primary",
      grantedScopes: ProviderConnectionService.googleCalendarRelayOwnedOAuthScopes,
      expiresAt: "2026-07-12T01:00:00Z")
    let initialRefresh = try unwrap(
      connection.credentialRequirements.first(where: {
        $0.fieldKey == "google_calendar_oauth_refresh_token"
      })?.secretReferenceId, "missing initial refresh reference")
    let retainedRefresh = try services.providerConnections
      .rotateGoogleCalendarRelayOwnedOAuthTokens(
        context: owner, connectionId: connection.id, accessToken: "calendar-access-next-sensitive",
        refreshToken: nil, expiresAt: "2026-07-12T02:00:00Z")
    try expect(
      retainedRefresh.credentialRequirements.first(where: {
        $0.fieldKey == "google_calendar_oauth_refresh_token"
      })?.secretReferenceId == initialRefresh,
      "Google Calendar rotation should preserve an omitted refresh token")
    let replaced = try services.providerConnections.rotateGoogleCalendarRelayOwnedOAuthTokens(
      context: owner, connectionId: connection.id, accessToken: "calendar-access-final-sensitive",
      refreshToken: "calendar-refresh-final-sensitive", expiresAt: "2026-07-12T03:00:00Z")
    try expect(
      connection.credentialOwnership == .relayOwned && !connection.userOwnedCredentialsRequired
        && Set(connection.secretReferenceIds).count == 2,
      "Google Calendar tokens should use two Relay-owned Keychain references")
    try expect(
      replaced.grantedScopes == ProviderConnectionService.googleCalendarRelayOwnedOAuthScopes
        && replaced.health.diagnostics["clientSecretLocation"]
          == .string("secure-railway-broker-only")
        && replaced.health.diagnostics["automaticPagination"] == .bool(false),
      "Google Calendar exact-scope broker evidence failed")
    try expect(
      replaced.credentialRequirements.first(where: {
        $0.fieldKey == "google_calendar_oauth_refresh_token"
      })?.secretReferenceId != initialRefresh,
      "Provider-returned Google Calendar refresh token should replace the old reference")
    let retained = try services.database.all(
      "SELECT connection_json AS value FROM applications_provider_connections"
    ).compactMap { sqliteText($0["value"]) }.joined()
    for secret in [
      "calendar-access-sensitive", "calendar-refresh-sensitive", "calendar-access-next-sensitive",
      "calendar-access-final-sensitive", "calendar-refresh-final-sensitive",
    ] {
      try expect(!retained.contains(secret), "Google Calendar token leaked into SQLite")
    }
  }

