  private static func testSentryProviderFoundationEnforcesObservabilityPolicy() throws {
    let services = try makeServices()
    let workspace = try unwrap(services.data.getAppState().activeWorkspace, "missing workspace")
    let owner = Self.context(
      roles: [.owner], workspaceId: workspace.id, correlationId: "sentry-foundation-owner-001")
    let member = Self.context(
      roles: [.member], workspaceId: workspace.id, correlationId: "sentry-foundation-member-001")

    do {
      _ = try services.providerFoundations.registerSentryFoundation(
        context: member,
        now: fixedDate("2026-01-01T00:00:00Z")
      )
      throw ServiceTestFailure("member unexpectedly registered Sentry provider foundation")
    } catch let denied as ServiceGuardResult {
      try expect(
        denied.reasonCode == .authorityRoleRequired,
        "Sentry foundation registration should require owner/admin authority")
    }

    let snapshot = try services.providerFoundations.registerSentryFoundation(
      context: owner,
      now: fixedDate("2026-01-01T00:00:01Z")
    )
    try expect(snapshot.appSlug == "sentry", "Sentry foundation should target Sentry")
    try expect(
      snapshot.providerName == "Sentry",
      "Sentry foundation should retain the canonical provider name")
    try expect(
      snapshot.providerFamily == "observability",
      "Sentry foundation should mark the provider as observability")
    try expect(
      snapshot.connectionMode == "relay-owned-sentry-device-oauth",
      "Sentry foundation should use device OAuth")
    try expect(
      snapshot.credentialOwnership == .relayOwned, "Sentry foundation should use Relay-owned OAuth")
    try expect(
      !snapshot.userOwnedCredentialsRequired,
      "Sentry foundation should not require user token entry")
    try expect(
      snapshot.supportedPolicyPresets == [
        .approvalRequired, .allowDirectWrites, .readOnly, .blocked,
      ], "Sentry foundation should advertise all four authority presets")
    try expect(
      snapshot.defaultPolicyPreset == .approvalRequired,
      "Sentry foundation should default to approval-required policy")
    try expect(
      snapshot.adapterBoundary == "brokered-native-sentry-rest-api-adapter",
      "Sentry foundation should keep REST API access behind the broker boundary")
    try expect(
      snapshot.actionMapVersion == "sentry-v1",
      "Sentry foundation should identify the V1 action map")
    try expect(
      !snapshot.rawProviderToolExposure,
      "Sentry foundation should not expose raw provider or MCP tools")
    try expect(
      snapshot.suppressedRawProviderToolCount == 13,
      "Sentry foundation should count safe and blocked V1 provider actions as suppressed raw tools")

    let app = try unwrap(
      try services.data.getMarketplaceCatalogApp(
        workspaceId: workspace.id, appIdOrSlug: snapshot.appId),
      "missing Sentry app"
    )
    try expect(app.slug == "sentry", "Sentry catalog app should retain the intended slug")
    try expect(
      app.websiteURL == "https://sentry.io/",
      "Sentry catalog app should retain the official website")
    try expect(
      app.docsURL == "https://docs.sentry.io/api/",
      "Sentry catalog app should retain official developer docs")
    try expect(!app.readOnly, "Sentry catalog app should remain write-capable for V1 issue updates")
    try expect(
      app.roleManifest.approvalRequired, "Sentry catalog app should require approvals by default")
    try expect(
      app.roleManifest.roleDefinitions?.contains {
        $0.canWrite && $0.approvalRequiredActions.contains("sentry_issue_update")
      } == true, "Sentry role manifest should gate issue updates")
    try expect(
      app.roleManifest.roleDefinitions?.contains {
        $0.blockedActions.contains("sentry_raw_mcp")
          && $0.blockedActions.contains("sentry_artifact_admin")
      } == true, "Sentry role manifest should block raw MCP and artifact administration")

    try expect(
      snapshot.credentials.map(\.fieldKey) == [
        "sentry_oauth_access_token",
        "sentry_oauth_refresh_token",
        "sentry_organization_slug",
        "sentry_base_url",
        "sentry_default_project_slug",
        "sentry_default_environment",
      ],
      "Sentry foundation should list OAuth pair and bounded routing metadata"
    )
    let credentialByKey = Dictionary(
      uniqueKeysWithValues: snapshot.credentials.map { ($0.fieldKey, $0) })
    try expect(
      credentialByKey["sentry_oauth_access_token"]?.required == true,
      "Sentry OAuth access should be required")
    try expect(
      credentialByKey["sentry_oauth_refresh_token"]?.secretStorage == "keychain-reference-only",
      "Sentry OAuth refresh should be Keychain-reference only")
    try expect(
      credentialByKey["sentry_organization_slug"]?.required == true,
      "Sentry organization slug should be required")
    try expect(
      credentialByKey["sentry_organization_slug"]?.secretStorage == "metadata-only",
      "Sentry organization slug should be non-secret metadata")
    try expect(
      snapshot.credentials.allSatisfy {
        $0.secretStorage == "keychain-reference-only" || $0.secretStorage == "metadata-only"
      }, "Sentry credentials should be secret references or metadata only")

    try expect(
      snapshot.budgetPolicy["maxWrapperTools"] == .number(6),
      "Sentry foundation should budget six wrapper tools")
    try expect(
      snapshot.budgetPolicy["promptSummaryMaxCharacters"] == .number(1200),
      "Sentry prompt summary budget should be retained")
    try expect(
      snapshot.budgetPolicy["maxIssueResults"] == .number(10),
      "Sentry issue search should be bounded")
    try expect(
      snapshot.budgetPolicy["maxEventContextChars"] == .number(6000),
      "Sentry event context should be bounded")
    try expect(
      snapshot.privacyPolicy["semanticReads"]
        == .string("project_issue_event_bounded_debug_context"),
      "Sentry semantic reads should retain the V1 contract")
    try expect(
      snapshot.privacyPolicy["writes"] == .string("approval_required_or_direct_write_by_policy"),
      "Sentry issue updates should default to approval while allowing explicit Direct writes")
    try expect(
      snapshot.privacyPolicy["attachments"] == .string("blocked"),
      "Sentry attachments should be blocked")
    try expect(
      snapshot.privacyPolicy["sourceMapsAndReleaseFiles"] == .string("blocked"),
      "Sentry source map and release file uploads should be blocked")
    try expect(
      snapshot.privacyPolicy["adminOperations"] == .string("blocked"),
      "Sentry admin operations should be blocked")
    try expect(
      snapshot.privacyPolicy["bulkMutations"] == .string("blocked"),
      "Sentry bulk mutations should be blocked")
    try expect(
      snapshot.privacyPolicy["rawMCPExposure"] == .string("blocked"),
      "Sentry raw MCP exposure should be blocked")
    try expect(
      snapshot.privacyPolicy["seerAI"] == .string("blocked"),
      "Sentry Seer/AI actions should be blocked")
    try expect(
      snapshot.privacyPolicy["relayOwnedSentryApp"] == .string("approved-device-oauth"),
      "Relay-owned Sentry device OAuth should be explicit")
    try expect(
      snapshot.privacyPolicy["rawCredentials"] == .string("secret-reference-only"),
      "Sentry raw credentials should stay behind secret references")

    let expectedSafeActions: Set<String> = [
      "sentry_list_projects",
      "sentry_search_issues",
      "sentry_get_issue",
      "sentry_get_event",
      "sentry_prepare_issue_update",
      "sentry_update_issue",
    ]
    let expectedBlockedActions: Set<String> = [
      "sentry_broad_export",
      "sentry_attachment_download",
      "sentry_source_map_upload",
      "sentry_admin_operation",
      "sentry_bulk_mutate",
      "sentry_raw_mcp_call",
      "sentry_seer_ai",
    ]
    let actionByKey = Dictionary(uniqueKeysWithValues: snapshot.actions.map { ($0.actionKey, $0) })
    try expect(
      Set(actionByKey.keys) == expectedSafeActions.union(expectedBlockedActions),
      "Sentry foundation should register the complete V1 safe and blocked action map")
    try expect(
      actionByKey["sentry_list_projects"]?.policyPermission == .allowed,
      "Sentry project list should be allowed")
    try expect(
      actionByKey["sentry_search_issues"]?.policyPermission == .allowed,
      "Sentry issue search should be allowed")
    try expect(
      actionByKey["sentry_get_issue"]?.policyPermission == .allowed,
      "Sentry issue detail should be allowed")
    try expect(
      actionByKey["sentry_get_event"]?.policyPermission == .allowed,
      "Sentry event detail should be allowed by the default policy")
    try expect(
      actionByKey["sentry_prepare_issue_update"]?.policyPermission == .allowed,
      "Sentry prepare issue update should be allowed")
    try expect(
      actionByKey["sentry_update_issue"]?.policyPermission == .approvalRequired,
      "Sentry issue update should require approval by default")
    try expect(
      actionByKey["sentry_update_issue"]?.requiredScopes
        == ProviderConnectionService.sentryAuthTokenScopes,
      "Sentry issue update should require the full V1 scope set")
    for actionKey in expectedBlockedActions {
      try expect(
        actionByKey[actionKey]?.policyPermission == .blocked,
        "Sentry blocked action \(actionKey) should stay blocked")
      try expect(
        actionByKey[actionKey]?.wrapperToolName == nil,
        "Sentry blocked action \(actionKey) should not have an agent-facing wrapper")
    }
    try expect(
      snapshot.blockedActionKeys == [
        "sentry_admin_operation",
        "sentry_attachment_download",
        "sentry_broad_export",
        "sentry_bulk_mutate",
        "sentry_raw_mcp_call",
        "sentry_seer_ai",
        "sentry_source_map_upload",
      ],
      "Sentry foundation should expose all blocked/deferred V1 actions"
    )
    try expect(
      snapshot.agentFacingWrapperToolNames.count == 6,
      "Sentry foundation should expose six safe wrapper names")
    try expect(
      snapshot.agentFacingWrapperToolNames.allSatisfy { $0.hasPrefix("relay_provider_sentry_") },
      "Sentry wrapper names should use Relay provider namespace")
    let wrapperNames = snapshot.agentFacingWrapperToolNames.joined(separator: "\n").lowercased()
    for leaked in [
      "sentry_broad_export",
      "sentry_attachment_download",
      "sentry_source_map_upload",
      "sentry_admin_operation",
      "sentry_bulk_mutate",
      "sentry_raw_mcp_call",
      "sentry_seer_ai",
      "raw_mcp",
      "auth_token",
      "bearer",
    ] {
      try expect(
        !wrapperNames.contains(leaked),
        "Sentry wrapper names leaked blocked or credential term \(leaked)")
    }

    let directPolicy = try services.providerActionPolicies.compilePolicyMap(
      context: owner,
      appIdOrSlug: snapshot.appId,
      preset: .allowDirectWrites, acknowledgeDangerousPolicy: true,
      now: fixedDate("2026-01-01T00:00:02Z")
    )
    try expect(
      directPolicy.permissions["sentry_list_projects"] == .allowed,
      "direct-write Sentry policy should keep project reads allowed")
    try expect(
      directPolicy.permissions["sentry_search_issues"] == .allowed,
      "direct-write Sentry policy should keep issue search allowed")
    try expect(
      directPolicy.permissions["sentry_get_issue"] == .allowed,
      "direct-write Sentry policy should keep issue reads allowed")
    try expect(
      directPolicy.permissions["sentry_get_event"] == .allowed,
      "direct-write Sentry policy should keep event reads allowed")
    try expect(
      directPolicy.permissions["sentry_prepare_issue_update"] == .allowed,
      "direct-write Sentry policy should keep local preparation allowed")
    try expect(
      directPolicy.permissions["sentry_update_issue"] == .autoExecute,
      "direct-write Sentry policy should auto-execute bounded issue updates")
    try expect(
      directPolicy.permissions["sentry_source_map_upload"] == .blocked,
      "direct-write Sentry policy should keep source map uploads blocked")
    try expect(
      directPolicy.permissions["sentry_admin_operation"] == .blocked,
      "direct-write Sentry policy should keep admin operations blocked")
    try expect(
      directPolicy.permissions["sentry_raw_mcp_call"] == .blocked,
      "direct-write Sentry policy should keep raw MCP blocked")

    let readOnly = try services.providerActionPolicies.compilePolicyMap(
      context: owner,
      appIdOrSlug: snapshot.appId,
      preset: .readOnly,
      now: fixedDate("2026-01-01T00:00:03Z")
    )
    try expect(
      readOnly.permissions["sentry_list_projects"] == .allowed,
      "read-only Sentry policy should allow project reads")
    try expect(
      readOnly.permissions["sentry_search_issues"] == .allowed,
      "read-only Sentry policy should allow issue search")
    try expect(
      readOnly.permissions["sentry_get_issue"] == .allowed,
      "read-only Sentry policy should allow issue reads")
    try expect(
      readOnly.permissions["sentry_get_event"] == .approvalRequired,
      "read-only Sentry policy should keep high-risk event context approval-gated")
    try expect(
      readOnly.permissions["sentry_prepare_issue_update"] == .allowed,
      "read-only Sentry policy should allow local preparation")
    try expect(
      readOnly.permissions["sentry_update_issue"] == .blocked,
      "read-only Sentry policy should block issue updates")
    try expect(
      readOnly.permissions["sentry_broad_export"] == .blocked,
      "read-only Sentry policy should block broad export")
    try expect(
      readOnly.permissions["sentry_attachment_download"] == .blocked,
      "read-only Sentry policy should block attachments")

    let blocked = try services.providerActionPolicies.compilePolicyMap(
      context: owner,
      appIdOrSlug: snapshot.appId,
      preset: .blocked,
      now: fixedDate("2026-01-01T00:00:04Z")
    )
    try expect(
      blocked.permissions.values.allSatisfy { $0 == .blocked },
      "blocked Sentry policy should block every action")

    let durableMap = try unwrap(
      try services.data.getMarketplaceActionPermissionMap(
        workspaceId: workspace.id, mapId: snapshot.defaultPermissionMapId),
      "missing durable Sentry default policy map"
    )
    try expect(
      durableMap.policyPreset == .blocked,
      "Sentry policy switching should update the scoped durable map")
    try expect(
      try services.data.listMarketplaceProviderActionDefinitions(
        workspaceId: workspace.id, appId: snapshot.appId
      ).count == 13, "Sentry foundation should persist all V1 provider action definitions")

    let encoded = String(data: try JSONEncoder().encode(snapshot), encoding: .utf8) ?? ""
    try expect(
      !encoded.contains("sentry_foundation_auth_token_secret"),
      "Sentry foundation snapshot should not contain auth token values")
    try expect(
      !encoded.localizedCaseInsensitiveContains("bearer "),
      "Sentry foundation snapshot should not contain bearer credentials")
    try expect(
      !encoded.localizedCaseInsensitiveContains("raw sentry mcp"),
      "Sentry foundation snapshot should not expose raw MCP tool dumps")
    try expect(
      encoded.contains("secret-reference-only"),
      "Sentry foundation snapshot should retain credential redaction evidence")
  }

  private static func testSentryProviderActionAdapterRoutesBrokeredSafeActions() throws {
    let services = try makeServices()
    let workspace = try unwrap(services.data.getAppState().activeWorkspace, "missing workspace")
    let owner = Self.context(
      roles: [.owner], workspaceId: workspace.id, correlationId: "sentry-adapter-owner-001")

    let snapshot = try services.providerFoundations.registerSentryFoundation(
      context: owner,
      now: fixedDate("2026-01-01T00:00:00Z")
    )
    let app = try unwrap(
      try services.data.getMarketplaceCatalogApp(
        workspaceId: workspace.id, appIdOrSlug: snapshot.appId),
      "missing Sentry app"
    )
    let broker = MarketplaceProviderActionBrokerService(
      data: services.data,
      approvals: services.providerActionApprovals,
      auditSecurity: services.auditSecurity,
      adapter: RoutingMarketplaceProviderActionAdapter(
        sentryAdapter: SentryProviderActionAdapter()
      )
    )
    struct StubSentryProviderHTTPClient: SentryProviderHTTPClient {
      let expectedToken: String

      func send(_ request: SentryProviderHTTPRequest) throws -> SentryProviderHTTPResponse {
        guard request.headers["Authorization"] == "Bearer \(expectedToken)" else {
          return SentryProviderHTTPResponse(
            statusCode: 401, body: Data(#"{"detail":"missing token"}"#.utf8))
        }
        guard request.method == "GET",
          request.url.path.contains("/api/0/organizations/"),
          request.url.path.contains("/issues/") || request.url.path.hasSuffix("/issues")
        else {
          return SentryProviderHTTPResponse(
            statusCode: 404, body: Data(#"{"detail":"unexpected Sentry request"}"#.utf8))
        }
        return SentryProviderHTTPResponse(
          statusCode: 200,
          body: Data(
            #"""
            [
              {
                "id": "SENTRY-LIVE-1",
                "shortId": "WEB-1",
                "title": "Live fixture issue",
                "culprit": "CheckoutView.render",
                "permalink": "https://sentry.io/organizations/relay-org/issues/SENTRY-LIVE-1/",
                "project": { "slug": "web-app" },
                "status": "unresolved",
                "substatus": "ongoing",
                "priority": "high",
                "level": "error",
                "count": "7",
                "userCount": 3,
                "firstSeen": "2026-01-01T00:00:00Z",
                "lastSeen": "2026-01-01T00:02:00Z"
            }
            ]
            """#.utf8
          )
        )
      }
    }

    let search = try broker.execute(
      context: owner,
      request: MarketplaceProviderActionBrokerRequest(
        appIdOrSlug: app.id,
        actionKey: "sentry_search_issues",
        payload: [
          "projectSlug": .string("web-app"),
          "environment": .string("production"),
          "query": .string("is:unresolved"),
          "limit": .number(5),
        ],
        connectionId: nil,
        installId: nil,
        agentId: nil,
        idempotencyKey: "sentry-adapter-search-001",
        dispatchId: "rtd-sentry-adapter-search-001"
      ),
      now: fixedDate("2026-01-01T00:00:01Z")
    )
    try expect(
      search.adapterExecuted, "Sentry issue search should execute through the routed adapter")
    try expect(
      search.execution.status == .succeeded,
      "Sentry issue search should persist a succeeded execution")
    let searchResult = try unwrap(
      search.execution.providerResult, "missing Sentry search provider result")
    try expect(
      searchResult["provider"] == .string("sentry"),
      "Sentry search result should identify the provider")
    try expect(
      searchResult["fakeAdapter"] == .bool(true),
      "Sentry fake adapter should mark deterministic fake execution")
    try expect(
      searchResult["semanticReadContract"] == .string("sentry-issue-search-v1"),
      "Sentry search should return semantic read contract evidence")
    try expect(
      searchResult["rawProviderToolExposure"] == .bool(false),
      "Sentry search should not expose raw provider tools")
    if case .array(let issues)? = searchResult["issues"] {
      try expect(!issues.isEmpty, "Sentry fake search should return a semantic issue fixture")
      if case .object(let issue)? = issues.first {
        try expect(
          issue["title"]?.string?.isEmpty == false, "Sentry fake issue should include a title")
        try expect(
          issue["permalink"]?.string?.contains("sentry.io") == true,
          "Sentry fake issue should include a provider permalink")
      }
    } else {
      throw ServiceTestFailure("Sentry search result did not return issues")
    }

    let pendingUpdate = try broker.execute(
      context: owner,
      request: MarketplaceProviderActionBrokerRequest(
        appIdOrSlug: app.id,
        actionKey: "sentry_update_issue",
        payload: [
          "issueId": .string("SENTRY-123"),
          "status": .string("resolved"),
        ],
        connectionId: nil,
        installId: nil,
        agentId: nil,
        idempotencyKey: "sentry-adapter-update-standard-001",
        dispatchId: "rtd-sentry-adapter-update-standard-001"
      ),
      now: fixedDate("2026-01-01T00:00:02Z")
    )
    try expect(
      !pendingUpdate.adapterExecuted,
      "Default Sentry issue update should not execute before approval")
    try expect(
      pendingUpdate.execution.status == .pendingApproval,
      "Default Sentry issue update should create a pending approval execution")
    try expect(
      pendingUpdate.approval?.status == .pending,
      "Default Sentry issue update should create a pending approval record")

    _ = try services.providerActionPolicies.compilePolicyMap(
      context: owner,
      appIdOrSlug: app.id,
      preset: .allowDirectWrites, acknowledgeDangerousPolicy: true,
      now: fixedDate("2026-01-01T00:00:03Z")
    )
    let directUpdate = try broker.execute(
      context: owner,
      request: MarketplaceProviderActionBrokerRequest(
        appIdOrSlug: app.id,
        actionKey: "sentry_update_issue",
        payload: [
          "issueId": .string("SENTRY-123"),
          "status": .string("resolved"),
          "isBookmarked": .bool(true),
        ],
        connectionId: nil,
        installId: nil,
        agentId: nil,
        idempotencyKey: "sentry-adapter-update-direct-001",
        dispatchId: "rtd-sentry-adapter-update-direct-001"
      ),
      now: fixedDate("2026-01-01T00:00:04Z")
    )
    try expect(
      directUpdate.adapterExecuted, "Direct Sentry issue update should execute through the adapter")
    try expect(
      directUpdate.execution.status == .succeeded,
      "Direct Sentry issue update should persist a succeeded execution")
    try expect(
      directUpdate.execution.permission == .autoExecute,
      "Direct Sentry issue update should use auto-execute permission")
    let directResult = try unwrap(
      directUpdate.execution.providerResult, "missing Sentry direct update provider result")
    try expect(
      directResult["issueId"] == .string("SENTRY-123"),
      "Sentry direct update should return the issue id")
    try expect(
      directResult["payloadHash"]?.string?.isEmpty == false,
      "Sentry direct update should return an exact payload hash")
    try expect(
      directResult["rawProviderToolExposure"] == .bool(false),
      "Sentry direct update should not expose raw provider tools")

    let blockedUpdate = try broker.execute(
      context: owner,
      request: MarketplaceProviderActionBrokerRequest(
        appIdOrSlug: app.id,
        actionKey: "sentry_update_issue",
        payload: [
          "issueId": .string("SENTRY-123"),
          "status": .string("resolved"),
          "isPublic": .bool(true),
        ],
        connectionId: nil,
        installId: nil,
        agentId: nil,
        idempotencyKey: "sentry-adapter-update-blocked-field-001",
        dispatchId: "rtd-sentry-adapter-update-blocked-field-001"
      ),
      now: fixedDate("2026-01-01T00:00:05Z")
    )
    try expect(
      blockedUpdate.adapterExecuted,
      "Sentry blocked update field should reach the adapter and fail there")
    try expect(
      blockedUpdate.execution.status == .failed,
      "Sentry blocked update field should persist a failed execution")
    try expect(
      blockedUpdate.execution.providerError?["providerErrorCode"]
        == .string("sentry_update_field_blocked"),
      "Sentry blocked update field should retain redacted provider error code")

    let rawMCP = try broker.execute(
      context: owner,
      request: MarketplaceProviderActionBrokerRequest(
        appIdOrSlug: app.id,
        actionKey: "sentry_raw_mcp_call",
        payload: ["toolName": .string("raw-sentry-mcp-tool")],
        connectionId: nil,
        installId: nil,
        agentId: nil,
        idempotencyKey: "sentry-adapter-raw-mcp-001",
        dispatchId: "rtd-sentry-adapter-raw-mcp-001"
      ),
      now: fixedDate("2026-01-01T00:00:06Z")
    )
    try expect(
      !rawMCP.adapterExecuted, "Sentry raw MCP action should be blocked before adapter execution")
    try expect(
      rawMCP.execution.status == .blocked,
      "Sentry raw MCP action should persist a blocked execution")
    try expect(
      rawMCP.execution.providerResult == nil,
      "Sentry raw MCP action should not return provider results")

    let liveToken = "sentry-live-adapter-sensitive-token"
    let liveConnection = try services.providerConnections.saveSentryAuthToken(
      context: owner,
      appIdOrSlug: app.id,
      authToken: liveToken,
      organizationSlug: "relay-org",
      baseURL: "https://sentry.io",
      defaultProjectSlug: "web-app",
      defaultEnvironment: "production",
      displayName: "Relay Sentry Live",
      validationResult: SentryTokenValidationResult(
        status: .ready,
        message: "Sentry auth token verified with a bounded organization projects request.",
        httpStatusCode: 200,
        organizationSlug: "relay-org",
        organizationName: "Relay Org",
        projectCount: 1,
        baseURL: "https://sentry.io"
      ),
      now: fixedDate("2026-01-01T00:00:07Z")
    )
    let liveBroker = MarketplaceProviderActionBrokerService(
      data: services.data,
      approvals: services.providerActionApprovals,
      auditSecurity: services.auditSecurity,
      adapter: RoutingMarketplaceProviderActionAdapter(
        sentryAdapter: SentryProviderActionAdapter(
          client: LiveSentryProviderActionClient(
            data: services.data,
            secrets: services.secrets,
            httpClient: StubSentryProviderHTTPClient(expectedToken: liveToken)
          )
        )
      )
    )
    let liveSearch = try liveBroker.execute(
      context: owner,
      request: MarketplaceProviderActionBrokerRequest(
        appIdOrSlug: app.id,
        actionKey: "sentry_search_issues",
        payload: [
          "limit": .number(1),
          "query": .string("is:unresolved"),
        ],
        connectionId: liveConnection.id,
        installId: nil,
        agentId: nil,
        idempotencyKey: "sentry-adapter-live-search-001",
        dispatchId: "rtd-sentry-adapter-live-search-001"
      ),
      now: fixedDate("2026-01-01T00:00:08Z")
    )
    try expect(
      liveSearch.adapterExecuted,
      "Live Sentry issue search should execute through the routed adapter")
    try expect(
      liveSearch.execution.status == .succeeded,
      "Live Sentry issue search should persist a succeeded execution; status=\(liveSearch.execution.status.rawValue) error=\(String(describing: liveSearch.execution.providerError))"
    )
    let liveResult = try unwrap(
      liveSearch.execution.providerResult, "missing live Sentry search provider result")
    try expect(
      liveResult["clientMode"] == .string("live-sentry-rest-api"),
      "Live Sentry search should identify the live REST client")
    try expect(
      liveResult["fakeAdapter"] == .bool(false), "Live Sentry search should not be marked as fake")
    try expect(
      liveResult["liveCredentialsUsed"] == .bool(true),
      "Live Sentry search should prove credential-gated execution")
    try expect(
      liveResult["rawProviderToolExposure"] == .bool(false),
      "Live Sentry search should not expose raw provider tools")
    if case .array(let issues)? = liveResult["issues"],
      case .object(let issue)? = issues.first
    {
      try expect(
        issue["id"] == .string("SENTRY-LIVE-1"),
        "Live Sentry search should return normalized issue evidence")
      try expect(
        issue["projectSlug"] == .string("web-app"),
        "Live Sentry search should retain the project slug")
    } else {
      throw ServiceTestFailure("Live Sentry search result did not return issues")
    }

    let executionDump = try services.data
      .listMarketplaceProviderActionExecutions(workspaceId: workspace.id)
      .flatMap { [$0.providerResult, $0.providerError].compactMap { $0 } }
      .map { String(data: try JSONEncoder().encode($0), encoding: .utf8) ?? "" }
      .joined(separator: "\n")
    try expect(
      !executionDump.localizedCaseInsensitiveContains("bearer "),
      "Sentry broker execution should not persist bearer tokens")
    try expect(
      !executionDump.localizedCaseInsensitiveContains("auth token"),
      "Sentry broker execution should not persist raw auth token text")
    try expect(
      !executionDump.contains(liveToken),
      "Sentry broker execution should not persist live auth token values")
    try expect(
      !executionDump.localizedCaseInsensitiveContains("raw-sentry-mcp-tool"),
      "Sentry broker execution should not persist raw MCP tool payloads as provider results")
  }

  private static func testFacebookPagesProviderFoundationContract() throws {
    let services = try makeServices()
    let workspace = try unwrap(services.data.getAppState().activeWorkspace, "missing workspace")
    let owner = Self.context(
      roles: [.owner], workspaceId: workspace.id,
      correlationId: "facebook-pages-foundation-owner")
    let foundation = try services.providerFoundations.registerFacebookPagesFoundation(
      context: owner, now: fixedDate("2026-07-12T11:30:00Z"))
    let exactActions: Set<String> = [
      "facebook_pages_page_get", "facebook_pages_own_posts_list",
      "facebook_pages_post_draft", "facebook_pages_text_post_create",
    ]
    try expect(
      foundation.appSlug == "facebook-pages"
        && foundation.connectionMode == "relay-owned-meta-selected-page-oauth"
        && foundation.credentialOwnership == .relayOwned
        && !foundation.userOwnedCredentialsRequired,
      "Facebook Pages foundation must retain Relay-owned selected-Page OAuth")
    try expect(
      Set(foundation.actions.map(\.actionKey)) == exactActions
        && foundation.actions.count == 4,
      "Facebook Pages foundation must register exactly four contracted actions")
    try expect(
      Set(foundation.credentials.map(\.fieldKey)) == [
        "facebook_pages_user_access_token", "facebook_pages_page_access_token",
        "facebook_pages_selected_page",
      ],
      "Facebook Pages foundation must expose two secret references and one Page binding")
    let catalog = try services.applications.catalogSnapshot(
      context: owner, selectedAppId: "facebook-pages")
    let app = try unwrap(
      catalog.apps.first { $0.slug == "facebook-pages" }, "missing Facebook Pages app")
    let standard = try services.providerActionPolicies.compilePolicyMap(
      context: owner, appIdOrSlug: app.id, preset: .approvalRequired)
    let direct = try services.providerActionPolicies.compilePolicyMap(
      context: owner, appIdOrSlug: app.id, preset: .allowDirectWrites, acknowledgeDangerousPolicy: true)
    let readOnly = try services.providerActionPolicies.compilePolicyMap(
      context: owner, appIdOrSlug: app.id, preset: .readOnly)
    let blocked = try services.providerActionPolicies.compilePolicyMap(
      context: owner, appIdOrSlug: app.id, preset: .blocked)
    for key in ["facebook_pages_page_get", "facebook_pages_own_posts_list", "facebook_pages_post_draft"] {
      try expect(
        standard.permissions[key] == .allowed && direct.permissions[key] == .allowed
          && readOnly.permissions[key] == .allowed,
        "Facebook Pages reads and local draft must remain allowed outside No access")
    }
    try expect(
      standard.permissions["facebook_pages_text_post_create"] == .approvalRequired,
      "Standard Facebook Pages authority must require publish approval")
    try expect(
      direct.permissions["facebook_pages_text_post_create"] == .autoExecute,
      "Direct writes must auto-execute only the Facebook Pages create action")
    try expect(
      readOnly.permissions["facebook_pages_text_post_create"] == .blocked,
      "Read only must block Facebook Pages publishing")
    try expect(
      blocked.permissions.values.allSatisfy { $0 == .blocked },
      "No access must block all Facebook Pages actions")
    let definitions = try services.providerActionPolicies.actionDefinitions(
      context: owner, appIdOrSlug: app.id)
    let dump = definitions.map(\.actionKey).joined(separator: "\n")
    for forbidden in ["comment", "message", "insight", "ad_", "media", "webhook", "delete", "schedule", "pagination", "raw"] {
      try expect(!dump.contains(forbidden), "Deferred Facebook Pages action leaked into definitions: \(forbidden)")
    }
  }

  private static func testFacebookPagesRelayOwnedOAuthConnectionContract() throws {
    let services = try makeServices()
    let workspace = try unwrap(services.data.getAppState().activeWorkspace, "missing workspace")
    let owner = Self.context(
      roles: [.owner], workspaceId: workspace.id,
      correlationId: "facebook-pages-oauth-owner")
    let catalog = try services.applications.catalogSnapshot(
      context: owner, selectedAppId: "facebook-pages")
    let app = try unwrap(
      catalog.apps.first { $0.slug == "facebook-pages" }, "missing Facebook Pages app")
    let userToken = "facebook-user-token-sensitive"
    let pageToken = "facebook-page-token-sensitive"
    let saved = try services.providerConnections.saveFacebookPagesRelayOwnedOAuthConnection(
      context: owner, appIdOrSlug: app.id, userAccessToken: userToken,
      pageAccessToken: pageToken, grantingUserId: "user_123", selectedPageId: "page_456",
      selectedPageName: "Relay Test Page", selectedPageLink: "https://www.facebook.com/relaytest",
      callbackURL: "https://relay.example.com/api/v1/oauth/facebook-pages/callback",
      grantedScopes: ProviderConnectionService.facebookPagesRelayOwnedOAuthScopes,
      accessExpiresAt: "2026-07-12T12:00:00Z",
      selectedPageCreateContentTaskVerified: true, stateVerified: true,
      now: fixedDate("2026-07-12T11:00:00Z"))
    try expect(
      saved.credentialOwnership == .relayOwned && !saved.userOwnedCredentialsRequired,
      "Facebook Pages must use Relay-owned OAuth")
    try expect(
      saved.requiredScopes == ProviderConnectionService.facebookPagesRelayOwnedOAuthScopes
        && saved.grantedScopes == ProviderConnectionService.facebookPagesRelayOwnedOAuthScopes,
      "Facebook Pages must retain exact three permissions")
    try expect(
      saved.secretReferenceIds.count == 2
        && Set(saved.credentialRequirements.compactMap { $0.secretReferenceId })
          == Set(saved.secretReferenceIds),
      "Facebook Pages must store separate granting-user and selected-Page references")
    try expect(
      saved.health.diagnostics["selectedPageId"] == .string("page_456")
        && saved.health.diagnostics["selectedPageVerified"] == .bool(true)
        && saved.health.diagnostics["pageAuthoredPostsOnly"] == .bool(true),
      "Facebook Pages must retain the immutable selected-Page boundary")
    try expect(
      saved.health.diagnostics["visitorFeedEnabled"] == .bool(false)
        && saved.health.diagnostics["commentsMessagesEnabled"] == .bool(false)
        && saved.health.diagnostics["rawToolsEnabled"] == .bool(false),
      "Facebook Pages must fail closed on excluded surfaces")
    let checked = try services.providerConnections.validateSavedFacebookPagesConnection(
      context: owner, connectionId: saved.id,
      now: fixedDate("2026-07-12T11:05:00Z"))
    try expect(
      checked.status == .connected && checked.health.state == .ready
        && !checked.reauthorizeRequired,
      "Readable exact-contract Facebook Pages references should remain ready")
    let oldRefs = saved.secretReferenceIds
    let rotatedUser = "facebook-user-token-rotated-sensitive"
    let rotatedPage = "facebook-page-token-rotated-sensitive"
    let rotated = try services.providerConnections.rotateFacebookPagesRelayOwnedOAuthTokens(
      context: owner, connectionId: saved.id, userAccessToken: rotatedUser,
      pageAccessToken: rotatedPage, accessExpiresAt: "2026-07-12T13:00:00Z",
      now: fixedDate("2026-07-12T11:10:00Z"))
    try expect(
      Set(rotated.secretReferenceIds).isDisjoint(with: Set(oldRefs))
        && oldRefs.allSatisfy { (try? services.secrets.getSecretValue($0)) == nil },
      "Facebook Pages rotation must atomically replace and delete both old references")
    let invalid = try services.providerConnections.recordFacebookPagesAuthorizationFailure(
      context: owner, connectionId: rotated.id, providerCode: "page_access_lost",
      now: fixedDate("2026-07-12T11:15:00Z"))
    try expect(
      invalid.status == .authRequired && invalid.health.state == .error
        && invalid.reauthorizeRequired
        && invalid.lastError?.contains("facebook_pages_page_access_lost") == true,
      "Provider authorization loss must fail closed and require reconnect")

    let missing = try services.providerConnections.saveFacebookPagesRelayOwnedOAuthConnection(
      context: owner, appIdOrSlug: app.id, userAccessToken: "facebook-user-missing-test",
      pageAccessToken: "facebook-page-missing-test", grantingUserId: "user_789",
      selectedPageId: "page_999", selectedPageName: "Missing Token Page",
      selectedPageLink: nil,
      callbackURL: "https://relay.example.com/api/v1/oauth/facebook-pages/callback",
      grantedScopes: ProviderConnectionService.facebookPagesRelayOwnedOAuthScopes,
      accessExpiresAt: nil, selectedPageCreateContentTaskVerified: true,
      stateVerified: true, now: fixedDate("2026-07-12T11:20:00Z"))
    _ = try services.secrets.delete(missing.secretReferenceIds[1])
    let missingHealth = try services.providerConnections.validateSavedFacebookPagesConnection(
      context: owner, connectionId: missing.id,
      now: fixedDate("2026-07-12T11:25:00Z"))
    try expect(
      missingHealth.status == .authRequired && missingHealth.health.state == .error
        && missingHealth.reauthorizeRequired
        && missingHealth.health.diagnostics["unreadableSecretFields"]
          == .array([.string("facebook_pages_page_access_token")]),
      "Missing Page token reference must be distinguished and require reconnect")

    let retained = try services.database.all(
      "SELECT connection_json AS value FROM applications_provider_connections UNION ALL SELECT label AS value FROM secret_references")
      .compactMap { sqliteText($0["value"]) }.joined(separator: "\n")
    for secret in [userToken, pageToken, rotatedUser, rotatedPage,
                   "facebook-user-missing-test", "facebook-page-missing-test"] {
      try expect(!retained.contains(secret), "Facebook Pages OAuth secret leaked into SQLite")
    }
  }

