        && saved.health.diagnostics["linkedFacebookPageRequired"] == .bool(false)
        && saved.health.diagnostics["ownedMediaOnly"] == .bool(true)
        && saved.health.diagnostics["publishingEnabled"] == .bool(false),
      "Instagram Business must bind one professional account without Facebook Page semantics")
    let checked = try services.providerConnections.validateSavedInstagramBusinessConnection(
      context: owner, connectionId: saved.id,
      now: fixedDate("2026-07-12T15:01:00Z"))
    try expect(
      checked.status == .connected && checked.health.state == .ready
        && !checked.reauthorizeRequired,
      "Readable exact-scope Instagram token should remain ready")
    let oldReference = try unwrap(saved.secretReferenceIds.first, "missing Instagram token reference")
    let rotatedToken = "instagram-business-access-rotated-sensitive"
