      context: owner, connectionId: saved.id, now: fixedDate("2026-07-12T20:01:00Z"))
    try expect(checked.status == .connected && checked.health.state == .ready,
      "Readable exact-bound Bluesky secret references should remain ready")
    let oldIds = Set(saved.secretReferenceIds)
    let replaced = try services.providerConnections.replaceBlueskyOAuthSecrets(
      context: owner, connectionId: saved.id, accessToken: "bluesky-access-replaced-sensitive",
      refreshToken: "bluesky-refresh-replaced-sensitive",
      dpopPrivateKey: "bluesky-dpop-replaced-sensitive",
      now: fixedDate("2026-07-12T20:02:00Z"))
    try expect(
      replaced.secretReferenceIds.count == 3 && oldIds.isDisjoint(with: replaced.secretReferenceIds)
        && oldIds.allSatisfy { (try? services.secrets.getSecretValue($0)) == nil }
        && replaced.health.diagnostics["did"] == .string("did:plc:abcdefghijklmnopqrstuvwx"),
      "Bluesky secret replacement must be atomic without changing identity binding")
    let missingDPoP = try unwrap(
      replaced.credentialRequirements.first { $0.fieldKey == "bluesky_dpop_private_key" }?.secretReferenceId,
      "missing Bluesky DPoP reference")
    _ = try services.secrets.delete(missingDPoP)
    let missing = try services.providerConnections.validateSavedBlueskyConnection(
      context: owner, connectionId: replaced.id, now: fixedDate("2026-07-12T20:03:00Z"))
    try expect(
      missing.status == .authRequired && missing.reauthorizeRequired
        && missing.health.diagnostics["unreadableSecretFields"]
          == .array([.string("bluesky_dpop_private_key")]),
      "Missing Bluesky DPoP reference must be distinguished and require reconnect")
    let persisted = try services.database.all(
      "SELECT connection_json AS value FROM applications_provider_connections UNION ALL SELECT label AS value FROM secret_references")
      .compactMap { sqliteText($0["value"]) }.joined(separator: "\n")
    for secret in [access, refresh, dpop, "bluesky-access-replaced-sensitive",
                   "bluesky-refresh-replaced-sensitive", "bluesky-dpop-replaced-sensitive"] {
      try expect(!persisted.contains(secret), "Bluesky OAuth/DPoP secret leaked into SQLite")
    }
  }

  private static func testBlueskyProviderFoundationContract() throws {
    let services = try makeServices()
    let workspace = try unwrap(services.data.getAppState().activeWorkspace, "missing workspace")
    let owner = Self.context(
      roles: [.owner], workspaceId: workspace.id, correlationId: "bluesky-foundation-owner")
    let foundation = try services.providerFoundations.registerBlueskyFoundation(
      context: owner, now: fixedDate("2026-07-12T20:10:00Z"))
    let exact: Set<String> = [
      "bluesky_profile_get", "bluesky_own_posts_list",
      "bluesky_text_post_draft", "bluesky_text_post_publish",
    ]
    try expect(
      foundation.appSlug == "bluesky"
        && foundation.connectionMode == "relay-owned-atproto-authorization-code-refresh-dpop"
        && foundation.credentialOwnership == .relayOwned
        && foundation.defaultPolicyPreset == .approvalRequired,
      "Bluesky foundation must retain Relay-owned AT Protocol OAuth and Standard authority")
    try expect(Set(foundation.actions.map(\.actionKey)) == exact && foundation.actions.count == 4,
      "Bluesky must register exactly four contracted actions")
    try expect(
      Set(foundation.agentFacingWrapperToolNames) == [
        "relay_bluesky_get_profile", "relay_bluesky_list_own_posts",
        "relay_bluesky_draft_text_post", "relay_bluesky_publish_text_post",
      ], "Bluesky must map exactly four stable wrappers")
    try expect(
      Set(foundation.credentials.map(\.fieldKey)) == [
        "bluesky_oauth_access_token", "bluesky_oauth_refresh_token",
        "bluesky_dpop_private_key", "bluesky_bound_identity",
      ] && !foundation.rawProviderToolExposure,
      "Bluesky must expose three secret refs, identity metadata, and no raw tools")
    let app = try unwrap(
      try services.data.getMarketplaceCatalogApp(
        workspaceId: workspace.id, appIdOrSlug: foundation.appId), "missing Bluesky app")
    let standard = try services.providerActionPolicies.compilePolicyMap(
      context: owner, appIdOrSlug: app.id, preset: .approvalRequired)
    let direct = try services.providerActionPolicies.compilePolicyMap(
      context: owner, appIdOrSlug: app.id, preset: .allowDirectWrites, acknowledgeDangerousPolicy: true)
    let readOnly = try services.providerActionPolicies.compilePolicyMap(
      context: owner, appIdOrSlug: app.id, preset: .readOnly)
    let blocked = try services.providerActionPolicies.compilePolicyMap(
      context: owner, appIdOrSlug: app.id, preset: .blocked)
    for key in ["bluesky_profile_get", "bluesky_own_posts_list", "bluesky_text_post_draft"] {
      try expect(
        standard.permissions[key] == .allowed && direct.permissions[key] == .allowed
          && readOnly.permissions[key] == .allowed,
        "Bluesky reads and local draft must remain allowed outside No access")
    }
    try expect(
      standard.permissions["bluesky_text_post_publish"] == .approvalRequired
        && direct.permissions["bluesky_text_post_publish"] == .autoExecute
        && readOnly.permissions["bluesky_text_post_publish"] == .blocked
        && blocked.permissions.values.allSatisfy { $0 == .blocked },
      "Bluesky publish authority must transform across all four presets")
    let dump = foundation.actions.map(\.actionKey).joined(separator: "\n")
    for forbidden in ["reply", "quote", "repost", "like", "follow", "media", "embed", "facet", "delete", "edit", "search", "timeline", "dm", "moderation", "firehose", "pagination", "raw"] {
      try expect(!dump.contains(forbidden), "Deferred Bluesky action leaked: \(forbidden)")
    }
  }

