  private static func testMeetupRuntimeHarnessContract() throws {
    let root = FileManager.default.temporaryDirectory
      .appendingPathComponent("RelayConsoleMeetupRuntimeTests", isDirectory: true)
      .appendingPathComponent(UUID().uuidString, isDirectory: true)
    let services = try makeServices(root: root)
    let workspace = try unwrap(services.data.getAppState().activeWorkspace, "missing workspace")
    let owner = Self.context(roles: [.owner], workspaceId: workspace.id, correlationId: "meetup-runtime-owner")
    let member = Self.context(roles: [.member], workspaceId: workspace.id, correlationId: "meetup-runtime-member")
    let foundation = try services.providerFoundations.registerMeetupFoundation(context: owner)
    let app = try unwrap(try services.data.getMarketplaceCatalogApp(
      workspaceId: workspace.id, appIdOrSlug: foundation.appId), "missing Meetup runtime app")
    let remoteReference = try services.secrets.set(
      scope: "provider_connection", scopeId: "mpc-meetup-runtime",
      label: "Meetup Railway connection reference", secretValue: "remote-meetup-connection")
    let timestamp = "2026-07-12T22:00:00Z"
    let connection = try services.providerConnections.saveConnection(
      context: owner, connection: MarketplaceProviderConnection(
        id: "mpc-meetup-runtime", workspaceId: workspace.id, appId: app.id,
        appSlug: app.slug, providerKey: "meetup-relay-owned-oauth:member-1",
        providerName: "Meetup", status: .connected, authorizationState: .completed,
        credentialOwnership: .relayOwned, executionAuthority: .railway,
        executionAuthorityVersion: MarketplaceExecutionAuthority.contractVersion,
        userOwnedCredentialsRequired: false,
        credentialRequirements: [ProviderCredentialRequirement(
          fieldKey: "meetup_railway_connection_reference", label: "Railway connection reference",
          required: true, userOwnedRequired: false, secretReferenceId: remoteReference.id,
          status: .verified, helpText: "Opaque Railway binding only.", redactionStatus: "secret-reference-only")],
        secretReferenceIds: [remoteReference.id], accountLabel: "Relay Member",
        connectedHandle: nil, callbackURL: nil, requiredScopes: [], grantedScopes: [],
        selectedCapabilities: app.capabilities,
        health: ProviderConnectorHealth(
          state: .ready, message: "Meetup connected member is ready.", lastCheckedAt: timestamp,
          missingScopes: [], unavailableTools: [], diagnostics: [
            "railwayCallbackOnly": .bool(true), "stateVerified": .bool(true),
            "memberVerified": .bool(true), "fixedQueriesOnly": .bool(true),
            "automaticRetry": .bool(false), "automaticPagination": .bool(false),
            "rawToolsEnabled": .bool(false), "maxProviderRequestsPerAction": .number(1),
          ], redactionStatus: "private-state-excluded"), senderIdentities: [],
        installPolicy: "connected_member_explicit_event_reads", lastCheckedAt: timestamp,
        lastError: nil, manualEvidenceNote: nil, reauthorizeRequired: false,
        disconnecting: false, betaBlocked: false, createdAt: timestamp, updatedAt: timestamp,
        redactionStatus: "private-state-excluded"))
    let hermesHarness = try prepareInstalledHarness(services: services, key: .hermes)
    let openClawHarness = try prepareInstalledHarness(services: services, key: .openclaw)
    let hermes = try services.data.createAgent(
      workspaceId: workspace.id, name: "Meetup Hermes", harnessId: hermesHarness.id,
      externalAgentId: "meetup-hermes", hermesProfileSlug: "meetup-hermes",
      hermesHomePath: root.appendingPathComponent("meetup-hermes-profile").path)
    let openClaw = try services.data.createAgent(
      workspaceId: workspace.id, name: "Meetup OpenClaw", harnessId: openClawHarness.id,
      externalAgentId: "meetup-openclaw",
      workspaceFolderPath: root.appendingPathComponent("meetup-openclaw-workspace").path)
    let unrelated = try services.data.createAgent(
      workspaceId: workspace.id, name: "Meetup Unrelated", harnessId: hermesHarness.id,
      externalAgentId: "meetup-unrelated", hermesProfileSlug: "meetup-unrelated",
      hermesHomePath: root.appendingPathComponent("meetup-unrelated-profile").path)
    for agent in [hermes, openClaw] {
      let install = try services.marketplaceInstalls.createInstall(
        context: owner, request: installRequest(
          id: createRelayId("minreq-meetup"), workspaceId: workspace.id, app: app,
          connectionId: connection.id, agent: agent, roleId: app.roleManifest.primaryRole,
          selectedCapabilities: app.capabilities, riskAcknowledged: true))
      _ = try services.providerActionPolicies.compilePolicyMap(
        context: owner, appIdOrSlug: app.id, preset: .readOnly,
        connectionId: connection.id, installId: install.id, agentId: agent.id)
    }
    let expected: Set<String> = ["relay_meetup_get_self", "relay_meetup_get_event"]
    for agent in [hermes, openClaw] {
      let snapshot = try services.marketplaceRuntimeMounts.snapshot(context: member, agent: agent)
      let mounted = try unwrap(snapshot.apps.first, "missing Meetup runtime mount")
      let prompt = try unwrap(services.marketplaceRuntimeMounts.renderPromptBlock(snapshot), "missing Meetup prompt")
      try expect(
        snapshot.apps.map(\.appSlug) == ["meetup"] && snapshot.toolCount == 2
          && Set(mounted.tools.map(\.toolName)) == expected
          && mounted.instructions.count <= 900
          && mounted.tools.allSatisfy { !$0.requiresApproval }
          && prompt.contains("App: Meetup (meetup)")
          && !snapshot.rawProviderToolExposure
          && !prompt.localizedCaseInsensitiveContains("graphql")
          && !prompt.localizedCaseInsensitiveContains("bearer "),
        "Meetup runtime must expose exactly two policy-scoped wrappers without raw GraphQL or secrets")
      let harness = agent.id == hermes.id ? hermesHarness : openClawHarness
      let harnessPath = URL(fileURLWithPath: try unwrap(
        harness.config["installPath"]?.string, "missing Meetup harness install path"))
      let dispatch = RuntimeDispatchRequest(
        dispatchId: "rtd-meetup-\(agent.id)", correlationId: "corr-meetup-\(agent.id)",
        threadId: "thr-meetup-\(agent.id)", messageId: "msg-meetup-\(agent.id)",
        sessionId: "rts-meetup-\(agent.id)", attempt: 1, agent: agent,
        runtimeBinding: agent.binding, harness: agent.harness,
        inputContent: "review the explicit Meetup event", inputFormat: .plain,
        recentMessages: [], timeoutMs: 30_000, createdAt: timestamp)
      let bridge = try services.harnessInstall.prepareMarketplaceRuntimeToolBridge(
        for: agent, request: dispatch, harnessPath: harnessPath, mount: snapshot)
      try expect(bridge.registeredToolNames == expected,
        "Hermes and OpenClaw must register both Meetup Relay wrappers")
    }
    let unrelatedSnapshot = try services.marketplaceRuntimeMounts.snapshot(context: member, agent: unrelated)
    try expect(unrelatedSnapshot.apps.isEmpty && unrelatedSnapshot.toolCount == 0,
      "Unrelated agents must not inherit Meetup wrappers")
  }

