  private static func testTwistProviderFoundationAndPolicyContract() throws {
    let services = try makeServices()
    let workspace = try unwrap(services.data.getAppState().activeWorkspace, "missing workspace")
    let owner = Self.context(
      roles: [.owner], workspaceId: workspace.id, correlationId: "twist-foundation-owner")
    let foundation = try services.providerFoundations.registerTwistFoundation(
      context: owner, now: fixedDate("2026-07-13T10:30:00Z"))
    let expectedActions: Set<String> = [
      "twist_user_get", "twist_workspaces_list", "twist_channels_list",
      "twist_inbox_threads_list", "twist_thread_comments_get",
