    let expectedWrappers: Set<String> = [
      "relay_twist_get_user", "relay_twist_list_workspaces",
      "relay_twist_list_channels", "relay_twist_list_inbox_threads",
      "relay_twist_get_thread_with_comments",
    ]
    let expectedScopes: Set<String> = [
      "user:read", "workspaces:read", "channels:read", "threads:read", "comments:read",
    ]
    try expect(
      foundation.appSlug == "twist"
        && foundation.credentialOwnership == .relayOwned
        && !foundation.userOwnedCredentialsRequired
        && foundation.supportedPolicyPresets == [.readOnly, .blocked]
        && foundation.defaultPolicyPreset == .readOnly
        && Set(foundation.actions.map(\.actionKey)) == expectedActions
