        && foundation.credentials.count == 3
        && foundation.credentials.filter { $0.secretStorage == "railway-encrypted-only" }.count == 2
        && foundation.budgetPolicy["maxWrapperTools"] == .number(5)
        && foundation.budgetPolicy["maxWorkspaces"] == .number(20)
        && foundation.budgetPolicy["maxChannels"] == .number(50)
        && foundation.budgetPolicy["maxInboxThreads"] == .number(20)
        && foundation.budgetPolicy["maxComments"] == .number(30)
        && foundation.budgetPolicy["maxProviderRequestsPerAction"] == .number(2)
        && foundation.budgetPolicy["automaticRetry"] == .bool(false)
        && foundation.budgetPolicy["automaticPagination"] == .bool(false)
        && foundation.privacyPolicy["directMessagesSearchAttachmentsNotificationsMembers"] == .string("blocked")
        && foundation.privacyPolicy["writesRemovesWebhooksBotsBulkExportRawAPI"] == .string("blocked")
        && !foundation.rawProviderToolExposure,
      "Twist foundation must expose only five bounded read wrappers and Relay-held credentials")
    let definitions = try services.data.listMarketplaceProviderActionDefinitions(
      workspaceId: workspace.id, appId: foundation.appId, limit: 10)
    let app = try unwrap(try services.data.getMarketplaceCatalogApp(
      workspaceId: workspace.id, appIdOrSlug: foundation.appId), "missing Twist app")
    try expect(
      definitions.count == 5
        && Set(definitions.flatMap(\.requiredScopes)) == expectedScopes
        && definitions.allSatisfy {
          $0.kind == .read && $0.adapterKind == .nativeAPI && $0.defaultPermission == .allowed
        }
        && definitions.allSatisfy {
          !$0.actionKey.localizedCaseInsensitiveContains("message")
            && !$0.actionKey.localizedCaseInsensitiveContains("search")
            && !$0.actionKey.localizedCaseInsensitiveContains("attachment")
            && !$0.actionKey.localizedCaseInsensitiveContains("write")
            && !$0.actionKey.localizedCaseInsensitiveContains("remove")
        },
      "Twist definitions must preserve exact scopes and suppress deferred authority")
    let audit = ProviderExecutionAuditIdentity(
      workspaceId: workspace.id, actorId: owner.actorId, actorRole: "owner",
      agentId: nil, appId: foundation.appId, appSlug: "twist",
      connectionId: "mpc-twist-broker", installId: nil, approvalId: nil,
      dispatchId: nil, threadId: nil, source: "twist-fake-adapter-test",
      redactionStatus: "private-state-excluded")
    let adapter = TwistProviderActionAdapter(client: FakeTwistProviderActionClient())
    func fakeRead(_ action: String, payload: JSONRecord = [:]) throws -> JSONRecord {
      let definition = try unwrap(
        definitions.first(where: { $0.actionKey == action }), "missing Twist action \(action)")
      return try adapter.execute(request: MarketplaceProviderActionAdapterRequest(
        context: owner, app: app, definition: definition, permission: .allowed,
        payload: payload, approvalReference: nil, auditIdentity: audit,
        idempotencyKey: "twist-fake-\(action)")).result
    }
    let userRead = try fakeRead("twist_user_get")
    let workspaceRead = try fakeRead("twist_workspaces_list", payload: ["limit": .number(5)])
    let channelRead = try fakeRead(
      "twist_channels_list", payload: ["workspaceId": .string("201"), "limit": .number(5)])
    let inboxRead = try fakeRead(
      "twist_inbox_threads_list", payload: ["workspaceId": .string("201"), "limit": .number(5)])
    let commentRead = try fakeRead(
      "twist_thread_comments_get", payload: ["threadId": .string("401"), "commentLimit": .number(5)])
    try expect(objectValue(userRead["user"])?["name"] == .string("Relay Teammate"),
      "Twist fake user read must return a useful connected-user name")
    try expect(objectValue(arrayValue(workspaceRead["workspaces"]).first)?["name"] == .string("Relay Workspace"),
      "Twist fake workspace read must return a useful workspace name")
    try expect(objectValue(arrayValue(channelRead["channels"]).first)?["name"] == .string("Engineering"),
      "Twist fake channel read must return a useful channel name")
    try expect(objectValue(arrayValue(inboxRead["threads"]).first)?["title"] == .string("Release readiness"),
      "Twist fake inbox read must return useful thread content")
    try expect(
      objectValue(arrayValue(commentRead["comments"]).first)?["content"]
        == .string("The release checklist is complete.")
        && commentRead["providerRequestCount"] == .number(2),
      "Twist fake composed read must return useful comments within two provider requests")
    let blocked = try services.providerActionPolicies.compilePolicyMap(
      context: owner, appIdOrSlug: foundation.appId, preset: .blocked,
      now: fixedDate("2026-07-13T10:31:00Z"))
    try expect(
      Set(blocked.permissions.keys) == expectedActions
        && blocked.permissions.values.allSatisfy { $0 == .blocked }
