    let secretReference = try services.secrets.set(
      scope: "provider_connection", scopeId: "mpc-twist-broker",
      label: "Twist Railway connection reference", secretValue: "remote-twist-connection")
    let timestamp = "2026-07-13T10:32:00Z"
    let connection = try services.providerConnections.saveConnection(
      context: owner, connection: MarketplaceProviderConnection(
        id: "mpc-twist-broker", workspaceId: workspace.id, appId: foundation.appId,
