      workspaceFolderPath: root.appendingPathComponent("twist-openclaw-workspace").path)
    let unrelated = try services.data.createAgent(
      workspaceId: workspace.id, name: "Twist Unrelated", harnessId: hermesHarness.id,
      externalAgentId: "twist-unrelated", hermesProfileSlug: "twist-unrelated",
      hermesHomePath: root.appendingPathComponent("twist-unrelated-profile").path)
    for agent in [hermes, openClaw] {
      let install = try services.marketplaceInstalls.createInstall(
        context: owner, request: installRequest(
