      let harnessPath = URL(fileURLWithPath: try unwrap(
        harness.config["installPath"]?.string, "missing Twist harness install path"))
      let dispatch = RuntimeDispatchRequest(
        dispatchId: "rtd-twist-\(agent.id)", correlationId: "corr-twist-\(agent.id)",
        threadId: "thr-twist-\(agent.id)", messageId: "msg-twist-\(agent.id)",
        sessionId: "rts-twist-\(agent.id)", attempt: 1, agent: agent,
        runtimeBinding: agent.binding, harness: agent.harness,
        inputContent: "summarize the explicit Twist thread", inputFormat: .plain,
        recentMessages: [], timeoutMs: 30_000, createdAt: timestamp)
      let bridge = try services.harnessInstall.prepareMarketplaceRuntimeToolBridge(
        for: agent, request: dispatch, harnessPath: harnessPath, mount: snapshot)
      try expect(bridge.registeredToolNames == expected,
        "Hermes and OpenClaw must register all five Twist Relay wrappers")
    }
    let unrelatedSnapshot = try services.marketplaceRuntimeMounts.snapshot(
      context: member, agent: unrelated)
    try expect(unrelatedSnapshot.apps.isEmpty && unrelatedSnapshot.toolCount == 0,
      "Unrelated agents must not inherit Twist instructions or tools")
  }

