  private static func testWebexRuntimeHarnessContract() throws {
    let root = FileManager.default.temporaryDirectory
      .appendingPathComponent("RelayConsoleWebexRuntimeTests", isDirectory: true)
      .appendingPathComponent(UUID().uuidString, isDirectory: true)
    let services = try makeServices(root: root)
    let workspace = try unwrap(services.data.getAppState().activeWorkspace, "missing workspace")
    let owner = Self.context(roles: [.owner], workspaceId: workspace.id, correlationId: "webex-runtime-owner")
    let member = Self.context(roles: [.member], workspaceId: workspace.id, correlationId: "webex-runtime-member")
    let foundation = try services.providerFoundations.registerWebexFoundation(context: owner)
    let app = try unwrap(try services.data.getMarketplaceCatalogApp(
      workspaceId: workspace.id, appIdOrSlug: foundation.appId), "missing Webex runtime app")
    let remoteReference = try services.secrets.set(
      scope: "provider_connection", scopeId: "mpc-webex-runtime",
      label: "Webex Railway connection reference", secretValue: "remote-webex-connection")
    let timestamp = "2026-07-12T22:50:00Z"
    let connection = try services.providerConnections.saveConnection(
      context: owner, connection: MarketplaceProviderConnection(
        id: "mpc-webex-runtime", workspaceId: workspace.id, appId: app.id,
        appSlug: app.slug, providerKey: "webex-relay-owned-oauth:person-A1",
        providerName: "Webex", status: .connected, authorizationState: .completed,
        credentialOwnership: .relayOwned, executionAuthority: .railway,
        executionAuthorityVersion: MarketplaceExecutionAuthority.contractVersion,
        userOwnedCredentialsRequired: false,
        credentialRequirements: [ProviderCredentialRequirement(
          fieldKey: "webex_railway_connection_reference", label: "Railway connection reference",
          required: true, userOwnedRequired: false, secretReferenceId: remoteReference.id,
          status: .verified, helpText: "Opaque Railway binding only.", redactionStatus: "secret-reference-only")],
        secretReferenceIds: [remoteReference.id], accountLabel: "Relay Person",
        connectedHandle: nil, callbackURL: nil,
        requiredScopes: ["spark:people_read", "meeting:schedules_read"],
        grantedScopes: ["spark:people_read", "meeting:schedules_read"],
        selectedCapabilities: app.capabilities,
        health: ProviderConnectorHealth(
          state: .ready, message: "Webex connected Person is ready.", lastCheckedAt: timestamp,
          missingScopes: [], unavailableTools: [], diagnostics: [
            "railwayCallbackOnly": .bool(true), "stateVerified": .bool(true), "pkceS256": .bool(true),
            "personVerified": .bool(true), "fixedEndpointsOnly": .bool(true),
            "automaticRetry": .bool(false), "automaticPagination": .bool(false),
            "rawToolsEnabled": .bool(false), "maxMeetings": .number(10),
            "maxProviderRequestsPerAction": .number(1),
          ], redactionStatus: "private-state-excluded"), senderIdentities: [],
        installPolicy: "connected_person_bounded_meeting_reads", lastCheckedAt: timestamp,
        lastError: nil, manualEvidenceNote: nil, reauthorizeRequired: false,
        disconnecting: false, betaBlocked: false, createdAt: timestamp, updatedAt: timestamp,
        redactionStatus: "private-state-excluded"))
    let hermesHarness = try prepareInstalledHarness(services: services, key: .hermes)
    let openClawHarness = try prepareInstalledHarness(services: services, key: .openclaw)
    let hermes = try services.data.createAgent(
      workspaceId: workspace.id, name: "Webex Hermes", harnessId: hermesHarness.id,
      externalAgentId: "webex-hermes", hermesProfileSlug: "webex-hermes",
      hermesHomePath: root.appendingPathComponent("webex-hermes-profile").path)
    let openClaw = try services.data.createAgent(
      workspaceId: workspace.id, name: "Webex OpenClaw", harnessId: openClawHarness.id,
      externalAgentId: "webex-openclaw",
      workspaceFolderPath: root.appendingPathComponent("webex-openclaw-workspace").path)
    let unrelated = try services.data.createAgent(
      workspaceId: workspace.id, name: "Webex Unrelated", harnessId: hermesHarness.id,
      externalAgentId: "webex-unrelated", hermesProfileSlug: "webex-unrelated",
      hermesHomePath: root.appendingPathComponent("webex-unrelated-profile").path)
    for agent in [hermes, openClaw] {
      let install = try services.marketplaceInstalls.createInstall(
        context: owner, request: installRequest(
          id: createRelayId("minreq-webex"), workspaceId: workspace.id, app: app,
          connectionId: connection.id, agent: agent, roleId: app.roleManifest.primaryRole,
          selectedCapabilities: app.capabilities, riskAcknowledged: true))
      _ = try services.providerActionPolicies.compilePolicyMap(
        context: owner, appIdOrSlug: app.id, preset: .readOnly,
        connectionId: connection.id, installId: install.id, agentId: agent.id)
    }
    let expected: Set<String> = ["relay_webex_get_person", "relay_webex_list_meetings", "relay_webex_get_meeting"]
    for agent in [hermes, openClaw] {
      let snapshot = try services.marketplaceRuntimeMounts.snapshot(context: member, agent: agent)
      let mounted = try unwrap(snapshot.apps.first, "missing Webex runtime mount")
      let prompt = try unwrap(services.marketplaceRuntimeMounts.renderPromptBlock(snapshot), "missing Webex prompt")
      try expect(snapshot.apps.map(\.appSlug) == ["webex"] && snapshot.toolCount == 3
        && Set(mounted.tools.map(\.toolName)) == expected
        && mounted.instructions.count <= 900
        && mounted.tools.allSatisfy { !$0.requiresApproval }
        && prompt.contains("App: Webex (webex)")
        && !snapshot.rawProviderToolExposure
        && !prompt.localizedCaseInsensitiveContains("bearer "),
        "Webex runtime must expose three policy-scoped wrappers without secrets")
      let harness = agent.id == hermes.id ? hermesHarness : openClawHarness
      let harnessPath = URL(fileURLWithPath: try unwrap(harness.config["installPath"]?.string, "missing Webex harness install path"))
      let dispatch = RuntimeDispatchRequest(
        dispatchId: "rtd-webex-\(agent.id)", correlationId: "corr-webex-\(agent.id)",
        threadId: "thr-webex-\(agent.id)", messageId: "msg-webex-\(agent.id)",
        sessionId: "rts-webex-\(agent.id)", attempt: 1, agent: agent,
        runtimeBinding: agent.binding, harness: agent.harness,
        inputContent: "review my Webex Meetings", inputFormat: .plain,
        recentMessages: [], timeoutMs: 30_000, createdAt: timestamp)
      let bridge = try services.harnessInstall.prepareMarketplaceRuntimeToolBridge(
        for: agent, request: dispatch, harnessPath: harnessPath, mount: snapshot)
      try expect(bridge.registeredToolNames == expected,
        "Hermes and OpenClaw must register all three Webex Relay wrappers")
    }
    let unrelatedSnapshot = try services.marketplaceRuntimeMounts.snapshot(context: member, agent: unrelated)
    try expect(unrelatedSnapshot.apps.isEmpty && unrelatedSnapshot.toolCount == 0,
      "Unrelated agents must not inherit Webex wrappers")
  }

