      try expect(snapshot.apps.map(\.appSlug) == ["line"], "LINE runtime must mount only the LINE app")
      try expect(snapshot.toolCount == 1, "LINE runtime must mount exactly one wrapper")
      try expect(mounted.tools.map(\.toolName) == ["relay_line_get_profile"], "LINE runtime must mount only relay_line_get_profile")
      try expect(mounted.instructions.count <= 900, "LINE runtime instructions must stay within the 900-character budget")
      try expect(mounted.tools.allSatisfy { !$0.requiresApproval }, "LINE profile reads must not require approval")
      try expect(prompt.contains("App: LINE (line)"), "LINE runtime prompt must identify the mounted app")
      try expect(!prompt.contains("relay_line_get_profile"), "LINE runtime prompt must not render callable wrapper names as fake text tools")
      try expect(!snapshot.rawProviderToolExposure, "LINE runtime must suppress raw provider tools")
      try expect(!prompt.localizedCaseInsensitiveContains("channel access token"), "LINE runtime prompt must not expose Messaging API credentials")
      try expect(!prompt.localizedCaseInsensitiveContains("bearer "), "LINE runtime prompt must not expose bearer-token language")
      let harness = agent.id == hermes.id ? hermesHarness : openClawHarness
      let harnessPath = URL(fileURLWithPath: try unwrap(harness.config["installPath"]?.string, "missing LINE harness path"))
      let dispatch = RuntimeDispatchRequest(
        dispatchId: "rtd-line-\(agent.id)", correlationId: "corr-line-\(agent.id)",
        threadId: "thr-line-\(agent.id)", messageId: "msg-line-\(agent.id)",
        sessionId: "rts-line-\(agent.id)", attempt: 1, agent: agent,
        runtimeBinding: agent.binding, harness: agent.harness,
        inputContent: "identify my connected LINE profile", inputFormat: .plain,
        recentMessages: [], timeoutMs: 30_000, createdAt: timestamp)
      let bridge = try services.harnessInstall.prepareMarketplaceRuntimeToolBridge(
        for: agent, request: dispatch, harnessPath: harnessPath, mount: snapshot)
      try expect(bridge.registeredToolNames == Set(["relay_line_get_profile"]),
        "Hermes and OpenClaw must each register exactly the LINE profile wrapper as callable")
    }
    let unrelatedSnapshot = try services.marketplaceRuntimeMounts.snapshot(context: member, agent: unrelated)
    try expect(unrelatedSnapshot.apps.isEmpty && unrelatedSnapshot.toolCount == 0, "LINE runtime mount must remain isolated from unrelated agents")
  }

