        recentMessages: [], timeoutMs: 30_000, createdAt: timestamp)
      let bridge = try services.harnessInstall.prepareMarketplaceRuntimeToolBridge(
        for: agent, request: dispatch, harnessPath: harnessPath, mount: snapshot)
      try expect(bridge.registeredToolNames == expected,
        "Hermes and OpenClaw must register every Nextdoor Relay wrapper")
    }
    let unrelatedSnapshot = try services.marketplaceRuntimeMounts.snapshot(context: member, agent: unrelated)
    try expect(unrelatedSnapshot.apps.isEmpty && unrelatedSnapshot.toolCount == 0,
      "Unrelated agents must not inherit Nextdoor wrappers")
    let install = try unwrap(hermesInstall, "missing Nextdoor Hermes install")
    let profile = try services.providerActionBroker.execute(
      context: owner, request: MarketplaceProviderActionBrokerRequest(
        appIdOrSlug: app.id, actionKey: "nextdoor_profile_get", payload: [:],
        connectionId: connection.id, installId: install.id, agentId: hermes.id,
        idempotencyKey: "nextdoor-profile"))
    let profileObject = objectValue(profile.transientProviderResult?["profile"])
    try expect(
      profile.adapterExecuted && profileObject?["profileType"] == .string("neighbor")
        && profileObject?["verified"] == .bool(true),
      "Nextdoor selected-profile read must execute through the broker with useful verified fields")
    let draft = try services.providerActionBroker.execute(
      context: owner, request: MarketplaceProviderActionBrokerRequest(
        appIdOrSlug: app.id, actionKey: "nextdoor_text_post_draft",
        payload: ["text": .string("A bounded draft")], connectionId: connection.id,
        installId: install.id, agentId: hermes.id, idempotencyKey: "nextdoor-draft"))
    try expect(
      draft.adapterExecuted && draft.transientProviderResult?["providerSideEffect"] == .bool(false),
      "Nextdoor draft must remain local and brokered")
    let pending = try services.providerActionBroker.execute(
      context: owner, request: MarketplaceProviderActionBrokerRequest(
        appIdOrSlug: app.id, actionKey: "nextdoor_text_post_publish",
        payload: ["text": .string("Approved neighborhood update")], connectionId: connection.id,
        installId: install.id, agentId: hermes.id, idempotencyKey: "nextdoor-pending"))
    try expect(!pending.adapterExecuted && pending.execution.status == .pendingApproval,
      "Standard Nextdoor publishing must create a pending approval")
    let approval = try unwrap(pending.approval, "missing Nextdoor approval")
    let approved = try services.providerActionApprovals.approve(
      context: owner, approvalId: approval.id,
      approvedPayload: ["text": .string("Approved neighborhood update")])
    let executed = try services.providerActionBroker.execute(
      context: owner, request: MarketplaceProviderActionBrokerRequest(
        appIdOrSlug: app.id, actionKey: "nextdoor_text_post_publish",
        payload: ["text": .string("Approved neighborhood update")], connectionId: connection.id,
        installId: install.id, agentId: hermes.id, approvalId: approved.id,
        idempotencyKey: "nextdoor-approved"))
    try expect(
      executed.adapterExecuted && executed.execution.status == .succeeded
        && (executed.execution.providerResult ?? executed.transientProviderResult)?["postId"]
          == .string("share-published"),
      "Approved Nextdoor publish must execute exactly once through the broker")
    _ = try services.providerActionPolicies.compilePolicyMap(
      context: owner, appIdOrSlug: app.id, preset: .allowDirectWrites, acknowledgeDangerousPolicy: true,
      connectionId: connection.id, installId: install.id, agentId: hermes.id)
    let direct = try services.providerActionBroker.execute(
      context: owner, request: MarketplaceProviderActionBrokerRequest(
        appIdOrSlug: app.id, actionKey: "nextdoor_text_post_publish",
        payload: ["text": .string("Direct neighborhood update")], connectionId: connection.id,
        installId: install.id, agentId: hermes.id, idempotencyKey: "nextdoor-direct"))
    try expect(
      direct.adapterExecuted && direct.execution.status == .succeeded
        && direct.auditEventId != nil && direct.permissionMap?.policyPreset == .allowDirectWrites,
      "Direct writes must still route through Nextdoor policy, adapter, execution, and audit")
    let rejected = try services.providerActionBroker.execute(
      context: owner, request: MarketplaceProviderActionBrokerRequest(
        appIdOrSlug: app.id, actionKey: "nextdoor_text_post_draft",
        payload: ["text": .string("No media"), "media": .string("https://example.com/image.png")],
        connectionId: connection.id, installId: install.id, agentId: hermes.id,
        idempotencyKey: "nextdoor-rejected"))
    try expect(
      rejected.execution.status == .failed
        && rejected.execution.providerError?["providerErrorCode"] == .string("nextdoor_payload_not_supported"),
      "Nextdoor broker must reject deferred media and foreign payload fields")
    let persisted = try services.database.all(
      "SELECT execution_json AS value FROM marketplace_provider_action_executions")
      .compactMap { sqliteText($0["value"]) }.joined(separator: "\n")
    try expect(!persisted.contains("remote-nextdoor-connection"),
      "Nextdoor broker persistence must not include the Railway connection reference")
  }

  private static func testBlueskyBrokerAdapterContract() throws {
