      grantedScopes: ProviderConnectionService.blueskyRelayOwnedOAuthScopes,
      stateVerified: true, pkceVerified: true, parVerified: true, dpopBound: true,
      didVerified: true, pdsVerified: true, issuerVerified: true)
    connection.executionAuthority = .railway
    connection.executionAuthorityVersion = MarketplaceExecutionAuthority.contractVersion
    connection = try services.providerConnections.saveConnection(
