      connectionId: connection.id)
    let profile = try services.providerActionBroker.execute(
      context: owner, request: MarketplaceProviderActionBrokerRequest(
        appIdOrSlug: app.id, actionKey: "bluesky_profile_get", payload: [:],
        connectionId: connection.id, idempotencyKey: "bluesky-profile"))
    let profileObject = objectValue(profile.transientProviderResult?["profile"])
    try expect(
