      context: owner, appIdOrSlug: app.id, preset: .allowDirectWrites, acknowledgeDangerousPolicy: true)
    let readOnly = try services.providerActionPolicies.compilePolicyMap(
      context: owner, appIdOrSlug: app.id, preset: .readOnly)
    let blocked = try services.providerActionPolicies.compilePolicyMap(
      context: owner, appIdOrSlug: app.id, preset: .blocked)
    for key in [
      "threads_profile_get", "threads_own_posts_list", "threads_own_post_get",
      "threads_text_post_draft",
    ] {
      try expect(
        standard.permissions[key] == .allowed && direct.permissions[key] == .allowed
          && readOnly.permissions[key] == .allowed,
        "Threads reads and local draft must remain allowed outside No access")
    }
    try expect(
      standard.permissions["threads_text_post_publish"] == .approvalRequired
        && direct.permissions["threads_text_post_publish"] == .autoExecute
        && readOnly.permissions["threads_text_post_publish"] == .blocked
        && blocked.permissions.values.allSatisfy { $0 == .blocked },
      "Threads publish authority must transform across all four presets")
    let definitions = try services.providerActionPolicies.actionDefinitions(
      context: owner, appIdOrSlug: app.id)
    let dump = definitions.map(\.actionKey).joined(separator: "\n")
    for forbidden in [
      "reply", "mention", "insight", "search", "discover", "media_publish", "poll",
      "location", "topic", "quote", "repost", "delete", "embed", "webhook", "pagination", "raw",
    ] {
      try expect(!dump.contains(forbidden), "Deferred Threads action leaked: \(forbidden)")
    }
  }

