  private static func testTumblrBrokerAdapterContract() throws {
    final class Stub: TumblrProviderHTTPClient, @unchecked Sendable {
      var requests: [TumblrProviderHTTPRequest] = []
      func send(_ request: TumblrProviderHTTPRequest) throws -> TumblrProviderHTTPResponse {
        requests.append(request)
        let body: String
        switch request.url.path {
        case "/v2/user/info":
          body = #"{"response":{"user":{"name":"relay_account","blogs":[{"uuid":"t:RelayOwnedBlog_123","name":"relay-blog","title":"Relay Blog","url":"https://relay-blog.tumblr.com/","primary":true,"type":"public"}]}}}"#
        case "/v2/blog/t:RelayOwnedBlog_123/info":
          body = #"{"response":{"blog":{"uuid":"t:RelayOwnedBlog_123","name":"relay-blog","title":"Relay Blog","url":"https://relay-blog.tumblr.com/","description":"<p>Notes about <strong>reliable agents</strong>.</p>","updated":1752326400,"posts":12}}}"#
        case "/v2/blog/t:RelayOwnedBlog_123/posts":
          body = #"{"response":{"blog":{"uuid":"t:RelayOwnedBlog_123","name":"relay-blog"},"posts":[{"blog_name":"relay-blog","id_string":"1234567890123456789","post_url":"https://relay-blog.tumblr.com/post/1234567890123456789","date":"2026-07-12 12:00:00 GMT","timestamp":1752326400,"state":"published","tags":["agents","reliability"],"content":[{"type":"text","text":"A practical note about reliable agent loops."}],"trail":[]}]}}"#
        default:
          throw MarketplaceProviderActionAdapterFailure(
            code: "tumblr_stub_unexpected_request", message: request.url.absoluteString)
        }
        return TumblrProviderHTTPResponse(statusCode: 200, body: Data(body.utf8))
      }
    }
    let services = try makeServices()
    let workspace = try unwrap(services.data.getAppState().activeWorkspace, "missing workspace")
    let owner = Self.context(
      roles: [.owner], workspaceId: workspace.id, correlationId: "tumblr-broker-owner")
    let foundation = try services.providerFoundations.registerTumblrFoundation(
      context: owner, now: fixedDate("2026-07-12T18:20:00Z"))
    let app = try unwrap(
      try services.data.getMarketplaceCatalogApp(
        workspaceId: workspace.id, appIdOrSlug: foundation.appId), "missing Tumblr app")
    let token = "tumblr-live-access-sensitive"
    let connection = try services.providerConnections.saveTumblrRelayOwnedOAuthConnection(
      context: owner, appIdOrSlug: app.id, accessToken: token,
      refreshToken: "tumblr-live-refresh-sensitive", accountName: "relay_account",
      selectedBlogUUID: "t:RelayOwnedBlog_123", selectedBlogName: "relay-blog",
      selectedBlogTitle: "Relay Blog", selectedBlogURL: "https://relay-blog.tumblr.com/",
      selectedBlogPrimary: true, selectedBlogType: "public",
      callbackURL: "https://relay.example.com/api/v1/oauth/tumblr/callback",
      grantedScopes: ProviderConnectionService.tumblrRelayOwnedOAuthScopes,
      accessExpiresAt: nil, stateVerified: true, now: fixedDate("2026-07-12T18:20:01Z"))
    _ = try services.providerActionPolicies.compilePolicyMap(
      context: owner, appIdOrSlug: app.id, preset: .readOnly,
      connectionId: connection.id, now: fixedDate("2026-07-12T18:20:02Z"))
    let stub = Stub()
    let broker = MarketplaceProviderActionBrokerService(
      data: services.data, approvals: services.providerActionApprovals,
      auditSecurity: services.auditSecurity,
      adapter: RoutingMarketplaceProviderActionAdapter(
        tumblrAdapter: TumblrProviderActionAdapter(
          client: LiveTumblrProviderActionClient(
            data: services.data, secrets: services.secrets, httpClient: stub))))
    func execute(
      _ action: String, payload: JSONRecord, suffix: String
    ) throws -> MarketplaceProviderActionBrokerResult {
      try broker.execute(
        context: owner,
        request: MarketplaceProviderActionBrokerRequest(
          appIdOrSlug: app.id, actionKey: action, payload: payload,
          connectionId: connection.id, idempotencyKey: "tumblr-\(suffix)"),
        now: fixedDate("2026-07-12T18:20:03Z"))
    }
    let account = try execute("tumblr_account_get", payload: [:], suffix: "account")
    try expect(
      account.adapterExecuted
        && account.execution.providerResult?["providerDataPersisted"] == .bool(false)
        && objectValue(account.transientProviderResult?["account"])?["name"]
          == .string("relay_account")
        && stub.requests.first?.headers["Authorization"] == "Bearer \(token)"
        && stub.requests.first?.headers["User-Agent"]?.contains("RelayConsole") == true,
      "Tumblr account data must be transient, bound, and use stable authenticated headers")
    let blog = try execute("tumblr_owned_blog_get", payload: [:], suffix: "blog")
    try expect(
      objectValue(blog.transientProviderResult?["blog"])?["descriptionText"]
        == .string("Notes about reliable agents .")
        && blog.transientProviderResult?["ownershipVerified"] == .bool(true),
      "Tumblr selected-blog result must contain useful sanitized description text")
    let posts = try execute(
      "tumblr_owned_blog_recent_posts_list",
      payload: ["limit": .number(10), "tag": .string("agents")], suffix: "posts")
    let firstPost = objectValue(arrayValue(posts.transientProviderResult?["posts"]).first)
    try expect(
      firstPost?["text"] == .string("A practical note about reliable agent loops.")
        && firstPost?["contentFormat"] == .string("npf")
        && posts.transientProviderResult?["nextPageFollowed"] == .bool(false)
        && posts.transientProviderResult?["providerRequestCount"] == .number(1)
        && stub.requests.last?.url.query?.contains("npf=true") == true
        && stub.requests.last?.url.query?.contains("limit=10") == true,
      "Tumblr posts must return useful NPF text with one bounded non-paginated request")
    let definitions = try services.providerActionPolicies.actionDefinitions(
      context: owner, appIdOrSlug: app.id)
    let listDefinition = try unwrap(
      definitions.first { $0.actionKey == "tumblr_owned_blog_recent_posts_list" },
      "missing Tumblr recent-post definition")
    do {
      _ = try TumblrProviderActionAdapter().execute(request: MarketplaceProviderActionAdapterRequest(
        context: owner, app: app, definition: listDefinition, permission: .allowed,
        payload: ["cursor": .string("forbidden")], approvalReference: nil,
        auditIdentity: ProviderExecutionAuditIdentity(
          workspaceId: workspace.id, actorId: owner.actorId, actorRole: "owner",
          agentId: nil, appId: app.id, appSlug: app.slug, connectionId: connection.id,
          installId: nil, approvalId: nil, dispatchId: nil, threadId: nil,
          source: "tumblr-payload-test", redactionStatus: "provider-content-not-stored"),
        idempotencyKey: "tumblr-cursor-rejected"))
      throw ServiceTestFailure("Tumblr cursor payload unexpectedly executed")
    } catch let error as MarketplaceProviderActionAdapterFailure {
      try expect(
        error.code == "tumblr_payload_not_supported",
        "Tumblr cursor input must fail at adapter boundary")
    }
    let persisted = try services.database.all(
      "SELECT execution_json AS value FROM marketplace_provider_action_executions")
      .compactMap { sqliteText($0["value"]) }.joined(separator: "\n")
    for forbidden in [
      token, "tumblr-live-refresh-sensitive", "relay_account", "Relay Blog",
      "reliable agent loops", "1234567890123456789",
    ] {
      try expect(
        !persisted.localizedCaseInsensitiveContains(forbidden),
        "Tumblr provider content leaked into persisted execution: \(forbidden)")
    }
    try expect(
      persisted.contains("providerDataPersisted") && persisted.contains("transientResultReturned"),
      "Tumblr persisted execution must retain explicit no-store audit evidence")
  }

