  private static func testTumblrRuntimeHarnessContract() throws {
    let root = FileManager.default.temporaryDirectory
      .appendingPathComponent("RelayConsoleTumblrRuntimeTests", isDirectory: true)
      .appendingPathComponent(UUID().uuidString, isDirectory: true)
    let services = try makeServices(root: root)
    let workspace = try unwrap(services.data.getAppState().activeWorkspace, "missing workspace")
    let owner = Self.context(
      roles: [.owner], workspaceId: workspace.id, correlationId: "tumblr-runtime-owner")
    let member = Self.context(
      roles: [.member], workspaceId: workspace.id, correlationId: "tumblr-runtime-member")
    let hermesHarness = try prepareInstalledHarness(services: services, key: .hermes)
    let openClawHarness = try prepareInstalledHarness(services: services, key: .openclaw)
    let hermesAgent = try services.data.createAgent(
      workspaceId: workspace.id, name: "Tumblr Hermes", harnessId: hermesHarness.id,
      externalAgentId: "tumblr-hermes", hermesProfileSlug: "tumblr-hermes",
      hermesHomePath: root.appendingPathComponent("tumblr-hermes-profile").path)
    let openClawState = root.appendingPathComponent("tumblr-openclaw-state")
    let openClawAgent = try services.data.createAgent(
      workspaceId: workspace.id, name: "Tumblr OpenClaw", harnessId: openClawHarness.id,
      externalAgentId: "tumblr-openclaw",
      workspaceFolderPath: root.appendingPathComponent("tumblr-openclaw-workspace").path,
      config: [
        "openclawAgentDir": .string(
          openClawState.appendingPathComponent("agents/tumblr-openclaw/agent").path),
        "openclawStateDir": .string(openClawState.path),
      ])
    let unrelatedAgent = try services.data.createAgent(
      workspaceId: workspace.id, name: "Tumblr Unrelated Hermes", harnessId: hermesHarness.id,
      externalAgentId: "tumblr-unrelated", hermesProfileSlug: "tumblr-unrelated",
      hermesHomePath: root.appendingPathComponent("tumblr-unrelated-profile").path)
    let foundation = try services.providerFoundations.registerTumblrFoundation(
      context: owner, now: fixedDate("2026-07-12T18:30:00Z"))
    let app = try unwrap(
      try services.data.getMarketplaceCatalogApp(
        workspaceId: workspace.id, appIdOrSlug: foundation.appId),
      "missing Tumblr runtime app")
    let connection = try services.providerConnections.saveTumblrRelayOwnedOAuthConnection(
      context: owner, appIdOrSlug: app.id,
      accessToken: "tumblr-runtime-access-sensitive",
      refreshToken: "tumblr-runtime-refresh-sensitive", accountName: "relay_account",
      selectedBlogUUID: "t:RelayOwnedBlog_123", selectedBlogName: "relay-blog",
      selectedBlogTitle: "Relay Blog", selectedBlogURL: "https://relay-blog.tumblr.com/",
      selectedBlogPrimary: true, selectedBlogType: "public",
      callbackURL: "https://relay.example.com/api/v1/oauth/tumblr/callback",
      grantedScopes: ProviderConnectionService.tumblrRelayOwnedOAuthScopes,
      accessExpiresAt: nil, stateVerified: true, now: fixedDate("2026-07-12T18:30:01Z"))
    func install(
      _ agent: AgentWithBinding, suffix: String, now: String
    ) throws -> MarketplaceInstallRecord {
      try services.marketplaceInstalls.createInstall(
        context: owner,
        request: installRequest(
          id: "minreq-tumblr-runtime-\(suffix)", workspaceId: workspace.id, app: app,
          connectionId: connection.id, agent: agent, roleId: app.roleManifest.primaryRole,
          selectedCapabilities: app.capabilities, riskAcknowledged: true), now: fixedDate(now))
    }
    let hermesInstall = try install(
      hermesAgent, suffix: "hermes", now: "2026-07-12T18:30:02Z")
    let openClawInstall = try install(
      openClawAgent, suffix: "openclaw", now: "2026-07-12T18:30:03Z")
    for pair in [(hermesInstall, hermesAgent), (openClawInstall, openClawAgent)] {
      _ = try services.providerActionPolicies.compilePolicyMap(
        context: owner, appIdOrSlug: app.id, preset: .readOnly,
        connectionId: connection.id, installId: pair.0.id, agentId: pair.1.id,
        now: fixedDate("2026-07-12T18:30:04Z"))
    }
    let expectedNames: Set<String> = [
      "relay_tumblr_get_account", "relay_tumblr_get_owned_blog",
      "relay_tumblr_list_owned_blog_recent_posts",
    ]
    let hermesSnapshot = try services.marketplaceRuntimeMounts.snapshot(
      context: member, agent: hermesAgent, now: fixedDate("2026-07-12T18:30:05Z"))
    let openClawSnapshot = try services.marketplaceRuntimeMounts.snapshot(
      context: member, agent: openClawAgent, now: fixedDate("2026-07-12T18:30:06Z"))
    for snapshot in [hermesSnapshot, openClawSnapshot] {
      let mounted = try unwrap(snapshot.apps.first, "missing Tumblr runtime mount")
      try expect(
        snapshot.apps.map(\.appSlug) == ["tumblr"] && snapshot.toolCount == 3
          && Set(mounted.tools.map(\.toolName)) == expectedNames
          && mounted.instructions.count <= 900
          && mounted.tools.allSatisfy { $0.readOnly && !$0.requiresApproval && !$0.autoExecutes }
          && !snapshot.rawProviderToolExposure,
        "Tumblr runtime must expose exactly three approval-free read wrappers")
      let prompt = try unwrap(
        services.marketplaceRuntimeMounts.renderPromptBlock(snapshot),
        "missing Tumblr runtime prompt")
      try expect(
