  private static func testThreadsBrokerAdapterContract() throws {
    final class Stub: ThreadsProviderHTTPClient, @unchecked Sendable {
      var requests: [ThreadsProviderHTTPRequest] = []; var ambiguousPublish = false
      func send(_ request: ThreadsProviderHTTPRequest) throws -> ThreadsProviderHTTPResponse {
        requests.append(request); let body: String
        switch (request.method, request.url.path) {
        case ("GET", "/me"):
          body = #"{"id":"th_123","username":"relay_threads","name":"Relay Threads","is_verified":true,"threads_biography":"Useful profile","threads_profile_picture_url":"https://example.invalid/p.jpg"}"#
        case ("GET", "/me/threads"):
          body = #"{"data":[{"id":"th_post_1","text":"Useful Threads update","media_type":"TEXT_POST","timestamp":"2026-07-12T12:00:00Z","permalink":"https://www.threads.net/@relay_threads/post/example","shortcode":"example","is_quote_post":false,"has_replies":false,"owner":{"id":"th_123"}}],"paging":{"next":"https://graph.threads.net/forbidden-next"}}"#
        case ("GET", "/th_post_1"):
          body = #"{"id":"th_post_1","text":"Useful Threads update","media_type":"TEXT_POST","timestamp":"2026-07-12T12:00:00Z","permalink":"https://www.threads.net/@relay_threads/post/example","shortcode":"example","is_quote_post":false,"has_replies":false,"owner":{"id":"th_123"}}"#
        case ("POST", "/me/threads"): body = #"{"id":"th_container_1"}"#
        case ("POST", "/me/threads_publish"):
          body = ambiguousPublish ? #"{"success":true}"# : #"{"id":"th_published_1"}"#
        default: throw MarketplaceProviderActionAdapterFailure(code: "threads_stub_unexpected_request", message: request.url.absoluteString)
        }
        return ThreadsProviderHTTPResponse(statusCode: 200, body: Data(body.utf8))
      }
    }
    let services = try makeServices(), workspace = try unwrap(services.data.getAppState().activeWorkspace, "missing workspace")
    let owner = Self.context(roles: [.owner], workspaceId: workspace.id, correlationId: "threads-broker-owner")
    let foundation = try services.providerFoundations.registerThreadsFoundation(context: owner, now: fixedDate("2026-07-12T16:20:00Z"))
    let app = try unwrap(try services.data.getMarketplaceCatalogApp(workspaceId: workspace.id, appIdOrSlug: foundation.appId), "missing Threads app")
    let token = "threads-live-token-sensitive"
    let connection = try services.providerConnections.saveThreadsRelayOwnedOAuthConnection(
      context: owner, appIdOrSlug: app.id, accessToken: token, profileId: "th_123",
      username: "relay_threads", displayName: "Relay Threads",
      callbackURL: "https://relay.example.com/api/v1/oauth/threads/callback",
      grantedScopes: ProviderConnectionService.threadsRelayOwnedOAuthScopes,
      tokenExpiresAt: nil, stateVerified: true, now: fixedDate("2026-07-12T16:20:01Z"))
    _ = try services.providerActionPolicies.compilePolicyMap(
      context: owner, appIdOrSlug: app.id, preset: .approvalRequired,
      connectionId: connection.id, now: fixedDate("2026-07-12T16:20:02Z"))
    let stub = Stub(), broker = MarketplaceProviderActionBrokerService(
      data: services.data, approvals: services.providerActionApprovals,
      auditSecurity: services.auditSecurity,
      adapter: RoutingMarketplaceProviderActionAdapter(
        threadsAdapter: ThreadsProviderActionAdapter(client: LiveThreadsProviderActionClient(
          data: services.data, secrets: services.secrets, httpClient: stub))))
    let profile = try broker.execute(context: owner, request: MarketplaceProviderActionBrokerRequest(
      appIdOrSlug: app.id, actionKey: "threads_profile_get", payload: [:], connectionId: connection.id,
      idempotencyKey: "threads-profile-read"), now: fixedDate("2026-07-12T16:20:03Z"))
    try expect(profile.adapterExecuted && objectValue(profile.execution.providerResult?["profile"])?["username"] == .string("relay_threads") && stub.requests.first?.headers["Authorization"] == "Bearer \(token)", "Threads profile read must use the bound profile and token")
    let list = try broker.execute(context: owner, request: MarketplaceProviderActionBrokerRequest(
      appIdOrSlug: app.id, actionKey: "threads_own_posts_list", payload: ["maxResults": .number(10)],
      connectionId: connection.id, idempotencyKey: "threads-list"), now: fixedDate("2026-07-12T16:20:04Z"))
    let listResult = try unwrap(list.execution.providerResult, "missing Threads posts")
    try expect(listResult["nextPageFollowed"] == .bool(false) && objectValue(arrayValue(listResult["posts"]).first)?["text"] == .string("Useful Threads update") && stub.requests.filter { $0.url.path == "/me/threads" }.count == 1, "Threads list must return useful text without pagination")
    let own = try broker.execute(context: owner, request: MarketplaceProviderActionBrokerRequest(
      appIdOrSlug: app.id, actionKey: "threads_own_post_get", payload: ["postId": .string("th_post_1")],
      connectionId: connection.id, idempotencyKey: "threads-get"), now: fixedDate("2026-07-12T16:20:05Z"))
    try expect(own.execution.providerResult?["ownershipVerified"] == .bool(true), "Threads exact post must verify ownership")
    let draft = try broker.execute(context: owner, request: MarketplaceProviderActionBrokerRequest(
      appIdOrSlug: app.id, actionKey: "threads_text_post_draft", payload: ["text": .string("A bounded draft")],
      connectionId: connection.id, idempotencyKey: "threads-draft"), now: fixedDate("2026-07-12T16:20:06Z"))
    try expect(draft.execution.providerResult?["providerCallMade"] == .bool(false) && stub.requests.count == 3, "Threads draft must remain local")
    let pending = try broker.execute(context: owner, request: MarketplaceProviderActionBrokerRequest(
      appIdOrSlug: app.id, actionKey: "threads_text_post_publish", payload: ["text": .string("Approved plain text")],
      connectionId: connection.id, idempotencyKey: "threads-pending"), now: fixedDate("2026-07-12T16:20:07Z"))
    try expect(!pending.adapterExecuted && pending.execution.status == .pendingApproval && stub.requests.count == 3, "Standard Threads publishing must not call the provider before approval")
    let approval = try unwrap(pending.approval, "missing Threads approval")
    do {
      _ = try broker.execute(context: owner, request: MarketplaceProviderActionBrokerRequest(
        appIdOrSlug: app.id, actionKey: "threads_text_post_publish", payload: ["text": .string("Changed")],
        connectionId: connection.id, approvalId: approval.id, idempotencyKey: "threads-changed"), now: fixedDate("2026-07-12T16:20:08Z"))
      throw ServiceTestFailure("Threads changed approval payload executed")
    } catch let denied as ServiceGuardResult { try expect(denied.reasonCode == .inputInvalid && stub.requests.count == 3, "Threads changed approval must fail before provider execution") }
    let approved = try services.providerActionApprovals.approve(context: owner, approvalId: approval.id, approvedPayload: ["text": .string("Approved plain text")], now: fixedDate("2026-07-12T16:20:09Z"))
    let executed = try broker.execute(context: owner, request: MarketplaceProviderActionBrokerRequest(
      appIdOrSlug: app.id, actionKey: "threads_text_post_publish", payload: ["text": .string("Approved plain text")],
      connectionId: connection.id, approvalId: approved.id, idempotencyKey: "threads-approved"), now: fixedDate("2026-07-12T16:20:10Z"))
    try expect(executed.execution.status == .succeeded && executed.execution.providerResult?["postId"] == .string("th_published_1") && stub.requests.filter { $0.method == "POST" }.count == 2, "Exact approved Threads publish must execute two provider requests once")
    _ = try services.providerActionPolicies.compilePolicyMap(context: owner, appIdOrSlug: app.id, preset: .allowDirectWrites, acknowledgeDangerousPolicy: true, connectionId: connection.id, now: fixedDate("2026-07-12T16:20:11Z"))
    let direct = try broker.execute(context: owner, request: MarketplaceProviderActionBrokerRequest(
      appIdOrSlug: app.id, actionKey: "threads_text_post_publish", payload: ["text": .string("Direct plain text")],
      connectionId: connection.id, idempotencyKey: "threads-direct"), now: fixedDate("2026-07-12T16:20:12Z"))
    try expect(direct.execution.status == .succeeded && stub.requests.filter { $0.method == "POST" }.count == 4, "Direct Threads publish must still route through the two-stage broker adapter")
    stub.ambiguousPublish = true
    let ambiguous = try broker.execute(context: owner, request: MarketplaceProviderActionBrokerRequest(
      appIdOrSlug: app.id, actionKey: "threads_text_post_publish", payload: ["text": .string("Ambiguous plain text")],
      connectionId: connection.id, idempotencyKey: "threads-ambiguous"), now: fixedDate("2026-07-12T16:20:13Z"))
    try expect(ambiguous.execution.status == .failed && ambiguous.execution.providerError?["providerErrorCode"] == .string("threads_ambiguous_publish_response") && stub.requests.filter { $0.method == "POST" }.count == 6, "Ambiguous Threads publish must fail after two requests without retry")
    let persisted = try services.database.all("SELECT execution_json AS value FROM marketplace_provider_action_executions").compactMap { sqliteText($0["value"]) }.joined(separator: "\n")
    try expect(!persisted.contains(token) && !persisted.localizedCaseInsensitiveContains("bearer "), "Threads execution persistence must redact authorization material")
  }

  private static func testMastodonBrokerAdapterContract() throws {
    final class Stub: MastodonProviderHTTPClient, @unchecked Sendable {
      var requests: [MastodonProviderHTTPRequest] = []; var ambiguousPublish = false
      func send(_ request: MastodonProviderHTTPRequest) throws -> MastodonProviderHTTPResponse {
        requests.append(request)
        let body: String
        switch (request.method, request.url.path) {
        case ("GET", "/api/v1/accounts/verify_credentials"):
          body = #"{"id":"109000000000000001","username":"relay","acct":"relay","display_name":"Relay","url":"https://social.example/@relay","avatar":"https://social.example/avatar.png"}"#
        case ("GET", "/api/v1/accounts/109000000000000001/statuses"):
          body = #"[{"id":"110000000000000001","content":"<p>A useful <strong>Mastodon</strong> update.</p>","created_at":"2026-07-12T12:00:00.000Z","url":"https://social.example/@relay/110000000000000001","visibility":"public","language":"en","spoiler_text":"","in_reply_to_id":null,"reblog":null}]"#
        case ("POST", "/api/v1/statuses"):
          body = ambiguousPublish
            ? #"{"created":true}"#
            : #"{"id":"110000000000000002","url":"https://social.example/@relay/110000000000000002","account":{"id":"109000000000000001"}}"#
        default:
          throw MarketplaceProviderActionAdapterFailure(
            code: "mastodon_stub_unexpected_request", message: request.url.absoluteString)
        }
        return MastodonProviderHTTPResponse(statusCode: 200, body: Data(body.utf8))
      }
    }
    let services = try makeServices()
    let workspace = try unwrap(services.data.getAppState().activeWorkspace, "missing workspace")
    let owner = Self.context(
      roles: [.owner], workspaceId: workspace.id, correlationId: "mastodon-broker-owner")
    let foundation = try services.providerFoundations.registerMastodonFoundation(
      context: owner, now: fixedDate("2026-07-12T16:40:00Z"))
    let app = try unwrap(
      try services.data.getMarketplaceCatalogApp(
        workspaceId: workspace.id, appIdOrSlug: foundation.appId), "missing Mastodon app")
    let accessToken = "mastodon-live-access-sensitive"
    let clientSecret = "mastodon-live-client-sensitive"
    let connection = try services.providerConnections.saveMastodonRelayOwnedOAuthConnection(
      context: owner, appIdOrSlug: app.id, clientSecret: clientSecret,
      accessToken: accessToken, clientId: "mastodon-client-1",
      instanceOrigin: "https://social.example", instanceDomain: "social.example",
      softwareVersion: "4.4.0", accountId: "109000000000000001", username: "relay",
      acct: "relay", displayName: "Relay", profileURL: "https://social.example/@relay",
      maxStatusCharacters: 500,
      callbackURL: "https://relay.example.com/api/v1/marketplace/oauth/mastodon/callback",
      grantedScopes: ProviderConnectionService.mastodonRelayOwnedOAuthScopes,
      stateVerified: true, instanceVerified: true, issuerVerified: true,
      serverOriginRestricted: true, now: fixedDate("2026-07-12T16:40:01Z"))
    _ = try services.providerActionPolicies.compilePolicyMap(
      context: owner, appIdOrSlug: app.id, preset: .approvalRequired,
      connectionId: connection.id, now: fixedDate("2026-07-12T16:40:02Z"))
    let stub = Stub()
    let broker = MarketplaceProviderActionBrokerService(
      data: services.data, approvals: services.providerActionApprovals,
      auditSecurity: services.auditSecurity,
      adapter: RoutingMarketplaceProviderActionAdapter(
        mastodonAdapter: MastodonProviderActionAdapter(
          client: LiveMastodonProviderActionClient(
            data: services.data, secrets: services.secrets, httpClient: stub))))
    let account = try broker.execute(
      context: owner, request: MarketplaceProviderActionBrokerRequest(
        appIdOrSlug: app.id, actionKey: "mastodon_account_get", payload: [:],
        connectionId: connection.id, idempotencyKey: "mastodon-account"),
      now: fixedDate("2026-07-12T16:40:03Z"))
    try expect(
      account.adapterExecuted
        && objectValue(account.execution.providerResult?["account"])?["username"] == .string("relay")
        && stub.requests.first?.url.host == "social.example"
        && stub.requests.first?.headers["Authorization"] == "Bearer \(accessToken)",
      "Mastodon account read must remain on the verified instance and bound account token")
    let list = try broker.execute(
      context: owner, request: MarketplaceProviderActionBrokerRequest(
        appIdOrSlug: app.id, actionKey: "mastodon_own_statuses_list",
        payload: ["maxResults": .number(10)], connectionId: connection.id,
        idempotencyKey: "mastodon-statuses"), now: fixedDate("2026-07-12T16:40:04Z"))
    let listResult = try unwrap(list.execution.providerResult, "missing Mastodon statuses")
    try expect(
      listResult["nextPageFollowed"] == .bool(false)
        && objectValue(arrayValue(listResult["statuses"]).first)?["text"]
          == .string("A useful Mastodon update.")
        && stub.requests[1].url.query?.contains("exclude_replies=true") == true
        && stub.requests[1].url.query?.contains("exclude_reblogs=true") == true,
      "Mastodon own-status read must normalize HTML and exclude replies/reblogs without paging")
    let draft = try broker.execute(
      context: owner, request: MarketplaceProviderActionBrokerRequest(
        appIdOrSlug: app.id, actionKey: "mastodon_text_status_draft",
        payload: ["text": .string("A bounded draft"), "visibility": .string("unlisted")],
        connectionId: connection.id, idempotencyKey: "mastodon-draft"),
      now: fixedDate("2026-07-12T16:40:05Z"))
    try expect(
      draft.execution.providerResult?["providerCallMade"] == .bool(false)
        && stub.requests.count == 2,
      "Mastodon draft must remain local")
    let pending = try broker.execute(
      context: owner, request: MarketplaceProviderActionBrokerRequest(
        appIdOrSlug: app.id, actionKey: "mastodon_text_status_publish",
        payload: ["text": .string("Approved status"), "visibility": .string("public"), "language": .string("en")],
        connectionId: connection.id, idempotencyKey: "mastodon-pending"),
      now: fixedDate("2026-07-12T16:40:06Z"))
    try expect(
      !pending.adapterExecuted && pending.execution.status == .pendingApproval
        && stub.requests.count == 2,
      "Standard Mastodon publishing must not call the instance before approval")
    let approval = try unwrap(pending.approval, "missing Mastodon approval")
    let approved = try services.providerActionApprovals.approve(
      context: owner, approvalId: approval.id,
      approvedPayload: ["text": .string("Approved status"), "visibility": .string("public"), "language": .string("en")],
      now: fixedDate("2026-07-12T16:40:07Z"))
    let executed = try broker.execute(
      context: owner, request: MarketplaceProviderActionBrokerRequest(
        appIdOrSlug: app.id, actionKey: "mastodon_text_status_publish",
        payload: ["text": .string("Approved status"), "visibility": .string("public"), "language": .string("en")],
        connectionId: connection.id, approvalId: approved.id,
        idempotencyKey: "mastodon-approved"), now: fixedDate("2026-07-12T16:40:08Z"))
    try expect(
      executed.execution.status == .succeeded
        && executed.execution.providerResult?["statusId"] == .string("110000000000000002")
        && stub.requests.last?.headers["Idempotency-Key"] == "mastodon-approved"
        && stub.requests.filter { $0.method == "POST" }.count == 1,
      "Approved Mastodon publish must execute once with the exact idempotency key")
    _ = try services.providerActionPolicies.compilePolicyMap(
      context: owner, appIdOrSlug: app.id, preset: .allowDirectWrites, acknowledgeDangerousPolicy: true,
      connectionId: connection.id, now: fixedDate("2026-07-12T16:40:09Z"))
    let direct = try broker.execute(
      context: owner, request: MarketplaceProviderActionBrokerRequest(
        appIdOrSlug: app.id, actionKey: "mastodon_text_status_publish",
        payload: ["text": .string("Direct status"), "visibility": .string("unlisted")],
        connectionId: connection.id, idempotencyKey: "mastodon-direct"),
      now: fixedDate("2026-07-12T16:40:10Z"))
    try expect(
      direct.execution.status == .succeeded
        && stub.requests.filter { $0.method == "POST" }.count == 2,
      "Direct Mastodon publishing must still route once through the broker adapter")
    stub.ambiguousPublish = true
    let ambiguous = try broker.execute(
      context: owner, request: MarketplaceProviderActionBrokerRequest(
        appIdOrSlug: app.id, actionKey: "mastodon_text_status_publish",
        payload: ["text": .string("Ambiguous status")], connectionId: connection.id,
        idempotencyKey: "mastodon-ambiguous"), now: fixedDate("2026-07-12T16:40:11Z"))
    try expect(
      ambiguous.execution.status == .failed
        && ambiguous.execution.providerError?["providerErrorCode"]
          == .string("mastodon_ambiguous_publish_response")
        && stub.requests.filter { $0.method == "POST" }.count == 3,
      "Ambiguous Mastodon publish must fail after one request without retry")
    let persisted = try services.database.all(
      "SELECT execution_json AS value FROM marketplace_provider_action_executions")
      .compactMap { sqliteText($0["value"]) }.joined(separator: "\n")
    try expect(
      !persisted.contains(accessToken) && !persisted.contains(clientSecret)
        && !persisted.localizedCaseInsensitiveContains("bearer "),
      "Mastodon execution persistence must redact both secrets and authorization material")
  }

  private static func testThreadsRuntimeHarnessContract() throws {
    let root = FileManager.default.temporaryDirectory
      .appendingPathComponent("RelayConsoleThreadsRuntimeTests", isDirectory: true)
      .appendingPathComponent(UUID().uuidString, isDirectory: true)
    let services = try makeServices(root: root)
    let workspace = try unwrap(services.data.getAppState().activeWorkspace, "missing workspace")
    let owner = Self.context(
      roles: [.owner], workspaceId: workspace.id, correlationId: "threads-runtime-owner")
    let member = Self.context(
      roles: [.member], workspaceId: workspace.id, correlationId: "threads-runtime-member")
    let hermesHarness = try prepareInstalledHarness(services: services, key: .hermes)
    let openClawHarness = try prepareInstalledHarness(services: services, key: .openclaw)
    let hermesAgent = try services.data.createAgent(
      workspaceId: workspace.id, name: "Threads Hermes", harnessId: hermesHarness.id,
      externalAgentId: "threads-hermes", hermesProfileSlug: "threads-hermes",
      hermesHomePath: root.appendingPathComponent("threads-hermes-profile").path)
    let openClawState = root.appendingPathComponent("threads-openclaw-state")
    let openClawAgent = try services.data.createAgent(
      workspaceId: workspace.id, name: "Threads OpenClaw", harnessId: openClawHarness.id,
      externalAgentId: "threads-openclaw",
      workspaceFolderPath: root.appendingPathComponent("threads-openclaw-workspace").path,
      config: [
        "openclawAgentDir": .string(
          openClawState.appendingPathComponent("agents/threads-openclaw/agent").path),
        "openclawStateDir": .string(openClawState.path),
      ])
    let unrelatedAgent = try services.data.createAgent(
      workspaceId: workspace.id, name: "Threads Unrelated Hermes", harnessId: hermesHarness.id,
      externalAgentId: "threads-unrelated", hermesProfileSlug: "threads-unrelated",
      hermesHomePath: root.appendingPathComponent("threads-unrelated-profile").path)
    let foundation = try services.providerFoundations.registerThreadsFoundation(
      context: owner, now: fixedDate("2026-07-12T16:30:00Z"))
    let app = try unwrap(
      try services.data.getMarketplaceCatalogApp(
        workspaceId: workspace.id, appIdOrSlug: foundation.appId), "missing Threads runtime app")
    let connection = try services.providerConnections.saveThreadsRelayOwnedOAuthConnection(
      context: owner, appIdOrSlug: app.id,
      accessToken: "threads-runtime-token-sensitive", profileId: "th_123",
      username: "relay_threads", displayName: "Relay Threads",
      callbackURL: "https://relay.example.com/api/v1/oauth/threads/callback",
      grantedScopes: ProviderConnectionService.threadsRelayOwnedOAuthScopes,
      tokenExpiresAt: nil, stateVerified: true, now: fixedDate("2026-07-12T16:30:01Z"))

    func install(_ agent: AgentWithBinding, suffix: String, now: String) throws -> MarketplaceInstallRecord {
      try services.marketplaceInstalls.createInstall(
        context: owner,
        request: installRequest(
          id: "minreq-threads-runtime-\(suffix)", workspaceId: workspace.id, app: app,
          connectionId: connection.id, agent: agent, roleId: app.roleManifest.primaryRole,
          selectedCapabilities: app.capabilities, riskAcknowledged: true), now: fixedDate(now))
    }
    let hermesInstall = try install(hermesAgent, suffix: "hermes", now: "2026-07-12T16:30:02Z")
    let openClawInstall = try install(openClawAgent, suffix: "openclaw", now: "2026-07-12T16:30:03Z")
    for pair in [(hermesInstall, hermesAgent), (openClawInstall, openClawAgent)] {
      _ = try services.providerActionPolicies.compilePolicyMap(
        context: owner, appIdOrSlug: app.id, preset: .approvalRequired,
        connectionId: connection.id, installId: pair.0.id, agentId: pair.1.id,
        now: fixedDate("2026-07-12T16:30:04Z"))
    }

    let expectedNames: Set<String> = [
      "relay_threads_get_profile", "relay_threads_list_own_posts",
      "relay_threads_get_own_post", "relay_threads_draft_text_post",
      "relay_threads_publish_text_post",
    ]
    let hermesSnapshot = try services.marketplaceRuntimeMounts.snapshot(
      context: member, agent: hermesAgent, now: fixedDate("2026-07-12T16:30:05Z"))
    let openClawSnapshot = try services.marketplaceRuntimeMounts.snapshot(
      context: member, agent: openClawAgent, now: fixedDate("2026-07-12T16:30:06Z"))
    for snapshot in [hermesSnapshot, openClawSnapshot] {
      let mounted = try unwrap(snapshot.apps.first, "missing Threads runtime mount")
      try expect(
        snapshot.apps.map(\.appSlug) == ["threads"] && snapshot.toolCount == 5
          && Set(mounted.tools.map(\.toolName)) == expectedNames
          && mounted.instructions.count <= 900
          && mounted.tools.filter(\.requiresApproval).map(\.toolName)
            == ["relay_threads_publish_text_post"]
          && !snapshot.rawProviderToolExposure,
        "Threads runtime must expose exactly five policy-scoped Relay wrappers")
      let prompt = try unwrap(
        services.marketplaceRuntimeMounts.renderPromptBlock(snapshot),
        "missing Threads runtime prompt")
      try expect(
        prompt.contains("App: Threads (threads)")
          && prompt.contains("5 brokered callable Relay tool")
          && prompt.contains("1 approval-required")
          && !prompt.contains("threads-runtime-token-sensitive")
          && !prompt.localizedCaseInsensitiveContains("bearer "),
        "Threads prompt must match the mounted wrapper surface without secret material")
    }
    let unrelated = try services.marketplaceRuntimeMounts.snapshot(
      context: member, agent: unrelatedAgent, now: fixedDate("2026-07-12T16:30:07Z"))
    try expect(
      unrelated.apps.isEmpty && unrelated.toolCount == 0,
      "Unrelated agents must not inherit Threads wrappers")

    func dispatch(_ agent: AgentWithBinding, suffix: String) -> RuntimeDispatchRequest {
      RuntimeDispatchRequest(
        dispatchId: "rtd-threads-\(suffix)", correlationId: "corr-threads-\(suffix)",
        threadId: "thr-threads-\(suffix)", messageId: "msg-threads-\(suffix)",
        sessionId: "rts-threads-\(suffix)", attempt: 1, agent: agent,
        runtimeBinding: agent.binding, harness: agent.harness,
        inputContent: "summarize my recent Threads posts", inputFormat: .plain,
        recentMessages: [], timeoutMs: 30_000, createdAt: "2026-07-12T16:30:08Z")
    }
    let hermesPath = URL(fileURLWithPath: try unwrap(
      hermesHarness.config["installPath"]?.string, "missing Hermes install path"))
    let openClawPath = URL(fileURLWithPath: try unwrap(
      openClawHarness.config["installPath"]?.string, "missing OpenClaw install path"))
    let hermesBridge = try services.harnessInstall.prepareMarketplaceRuntimeToolBridge(
      for: hermesAgent, request: dispatch(hermesAgent, suffix: "hermes"),
      harnessPath: hermesPath, mount: hermesSnapshot)
    let openClawBridge = try services.harnessInstall.prepareMarketplaceRuntimeToolBridge(
      for: openClawAgent, request: dispatch(openClawAgent, suffix: "openclaw"),
      harnessPath: openClawPath, mount: openClawSnapshot)
    try expect(
      hermesBridge.registeredToolNames == expectedNames
        && openClawBridge.registeredToolNames == expectedNames,
      "Hermes and OpenClaw must register every Threads wrapper")

    let read = try services.marketplaceRuntimeToolBridge.execute(
      toolName: "relay_threads_list_own_posts", payload: ["maxResults": .number(10)],
      runtime: MarketplaceRuntimeToolExecutionContext(
        agentId: hermesAgent.id, workspaceId: workspace.id, runtimeType: .hermes,
        dispatchId: "rtd-threads-call", threadId: "thr-threads-call",
        runtimeSessionId: "rts-threads-call", correlationId: "corr-threads-call"),
      now: fixedDate("2026-07-12T16:30:09Z"))
    try expect(
      read["adapterExecuted"] == .bool(true) && read["appSlug"] == .string("threads")
        && read["actionKey"] == .string("threads_own_posts_list")
        && objectValue(read["providerResult"])?["fakeAdapter"] == .bool(true),
      "Threads wrapper must execute through the broker adapter")
  }

