      grantedScopes: ProviderConnectionService.mastodonRelayOwnedOAuthScopes,
      stateVerified: true, instanceVerified: true, issuerVerified: true,
      serverOriginRestricted: true, now: fixedDate("2026-07-12T16:50:01Z"))
    func install(
      _ agent: AgentWithBinding, suffix: String, now: String
    ) throws -> MarketplaceInstallRecord {
      try services.marketplaceInstalls.createInstall(
        context: owner,
        request: installRequest(
          id: "minreq-mastodon-runtime-\(suffix)", workspaceId: workspace.id, app: app,
          connectionId: connection.id, agent: agent,
          roleId: app.roleManifest.primaryRole, selectedCapabilities: app.capabilities,
          riskAcknowledged: true), now: fixedDate(now))
    }
    let hermesInstall = try install(
      hermesAgent, suffix: "hermes", now: "2026-07-12T16:50:02Z")
    let openClawInstall = try install(
      openClawAgent, suffix: "openclaw", now: "2026-07-12T16:50:03Z")
    for pair in [(hermesInstall, hermesAgent), (openClawInstall, openClawAgent)] {
      _ = try services.providerActionPolicies.compilePolicyMap(
        context: owner, appIdOrSlug: app.id, preset: .approvalRequired,
        connectionId: connection.id, installId: pair.0.id, agentId: pair.1.id,
        now: fixedDate("2026-07-12T16:50:04Z"))
    }
    let expectedNames: Set<String> = [
      "relay_mastodon_get_account", "relay_mastodon_list_own_statuses",
      "relay_mastodon_draft_text_status", "relay_mastodon_publish_text_status",
    ]
    let hermesSnapshot = try services.marketplaceRuntimeMounts.snapshot(
      context: member, agent: hermesAgent, now: fixedDate("2026-07-12T16:50:05Z"))
    let openClawSnapshot = try services.marketplaceRuntimeMounts.snapshot(
      context: member, agent: openClawAgent, now: fixedDate("2026-07-12T16:50:06Z"))
    for snapshot in [hermesSnapshot, openClawSnapshot] {
      let mounted = try unwrap(snapshot.apps.first, "missing Mastodon runtime mount")
      try expect(
        snapshot.apps.map(\.appSlug) == ["mastodon"] && snapshot.toolCount == 4
          && Set(mounted.tools.map(\.toolName)) == expectedNames
          && mounted.instructions.count <= 900
          && mounted.tools.filter(\.requiresApproval).map(\.toolName)
            == ["relay_mastodon_publish_text_status"]
          && !snapshot.rawProviderToolExposure,
        "Mastodon runtime must expose exactly four policy-scoped Relay wrappers")
      let prompt = try unwrap(
        services.marketplaceRuntimeMounts.renderPromptBlock(snapshot),
        "missing Mastodon runtime prompt")
      try expect(
        prompt.contains("App: Mastodon (mastodon)")
          && prompt.contains("4 brokered callable Relay tool")
          && prompt.contains("1 approval-required")
          && !prompt.contains(clientSecret) && !prompt.contains(accessToken)
          && !prompt.localizedCaseInsensitiveContains("bearer "),
        "Mastodon prompt must match the mounted wrapper surface without secret material")
    }
    let unrelated = try services.marketplaceRuntimeMounts.snapshot(
      context: member, agent: unrelatedAgent, now: fixedDate("2026-07-12T16:50:07Z"))
    try expect(
      unrelated.apps.isEmpty && unrelated.toolCount == 0,
      "Unrelated agents must not inherit Mastodon wrappers")
    func dispatch(_ agent: AgentWithBinding, suffix: String) -> RuntimeDispatchRequest {
      RuntimeDispatchRequest(
        dispatchId: "rtd-mastodon-\(suffix)", correlationId: "corr-mastodon-\(suffix)",
        threadId: "thr-mastodon-\(suffix)", messageId: "msg-mastodon-\(suffix)",
        sessionId: "rts-mastodon-\(suffix)", attempt: 1, agent: agent,
        runtimeBinding: agent.binding, harness: agent.harness,
        inputContent: "summarize my recent Mastodon statuses", inputFormat: .plain,
        recentMessages: [], timeoutMs: 30_000, createdAt: "2026-07-12T16:50:08Z")
    }
    let hermesPath = URL(fileURLWithPath: try unwrap(
      hermesHarness.config["installPath"]?.string, "missing Hermes install path"))
    let openClawPath = URL(fileURLWithPath: try unwrap(
      openClawHarness.config["installPath"]?.string, "missing OpenClaw install path"))
    let hermesBridge = try services.harnessInstall.prepareMarketplaceRuntimeToolBridge(
      for: hermesAgent, request: dispatch(hermesAgent, suffix: "hermes"),
      harnessPath: hermesPath, mount: hermesSnapshot)
    let openClawBridge = try services.harnessInstall.prepareMarketplaceRuntimeToolBridge(
      for: openClawAgent, request: dispatch(openClawAgent, suffix: "openclaw"),
      harnessPath: openClawPath, mount: openClawSnapshot)
    try expect(
      hermesBridge.registeredToolNames == expectedNames
        && openClawBridge.registeredToolNames == expectedNames,
      "Hermes and OpenClaw must register every Mastodon wrapper")
    let read = try services.marketplaceRuntimeToolBridge.execute(
      toolName: "relay_mastodon_list_own_statuses", payload: ["maxResults": .number(10)],
      runtime: MarketplaceRuntimeToolExecutionContext(
        agentId: hermesAgent.id, workspaceId: workspace.id, runtimeType: .hermes,
        dispatchId: "rtd-mastodon-call", threadId: "thr-mastodon-call",
        runtimeSessionId: "rts-mastodon-call", correlationId: "corr-mastodon-call"),
      now: fixedDate("2026-07-12T16:50:09Z"))
    try expect(
      read["adapterExecuted"] == .bool(true) && read["appSlug"] == .string("mastodon")
        && read["actionKey"] == .string("mastodon_own_statuses_list")
        && objectValue(read["providerResult"])?["fakeAdapter"] == .bool(true),
      "Mastodon wrapper must execute through the broker adapter")
  }

