  private static func testMastodonPublicNetworkBoundary() throws {
    for value: UInt32 in [
      0x00000000, 0x0a000001, 0x64400001, 0x7f000001, 0xa9fe0001,
      0xac100001, 0xc0000001, 0xc0000201, 0xc0a80001, 0xc6120001,
      0xc6336401, 0xcb007101, 0xe0000001,
    ] {
      try expect(
        !MastodonPublicNetworkBoundary.isPublicIPv4(value),
        "Mastodon must reject non-public IPv4 address \(String(value, radix: 16))")
    }
    try expect(
      MastodonPublicNetworkBoundary.isPublicIPv4(0x08080808),
      "Mastodon public-address classifier must retain public IPv4")
    let nonPublicIPv6: [[UInt8]] = [
      [UInt8](repeating: 0, count: 16),
      [UInt8](repeating: 0, count: 15) + [1],
      [0xfc] + [UInt8](repeating: 0, count: 15),
      [0xfe, 0x80] + [UInt8](repeating: 0, count: 14),
      [0xff] + [UInt8](repeating: 0, count: 15),
      [0x20, 0x01, 0x0d, 0xb8] + [UInt8](repeating: 0, count: 12),
    ]
    for bytes in nonPublicIPv6 {
      try expect(
        !MastodonPublicNetworkBoundary.isPublicIPv6(bytes),
        "Mastodon must reject non-public IPv6 address classes")
    }
    do {
      try MastodonPublicNetworkBoundary.requirePublicDNSHost("127.0.0.1")
      throw ServiceTestFailure("Mastodon accepted an IPv4 literal instance")
    } catch let failure as MarketplaceProviderActionAdapterFailure {
      try expect(
        failure.code == "mastodon_instance_ip_literal_rejected",
        "Mastodon IPv4 literal rejection must fail with the exact code")
    }
    do {
      try MastodonPublicNetworkBoundary.requirePublicDNSHost("::1")
      throw ServiceTestFailure("Mastodon accepted an IPv6 literal instance")
    } catch let failure as MarketplaceProviderActionAdapterFailure {
      try expect(
        failure.code == "mastodon_instance_ip_literal_rejected",
        "Mastodon IPv6 literal rejection must fail with the exact code")
    }
  }

  private static func testInstagramBusinessProviderFoundationContract() throws {
    let services = try makeServices()
    let workspace = try unwrap(services.data.getAppState().activeWorkspace, "missing workspace")
    let owner = Self.context(
      roles: [.owner], workspaceId: workspace.id,
      correlationId: "instagram-business-foundation-owner")
    let foundation = try services.providerFoundations.registerInstagramBusinessFoundation(
      context: owner, now: fixedDate("2026-07-12T15:10:00Z"))
    let exactActions: Set<String> = [
      "instagram_business_account_get", "instagram_business_own_media_list",
      "instagram_business_own_media_get",
    ]
    try expect(
      foundation.appSlug == "instagram-business"
        && foundation.connectionMode == "relay-owned-instagram-login-professional-account"
        && foundation.credentialOwnership == .relayOwned
        && !foundation.userOwnedCredentialsRequired
        && foundation.supportedPolicyPresets == [.readOnly, .blocked]
        && foundation.defaultPolicyPreset == .readOnly,
      "Instagram Business foundation must be Relay-owned and read-only")
    try expect(
      Set(foundation.actions.map(\.actionKey)) == exactActions
        && foundation.actions.count == 3
        && foundation.actions.allSatisfy {
          $0.kind == .read && $0.defaultPermission == .allowed
            && $0.policyPermission == .allowed
            && $0.requiredScopes == ["instagram_business_basic"]
        },
      "Instagram Business must register exactly three exact-scope read actions")
    try expect(
      Set(foundation.agentFacingWrapperToolNames) == [
        "relay_instagram_business_get_account",
        "relay_instagram_business_list_own_media",
        "relay_instagram_business_get_own_media",
      ],
      "Instagram Business actions must map to exactly three stable Relay wrappers")
    try expect(
      Set(foundation.credentials.map(\.fieldKey)) == [
        "instagram_business_user_access_token",
        "instagram_business_professional_account",
      ],
      "Instagram Business foundation must expose one secret and one account binding")
    let catalog = try services.applications.catalogSnapshot(
      context: owner, selectedAppId: "instagram-business")
    let app = try unwrap(
      catalog.apps.first { $0.slug == "instagram-business" }, "missing Instagram Business app")
    for preset in [MarketplaceActionPolicyPreset.approvalRequired, .allowDirectWrites, .readOnly] {
      let policy = try services.providerActionPolicies.compilePolicyMap(
        context: owner, appIdOrSlug: app.id, preset: preset,
        acknowledgeDangerousPolicy: preset == .allowDirectWrites)
      try expect(
        Set(policy.permissions.keys) == exactActions
          && policy.permissions.values.allSatisfy { $0 == .allowed },
        "Every non-blocked Instagram Business preset must remain read-only allowed")
    }
    let blocked = try services.providerActionPolicies.compilePolicyMap(
      context: owner, appIdOrSlug: app.id, preset: .blocked)
    try expect(
      Set(blocked.permissions.keys) == exactActions
        && blocked.permissions.values.allSatisfy { $0 == .blocked },
      "No access must block every Instagram Business action")
    let definitions = try services.providerActionPolicies.actionDefinitions(
      context: owner, appIdOrSlug: app.id)
    let dump = definitions.map(\.actionKey).joined(separator: "\n")
    for forbidden in [
      "publish", "comment", "message", "insight", "ad_", "tagging", "discover",
      "download", "webhook", "delete", "pagination", "raw",
    ] {
      try expect(
        !dump.contains(forbidden),
        "Deferred Instagram Business action leaked into definitions: \(forbidden)")
    }
  }

  private static func testInstagramBusinessBrokerAdapterContract() throws {
    final class Stub: InstagramBusinessProviderHTTPClient, @unchecked Sendable {
      var urls: [URL] = []
      var authorizationHeaders: [String] = []
      func get(
        url: URL, headers: [String: String]
      ) throws -> InstagramBusinessProviderHTTPResponse {
        urls.append(url)
        authorizationHeaders.append(headers["Authorization"] ?? "")
        let body: String
        switch url.path {
        case "/me":
          body = #"{"id":"ig_123","username":"relay_business","name":"Relay Business","account_type":"BUSINESS","media_count":2,"profile_picture_url":"https://example.invalid/profile.jpg"}"#
        case "/me/media":
          body = #"{"data":[{"id":"ig_media_1","caption":"Useful launch image","media_type":"IMAGE","media_product_type":"FEED","timestamp":"2026-07-12T12:00:00Z","permalink":"https://www.instagram.com/p/example/"}],"paging":{"next":"https://graph.instagram.com/forbidden-next"}}"#
        case "/ig_media_1":
          body = #"{"id":"ig_media_1","caption":"Useful launch image","media_type":"IMAGE","media_product_type":"FEED","timestamp":"2026-07-12T12:00:00Z","permalink":"https://www.instagram.com/p/example/","owner":{"id":"ig_123"}}"#
        default:
          throw MarketplaceProviderActionAdapterFailure(
            code: "instagram_business_stub_unexpected_request", message: url.absoluteString)
        }
        return InstagramBusinessProviderHTTPResponse(statusCode: 200, body: Data(body.utf8))
      }
    }

    let services = try makeServices()
    let workspace = try unwrap(services.data.getAppState().activeWorkspace, "missing workspace")
    let owner = Self.context(
      roles: [.owner], workspaceId: workspace.id,
      correlationId: "instagram-business-broker-owner")
    let foundation = try services.providerFoundations.registerInstagramBusinessFoundation(
      context: owner, now: fixedDate("2026-07-12T15:20:00Z"))
    let app = try unwrap(
      try services.data.getMarketplaceCatalogApp(
        workspaceId: workspace.id, appIdOrSlug: foundation.appId),
      "missing Instagram Business app")
    let token = "instagram-business-live-token-sensitive"
    let connection = try services.providerConnections.saveInstagramBusinessRelayOwnedOAuthConnection(
      context: owner, appIdOrSlug: app.id, accessToken: token,
      professionalAccountId: "ig_123", username: "relay_business", accountType: "BUSINESS",
      callbackURL: "https://relay.example.com/api/v1/oauth/instagram-business/callback",
      grantedScopes: ProviderConnectionService.instagramBusinessRelayOwnedOAuthScopes,
      accessExpiresAt: nil, stateVerified: true,
      now: fixedDate("2026-07-12T15:20:01Z"))
    _ = try services.providerActionPolicies.compilePolicyMap(
      context: owner, appIdOrSlug: app.id, preset: .readOnly,
      connectionId: connection.id, now: fixedDate("2026-07-12T15:20:02Z"))
    let stub = Stub()
    let broker = MarketplaceProviderActionBrokerService(
      data: services.data, approvals: services.providerActionApprovals,
      auditSecurity: services.auditSecurity,
      adapter: RoutingMarketplaceProviderActionAdapter(
        instagramBusinessAdapter: InstagramBusinessProviderActionAdapter(
          client: LiveInstagramBusinessProviderActionClient(
            data: services.data, secrets: services.secrets, httpClient: stub))))

    let account = try broker.execute(
      context: owner,
      request: MarketplaceProviderActionBrokerRequest(
        appIdOrSlug: app.id, actionKey: "instagram_business_account_get", payload: [:],
        connectionId: connection.id, idempotencyKey: "instagram-account-read"),
      now: fixedDate("2026-07-12T15:20:03Z"))
    try expect(
      account.adapterExecuted
        && account.execution.providerResult?["providerRequestCount"] == .number(1)
        && objectValue(account.execution.providerResult?["account"])?["username"]
          == .string("relay_business"),
      "Instagram account read must execute once for the bound professional account")

    let list = try broker.execute(
      context: owner,
      request: MarketplaceProviderActionBrokerRequest(
        appIdOrSlug: app.id, actionKey: "instagram_business_own_media_list",
        payload: ["maxResults": .number(10)], connectionId: connection.id,
        idempotencyKey: "instagram-media-list"),
      now: fixedDate("2026-07-12T15:20:04Z"))
    let listResult = try unwrap(list.execution.providerResult, "missing Instagram media list")
    try expect(
      listResult["resultCount"] == .number(1)
        && listResult["nextPageFollowed"] == .bool(false)
        && objectValue(arrayValue(listResult["media"]).first)?["caption"]
          == .string("Useful launch image")
        && stub.urls.filter { $0.path == "/me/media" }.count == 1,
      "Instagram media list must return useful owned-media fields without following paging")

    let item = try broker.execute(
      context: owner,
      request: MarketplaceProviderActionBrokerRequest(
        appIdOrSlug: app.id, actionKey: "instagram_business_own_media_get",
        payload: ["mediaId": .string("ig_media_1")], connectionId: connection.id,
        idempotencyKey: "instagram-media-get"),
      now: fixedDate("2026-07-12T15:20:05Z"))
    try expect(
      item.execution.providerResult?["ownershipVerified"] == .bool(true)
        && stub.authorizationHeaders.allSatisfy { $0 == "Bearer \(token)" }
        && stub.urls.count == 3,
      "Instagram exact-media read must verify owner and use one request")

    let definitions = try services.data.listMarketplaceProviderActionDefinitions(
      workspaceId: workspace.id, appId: app.id)
    let listDefinition = try unwrap(
      definitions.first { $0.actionKey == "instagram_business_own_media_list" },
      "missing Instagram media-list definition")
    let directAdapter = InstagramBusinessProviderActionAdapter()
    let audit = ProviderExecutionAuditIdentity(
      workspaceId: workspace.id, actorId: owner.actorId, actorRole: "owner", agentId: nil,
      appId: app.id, appSlug: app.slug, connectionId: connection.id, installId: nil,
      approvalId: nil, dispatchId: nil, threadId: nil, source: "instagram-payload-test",
      redactionStatus: "private-state-excluded")
    do {
      _ = try directAdapter.execute(request: MarketplaceProviderActionAdapterRequest(
        context: owner, app: app, definition: listDefinition, permission: .allowed,
        payload: ["cursor": .string("forbidden")], approvalReference: nil,
        auditIdentity: audit, idempotencyKey: "instagram-cursor-rejected"))
      throw ServiceTestFailure("Instagram cursor payload unexpectedly executed")
    } catch let error as MarketplaceProviderActionAdapterFailure {
      try expect(
        error.code == "instagram_business_payload_not_supported",
        "Instagram arbitrary cursor payload must fail at the adapter boundary")
    }
    let dump = try services.data.listMarketplaceProviderActionExecutions(workspaceId: workspace.id)
      .compactMap(\.providerResult)
      .map { String(data: try JSONEncoder().encode($0), encoding: .utf8) ?? "" }
      .joined(separator: "\n")
    try expect(!dump.contains(token), "Instagram broker results must not persist the access token")
  }

  private static func testInstagramBusinessRuntimeHarnessContract() throws {
    let root = FileManager.default.temporaryDirectory
      .appendingPathComponent("RelayConsoleInstagramBusinessRuntimeTests", isDirectory: true)
      .appendingPathComponent(UUID().uuidString, isDirectory: true)
    let services = try makeServices(root: root)
    let workspace = try unwrap(services.data.getAppState().activeWorkspace, "missing workspace")
    let owner = Self.context(
      roles: [.owner], workspaceId: workspace.id,
      correlationId: "instagram-business-runtime-owner")
    let member = Self.context(
      roles: [.member], workspaceId: workspace.id,
      correlationId: "instagram-business-runtime-member")
    let hermesHarness = try prepareInstalledHarness(services: services, key: .hermes)
    let openClawHarness = try prepareInstalledHarness(services: services, key: .openclaw)
    let hermesAgent = try services.data.createAgent(
      workspaceId: workspace.id, name: "Instagram Business Hermes",
      harnessId: hermesHarness.id, externalAgentId: "instagram-business-hermes",
      hermesProfileSlug: "instagram-business-hermes",
      hermesHomePath: root.appendingPathComponent("instagram-business-hermes-profile").path)
    let openClawState = root.appendingPathComponent("instagram-business-openclaw-state")
    let openClawAgent = try services.data.createAgent(
      workspaceId: workspace.id, name: "Instagram Business OpenClaw",
      harnessId: openClawHarness.id, externalAgentId: "instagram-business-openclaw",
      workspaceFolderPath: root.appendingPathComponent("instagram-business-openclaw-workspace").path,
      config: [
        "openclawAgentDir": .string(
          openClawState.appendingPathComponent("agents/instagram-business-openclaw/agent").path),
        "openclawStateDir": .string(openClawState.path),
      ])
    let unrelatedAgent = try services.data.createAgent(
      workspaceId: workspace.id, name: "Instagram Unrelated Hermes",
      harnessId: hermesHarness.id, externalAgentId: "instagram-business-unrelated",
      hermesProfileSlug: "instagram-business-unrelated",
      hermesHomePath: root.appendingPathComponent("instagram-business-unrelated-profile").path)
    let foundation = try services.providerFoundations.registerInstagramBusinessFoundation(
      context: owner, now: fixedDate("2026-07-12T15:30:00Z"))
    let app = try unwrap(
      try services.data.getMarketplaceCatalogApp(
        workspaceId: workspace.id, appIdOrSlug: foundation.appId),
      "missing Instagram Business runtime app")
    let connection = try services.providerConnections.saveInstagramBusinessRelayOwnedOAuthConnection(
      context: owner, appIdOrSlug: app.id,
      accessToken: "instagram-business-runtime-token-sensitive",
      professionalAccountId: "ig_123", username: "relay_business", accountType: "BUSINESS",
      callbackURL: "https://relay.example.com/api/v1/oauth/instagram-business/callback",
      grantedScopes: ProviderConnectionService.instagramBusinessRelayOwnedOAuthScopes,
      accessExpiresAt: nil, stateVerified: true,
      now: fixedDate("2026-07-12T15:30:01Z"))

    func install(
      _ agent: AgentWithBinding, suffix: String, now: String
    ) throws -> MarketplaceInstallRecord {
      try services.marketplaceInstalls.createInstall(
        context: owner,
        request: installRequest(
          id: "minreq-instagram-business-runtime-\(suffix)", workspaceId: workspace.id,
          app: app, connectionId: connection.id, agent: agent,
          roleId: app.roleManifest.primaryRole, selectedCapabilities: app.capabilities,
          riskAcknowledged: true), now: fixedDate(now))
    }
    let hermesInstall = try install(
      hermesAgent, suffix: "hermes", now: "2026-07-12T15:30:02Z")
    let openClawInstall = try install(
      openClawAgent, suffix: "openclaw", now: "2026-07-12T15:30:03Z")
    for pair in [(hermesInstall, hermesAgent), (openClawInstall, openClawAgent)] {
      _ = try services.providerActionPolicies.compilePolicyMap(
        context: owner, appIdOrSlug: app.id, preset: .readOnly,
        connectionId: connection.id, installId: pair.0.id, agentId: pair.1.id,
        now: fixedDate("2026-07-12T15:30:04Z"))
    }

    let expectedNames: Set<String> = [
      "relay_instagram_business_get_account", "relay_instagram_business_list_own_media",
      "relay_instagram_business_get_own_media",
    ]
    let hermesSnapshot = try services.marketplaceRuntimeMounts.snapshot(
      context: member, agent: hermesAgent, now: fixedDate("2026-07-12T15:30:05Z"))
    let openClawSnapshot = try services.marketplaceRuntimeMounts.snapshot(
      context: member, agent: openClawAgent, now: fixedDate("2026-07-12T15:30:06Z"))
    for snapshot in [hermesSnapshot, openClawSnapshot] {
      let mounted = try unwrap(snapshot.apps.first, "missing Instagram Business runtime mount")
      try expect(
        snapshot.apps.map(\.appSlug) == ["instagram-business"] && snapshot.toolCount == 3
          && Set(mounted.tools.map(\.toolName)) == expectedNames
          && mounted.instructions.count <= 900
          && mounted.tools.allSatisfy { !$0.requiresApproval }
          && !snapshot.rawProviderToolExposure,
        "Instagram Business runtime must expose exactly three approval-free read wrappers")
      let prompt = try unwrap(
        services.marketplaceRuntimeMounts.renderPromptBlock(snapshot),
        "missing Instagram Business runtime prompt")
      try expect(
        prompt.contains("App: Instagram Business (instagram-business)")
          && prompt.contains("3 brokered callable Relay tool")
          && !prompt.contains("instagram_business_content_publish")
          && !prompt.contains("instagram-business-runtime-token-sensitive")
          && !prompt.localizedCaseInsensitiveContains("bearer "),
        "Instagram Business prompt must match the mounted read-only surface")
    }
    let unrelated = try services.marketplaceRuntimeMounts.snapshot(
      context: member, agent: unrelatedAgent, now: fixedDate("2026-07-12T15:30:07Z"))
    try expect(
      unrelated.apps.isEmpty && unrelated.toolCount == 0,
      "Unrelated agents must not inherit Instagram Business wrappers")

    func dispatch(_ agent: AgentWithBinding, suffix: String) -> RuntimeDispatchRequest {
      RuntimeDispatchRequest(
        dispatchId: "rtd-instagram-business-\(suffix)",
        correlationId: "corr-instagram-business-\(suffix)",
        threadId: "thr-instagram-business-\(suffix)",
        messageId: "msg-instagram-business-\(suffix)",
        sessionId: "rts-instagram-business-\(suffix)", attempt: 1, agent: agent,
        runtimeBinding: agent.binding, harness: agent.harness,
        inputContent: "summarize recent owned Instagram media", inputFormat: .plain,
        recentMessages: [], timeoutMs: 30_000, createdAt: "2026-07-12T15:30:08Z")
    }
    let hermesPath = URL(fileURLWithPath: try unwrap(
      hermesHarness.config["installPath"]?.string, "missing Hermes install path"))
    let openClawPath = URL(fileURLWithPath: try unwrap(
      openClawHarness.config["installPath"]?.string, "missing OpenClaw install path"))
    let hermesBridge = try services.harnessInstall.prepareMarketplaceRuntimeToolBridge(
      for: hermesAgent, request: dispatch(hermesAgent, suffix: "hermes"),
      harnessPath: hermesPath, mount: hermesSnapshot)
    let openClawBridge = try services.harnessInstall.prepareMarketplaceRuntimeToolBridge(
      for: openClawAgent, request: dispatch(openClawAgent, suffix: "openclaw"),
      harnessPath: openClawPath, mount: openClawSnapshot)
    try expect(
      hermesBridge.registeredToolNames == expectedNames
        && openClawBridge.registeredToolNames == expectedNames,
      "Hermes and OpenClaw must register every Instagram Business wrapper")

    let read = try services.marketplaceRuntimeToolBridge.execute(
      toolName: "relay_instagram_business_list_own_media",
      payload: ["maxResults": .number(10)],
      runtime: MarketplaceRuntimeToolExecutionContext(
        agentId: hermesAgent.id, workspaceId: workspace.id, runtimeType: .hermes,
        dispatchId: "rtd-instagram-business-call", threadId: "thr-instagram-business-call",
        runtimeSessionId: "rts-instagram-business-call",
        correlationId: "corr-instagram-business-call"),
      now: fixedDate("2026-07-12T15:30:09Z"))
    try expect(
      read["adapterExecuted"] == .bool(true)
        && read["appSlug"] == .string("instagram-business")
        && read["actionKey"] == .string("instagram_business_own_media_list")
        && objectValue(read["providerResult"])?["fakeAdapter"] == .bool(true),
      "Instagram Business wrapper must execute through the broker adapter")
  }

  private static func testInstagramBusinessAgentAuthorityContract() throws {
    let services = try makeServices()
    let workspace = try unwrap(services.data.getAppState().activeWorkspace, "missing workspace")
    let owner = Self.context(
      roles: [.owner], workspaceId: workspace.id,
      correlationId: "instagram-business-authority-owner")
    let harness = try services.data.upsertHarness(
      runtimeType: .hermes, displayName: "Instagram Business Authority Hermes",
      mode: .appManaged, config: [:])
    let assignedAgent = try services.data.createAgent(
      workspaceId: workspace.id, name: "Assigned Instagram Business Agent",
      harnessId: harness.id, externalAgentId: "instagram-business-authority-assigned",
      hermesProfileSlug: "instagram-business-authority-assigned")
    let unrelatedAgent = try services.data.createAgent(
      workspaceId: workspace.id, name: "Unrelated Instagram Business Agent",
      harnessId: harness.id, externalAgentId: "instagram-business-authority-unrelated",
      hermesProfileSlug: "instagram-business-authority-unrelated")
    let foundation = try services.providerFoundations.registerInstagramBusinessFoundation(
      context: owner, now: fixedDate("2026-07-12T15:40:00Z"))
    let app = try unwrap(
      try services.data.getMarketplaceCatalogApp(
        workspaceId: workspace.id, appIdOrSlug: foundation.appId),
      "missing Instagram Business authority app")
    let beforeConnection = try services.marketplaceInstalls.snapshot(
      context: owner, appIdOrSlug: app.id, now: fixedDate("2026-07-12T15:40:01Z"))
    try expect(
      beforeConnection.compatibleAgents.map(\.agentId).contains(assignedAgent.id)
        && beforeConnection.compatibleAgents.map(\.agentId).contains(unrelatedAgent.id),
      "Instagram Business agent rows must remain available before a connection exists")
    let connection = try services.providerConnections.saveInstagramBusinessRelayOwnedOAuthConnection(
      context: owner, appIdOrSlug: app.id,
      accessToken: "instagram-business-authority-token-sensitive",
      professionalAccountId: "ig_123", username: "relay_business", accountType: "BUSINESS",
      callbackURL: "https://relay.example.com/api/v1/oauth/instagram-business/callback",
      grantedScopes: ProviderConnectionService.instagramBusinessRelayOwnedOAuthScopes,
      accessExpiresAt: nil, stateVerified: true,
      now: fixedDate("2026-07-12T15:40:02Z"))
    let install = try services.marketplaceInstalls.createInstall(
      context: owner,
      request: installRequest(
        id: "minreq-instagram-business-authority", workspaceId: workspace.id, app: app,
        connectionId: connection.id, agent: assignedAgent,
        roleId: app.roleManifest.primaryRole, selectedCapabilities: app.capabilities,
        riskAcknowledged: true), now: fixedDate("2026-07-12T15:40:03Z"))
    for (index, preset) in [
      MarketplaceActionPolicyPreset.readOnly, MarketplaceActionPolicyPreset.blocked,
    ].enumerated() {
      let map = try services.providerActionPolicies.compilePolicyMap(
        context: owner, appIdOrSlug: app.id, preset: preset,
        acknowledgeDangerousPolicy: preset == .allowDirectWrites,
        connectionId: connection.id, installId: install.id, agentId: assignedAgent.id,
        now: fixedDate("2026-07-12T15:40:0\(4 + index)Z"))
      let snapshot = try services.marketplaceRuntimeMounts.snapshot(
        context: owner, agent: assignedAgent,
        now: fixedDate("2026-07-12T15:40:0\(6 + index)Z"))
      let mounted = try unwrap(snapshot.apps.first, "missing scoped Instagram Business mount")
      try expect(
        map.policyPreset == preset && mounted.tools.count == (preset == .readOnly ? 3 : 0),
        "Instagram Business authority \(preset.rawValue) must refresh the scoped read surface")
      let unrelated = try services.marketplaceRuntimeMounts.snapshot(
        context: owner, agent: unrelatedAgent,
        now: fixedDate("2026-07-12T15:40:0\(8 + index)Z"))
      try expect(
        unrelated.apps.isEmpty && unrelated.toolCount == 0,
        "Instagram Business authority changes must not grant unrelated agents")
    }

    let views = try readPackageFile("Sources/RelayConsoleApp/Views.swift")
    let viewModel = try readPackageFile("Sources/RelayConsoleApp/AppViewModel.swift")
    for required in [
      "ApplicationsInstagramBusinessAgentRow",
      "Controls remain visible while unavailable",
      "ApplicationsAgentAuthorityRow",
      "Assign Read only or No access authority",
      "No Instagram account selected", "Search agents...",
      "agents connected to Instagram Business.", "ApplicationsAgentGridScroll",
      "Connect \\(displayName) to Instagram Business?",
      "Disconnect Instagram Business for \\(displayName)?",
    ] {
      try expect(
        views.contains(required),
        "Instagram Business Applications UI is missing assignment source: \(required)")
    }
    try expect(
      viewModel.contains("setInstagramBusinessAgentConnection")
        && viewModel.contains("setMarketplaceAgentPolicy")
        && viewModel.contains("case \"instagram-business\", \"google-ads\""),
      "Instagram Business assignment and read-only authority must use shared scoped services")
  }

  private static func testFacebookPagesBrokerAdapterContract() throws {
    final class Stub: FacebookPagesProviderHTTPClient, @unchecked Sendable {
      var requests: [FacebookPagesProviderHTTPRequest] = []
      var ambiguousCreate = false

      func send(
        _ request: FacebookPagesProviderHTTPRequest
      ) throws -> FacebookPagesProviderHTTPResponse {
        requests.append(request)
        switch (request.method, request.url.path) {
        case ("GET", "/v25.0/page_456"):
          return FacebookPagesProviderHTTPResponse(
            statusCode: 200,
            body: Data(
              #"{"id":"page_456","name":"Relay Test Page","link":"https://www.facebook.com/relaytest","category":"Software","picture":{"data":{"url":"https://example.invalid/picture"}}}"#.utf8))
        case ("GET", "/v25.0/page_456/posts"):
          return FacebookPagesProviderHTTPResponse(
            statusCode: 200,
            body: Data(
              #"{"data":[{"id":"page_456_post_1","message":"Useful Page-authored update","created_time":"2026-07-12T10:00:00Z","permalink_url":"https://www.facebook.com/relaytest/posts/1","is_published":true}],"paging":{"next":"https://graph.facebook.com/should-not-be-followed"}}"#.utf8))
        case ("POST", "/v25.0/page_456/feed"):
          return FacebookPagesProviderHTTPResponse(
            statusCode: 200,
            body: Data((ambiguousCreate ? #"{"success":true}"# : #"{"id":"page_456_post_2"}"#).utf8))
        default:
          throw MarketplaceProviderActionAdapterFailure(
            code: "facebook_pages_stub_unexpected_request", message: request.url.absoluteString)
        }
      }
    }

    let stub = Stub()
    let root = FileManager.default.temporaryDirectory
      .appendingPathComponent("RelayConsoleFacebookPagesAdapterTests", isDirectory: true)
      .appendingPathComponent(UUID().uuidString, isDirectory: true)
    let seed = try makeServices(root: root)
    let workspace = try unwrap(seed.data.getAppState().activeWorkspace, "missing workspace")
    let owner = Self.context(
      roles: [.owner], workspaceId: workspace.id,
      correlationId: "facebook-pages-adapter-owner")
    let foundation = try seed.providerFoundations.registerFacebookPagesFoundation(
      context: owner, now: fixedDate("2026-07-12T12:00:00Z"))
    let app = try unwrap(
      try seed.data.getMarketplaceCatalogApp(
        workspaceId: workspace.id, appIdOrSlug: foundation.appId),
      "missing Facebook Pages app")
    let pageToken = "facebook-pages-live-page-token-sensitive"
    let connection = try seed.providerConnections.saveFacebookPagesRelayOwnedOAuthConnection(
      context: owner, appIdOrSlug: app.id,
      userAccessToken: "facebook-pages-live-user-token-sensitive",
      pageAccessToken: pageToken, grantingUserId: "user_123",
      selectedPageId: "page_456", selectedPageName: "Relay Test Page",
      selectedPageLink: "https://www.facebook.com/relaytest",
      callbackURL: "https://relay.example.com/api/v1/oauth/facebook-pages/callback",
      grantedScopes: ProviderConnectionService.facebookPagesRelayOwnedOAuthScopes,
      accessExpiresAt: nil, selectedPageCreateContentTaskVerified: true,
      stateVerified: true, now: fixedDate("2026-07-12T12:00:01Z"))
    _ = try seed.providerActionPolicies.compilePolicyMap(
      context: owner, appIdOrSlug: app.id, preset: .approvalRequired,
      connectionId: connection.id, now: fixedDate("2026-07-12T12:00:02Z"))
    let broker = MarketplaceProviderActionBrokerService(
      data: seed.data, approvals: seed.providerActionApprovals,
      auditSecurity: seed.auditSecurity,
      adapter: RoutingMarketplaceProviderActionAdapter(
        facebookPagesAdapter: FacebookPagesProviderActionAdapter(
          client: LiveFacebookPagesProviderActionClient(
            data: seed.data, secrets: seed.secrets, httpClient: stub))))

    let pageRead = try broker.execute(
      context: owner,
      request: MarketplaceProviderActionBrokerRequest(
        appIdOrSlug: app.id, actionKey: "facebook_pages_page_get", payload: [:],
        connectionId: connection.id, idempotencyKey: "facebook-pages-page-read"),
      now: fixedDate("2026-07-12T12:00:03Z"))
    let pageResult = try unwrap(pageRead.execution.providerResult, "missing Page result")
    try expect(
      pageRead.adapterExecuted && pageRead.execution.status == .succeeded
        && objectValue(pageResult["page"])?["id"] == .string("page_456")
        && stub.requests.first?.headers["Authorization"] == "Bearer \(pageToken)",
      "Facebook Pages read must execute with the bound Page and Page token")

    let postsRead = try broker.execute(
      context: owner,
      request: MarketplaceProviderActionBrokerRequest(
        appIdOrSlug: app.id, actionKey: "facebook_pages_own_posts_list",
        payload: ["maxResults": .number(10)], connectionId: connection.id,
        idempotencyKey: "facebook-pages-posts-read"),
      now: fixedDate("2026-07-12T12:00:04Z"))
    let postsResult = try unwrap(postsRead.execution.providerResult, "missing posts result")
    try expect(
      postsResult["resultCount"] == .number(1)
        && postsResult["nextPageFollowed"] == .bool(false)
        && objectValue(arrayValue(postsResult["posts"]).first)?["message"]
          == .string("Useful Page-authored update")
        && stub.requests.filter { $0.url.path.hasSuffix("/posts") }.count == 1,
      "Facebook Pages own-posts read must return useful fields without pagination")

    let draft = try broker.execute(
      context: owner,
      request: MarketplaceProviderActionBrokerRequest(
        appIdOrSlug: app.id, actionKey: "facebook_pages_post_draft",
        payload: ["message": .string("A bounded local draft")],
        connectionId: connection.id, idempotencyKey: "facebook-pages-draft"),
      now: fixedDate("2026-07-12T12:00:05Z"))
    try expect(
      draft.execution.providerResult?["providerCallMade"] == .bool(false)
        && stub.requests.count == 2,
      "Facebook Pages drafting must remain local")

    let pending = try broker.execute(
      context: owner,
      request: MarketplaceProviderActionBrokerRequest(
        appIdOrSlug: app.id, actionKey: "facebook_pages_text_post_create",
        payload: ["message": .string("Approved plain text")],
        connectionId: connection.id, idempotencyKey: "facebook-pages-pending"),
      now: fixedDate("2026-07-12T12:00:06Z"))
    try expect(
      !pending.adapterExecuted && pending.execution.status == .pendingApproval
        && pending.approval != nil && stub.requests.count == 2,
      "Standard Facebook Pages publishing must wait for approval without a provider call")

    let pendingApproval = try unwrap(pending.approval, "missing Facebook Pages approval")
    do {
      _ = try broker.execute(
        context: owner,
        request: MarketplaceProviderActionBrokerRequest(
          appIdOrSlug: app.id, actionKey: "facebook_pages_text_post_create",
          payload: ["message": .string("Changed after the approval card")],
          connectionId: connection.id, approvalId: pendingApproval.id,
          idempotencyKey: "facebook-pages-changed-payload"),
        now: fixedDate("2026-07-12T12:00:06Z"))
      throw ServiceTestFailure("Facebook Pages unexpectedly executed a changed approval payload")
    } catch let denied as ServiceGuardResult {
      try expect(
        denied.reasonCode == .inputInvalid && stub.requests.count == 2,
        "Changed Facebook Pages approval payloads must fail before provider execution")
    }
    let approved = try seed.providerActionApprovals.approve(
      context: owner, approvalId: pendingApproval.id,
      approvedPayload: ["message": .string("Approved plain text")],
      now: fixedDate("2026-07-12T12:00:07Z"))
    let approvedExecution = try broker.execute(
      context: owner,
      request: MarketplaceProviderActionBrokerRequest(
        appIdOrSlug: app.id, actionKey: "facebook_pages_text_post_create",
        payload: ["message": .string("Approved plain text")],
        connectionId: connection.id, approvalId: approved.id,
        idempotencyKey: "facebook-pages-approved"),
      now: fixedDate("2026-07-12T12:00:08Z"))
    try expect(
      approvedExecution.adapterExecuted && approvedExecution.execution.status == .succeeded
        && approvedExecution.execution.approvalReference?.status == .approved
        && approvedExecution.execution.providerResult?["postId"] == .string("page_456_post_2")
        && stub.requests.filter { $0.method == "POST" }.count == 1,
      "Exact approved Facebook Pages payloads must execute once through the broker adapter")

    _ = try seed.providerActionPolicies.compilePolicyMap(
      context: owner, appIdOrSlug: app.id, preset: .allowDirectWrites, acknowledgeDangerousPolicy: true,
      connectionId: connection.id, now: fixedDate("2026-07-12T12:00:09Z"))
    let published = try broker.execute(
      context: owner,
      request: MarketplaceProviderActionBrokerRequest(
        appIdOrSlug: app.id, actionKey: "facebook_pages_text_post_create",
        payload: ["message": .string("Approved plain text")],
        connectionId: connection.id, idempotencyKey: "facebook-pages-direct"),
      now: fixedDate("2026-07-12T12:00:10Z"))
    let postRequest = try unwrap(
      stub.requests.last { $0.method == "POST" }, "missing Facebook Pages POST")
    try expect(
      published.adapterExecuted && published.execution.status == .succeeded
        && published.execution.providerResult?["postId"] == .string("page_456_post_2")
        && String(data: postRequest.body ?? Data(), encoding: .utf8)
          == "message=Approved%20plain%20text",
      "Direct Facebook Pages publishing must send only a form-encoded message")

    let definitions = try seed.data.listMarketplaceProviderActionDefinitions(
      workspaceId: workspace.id, appId: app.id)
    let pageDefinition = try unwrap(
      definitions.first { $0.actionKey == "facebook_pages_page_get" },
      "missing Page definition")
    let adapter = FacebookPagesProviderActionAdapter(client: FakeFacebookPagesProviderActionClient())
    let audit = ProviderExecutionAuditIdentity(
      workspaceId: workspace.id, actorId: owner.actorId, actorRole: "owner", agentId: nil,
      appId: app.id, appSlug: app.slug, connectionId: connection.id, installId: nil,
      approvalId: nil, dispatchId: nil, threadId: nil, source: "facebook-pages-payload-test",
      redactionStatus: "private-state-excluded")
    do {
      _ = try adapter.execute(request: MarketplaceProviderActionAdapterRequest(
        context: owner, app: app, definition: pageDefinition, permission: .allowed,
        payload: ["pageId": .string("attacker_page")], approvalReference: nil,
        auditIdentity: audit, idempotencyKey: "facebook-pages-arbitrary-page"))
      throw ServiceTestFailure("Facebook Pages unexpectedly accepted an arbitrary Page ID")
    } catch let failure as MarketplaceProviderActionAdapterFailure {
      try expect(
        failure.code == "facebook_pages_payload_not_supported",
        "Facebook Pages must reject arbitrary Page IDs and raw payload fields")
    }

    stub.ambiguousCreate = true
    let ambiguous = try broker.execute(
      context: owner,
      request: MarketplaceProviderActionBrokerRequest(
        appIdOrSlug: app.id, actionKey: "facebook_pages_text_post_create",
        payload: ["message": .string("Ambiguous provider response")],
        connectionId: connection.id, idempotencyKey: "facebook-pages-ambiguous"),
      now: fixedDate("2026-07-12T12:00:11Z"))
    try expect(
      ambiguous.execution.status == .failed
        && ambiguous.execution.providerError?["providerErrorCode"]
          == .string("facebook_pages_ambiguous_create_response")
        && stub.requests.filter { $0.method == "POST" }.count == 3,
      "Ambiguous Facebook Pages writes must fail once without retry")

    let retained = try seed.database.all(
      "SELECT execution_json AS value FROM marketplace_provider_action_executions")
      .compactMap { sqliteText($0["value"]) }.joined(separator: "\n")
    try expect(
      !retained.contains(pageToken) && !retained.localizedCaseInsensitiveContains("bearer "),
      "Facebook Pages execution persistence must redact authorization material")
  }

