      hermesProfileSlug: "facebook-pages-authority-assigned")
    let unrelatedAgent = try services.data.createAgent(
      workspaceId: workspace.id, name: "Unrelated Facebook Pages Agent",
      harnessId: harness.id, externalAgentId: "facebook-pages-authority-unrelated",
      hermesProfileSlug: "facebook-pages-authority-unrelated")
