      context: owner, now: fixedDate("2026-07-12T14:00:00Z"))
    let app = try unwrap(
      try services.data.getMarketplaceCatalogApp(
        workspaceId: workspace.id, appIdOrSlug: foundation.appId),
      "missing Facebook Pages authority app")
    let beforeConnection = try services.marketplaceInstalls.snapshot(
      context: owner, appIdOrSlug: app.id, now: fixedDate("2026-07-12T14:00:01Z"))
    try expect(
      beforeConnection.compatibleAgents.map(\.agentId).contains(assignedAgent.id)
        && beforeConnection.compatibleAgents.map(\.agentId).contains(unrelatedAgent.id),
      "Facebook Pages agent rows must remain available before a connection exists")
    let connection = try services.providerConnections.saveFacebookPagesRelayOwnedOAuthConnection(
      context: owner, appIdOrSlug: app.id,
      userAccessToken: "facebook-pages-authority-user-sensitive",
      pageAccessToken: "facebook-pages-authority-page-sensitive",
      grantingUserId: "authority_user", selectedPageId: "page_456",
      selectedPageName: "Authority Test Page", selectedPageLink: nil,
      callbackURL: "https://relay.example.com/api/v1/oauth/facebook-pages/callback",
      grantedScopes: ProviderConnectionService.facebookPagesRelayOwnedOAuthScopes,
      accessExpiresAt: nil, selectedPageCreateContentTaskVerified: true,
      stateVerified: true, now: fixedDate("2026-07-12T14:00:02Z"))
    let install = try services.marketplaceInstalls.createInstall(
      context: owner,
      request: installRequest(
        id: "minreq-facebook-pages-authority", workspaceId: workspace.id, app: app,
        connectionId: connection.id, agent: assignedAgent,
        roleId: app.roleManifest.primaryRole, selectedCapabilities: app.capabilities,
        riskAcknowledged: true), now: fixedDate("2026-07-12T14:00:03Z"))
    let presets: [MarketplaceActionPolicyPreset] = [
      .approvalRequired, .allowDirectWrites, .readOnly, .blocked,
    ]
    let expectedCounts: [MarketplaceActionPolicyPreset: Int] = [
      .approvalRequired: 4, .allowDirectWrites: 4, .readOnly: 3, .blocked: 0,
    ]
    for (index, preset) in presets.enumerated() {
      let map = try services.providerActionPolicies.compilePolicyMap(
        context: owner, appIdOrSlug: app.id, preset: preset,
        acknowledgeDangerousPolicy: preset == .allowDirectWrites,
        connectionId: connection.id, installId: install.id, agentId: assignedAgent.id,
        now: fixedDate("2026-07-12T14:00:0\(4 + index)Z"))
      let snapshot = try services.marketplaceRuntimeMounts.snapshot(
        context: owner, agent: assignedAgent,
        now: fixedDate("2026-07-12T14:00:0\(8 + index)Z"))
      let mounted = try unwrap(snapshot.apps.first, "missing scoped Facebook Pages mount")
      try expect(
        map.policyPreset == preset && mounted.tools.count == expectedCounts[preset],
        "Facebook Pages authority \(preset.rawValue) must refresh only the scoped tool surface")
      if preset == .approvalRequired {
        try expect(
          mounted.tools.first {
            $0.toolName == "relay_facebook_pages_publish_text_post"
          }?.requiresApproval == true,
          "Standard Facebook Pages authority must expose an approval-gated publish wrapper")
      }
      if preset == .allowDirectWrites {
        try expect(
          mounted.tools.first {
            $0.toolName == "relay_facebook_pages_publish_text_post"
          }?.autoExecutes == true,
          "Direct writes must expose only the supported publish wrapper for auto-execution")
      }
      let unrelated = try services.marketplaceRuntimeMounts.snapshot(
        context: owner, agent: unrelatedAgent,
        now: fixedDate("2026-07-12T14:00:1\(2 + index)Z"))
      try expect(
        unrelated.apps.isEmpty && unrelated.toolCount == 0,
        "Facebook Pages authority changes must not refresh or grant unrelated agents")
    }

    let views = try readPackageFile("Sources/RelayConsoleApp/Views.swift")
    let viewModel = try readPackageFile("Sources/RelayConsoleApp/AppViewModel.swift")
    for required in [
      "ApplicationsFacebookPagesAgentRow", "Controls remain visible while unavailable",
      "ApplicationsAgentAuthorityRow", "Direct writes, Read only, or No access",
      "facebookPagesAgentControls", "No Facebook Page selected", "Search agents...",
      "agents connected to Facebook Pages.", "ApplicationsAgentGridScroll",
      "Connect \\(displayName) to Facebook Pages?",
      "Disconnect Facebook Pages for \\(displayName)?",
    ] {
      try expect(
        views.contains(required),
        "Facebook Pages Applications UI is missing required assignment source: \(required)")
    }
    try expect(
      viewModel.contains("setFacebookPagesAgentConnection")
        && viewModel.contains("setMarketplaceAgentPolicy")
        && viewModel.contains("case \"facebook-pages\":"),
      "Facebook Pages assignment and four-authority mutations must use the shared scoped services")
  }

  private static func testXRelayOwnedOAuthConnectionContract() throws {
    let services = try makeServices()
    let workspace = try unwrap(services.data.getAppState().activeWorkspace, "missing workspace")
    let owner = Self.context(roles: [.owner], workspaceId: workspace.id, correlationId: "x-oauth2-owner")
    let catalog = try services.applications.catalogSnapshot(context: owner, selectedAppId: "x")
    let x = try unwrap(catalog.apps.first { $0.slug == "x" }, "missing X app")
    let access = "x-oauth2-access-sensitive"
    let refresh = "x-oauth2-refresh-sensitive"
    let saved = try services.providerConnections.saveXRelayOwnedOAuthConnection(
      context: owner, appIdOrSlug: x.id, accessToken: access, refreshToken: refresh,
      userId: "12345", username: "relay_user", displayName: "Relay User",
      grantedScopes: ProviderConnectionService.xRelayOwnedOAuthScopes,
      expiresAt: "2026-01-01T01:00:00Z", billingReady: true,
      now: fixedDate("2026-01-01T00:00:00Z"))
    try expect(saved.credentialOwnership == .relayOwned && !saved.userOwnedCredentialsRequired, "X must use Relay-owned OAuth")
    try expect(saved.callbackURL?.hasPrefix("https://") == true && saved.callbackURL?.contains("/api/v1/oauth/x/callback") == true, "X must retain the exact HTTPS Railway callback")
    try expect(saved.requiredScopes == ProviderConnectionService.xRelayOwnedOAuthScopes && saved.grantedScopes == ProviderConnectionService.xRelayOwnedOAuthScopes, "X must retain exact scopes")
    try expect(saved.secretReferenceIds.count == 2 && Set(saved.credentialRequirements.map(\.fieldKey)) == ["x_oauth_access_token", "x_oauth_refresh_token"], "X must store only separate access and refresh references")
    try expect(saved.health.diagnostics["pkceS256"] == .bool(true) && saved.health.diagnostics["stateVerified"] == .bool(true) && saved.health.diagnostics["billingReady"] == .bool(true), "X must prove PKCE/state/billing readiness")
    try expect(saved.health.diagnostics["replyAutomationEnabled"] == .bool(false) && saved.health.diagnostics["urlsEnabled"] == .bool(false) && saved.health.diagnostics["rawToolsEnabled"] == .bool(false), "X must fail closed on excluded surfaces")
    let rotated = try services.providerConnections.rotateXRelayOwnedOAuthTokens(
      context: owner, connectionId: saved.id, accessToken: "x-oauth2-access-rotated-sensitive",
      refreshToken: "x-oauth2-refresh-rotated-sensitive", expiresAt: "2026-01-01T02:00:00Z",
      now: fixedDate("2026-01-01T00:30:00Z"))
    try expect(rotated.secretReferenceIds.count == 2 && Set(rotated.secretReferenceIds).isDisjoint(with: Set(saved.secretReferenceIds)), "X refresh must atomically rotate both references")
    let retained = try services.database.all("SELECT connection_json AS value FROM applications_provider_connections UNION ALL SELECT label AS value FROM secret_references").compactMap { sqliteText($0["value"]) }.joined(separator: "\n")
    for secret in [access, refresh, "x-oauth2-access-rotated-sensitive", "x-oauth2-refresh-rotated-sensitive"] { try expect(!retained.contains(secret), "X OAuth secret leaked into SQLite") }
  }

