  private static func testXRelayOwnedAdapterContract() throws {
    let services = try makeServices()
    let workspace = try unwrap(services.data.getAppState().activeWorkspace, "missing workspace")
    let owner = Self.context(roles: [.owner], workspaceId: workspace.id, correlationId: "x-adapter-v1-owner")
    let foundation = try services.providerFoundations.registerXFoundation(context: owner)
    let x = try unwrap(try services.data.getMarketplaceCatalogApp(workspaceId: workspace.id, appIdOrSlug: foundation.appId), "missing X app")
    let definitions = try services.data.listMarketplaceProviderActionDefinitions(workspaceId: workspace.id, appId: x.id)
    let post = try unwrap(definitions.first { $0.actionKey == "x_text_post_create" }, "missing X publish action")
    let audit = ProviderExecutionAuditIdentity(workspaceId: workspace.id, actorId: owner.actorId, actorRole: "owner", agentId: nil, appId: x.id, appSlug: x.slug, connectionId: nil, installId: nil, approvalId: nil, dispatchId: nil, threadId: nil, source: "x-v1-adapter-test", redactionStatus: "private-state-excluded")
    let adapter = XProviderActionAdapter(client: FakeXProviderActionClient())
    let result = try adapter.execute(request: MarketplaceProviderActionAdapterRequest(context: owner, app: x, definition: post, permission: .autoExecute, payload: ["text": .string("Bounded plain text")], approvalReference: nil, auditIdentity: audit, idempotencyKey: "x-v1-post"))
    try expect(result.result["madeWithAI"] == .bool(true) && result.result["published"] == .bool(true) && result.result["postURL"]?.string?.hasPrefix("https://x.com/") == true, "X publish result must include AI disclosure and usable URL")
    do {
      _ = try adapter.execute(request: MarketplaceProviderActionAdapterRequest(context: owner, app: x, definition: post, permission: .autoExecute, payload: ["text": .string("See https://example.com")], approvalReference: nil, auditIdentity: audit, idempotencyKey: "x-v1-url"))
      throw ServiceTestFailure("X unexpectedly accepted URL-bearing text")
    } catch let failure as MarketplaceProviderActionAdapterFailure { try expect(failure.code == "x_url_not_supported", "X must reject URL-bearing text") }
    var reply = post; reply.actionKey = "x_reply_create"
    do {
      _ = try adapter.execute(request: MarketplaceProviderActionAdapterRequest(context: owner, app: x, definition: reply, permission: .autoExecute, payload: ["text": .string("reply")], approvalReference: nil, auditIdentity: audit, idempotencyKey: "x-v1-reply"))
      throw ServiceTestFailure("X unexpectedly accepted reply action")
    } catch let failure as MarketplaceProviderActionAdapterFailure { try expect(failure.code == "x_action_not_allowlisted", "X must reject reply automation") }
  }

