          return XProviderHTTPResponse(statusCode: 200, body: Data(#"{"data":[{"id":"p1","text":"Useful Post","created_at":"2026-01-01T00:00:00Z"}]}"#.utf8))
        }
        throw MarketplaceProviderActionAdapterFailure(code: "stub_path", message: request.url.path)
      }
    }
    let services = try makeServices(); let workspace = try unwrap(services.data.getAppState().activeWorkspace, "missing workspace"); let owner = Self.context(roles: [.owner], workspaceId: workspace.id, correlationId: "x-live-read-v1")
    let foundation = try services.providerFoundations.registerXFoundation(context: owner); let x = try unwrap(try services.data.getMarketplaceCatalogApp(workspaceId: workspace.id, appIdOrSlug: foundation.appId), "missing X")
    let token = "x-live-read-oauth2-sensitive"; let connection = try services.providerConnections.saveXRelayOwnedOAuthConnection(context: owner, appIdOrSlug: x.id, accessToken: token, refreshToken: "x-live-read-refresh-sensitive", userId: "u1", username: "relay", displayName: "Relay", grantedScopes: ProviderConnectionService.xRelayOwnedOAuthScopes, expiresAt: nil, billingReady: true)
    let broker = MarketplaceProviderActionBrokerService(data: services.data, approvals: services.providerActionApprovals, auditSecurity: services.auditSecurity, adapter: RoutingMarketplaceProviderActionAdapter(xAdapter: XProviderActionAdapter(client: LiveXProviderActionClient(data: services.data, secrets: services.secrets, httpClient: Stub()))))
    let executed = try broker.execute(context: owner, request: MarketplaceProviderActionBrokerRequest(appIdOrSlug: x.id, actionKey: "x_own_posts_list", payload: ["maxResults": .number(10)], connectionId: connection.id, idempotencyKey: "x-read-v1"))
    let result = try unwrap(executed.execution.providerResult, "missing X read result"); let posts = arrayValue(result["posts"])
    try expect(posts.count == 1 && objectValue(posts[0])?["text"] == .string("Useful Post") && result["onePageOnly"] == .bool(true), "X read must return useful bounded Post fields")
    let retained = try services.database.all("SELECT execution_json AS value FROM marketplace_provider_action_executions").compactMap { sqliteText($0["value"]) }.joined(); try expect(!retained.contains(token), "X read leaked access token")
  }

  private static func testXRelayOwnedLiveWriteContract() throws {
    final class Stub: XProviderHTTPClient, @unchecked Sendable {
      var body: Data?
      func send(_ request: XProviderHTTPRequest) throws -> XProviderHTTPResponse { body = request.body; return XProviderHTTPResponse(statusCode: 201, body: Data(#"{"data":{"id":"p1","text":"Published"}}"#.utf8)) }
    }
    let services = try makeServices(); let workspace = try unwrap(services.data.getAppState().activeWorkspace, "missing workspace"); let owner = Self.context(roles: [.owner], workspaceId: workspace.id, correlationId: "x-live-write-v1")
    let foundation = try services.providerFoundations.registerXFoundation(context: owner); let x = try unwrap(try services.data.getMarketplaceCatalogApp(workspaceId: workspace.id, appIdOrSlug: foundation.appId), "missing X")
    let connection = try services.providerConnections.saveXRelayOwnedOAuthConnection(context: owner, appIdOrSlug: x.id, accessToken: "x-write-access-sensitive", refreshToken: "x-write-refresh-sensitive", userId: "u1", username: "relay", displayName: "Relay", grantedScopes: ProviderConnectionService.xRelayOwnedOAuthScopes, expiresAt: nil, billingReady: true)
    _ = try services.providerActionPolicies.compilePolicyMap(context: owner, appIdOrSlug: x.id, preset: .allowDirectWrites, acknowledgeDangerousPolicy: true, connectionId: connection.id)
    let stub = Stub(); let broker = MarketplaceProviderActionBrokerService(data: services.data, approvals: services.providerActionApprovals, auditSecurity: services.auditSecurity, adapter: RoutingMarketplaceProviderActionAdapter(xAdapter: XProviderActionAdapter(client: LiveXProviderActionClient(data: services.data, secrets: services.secrets, httpClient: stub))))
    let executed = try broker.execute(context: owner, request: MarketplaceProviderActionBrokerRequest(appIdOrSlug: x.id, actionKey: "x_text_post_create", payload: ["text": .string("Published")], connectionId: connection.id, idempotencyKey: "x-write-v1"))
    let requestBody = try unwrap(stub.body.flatMap { try? JSONSerialization.jsonObject(with: $0) as? [String: Any] }, "missing X request body")
    try expect(requestBody["text"] as? String == "Published" && requestBody["made_with_ai"] as? Bool == true && Set(requestBody.keys) == ["text", "made_with_ai"], "X write must send only text plus AI disclosure")
    let result = try unwrap(executed.execution.providerResult, "missing X write result"); try expect(result["postId"] == .string("p1") && result["madeWithAI"] == .bool(true) && result["published"] == .bool(true), "X write must return safe publish result")
  }


  private static func testMarketplaceInstallsTargetCompatibleAgentsAndRemoveAsUnconfigured() throws
  {
    let root = FileManager.default.temporaryDirectory
      .appendingPathComponent("RelayConsoleMarketplaceInstallTests", isDirectory: true)
      .appendingPathComponent(UUID().uuidString, isDirectory: true)
    let workspaceId: String
    let appId: String
    let connectionId: String
    let retainedSecret = "client_secret=marketplace-install-sensitive-value"

    do {
      let services = try makeServices(root: root)
      let workspace = try unwrap(services.data.getAppState().activeWorkspace, "missing workspace")
      workspaceId = workspace.id
      let owner = Self.context(
        roles: [.owner], workspaceId: workspace.id, correlationId: "marketplace-install-owner-001")
      let admin = Self.context(
        roles: [.admin], workspaceId: workspace.id, correlationId: "marketplace-install-admin-001")
      let member = Self.context(
        roles: [.member], workspaceId: workspace.id, correlationId: "marketplace-install-member-001"
      )
      let viewer = Self.context(
        roles: [.viewer], workspaceId: workspace.id, correlationId: "marketplace-install-viewer-001"
      )
      let events = EventCounter()
      _ = services.eventBus.on(.applicationsMarketplaceInstallUpdated) { _ in events.increment() }

      let hermesHarness = try prepareInstalledHarness(services: services, key: .hermes)
      let openClawHarness = try prepareInstalledHarness(services: services, key: .openclaw)
      let hermesAgent = try services.data.createAgent(
        workspaceId: workspace.id,
        name: "Hermes Operator",
        harnessId: hermesHarness.id,
        externalAgentId: "hermes-operator"
      )
      let openClawAgent = try services.data.createAgent(
        workspaceId: workspace.id,
        name: "OpenClaw Auditor",
        harnessId: openClawHarness.id,
        externalAgentId: "openclaw-auditor"
      )
      let inactiveAgent = try services.data.updateAgent(
        agentId: openClawAgent.id,
        name: "OpenClaw Auditor",
        status: "inactive"
      )

      let outlook = marketplaceApp(
        workspaceId: workspace.id,
        slug: "outlook",
        name: "Outlook",
        summary: "Mail and calendar provider.",
        category: "Productivity",
        riskLevel: .high,
        connectionState: .none,
        installState: .notInstalled
      )
      let paperclip = marketplaceApp(
        workspaceId: workspace.id,
        slug: "paperclip-local",
        name: "Paperclip Local",
        summary: "Excluded Paperclip provider.",
        category: "Local",
        riskLevel: .medium,
        availability: .unavailable,
        availabilityReason: "Paperclip is excluded",
        connectionState: .unavailable,
        installState: .unavailable,
        localAppExcluded: true,
        reviewExcluded: true
      )
      _ = try services.applications.saveCatalogApps(context: owner, apps: [outlook, paperclip])
      appId = outlook.id

      let empty = try services.marketplaceInstalls.snapshot(
        context: member, appIdOrSlug: outlook.slug, now: fixedDate("2026-01-01T00:00:00Z"))
      try expect(
        empty.state == .readOnly,
        "member install snapshot should be read-only when compatible agents exist")
      try expect(empty.readOnly, "member install snapshot should be read-only")
      try expect(
        empty.compatibleAgents.contains {
          $0.agentId == hermesAgent.id && $0.status == .compatible
        }, "Hermes agent should be compatible")
      try expect(
        empty.compatibleAgents.contains {
          $0.agentId == inactiveAgent.id && $0.status == .inactiveAgent
        }, "inactive agent should be retained as incompatible")

      do {
        _ = try services.marketplaceInstalls.snapshot(context: viewer, appIdOrSlug: outlook.slug)
        throw ServiceTestFailure("viewer unexpectedly read Marketplace installs")
      } catch let denied as ServiceGuardResult {
        try expect(
          denied.reasonCode == .authorityRoleRequired,
          "viewer install read should require workspace access")
      }

      let secret = try services.secrets.set(
        scope: "provider_connection", scopeId: outlook.id, label: "Outlook Client Secret",
        secretValue: retainedSecret)
      let connected = providerConnection(
        workspaceId: workspace.id,
        app: outlook,
        status: .connected,
        authorizationState: .completed,
        secretReferenceId: secret.id,
        accountLabel: "Outlook contract account",
        connectedHandle: "relay-outlook",
        lastError: nil
      )
      let savedConnection = try services.providerConnections.saveConnection(
        context: admin, connection: connected)
      connectionId = savedConnection.id

      do {
        _ = try services.marketplaceInstalls.createInstall(
          context: member,
          request: installRequest(
            workspaceId: workspace.id,
            app: outlook,
            connectionId: savedConnection.id,
            agent: hermesAgent,
            roleId: "operator",
            riskAcknowledged: true
          )
        )
        throw ServiceTestFailure("member install mutation unexpectedly succeeded")
      } catch let denied as ServiceGuardResult {
        try expect(
          denied.reasonCode == .authorityRoleRequired, "member install mutation should be denied")
      }

      do {
        _ = try services.marketplaceInstalls.createInstall(
          context: owner,
          request: installRequest(
            workspaceId: workspace.id,
            app: outlook,
            connectionId: savedConnection.id,
            agent: hermesAgent,
            roleId: "operator",
            riskAcknowledged: false
          )
        )
        throw ServiceTestFailure("high-risk install without acknowledgement unexpectedly succeeded")
      } catch let denied as ServiceGuardResult {
        try expect(
          denied.reasonCode == .decisionRequired, "high-risk install should require acknowledgement"
        )
      }

      do {
        _ = try services.marketplaceInstalls.createInstall(
          context: owner,
          request: installRequest(
            workspaceId: workspace.id,
            app: outlook,
            connectionId: savedConnection.id,
            agent: hermesAgent,
            roleId: "operator",
            selectedCapabilities: ["read_status", "raw_api_key"],
            riskAcknowledged: true
          )
        )
        throw ServiceTestFailure("install with unsupported capability unexpectedly succeeded")
      } catch let denied as ServiceGuardResult {
        try expect(
          denied.reasonCode == .inputInvalid,
          "unsupported install capability should be invalid input")
      }

      do {
        _ = try services.marketplaceInstalls.createInstall(
          context: owner,
          request: installRequest(
            workspaceId: workspace.id,
            app: outlook,
            connectionId: savedConnection.id,
            agent: hermesAgent,
            roleId: "manager",
            riskAcknowledged: true
          )
        )
        throw ServiceTestFailure("non-installable manager role unexpectedly succeeded")
      } catch let denied as ServiceGuardResult {
        try expect(
          denied.reasonCode == .capabilityMissing,
          "non-installable role should be capability-missing")
      }

      do {
        var missingAgentRequest = installRequest(
          workspaceId: workspace.id,
          app: outlook,
          connectionId: savedConnection.id,
          agent: hermesAgent,
          roleId: "operator",
          riskAcknowledged: true
        )
        missingAgentRequest.targetAgentId = "agt-missing-marketplace-install"
        _ = try services.marketplaceInstalls.createInstall(
          context: owner, request: missingAgentRequest)
        throw ServiceTestFailure("missing agent install unexpectedly succeeded")
      } catch {
        try expect(
          try services.data.listMarketplaceInstalls(workspaceId: workspace.id, appId: outlook.id)
            .isEmpty, "missing agent attempt should not create install records")
      }

      do {
        var dangerousRequest = installRequest(
          workspaceId: workspace.id,
          app: outlook,
          connectionId: savedConnection.id,
          agent: hermesAgent,
          roleId: "operator",
          riskAcknowledged: true
        )
        dangerousRequest.approvalProfileId = MarketplaceInstallService.dangerouslySkipPermissionsPolicyId
        _ = try services.marketplaceInstalls.createInstall(context: owner, request: dangerousRequest)
        throw ServiceTestFailure("dangerous policy install without dedicated acknowledgement unexpectedly succeeded")
      } catch let denied as ServiceGuardResult {
        try expect(
          denied.reasonCode == .decisionRequired,
          "dangerous policy install should require its dedicated acknowledgement"
        )
      }

      let firstInstall = try services.marketplaceInstalls.createInstall(
        context: owner,
        request: installRequest(
          workspaceId: workspace.id,
          app: outlook,
          connectionId: savedConnection.id,
          agent: hermesAgent,
          roleId: "operator",
          selectedCapabilities: ["read_status"],
          riskAcknowledged: true
        ),
        now: fixedDate("2026-01-01T00:00:01Z")
      )
      try expect(
        firstInstall.installStatus == .installed,
        "valid install should persist installed lifecycle status")
      try expect(firstInstall.driftStatus == .current, "valid install should start current")
      try expect(
        firstInstall.metadata["runtimeWriteDeferred"] == .bool(true),
        "install should defer runtime writes")
      try expect(
        firstInstall.metadata["providerWriteDeferred"] == .bool(true),
        "install should defer provider writes")
      try expect(
        firstInstall.metadata["toolAutoGrantCreated"] == .bool(false),
        "install should not create fake tool grants")

      let secondInstall = try services.marketplaceInstalls.createInstall(
        context: owner,
        request: installRequest(
          id: "minreq-marketplace-install-duplicate",
          workspaceId: workspace.id,
          app: outlook,
          connectionId: savedConnection.id,
          agent: hermesAgent,
          roleId: "operator",
          selectedCapabilities: ["read_status", "agent_install_status"],
          riskAcknowledged: true
        ),
        now: fixedDate("2026-01-01T00:00:02Z")
      )
      let installsAfterDuplicate = try services.data.listMarketplaceInstalls(
        workspaceId: workspace.id, appId: outlook.id)
      try expect(
        installsAfterDuplicate.contains {
          $0.id == firstInstall.id && $0.installStatus == .superseded
        }, "duplicate active target should supersede older install")
      try expect(
        installsAfterDuplicate.contains {
          $0.id == secondInstall.id && $0.installStatus == .installed
        }, "duplicate install should leave new active record")

      do {
        _ = try services.marketplaceInstalls.updateInstall(
          context: admin,
          installId: secondInstall.id,
          approvalProfileId: MarketplaceInstallService.dangerouslySkipPermissionsPolicyId
        )
        throw ServiceTestFailure("dangerous policy update without dedicated acknowledgement unexpectedly succeeded")
      } catch let denied as ServiceGuardResult {
        try expect(
          denied.reasonCode == .decisionRequired,
          "dangerous policy update should require its dedicated acknowledgement"
        )
      }

      let dangerousUpdated = try services.marketplaceInstalls.updateInstall(
        context: admin,
        installId: secondInstall.id,
        approvalProfileId: MarketplaceInstallService.dangerouslySkipPermissionsPolicyId,
        acknowledgeDangerouslySkipPermissions: true,
        now: fixedDate("2026-01-01T00:00:02Z")
      )
      try expect(
        dangerousUpdated.metadata["dangerousPolicyAcknowledged"] == .bool(true),
        "dangerous policy update should persist acknowledgement evidence"
      )
      try expect(
        dangerousUpdated.metadata["dangerousPolicyAcknowledgementVersion"] ==
          .string(MarketplaceInstallService.dangerousPolicyAcknowledgementVersion),
        "dangerous policy update should persist the acknowledgement version"
      )
      try expect(
        dangerousUpdated.metadata["dangerousPolicyPreservedInvariants"] ==
          .array(MarketplaceInstallService.dangerousPolicyPreservedInvariants.map(JSONValue.string)),
        "dangerous policy update should preserve non-approval invariants"
      )

      let updated = try services.marketplaceInstalls.updateInstall(
        context: admin,
        installId: secondInstall.id,
        selectedCapabilities: ["agent_install_status"],
        approvalProfileId: "approval-marketplace-install-review",
        driftStatus: .refreshNeeded,
        now: fixedDate("2026-01-01T00:00:03Z")
      )
      try expect(
        updated.selectedCapabilities == ["agent_install_status"],
        "install policy update should persist selected capabilities")
      try expect(
        updated.approvalProfileId == "approval-marketplace-install-review",
        "install policy update should persist approval profile")
      try expect(updated.driftStatus == .refreshNeeded, "install drift should persist")

      let removed = try services.marketplaceInstalls.removeInstall(
        context: owner,
        installId: secondInstall.id,
        now: fixedDate("2026-01-01T00:00:04Z")
      )
      try expect(removed.installStatus == .removed, "remove should retain removed status")
      try expect(removed.driftStatus == .unconfigured, "remove should mark install unconfigured")
      try expect(
        removed.metadata["removeAsUnconfigured"] == .bool(true),
        "remove should be recorded as unconfigured")
      try expect(
        removed.metadata["runtimeCleanupPerformed"] == .bool(false),
        "remove should not claim runtime cleanup")
      try expect(
        removed.metadata["credentialsPreserved"] == .bool(true),
        "remove should preserve provider credentials")

      let installSnapshot = try services.marketplaceInstalls.snapshot(
        context: member, appIdOrSlug: outlook.id, now: fixedDate("2026-01-01T00:00:05Z"))
      try expect(
        installSnapshot.state == .readOnly, "member populated install snapshot should be read-only")
      try expect(
        installSnapshot.installs.count == 2, "snapshot should retain superseded and removed records"
      )
      try expect(
        installSnapshot.diagnostics.runtimeWriteSummary
          == "Runtime writes deferred until safety cards authorize them.",
        "snapshot should state runtime writes are deferred")
      try expect(
        installSnapshot.diagnostics.removalSummary.contains("1 remove-as-unconfigured"),
        "snapshot should summarize remove-as-unconfigured records")

      let syncedApp = try unwrap(
        try services.data.getMarketplaceCatalogApp(
          workspaceId: workspace.id, appIdOrSlug: outlook.slug),
        "missing synced install catalog app")
      try expect(
        syncedApp.installState == .notInstalled,
        "removed install should leave catalogue not installed")
      try expect(
        syncedApp.installedAgentIds.isEmpty, "removed install should clear active installed agents")
      try expect(
        try services.providerConnections.snapshot(context: owner, appIdOrSlug: outlook.id)
          .connections.first?.id == savedConnection.id,
        "provider connection should survive install removal")
      try expect(
        try services.runtimeActions.listRuns(context: owner).isEmpty,
        "Marketplace install flow should not execute runtime actions")

      do {
        _ = try services.marketplaceInstalls.snapshot(context: owner, appIdOrSlug: paperclip.slug)
        throw ServiceTestFailure("Paperclip install snapshot unexpectedly succeeded")
      } catch let denied as ServiceGuardResult {
        try expect(
          denied.reasonCode == .inputInvalid, "Paperclip install state should remain excluded")
      }

      let sqliteDump = try services.database.all(
        """
        SELECT install_json AS value FROM applications_marketplace_installs
        UNION ALL
        SELECT metadata_json AS value FROM applications_marketplace_installs
        UNION ALL
        SELECT snapshot_json AS value FROM applications_marketplace_install_snapshots
        """
      ).compactMap { sqliteText($0["value"]) }.joined(separator: "\n")
      try expect(
        !sqliteDump.contains("marketplace-install-sensitive-value"),
        "raw install secret leaked into SQLite JSON")
      try expect(
        !sqliteDump.contains("/private/tmp/marketplace-install-sensitive-value"),
        "raw install local path leaked into SQLite JSON")
      try expect(
        sqliteDump.contains("[REDACTED]"), "install records should persist redacted evidence")
      try expect(
        events.value >= 5,
        "Marketplace install events should publish for save/update/remove/snapshot updates")
    }

    let reopened = try makeServices(root: root)
    let reopenedContext = Self.context(
      roles: [.owner], workspaceId: workspaceId, correlationId: "marketplace-install-reopen-001")
    let reopenedSnapshot = try reopened.marketplaceInstalls.snapshot(
      context: reopenedContext,
      appIdOrSlug: appId,
      now: fixedDate("2026-01-01T00:00:06Z")
    )
    try expect(
      reopenedSnapshot.installs.count == 2, "Marketplace install records should survive relaunch")
    try expect(
      reopenedSnapshot.installs.contains { $0.installStatus == .removed },
      "removed install should survive relaunch")
    try expect(
      try reopened.marketplaceInstalls.latestSnapshot(context: reopenedContext, appId: appId)
        != nil, "latest install snapshot should be durable")
    try expect(
      try reopened.providerConnections.snapshot(context: reopenedContext, appIdOrSlug: appId)
        .connections.first?.id == connectionId,
      "provider connection should survive Marketplace install relaunch")
  }

  private static func testGenericProviderActionPersistenceRoundTripsAndRedactsPayloads() throws {
    let root = FileManager.default.temporaryDirectory
      .appendingPathComponent("RelayConsoleProviderActionPersistenceTests", isDirectory: true)
      .appendingPathComponent(UUID().uuidString, isDirectory: true)
    let workspaceId: String
    let appId: String
    let actionId = "mpact-provider-action-001"
    let permissionMapId = "mpperm-provider-action-001"
    let approvalId = "mpapr-provider-action-001"
    let executionId = "mpexec-provider-action-001"
    let rawSensitive = "provider-action-sensitive-value"
    let rawPath = "/private/tmp/provider-action-sensitive-value"

    do {
      let services = try makeServices(root: root)
      let workspace = try unwrap(services.data.getAppState().activeWorkspace, "missing workspace")
      workspaceId = workspace.id
      let owner = Self.context(
        roles: [.owner], workspaceId: workspace.id, correlationId: "provider-action-owner-001")
      let events = EventCounter()
      _ = services.eventBus.on(.applicationsProviderActionUpdated) { _ in events.increment() }

      let agent = try createServiceAgent(services: services, workspaceId: workspace.id)
      let app = marketplaceApp(
        workspaceId: workspace.id,
        slug: "github",
        name: "GitHub",
        summary: "Repository provider action fixture.",
        category: "Engineering",
        riskLevel: .high,
        connectionState: .connected,
        installState: .installed,
        installedAgentCount: 1,
        installedAgentIds: [agent.id]
      )
      _ = try services.applications.saveCatalogApps(context: owner, apps: [app])
      appId = app.id

      let secret = try services.secrets.set(
        scope: "provider_connection",
        scopeId: app.id,
        label: "GitHub token",
        secretValue: "token=\(rawSensitive)"
      )
      let connection = try services.providerConnections.saveConnection(
        context: owner,
        connection: providerConnection(
          workspaceId: workspace.id,
          app: app,
          status: .connected,
          authorizationState: .completed,
          secretReferenceId: secret.id,
          accountLabel: "Provider Action Account",
          connectedHandle: "provider-action",
          lastError: nil
        )
      )
      let timestamp = "2026-01-01T00:00:00Z"
      let install = try services.data.saveMarketplaceInstall(
        MarketplaceInstallRecord(
          id: "minst-provider-action-001",
          workspaceId: workspace.id,
          appId: app.id,
          appSlug: app.slug,
          connectionId: connection.id,
          agentId: agent.id,
          agentName: agent.name,
          runtimeBindingId: agent.binding.id,
          harnessId: agent.harness.id,
          runtimeType: agent.binding.runtimeType,
          roleId: "operator",
          roleLabel: "Operator",
          selectedCapabilities: ["issues.write"],
          approvalProfileId: "approval-provider-action-default",
          runtimeFormat: agent.binding.runtimeType,
          targetMode: .existingAgent,
          riskAcknowledged: true,
          installStatus: .installed,
          driftStatus: .current,
          lastInstalledAt: timestamp,
          removedAt: nil,
          failureMessage: nil,
          metadata: [
            "providerWriteDeferred": .bool(true),
            "localPath": .string(rawPath),
          ],
          createdByActorId: owner.actorId,
          createdAt: timestamp,
          updatedAt: timestamp,
          redactionStatus: "private-state-excluded"
        ))

      let definition = try services.data.saveMarketplaceProviderActionDefinition(
        MarketplaceProviderActionDefinition(
          id: actionId,
          workspaceId: workspace.id,
          appId: app.id,
          appSlug: app.slug,
          providerKey: app.slug,
          actionKey: "github.issue.create",
          displayName: "Create issue token=\(rawSensitive)",
          summary: "Create a provider issue after approval.",
          kind: .write,
          riskLevel: .high,
          adapterKind: .officialMCP,
          defaultPermission: .approvalRequired,
          requiredScopes: ["repo.write"],
          capabilityKeys: ["issues.write"],
          payloadSchema: [
            "title": .string("string"),
            "body": .string("token=\(rawSensitive)"),
          ],
          resultSchema: ["issueUrl": .string("string")],
          enabled: true,
          createdAt: timestamp,
          updatedAt: timestamp,
          redactionStatus: "private-state-excluded"
        ))
      try expect(
        definition.displayName.contains("[REDACTED]"),
        "provider action definition should redact display text evidence")
      try expect(
        definition.payloadSchema["body"] == .string("token=[REDACTED]"),
        "provider action payload schema should redact token-like values")

      let permissionMap = try services.data.saveMarketplaceActionPermissionMap(
        MarketplaceActionPermissionMap(
          id: permissionMapId,
          workspaceId: workspace.id,
          appId: app.id,
          appSlug: app.slug,
          connectionId: connection.id,
          installId: install.id,
          agentId: agent.id,
          policyPreset: .approvalRequired,
          permissions: [
            "github.issue.create": .approvalRequired,
            "github.issue.search": .allowed,
            "github.repository.delete": .blocked,
          ],
          blockedReasons: [
            "github.repository.delete": "Destructive repository deletion is blocked."
          ],
          source: "marketplace-policy-compiler",
          createdByActorId: owner.actorId,
          updatedByActorId: owner.actorId,
          createdAt: timestamp,
          updatedAt: timestamp,
          redactionStatus: "private-state-excluded"
        ))
      try expect(
        permissionMap.permissions["github.issue.create"] == .approvalRequired,
        "permission map should retain approval-required action")

      let proposedPayload: JSONRecord = [
        "title": .string("Provider action issue"),
        "body": .string("Create an issue from provider action approval."),
        "authorization": .string("Bearer \(rawSensitive)"),
        "localPath": .string(rawPath),
      ]
      let approval = try services.data.saveMarketplaceProviderActionApproval(
        MarketplaceProviderActionApprovalRecord(
          id: approvalId,
          workspaceId: workspace.id,
          appId: app.id,
          appSlug: app.slug,
          connectionId: connection.id,
          installId: install.id,
          agentId: agent.id,
          providerActionId: definition.id,
          actionKey: definition.actionKey,
          proposedPayload: proposedPayload,
