    )
    try expect(
      try reopened.data.getMarketplaceProviderActionExecution(
        workspaceId: workspaceId, executionId: executionId)?.status == .succeeded,
      "provider action execution should survive relaunch"
    )
    try expect(
      try reopened.data.listMarketplaceInstalls(workspaceId: workspaceId, appId: appId).first?.id
        == "minst-provider-action-001",
      "provider action install reference should remain compatible with existing install storage"
    )
  }


  private static func testExaSearchProviderFoundationEnforcesResearchPolicy() throws {
    let services = try makeServices()
    let workspace = try unwrap(services.data.getAppState().activeWorkspace, "missing workspace")
    let owner = Self.context(
      roles: [.owner], workspaceId: workspace.id, correlationId: "exa-foundation-owner-001")
    let member = Self.context(
      roles: [.member], workspaceId: workspace.id, correlationId: "exa-foundation-member-001")

    let snapshot = try services.providerFoundations.registerExaSearchFoundation(
      context: owner,
      now: fixedDate("2026-01-01T00:00:00Z")
    )
    try expect(snapshot.appSlug == "exa-search", "Exa foundation should target Exa Search")
    try expect(
      snapshot.providerFamily == "research", "Exa foundation should mark the provider as research")
    try expect(
      snapshot.connectionMode == "user-owned-exa-api-key",
      "Exa foundation should use a user-owned API key")
    try expect(
      snapshot.credentials.map(\.fieldKey) == ["exa_api_key"],
      "Exa foundation should list only the Exa API key credential")
    try expect(
      snapshot.budgetPolicy["deepSearch"] == .string("approval_required"),
      "Exa deep search should require budget review")
    try expect(
      snapshot.privacyPolicy["resultExport"] == .string("blocked"),
      "Exa result export should be privacy-blocked")
    try expect(
      snapshot.defaultPolicyPreset == .approvalRequired,
      "Exa foundation should default to approval-required policy")
    try expect(
      snapshot.blockedActionKeys == ["exa.result.export"],
      "Exa export should be blocked in the foundation")
    try expect(
      snapshot.agentFacingWrapperToolNames.count == 3,
      "Exa foundation should expose three safe wrapper names")
    try expect(
      snapshot.agentFacingWrapperToolNames.allSatisfy {
        $0.hasPrefix("relay_provider_exa_search_")
      }, "Exa wrapper names should use Relay provider namespace")

    let actionByKey = Dictionary(uniqueKeysWithValues: snapshot.actions.map { ($0.actionKey, $0) })
    try expect(
      actionByKey["exa.search.web"]?.policyPermission == .allowed,
      "standard Exa search should be allowed")
    try expect(
      actionByKey["exa.answer.read"]?.policyPermission == .allowed,
      "Exa answer reads should be allowed")
    try expect(
      actionByKey["exa.search.deep"]?.policyPermission == .approvalRequired,
      "Exa deep search should require approval")
    try expect(
      actionByKey["exa.result.export"]?.policyPermission == .blocked, "Exa export should be blocked"
    )

    let readOnly = try services.providerActionPolicies.compilePolicyMap(
      context: owner,
      appIdOrSlug: snapshot.appId,
      preset: .readOnly,
      now: fixedDate("2026-01-01T00:00:01Z")
    )
    try expect(
      readOnly.permissions["exa.search.web"] == .allowed,
      "read-only Exa policy should allow standard search")
    try expect(
      readOnly.permissions["exa.answer.read"] == .allowed,
      "read-only Exa policy should allow answer read")
    try expect(
      readOnly.permissions["exa.search.deep"] == .approvalRequired,
      "read-only Exa policy should still review high-cost deep search")
    try expect(
      readOnly.permissions["exa.result.export"] == .blocked,
      "read-only Exa policy should block export")

    let app = try unwrap(
      try services.data.getMarketplaceCatalogApp(
        workspaceId: workspace.id, appIdOrSlug: snapshot.appId),
      "missing Exa Search app"
    )
    let connection = try services.providerConnections.saveExaAPIKeyConnection(
      context: owner,
      appIdOrSlug: app.id,
      apiKey: "exa_search_foundation_secret_123",
      validationResult: ExaAPIKeyValidationResult(
        status: .ready, message: "Exa API key verified.", httpStatusCode: 200),
      now: fixedDate("2026-01-01T00:00:02Z")
    )
    let agent = try createServiceAgent(services: services, workspaceId: workspace.id)
    let unassignedAgent = try createServiceAgent(services: services, workspaceId: workspace.id)
    let timestamp = "2026-01-01T00:00:03Z"
    let install = try services.data.saveMarketplaceInstall(
      MarketplaceInstallRecord(
        id: "minst-exa-foundation-001",
        workspaceId: workspace.id,
        appId: app.id,
        appSlug: app.slug,
        connectionId: connection.id,
        agentId: agent.id,
        agentName: agent.name,
        runtimeBindingId: agent.binding.id,
        harnessId: agent.harness.id,
        runtimeType: agent.binding.runtimeType,
        roleId: app.roleManifest.primaryRole,
        roleLabel: "Researcher",
        selectedCapabilities: app.capabilities,
        approvalProfileId: "approval-exa-foundation-default",
        runtimeFormat: agent.binding.runtimeType,
        targetMode: .existingAgent,
        riskAcknowledged: false,
        installStatus: .installed,
        driftStatus: .current,
        lastInstalledAt: timestamp,
        removedAt: nil,
        failureMessage: nil,
        metadata: ["researchProvider": .string("exa-search")],
        createdByActorId: owner.actorId,
        createdAt: timestamp,
        updatedAt: timestamp,
        redactionStatus: "private-state-excluded"
      ))
    let surface = try services.providerWrapperTools.compileSurface(
      context: member,
      appIdOrSlug: app.id,
      installId: install.id,
      agentId: agent.id,
      now: fixedDate("2026-01-01T00:00:04Z")
    )
    try expect(
      surface.tools.count == 3, "assigned Exa install should expose three safe wrapper tools")
    try expect(
      surface.tools.contains { $0.displayName == "Search web" && $0.readOnly },
      "Exa standard search should compile as read-only wrapper")
    try expect(
      surface.tools.contains { $0.displayName == "Read answer" && $0.readOnly },
      "Exa answer read should compile as read-only wrapper")
    try expect(
      surface.tools.contains { $0.displayName == "Deep search" && $0.requiresApproval },
      "Exa deep search should compile as approval wrapper")
    try expect(
      !surface.tools.contains { $0.displayName == "Export results" },
      "Exa export should not become an agent-facing wrapper")

    let unassignedSurface = try services.providerWrapperTools.compileSurface(
      context: owner,
      appIdOrSlug: app.id,
      agentId: unassignedAgent.id,
      now: fixedDate("2026-01-01T00:00:05Z")
    )
    try expect(
      unassignedSurface.tools.isEmpty, "unassigned agent should not receive Exa wrapper tools")
    try expect(
      !unassignedSurface.diagnostics.assignedAgentReady,
      "unassigned Exa wrapper surface should report missing assignment")

    let search = try services.providerActionBroker.execute(
      context: owner,
      request: MarketplaceProviderActionBrokerRequest(
        appIdOrSlug: app.id,
        actionKey: "exa.search.web",
        payload: [
          "query": .string("Relay Console research policy"),
          "numResults": .number(3),
        ],
        installId: install.id,
        idempotencyKey: "exa-foundation-search-001"
      ),
      now: fixedDate("2026-01-01T00:00:06Z")
    )
    try expect(search.adapterExecuted, "allowed Exa standard search should execute through broker")
    try expect(
      search.execution.status == .succeeded,
      "allowed Exa standard search should persist succeeded execution")

    let answer = try services.providerActionBroker.execute(
      context: owner,
      request: MarketplaceProviderActionBrokerRequest(
        appIdOrSlug: app.id,
        actionKey: "exa.answer.read",
        payload: ["query": .string("What is Relay Console?")],
        installId: install.id,
        idempotencyKey: "exa-foundation-answer-001"
      ),
      now: fixedDate("2026-01-01T00:00:07Z")
    )
    try expect(answer.adapterExecuted, "allowed Exa answer read should execute through broker")
    try expect(
      answer.execution.status == .succeeded,
      "allowed Exa answer read should persist succeeded execution")

    let deepSearch = try services.providerActionBroker.execute(
      context: owner,
      request: MarketplaceProviderActionBrokerRequest(
        appIdOrSlug: app.id,
        actionKey: "exa.search.deep",
        payload: [
          "query": .string("High-cost research"),
          "budget": .number(25),
        ],
        installId: install.id,
        idempotencyKey: "exa-foundation-deep-001"
      ),
      now: fixedDate("2026-01-01T00:00:08Z")
    )
    try expect(!deepSearch.adapterExecuted, "Exa deep search should not execute before approval")
    try expect(
      deepSearch.execution.status == .pendingApproval,
      "Exa deep search should create pending approval execution")
    try expect(
      deepSearch.approval?.metadata["permission"]
        == .string(ProviderActionPermission.approvalRequired.rawValue),
      "Exa deep search approval should retain permission evidence")

    let export = try services.providerActionBroker.execute(
      context: owner,
      request: MarketplaceProviderActionBrokerRequest(
        appIdOrSlug: app.id,
        actionKey: "exa.result.export",
        payload: ["destination": .string("external")],
        installId: install.id,
        idempotencyKey: "exa-foundation-export-001"
      ),
      now: fixedDate("2026-01-01T00:00:09Z")
    )
    try expect(!export.adapterExecuted, "Exa export should not execute")
    try expect(export.execution.status == .blocked, "Exa export should persist blocked execution")
    try expect(
      export.execution.providerError?["reason"]?.string?.contains("privacy") == true,
      "Exa export should explain privacy block")

    let encoded = String(data: try JSONEncoder().encode(snapshot), encoding: .utf8) ?? ""
    try expect(
      !encoded.contains("exa_search_foundation_secret"),
      "Exa foundation snapshot should not contain API key values")
    try expect(
      encoded.contains("secret-reference-only"),
      "Exa foundation snapshot should retain credential redaction evidence")
  }

