  }

  private static func testLinkedInProviderFoundationEnforcesLimitedSocialPolicy() throws {
    final class StubLinkedInHTTPClient: LinkedInProviderHTTPClient, @unchecked Sendable {
      private let lock = NSLock()
      private var responsesByRequest: [String: [LinkedInProviderHTTPResponse]]

      init(responsesByRequest: [String: [LinkedInProviderHTTPResponse]]) {
        self.responsesByRequest = responsesByRequest
      }

      func send(_ request: LinkedInProviderHTTPRequest) throws -> LinkedInProviderHTTPResponse {
        let key = "\(request.method) \(request.url.path)"
        lock.lock()
        defer { lock.unlock() }
        guard var responses = responsesByRequest[key], !responses.isEmpty else {
          throw MarketplaceProviderActionAdapterFailure(
            code: "stub_missing_linkedin_response",
            message: "No stubbed LinkedIn response for \(key)."
          )
        }
        let response = responses.removeFirst()
        responsesByRequest[key] = responses
        if request.method == "POST", request.body == nil {
          throw MarketplaceProviderActionAdapterFailure(
            code: "stub_missing_linkedin_body",
            message: "LinkedIn write requests must include a JSON body."
          )
        }
        return response
      }
    }

    func linkedInResponse(
      _ text: String,
      status: Int = 200,
      headers: [String: String] = [:]
    ) -> LinkedInProviderHTTPResponse {
      LinkedInProviderHTTPResponse(statusCode: status, headers: headers, body: Data(text.utf8))
    }

    let services = try makeServices()
    let workspace = try unwrap(services.data.getAppState().activeWorkspace, "missing workspace")
    let owner = Self.context(
      roles: [.owner], workspaceId: workspace.id, correlationId: "linkedin-foundation-owner-001")
    let member = Self.context(
      roles: [.member], workspaceId: workspace.id, correlationId: "linkedin-foundation-member-001")

    let snapshot = try services.providerFoundations.registerLinkedInFoundation(
      context: owner,
      now: fixedDate("2026-01-01T00:00:00Z")
    )
    try expect(snapshot.appSlug == "linkedin", "LinkedIn foundation should target LinkedIn")
    try expect(
      snapshot.providerFamily == "public-social",
      "LinkedIn foundation should mark the provider as public-social")
    try expect(
      snapshot.connectionMode == "user-owned-linkedin-manual-member-token",
