    try expect(
      snapshot.credentials.map(\.fieldKey) == [
        "linkedin_client_id", "linkedin_client_secret", "linkedin_access_token",
        "linkedin_refresh_token",
      ],
      "LinkedIn foundation should list app credentials, access token, and optional refresh token credentials"
    )
    try expect(
      snapshot.privacyPolicy["memberPublishing"]
        == .string("approval_required_or_direct_write_by_policy"),
