    try expect(
      encoded.contains("secret-reference-only"),
      "LinkedIn foundation snapshot should retain credential redaction evidence")
  }

  private static func testGmailProviderFoundationEnforcesEmailPolicy() throws {
    let services = try makeServices()
    let workspace = try unwrap(services.data.getAppState().activeWorkspace, "missing workspace")
    let owner = Self.context(
      roles: [.owner], workspaceId: workspace.id, correlationId: "gmail-foundation-owner-001")
    let member = Self.context(
      roles: [.member], workspaceId: workspace.id, correlationId: "gmail-foundation-member-001")

    let snapshot = try services.providerFoundations.registerGmailFoundation(
      context: owner,
      now: fixedDate("2026-01-01T00:00:00Z")
    )
    try expect(snapshot.appSlug == "gmail", "Gmail foundation should target Gmail")
    try expect(
      snapshot.providerFamily == "email", "Gmail foundation should mark the provider as email")
    try expect(
      snapshot.connectionMode == "relay-owned-google-oauth-gmail-confidential-web-server",
      "Gmail foundation should use Relay-owned confidential Google OAuth mode")
    try expect(
      snapshot.credentialOwnership == .relayOwned && snapshot.userOwnedCredentialsRequired == false,
      "Gmail foundation should declare Relay-owned credentials")
    try expect(
      snapshot.supportedPolicyPresets == [
        .approvalRequired, .allowDirectWrites, .readOnly, .blocked,
      ], "Gmail foundation should advertise all four authority presets")
    try expect(
      snapshot.credentials.map(\.fieldKey) == [
        "google_oauth_refresh_token",
        "google_oauth_access_token",
        "gmail_google_account",
      ],
      "Gmail foundation should list Google OAuth credential fields"
    )
    let credentialByKey = Dictionary(
      uniqueKeysWithValues: snapshot.credentials.map { ($0.fieldKey, $0) })
    try expect(
      credentialByKey["google_oauth_refresh_token"]?.required == true,
      "Gmail foundation should require the Google OAuth refresh token")
    try expect(
      credentialByKey["google_oauth_access_token"]?.required == true,
      "Gmail foundation should require the broker-issued access token")
    try expect(
      credentialByKey["gmail_google_account"]?.required == true,
      "Gmail foundation should require authorized account metadata")
    try expect(
      snapshot.privacyPolicy["messageBodies"] == .string("task_context_only"),
      "Gmail message bodies should stay task-scoped")
    try expect(
      snapshot.privacyPolicy["sending"] == .string("approval_required_or_direct_write_by_policy"),
      "Gmail sending should default to approval while allowing explicit direct-write policy")
    try expect(
      snapshot.privacyPolicy["deleteModifySettings"] == .string("blocked"),
      "Gmail destructive mailbox operations should be blocked")
    try expect(
      snapshot.defaultPolicyPreset == .approvalRequired,
      "Gmail foundation should default to approval-required policy")
    try expect(
      snapshot.blockedActionKeys == ["gmail.message.delete", "gmail.settings.modify"],
      "Gmail destructive actions should be blocked in the foundation")
    try expect(
      snapshot.agentFacingWrapperToolNames.count == 6,
      "Gmail foundation should expose six safe wrapper names")
    try expect(
      snapshot.agentFacingWrapperToolNames.allSatisfy { $0.hasPrefix("relay_provider_gmail_") },
      "Gmail wrapper names should use Relay provider namespace")

    let actionByKey = Dictionary(uniqueKeysWithValues: snapshot.actions.map { ($0.actionKey, $0) })
    try expect(
      actionByKey["gmail.messages.search"]?.policyPermission == .allowed,
      "Gmail search should be allowed")
    try expect(
      actionByKey["gmail.message.read"]?.policyPermission == .allowed,
      "Gmail read should be allowed")
    try expect(
      actionByKey["gmail.labels.list"]?.policyPermission == .allowed,
      "Gmail labels should be allowed")
    try expect(
      actionByKey["gmail.email.prepare"]?.policyPermission == .allowed,
      "Gmail local prepare should be allowed")
    try expect(
      actionByKey["gmail.draft.create"]?.policyPermission == .approvalRequired,
      "Gmail draft creation should require approval")
    try expect(
      actionByKey["gmail.email.send"]?.policyPermission == .approvalRequired,
      "Gmail send should require approval")
    try expect(
      actionByKey["gmail.message.delete"]?.policyPermission == .blocked,
      "Gmail delete should be blocked")
    try expect(
      actionByKey["gmail.settings.modify"]?.policyPermission == .blocked,
      "Gmail settings modification should be blocked")

    let directPolicy = try services.providerActionPolicies.compilePolicyMap(
      context: owner,
      appIdOrSlug: snapshot.appId,
      preset: .allowDirectWrites, acknowledgeDangerousPolicy: true,
      now: fixedDate("2026-01-01T00:00:00Z")
    )
    try expect(
      directPolicy.permissions["gmail.messages.search"] == .allowed,
      "direct-write Gmail policy should keep search allowed")
    try expect(
      directPolicy.permissions["gmail.message.read"] == .allowed,
      "direct-write Gmail policy should keep message read allowed")
    try expect(
      directPolicy.permissions["gmail.labels.list"] == .allowed,
      "direct-write Gmail policy should keep labels allowed")
    try expect(
      directPolicy.permissions["gmail.email.prepare"] == .allowed,
      "direct-write Gmail policy should keep local preparation allowed")
    try expect(
      directPolicy.permissions["gmail.draft.create"] == .autoExecute,
      "direct-write Gmail policy should auto-execute draft creation")
    try expect(
      directPolicy.permissions["gmail.email.send"] == .autoExecute,
      "direct-write Gmail policy should auto-execute sends")
    try expect(
      directPolicy.permissions["gmail.message.delete"] == .blocked,
      "direct-write Gmail policy should keep deletes blocked")
    try expect(
      directPolicy.permissions["gmail.settings.modify"] == .blocked,
      "direct-write Gmail policy should keep settings changes blocked")

    let app = try unwrap(
      try services.data.getMarketplaceCatalogApp(
        workspaceId: workspace.id, appIdOrSlug: snapshot.appId),
      "missing Gmail app"
    )
    let connection = try services.providerConnections.saveGmailOAuthCredentials(
      context: owner,
      appIdOrSlug: app.id,
      clientId: "gmail_foundation_client_id_secret",
      clientSecret: "gmail_foundation_client_secret",
      refreshToken: "gmail_foundation_refresh_secret",
      accessToken: "gmail_foundation_access_secret",
      accountEmail: "foundation.gmail@example.com",
      displayName: "Gmail Foundation Account",
      now: fixedDate("2026-01-01T00:00:01Z")
    )
    let agent = try createServiceAgent(services: services, workspaceId: workspace.id)
    let unassignedAgent = try createServiceAgent(services: services, workspaceId: workspace.id)
    let install = try services.marketplaceInstalls.createInstall(
      context: owner,
      request: installRequest(
        id: "minreq-gmail-foundation-001",
        workspaceId: workspace.id,
        app: app,
        connectionId: connection.id,
        agent: agent,
        roleId: app.roleManifest.primaryRole,
        selectedCapabilities: app.capabilities,
        riskAcknowledged: true
      ),
      now: fixedDate("2026-01-01T00:00:02Z")
    )

    let surface = try services.providerWrapperTools.compileSurface(
      context: member,
      appIdOrSlug: app.id,
      installId: install.id,
      agentId: agent.id,
      now: fixedDate("2026-01-01T00:00:03Z")
    )
    try expect(
      surface.tools.count == 6, "assigned Gmail install should expose six safe wrapper tools")
    try expect(
      surface.tools.contains { $0.displayName == "Search messages" && $0.readOnly },
      "Gmail search should compile as read-only wrapper")
    try expect(
      surface.tools.contains { $0.displayName == "Read message" && $0.readOnly },
      "Gmail read should compile as read-only wrapper")
    try expect(
      surface.tools.contains { $0.displayName == "List labels" && $0.readOnly },
      "Gmail labels should compile as read-only wrapper")
    try expect(
      surface.tools.contains { $0.displayName == "Prepare email" && $0.permission == .allowed },
      "Gmail prepare should compile as an allowed local wrapper")
    try expect(
      surface.tools.contains { $0.displayName == "Create draft" && $0.requiresApproval },
      "Gmail draft creation should compile as approval wrapper")
    try expect(
      surface.tools.contains { $0.displayName == "Send email" && $0.requiresApproval },
      "Gmail send should compile as approval wrapper")
    try expect(
      !surface.tools.contains { ["Delete message", "Modify settings"].contains($0.displayName) },
      "Gmail blocked actions should not become agent-facing wrappers")
    try expect(
      surface.diagnostics.blockedActionCount == 2,
      "Gmail wrapper diagnostics should count blocked destructive actions")

    let unassignedSurface = try services.providerWrapperTools.compileSurface(
      context: owner,
      appIdOrSlug: app.id,
      agentId: unassignedAgent.id,
      now: fixedDate("2026-01-01T00:00:04Z")
    )
    try expect(
      unassignedSurface.tools.isEmpty, "unassigned agent should not receive Gmail wrapper tools")
    try expect(
      !unassignedSurface.diagnostics.assignedAgentReady,
      "unassigned Gmail wrapper surface should report missing assignment")

    let fakeGmailBroker = MarketplaceProviderActionBrokerService(
      data: services.data,
      approvals: services.providerActionApprovals,
      auditSecurity: services.auditSecurity,
      adapter: RoutingMarketplaceProviderActionAdapter(
        gmailAdapter: GmailProviderActionAdapter(client: FakeGmailProviderActionClient())
      )
    )
    let prepare = try fakeGmailBroker.execute(
      context: owner,
      request: MarketplaceProviderActionBrokerRequest(
        appIdOrSlug: app.id,
        actionKey: "gmail.email.prepare",
        payload: [
          "to": .array([.string("recipient@example.com")]),
          "subject": .string("Relay Gmail draft"),
          "body": .string("Prepared but not sent."),
        ],
        installId: install.id,
        idempotencyKey: "gmail-foundation-prepare-001"
      ),
      now: fixedDate("2026-01-01T00:00:05Z")
    )
    try expect(prepare.adapterExecuted, "allowed Gmail prepare should execute through broker")
    try expect(
      prepare.execution.status == .succeeded,
      "allowed Gmail prepare should persist succeeded execution")
    try expect(
      prepare.execution.providerResult?["sent"] == .bool(false),
      "Gmail prepare should not send email")

    let search = try fakeGmailBroker.execute(
      context: owner,
      request: MarketplaceProviderActionBrokerRequest(
        appIdOrSlug: app.id,
        actionKey: "gmail.messages.search",
        payload: ["query": .string("from:relay@example.com newer_than:7d")],
        installId: install.id,
        idempotencyKey: "gmail-foundation-search-001"
      ),
      now: fixedDate("2026-01-01T00:00:06Z")
    )
    try expect(search.adapterExecuted, "allowed Gmail search should execute through broker")
    try expect(
      search.execution.status == .succeeded,
      "allowed Gmail search should persist succeeded execution")

    let sendPayload: JSONRecord = [
      "to": .string("recipient@example.com"),
      "subject": .string("Approval-gated Gmail send"),
      "body": .string("Send only after approval."),
    ]
    let pendingSend = try fakeGmailBroker.execute(
      context: owner,
      request: MarketplaceProviderActionBrokerRequest(
        appIdOrSlug: app.id,
        actionKey: "gmail.email.send",
        payload: sendPayload,
        installId: install.id,
        idempotencyKey: "gmail-foundation-send-001"
      ),
      now: fixedDate("2026-01-01T00:00:07Z")
    )
    try expect(!pendingSend.adapterExecuted, "Gmail send should not execute before approval")
    try expect(
      pendingSend.execution.status == .pendingApproval,
      "Gmail send should create pending approval execution")
    let approval = try unwrap(pendingSend.approval, "Gmail send should create approval")
    let approved = try services.providerActionApprovals.approve(
      context: owner,
      approvalId: approval.id,
      approvedPayload: sendPayload,
      now: fixedDate("2026-01-01T00:00:08Z")
    )
    let approvedSend = try fakeGmailBroker.execute(
      context: owner,
      request: MarketplaceProviderActionBrokerRequest(
        appIdOrSlug: app.id,
        actionKey: "gmail.email.send",
        payload: sendPayload,
        installId: install.id,
        approvalId: approved.id,
        idempotencyKey: "gmail-foundation-send-approved-001"
      ),
      now: fixedDate("2026-01-01T00:00:09Z")
    )
    try expect(approvedSend.adapterExecuted, "approved Gmail send should execute through broker")
    try expect(
      approvedSend.execution.status == .succeeded,
      "approved Gmail send should persist succeeded execution")
    try expect(
      approvedSend.execution.providerResult?["sent"] == .bool(true),
      "approved Gmail send should retain fake sent evidence")

    _ = try services.providerActionPolicies.compilePolicyMap(
      context: owner,
      appIdOrSlug: snapshot.appId,
      preset: .allowDirectWrites, acknowledgeDangerousPolicy: true,
      connectionId: connection.id,
      installId: install.id,
      agentId: agent.id,
      now: fixedDate("2026-01-01T00:00:10Z")
    )
    let directSurface = try services.providerWrapperTools.compileSurface(
      context: member,
      appIdOrSlug: app.id,
      installId: install.id,
      agentId: agent.id,
      now: fixedDate("2026-01-01T00:00:11Z")
    )
    try expect(
      directSurface.tools.contains {
        $0.displayName == "Create draft" && $0.autoExecutes && !$0.requiresApproval
      }, "direct-write Gmail draft wrapper should auto-execute without approval")
    try expect(
      directSurface.tools.contains {
        $0.displayName == "Send email" && $0.autoExecutes && !$0.requiresApproval
      }, "direct-write Gmail send wrapper should auto-execute without approval")
    try expect(
      directSurface.diagnostics.autoExecuteCount == 2,
      "direct-write Gmail diagnostics should count draft and send auto-execute wrappers")

    let directDraft = try fakeGmailBroker.execute(
      context: owner,
      request: MarketplaceProviderActionBrokerRequest(
        appIdOrSlug: app.id,
        actionKey: "gmail.draft.create",
        payload: [
          "to": .string("recipient@example.com"),
          "subject": .string("Direct-write Gmail draft"),
          "body": .string("Create immediately under explicit direct-write authority."),
        ],
        connectionId: connection.id,
        installId: install.id,
        agentId: agent.id,
        idempotencyKey: "gmail-foundation-direct-draft-001"
      ),
      now: fixedDate("2026-01-01T00:00:12Z")
    )
    try expect(
      directDraft.adapterExecuted,
      "direct-write Gmail draft should execute immediately through broker")
    try expect(
      directDraft.execution.permission == .autoExecute,
      "direct-write Gmail draft should retain auto-execute permission")
    try expect(
      directDraft.execution.status == .succeeded,
      "direct-write Gmail draft should persist succeeded execution")
    try expect(
      directDraft.execution.providerResult?["draftId"] != nil,
      "direct-write Gmail draft should retain fake draft evidence")

    let directSend = try fakeGmailBroker.execute(
      context: owner,
      request: MarketplaceProviderActionBrokerRequest(
        appIdOrSlug: app.id,
        actionKey: "gmail.email.send",
        payload: [
          "to": .string("recipient@example.com"),
          "subject": .string("Direct-write Gmail send"),
          "body": .string("Send immediately under explicit direct-write authority."),
        ],
        connectionId: connection.id,
        installId: install.id,
        agentId: agent.id,
        idempotencyKey: "gmail-foundation-direct-send-001"
      ),
      now: fixedDate("2026-01-01T00:00:13Z")
    )
    try expect(
      directSend.adapterExecuted,
      "direct-write Gmail send should execute immediately through broker")
    try expect(
      directSend.execution.permission == .autoExecute,
      "direct-write Gmail send should retain auto-execute permission")
    try expect(
      directSend.execution.status == .succeeded,
      "direct-write Gmail send should persist succeeded execution")
    try expect(
      directSend.execution.providerResult?["sent"] == .bool(true),
      "direct-write Gmail send should retain fake sent evidence")

    let blockedDelete = try fakeGmailBroker.execute(
      context: owner,
      request: MarketplaceProviderActionBrokerRequest(
        appIdOrSlug: app.id,
        actionKey: "gmail.message.delete",
        payload: ["messageId": .string("msg-001")],
        installId: install.id,
        idempotencyKey: "gmail-foundation-delete-001"
      ),
      now: fixedDate("2026-01-01T00:00:14Z")
    )
    try expect(!blockedDelete.adapterExecuted, "Gmail delete should not execute")
    try expect(
      blockedDelete.execution.status == .blocked, "Gmail delete should persist blocked execution")

    let readOnly = try services.providerActionPolicies.compilePolicyMap(
      context: owner,
      appIdOrSlug: snapshot.appId,
      preset: .readOnly,
      now: fixedDate("2026-01-01T00:00:15Z")
    )
    try expect(
      readOnly.permissions["gmail.messages.search"] == .allowed,
      "read-only Gmail policy should allow search")
    try expect(
      readOnly.permissions["gmail.message.read"] == .allowed,
      "read-only Gmail policy should allow message read")
    try expect(
      readOnly.permissions["gmail.labels.list"] == .allowed,
      "read-only Gmail policy should allow label read")
    try expect(
      readOnly.permissions["gmail.email.prepare"] == .allowed,
      "read-only Gmail policy should allow local preparation")
    try expect(
      readOnly.permissions["gmail.draft.create"] == .blocked,
      "read-only Gmail policy should block draft creation")
    try expect(
      readOnly.permissions["gmail.email.send"] == .blocked,
      "read-only Gmail policy should block sending")
    try expect(
      readOnly.permissions["gmail.message.delete"] == .blocked,
      "read-only Gmail policy should block deletes")
    try expect(
      readOnly.permissions["gmail.settings.modify"] == .blocked,
      "read-only Gmail policy should block settings changes")

    let encoded = String(data: try JSONEncoder().encode(snapshot), encoding: .utf8) ?? ""
    try expect(
      !encoded.contains("gmail_foundation_refresh_secret"),
      "Gmail foundation snapshot should not contain refresh token values")
    try expect(
      !encoded.contains("gmail_foundation_access_secret"),
      "Gmail foundation snapshot should not contain access token values")
    try expect(
      encoded.contains("secret-reference-only"),
      "Gmail foundation snapshot should retain credential redaction evidence")
  }

  private static func testGoogleDocsProviderFoundationEnforcesDocumentPolicy() throws {
    let services = try makeServices()
    let workspace = try unwrap(services.data.getAppState().activeWorkspace, "missing workspace")
    let owner = Self.context(
      roles: [.owner], workspaceId: workspace.id, correlationId: "google-docs-foundation-owner-001")
    let member = Self.context(
      roles: [.member], workspaceId: workspace.id,
      correlationId: "google-docs-foundation-member-001")

    do {
      _ = try services.providerFoundations.registerGoogleDocsFoundation(
        context: member,
        now: fixedDate("2026-01-01T00:00:00Z")
      )
      throw ServiceTestFailure("member unexpectedly registered Google Docs provider foundation")
    } catch let denied as ServiceGuardResult {
      try expect(
        denied.reasonCode == .authorityRoleRequired,
        "Google Docs foundation registration should require owner/admin authority")
    }

    let snapshot = try services.providerFoundations.registerGoogleDocsFoundation(
      context: owner,
      now: fixedDate("2026-01-01T00:00:01Z")
    )
    try expect(
      snapshot.appSlug == "google-docs", "Google Docs foundation should target Google Docs")
    try expect(
      snapshot.providerFamily == "documents",
      "Google Docs foundation should mark the provider as documents")
    try expect(
      snapshot.connectionMode == "relay-owned-google-oauth-docs",
      "Google Docs foundation should use Relay-owned Google OAuth Docs mode")
    try expect(
      snapshot.credentialOwnership == .relayOwned,
      "Google Docs foundation should use Relay-owned credentials")
    try expect(
      !snapshot.userOwnedCredentialsRequired,
      "Google Docs foundation should not require user-owned credential entry")
    try expect(
      snapshot.supportedPolicyPresets == [
        .approvalRequired, .allowDirectWrites, .readOnly, .blocked,
      ], "Google Docs foundation should advertise all four authority presets")
    try expect(
      snapshot.defaultPolicyPreset == .approvalRequired,
      "Google Docs foundation should default to approval-required policy")
    try expect(
      snapshot.adapterBoundary == "brokered-native-google-docs-api-adapter",
      "Google Docs foundation should keep Docs API access behind the broker boundary")
    try expect(
      snapshot.actionMapVersion == "google-docs-v1",
      "Google Docs foundation should identify the V1 action map")
    try expect(
      !snapshot.rawProviderToolExposure,
      "Google Docs foundation should not expose raw provider or MCP tools")
    try expect(
      snapshot.suppressedRawProviderToolCount == 12,
      "Google Docs foundation should count safe and blocked V1 provider actions as suppressed raw tools"
    )

    let app = try unwrap(
      try services.data.getMarketplaceCatalogApp(
        workspaceId: workspace.id, appIdOrSlug: snapshot.appId),
      "missing Google Docs app"
    )
    try expect(app.slug == "google-docs", "Google Docs catalog app should retain the intended slug")
    try expect(
      app.name == "Google Docs", "Google Docs catalog app should retain the canonical app name")
    try expect(
      app.websiteURL == "https://docs.google.com/",
      "Google Docs catalog app should retain the official website")
    try expect(
      app.docsURL == "https://developers.google.com/workspace/docs/api/auth",
      "Google Docs catalog app should retain official developer docs")
    try expect(
      !app.readOnly,
      "Google Docs catalog app should remain write-capable for V1 create/update actions")

    try expect(
      snapshot.credentials.map(\.fieldKey) == [
        "google_docs_oauth_access_token",
        "google_docs_oauth_refresh_token",
        "google_docs_account",
      ],
      "Google Docs foundation should list separate broker token and account fields"
    )
    let credentialByKey = Dictionary(
      uniqueKeysWithValues: snapshot.credentials.map { ($0.fieldKey, $0) })
    try expect(
      credentialByKey["google_docs_oauth_refresh_token"]?.required == true,
      "Google Docs refresh token should be required")
    try expect(
      credentialByKey["google_docs_oauth_access_token"]?.required == true,
      "Google Docs access token should be required")
    try expect(
      credentialByKey["google_docs_account"]?.secretStorage == "metadata-only",
      "Google Docs account should be metadata-only")
    try expect(
      credentialByKey["google_docs_oauth_refresh_token"]?.secretStorage
        == "keychain-reference-only", "Google Docs refresh token should be Keychain-reference only")
    try expect(
      snapshot.credentials.allSatisfy { !$0.userOwnedRequired },
      "Google Docs credentials should be supplied by Relay-owned OAuth instead of user-owned entry")

    try expect(
      snapshot.budgetPolicy["maxWrapperTools"] == .number(4),
      "Google Docs foundation should budget four wrapper tools")
    try expect(
      snapshot.budgetPolicy["promptSummaryMaxCharacters"] == .number(1200),
      "Google Docs prompt summary budget should be retained")
    try expect(
      snapshot.budgetPolicy["maxBodyChars"] == .number(8000),
      "Google Docs body text should be bounded")
    try expect(
      snapshot.privacyPolicy["documentContent"] == .string("task_context_only"),
      "Google Docs document content should stay task-scoped")
    try expect(
      snapshot.privacyPolicy["semanticReads"] == .string("document_id_or_url_bounded_text"),
      "Google Docs semantic reads should retain the V1 contract")
    try expect(
      snapshot.privacyPolicy["writes"] == .string("approval_required_or_direct_write_by_policy"),
      "Google Docs writes should default to approval while allowing explicit Direct writes")
    try expect(
      snapshot.privacyPolicy["driveSearch"] == .string("blocked"),
      "Google Docs broad Drive search should be blocked")
    try expect(
      snapshot.privacyPolicy["exportsDownloads"] == .string("blocked"),
      "Google Docs exports should be blocked")
    try expect(
      snapshot.privacyPolicy["commentsSuggestions"] == .string("blocked"),
      "Google Docs comments/suggestions should be blocked")
    try expect(
      snapshot.privacyPolicy["sharingPermissions"] == .string("blocked"),
      "Google Docs sharing and permission actions should be blocked")
    try expect(
      snapshot.privacyPolicy["rawMCPExposure"] == .string("blocked"),
      "Google Docs raw MCP exposure should be blocked")
    try expect(
      snapshot.privacyPolicy["relayOwnedGoogleApp"] == .string("supported"),
      "Relay-owned Google app behavior should be supported")
    try expect(
      snapshot.privacyPolicy["rawCredentials"] == .string("secret-reference-only"),
      "Google Docs raw credentials should stay behind secret references")

    let expectedSafeActions: Set<String> = [
      "google_docs_read_document",
      "google_docs_prepare_document_update",
      "google_docs_create_document",
      "google_docs_apply_document_update",
    ]
    let expectedBlockedActions: Set<String> = [
      "google_docs_drive_search",
      "google_docs_export_document",
      "google_docs_comments_suggestions",
      "google_docs_permissions_sharing",
      "google_docs_delete_or_move_document",
      "google_docs_domain_wide_delegation",
      "google_docs_raw_mcp_call",
      "google_docs_media_extraction",
    ]
    let actionByKey = Dictionary(uniqueKeysWithValues: snapshot.actions.map { ($0.actionKey, $0) })
    try expect(
      Set(actionByKey.keys) == expectedSafeActions.union(expectedBlockedActions),
      "Google Docs foundation should register the complete V1 safe and blocked action map")
    try expect(
      actionByKey["google_docs_read_document"]?.policyPermission == .allowed,
      "Google Docs document read should be allowed")
    try expect(
      actionByKey["google_docs_prepare_document_update"]?.policyPermission == .allowed,
      "Google Docs prepare should be allowed")
    try expect(
      actionByKey["google_docs_create_document"]?.policyPermission == .approvalRequired,
      "Google Docs create document should require approval")
    try expect(
      actionByKey["google_docs_apply_document_update"]?.policyPermission == .approvalRequired,
      "Google Docs apply update should require approval")
    for actionKey in expectedBlockedActions {
      try expect(
        actionByKey[actionKey]?.policyPermission == .blocked,
        "Google Docs blocked action \(actionKey) should stay blocked")
      try expect(
        actionByKey[actionKey]?.wrapperToolName == nil,
        "Google Docs blocked action \(actionKey) should not have an agent-facing wrapper")
    }
    try expect(
      Set(snapshot.blockedActionKeys) == expectedBlockedActions,
      "Google Docs foundation should expose all blocked/deferred V1 actions")

    try expect(
      snapshot.agentFacingWrapperToolNames.count == 4,
      "Google Docs foundation should expose four safe wrapper names")
    try expect(
      snapshot.agentFacingWrapperToolNames.allSatisfy {
        $0.hasPrefix("relay_provider_google_docs_")
      }, "Google Docs wrapper names should use Relay provider namespace")
    let wrapperNames = snapshot.agentFacingWrapperToolNames.joined(separator: "\n").lowercased()
    for leaked in [
      "google_docs_drive_search",
      "google_docs_export_document",
      "google_docs_permissions_sharing",
      "google_docs_raw_mcp_call",
      "raw_mcp",
      "oauth",
