    try expect(
      snapshot.privacyPolicy["broadExport"] == .string("blocked"),
      "Google Drive broad export should be blocked")
    try expect(
      snapshot.privacyPolicy["rawMCPExposure"] == .string("blocked"),
      "Google Drive raw MCP exposure should be blocked")
    try expect(
      snapshot.privacyPolicy["relayOwnedGoogleApp"] == .string("supported"),
      "Relay-owned Google app behavior should be supported")
    try expect(
      snapshot.privacyPolicy["rawCredentials"] == .string("secret-reference-only"),
      "Google Drive raw credentials should stay behind secret references")

    let expectedSafeActions: Set<String> = [
      "google_drive_search_files",
      "google_drive_get_file_metadata",
      "google_drive_read_file_content",
      "google_drive_prepare_file",
      "google_drive_create_file",
      "google_drive_copy_file",
    ]
    let expectedBlockedActions: Set<String> = [
      "google_drive_delete_file",
      "google_drive_share_file",
      "google_drive_export_all",
      "google_drive_update_file",
      "google_drive_raw_mcp_call",
      "google_drive_domain_wide_delegation",
    ]
    let actionByKey = Dictionary(uniqueKeysWithValues: snapshot.actions.map { ($0.actionKey, $0) })
    try expect(
      Set(actionByKey.keys) == expectedSafeActions.union(expectedBlockedActions),
      "Google Drive foundation should register the complete V1 safe and blocked action map")
    try expect(
      actionByKey["google_drive_search_files"]?.policyPermission == .allowed,
      "Google Drive search should be allowed")
    try expect(
      actionByKey["google_drive_get_file_metadata"]?.policyPermission == .allowed,
      "Google Drive metadata should be allowed")
    try expect(
      actionByKey["google_drive_read_file_content"]?.policyPermission == .allowed,
      "Google Drive bounded content read should be allowed")
    try expect(
      actionByKey["google_drive_prepare_file"]?.policyPermission == .allowed,
      "Google Drive prepare should be allowed")
    try expect(
      actionByKey["google_drive_create_file"]?.policyPermission == .approvalRequired,
