  private static func testMicrosoftClarityProviderFoundationEnforcesAnalyticsPolicy() throws {
    final class StubMicrosoftClarityHTTPClient: MicrosoftClarityProviderHTTPClient,
      @unchecked Sendable
    {
      private let lock = NSLock()
      private var responses: [MicrosoftClarityProviderHTTPResponse]
      private var requests: [MicrosoftClarityProviderHTTPRequest] = []

      init(responses: [MicrosoftClarityProviderHTTPResponse]) {
        self.responses = responses
      }

      func send(_ request: MicrosoftClarityProviderHTTPRequest) throws
        -> MicrosoftClarityProviderHTTPResponse
      {
        lock.lock()
        defer { lock.unlock() }
        requests.append(request)
        guard !responses.isEmpty else {
          throw MarketplaceProviderActionAdapterFailure(
            code: "stub_missing_microsoft_clarity_response",
            message: "No stubbed Microsoft Clarity response."
          )
        }
        return responses.removeFirst()
      }

      func capturedRequests() -> [MicrosoftClarityProviderHTTPRequest] {
        lock.lock()
        defer { lock.unlock() }
        return requests
      }
    }

    func response(_ text: String, status: Int = 200) -> MicrosoftClarityProviderHTTPResponse {
      MicrosoftClarityProviderHTTPResponse(statusCode: status, body: Data(text.utf8))
    }

