          httpClient: stub
        )
      )
    )
    let executed = try liveBroker.execute(
      context: owner,
      request: MarketplaceProviderActionBrokerRequest(
        appIdOrSlug: app.id,
        actionKey: "microsoft_clarity_get_project_live_insights",
        payload: [
          "numOfDays": .number(2),
          "dimensions": .array([.string("URL"), .string("OS")]),
          "maxRowsPerMetric": .number(1),
          "redactUrls": .bool(true),
        ],
        connectionId: connection.id,
        installId: install.id,
        agentId: agent.id,
        idempotencyKey: "microsoft-clarity-foundation-live-read-001",
        dispatchId: "rtd-microsoft-clarity-foundation-read-001"
      ),
      now: fixedDate("2026-01-01T00:00:07Z")
    )
    try expect(
      executed.adapterExecuted,
      "Microsoft Clarity live read should execute through the brokered adapter")
    try expect(
      executed.execution.status == .succeeded,
      "Microsoft Clarity live read should persist a succeeded execution")
    let providerResult = try unwrap(
      executed.execution.providerResult, "missing Microsoft Clarity provider result")
    try expect(
      providerResult["clientMode"] == .string("live-microsoft-clarity-data-export-api"),
      "Microsoft Clarity result should identify the live Data Export API adapter")
    try expect(
      providerResult["liveProvider"] == .bool(true),
      "Microsoft Clarity result should mark live provider execution")
    try expect(
      providerResult["fakeAdapter"] == .bool(false),
      "Microsoft Clarity result should not use the fake adapter")
    try expect(
      providerResult["simulated"] == .bool(false),
      "Microsoft Clarity result should not be simulated")
    try expect(
      providerResult["dayWindow"] == .number(2),
      "Microsoft Clarity result should retain the requested day window")
    try expect(
      providerResult["rowCount"] == .number(2),
      "Microsoft Clarity result should retain source row count")
    try expect(
      providerResult["returnedRowCount"] == .number(1),
      "Microsoft Clarity result should retain bounded returned row count")
    try expect(
      providerResult["truncated"] == .bool(true),
      "Microsoft Clarity result should report truncated rows")
    let metricGroups = arrayValue(providerResult["metricGroups"])
    let firstGroup = try unwrap(
      objectValue(metricGroups.first), "missing Microsoft Clarity metric group")
    let firstRow = try unwrap(
      objectValue(arrayValue(firstGroup["information"]).first),
      "missing Microsoft Clarity metric row")
    try expect(
      firstRow["URL"] == .string("https://example.com/landing"),
      "Microsoft Clarity URL values should be redacted to origin and path")

    let liveBridge = MarketplaceRuntimeToolBridgeService(
      data: services.data,
      runtimeMounts: services.marketplaceRuntimeMounts,
      broker: liveBroker
    )
    let bridgeResult = try liveBridge.execute(
      toolName: "relay_microsoft_clarity_get_project_live_insights",
      payload: [
        "numOfDays": .number(1),
        "dimension1": .string("OS"),
        "maxRowsPerMetric": .number(1),
      ],
      runtime: MarketplaceRuntimeToolExecutionContext(
        agentId: agent.id,
        workspaceId: workspace.id,
        runtimeType: agent.binding.runtimeType,
        dispatchId: "rtd-microsoft-clarity-runtime-read-001",
        threadId: "thr-microsoft-clarity-runtime-read-001",
        runtimeSessionId: "rts-microsoft-clarity-runtime-read-001",
        correlationId: "microsoft-clarity-runtime-read-001"
      ),
      now: fixedDate("2026-01-01T00:00:08Z")
    )
    try expect(
      bridgeResult["toolName"] == .string("relay_microsoft_clarity_get_project_live_insights"),
      "Microsoft Clarity runtime bridge should echo the wrapper tool name")
    try expect(
      bridgeResult["appSlug"] == .string("microsoft-clarity"),
      "Microsoft Clarity runtime bridge should map wrapper tool back to the app")
    try expect(
      bridgeResult["adapterExecuted"] == .bool(true),
      "Microsoft Clarity runtime bridge should execute through the brokered adapter")
    try expect(
      objectValue(bridgeResult["providerResult"])?["fakeAdapter"] == .bool(false),
      "Microsoft Clarity runtime bridge should return live adapter metadata")

    let captured = stub.capturedRequests()
    try expect(
      captured.count == 2,
      "Microsoft Clarity stub should receive one direct broker request and one runtime bridge request"
    )
    let firstRequest = try unwrap(captured.first, "missing captured Microsoft Clarity request")
    let firstQuery =
      URLComponents(url: firstRequest.url, resolvingAgainstBaseURL: false)?.queryItems ?? []
    try expect(
      firstRequest.method == "GET",
      "Microsoft Clarity adapter should call the Data Export API with GET")
    try expect(
      firstRequest.url.host == "www.clarity.ms",
      "Microsoft Clarity adapter should call the official Clarity API host")
    try expect(
      firstRequest.url.path == "/export-data/api/v1/project-live-insights",
      "Microsoft Clarity adapter should call the official live-insights endpoint")
    try expect(
      firstRequest.headers["Authorization"] == "Bearer \(token)",
      "Microsoft Clarity adapter should send the saved token only as an Authorization header")
    try expect(
      firstQuery.first { $0.name == "numOfDays" }?.value == "2",
      "Microsoft Clarity adapter should preserve numOfDays")
    try expect(
      firstQuery.first { $0.name == "dimension1" }?.value == "URL",
      "Microsoft Clarity adapter should preserve first requested dimension")
    try expect(
      firstQuery.first { $0.name == "dimension2" }?.value == "OS",
      "Microsoft Clarity adapter should preserve second requested dimension")

    let retained = try services.database.all(
      """
      SELECT connection_json AS value FROM applications_provider_connections
      UNION ALL SELECT execution_json AS value FROM marketplace_provider_action_executions
      UNION ALL SELECT install_json AS value FROM applications_marketplace_installs
      """
    ).compactMap { sqliteText($0["value"]) }.joined(separator: "\n")
    try expect(!retained.contains(token), "Microsoft Clarity storage leaked raw API token")
    try expect(
      retained.contains("[REDACTED]"),
      "Microsoft Clarity storage should retain redaction markers for sensitive metadata")
  }

  private static func testPostHogProviderFoundationEnforcesReadOnlyAnalyticsPolicy() throws {
    final class StubPostHogHTTPClient: PostHogProviderHTTPClient, @unchecked Sendable {
      private let lock = NSLock()
      private var responses: [PostHogProviderHTTPResponse]
      private var requests: [PostHogProviderHTTPRequest] = []

      init(responses: [PostHogProviderHTTPResponse]) {
        self.responses = responses
      }

      func send(_ request: PostHogProviderHTTPRequest) throws -> PostHogProviderHTTPResponse {
        lock.lock()
        defer { lock.unlock() }
        requests.append(request)
        guard !responses.isEmpty else {
          throw MarketplaceProviderActionAdapterFailure(
            code: "stub_missing_posthog_response",
            message: "No stubbed PostHog response."
          )
        }
        return responses.removeFirst()
      }

      func capturedRequests() -> [PostHogProviderHTTPRequest] {
        lock.lock()
        defer { lock.unlock() }
        return requests
      }
    }

    func response(_ text: String, status: Int = 200) -> PostHogProviderHTTPResponse {
      PostHogProviderHTTPResponse(statusCode: status, body: Data(text.utf8))
    }

    let services = try makeServices()
    let workspace = try unwrap(services.data.getAppState().activeWorkspace, "missing workspace")
    let owner = Self.context(
      roles: [.owner], workspaceId: workspace.id, correlationId: "posthog-foundation-owner-001")
    let member = Self.context(
      roles: [.member], workspaceId: workspace.id, correlationId: "posthog-foundation-member-001")
    let token = "phx_posthog_foundation_token_sensitive"

    do {
      _ = try services.providerFoundations.registerPostHogFoundation(
        context: member,
        now: fixedDate("2026-01-01T00:00:00Z")
      )
      throw ServiceTestFailure("member unexpectedly registered PostHog provider foundation")
    } catch let denied as ServiceGuardResult {
      try expect(
        denied.reasonCode == .authorityRoleRequired,
        "PostHog foundation registration should require owner/admin authority")
    }

    let snapshot = try services.providerFoundations.registerPostHogFoundation(
      context: owner,
      now: fixedDate("2026-01-01T00:00:01Z")
    )
    try expect(snapshot.appSlug == "posthog", "PostHog foundation should target the canonical app")
    try expect(
      snapshot.providerName == "PostHog",
      "PostHog foundation should retain the canonical provider name")
    try expect(
      snapshot.providerFamily == "product-analytics",
      "PostHog foundation should mark the provider as product analytics")
    try expect(
      snapshot.connectionMode == "relay-owned-posthog-oauth-pkce-cimd",
      "PostHog foundation should use Relay-owned OAuth")
    try expect(
      snapshot.credentialOwnership == .relayOwned,
      "PostHog foundation should record Relay-owned OAuth")
    try expect(
      !snapshot.userOwnedCredentialsRequired,
      "PostHog foundation should not require a user-owned key")
    try expect(
      snapshot.supportedPolicyPresets == [.readOnly, .blocked],
      "PostHog foundation should advertise only read-only and blocked policies")
    try expect(
      snapshot.defaultPolicyPreset == .readOnly,
      "PostHog foundation should default to read-only policy")
    try expect(
      snapshot.adapterBoundary == "brokered-native-posthog-api-adapter",
      "PostHog foundation should keep API access behind the broker boundary")
    try expect(
      snapshot.actionMapVersion == "posthog-v1",
      "PostHog foundation should identify the V1 action map")
    try expect(
      !snapshot.rawProviderToolExposure, "PostHog foundation should not expose raw provider tools")
    try expect(
      snapshot.suppressedRawProviderToolCount == 15,
      "PostHog foundation should count safe and blocked V1 provider actions as suppressed raw tools"
    )
    try expect(
      snapshot.budgetPolicy["maxWrapperTools"] == .number(7),
      "PostHog foundation should budget seven wrapper tools")
    try expect(
      snapshot.budgetPolicy["maxQueryRows"] == .number(100),
      "PostHog foundation should cap bounded query rows")
    try expect(
      snapshot.privacyPolicy["eventCapture"] == .string("blocked"),
      "PostHog event capture should be blocked")
    try expect(
      snapshot.privacyPolicy["featureFlagsAndExperiments"] == .string("blocked"),
      "PostHog feature flags and experiments should be blocked")
    try expect(
