    for actionKey in expectedReadActions.subtracting(["posthog_query_bounded"]) {
      try expect(
        actionByKey[actionKey]?.policyPermission == .allowed,
        "PostHog read action \(actionKey) should be allowed by read-only policy")
      try expect(
