      adapter: RoutingMarketplaceProviderActionAdapter(
        googleDocsAdapter: GoogleDocsProviderActionAdapter(
          client: FakeGoogleDocsProviderActionClient(failureByActionKey: [
            "google_docs_read_document": MarketplaceProviderActionAdapterFailure(
              code: "google_docs_rate_limited",
              message: "Google Docs rate-limited the read request.",
              providerStatusCode: 429,
              detail: ["retryAfter": .string("later")]
            )
          ]))
      )
    )
    let failed = try failingBroker.execute(
      context: owner,
      request: MarketplaceProviderActionBrokerRequest(
        appIdOrSlug: googleDocs.id,
        actionKey: "google_docs_read_document",
        payload: ["documentIdOrUrl": .string("doc-rate-limited-001")],
        idempotencyKey: "google-docs-broker-provider-failure-001"
      ),
      now: fixedDate("2026-01-01T00:00:10Z")
    )
    try expect(
      failed.adapterExecuted, "Google Docs provider failure should still attempt the adapter")
    try expect(
      failed.execution.status == .failed,
      "Google Docs provider failures should persist failed executions")
    try expect(
      failed.execution.providerError?["providerErrorCode"] == .string("google_docs_rate_limited"),
      "Google Docs adapter failure should map provider error code")
    try expect(
      failed.execution.providerError?["providerStatusCode"] == .number(429),
      "Google Docs adapter failure should map provider status code")

    let retained = try services.database.all(
      """
      SELECT approval_json AS value FROM marketplace_provider_action_approvals
      UNION ALL SELECT execution_json AS value FROM marketplace_provider_action_executions
      UNION ALL SELECT context_json AS value FROM audit_log_records
      """
    ).compactMap { sqliteText($0["value"]) }.joined(separator: "\n")
    try expect(
      retained.contains("[REDACTED]"), "Google Docs broker storage should retain redaction markers")
  }

  private static func testGoogleDocsLiveSemanticReadMapsDocumentTextWithoutLeakingSecrets() throws {
    final class StubGoogleDocsHTTPClient: GoogleDocsProviderHTTPClient, @unchecked Sendable {
      private let lock = NSLock()
      private var responsesByRequest: [String: [GoogleDocsProviderHTTPResponse]]

      init(responsesByRequest: [String: [GoogleDocsProviderHTTPResponse]]) {
        self.responsesByRequest = responsesByRequest
      }

      func send(_ request: GoogleDocsProviderHTTPRequest) throws -> GoogleDocsProviderHTTPResponse {
        lock.lock()
        defer { lock.unlock() }
        let key = "\(request.method.uppercased()) \(request.url.path)"
        guard var responses = responsesByRequest[key], !responses.isEmpty else {
          throw MarketplaceProviderActionAdapterFailure(
            code: "stub_missing_google_docs_response",
            message: "No stubbed Google Docs response for \(key)."
          )
        }
        if request.url.host == "docs.googleapis.com",
          request.headers["Authorization"] != "Bearer stub-google-docs-access-token"
        {
          throw MarketplaceProviderActionAdapterFailure(
            code: "stub_missing_google_docs_authorization",
            message: "Stub Google Docs requests must include the refreshed bearer token."
          )
        }
        let response = responses.removeFirst()
        responsesByRequest[key] = responses
        return response
      }
    }

    func docsResponse(_ text: String, status: Int = 200) -> GoogleDocsProviderHTTPResponse {
      GoogleDocsProviderHTTPResponse(statusCode: status, body: Data(text.utf8))
    }

    let documentJSON = #"""
        {
          "documentId": "doc-live-semantic-001",
          "title": "Live semantic Docs proof",
          "revisionId": "rev-live-001",
          "body": {
            "content": [
              {
                "paragraph": {
                  "paragraphStyle": {"namedStyleType": "HEADING_1"},
                  "elements": [
                    {"textRun": {"content": "Launch plan\n"}}
                  ]
                }
              },
              {
                "paragraph": {
                  "elements": [
                    {"textRun": {"content": "The team will connect Google Docs, read bounded document text, and keep writes behind Relay policy.\n"}}
                  ]
                }
              },
              {
                "table": {
                  "tableRows": [
                    {
                      "tableCells": [
                        {"content": [{"paragraph": {"elements": [{"textRun": {"content": "Owner"}}]}}]},
                        {"content": [{"paragraph": {"elements": [{"textRun": {"content": "Relay"}}]}}]}
                      ]
      }
                  ]
                }
              }
            ]
          }
        }
      """#

    let services = try makeServices()
    let workspace = try unwrap(services.data.getAppState().activeWorkspace, "missing workspace")
    let owner = Self.context(
      roles: [.owner], workspaceId: workspace.id, correlationId: "google-docs-live-read-owner-001")
    let foundation = try services.providerFoundations.registerGoogleDocsFoundation(
      context: owner,
      now: fixedDate("2026-01-01T00:00:00Z")
    )
    let app = try unwrap(
      try services.data.getMarketplaceCatalogApp(
        workspaceId: workspace.id, appIdOrSlug: foundation.appId),
      "missing Google Docs app"
    )
    let connection = try services.providerConnections.saveGoogleDocsOAuthCredentials(
      context: owner,
      appIdOrSlug: app.id,
      clientId: "google-docs-live-client-id-sensitive-value",
      clientSecret: "google-docs-live-client-secret-sensitive-value",
      refreshToken: "google-docs-live-refresh-token-sensitive-value",
      accessToken: nil,
      accountEmail: "docs-reader@example.com",
      projectId: "google-docs-live-project",
      displayName: "Docs Reader",
      now: fixedDate("2026-01-01T00:00:01Z")
    )
    _ = try services.providerActionPolicies.compilePolicyMap(
      context: owner,
      appIdOrSlug: app.id,
      preset: .approvalRequired,
      now: fixedDate("2026-01-01T00:00:02Z")
    )
    let broker = MarketplaceProviderActionBrokerService(
      data: services.data,
      approvals: services.providerActionApprovals,
      auditSecurity: services.auditSecurity,
      adapter: RoutingMarketplaceProviderActionAdapter(
        googleDocsAdapter: GoogleDocsProviderActionAdapter(
          client: LiveGoogleDocsProviderActionClient(
            data: services.data,
            secrets: services.secrets,
            httpClient: StubGoogleDocsHTTPClient(responsesByRequest: [
              "POST /token": [
                docsResponse(
                  #"{"access_token":"stub-google-docs-access-token","expires_in":3600,"token_type":"Bearer"}"#
                )
              ],
              "GET /v1/documents/doc-live-semantic-001": [
                docsResponse(documentJSON)
              ],
            ])
          )
        )
      )
    )

    let read = try broker.execute(
      context: owner,
      request: MarketplaceProviderActionBrokerRequest(
        appIdOrSlug: app.id,
        actionKey: "google_docs_read_document",
        payload: [
          "documentIdOrUrl": .string(
            "https://docs.google.com/document/d/doc-live-semantic-001/edit"),
          "maxBodyChars": .number(1200),
        ],
        connectionId: connection.id,
        idempotencyKey: "google-docs-live-read-001"
      ),
      now: fixedDate("2026-01-01T00:00:03Z")
    )
    try expect(
      read.adapterExecuted, "Google Docs live semantic read should execute through the adapter")
    try expect(
      read.execution.status == ProviderActionExecutionStatus.succeeded,
      "Google Docs live semantic read should persist succeeded execution")
    try expect(
      read.execution.providerResult?["clientMode"] == JSONValue.string("live-google-docs-api"),
      "Google Docs live read should mark live client mode")
    try expect(
      read.execution.providerResult?["liveCredentialsUsed"] == JSONValue.bool(true),
      "Google Docs live read should use saved credentials through secret references")
    try expect(
      read.execution.providerResult?["semanticReadContract"]
        == JSONValue.string("google-docs-document-summary-v1"),
      "Google Docs live read should name the semantic read contract")
    let document = try unwrap(
      objectValue(read.execution.providerResult?["document"]),
      "Google Docs live read should return a document object")
    try expect(
      document["documentId"] == JSONValue.string("doc-live-semantic-001"),
      "Google Docs live read should return document ID")
    try expect(
      document["title"] == JSONValue.string("Live semantic Docs proof"),
      "Google Docs live read should return document title")
    try expect(
      document["revisionId"] == JSONValue.string("rev-live-001"),
      "Google Docs live read should return revision marker")
    try expect(
      document["text"]?.string?.contains("read bounded document text") == true,
      "Google Docs live read should return human-readable body text")
    guard case JSONValue.array(let headings)? = document["headings"] else {
      throw ServiceTestFailure("Google Docs live read should return headings")
    }
    try expect(
      headings.contains(JSONValue.string("Launch plan")),
      "Google Docs live read should extract headings")
    guard case JSONValue.array(let tableText)? = document["tableText"] else {
      throw ServiceTestFailure("Google Docs live read should return table text")
    }
    try expect(
      tableText.contains(JSONValue.string("Owner | Relay")),
      "Google Docs live read should flatten table text")

    let retained = try services.database.all(
      """
              SELECT connection_json AS value FROM applications_provider_connections
              UNION ALL SELECT execution_json AS value FROM marketplace_provider_action_executions
        UNION ALL SELECT context_json AS value FROM audit_log_records
      """
    ).compactMap { sqliteText($0["value"]) }.joined(separator: "\n")
    for secret in [
      "google-docs-live-client-id-sensitive-value",
      "google-docs-live-client-secret-sensitive-value",
      "google-docs-live-refresh-token-sensitive-value",
      "stub-google-docs-access-token",
    ] {
      try expect(
        !retained.contains(secret), "Google Docs live read storage leaked secret \(secret)")
    }
    try expect(
      retained.contains("[REDACTED]"),
      "Google Docs live read storage should retain redaction markers")
  }

  private static func testNotionProviderActionLiveReadMapsSearchWithoutLeakingSecrets() throws {
    final class StubNotionHTTPClient: NotionProviderHTTPClient, @unchecked Sendable {
      private let lock = NSLock()
      private var responsesByRequest: [String: [NotionProviderHTTPResponse]]
      private var captured: [NotionProviderHTTPRequest] = []

      init(responsesByRequest: [String: [NotionProviderHTTPResponse]]) {
        self.responsesByRequest = responsesByRequest
      }

      func send(_ request: NotionProviderHTTPRequest) throws -> NotionProviderHTTPResponse {
        let key = "\(request.method) \(request.url.path)"
        lock.lock()
        defer { lock.unlock() }
        captured.append(request)
        guard var responses = responsesByRequest[key], !responses.isEmpty else {
          throw MarketplaceProviderActionAdapterFailure(
            code: "stub_missing_notion_response",
            message: "No stubbed Notion response for \(key)."
          )
        }
        let response = responses.removeFirst()
        responsesByRequest[key] = responses
        return response
      }

      func capturedRequests() -> [NotionProviderHTTPRequest] {
        lock.lock()
        defer { lock.unlock() }
        return captured
      }
    }

    func notionResponse(_ text: String, status: Int = 200) -> NotionProviderHTTPResponse {
      NotionProviderHTTPResponse(statusCode: status, body: Data(text.utf8))
    }

    let services = try makeServices()
    let workspace = try unwrap(services.data.getAppState().activeWorkspace, "missing workspace")
    let owner = Self.context(
      roles: [.owner], workspaceId: workspace.id, correlationId: "notion-live-read-owner-001")
    let foundation = try services.providerFoundations.registerNotionFoundation(
      context: owner,
      now: fixedDate("2026-01-01T00:00:00Z")
    )
    let notion = try unwrap(
      try services.data.getMarketplaceCatalogApp(
        workspaceId: workspace.id, appIdOrSlug: foundation.appId),
      "missing Notion app"
    )
    let token = "secret_notion_live_read_sensitive_token"
    let connection = try services.providerConnections.saveNotionAPIToken(
      context: owner,
      appIdOrSlug: notion.id,
      credentialMode: "personal_access_token",
      apiToken: token,
      workspaceLabel: "Fixture Notion Workspace",
      displayName: "Live Notion Read Test",
      validationResult: NotionTokenValidationResult(
        status: .ready,
        message: "Notion API token verified.",
        httpStatusCode: 200,
        userId: "notion-user-001",
        userType: "person"
      ),
      now: fixedDate("2026-01-01T00:00:01Z")
    )
    let stub = StubNotionHTTPClient(responsesByRequest: [
      "POST /v1/search": [
        notionResponse(
          #"""
          {
            "object": "list",
            "results": [
              {
                "object": "page",
                "id": "page-live-001",
                "created_time": "2026-06-27T08:00:00.000Z",
                "last_edited_time": "2026-06-27T09:00:00.000Z",
                "url": "https://www.notion.so/page-live-001",
                "archived": false,
                "in_trash": false,
                "parent": {"type": "workspace", "workspace": true},
                "properties": {
                  "Name": {
                    "type": "title",
                    "title": [
                      {"plain_text": "Launch Notes", "text": {"content": "Launch Notes"}}
                    ]
                  }
                }
              }
            ],
            "next_cursor": "cursor-next",
            "has_more": true
          }
          """#)
      ]
    ])
    let liveBroker = MarketplaceProviderActionBrokerService(
      data: services.data,
      approvals: services.providerActionApprovals,
      auditSecurity: services.auditSecurity,
      adapter: RoutingMarketplaceProviderActionAdapter(
        notionAdapter: NotionProviderActionAdapter(
          client: LiveNotionProviderActionClient(
            data: services.data,
            secrets: services.secrets,
            httpClient: stub
          )
        )
      )
    )
    let result = try liveBroker.execute(
      context: owner,
      request: MarketplaceProviderActionBrokerRequest(
        appIdOrSlug: notion.id,
        actionKey: "notion_search",
        payload: [
          "query": .string("Launch"),
          "limit": .number(1),
          "objectType": .string("page"),
        ],
        connectionId: connection.id,
        idempotencyKey: "notion-live-read-search-001",
        dispatchId: "rtd-notion-live-read-search-001"
      ),
      now: fixedDate("2026-01-01T00:00:02Z")
    )
    try expect(
      result.adapterExecuted, "live Notion search should execute through the Notion adapter")
    try expect(
      result.execution.status == .succeeded, "live Notion search should persist succeeded execution"
    )
    let providerResult = try unwrap(
      result.execution.providerResult, "missing live Notion provider result")
    try expect(
      providerResult["fakeAdapter"] == .bool(false),
      "live Notion search should not use fake adapter")
    try expect(
      providerResult["clientMode"] == .string("live-notion-api"),
      "live Notion search should identify the live API client")
    try expect(
      providerResult["liveCredentialsUsed"] == .bool(true),
      "live Notion search should use broker-held Keychain credentials")
    try expect(
      providerResult["semanticReadContract"] == .string("notion-search-summary-v1"),
      "live Notion search should retain semantic read contract")
    let items = arrayValue(providerResult["results"]).compactMap(objectValue)
    try expect(items.count == 1, "live Notion search should trim results to the requested limit")
    try expect(
      items.first?["title"] == .string("Launch Notes"),
      "live Notion search should summarize page titles")
    try expect(
      providerResult["nextCursor"] == .string("cursor-next"),
      "live Notion search should return provider pagination cursor")

    let captured = stub.capturedRequests()
    try expect(captured.count == 1, "Notion live search should make one provider request")
    let capturedRequest = try unwrap(captured.first, "missing captured Notion request")
    try expect(capturedRequest.method == "POST", "Notion live search should use POST")
    try expect(
      capturedRequest.url.host == "api.notion.com", "Notion live search should target Notion API")
    try expect(
      capturedRequest.url.path == "/v1/search", "Notion live search should call the search endpoint"
    )
    try expect(
      capturedRequest.headers["Authorization"] == "Bearer \(token)",
      "Notion live search should send the saved token only as an Authorization header")
    try expect(
      capturedRequest.headers["Notion-Version"] == "2026-03-11",
      "Notion live search should use the approved Notion API version")
    let requestBody = try unwrap(
      capturedRequest.body.flatMap { try? JSONDecoder().decode(JSONRecord.self, from: $0) },
      "missing Notion search JSON body")
    try expect(
      requestBody["page_size"] == .number(1), "Notion live search should preserve bounded page size"
    )
    try expect(
      requestBody["query"] == .string("Launch"), "Notion live search should preserve the query")

    let failingStub = StubNotionHTTPClient(responsesByRequest: [
      "POST /v1/search": [
        notionResponse(
          #"{"object":"error","code":"rate_limited","message":"Slow down"}"#, status: 429)
      ]
    ])
    let failingBroker = MarketplaceProviderActionBrokerService(
      data: services.data,
      approvals: services.providerActionApprovals,
      auditSecurity: services.auditSecurity,
      adapter: RoutingMarketplaceProviderActionAdapter(
        notionAdapter: NotionProviderActionAdapter(
          client: LiveNotionProviderActionClient(
            data: services.data,
            secrets: services.secrets,
            httpClient: failingStub
          )
        )
      )
    )
    let failed = try failingBroker.execute(
      context: owner,
      request: MarketplaceProviderActionBrokerRequest(
        appIdOrSlug: notion.id,
        actionKey: "notion_search",
        payload: ["query": .string("rate limited")],
        connectionId: connection.id,
        idempotencyKey: "notion-live-read-failure-001"
      ),
      now: fixedDate("2026-01-01T00:00:03Z")
    )
    try expect(
      failed.adapterExecuted, "live Notion provider error should still attempt the adapter")
    try expect(
      failed.execution.status == .failed,
      "live Notion provider error should persist failed execution")
    try expect(
      failed.execution.providerError?["providerErrorCode"] == .string("notion_search_http_error"),
      "live Notion provider error should map provider error code")
    try expect(
      failed.execution.providerError?["providerStatusCode"] == .number(429),
      "live Notion provider error should map provider status code")

    let retained = try services.database.all(
      """
      SELECT connection_json AS value FROM applications_provider_connections
      UNION ALL SELECT execution_json AS value FROM marketplace_provider_action_executions
      UNION ALL SELECT context_json AS value FROM audit_log_records
      """
    ).compactMap { sqliteText($0["value"]) }.joined(separator: "\n")
    try expect(!retained.contains(token), "Notion live read storage leaked raw API token")
    try expect(
      retained.contains("secret-reference-only"),
      "Notion live read storage should retain secret-reference evidence")
  }

  private static func testGmailSemanticReadClientReturnsUsefulSummaries() throws {
    final class StubGmailHTTPClient: GmailProviderHTTPClient, @unchecked Sendable {
      private let lock = NSLock()
      private var responsesByRequest: [String: [GmailProviderHTTPResponse]]

      init(responsesByRequest: [String: [GmailProviderHTTPResponse]]) {
        self.responsesByRequest = responsesByRequest
      }

      func send(_ request: GmailProviderHTTPRequest) throws -> GmailProviderHTTPResponse {
        let key = "\(request.method) \(request.url.path)"
        lock.lock()
        defer { lock.unlock() }
        guard var responses = responsesByRequest[key], !responses.isEmpty else {
          throw MarketplaceProviderActionAdapterFailure(
            code: "stub_missing_gmail_response",
            message: "No stubbed Gmail response for \(key)."
          )
        }
        if request.url.host == "gmail.googleapis.com",
          request.headers["Authorization"] != "Bearer stub-gmail-access-token"
        {
          throw MarketplaceProviderActionAdapterFailure(
            code: "stub_missing_gmail_authorization",
            message: "Stub Gmail requests must include the refreshed bearer token."
          )
        }
        let response = responses.removeFirst()
        responsesByRequest[key] = responses
        return response
      }
    }

    func gmailResponse(_ text: String, status: Int = 200) -> GmailProviderHTTPResponse {
      GmailProviderHTTPResponse(statusCode: status, body: Data(text.utf8))
    }

    func gmailBodyData(_ text: String) -> String {
      Data(text.utf8)
        .base64EncodedString()
        .replacingOccurrences(of: "+", with: "-")
        .replacingOccurrences(of: "/", with: "_")
        .replacingOccurrences(of: "=", with: "")
    }

    let semanticBody = """
      <p>Hello semantic Gmail body.</p>
      <p>This bounded excerpt lets the assigned agent summarize the message without receiving OAuth secrets or a full mailbox export.</p>
      """
    let metadataMessage = #"""
        {
          "id": "gmail-msg-semantic-001",
          "threadId": "gmail-thread-semantic-001",
          "labelIds": ["INBOX"],
          "internalDate": "1760000000000",
          "snippet": "Hello semantic Gmail body. This bounded excerpt lets the assigned agent summarize.",
          "payload": {
            "headers": [
              {"name": "From", "value": "Sender Example <sender@example.com>"},
              {"name": "To", "value": "Relay User <relay@example.com>"},
              {"name": "Subject", "value": "Semantic Gmail proof"},
              {"name": "Date", "value": "Sat, 27 Jun 2026 12:00:00 +0000"}
          ]
          }
      }
      """#
    let fullMessage = """
      {
        "id": "gmail-msg-semantic-001",
        "threadId": "gmail-thread-semantic-001",
        "labelIds": ["INBOX"],
        "internalDate": "1760000000000",
        "snippet": "Hello semantic Gmail body. This bounded excerpt lets the assigned agent summarize.",
        "payload": {
          "mimeType": "multipart/alternative",
          "headers": [
            {"name": "From", "value": "Sender Example <sender@example.com>"},
            {"name": "To", "value": "Relay User <relay@example.com>"},
            {"name": "Subject", "value": "Semantic Gmail proof"},
            {"name": "Date", "value": "Sat, 27 Jun 2026 12:00:00 +0000"}
          ],
          "parts": [
            {
              "mimeType": "text/html",
              "body": {"data": "\(gmailBodyData(semanticBody))"}
            }
          ]
        }
      }
      """

    let services = try makeServices()
    let workspace = try unwrap(services.data.getAppState().activeWorkspace, "missing workspace")
    let owner = Self.context(
      roles: [.owner], workspaceId: workspace.id, correlationId: "gmail-semantic-owner-001")
    _ = try services.providerFoundations.registerGmailFoundation(
      context: owner, now: fixedDate("2026-01-01T00:00:00Z"))
    let app = try unwrap(
      try services.data.getMarketplaceCatalogApp(workspaceId: workspace.id, appIdOrSlug: "gmail"),
      "missing Gmail app"
    )
    let connection = try services.providerConnections.saveGmailOAuthCredentials(
      context: owner,
      appIdOrSlug: app.id,
      clientId: "gmail_semantic_client_id_secret",
      clientSecret: "gmail_semantic_client_secret",
      refreshToken: "gmail_semantic_refresh_secret",
      accessToken: nil,
      accountEmail: "relay@example.com",
      displayName: "Semantic Gmail Account",
      now: fixedDate("2026-01-01T00:00:01Z")
    )
    let agent = try createServiceAgent(services: services, workspaceId: workspace.id)
    let install = try services.marketplaceInstalls.createInstall(
      context: owner,
      request: installRequest(
        id: "minreq-gmail-semantic-001",
        workspaceId: workspace.id,
        app: app,
        connectionId: connection.id,
        agent: agent,
        roleId: app.roleManifest.primaryRole,
        selectedCapabilities: app.capabilities,
        riskAcknowledged: true
      ),
      now: fixedDate("2026-01-01T00:00:02Z")
    )
    let broker = MarketplaceProviderActionBrokerService(
      data: services.data,
      approvals: services.providerActionApprovals,
      auditSecurity: services.auditSecurity,
      adapter: RoutingMarketplaceProviderActionAdapter(
        gmailAdapter: GmailProviderActionAdapter(
          client: LiveGmailProviderActionClient(
            data: services.data,
            secrets: services.secrets,
            httpClient: StubGmailHTTPClient(responsesByRequest: [
              "POST /token": [
                gmailResponse(
                  #"{"access_token":"stub-gmail-access-token","expires_in":3600,"token_type":"Bearer"}"#
                ),
                gmailResponse(
                  #"{"access_token":"stub-gmail-access-token","expires_in":3600,"token_type":"Bearer"}"#
                ),
              ],
              "GET /gmail/v1/users/me/messages": [
                gmailResponse(
                  #"{"messages":[{"id":"gmail-msg-semantic-001","threadId":"gmail-thread-semantic-001"}],"resultSizeEstimate":1}"#
                )
              ],
              "GET /gmail/v1/users/me/messages/gmail-msg-semantic-001": [
                gmailResponse(metadataMessage),
                gmailResponse(fullMessage),
              ],
            ])
          )
        )
      )
    )

    let search = try broker.execute(
      context: owner,
      request: MarketplaceProviderActionBrokerRequest(
        appIdOrSlug: app.id,
        actionKey: "gmail.messages.search",
        payload: [
          "query": .string("from:sender@example.com newer_than:7d"),
          "maxResults": .number(1),
        ],
        connectionId: connection.id,
        installId: install.id,
        agentId: agent.id,
        idempotencyKey: "gmail-semantic-search-001"
      ),
      now: fixedDate("2026-01-01T00:00:03Z")
    )
    try expect(search.adapterExecuted, "semantic Gmail search should execute through broker")
    try expect(
      search.execution.providerResult?["semanticReadContract"]
        == .string("gmail-search-summary-v1"),
      "semantic Gmail search should name the result contract")
    guard case .array(let messages)? = search.execution.providerResult?["messages"],
      let firstMessage = messages.compactMap(objectValue).first
    else {
      throw ServiceTestFailure("semantic Gmail search should return message summaries")
    }
    try expect(
      firstMessage["from"] == .string("Sender Example <sender@example.com>"),
      "semantic Gmail search should include sender value")
    try expect(
      firstMessage["subject"] == .string("Semantic Gmail proof"),
      "semantic Gmail search should include subject value")
    try expect(
      firstMessage["date"] == .string("Sat, 27 Jun 2026 12:00:00 +0000"),
      "semantic Gmail search should include date value")
    try expect(
      firstMessage["snippet"]?.string?.contains("Hello semantic Gmail body") == true,
      "semantic Gmail search should include a useful snippet")
    try expect(
      firstMessage["bodyReturned"] == .bool(false),
      "semantic Gmail search should not return full body text")

    let read = try broker.execute(
      context: owner,
      request: MarketplaceProviderActionBrokerRequest(
        appIdOrSlug: app.id,
        actionKey: "gmail.message.read",
        payload: [
          "messageId": .string("gmail-msg-semantic-001"),
          "format": .string("summary"),
          "maxBodyChars": .number(80),
        ],
        connectionId: connection.id,
        installId: install.id,
        agentId: agent.id,
        idempotencyKey: "gmail-semantic-read-001"
      ),
      now: fixedDate("2026-01-01T00:00:04Z")
    )
    try expect(read.adapterExecuted, "semantic Gmail read should execute through broker")
    try expect(
      read.execution.providerResult?["semanticReadContract"] == .string("gmail-message-summary-v1"),
      "semantic Gmail read should name the result contract")
    let message = try unwrap(
      objectValue(read.execution.providerResult?["message"]),
      "semantic Gmail read should return a message object")
    try expect(
      message["from"] == .string("Sender Example <sender@example.com>"),
      "semantic Gmail read should include sender value")
    try expect(
      message["to"] == .string("Relay User <relay@example.com>"),
      "semantic Gmail read should include recipient value")
    try expect(
      message["subject"] == .string("Semantic Gmail proof"),
      "semantic Gmail read should include subject value")
    try expect(
      message["date"] == .string("Sat, 27 Jun 2026 12:00:00 +0000"),
      "semantic Gmail read should include date value")
    try expect(
      message["bodyReturned"] == .bool(true),
      "semantic Gmail read should return a bounded body excerpt")
    let bodyExcerpt = try unwrap(
      message["bodyExcerpt"]?.string, "semantic Gmail read should include body excerpt text")
    try expect(
      bodyExcerpt.contains("Hello semantic Gmail body."),
      "semantic Gmail read should decode useful body text")
    try expect(
      !bodyExcerpt.contains("<p>"),
      "semantic Gmail read should strip unsafe markup from HTML bodies")
    try expect(bodyExcerpt.count <= 80, "semantic Gmail read should bound the body excerpt")
    try expect(
      message["bodyTruncated"] == .bool(true), "semantic Gmail read should mark bounded truncation")
    guard case .array(let fields)? = message["semanticFieldsReturned"] else {
      throw ServiceTestFailure("semantic Gmail read should list semantic fields")
    }
    let fieldNames = Set(fields.compactMap(\.string))
    try expect(
      fieldNames.isSuperset(of: ["from", "subject", "date", "snippet", "bodyExcerpt"]),
      "semantic Gmail read should report the useful fields returned")
  }

  private static func testGmailLiveSemanticReadUsesAssignedRuntimeWrapper() throws {
    let environment = ProcessInfo.processInfo.environment
    guard environment["RELAY_CONSOLE_LIVE_GMAIL_SEMANTIC_READ"] == "1" else {
      return
    }
    guard let dataPath = liveKeychainUserDataPath(environment, testName: "Gmail live semantic read")
    else {
      return
    }
    let searchQuery =
      nonEmpty(environment["RELAY_CONSOLE_LIVE_GMAIL_READ_QUERY"])
      ?? "in:anywhere newer_than:30d"
    let services = try RelayConsoleServices(
      userDataPath: URL(fileURLWithPath: dataPath, isDirectory: true),
      refreshInstalledHarnessesOnLaunch: false,
      startRuntimeBrokerServer: false
    )
    let workspace = try unwrap(
      services.data.getAppState().activeWorkspace, "missing live workspace")
    let owner = Self.context(
      roles: [.owner, .approver], workspaceId: workspace.id,
      correlationId: "gmail-live-semantic-owner")
    let member = Self.context(
      roles: [.member], workspaceId: workspace.id, correlationId: "gmail-live-semantic-member")
    _ = try services.providerFoundations.registerGmailFoundation(context: owner, now: Date())
    let app = try unwrap(
      try services.data.getMarketplaceCatalogApp(workspaceId: workspace.id, appIdOrSlug: "gmail"),
      "missing live Gmail app"
    )
    let connectedConnections = try services.data.listProviderConnections(
      workspaceId: workspace.id, appId: app.id, limit: 50
    )
    .filter { $0.status == .connected }
    let connectionsById = Dictionary(uniqueKeysWithValues: connectedConnections.map { ($0.id, $0) })
    let activeInstalls = try services.data.listMarketplaceInstalls(
      workspaceId: workspace.id, appId: app.id, limit: 100)
    let assigned = activeInstalls.compactMap {
      install -> (MarketplaceInstallRecord, MarketplaceProviderConnection, AgentWithBinding)? in
      guard install.installStatus == .installed || install.installStatus == .requested,
        let connectionId = install.connectionId,
        let connection = connectionsById[connectionId],
        let agent = try? services.data.getAgent(install.agentId),
        agent.status == "active"
      else {
        return nil
      }
      return (install, connection, agent)
    }
    .sorted { lhs, rhs in
      if lhs.1.accountLabel == "JungleHouse", rhs.1.accountLabel != "JungleHouse" {
        return true
      }
      if rhs.1.accountLabel == "JungleHouse", lhs.1.accountLabel != "JungleHouse" {
        return false
      }
      return lhs.0.updatedAt > rhs.0.updatedAt
    }
    .first
    let (install, connection, agent) = try unwrap(
      assigned,
      "missing active assigned Gmail Marketplace install for a connected Gmail account"
    )

    let snapshot = try services.marketplaceRuntimeMounts.snapshot(
      context: member, agent: agent, now: Date())
    let gmailMount = try unwrap(
      snapshot.apps.first { $0.appSlug == "gmail" && $0.installId == install.id },
      "assigned agent runtime snapshot did not mount Gmail"
    )
    try expect(gmailMount.connected, "live Gmail runtime mount should report connected")
    try expect(
      gmailMount.assignedAgentReady, "live Gmail runtime mount should report assigned agent ready")
    try expect(
      gmailMount.tools.count <= 6,
      "live Gmail runtime mount should stay inside the V1 wrapper tool budget")
    try expect(
      !snapshot.rawProviderToolExposure,
      "live Gmail runtime mount must not expose raw provider tools")
    let prompt = services.marketplaceRuntimeMounts.renderPromptBlock(snapshot) ?? ""
    try expect(
      prompt.contains("App: Gmail (gmail)"),
      "live Gmail runtime prompt should include Gmail app summary")
    try expect(
      !prompt.contains("gmail.message.read"),
      "live Gmail runtime prompt must not dump raw Gmail action names")
    try expect(
      !prompt.contains("gmail.messages.search"),
      "live Gmail runtime prompt must not dump raw Gmail action names")
    let searchTool = try unwrap(
      gmailMount.tools.first { $0.displayName == "Search messages" },
      "missing live Gmail search wrapper tool"
    )
    let readTool = try unwrap(
      gmailMount.tools.first { $0.displayName == "Read message" },
      "missing live Gmail read wrapper tool"
    )
    try expect(
      searchTool.toolName.hasPrefix("relay_provider_gmail_"),
      "live Gmail search must use a Relay wrapper tool")
    try expect(
      readTool.toolName.hasPrefix("relay_provider_gmail_"),
      "live Gmail read must use a Relay wrapper tool")

    let marker = "gmail-live-semantic-\(Int(Date().timeIntervalSince1970))"
    let runtimeContext = MarketplaceRuntimeToolExecutionContext(
      agentId: agent.id,
      workspaceId: workspace.id,
      runtimeType: agent.binding.runtimeType,
      dispatchId: "rtd-\(marker)",
      threadId: "thr-\(marker)",
      runtimeSessionId: "rts-\(marker)",
      correlationId: marker
    )
    let searchResult = try services.marketplaceRuntimeToolBridge.execute(
      toolName: searchTool.toolName,
      payload: [
        "query": .string(searchQuery),
        "maxResults": .number(1),
      ],
      runtime: runtimeContext,
      now: Date()
    )
    try expect(
      searchResult["toolName"] == .string(searchTool.toolName),
      "live Gmail search should execute the mounted wrapper tool")
    try expect(
      searchResult["appSlug"] == .string("gmail"),
      "live Gmail search should map wrapper back to Gmail")
    try expect(
      searchResult["actionKey"] == .string("gmail.messages.search"),
      "live Gmail search should resolve the Gmail search action")
    try expect(
      searchResult["adapterExecuted"] == .bool(true),
      "live Gmail search should execute through the broker adapter")
    let searchProviderResult = try unwrap(
      objectValue(searchResult["providerResult"]), "live Gmail search should return provider result"
    )
    try expect(
      searchProviderResult["clientMode"] == .string("live-gmail-api"),
      "live Gmail search should identify the live Gmail client")
    try expect(
      searchProviderResult["fakeAdapter"] == .bool(false),
      "live Gmail search must not use fake adapter evidence")
    try expect(
      searchProviderResult["semanticReadContract"] == .string("gmail-search-summary-v1"),
      "live Gmail search should name the semantic contract")
    guard case .array(let searchMessages)? = searchProviderResult["messages"],
      let firstMessage = searchMessages.compactMap(objectValue).first
    else {
      throw ServiceTestFailure(
        "live Gmail search returned no message summary for the bounded query")
    }
    let firstMessageId = try unwrap(
      nonEmpty(firstMessage["id"]?.string), "live Gmail search should return a message id")
    let searchFrom = try unwrap(
      nonEmpty(firstMessage["from"]?.string), "live Gmail search should return sender value")
    let searchSubject = try unwrap(
      nonEmpty(firstMessage["subject"]?.string), "live Gmail search should return subject value")
    let searchDate = try unwrap(
      nonEmpty(firstMessage["date"]?.string), "live Gmail search should return date value")
    let searchSnippet = try unwrap(
      nonEmpty(firstMessage["snippet"]?.string), "live Gmail search should return a bounded snippet"
    )
    try expect(
      firstMessage["bodyReturned"] == .bool(false), "live Gmail search should not return body text")

    let readResult = try services.marketplaceRuntimeToolBridge.execute(
      toolName: readTool.toolName,
      payload: [
        "messageId": .string(firstMessageId),
        "format": .string("summary"),
        "maxBodyChars": .number(240),
      ],
      runtime: MarketplaceRuntimeToolExecutionContext(
        agentId: agent.id,
        workspaceId: workspace.id,
        runtimeType: agent.binding.runtimeType,
        dispatchId: "rtd-\(marker)-read",
        threadId: "thr-\(marker)-read",
        runtimeSessionId: "rts-\(marker)-read",
        correlationId: "\(marker)-read"
      ),
      now: Date()
    )
    try expect(
      readResult["toolName"] == .string(readTool.toolName),
      "live Gmail read should execute the mounted wrapper tool")
    try expect(
      readResult["appSlug"] == .string("gmail"), "live Gmail read should map wrapper back to Gmail")
    try expect(
      readResult["actionKey"] == .string("gmail.message.read"),
      "live Gmail read should resolve the Gmail read action")
    try expect(
      readResult["adapterExecuted"] == .bool(true),
      "live Gmail read should execute through the broker adapter")
    let readProviderResult = try unwrap(
      objectValue(readResult["providerResult"]), "live Gmail read should return provider result")
    try expect(
      readProviderResult["clientMode"] == .string("live-gmail-api"),
      "live Gmail read should identify the live Gmail client")
    try expect(
      readProviderResult["fakeAdapter"] == .bool(false),
      "live Gmail read must not use fake adapter evidence")
    try expect(
      readProviderResult["semanticReadContract"] == .string("gmail-message-summary-v1"),
      "live Gmail read should name the semantic contract")
    let message = try unwrap(
      objectValue(readProviderResult["message"]), "live Gmail read should return a message object")
    _ = try unwrap(nonEmpty(message["from"]?.string), "live Gmail read should return sender value")
    _ = try unwrap(
      nonEmpty(message["subject"]?.string), "live Gmail read should return subject value")
    _ = try unwrap(nonEmpty(message["date"]?.string), "live Gmail read should return date value")
    _ = try unwrap(
      nonEmpty(message["snippet"]?.string), "live Gmail read should return snippet value")
    try expect(
      message["bodyReturned"] == .bool(true), "live Gmail read should return a bounded body excerpt"
    )
    let bodyExcerpt = try unwrap(
      nonEmpty(message["bodyExcerpt"]?.string), "live Gmail read should include body excerpt text")
    try expect(bodyExcerpt.count <= 240, "live Gmail read should keep the body excerpt bounded")
    guard case .array(let fields)? = message["semanticFieldsReturned"] else {
      throw ServiceTestFailure("live Gmail read should report semantic fields")
    }
    let readFieldNames = Set(fields.compactMap(\.string))
    try expect(
      readFieldNames.isSuperset(of: ["from", "subject", "date", "snippet", "bodyExcerpt"]),
      "live Gmail read should report all semantic fields")

    let retained = try services.database.all(
      "SELECT connection_json AS value FROM applications_provider_connections WHERE app_slug = 'gmail' UNION ALL SELECT execution_json AS value FROM marketplace_provider_action_executions WHERE app_id = ?",
      [.text(app.id)]
    ).compactMap { sqliteText($0["value"]) }.joined(separator: "\n")
    let savedSecretValues = try connection.secretReferenceIds.map {
      try services.secrets.getSecretValue($0)
    }
    for secretValue in savedSecretValues {
      try expect(
        !retained.contains(secretValue),
        "live Gmail semantic read evidence leaked a saved OAuth secret value")
    }
    for forbidden in ["Authorization: Bearer"] {
      try expect(
        !retained.localizedCaseInsensitiveContains(forbidden),
        "live Gmail semantic read evidence leaked raw OAuth marker \(forbidden)")
    }
    print(
      "live Gmail semantic evidence: runtime=\(agent.binding.runtimeType.rawValue), connectionLabel=\(connection.accountLabel ?? "connected"), searchFields=from,subject,date,snippet, readFields=\(readFieldNames.sorted().joined(separator: ",")), snippetChars=\(searchSnippet.count), bodyExcerptChars=\(bodyExcerpt.count), fakeAdapter=false, rawProviderToolExposure=false"
    )
    try expect(
      !searchFrom.isEmpty && !searchSubject.isEmpty && !searchDate.isEmpty,
      "live Gmail search semantic fields should be non-empty")
  }

  private static func testGmailLiveE2EUsesSavedMarketplaceConnection() throws {
    let environment = ProcessInfo.processInfo.environment
    guard environment["RELAY_CONSOLE_LIVE_GMAIL_E2E"] == "1" else {
      return
    }
    guard let dataPath = liveKeychainUserDataPath(environment, testName: "Gmail live E2E") else {
      return
    }
    let services = try RelayConsoleServices(
      userDataPath: URL(fileURLWithPath: dataPath, isDirectory: true),
      refreshInstalledHarnessesOnLaunch: false,
      startRuntimeBrokerServer: false
    )
    let workspace = try unwrap(
      services.data.getAppState().activeWorkspace, "missing live workspace")
    let owner = Self.context(
      roles: [.owner, .approver], workspaceId: workspace.id, correlationId: "gmail-live-e2e-owner")
    _ = try services.providerFoundations.registerGmailFoundation(context: owner, now: Date())
    let app = try unwrap(
      try services.data.getMarketplaceCatalogApp(workspaceId: workspace.id, appIdOrSlug: "gmail"),
      "missing live Gmail app"
    )
    let connection = try unwrap(
      try services.data.listProviderConnections(workspaceId: workspace.id, appId: app.id, limit: 20)
        .first(where: { $0.accountLabel == "JungleHouse" && $0.status == .connected })
        ?? services.data.listProviderConnections(
          workspaceId: workspace.id, appId: app.id, limit: 20
        ).first(where: { $0.status == .connected }),
      "missing connected Gmail Marketplace connection"
    )
    let recipient = try unwrap(
      nonEmpty(connection.connectedHandle),
      "Gmail live E2E requires the connection account email as recipient")
    let marker = "relay-live-gmail-e2e-\(Int(Date().timeIntervalSince1970))"

    let labels = try services.providerActionBroker.execute(
      context: owner,
      request: MarketplaceProviderActionBrokerRequest(
        appIdOrSlug: app.id,
        actionKey: "gmail.labels.list",
        payload: [:],
        connectionId: connection.id,
        idempotencyKey: "\(marker)-labels"
      )
    )
    try expect(labels.adapterExecuted, "live Gmail labels read should execute through broker")
    try expect(labels.execution.status == .succeeded, "live Gmail labels read should succeed")
    try expect(
      labels.execution.providerResult?["fakeAdapter"] == .bool(false),
      "live Gmail labels read must not use fake adapter evidence")
    try expect(
      labels.execution.providerResult?["clientMode"] == .string("live-gmail-api"),
      "live Gmail labels read should identify live client")

    let search = try services.providerActionBroker.execute(
      context: owner,
      request: MarketplaceProviderActionBrokerRequest(
        appIdOrSlug: app.id,
        actionKey: "gmail.messages.search",
        payload: [
          "query": .string("in:anywhere newer_than:30d"),
          "maxResults": .number(1),
        ],
        connectionId: connection.id,
        idempotencyKey: "\(marker)-search"
      )
    )
    try expect(search.adapterExecuted, "live Gmail search should execute through broker")
    try expect(search.execution.status == .succeeded, "live Gmail search should succeed")
    try expect(
      search.execution.providerResult?["fakeAdapter"] == .bool(false),
      "live Gmail search must not use fake adapter evidence")
    if let firstMessageId = firstGmailMessageId(search.execution.providerResult) {
      let read = try services.providerActionBroker.execute(
        context: owner,
        request: MarketplaceProviderActionBrokerRequest(
          appIdOrSlug: app.id,
          actionKey: "gmail.message.read",
          payload: ["messageId": .string(firstMessageId)],
          connectionId: connection.id,
          idempotencyKey: "\(marker)-read"
        )
      )
      try expect(read.adapterExecuted, "live Gmail metadata read should execute through broker")
      try expect(read.execution.status == .succeeded, "live Gmail metadata read should succeed")
      try expect(
        read.execution.providerResult?["fakeAdapter"] == .bool(false),
        "live Gmail metadata read must not use fake adapter evidence")
      let message = try unwrap(
        objectValue(read.execution.providerResult?["message"]),
        "live Gmail read should return redacted message metadata")
      try expect(
        message["bodyReturned"] == .bool(false),
        "live Gmail metadata read should not persist message body")
    }

    let draftPayload: JSONRecord = [
      "to": .string(recipient),
      "subject": .string("Relay Gmail live draft proof \(marker)"),
      "body": .string("Relay Gmail live draft proof. Marker: \(marker)."),
    ]
    let pendingDraft = try services.providerActionBroker.execute(
      context: owner,
      request: MarketplaceProviderActionBrokerRequest(
        appIdOrSlug: app.id,
        actionKey: "gmail.draft.create",
        payload: draftPayload,
        connectionId: connection.id,
        idempotencyKey: "\(marker)-draft-pending"
      )
    )
    try expect(!pendingDraft.adapterExecuted, "live Gmail draft should not execute before approval")
    try expect(
      pendingDraft.execution.status == .pendingApproval,
      "live Gmail draft should create pending approval")
    let draftApproval = try unwrap(pendingDraft.approval, "live Gmail draft should create approval")
    let approvedDraft = try services.providerActionApprovals.approve(
      context: owner,
      approvalId: draftApproval.id,
      approvedPayload: draftPayload
    )
    let draft = try services.providerActionBroker.execute(
      context: owner,
      request: MarketplaceProviderActionBrokerRequest(
        appIdOrSlug: app.id,
        actionKey: "gmail.draft.create",
        payload: draftPayload,
        connectionId: connection.id,
        approvalId: approvedDraft.id,
        idempotencyKey: "\(marker)-draft-approved"
      )
    )
    try expect(draft.adapterExecuted, "approved live Gmail draft should execute through broker")
    try expect(draft.execution.status == .succeeded, "approved live Gmail draft should succeed")
    try expect(
      draft.execution.providerResult?["fakeAdapter"] == .bool(false),
      "approved live Gmail draft must not use fake adapter evidence")
    try expect(
      nonEmpty(draft.execution.providerResult?["draftId"]?.string) != nil,
      "approved live Gmail draft should return a provider draft id")

    let sendPayload: JSONRecord = [
      "to": .string(recipient),
      "subject": .string("Relay Gmail live send proof \(marker)"),
      "body": .string("Relay Gmail live send proof. Marker: \(marker)."),
    ]
    let pendingSend = try services.providerActionBroker.execute(
      context: owner,
      request: MarketplaceProviderActionBrokerRequest(
        appIdOrSlug: app.id,
        actionKey: "gmail.email.send",
        payload: sendPayload,
        connectionId: connection.id,
        idempotencyKey: "\(marker)-send-pending"
      )
    )
    try expect(!pendingSend.adapterExecuted, "live Gmail send should not execute before approval")
    try expect(
      pendingSend.execution.status == .pendingApproval,
      "live Gmail send should create pending approval")
    let sendApproval = try unwrap(pendingSend.approval, "live Gmail send should create approval")
    let approvedSend = try services.providerActionApprovals.approve(
      context: owner,
      approvalId: sendApproval.id,
      approvedPayload: sendPayload
    )
    let sent = try services.providerActionBroker.execute(
      context: owner,
      request: MarketplaceProviderActionBrokerRequest(
        appIdOrSlug: app.id,
        actionKey: "gmail.email.send",
        payload: sendPayload,
        connectionId: connection.id,
        approvalId: approvedSend.id,
        idempotencyKey: "\(marker)-send-approved"
      )
    )
    try expect(sent.adapterExecuted, "approved live Gmail send should execute through broker")
    try expect(sent.execution.status == .succeeded, "approved live Gmail send should succeed")
    try expect(
      sent.execution.providerResult?["fakeAdapter"] == .bool(false),
      "approved live Gmail send must not use fake adapter evidence")
    try expect(
      sent.execution.providerResult?["sent"] == .bool(true),
      "approved live Gmail send should retain sent evidence")
    try expect(
      nonEmpty(sent.execution.providerResult?["messageId"]?.string) != nil,
      "approved live Gmail send should return a provider message id")

    let rejectedPayload: JSONRecord = [
      "to": .string(recipient),
      "subject": .string("Relay Gmail rejected proof \(marker)"),
      "body": .string("This rejected proof must not send."),
    ]
    let pendingRejected = try services.providerActionBroker.execute(
      context: owner,
      request: MarketplaceProviderActionBrokerRequest(
        appIdOrSlug: app.id,
        actionKey: "gmail.email.send",
        payload: rejectedPayload,
        connectionId: connection.id,
        idempotencyKey: "\(marker)-send-rejected-pending"
      )
    )
    let rejectedApproval = try unwrap(
      pendingRejected.approval, "live Gmail rejected proof should create approval")
    _ = try services.providerActionApprovals.reject(
      context: owner, approvalId: rejectedApproval.id,
      reason: "Live Gmail E2E rejected payload proof.")
    do {
      _ = try services.providerActionBroker.execute(
        context: owner,
        request: MarketplaceProviderActionBrokerRequest(
          appIdOrSlug: app.id,
          actionKey: "gmail.email.send",
          payload: rejectedPayload,
          connectionId: connection.id,
          approvalId: rejectedApproval.id,
          idempotencyKey: "\(marker)-send-rejected-execute"
        )
      )
      throw ServiceTestFailure("rejected live Gmail send unexpectedly executed")
    } catch let denied as ServiceGuardResult {
      try expect(
        denied.reasonCode == .inputInvalid,
        "rejected live Gmail send should fail before provider execution")
    }

    let blockedDelete = try services.providerActionBroker.execute(
      context: owner,
      request: MarketplaceProviderActionBrokerRequest(
        appIdOrSlug: app.id,
        actionKey: "gmail.message.delete",
        payload: ["messageId": .string("live-gmail-delete-proof-noop")],
        connectionId: connection.id,
        idempotencyKey: "\(marker)-delete-blocked"
      )
    )
    try expect(
      !blockedDelete.adapterExecuted, "live Gmail blocked delete should not execute adapter")
    try expect(
      blockedDelete.execution.status == .blocked,
      "live Gmail blocked delete should persist blocked execution")

    let retained = try services.database.all(
      "SELECT connection_json AS value FROM applications_provider_connections WHERE app_slug = 'gmail' UNION ALL SELECT execution_json AS value FROM marketplace_provider_action_executions WHERE app_id = ?",
      [.text(app.id)]
    ).compactMap { sqliteText($0["value"]) }.joined(separator: "\n")
    let savedSecretValues = try connection.secretReferenceIds.map {
      try services.secrets.getSecretValue($0)
    }
    for secretValue in savedSecretValues {
      try expect(
        !retained.contains(secretValue), "live Gmail evidence leaked a saved OAuth secret value")
    }
  }

  private static func firstGmailMessageId(_ result: JSONRecord?) -> String? {
    guard case .array(let messages)? = result?["messages"] else {
      return nil
    }
    return messages.compactMap { value -> String? in
      guard let object = objectValue(value) else { return nil }
      return nonEmpty(object["id"]?.string)
    }.first
  }

  private static func nonEmpty(_ value: String?) -> String? {
    guard let trimmed = value?.trimmingCharacters(in: .whitespacesAndNewlines), !trimmed.isEmpty
    else {
      return nil
    }
    return trimmed
  }

  private static func testProviderActionPolicyCompilerMapsRetainedProviderPresets() throws {
    let services = try makeServices()
    let workspace = try unwrap(services.data.getAppState().activeWorkspace, "missing workspace")
    let owner = Self.context(
      roles: [.owner], workspaceId: workspace.id, correlationId: "provider-policy-owner-001")
    let member = Self.context(
      roles: [.member], workspaceId: workspace.id, correlationId: "provider-policy-member-001")
    let events = EventCounter()
    _ = services.eventBus.on(.applicationsProviderActionUpdated) { _ in events.increment() }

    let catalog = try services.applications.catalogSnapshot(
      context: owner,
      selectedAppId: "x",
      now: fixedDate("2026-01-01T00:00:00Z")
    )
    let x = try unwrap(catalog.apps.first { $0.slug == "x" }, "missing X app")
    let linkedIn = try unwrap(catalog.apps.first { $0.slug == "linkedin" }, "missing LinkedIn app")
    let gmail = try unwrap(catalog.apps.first { $0.slug == "gmail" }, "missing Gmail app")
    let googleDocs = try unwrap(
      catalog.apps.first { $0.slug == "google-docs" }, "missing Google Docs app")
    let googleDrive = try unwrap(
      catalog.apps.first { $0.slug == "google-drive" }, "missing Google Drive app")
    let microsoftClarity = try unwrap(
      catalog.apps.first { $0.slug == "microsoft-clarity" }, "missing Microsoft Clarity app")
    let telemetryDeck = try unwrap(
      catalog.apps.first { $0.slug == "telemetrydeck" }, "missing TelemetryDeck app")
    let notion = try unwrap(catalog.apps.first { $0.slug == "notion" }, "missing Notion app")
    let exa = try unwrap(catalog.apps.first { $0.slug == "exa-search" }, "missing Exa Search app")

    do {
      _ = try services.providerActionPolicies.compilePolicyMap(
        context: member,
        appIdOrSlug: x.id,
        preset: .approvalRequired
      )
      throw ServiceTestFailure("member unexpectedly compiled provider action policy")
    } catch let denied as ServiceGuardResult {
      try expect(
        denied.reasonCode == .authorityRoleRequired,
        "provider action policy compile should require owner/admin")
    }

    let xApproval = try services.providerActionPolicies.compilePolicyMap(
      context: owner,
      appIdOrSlug: x.id,
      preset: .approvalRequired,
      now: fixedDate("2026-01-01T00:00:01Z")
    )
    try expect(
      xApproval.permissions["x_own_posts_list"] == .allowed, "X approval preset should allow reads")
    try expect(
      xApproval.permissions["x_post_draft"] == .allowed, "X approval preset should allow drafts")
    try expect(
      xApproval.permissions["x_text_post_create"] == .approvalRequired,
      "X approval preset should require approval for post create")
    let xDefinitions = try services.data.listMarketplaceProviderActionDefinitions(
      workspaceId: workspace.id, appId: x.id)
    try expect(xDefinitions.count == 4, "X template should persist four provider actions")
    try expect(
      xDefinitions.contains {
        $0.actionKey == "x_text_post_create" && $0.defaultPermission == .approvalRequired
      }, "X post create definition should be approval-gated by default")

    do {
      _ = try services.providerActionPolicies.compilePolicyMap(
        context: owner,
        appIdOrSlug: x.slug,
        preset: .allowDirectWrites,
        now: fixedDate("2026-01-01T00:00:02Z")
      )
      throw ServiceTestFailure("Direct writes unexpectedly compiled without acknowledgement")
    } catch let denied as ServiceGuardResult {
      try expect(
        denied.reasonCode == .inputInvalid,
        "Direct writes should require an explicit advanced acknowledgement")
    }

    let xDirect = try services.providerActionPolicies.compilePolicyMap(
      context: owner,
      appIdOrSlug: x.slug,
      preset: .allowDirectWrites, acknowledgeDangerousPolicy: true,
      now: fixedDate("2026-01-01T00:00:02Z")
    )
    try expect(
      xDirect.id == xApproval.id, "policy switching should update the same scoped permission map")
    try expect(
      xDirect.policyPreset == .allowDirectWrites,
      "policy switching should persist the direct-write preset")
    try expect(
      xDirect.createdAt == xApproval.createdAt,
      "policy switching should preserve original creation time")
    try expect(
      xDirect.permissions["x_text_post_create"] == .autoExecute,
      "X direct-write preset should auto-execute post create")
    try expect(
      xDirect.permissions["x_own_posts_list"] == .allowed,
      "X direct-write preset should keep reads allowed")
    try expect(
      xDirect.dangerousPolicyAcknowledgementVersion
        == MarketplaceProviderActionPolicyCompilerService.dangerousPolicyAcknowledgementVersion,
      "Direct writes should persist the acknowledgement contract version")
    try expect(
      xDirect.dangerousPolicyAcknowledgedAt?.isEmpty == false
        && xDirect.dangerousPolicyAcknowledgedByActorId == owner.actorId,
      "Direct writes should persist acknowledgement time and actor evidence")
    try expect(
      Set(xDirect.dangerousPolicyPreservedInvariants ?? [])
        == Set(MarketplaceProviderActionPolicyCompilerService.dangerousPolicyPreservedInvariants),
      "Direct writes should persist the complete preserved-invariant contract")
    try expect(xDirect.permissions["x_account_get"] == .allowed, "X direct-write preset should keep account reads allowed")
    try expect(
      try services.data.getMarketplaceActionPermissionMap(
        workspaceId: workspace.id, mapId: xDirect.id)?.policyPreset == .allowDirectWrites,
      "direct-write switch should be durable")

    let linkedInApproval = try services.providerActionPolicies.compilePolicyMap(
      context: owner,
      appIdOrSlug: linkedIn.id,
      preset: .approvalRequired,
      now: fixedDate("2026-01-01T00:00:03Z")
    )
    try expect(
      linkedInApproval.permissions["linkedin_profile_get"] == .allowed,
      "LinkedIn profile reads should be allowed")
    try expect(
      linkedInApproval.permissions["linkedin_text_post_create"] == .approvalRequired,
      "LinkedIn post create should require approval")
    try expect(
      linkedInApproval.permissions["linkedin.dm.send"] == .blocked, "LinkedIn DMs should be blocked"
    )
    try expect(
      linkedInApproval.permissions["linkedin.connection.request"] == .blocked,
      "LinkedIn connection requests should be blocked")
    try expect(
      linkedInApproval.permissions["linkedin.browser.scrape"] == .blocked,
      "LinkedIn browser scraping should be blocked")
    let linkedInDefinitions = try services.data.listMarketplaceProviderActionDefinitions(
      workspaceId: workspace.id, appId: linkedIn.id)
    try expect(
      linkedInDefinitions.count == 6, "LinkedIn template should persist the current six provider actions")

    let linkedInDirect = try services.providerActionPolicies.compilePolicyMap(
      context: owner,
      appIdOrSlug: linkedIn.id,
      preset: .allowDirectWrites, acknowledgeDangerousPolicy: true,
      now: fixedDate("2026-01-01T00:00:04Z")
    )
    try expect(
      linkedInDirect.permissions["linkedin_profile_get"] == .allowed,
      "LinkedIn direct-write preset should keep profile reads allowed")
    try expect(
      linkedInDirect.permissions["linkedin_post_draft"] == .allowed,
      "LinkedIn direct-write preset should keep local drafts allowed")
    try expect(
      linkedInDirect.permissions["linkedin_text_post_create"] == .autoExecute,
      "LinkedIn direct-write preset should auto-execute member posts")
    try expect(
      linkedInDirect.permissions["linkedin_comment_create"] == nil,
      "LinkedIn direct-write preset must not expose removed comment publishing")
    try expect(
      linkedInDirect.permissions["linkedin.dm.send"] == .blocked,
      "LinkedIn direct-write preset should keep DMs blocked")

    let gmailApproval = try services.providerActionPolicies.compilePolicyMap(
      context: owner,
      appIdOrSlug: gmail.id,
      preset: .approvalRequired,
      now: fixedDate("2026-01-01T00:00:05Z")
    )
    try expect(
      gmailApproval.permissions["gmail.messages.search"] == .allowed,
