    let gmailDefinitions = try services.data.listMarketplaceProviderActionDefinitions(
      workspaceId: workspace.id, appId: gmail.id)
    try expect(gmailDefinitions.count == 8, "Gmail template should persist eight provider actions")

    let gmailDirect = try services.providerActionPolicies.compilePolicyMap(
      context: owner,
      appIdOrSlug: gmail.slug,
      preset: .allowDirectWrites, acknowledgeDangerousPolicy: true,
