    )

    let confirmedNames = Set(hermesMounted.tools.prefix(2).map(\.toolName))
    let confirmedSnapshot = hermesSnapshot.confirmedRegisteredToolSnapshot(
      registeredToolNames: confirmedNames)
    try expect(
      confirmedSnapshot.toolCount == 2,
      "confirmed Google Docs snapshot should retain only registered tools")
    let confirmedPrompt = try unwrap(
      services.marketplaceRuntimeMounts.renderPromptBlock(confirmedSnapshot),
      "missing confirmed Google Docs prompt")
    try expect(
      confirmedPrompt.contains("2 brokered callable Relay tool"),
      "confirmed Google Docs prompt should count only registered tools")
    try expect(
      !confirmedPrompt.contains("google_docs_export_document"),
      "confirmed Google Docs prompt should not invent unregistered blocked tools")

    let readTool = try unwrap(
      hermesMounted.tools.first { $0.displayName == "Read document" },
