        "maxBodyChars": .number(500),
        "fakeBody": .string("Runtime Google Docs read returned semantic text through the broker."),
      ],
      runtime: MarketplaceRuntimeToolExecutionContext(
        agentId: hermesAgent.id,
        workspaceId: workspace.id,
        runtimeType: .hermes,
        dispatchId: "rtd-google-docs-runtime-read-001",
        threadId: "thr-google-docs-runtime-read-001",
        runtimeSessionId: "rts-google-docs-runtime-read-001",
        correlationId: "google-docs-runtime-read-001"
      ),
      now: fixedDate("2026-01-01T00:00:08Z")
    )
    try expect(
      readResult["toolName"] == .string(readTool.toolName),
      "Google Docs runtime bridge should echo the wrapper tool name")
    try expect(
      readResult["appSlug"] == .string("google-docs"),
      "Google Docs runtime bridge should resolve app slug")
    try expect(
      readResult["actionKey"] == .string("google_docs_read_document"),
      "Google Docs runtime bridge should resolve read action key")
    try expect(
      readResult["adapterExecuted"] == .bool(true),
      "Google Docs runtime bridge should execute read through the broker adapter")
    let providerResult = try unwrap(
      objectValue(readResult["providerResult"]),
      "Google Docs runtime read should return provider result")
    try expect(
      providerResult["semanticReadContract"] == .string("google-docs-document-summary-v1"),
      "Google Docs runtime read should preserve semantic read contract")
    let document = try unwrap(
      objectValue(providerResult["document"]),
      "Google Docs runtime read should return document result")
    try expect(
      document["text"]?.string?.contains("semantic text through the broker") == true,
      "Google Docs runtime read should return semantic text")

    try assertGoogleDocsRuntimeStorageDoesNotLeakSecrets(services: services)
  }

