      userAccessToken: nil,
      refreshToken: nil,
      teamId: "T-RUNTIME-SLACK",
      workspaceName: "Runtime Slack Workspace",
      botUserId: "B-RUNTIME-SLACK",
      displayName: "Runtime Slack",
      now: fixedDate("2026-01-01T00:00:01Z")
    )
    let agent = try createServiceAgent(services: services, workspaceId: workspace.id)
    let install = try services.marketplaceInstalls.createInstall(
      context: owner,
      request: installRequest(
        id: "minreq-slack-runtime-001",
        workspaceId: workspace.id,
        app: app,
        connectionId: connection.id,
        agent: agent,
        roleId: app.roleManifest.primaryRole,
        selectedCapabilities: app.capabilities,
        riskAcknowledged: true
      ),
      now: fixedDate("2026-01-01T00:00:02Z")
    )
    _ = try services.providerActionPolicies.compilePolicyMap(
      context: owner,
      appIdOrSlug: app.id,
      preset: .approvalRequired,
      connectionId: connection.id,
      installId: install.id,
      agentId: agent.id,
      now: fixedDate("2026-01-01T00:00:03Z")
    )

    let surface = try services.providerWrapperTools.compileSurface(
      context: owner,
      appIdOrSlug: app.id,
      installId: install.id,
      agentId: agent.id,
      now: fixedDate("2026-01-01T00:00:04Z")
    )
    try expect(
      surface.tools.count == 5, "Slack wrapper surface should expose five V1 wrapper tools")
    try expect(
      surface.diagnostics.blockedActionCount == 3,
      "Slack wrapper diagnostics should count three blocked raw/admin actions")
    try expect(
      !surface.diagnostics.rawProviderToolExposure,
      "Slack wrapper diagnostics should flag raw provider exposure as false")
    try expect(
      surface.tools.contains { $0.displayName == "Send Slack message" && $0.requiresApproval },
      "Slack send wrapper should require approval by default")
    try expect(
      surface.tools.contains { $0.displayName == "Search Slack conversations" && $0.readOnly },
      "Slack search wrapper should be read-only")
    try expect(
      !surface.tools.contains { $0.displayName == "Raw Slack API call" },
      "Slack raw API action should not mount")

    let snapshot = try services.marketplaceRuntimeMounts.snapshot(
      context: owner,
      agent: agent,
      now: fixedDate("2026-01-01T00:00:05Z")
    )
    try expect(
      snapshot.apps.map(\.appSlug) == ["slack"],
