    try expect(snapshot.toolCount == 5, "Slack runtime snapshot should expose five brokered tools")
    let mounted = try unwrap(snapshot.apps.first, "missing mounted Slack app")
    try expect(
      mounted.instructions.contains("approval-scoped message sends"),
      "Slack runtime instructions should explain approval-scoped sends")
    try expect(
      mounted.instructions.contains("raw Slack API calls"),
      "Slack runtime instructions should block raw Slack API calls")
    let prompt = try unwrap(
      services.marketplaceRuntimeMounts.renderPromptBlock(snapshot), "missing Slack runtime prompt")
    try expect(prompt.contains("Slack (slack)"), "Slack prompt should mention the mounted app")
    try expect(
      prompt.contains("5 brokered callable Relay tool"),
      "Slack prompt should count the mounted callable tools")
    try expect(
      !prompt.contains("slack_raw_api_call"),
      "Slack prompt should not include blocked raw action names")

    let searchTool = try unwrap(
      mounted.tools.first { $0.displayName == "Search Slack conversations" },
      "missing Slack search runtime tool"
    )
    let searchResult = try services.marketplaceRuntimeToolBridge.execute(
      toolName: searchTool.toolName,
      payload: [
        "query": .string("release planning"),
        "limit": .number(2),
      ],
      runtime: MarketplaceRuntimeToolExecutionContext(
        agentId: agent.id,
        workspaceId: workspace.id,
        runtimeType: .hermes,
        dispatchId: "rtd-slack-runtime-search-001",
        threadId: "thr-slack-runtime-search-001",
        runtimeSessionId: "rts-slack-runtime-search-001",
        correlationId: "slack-runtime-search-001"
      ),
      now: fixedDate("2026-01-01T00:00:06Z")
    )
    try expect(
      searchResult["appSlug"] == .string("slack"), "Slack runtime bridge should resolve app slug")
    try expect(
      searchResult["actionKey"] == .string("slack_conversation_search"),
      "Slack runtime bridge should resolve search action key")
    try expect(
      searchResult["adapterExecuted"] == .bool(true),
      "Slack runtime bridge should execute through the broker adapter")
    let providerResult = try unwrap(
      objectValue(searchResult["providerResult"]),
      "Slack runtime search should return provider result")
    try expect(
      providerResult["semanticReadContract"] == .string("slack-conversation-search-v1"),
      "Slack runtime search should preserve semantic read contract")
    let messages = try unwrap(
      arrayValue(providerResult["messages"]), "Slack runtime search should return bounded messages")
    try expect(messages.count == 2, "Slack runtime search should honor the bounded limit")

    let retained = try services.database.all(
      """
      SELECT connection_json AS value FROM applications_provider_connections
      UNION ALL SELECT install_json AS value FROM applications_marketplace_installs
      """
    ).compactMap { sqliteText($0["value"]) }.joined(separator: "\n")
    try expect(
      !retained.contains("xoxb-slack-runtime-sensitive-bot-token"),
      "Slack runtime storage leaked raw OAuth token")
    try expect(
      retained.contains("[REDACTED]"), "Slack runtime storage should retain redaction markers")
  }

