    try expect(
      searchResult["actionKey"] == .string("bitbucket_repository_search"),
      "Bitbucket runtime bridge should resolve repository search action key")
    try expect(
      searchResult["adapterExecuted"] == .bool(true),
      "Bitbucket runtime bridge should execute through the broker adapter")
    let providerResult = try unwrap(
      objectValue(searchResult["providerResult"]),
      "Bitbucket runtime search should return provider result")
    try expect(
      providerResult["semanticReadContract"] == .string("bitbucket-repository-search-v1"),
      "Bitbucket runtime search should preserve semantic read contract")
    let repositories = try unwrap(
      arrayValue(providerResult["repositories"]),
      "Bitbucket runtime search should return bounded repositories")
    try expect(repositories.count == 2, "Bitbucket runtime search should honor the bounded limit")

    let commentTool = try unwrap(
      mounted.tools.first { $0.displayName == "Create Bitbucket issue comment" },
      "missing Bitbucket issue comment runtime tool"
    )
    let pendingComment = try services.marketplaceRuntimeToolBridge.execute(
      toolName: commentTool.toolName,
      payload: [
        "repositoryPath": .string("relay-console/desktop"),
        "issueId": .number(7),
        "body": .string("Approval-gated runtime Bitbucket issue comment."),
      ],
      runtime: MarketplaceRuntimeToolExecutionContext(
        agentId: agent.id,
        workspaceId: workspace.id,
        runtimeType: .hermes,
        dispatchId: "rtd-bitbucket-runtime-comment-001",
        threadId: "thr-bitbucket-runtime-comment-001",
        runtimeSessionId: "rts-bitbucket-runtime-comment-001",
        correlationId: "bitbucket-runtime-comment-001"
      ),
      now: fixedDate("2026-01-01T00:00:06Z")
    )
    try expect(
      pendingComment["appSlug"] == .string("bitbucket"),
      "Bitbucket comment wrapper should map back to Bitbucket")
    try expect(
      pendingComment["executionStatus"]
        == .string(ProviderActionExecutionStatus.pendingApproval.rawValue),
      "Bitbucket comment wrapper should create pending approval")
    try expect(
      pendingComment["adapterExecuted"] == .bool(false),
      "Bitbucket comment wrapper must not execute before approval")
    try expect(
      pendingComment["requiresApproval"] == .bool(true),
      "Bitbucket comment wrapper should be approval-required by default")

    let retained = try services.database.all(
      """
      SELECT connection_json AS value FROM applications_provider_connections
      UNION ALL SELECT install_json AS value FROM applications_marketplace_installs
      UNION ALL SELECT execution_json AS value FROM marketplace_provider_action_executions
      """
    ).compactMap { sqliteText($0["value"]) }.joined(separator: "\n")
    try expect(!retained.contains(accessToken), "Bitbucket runtime storage leaked raw OAuth token")
    try expect(
      retained.contains("[REDACTED]"), "Bitbucket runtime storage should retain redaction markers")
  }

  private static func assertGoogleDocsRuntimeSnapshot(
    _ snapshot: MarketplaceRuntimeCapabilitySnapshot,
    runtimeType: RuntimeType,
    mounts: MarketplaceRuntimeMountService
  ) throws -> MarketplaceRuntimeMountedApp {
    try expect(
      snapshot.runtimeType == runtimeType, "Google Docs runtime snapshot should record runtime type"
    )
    try expect(
      snapshot.apps.map(\.appSlug) == ["google-docs"],
      "Google Docs runtime snapshot should contain only the assigned Google Docs app")
    try expect(
      snapshot.toolCount == 4, "Google Docs runtime snapshot should expose four V1 wrapper tools")
    try expect(
      !snapshot.rawProviderToolExposure,
      "Google Docs runtime snapshot should not expose raw provider tools")

    let mounted = try unwrap(snapshot.apps.first, "missing mounted Google Docs app")
    try expect(
      mounted.connected && mounted.assignedAgentReady,
      "Google Docs runtime mount should be connected and assigned")
    try expect(
      mounted.instructions.contains("user-specified document URLs or IDs"),
      "Google Docs runtime instructions should describe bounded document reads")
    try expect(
      mounted.instructions.contains("Direct writes"),
      "Google Docs runtime instructions should mention Direct writes policy")
    try expect(
      mounted.instructions.contains("never invoke raw Google Workspace MCP tools"),
      "Google Docs runtime instructions should block raw MCP tools")
    try expect(mounted.tools.count == 4, "Google Docs mounted app should expose four wrapper tools")

    let toolNames = mounted.tools.map(\.toolName)
    try expect(
      toolNames.allSatisfy { $0.hasPrefix("relay_provider_google_docs_") },
      "Google Docs runtime tools should use Relay wrapper names")
    try expect(
      toolNames.allSatisfy { !$0.contains(".") },
      "Google Docs runtime tool names should not expose dotted provider action names")
    try expect(
      toolNames.allSatisfy { !$0.contains("raw_mcp") },
      "Google Docs runtime should not expose raw MCP wrapper")

    let toolsByDisplayName = Dictionary(
      uniqueKeysWithValues: mounted.tools.map { ($0.displayName, $0) })
    try expect(
      toolsByDisplayName["Read document"]?.readOnly == true,
      "Google Docs runtime should expose read wrapper as read-only")
    try expect(
      toolsByDisplayName["Prepare document update"]?.requiresApproval == false,
      "Google Docs runtime should expose local prepare wrapper")
    try expect(
      toolsByDisplayName["Create document"]?.requiresApproval == true,
      "Google Docs runtime should expose approval-gated create wrapper")
    try expect(
      toolsByDisplayName["Apply document update"]?.requiresApproval == true,
      "Google Docs runtime should expose approval-gated update wrapper")
    try expect(
      toolsByDisplayName["Search Drive files"] == nil,
      "Google Docs runtime should not expose broad Drive search")

    let prompt = try unwrap(
      mounts.renderPromptBlock(snapshot), "missing Google Docs runtime prompt")
    try expect(
      prompt.contains("App: Google Docs (google-docs)"),
      "Google Docs runtime prompt should include the app")
    try expect(
      prompt.contains("4 brokered callable Relay tool"),
      "Google Docs runtime prompt should count registered tools")
    try expect(
      !prompt.contains("google_docs_raw_mcp_call"),
      "Google Docs runtime prompt should not mention blocked raw MCP action")
    try expect(
      !prompt.contains("google_docs_drive_search"),
      "Google Docs runtime prompt should not mention blocked Drive search")
    try expect(
      !prompt.contains("google-docs-runtime-refresh-token"),
      "Google Docs runtime prompt should not leak refresh token")
    return mounted
  }

  private static func assertGoogleDocsRuntimeStorageDoesNotLeakSecrets(
    services: RelayConsoleServices
  ) throws {
    let rows = try services.database.all(
      """
      SELECT connection_json AS value FROM applications_provider_connections
      UNION ALL SELECT install_json AS value FROM applications_marketplace_installs
      UNION ALL SELECT execution_json AS value FROM marketplace_provider_action_executions
      """
    )
    let retained = rows.compactMap { sqliteText($0["value"]) }.joined(separator: "\n")
    let secrets = [
      "google-docs-runtime-client-id",
      "google-docs-runtime-client-secret",
      "google-docs-runtime-refresh-token",
    ]
    for secret in secrets {
      try expect(
        !retained.contains(secret), "Google Docs runtime mount storage leaked secret \(secret)")
    }
    try expect(
      retained.contains("[REDACTED]"),
      "Google Docs runtime mount storage should retain redaction markers")
  }

  private static func testProviderActionApprovalsEnforceExactPayloadsAndExpiry() throws {
    let services = try makeServices()
    let workspace = try unwrap(services.data.getAppState().activeWorkspace, "missing workspace")
    let owner = Self.context(
      roles: [.owner], workspaceId: workspace.id, correlationId: "provider-approval-owner-001")
    let approver = Self.context(
      roles: [.approver], workspaceId: workspace.id, correlationId: "provider-approval-approver-001"
    )
    let member = Self.context(
      roles: [.member], workspaceId: workspace.id, correlationId: "provider-approval-member-001")
    let events = EventCounter()
    _ = services.eventBus.on(.applicationsProviderActionUpdated) { _ in events.increment() }

    let catalog = try services.applications.catalogSnapshot(
      context: owner,
      selectedAppId: "x",
      now: fixedDate("2026-01-01T00:00:00Z")
    )
    let x = try unwrap(catalog.apps.first { $0.slug == "x" }, "missing X app")
    _ = try services.providerActionPolicies.compilePolicyMap(
      context: owner,
      appIdOrSlug: x.id,
      preset: .approvalRequired,
      now: fixedDate("2026-01-01T00:00:01Z")
    )

    let proposedPayload: JSONRecord = [
      "text": .string("Ship the exact approved message."),
      "link": .string("https://example.invalid/post"),
      "authorization": .string("Bearer provider-action-approval-sensitive-value"),
    ]
    let expectedHash = MarketplaceProviderActionApprovalService.payloadHash(proposedPayload)
    let approval = try services.providerActionApprovals.requestApproval(
      context: owner,
      appIdOrSlug: x.id,
      actionKey: "x_text_post_create",
      proposedPayload: proposedPayload,
      expiresAt: "2026-01-01T01:00:00Z",
      idempotencyKey: "provider-approval-exact-001",
      executionId: "mpexec-provider-approval-001",
      now: fixedDate("2026-01-01T00:00:02Z")
    )
    try expect(approval.status == .pending, "provider action approval should start pending")
    try expect(
      approval.proposedPayloadHash == expectedHash,
      "provider action approval should record canonical payload hash")
    try expect(
      approval.proposedPayload["authorization"] == .string("[REDACTED]"),
      "provider action approval should redact authorization payload")

    let duplicate = try services.providerActionApprovals.requestApproval(
      context: owner,
      appIdOrSlug: x.slug,
      actionKey: "x_text_post_create",
      proposedPayload: proposedPayload,
      idempotencyKey: "provider-approval-exact-001",
      now: fixedDate("2026-01-01T00:00:03Z")
    )
    try expect(
      duplicate.id == approval.id, "approval request idempotency should return existing record")

    do {
      _ = try services.providerActionApprovals.approve(
        context: member,
        approvalId: approval.id,
        approvedPayload: proposedPayload,
        now: fixedDate("2026-01-01T00:00:04Z")
      )
      throw ServiceTestFailure("member unexpectedly approved provider action")
    } catch let denied as ServiceGuardResult {
      try expect(
        denied.reasonCode == .authorityRoleRequired,
        "provider approval resolution should require owner/admin/approver")
    }

    var changedPayload = proposedPayload
    changedPayload["text"] = .string("Changed after approval card was shown.")
    do {
      _ = try services.providerActionApprovals.approve(
        context: approver,
        approvalId: approval.id,
        approvedPayload: changedPayload,
        now: fixedDate("2026-01-01T00:00:05Z")
      )
      throw ServiceTestFailure("changed payload unexpectedly approved")
    } catch let denied as ServiceGuardResult {
      try expect(denied.reasonCode == .inputInvalid, "changed approval payload should be invalid")
    }
    try expect(
      try services.providerActionApprovals.getApproval(context: owner, approvalId: approval.id)
        .status == .pending, "mismatched payload should leave approval pending")

    let approved = try services.providerActionApprovals.approve(
      context: approver,
      approvalId: approval.id,
      approvedPayload: proposedPayload,
      now: fixedDate("2026-01-01T00:00:06Z")
    )
    try expect(approved.status == .approved, "exact payload should approve")
    try expect(
      approved.resolvedByActorId == approver.actorId, "approval should record resolver actor")
    try expect(
      approved.metadata["approvedPayloadHash"] == .string(expectedHash),
      "approval should retain approved payload hash")

    let rejectable = try services.providerActionApprovals.requestApproval(
      context: owner,
      appIdOrSlug: x.id,
      actionKey: "x_text_post_create",
      proposedPayload: ["text": .string("Rejected Post draft")],
      idempotencyKey: "provider-approval-reject-001",
      now: fixedDate("2026-01-01T00:00:07Z")
    )
    let rejected = try services.providerActionApprovals.reject(
      context: owner,
      approvalId: rejectable.id,
      reason: "Needs brand review",
      now: fixedDate("2026-01-01T00:00:08Z")
    )
    try expect(rejected.status == .rejected, "provider approval should support rejection")
    try expect(
      rejected.metadata["reason"] == .string("Needs brand review"), "rejection should retain reason"
    )

    let cancellable = try services.providerActionApprovals.requestApproval(
      context: owner,
      appIdOrSlug: x.id,
      actionKey: "x_text_post_create",
      proposedPayload: ["text": .string("Cancelled Post draft")],
      idempotencyKey: "provider-approval-cancel-001",
      now: fixedDate("2026-01-01T00:00:09Z")
    )
    let cancelled = try services.providerActionApprovals.cancel(
      context: owner,
      approvalId: cancellable.id,
      reason: "Superseded by a newer draft",
      now: fixedDate("2026-01-01T00:00:10Z")
    )
    try expect(cancelled.status == .cancelled, "provider approval should support cancellation")

    let expiredCandidate = try services.providerActionApprovals.requestApproval(
      context: owner,
      appIdOrSlug: x.id,
      actionKey: "x_text_post_create",
      proposedPayload: ["text": .string("This request expires.")],
      expiresAt: "2026-01-01T00:00:11Z",
      idempotencyKey: "provider-approval-expired-001",
      now: fixedDate("2026-01-01T00:00:10Z")
    )
    let stale = try services.providerActionApprovals.stalePendingApprovals(
      context: owner,
      now: fixedDate("2026-01-01T00:00:12Z")
    )
    try expect(
      stale.map(\.id) == [expiredCandidate.id], "expired pending approval should be reported stale")
    do {
      _ = try services.providerActionApprovals.approve(
        context: owner,
        approvalId: expiredCandidate.id,
        approvedPayload: ["text": .string("This request expires.")],
        now: fixedDate("2026-01-01T00:00:12Z")
      )
      throw ServiceTestFailure("expired approval unexpectedly approved")
    } catch let denied as ServiceGuardResult {
      try expect(
        denied.reasonCode == .inputInvalid, "expired approval should reject approval attempts")
    }
    try expect(
      try services.providerActionApprovals.getApproval(
        context: owner, approvalId: expiredCandidate.id
      ).status == .expired, "expired approval attempt should persist expired status")

    let bulkExpired = try services.providerActionApprovals.requestApproval(
      context: owner,
      appIdOrSlug: x.id,
      actionKey: "x_text_post_create",
      proposedPayload: ["text": .string("Bulk expire")],
      expiresAt: "2026-01-01T00:00:13Z",
      idempotencyKey: "provider-approval-bulk-expire-001",
      now: fixedDate("2026-01-01T00:00:12Z")
    )
    let expired = try services.providerActionApprovals.expireStaleApprovals(
      context: owner,
      now: fixedDate("2026-01-01T00:00:14Z")
    )
    try expect(
      expired.map(\.id) == [bulkExpired.id],
      "bulk stale expiry should expire pending stale approval")
    try expect(
      try services.providerActionApprovals.listApprovals(context: owner, status: .approved).map(
        \.id) == [approval.id], "approved approval should list by status")
    try expect(events.value >= 10, "provider approval transitions should publish update events")

    let sqliteDump = try services.database.all(
      """
      SELECT approval_json AS value FROM marketplace_provider_action_approvals
      UNION ALL SELECT approval_json AS value FROM marketplace_provider_action_approvals
      """
    ).compactMap { sqliteText($0["value"]) }.joined(separator: "\n")
    try expect(
      !sqliteDump.contains("provider-action-approval-sensitive-value"),
      "provider approval storage leaked raw authorization value")
    try expect(
      sqliteDump.contains("[REDACTED]"), "provider approval storage should retain redaction markers"
    )
  }

  private static func testProviderActionApprovalInboxRendersReusableCardStates() throws {
    let services = try makeServices()
    let workspace = try unwrap(services.data.getAppState().activeWorkspace, "missing workspace")
    let owner = Self.context(
      roles: [.owner], workspaceId: workspace.id, correlationId: "provider-approval-inbox-owner-001"
    )
    let member = Self.context(
      roles: [.member], workspaceId: workspace.id,
      correlationId: "provider-approval-inbox-member-001")

    let catalog = try services.applications.catalogSnapshot(
      context: owner,
      selectedAppId: "x",
      now: fixedDate("2026-01-01T00:00:00Z")
    )
    let x = try unwrap(catalog.apps.first { $0.slug == "x" }, "missing X app")
    _ = try services.providerActionPolicies.compilePolicyMap(
      context: owner,
      appIdOrSlug: x.id,
      preset: .approvalRequired,
      now: fixedDate("2026-01-01T00:00:01Z")
    )
    let definition = try unwrap(
      try services.data.listMarketplaceProviderActionDefinitions(
        workspaceId: workspace.id, appId: x.id
      )
      .first { $0.actionKey == "x_text_post_create" },
      "missing X post create definition"
    )

    func request(
      _ key: String,
      text: String,
      includeSensitivePayload: Bool = true,
      expiresAt: IsoTimestamp? = nil
    ) throws -> MarketplaceProviderActionApprovalRecord {
      var proposedPayload: JSONRecord = [
        "text": .string(text)
      ]
      if includeSensitivePayload {
        proposedPayload["authorization"] = .string("Bearer provider-approval-inbox-sensitive-value")
      }
      return try services.providerActionApprovals.requestApproval(
        context: owner,
        appIdOrSlug: x.id,
        actionKey: "x_text_post_create",
        proposedPayload: proposedPayload,
        expiresAt: expiresAt,
        idempotencyKey: key,
        now: fixedDate("2026-01-01T00:00:02Z")
      )
    }

    let pending = try request(
      "provider-approval-inbox-pending",
      text: "Pending card",
      includeSensitivePayload: false
    )
    let redactedPending = try request(
      "provider-approval-inbox-redacted-pending", text: "Redacted pending card")
    let approved = try services.providerActionApprovals.approve(
      context: owner,
      approvalId: try request("provider-approval-inbox-approved", text: "Approved card").id,
      approvedPayload: [
        "text": .string("Approved card"),
        "authorization": .string("Bearer provider-approval-inbox-sensitive-value"),
      ],
      now: fixedDate("2026-01-01T00:00:03Z")
    )
    let rejected = try services.providerActionApprovals.reject(
      context: owner,
      approvalId: try request("provider-approval-inbox-rejected", text: "Rejected card").id,
      reason: "No longer needed",
      now: fixedDate("2026-01-01T00:00:04Z")
    )
    let expired = try request(
      "provider-approval-inbox-expired",
      text: "Expired card",
      expiresAt: "2026-01-01T00:00:05Z"
    )
    let executed = try services.providerActionApprovals.approve(
      context: owner,
      approvalId: try request("provider-approval-inbox-executed", text: "Executed card").id,
      approvedPayload: [
        "text": .string("Executed card"),
        "authorization": .string("Bearer provider-approval-inbox-sensitive-value"),
      ],
      now: fixedDate("2026-01-01T00:00:06Z")
    )
    let failed = try services.providerActionApprovals.approve(
      context: owner,
      approvalId: try request("provider-approval-inbox-failed", text: "Failed card").id,
      approvedPayload: [
        "text": .string("Failed card"),
        "authorization": .string("Bearer provider-approval-inbox-sensitive-value"),
      ],
      now: fixedDate("2026-01-01T00:00:07Z")
    )
    func saveExecution(
      approval: MarketplaceProviderActionApprovalRecord,
      status: ProviderActionExecutionStatus,
      suffix: String
    ) throws {
      let reference = ProviderActionApprovalReference(
        approvalId: approval.id,
        status: approval.status,
        proposedPayloadHash: approval.proposedPayloadHash,
        expiresAt: approval.expiresAt,
        idempotencyKey: approval.idempotencyKey,
        executionId: "mpexec-provider-approval-inbox-\(suffix)",
        redactionStatus: "private-state-excluded"
      )
      let auditIdentity = ProviderExecutionAuditIdentity(
        workspaceId: workspace.id,
        actorId: owner.actorId,
        actorRole: "owner",
        agentId: nil,
        appId: x.id,
        appSlug: x.slug,
        connectionId: nil,
        installId: nil,
        approvalId: approval.id,
        dispatchId: nil,
        threadId: nil,
        source: "provider-action-inbox-test",
        redactionStatus: "private-state-excluded"
      )
      _ = try services.data.saveMarketplaceProviderActionExecution(
        MarketplaceProviderActionExecutionRecord(
          id: "mpexec-provider-approval-inbox-\(suffix)",
          workspaceId: workspace.id,
          appId: x.id,
          appSlug: x.slug,
          connectionId: nil,
          installId: nil,
          agentId: nil,
          providerActionId: definition.id,
          actionKey: definition.actionKey,
          permission: .approvalRequired,
          status: status,
          idempotencyKey: "provider-approval-inbox-exec-\(suffix)",
          requestedPayload: ["text": .string("Execution \(suffix)")],
          approvedPayloadHash: approval.proposedPayloadHash,
          approvalReference: reference,
          adapterKind: definition.adapterKind,
          auditIdentity: auditIdentity,
          providerResult: status == .succeeded ? ["ok": .bool(true)] : nil,
          providerError: status == .failed ? ["message": .string("Adapter failed")] : nil,
          startedAt: "2026-01-01T00:00:08Z",
          completedAt: "2026-01-01T00:00:09Z",
          createdAt: "2026-01-01T00:00:08Z",
          updatedAt: "2026-01-01T00:00:09Z",
          redactionStatus: "private-state-excluded"
        ))
    }
    try saveExecution(approval: executed, status: .succeeded, suffix: "executed")
    try saveExecution(approval: failed, status: .failed, suffix: "failed")

    let snapshot = try services.providerActionApprovalInbox.snapshot(
      context: member,
      selectedApprovalId: pending.id,
      now: fixedDate("2026-01-01T00:00:10Z")
    )
    try expect(snapshot.readOnly, "member approval inbox should be read-only")
    try expect(
      snapshot.selectedCard?.approvalId == pending.id, "approval inbox should retain selected card")
    try expect(snapshot.summary.pendingCount == 2, "approval inbox should count pending cards")
    try expect(snapshot.summary.approvedCount == 1, "approval inbox should count approved cards")
    try expect(snapshot.summary.rejectedCount == 1, "approval inbox should count rejected cards")
    try expect(snapshot.summary.executedCount == 1, "approval inbox should count executed cards")
    try expect(snapshot.summary.failedCount == 1, "approval inbox should count failed cards")
    try expect(snapshot.summary.expiredCount == 1, "approval inbox should count expired cards")
    let statuses = Set(snapshot.cards.map(\.status))
    try expect(
      statuses.isSuperset(of: [.pending, .approved, .rejected, .executed, .failed, .expired]),
      "approval inbox should render all required card states")
    try expect(
      snapshot.cards.first { $0.approvalId == expired.id }?.status == .expired,
      "approval inbox should derive stale pending cards as expired")
    let ownerSnapshot = try services.providerActionApprovalInbox.snapshot(
      context: owner,
      selectedApprovalId: pending.id,
      now: fixedDate("2026-01-01T00:00:10Z")
    )
    try expect(!ownerSnapshot.readOnly, "owner approval inbox should allow decisions")
    let pendingCard = try unwrap(
      ownerSnapshot.cards.first { $0.approvalId == pending.id },
      "missing exact retained pending card")
    try expect(
      pendingCard.decisionAvailableInTopLevelUI,
      "exact retained payload should be actionable from the top-level approval UI")
    try expect(
      pendingCard.decisionUnavailableReason == nil,
      "exact retained payload should not show an unavailable reason")
    try expect(
      pendingCard.payloadSummary.contains("Pending card"),
      "approval card should preview retained non-secret payload values")
    let redactedCard = try unwrap(
      ownerSnapshot.cards.first { $0.approvalId == redactedPending.id },
      "missing redacted pending card")
    try expect(
      !redactedCard.decisionAvailableInTopLevelUI,
      "redacted pending payload should not be actionable from the top-level approval UI")
    try expect(
      redactedCard.decisionUnavailableReason?.contains("exact broker payload") == true,
      "redacted pending card should explain exact payload gate")

    let encoded = String(data: try JSONEncoder().encode(snapshot), encoding: .utf8) ?? ""
    try expect(
      !encoded.contains("provider-approval-inbox-sensitive-value"),
      "approval inbox card state leaked raw authorization value")
    try expect(
      encoded.contains("[REDACTED]"), "approval inbox card state should retain redaction markers")
    try expect(
      approved.status == .approved && rejected.status == .rejected,
      "approval setup should retain approved and rejected states")
  }

  private static func testMarketplaceExecutionAuthorityMigrationFailsClosed() throws {
    let expectedRailwaySlugs: Set<String> = [
      "bluesky", "dialpad", "eventbrite", "goto-meeting", "line", "meetup",
      "nextdoor", "ringcentral", "twist", "webex", "zoho-mail",
    ]
    try expect(
      MarketplaceExecutionAuthority.railwayBrokeredAppSlugs == expectedRailwaySlugs,
      "Swift execution-authority routing drifted from the eleven Railway clients")

    let services = try makeServices()
    let workspace = try unwrap(services.data.getAppState().activeWorkspace, "missing workspace")
    let owner = Self.context(
      roles: [.owner], workspaceId: workspace.id,
      correlationId: "marketplace-authority-migration-owner")
    let foundation = try services.providerFoundations.registerBlueskyFoundation(context: owner)
    let app = try unwrap(
      try services.data.getMarketplaceCatalogApp(
        workspaceId: workspace.id, appIdOrSlug: foundation.appId),
      "missing Bluesky authority-migration app")
    let saved = try services.providerConnections.saveBlueskyRelayOwnedOAuthConnection(
      context: owner, appIdOrSlug: app.id,
      accessToken: "authority-migration-access-sensitive",
      refreshToken: "authority-migration-refresh-sensitive",
      dpopPrivateKey: "authority-migration-dpop-sensitive",
      did: "did:plc:authoritymigration123456",
      handle: "authority-migration.bsky.social",
      displayName: "Authority Migration",
      pdsOrigin: "https://pds.example/",
      authorizationIssuer: "https://auth.example/",
      callbackURL: "https://relay.example.com/api/v1/marketplace/oauth/bluesky/callback",
      grantedScopes: ProviderConnectionService.blueskyRelayOwnedOAuthScopes,
      stateVerified: true, pkceVerified: true, parVerified: true, dpopBound: true,
      didVerified: true, pdsVerified: true, issuerVerified: true)

    var legacyObject = try unwrap(
      JSONSerialization.jsonObject(with: JSONEncoder().encode(saved)) as? [String: Any],
      "failed to encode legacy Marketplace connection fixture")
    legacyObject.removeValue(forKey: "executionAuthority")
    legacyObject.removeValue(forKey: "executionAuthorityVersion")
    let legacy = try JSONDecoder().decode(
      MarketplaceProviderConnection.self,
      from: JSONSerialization.data(withJSONObject: legacyObject, options: [.sortedKeys]))
    try expect(
      legacy.executionAuthority == nil && legacy.executionAuthorityVersion == nil,
      "legacy fixture unexpectedly retained execution-authority fields")

    let migrated = try services.data.saveProviderConnection(legacy)
    try expect(
      migrated.executionAuthority == .deviceLocal
        && migrated.executionAuthorityVersion == MarketplaceExecutionAuthority.contractVersion
        && migrated.resolvedExecutionAuthority == .deviceLocal,
      "Keychain-backed legacy connection must migrate to the device-local Swift broker")

    let agent = try createServiceAgent(services: services, workspaceId: workspace.id)
    let timestamp = "2026-07-14T12:00:00Z"
    let railwayInstall = try services.data.saveMarketplaceInstall(
      MarketplaceInstallRecord(
        id: "minst-authority-migration", workspaceId: workspace.id, appId: app.id,
        appSlug: app.slug, connectionId: migrated.id, agentId: agent.id,
        agentName: agent.name, runtimeBindingId: agent.binding.id,
        harnessId: agent.harness.id, runtimeType: agent.binding.runtimeType,
        roleId: app.roleManifest.primaryRole, roleLabel: "Operator",
        selectedCapabilities: app.capabilities, approvalProfileId: nil,
        runtimeFormat: agent.binding.runtimeType, targetMode: .existingAgent,
        riskAcknowledged: true, installStatus: .installed, driftStatus: .current,
        lastInstalledAt: timestamp, removedAt: nil, failureMessage: nil,
        metadata: [:], createdByActorId: owner.actorId, createdAt: timestamp,
        updatedAt: timestamp, executionAuthority: .railway,
        executionAuthorityVersion: MarketplaceExecutionAuthority.contractVersion,
        redactionStatus: "private-state-excluded"))
    let surface = try services.providerWrapperTools.compileSurface(
      context: owner, appIdOrSlug: app.id, connectionId: migrated.id,
      installId: railwayInstall.id, agentId: agent.id)
    try expect(
      surface.tools.isEmpty && !surface.diagnostics.authorityReady
        && surface.diagnostics.message.contains("no fallback was attempted"),
      "mixed Swift/Railway records must expose zero tools and an explicit no-fallback state")

    do {
      _ = try services.providerActionBroker.execute(
        context: owner,
        request: MarketplaceProviderActionBrokerRequest(
          appIdOrSlug: app.id, actionKey: "bluesky_profile_get", payload: [:],
          connectionId: migrated.id, installId: railwayInstall.id, agentId: agent.id,
          idempotencyKey: "authority-migration-no-fallback",
          executionAuthority: .railway,
          executionAuthorityVersion: MarketplaceExecutionAuthority.contractVersion))
      throw ServiceTestFailure("mixed-authority dispatch unexpectedly reached an adapter")
    } catch let denied as ServiceGuardResult {
      try expect(
        denied.stateKind == .unavailable && denied.reasonCode == .featureUnavailable
          && denied.message.contains("no fallback was attempted"),
        "mixed-authority dispatch must fail closed as unavailable")
    }
    try expect(
      sqliteInteger(
        try services.database.get(
          "SELECT COUNT(*) AS count FROM marketplace_provider_action_executions")?["count"])
        == 0,
      "authority rejection must occur before an execution or adapter result is persisted")

    var partial = migrated
    partial.executionAuthority = .railway
    partial.executionAuthorityVersion = nil
    let unresolved = try services.data.saveProviderConnection(partial)
    try expect(
      unresolved.resolvedExecutionAuthority == nil,
      "partially versioned authority must remain unresolved instead of being guessed")
    let unresolvedSurface = try services.providerWrapperTools.compileSurface(
      context: owner, appIdOrSlug: app.id, connectionId: unresolved.id,
      installId: railwayInstall.id, agentId: agent.id)
    try expect(
      unresolvedSurface.tools.isEmpty && !unresolvedSurface.diagnostics.authorityReady,
      "partially versioned authority must fail closed with zero wrapper tools")
  }

  private static func testProviderActionBrokerEnforcesPolicyAndFakeAdapter() throws {
    let services = try makeServices()
    let workspace = try unwrap(services.data.getAppState().activeWorkspace, "missing workspace")
    let owner = Self.context(
      roles: [.owner], workspaceId: workspace.id, correlationId: "provider-broker-owner-001")
    let member = Self.context(
      roles: [.member], workspaceId: workspace.id, correlationId: "provider-broker-member-001")
    let events = EventCounter()
    _ = services.eventBus.on(.applicationsProviderActionUpdated) { _ in events.increment() }

    let catalog = try services.applications.catalogSnapshot(
      context: owner,
      selectedAppId: "x",
      now: fixedDate("2026-01-01T00:00:00Z")
    )
    let x = try unwrap(catalog.apps.first { $0.slug == "x" }, "missing X app")
    _ = try services.providerActionPolicies.compilePolicyMap(
      context: owner,
      appIdOrSlug: x.id,
      preset: .approvalRequired,
      now: fixedDate("2026-01-01T00:00:01Z")
    )
    let xPostDefinition = try unwrap(
      try services.data.listMarketplaceProviderActionDefinitions(
        workspaceId: workspace.id, appId: x.id
      )
      .first { $0.actionKey == "x_text_post_create" },
      "missing X post create definition"
    )

    do {
      _ = try services.providerActionBroker.execute(
        context: member,
        request: MarketplaceProviderActionBrokerRequest(
          appIdOrSlug: x.id,
          actionKey: "x_own_posts_list",
          payload: [:]
        ),
        now: fixedDate("2026-01-01T00:00:02Z")
      )
      throw ServiceTestFailure("member unexpectedly executed provider action")
    } catch let denied as ServiceGuardResult {
      try expect(
        denied.reasonCode == .authorityRoleRequired,
        "provider action broker should require owner/admin/operator")
    }

    let readResult = try services.providerActionBroker.execute(
      context: owner,
      request: MarketplaceProviderActionBrokerRequest(
        appIdOrSlug: x.slug,
        actionKey: "x_own_posts_list",
        payload: ["maxResults": .number(10)],
        idempotencyKey: "provider-broker-read-001",
        dispatchId: "rtd-provider-broker-read-001"
      ),
      now: fixedDate("2026-01-01T00:00:03Z")
    )
    try expect(
      readResult.adapterExecuted, "allowed read action should execute through fake adapter")
    try expect(
      readResult.execution.status == .succeeded,
      "allowed read action should persist succeeded execution")
    try expect(
      readResult.execution.providerResult?["fakeAdapter"] == .bool(true),
      "fake adapter result should be persisted")
    try expect(
      readResult.execution.auditIdentity.dispatchId == "rtd-provider-broker-read-001",
      "broker should retain dispatch audit identity")
    try expect(
      readResult.execution.executionAuthority == .deviceLocal
        && readResult.execution.executionAuthorityVersion
          == MarketplaceExecutionAuthority.contractVersion
        && readResult.execution.auditIdentity.executionAuthority == .deviceLocal
        && readResult.execution.auditIdentity.executionAuthorityVersion
          == MarketplaceExecutionAuthority.contractVersion,
      "execution and audit identity must retain the exact broker authority contract")

    let postPayload: JSONRecord = [
      "text": .string("Ship the approved broker post."),
      "authorization": .string("Bearer provider-action-broker-sensitive-value"),
    ]
    let pending = try services.providerActionBroker.execute(
      context: owner,
      request: MarketplaceProviderActionBrokerRequest(
        appIdOrSlug: x.id,
        actionKey: "x_text_post_create",
        payload: postPayload,
        idempotencyKey: "provider-broker-approval-request-001",
        threadId: "thr-provider-broker-001"
      ),
      now: fixedDate("2026-01-01T00:00:05Z")
    )
    try expect(
      !pending.adapterExecuted,
      "approval-required provider action should not execute before approval")
    try expect(
      pending.execution.status == .pendingApproval,
      "approval-required provider action should persist pending approval execution")
    let pendingApproval = try unwrap(
      pending.approval, "broker should create provider action approval")
    try expect(
      pending.execution.approvalReference?.approvalId == pendingApproval.id,
      "pending execution should link approval reference")
    try expect(
      pendingApproval.proposedPayloadHash
        == MarketplaceProviderActionApprovalService.payloadHash(postPayload),
      "broker approval should use exact payload hash")

    do {
      _ = try services.providerActionBroker.execute(
