          appIdOrSlug: x.id,
          actionKey: "x_text_post_create",
          payload: ["text": .string("Changed after approval request.")],
          approvalId: pendingApproval.id,
          idempotencyKey: "provider-broker-approved-mismatch-001"
        ),
        now: fixedDate("2026-01-01T00:00:06Z")
      )
      throw ServiceTestFailure("changed approved payload unexpectedly executed")
    } catch let denied as ServiceGuardResult {
      try expect(
        denied.reasonCode == .inputInvalid,
