    }

    let approved = try services.providerActionApprovals.approve(
      context: owner,
      approvalId: pendingApproval.id,
      approvedPayload: postPayload,
      now: fixedDate("2026-01-01T00:00:07Z")
    )
    let approvedPayloadHash = MarketplaceProviderActionApprovalService.payloadHash(postPayload)
    let approvedIdempotencyKey =
      "execute-\(xPostDefinition.id)-\(approved.id)-\(approvedPayloadHash)"
    let staleApprovedExecutionId = "mpexec-provider-broker-approved-stale"
    let staleApprovalReference = ProviderActionApprovalReference(
      approvalId: approved.id,
      status: approved.status,
      proposedPayloadHash: approved.proposedPayloadHash,
      expiresAt: approved.expiresAt,
      idempotencyKey: approved.idempotencyKey,
      executionId: staleApprovedExecutionId,
      redactionStatus: "private-state-excluded"
    )
    let staleAuditIdentity = ProviderExecutionAuditIdentity(
      workspaceId: workspace.id,
      actorId: owner.actorId,
      actorRole: "owner",
      agentId: nil,
      appId: x.id,
      appSlug: x.slug,
      connectionId: nil,
      installId: nil,
      approvalId: approved.id,
      dispatchId: nil,
      threadId: "thr-provider-broker-001",
      source: "provider-broker-stale-approved-test",
      redactionStatus: "private-state-excluded"
    )
    _ = try services.data.saveMarketplaceProviderActionExecution(
      MarketplaceProviderActionExecutionRecord(
        id: staleApprovedExecutionId,
        workspaceId: workspace.id,
        appId: x.id,
        appSlug: x.slug,
        connectionId: nil,
        installId: nil,
        agentId: nil,
        providerActionId: xPostDefinition.id,
        actionKey: xPostDefinition.actionKey,
        permission: .approvalRequired,
        status: .pendingApproval,
        idempotencyKey: approvedIdempotencyKey,
        requestedPayload: postPayload,
        approvedPayloadHash: approvedPayloadHash,
        approvalReference: staleApprovalReference,
        adapterKind: xPostDefinition.adapterKind,
        auditIdentity: staleAuditIdentity,
        providerResult: nil,
        providerError: nil,
        startedAt: nil,
        completedAt: nil,
        createdAt: "2026-01-01T00:00:07Z",
        updatedAt: "2026-01-01T00:00:07Z",
        redactionStatus: "private-state-excluded"
      ))
    let approvedExecution = try services.providerActionBroker.execute(
      context: owner,
      request: MarketplaceProviderActionBrokerRequest(
        appIdOrSlug: x.id,
        actionKey: "x_text_post_create",
        payload: postPayload,
        approvalId: approved.id
      ),
      now: fixedDate("2026-01-01T00:00:08Z")
    )
    try expect(approvedExecution.adapterExecuted, "approved provider action should execute adapter")
    try expect(
      approvedExecution.execution.id == staleApprovedExecutionId,
      "approved execution should replace a stale pending approved execution")
    try expect(
      approvedExecution.execution.status == .succeeded,
      "approved provider action should persist succeeded execution")
    try expect(
      approvedExecution.execution.approvalReference?.status == .approved,
      "approved execution should retain approved reference")
    try expect(
      approvedExecution.execution.providerResult?["approved"] == .bool(true),
      "fake adapter should receive approval reference")
    try expect(
      approvedExecution.execution.providerResult?["provider"] == .string("x"),
      "approved X post should return X provider evidence")
    try expect(
      approvedExecution.execution.providerResult?["actionFamily"] == .string("public-social-text"),
      "approved X post should use text action family")
    try expect(
      approvedExecution.execution.providerResult?["postId"] != nil,
      "approved X post should return a deterministic post id")
    let resubmittedApprovedRequest = try services.providerActionBroker.execute(
      context: owner,
      request: MarketplaceProviderActionBrokerRequest(
        appIdOrSlug: x.id,
        actionKey: "x_text_post_create",
        payload: postPayload,
        idempotencyKey: "provider-broker-approval-request-001",
        threadId: "thr-provider-broker-001"
      ),
      now: fixedDate("2026-01-01T00:00:08Z")
    )
    try expect(
      !resubmittedApprovedRequest.adapterExecuted,
      "resubmitting an already-approved request should not duplicate provider execution")
    try expect(
      resubmittedApprovedRequest.execution.id == approvedExecution.execution.id,
      "resubmitting an approved request should return the resolved execution")
    try expect(
      resubmittedApprovedRequest.execution.status == .succeeded,
