    )
    try expect(
      legacySurface.diagnostics.autoExecuteCount == 0,
      "Legacy Direct writes maps should not expose auto-executing wrapper tools")

    _ = try services.providerActionPolicies.compilePolicyMap(
      context: owner,
      appIdOrSlug: x.id,
      preset: .allowDirectWrites, acknowledgeDangerousPolicy: true,
      now: fixedDate("2026-01-01T00:00:09Z")
    )
    let direct = try services.providerActionBroker.execute(
