    let admin = try services.providerActionBroker.execute(
      context: owner,
      request: MarketplaceProviderActionBrokerRequest(
        appIdOrSlug: github.id,
        actionKey: "github_repo_admin",
        payload: ["owner": .string("relay-console"), "repo": .string("desktop")],
        installId: install.id,
        idempotencyKey: "github-admin-blocked-001"
      ),
