    )
    try expect(
      !admin.adapterExecuted, "GitHub admin actions should never execute through the adapter")
    try expect(
      admin.execution.status == .blocked, "GitHub admin actions should persist blocked execution")

    let sqliteDump = try services.database.all(
      """
      SELECT connection_json AS value FROM applications_provider_connections
      UNION ALL SELECT execution_json AS value FROM marketplace_provider_action_executions
      UNION ALL SELECT approval_json AS value FROM marketplace_provider_action_approvals
      UNION ALL SELECT map_json AS value FROM marketplace_action_permission_maps
      """
    ).compactMap { sqliteText($0["value"]) }.joined(separator: "\n")
    try expect(
      !sqliteDump.contains(accessToken),
      "GitHub provider action persistence leaked raw access token")
    try expect(
      !sqliteDump.localizedCaseInsensitiveContains("github raw api"),
      "GitHub wrapper persistence should not expose raw API tooling")
    try expect(
      sqliteDump.contains("[REDACTED]"),
      "GitHub provider action persistence should retain redaction markers")
  }

