      roles: [.member], workspaceId: workspace.id, correlationId: "provider-wrapper-member-001")
    let viewer = Self.context(
      roles: [.viewer], workspaceId: workspace.id, correlationId: "provider-wrapper-viewer-001")

    let catalog = try services.applications.catalogSnapshot(
      context: owner,
      selectedAppId: "x",
      now: fixedDate("2026-01-01T00:00:00Z")
    )
    let x = try unwrap(catalog.apps.first { $0.slug == "x" }, "missing X app")
    let agent = try createServiceAgent(services: services, workspaceId: workspace.id)
    let unassignedAgent = try createServiceAgent(services: services, workspaceId: workspace.id)
    let secret = try services.secrets.set(
      scope: "provider_connection",
      scopeId: x.id,
      label: "X wrapper token",
      secretValue: "token=provider-wrapper-sensitive-value"
    )
    let connection = try services.data.saveProviderConnection(
      providerConnection(
        workspaceId: workspace.id,
        app: x,
        status: .connected,
        authorizationState: .completed,
        secretReferenceId: secret.id,
        accountLabel: "Wrapper Tools Account",
        connectedHandle: "wrapper-tools",
        lastError: nil
      ))
    let timestamp = "2026-01-01T00:00:01Z"
    let install = try services.data.saveMarketplaceInstall(
      MarketplaceInstallRecord(
        id: "minst-provider-wrapper-001",
        workspaceId: workspace.id,
        appId: x.id,
        appSlug: x.slug,
        connectionId: connection.id,
        agentId: agent.id,
        agentName: agent.name,
        runtimeBindingId: agent.binding.id,
        harnessId: agent.harness.id,
        runtimeType: agent.binding.runtimeType,
        roleId: "operator",
        roleLabel: "Operator",
        selectedCapabilities: x.capabilities,
        approvalProfileId: "approval-provider-wrapper-default",
        runtimeFormat: agent.binding.runtimeType,
        targetMode: .existingAgent,
        riskAcknowledged: true,
        installStatus: .installed,
        driftStatus: .current,
        lastInstalledAt: timestamp,
        removedAt: nil,
        failureMessage: nil,
        metadata: [
          "wrapperToolCompiler": .bool(true),
          "secret": .string("provider-wrapper-sensitive-value"),
        ],
        createdByActorId: owner.actorId,
        createdAt: timestamp,
        updatedAt: timestamp,
        redactionStatus: "private-state-excluded"
      ))
    let approvalPolicy = try services.providerActionPolicies.compilePolicyMap(
      context: owner,
      appIdOrSlug: x.id,
      preset: .approvalRequired,
      connectionId: connection.id,
      installId: install.id,
      agentId: agent.id,
      now: fixedDate("2026-01-01T00:00:02Z")
    )

    do {
      _ = try services.providerWrapperTools.compileSurface(
        context: viewer,
        appIdOrSlug: x.id,
        installId: install.id,
        agentId: agent.id,
        now: fixedDate("2026-01-01T00:00:03Z")
      )
      throw ServiceTestFailure("viewer unexpectedly read provider wrapper tools")
    } catch let denied as ServiceGuardResult {
      try expect(
        denied.reasonCode == .authorityRoleRequired,
        "wrapper tool compiler should require workspace read authority")
    }

    let approvalSurface = try services.providerWrapperTools.compileSurface(
      context: member,
      appIdOrSlug: x.id,
      installId: install.id,
      agentId: agent.id,
      now: fixedDate("2026-01-01T00:00:04Z")
    )
    try expect(
      approvalSurface.permissionMapId == approvalPolicy.id,
      "wrapper surface should select the scoped permission map")
    try expect(approvalSurface.readOnly, "member wrapper surface should be read-only")
    try expect(
      approvalSurface.tools.count == 4, "approval policy should expose four safe X wrapper tools")
    try expect(
      approvalSurface.executionAuthority == .deviceLocal
        && approvalSurface.executionAuthorityVersion
          == MarketplaceExecutionAuthority.contractVersion
        && approvalSurface.diagnostics.executionAuthority == .deviceLocal
        && approvalSurface.diagnostics.authorityReady
        && approvalSurface.tools.allSatisfy {
          $0.executionAuthority == .deviceLocal
            && $0.executionAuthorityVersion == MarketplaceExecutionAuthority.contractVersion
            && $0.metadata["executionAuthority"] == .string("swift")
        },
      "wrapper surface, diagnostics, tools, and metadata must retain one exact authority")
    try expect(
      approvalSurface.tools.contains { $0.displayName == "Read connected account" && $0.readOnly },
      "read action should compile as read-only wrapper")
    try expect(
      approvalSurface.tools.contains { $0.displayName == "Publish text Post" && $0.requiresApproval },
      "post create should require approval")
    try expect(
      approvalSurface.tools.contains { $0.displayName == "Draft post" },
      "local draft should compile as a non-publishing wrapper")
    try expect(approvalSurface.diagnostics.blockedActionCount == 0, "unsupported X actions must be suppressed rather than advertised")
    try expect(
      approvalSurface.diagnostics.rawProviderToolExposure == false,
      "wrapper diagnostics should flag raw provider tool exposure as false")
    try expect(
      approvalSurface.diagnostics.suppressedRawProviderToolCount >= approvalSurface.tools.count,
      "wrapper diagnostics should count suppressed raw provider tools")

    let encodedTools = try String(
      data: JSONEncoder().encode(approvalSurface.tools), encoding: .utf8
    ).map {
      $0.lowercased()
    }
    let agentFacingTools = try unwrap(encodedTools, "missing encoded wrapper tool JSON")
    for leaked in [
      "tweet.write",
      "publish_posts",
      "publish_replies",
      "official_mcp",
      "community_mcp",
      "xmcp",
    ] {
      try expect(
        !agentFacingTools.contains(leaked),
        "agent-facing wrapper tools leaked raw provider/MCP term \(leaked)")
    }
    try expect(Set(approvalSurface.tools.map(\.toolName)) == ["relay_x_get_account", "relay_x_list_own_posts", "relay_x_draft_text_post", "relay_x_publish_text_post"], "wrapper tool names should use the stable X namespace")
    try expect(
      approvalSurface.tools.allSatisfy { !$0.toolName.contains(".") },
      "wrapper tool names should not expose dotted provider action names")

    _ = try services.providerActionPolicies.compilePolicyMap(
      context: owner,
      appIdOrSlug: x.id,
      preset: .allowDirectWrites, acknowledgeDangerousPolicy: true,
      connectionId: connection.id,
      installId: install.id,
      agentId: agent.id,
      now: fixedDate("2026-01-01T00:00:05Z")
    )
    let directSurface = try services.providerWrapperTools.compileSurface(
      context: owner,
      appIdOrSlug: x.id,
      installId: install.id,
      agentId: agent.id,
      now: fixedDate("2026-01-01T00:00:06Z")
    )
    let directPost = try unwrap(
      directSurface.tools.first { $0.displayName == "Publish text Post" }, "missing direct post wrapper")
    try expect(
      directPost.executionMode == .autoExecute,
      "direct-write policy should compile post create as auto-execute")
    try expect(
      directPost.autoExecutes && !directPost.requiresApproval,
      "direct-write wrapper should not require approval")
    try expect(
      directSurface.diagnostics.autoExecuteCount == 1,
      "direct-write diagnostics should count auto-execute wrappers")

    let unassignedSurface = try services.providerWrapperTools.compileSurface(
      context: owner,
      appIdOrSlug: x.id,
      agentId: unassignedAgent.id,
      now: fixedDate("2026-01-01T00:00:07Z")
    )
    try expect(
      unassignedSurface.tools.isEmpty, "unassigned agent should not receive provider wrapper tools")
    try expect(
      !unassignedSurface.diagnostics.assignedAgentReady,
      "unassigned wrapper surface should report missing assignment")

    let storedInstall = try unwrap(
      try services.data.getMarketplaceInstall(workspaceId: workspace.id, installId: install.id),
      "missing stored wrapper install"
    )
    try expect(
      storedInstall.metadata["secret"] == .string("[REDACTED]"),
      "wrapper test install metadata should remain redacted")
  }

