    func assertSnapshot(_ snapshot: MarketplaceRuntimeCapabilitySnapshot, runtimeType: RuntimeType)
      throws
    {
      try expect(
        snapshot.runtimeType == runtimeType, "runtime mount snapshot should record the runtime type"
      )
      try expect(
        snapshot.apps.map(\.appSlug) == ["exa-search", "gmail", "linkedin", "notion", "x"],
        "runtime mount should compile all installed provider apps in stable order")
      try expect(snapshot.toolCount == snapshot.apps.reduce(0) { $0 + $1.tools.count }, "runtime mount tool count must equal its policy-scoped app surfaces")
      try expect(Set(snapshot.apps.first { $0.appSlug == "x" }?.tools.map(\.toolName) ?? []) == ["relay_x_get_account", "relay_x_list_own_posts", "relay_x_draft_text_post", "relay_x_publish_text_post"], "runtime mount must expose exactly four stable X wrappers")
      try expect(
        !snapshot.rawProviderToolExposure, "runtime mount should not expose raw provider tools")
      try expect(
        snapshot.redactionStatus == "private-state-excluded",
        "runtime mount should retain redaction evidence")
      try expect(
        snapshot.apps.allSatisfy { $0.connected && $0.assignedAgentReady },
        "runtime mount apps should be connected and assigned")
      try expect(
        snapshot.apps.allSatisfy {
          $0.tools.allSatisfy { $0.toolName.hasPrefix("relay_") }
        }, "runtime mount should only expose Relay wrapper tool names")
      try expect(
        snapshot.apps.allSatisfy { !$0.diagnostics.rawProviderToolExposure },
        "runtime mount diagnostics should suppress raw provider tools")
      let prompt = try unwrap(
        services.marketplaceRuntimeMounts.renderPromptBlock(snapshot),
        "missing rendered runtime mount prompt")
      try expect(
        prompt.contains("Relay Marketplace Provider Capabilities"),
        "runtime mount prompt should identify the provider capability snapshot")
      try expect(prompt.contains("App: X (x)"), "runtime mount prompt should include X")
      try expect(
        prompt.contains("App: Exa Search (exa-search)"),
        "runtime mount prompt should include Exa Search")
      try expect(prompt.contains("App: Gmail (gmail)"), "runtime mount prompt should include Gmail")
      try expect(
        prompt.contains("App: LinkedIn (linkedin)"), "runtime mount prompt should include LinkedIn")
      try expect(
        prompt.contains("App: Notion (notion)"), "runtime mount prompt should include Notion")
      try expect(
        !prompt.contains("relay_x_"),
        "runtime mount prompt should not render X wrapper names as fake text tools")
      try expect(
        !prompt.contains("relay_provider_exa_search_"),
        "runtime mount prompt should not render Exa wrapper names as fake text tools")
      try expect(
        !prompt.contains("relay_provider_gmail_"),
        "runtime mount prompt should not render Gmail wrapper names as fake text tools")
      try expect(
        !prompt.contains("relay_provider_linkedin_"),
        "runtime mount prompt should not render LinkedIn wrapper names as fake text tools")
      try expect(
        !prompt.contains("relay_provider_notion_"),
        "runtime mount prompt should not render Notion wrapper names as fake text tools")
      for leaked in [
        xAccessToken,
        xRefreshToken,
        exaSecret,
        linkedInAccessToken,
        linkedInRefreshToken,
        gmailClientId,
        gmailRefreshToken,
        notionToken,
        "EXA_API_KEY",
        "X_ACCESS_TOKEN",
        "x_text_post_create",
        "gmail.email.send",
        "linkedin_text_post_create",
        "exa.search.web",
        "notion_raw_mcp_call",
        "notion.admin",
        "official_mcp",
        "community_mcp",
        "xmcp",
      ] {
        try expect(
          !prompt.contains(leaked),
          "runtime mount prompt leaked raw provider state or tool surface \(leaked)")
      }
    }

    func assertGmailRuntimeBridge(
      snapshot: MarketplaceRuntimeCapabilitySnapshot, agent: AgentWithBinding, suffix: String
    ) throws {
      let gmailApp = try unwrap(
        snapshot.apps.first { $0.appSlug == "gmail" }, "missing Gmail runtime mount app")
      let searchTool = try unwrap(
        gmailApp.tools.first { $0.displayName == "Search messages" },
        "missing Gmail search wrapper tool"
      )
      let readTool = try unwrap(
        gmailApp.tools.first { $0.displayName == "Read message" },
        "missing Gmail read wrapper tool"
      )
      let createDraftTool = try unwrap(
        gmailApp.tools.first { $0.displayName == "Create draft" },
        "missing Gmail draft wrapper tool"
      )
      let sendTool = try unwrap(
        gmailApp.tools.first { $0.displayName == "Send email" },
        "missing Gmail send wrapper tool"
      )
      let searchResult = try services.marketplaceRuntimeToolBridge.execute(
        toolName: searchTool.toolName,
        payload: [
          "query": .string("from:fixture.sender@example.com newer_than:7d"),
          "maxResults": .number(1),
        ],
        runtime: MarketplaceRuntimeToolExecutionContext(
          agentId: agent.id,
          workspaceId: workspace.id,
          runtimeType: snapshot.runtimeType,
          dispatchId: "rtd-runtime-bridge-gmail-search-\(suffix)",
          threadId: "thr-runtime-bridge-gmail-search-\(suffix)",
          runtimeSessionId: "rts-runtime-bridge-gmail-search-\(suffix)",
          correlationId: "runtime-bridge-gmail-search-\(suffix)"
        ),
        now: fixedDate("2026-01-01T00:00:10Z")
      )
      try expect(
        searchResult["toolName"] == .string(searchTool.toolName),
        "Gmail runtime bridge should echo the search wrapper tool name")
      try expect(
        searchResult["appSlug"] == .string("gmail"),
        "Gmail runtime bridge should map search wrapper back to Gmail")
      try expect(
        searchResult["actionKey"] == .string("gmail.messages.search"),
        "Gmail runtime bridge should resolve search action key")
      try expect(
        searchResult["adapterExecuted"] == .bool(true),
        "Gmail runtime bridge should execute search through the broker adapter")
      let searchProviderResult = try unwrap(
        objectValue(searchResult["providerResult"]),
        "Gmail search bridge should return provider result")
      try expect(
        searchProviderResult["clientMode"] == .string("fake-gmail-api"),
        "Gmail search bridge should use deterministic fake provider result")
      guard case .array(let messages)? = searchProviderResult["messages"],
        let firstMessage = messages.compactMap(objectValue).first
      else {
        throw ServiceTestFailure("Gmail runtime search should return semantic message summaries")
      }
      try expect(
        firstMessage["from"] == .string("Fixture Sender <fixture.sender@example.com>"),
        "Gmail runtime search should include sender")
      try expect(
        firstMessage["subject"] == .string("Redacted Gmail fixture"),
        "Gmail runtime search should include subject")
      try expect(
        firstMessage["date"] == .string("2026-01-01T00:00:00Z"),
        "Gmail runtime search should include date")
      try expect(
        firstMessage["snippet"]?.string?.contains("Redacted Gmail search fixture") == true,
        "Gmail runtime search should include snippet")

      let readResult = try services.marketplaceRuntimeToolBridge.execute(
        toolName: readTool.toolName,
        payload: [
          "messageId": .string(firstMessage["id"]?.string ?? "gmail-msg-runtime-\(suffix)"),
          "format": .string("summary"),
          "maxBodyChars": .number(120),
        ],
        runtime: MarketplaceRuntimeToolExecutionContext(
          agentId: agent.id,
          workspaceId: workspace.id,
          runtimeType: snapshot.runtimeType,
          dispatchId: "rtd-runtime-bridge-gmail-read-\(suffix)",
          threadId: "thr-runtime-bridge-gmail-read-\(suffix)",
          runtimeSessionId: "rts-runtime-bridge-gmail-read-\(suffix)",
          correlationId: "runtime-bridge-gmail-read-\(suffix)"
        ),
        now: fixedDate("2026-01-01T00:00:10Z")
      )
      try expect(
        readResult["toolName"] == .string(readTool.toolName),
        "Gmail runtime bridge should echo the read wrapper tool name")
      try expect(
        readResult["appSlug"] == .string("gmail"),
        "Gmail runtime bridge should map read wrapper back to Gmail")
      try expect(
        readResult["actionKey"] == .string("gmail.message.read"),
        "Gmail runtime bridge should resolve read action key")
      try expect(
        readResult["adapterExecuted"] == .bool(true),
        "Gmail runtime bridge should execute read through the broker adapter")
      let readProviderResult = try unwrap(
        objectValue(readResult["providerResult"]), "Gmail read bridge should return provider result"
      )
      let message = try unwrap(
        objectValue(readProviderResult["message"]),
        "Gmail runtime read should return a message object")
      try expect(
        message["from"] == .string("Fixture Sender <fixture.sender@example.com>"),
        "Gmail runtime read should include sender")
      try expect(
        message["subject"] == .string("Redacted Gmail fixture"),
        "Gmail runtime read should include subject")
      try expect(
        message["date"] == .string("2026-01-01T00:00:00Z"), "Gmail runtime read should include date"
      )
      try expect(
        message["bodyReturned"] == .bool(true),
        "Gmail runtime read should include bounded body proof")
      try expect(
        message["bodyExcerpt"]?.string?.contains("Message body excerpt") == true,
        "Gmail runtime read should include body excerpt")

      func assertApprovalWrapper(
        tool: RelayProviderWrapperTool,
        actionKey: String,
        payload: JSONRecord,
        dispatchSuffix: String
      ) throws {
        let pending = try services.marketplaceRuntimeToolBridge.execute(
          toolName: tool.toolName,
          payload: payload,
          runtime: MarketplaceRuntimeToolExecutionContext(
            agentId: agent.id,
            workspaceId: workspace.id,
            runtimeType: snapshot.runtimeType,
            dispatchId: "rtd-runtime-bridge-gmail-\(dispatchSuffix)-\(suffix)",
            threadId: "thr-runtime-bridge-gmail-\(dispatchSuffix)-\(suffix)",
            runtimeSessionId: "rts-runtime-bridge-gmail-\(dispatchSuffix)-\(suffix)",
            correlationId: "runtime-bridge-gmail-\(dispatchSuffix)-\(suffix)"
          ),
          now: fixedDate("2026-01-01T00:00:10Z")
        )
        try expect(
          pending["toolName"] == .string(tool.toolName),
          "Gmail runtime write wrapper should echo the wrapper tool name")
        try expect(
          pending["appSlug"] == .string("gmail"),
          "Gmail runtime write wrapper should map back to Gmail")
        try expect(
          pending["actionKey"] == .string(actionKey),
          "Gmail runtime write wrapper should resolve the expected action")
        try expect(
          pending["ok"] == .bool(true),
          "Gmail runtime write wrapper should return a clean pending result")
        try expect(
          pending["executionStatus"]
            == .string(ProviderActionExecutionStatus.pendingApproval.rawValue),
          "Gmail runtime write wrapper should create a pending approval execution")
        try expect(
          pending["adapterExecuted"] == .bool(false),
          "Gmail runtime write wrapper must not execute the adapter before approval")
        try expect(
          pending["requiresApproval"] == .bool(true),
          "Gmail runtime write wrapper should be marked approval-required")
        let approval = try unwrap(
          objectValue(pending["approval"]),
          "Gmail runtime write wrapper should return approval metadata")
        let approvalId = try unwrap(
          approval["approvalId"]?.string, "Gmail runtime write wrapper should include approval id")
        let approvalRecord = try services.providerActionApprovals.getApproval(
          context: owner, approvalId: approvalId)
        try expect(
          approvalRecord.status == .pending,
          "Gmail runtime write wrapper should create a pending provider-action approval")
        try expect(
          !String(describing: pending).contains("live-gmail-api"),
          "Gmail runtime write wrapper pending approval must not reach live Gmail")
      }

      let writePayload: JSONRecord = [
        "to": .string("recipient@example.com"),
        "subject": .string("Runtime Gmail approval proof \(suffix)"),
        "body": .string("This fake runtime proof must stop at pending approval."),
      ]
      try assertApprovalWrapper(
        tool: createDraftTool,
        actionKey: "gmail.draft.create",
        payload: writePayload,
        dispatchSuffix: "draft"
      )
      try assertApprovalWrapper(
        tool: sendTool,
        actionKey: "gmail.email.send",
        payload: writePayload,
        dispatchSuffix: "send"
      )
    }

