    func runtimeRequest(agent: AgentWithBinding, suffix: String) -> RuntimeDispatchRequest {
      RuntimeDispatchRequest(
        dispatchId: "rtd-runtime-harness-\(suffix)",
        correlationId: "corr-runtime-harness-\(suffix)",
        threadId: "thr-runtime-harness-\(suffix)",
        messageId: "msg-runtime-harness-\(suffix)",
        sessionId: "rts-runtime-harness-\(suffix)",
        attempt: 1,
        agent: agent,
        runtimeBinding: agent.binding,
        harness: agent.harness,
        inputContent: "what tools do you have?",
        inputFormat: .plain,
        recentMessages: [],
        timeoutMs: 30_000,
        createdAt: "2026-01-01T00:00:12Z"
      )
    }

    let openClawConfigURL = services.paths.openClawHomeDir.appendingPathComponent("openclaw.json")
    try FileManager.default.createDirectory(
      at: openClawConfigURL.deletingLastPathComponent(),
      withIntermediateDirectories: true
    )
    let existingOpenClawConfig: [String: Any] = [
      "plugins": [
        "entries": [
          "clawchat": ["enabled": true],
          "codex": ["enabled": true],
          "openai": ["enabled": true],
          "disabled-plugin": ["enabled": false],
        ]
      ]
    ]
    try JSONSerialization.data(withJSONObject: existingOpenClawConfig, options: [.sortedKeys])
      .write(to: openClawConfigURL, options: .atomic)

    let openClawHarnessInstall = try services.harnessInstall.prepareMarketplaceRuntimeToolBridge(
      for: openClawAgent,
      request: runtimeRequest(agent: openClawAgent, suffix: "openclaw"),
      harnessPath: URL(
        fileURLWithPath: try unwrap(
          openClawHarness.config["installPath"]?.string, "missing OpenClaw harness path")),
      mount: openClawSnapshot
    )
    try expect(
      openClawHarnessInstall.registeredToolNames == Set(openClawSnapshot.mountedToolNames),
      "OpenClaw adapter should confirm every policy-scoped wrapper tool as registered")
    try expect(
      openClawHarnessInstall.requiresHarnessRefresh,
      "OpenClaw adapter should request a harness refresh when it changes marketplace plugin config")
    let openClawPluginDir = services.paths.root
      .appendingPathComponent("marketplace-runtime", isDirectory: true)
      .appendingPathComponent("openclaw-relay-marketplace-plugin", isDirectory: true)
    let openClawManifestURL = openClawPluginDir.appendingPathComponent("openclaw.plugin.json")
    let openClawManifestData = try Data(contentsOf: openClawManifestURL)
    guard
      let openClawManifest = try JSONSerialization.jsonObject(with: openClawManifestData)
        as? [String: Any],
      let contracts = openClawManifest["contracts"] as? [String: Any],
      let contractTools = contracts["tools"] as? [String]
    else {
      throw ServiceTestFailure("OpenClaw marketplace plugin manifest was not valid JSON")
    }
    try expect(
      Set(contractTools) == Set(openClawSnapshot.mountedToolNames),
      "OpenClaw manifest contracts.tools must declare the exact generated wrapper tools")
    try expect(
      !contractTools.contains("relay-marketplace"),
      "OpenClaw manifest must not use the plugin id as a fake tool contract")
    try expect(
      contractTools.contains { $0.hasPrefix("relay_x_") },
      "OpenClaw harness contracts should include X wrapper tools")
    try expect(
      contractTools.contains { $0.hasPrefix("relay_provider_exa_search_") },
      "OpenClaw harness contracts should include Exa wrapper tools")
    try expect(
      contractTools.contains { $0.hasPrefix("relay_provider_gmail_") },
      "OpenClaw harness contracts should include Gmail wrapper tools")
    try expect(
      contractTools.contains { $0.hasPrefix("relay_linkedin_") },
      "OpenClaw harness contracts should include LinkedIn wrapper tools")
    try expect(
      contractTools.contains { $0.hasPrefix("relay_provider_notion_") },
      "OpenClaw harness contracts should include Notion wrapper tools")
    let openClawConfigData = try Data(contentsOf: openClawConfigURL)
    guard
      let openClawConfig = try JSONSerialization.jsonObject(with: openClawConfigData)
        as? [String: Any],
      let openClawPlugins = openClawConfig["plugins"] as? [String: Any],
      let openClawAllow = openClawPlugins["allow"] as? [String],
      let openClawLoad = openClawPlugins["load"] as? [String: Any],
      let openClawLoadPaths = openClawLoad["paths"] as? [String],
      let openClawEntries = openClawPlugins["entries"] as? [String: Any],
      let openClawMarketplaceEntry = openClawEntries["relay-marketplace"] as? [String: Any],
      let openClawMarketplaceConfig = openClawMarketplaceEntry["config"] as? [String: Any],
      let openClawMarketplaceBridgeEnvironment = openClawMarketplaceConfig["bridgeEnvironment"]
        as? [String: String]
    else {
      throw ServiceTestFailure("OpenClaw marketplace plugin config was not valid JSON")
    }
    try expect(
      openClawAllow.contains("relay-marketplace"),
      "OpenClaw marketplace plugin must be explicitly admitted through plugins.allow")
    try expect(
      Set(openClawAllow) == Set(["clawchat", "codex", "openai", "relay-marketplace"]),
      "creating plugins.allow must preserve enabled OpenClaw plugins without admitting disabled entries")
    try expect(
      openClawLoadPaths.contains(openClawPluginDir.path),
      "OpenClaw marketplace plugin path must be present in plugins.load.paths")
    try expect(
      openClawMarketplaceConfig["snapshotPath"] as? String != nil,
      "OpenClaw marketplace plugin config must persist the mounted capability snapshot path")
    try expect(
      openClawMarketplaceConfig["bridgeCommand"] as? String != nil,
      "OpenClaw marketplace plugin config must persist the Relay bridge command")
    try expect(
      openClawMarketplaceConfig["bridgeArgs"] as? [String] != nil,
      "OpenClaw marketplace plugin config must persist the Relay bridge args")
    try expect(
      openClawMarketplaceBridgeEnvironment["RELAY_MARKETPLACE_AGENT_ID"] == openClawAgent.id,
      "OpenClaw marketplace plugin config must include the Relay agent id for bridge fallback execution"
    )
    try expect(
      openClawMarketplaceBridgeEnvironment["RELAY_MARKETPLACE_WORKSPACE_ID"] == workspace.id,
      "OpenClaw marketplace plugin config must include the Relay workspace id for bridge fallback execution"
    )
    try expect(
      openClawMarketplaceBridgeEnvironment["RELAY_MARKETPLACE_RUNTIME_TYPE"]
        == RuntimeType.openclaw.rawValue,
      "OpenClaw marketplace plugin config must include the runtime type")
    try expect(
      openClawMarketplaceBridgeEnvironment[
        MarketplaceRuntimeBrokerEndpoint.socketPathEnvironmentKey] != nil,
      "OpenClaw marketplace plugin config must include the Relay broker socket path")
    try expect(
      openClawMarketplaceBridgeEnvironment[MarketplaceRuntimeBrokerEndpoint.tokenPathEnvironmentKey]
        != nil, "OpenClaw marketplace plugin config must include the Relay broker token path")
    try expect(
      openClawMarketplaceBridgeEnvironment["RELAY_MARKETPLACE_RUNTIME_CONTEXT_PATH"] != nil,
      "OpenClaw marketplace plugin config must include the per-session dispatch context path")
    try expect(
      openClawMarketplaceBridgeEnvironment["RELAY_MARKETPLACE_DISPATCH_ID"] == nil,
      "OpenClaw marketplace plugin config should not persist per-turn dispatch ids")
    var openClawProbeConfig = openClawMarketplaceConfig
    openClawProbeConfig["bridgeCommand"] = "python3"
    openClawProbeConfig["bridgeArgs"] = [
      "-c",
      "import json, sys; payload=json.load(sys.stdin); print(json.dumps({'ok': True, 'toolName': payload.get('toolName')}))",
    ]
    let openClawProbeConfigData = try JSONSerialization.data(withJSONObject: openClawProbeConfig)
    let openClawProbeConfigJSON = String(data: openClawProbeConfigData, encoding: .utf8) ?? "{}"
    let openClawProbeScript = """
      const pluginPath = process.argv[1];
      const config = JSON.parse(process.argv[2]);
      for (const key of Object.keys(process.env)) {
        if (key === "RELAY_CONSOLE_USER_DATA_PATH" || key.startsWith("RELAY_MARKETPLACE_")) delete process.env[key];
      }
      const plugin = require(pluginPath);
      const calls = [];
      const contextPath = config.bridgeEnvironment.RELAY_MARKETPLACE_RUNTIME_CONTEXT_PATH;
      const contextRoot = JSON.parse(require("node:fs").readFileSync(contextPath, "utf8"));
      const sessionKey = Object.keys(contextRoot.contexts || {})[0];
      plugin.register({
        pluginConfig: config,
        registerTool(definition, options) {
          if (typeof definition === "function") definition = definition({ sessionKey });
          calls.push({ definition, options });
        },
      });
      (async () => {
        const handlerResults = {};
        for (const call of calls) {
          const name = call.definition && call.definition.name;
          if (!name || !name.startsWith("relay_")) continue;
          const result = await call.definition.execute("tool-call-001", { maxResults: 3 });
          handlerResults[name] = result.details;
        }
        console.log(JSON.stringify({
          registered: calls.map((call) => call.definition.name),
          handlerResults,
        }, null, 2));
      })().catch((error) => {
        console.error(error && error.stack ? error.stack : String(error));
        process.exit(1);
      });
      """
    let nodeProbeExecutable = try unwrap(
      ProcessInfo.processInfo.environment["PATH"]?
        .split(separator: ":")
        .map { URL(fileURLWithPath: String($0)).appendingPathComponent("node") }
        .first { FileManager.default.isExecutableFile(atPath: $0.path) },
      "Node executable is required for the generated OpenClaw plugin probe"
    )
    let openClawProbe = try awaitResult {
      await ProcessCommandRunner().run(
        nodeProbeExecutable.path,
        [
          "-e",
          openClawProbeScript,
          openClawPluginDir.appendingPathComponent("index.js").path,
          openClawProbeConfigJSON,
        ],
        options: CommandOptions(
          cwd: openClawPluginDir,
          timeoutMs: 30_000,
          executableAuthorization: .exact(nodeProbeExecutable)
        )
      )
    }
    try expect(
      openClawProbe.code == 0,
      "OpenClaw generated marketplace plugin should register tools from plugin config without Relay env: \(openClawProbe.stderr)"
    )
    guard let openClawProbeData = openClawProbe.stdout.data(using: .utf8),
      let openClawProbeJSON = try JSONSerialization.jsonObject(with: openClawProbeData)
        as? [String: Any],
      let openClawRegistered = openClawProbeJSON["registered"] as? [String],
      let openClawHandlerResults = openClawProbeJSON["handlerResults"] as? [String: [String: Any]]
    else {
      throw ServiceTestFailure(
        "OpenClaw generated marketplace plugin returned invalid probe JSON: \(openClawProbe.stdout)"
      )
    }
    try expect(
      Set(openClawRegistered) == Set(openClawSnapshot.mountedToolNames),
      "OpenClaw generated plugin should register the exact snapshot wrapper tools from config")
    try expect(
      Set(openClawHandlerResults.keys) == Set(openClawSnapshot.mountedToolNames),
      "OpenClaw generated handlers should be callable through the Relay Marketplace bridge")
    for (toolName, result) in openClawHandlerResults {
      try expect(
        result["toolName"] as? String == toolName,
        "OpenClaw generated handler should route \(toolName) through the Relay Marketplace bridge")
    }
    let openClawHarnessInstallAgain = try services.harnessInstall
      .prepareMarketplaceRuntimeToolBridge(
        for: openClawAgent,
        request: runtimeRequest(agent: openClawAgent, suffix: "openclaw-repeat"),
        harnessPath: URL(
          fileURLWithPath: try unwrap(
            openClawHarness.config["installPath"]?.string, "missing OpenClaw harness path")),
        mount: openClawSnapshot
      )
    try expect(
      !openClawHarnessInstallAgain.requiresHarnessRefresh,
      "OpenClaw adapter should not request another refresh when marketplace plugin config is already current"
    )

    let hermesHarnessPath = URL(
      fileURLWithPath: try unwrap(
        hermesHarness.config["installPath"]?.string, "missing Hermes harness path"))
    let hermesHarnessInstall = try services.harnessInstall.prepareMarketplaceRuntimeToolBridge(
      for: hermesAgent,
      request: runtimeRequest(agent: hermesAgent, suffix: "hermes"),
      harnessPath: hermesHarnessPath,
      mount: hermesSnapshot
    )
    try expect(
      hermesHarnessInstall.registeredToolNames == Set(hermesSnapshot.mountedToolNames),
      "Hermes adapter should confirm every policy-scoped wrapper tool as registered")
    let hermesToolsDir = hermesHarnessPath.appendingPathComponent("tools", isDirectory: true)
    try "__all__ = []\n".write(
      to: hermesToolsDir.appendingPathComponent("__init__.py"), atomically: true, encoding: .utf8)
    try """
    class Registry:
        def __init__(self):
            self.calls = []
        def register(self, **kwargs):
            self.calls.append(kwargs)
    registry = Registry()
    """.write(
      to: hermesToolsDir.appendingPathComponent("registry.py"), atomically: true, encoding: .utf8)
    try """
    _HERMES_CORE_TOOLS = ["web_search"]
    TOOLSETS = {
        "hermes-cli": {"description": "CLI", "tools": _HERMES_CORE_TOOLS, "includes": []},
        "web": {"description": "Web", "tools": ["web_search"], "includes": []},
    }
    """.write(
      to: hermesHarnessPath.appendingPathComponent("toolsets.py"), atomically: true, encoding: .utf8
    )
    var hermesProbeEnv = CommandExecutionEnvironment.minimal
    hermesProbeEnv.merge(hermesHarnessInstall.env) { _, new in new }
    hermesProbeEnv["RELAY_MARKETPLACE_TOOL_BRIDGE_COMMAND"] = "python3"
    hermesProbeEnv["RELAY_MARKETPLACE_TOOL_BRIDGE_ARGS_JSON"] = """
      ["-c", "import json, sys; payload=json.load(sys.stdin); print(json.dumps({'ok': True, 'toolName': payload.get('toolName')}))"]
      """
    let hermesProbeScript = """
      import json
      import sys
      sys.path.insert(0, ".")
      import tools.relay_marketplace_tools
      from tools.registry import registry
      import toolsets
      calls = [call for call in registry.calls if str(call.get("name") or "").startswith("relay_") and call.get("name") != "relay_marketplace_unavailable"]
      handler_results = {}
      for call in calls:
          result = call["handler"]({"maxResults": 3}, task_id="hermes-runtime-test-task", tool_call_id="tool-call-001")
          handler_results[call.get("name")] = json.loads(result)
      print(json.dumps({
          "registered": [call.get("name") for call in calls],
          "registered_toolsets": [call.get("toolset") for call in calls],
          "relay_toolset": toolsets.TOOLSETS.get("relay-marketplace", {}).get("tools", []),
          "hermes_cli_tools": toolsets.TOOLSETS.get("hermes-cli", {}).get("tools", []),
          "web_tools": toolsets.TOOLSETS.get("web", {}).get("tools", []),
          "handler_results": handler_results,
      }, sort_keys=True))
      """
    let hermesProbe = try awaitResult {
      await ProcessCommandRunner().run(
        "/usr/bin/python3",
        ["-c", hermesProbeScript],
        options: CommandOptions(
          cwd: hermesHarnessPath,
          env: hermesProbeEnv,
          timeoutMs: 30_000,
          executableAuthorization: .exact(URL(fileURLWithPath: "/usr/bin/python3"))
        )
      )
    }
    try expect(
      hermesProbe.code == 0,
      "Hermes generated marketplace module should import and register tools: \(hermesProbe.stderr)")
    guard let hermesProbeData = hermesProbe.stdout.data(using: .utf8),
      let hermesProbeJSON = try JSONSerialization.jsonObject(with: hermesProbeData)
        as? [String: Any],
      let hermesRegistered = hermesProbeJSON["registered"] as? [String],
      let hermesRegisteredToolsets = hermesProbeJSON["registered_toolsets"] as? [String],
      let hermesRelayToolset = hermesProbeJSON["relay_toolset"] as? [String],
      let hermesCLITools = hermesProbeJSON["hermes_cli_tools"] as? [String],
      let hermesWebTools = hermesProbeJSON["web_tools"] as? [String],
      let hermesHandlerResults = hermesProbeJSON["handler_results"] as? [String: [String: Any]]
    else {
      throw ServiceTestFailure(
        "Hermes generated marketplace module returned invalid probe JSON: \(hermesProbe.stdout)")
    }
    try expect(
      Set(hermesRegistered) == Set(hermesSnapshot.mountedToolNames),
      "Hermes generated module should register the exact snapshot wrapper tools")
    try expect(
      Set(hermesRegisteredToolsets) == Set(["relay-marketplace"]),
      "Hermes generated module should register tools under the Relay Marketplace toolset")
    try expect(
      Set(hermesRelayToolset) == Set(hermesSnapshot.mountedToolNames),
      "Hermes Relay Marketplace toolset should expose the exact wrapper tools")
    try expect(
      Set(hermesSnapshot.mountedToolNames).isSubset(of: Set(hermesCLITools)),
      "Hermes CLI toolset should include marketplace tools for the runtime session")
    try expect(
      Set(hermesSnapshot.mountedToolNames).isSubset(of: Set(hermesWebTools)),
      "Hermes adapter should mount marketplace tools independently of a narrow configured toolset")
    try expect(
      Set(hermesHandlerResults.keys) == Set(hermesSnapshot.mountedToolNames),
      "Hermes generated handlers should be callable with harness metadata kwargs for every mounted wrapper tool"
    )
    for (toolName, result) in hermesHandlerResults {
      try expect(
        result["toolName"] as? String == toolName,
        "Hermes generated handler should route \(toolName) through the Relay Marketplace bridge")
    }

    _ = try services.providerActionPolicies.compilePolicyMap(
      context: owner,
      appIdOrSlug: x.id,
      preset: .allowDirectWrites, acknowledgeDangerousPolicy: true,
      connectionId: xConnection.id,
      installId: hermesXInstall.id,
      agentId: hermesAgent.id,
      now: fixedDate("2026-01-01T00:00:12Z")
    )
    let directHermesSnapshot = try services.marketplaceRuntimeMounts.snapshot(
      context: member,
      agent: hermesAgent,
      now: fixedDate("2026-01-01T00:00:12Z")
    )
    let directHermesPostTool = try unwrap(
      directHermesSnapshot.apps.first { $0.appSlug == "x" }?.tools.first {
        $0.displayName == "Publish text Post"
      },
      "missing direct-write Hermes X post wrapper tool"
    )
    try expect(
      directHermesPostTool.autoExecutes && !directHermesPostTool.requiresApproval,
      "direct-write Hermes post wrapper should auto-execute")
    let directHermesWrite = try services.marketplaceRuntimeToolBridge.execute(
      toolName: directHermesPostTool.toolName,
      payload: ["text": .string("Direct-write Hermes runtime post.")],
      runtime: MarketplaceRuntimeToolExecutionContext(
        agentId: hermesAgent.id,
        workspaceId: workspace.id,
        runtimeType: .hermes,
        dispatchId: "rtd-runtime-bridge-hermes-write-direct-001",
        threadId: "thr-runtime-bridge-hermes-write-direct-001",
        runtimeSessionId: "rts-runtime-bridge-hermes-write-direct-001",
        correlationId: "runtime-bridge-hermes-write-direct-001"
      ),
      now: fixedDate("2026-01-01T00:00:12Z")
    )
    try expect(
      directHermesWrite["ok"] == .bool(true),
      "direct-write Hermes runtime write should return without timing out")
    try expect(
      directHermesWrite["executionStatus"]
        == .string(ProviderActionExecutionStatus.succeeded.rawValue),
      "direct-write Hermes runtime write should execute through the broker")
    try expect(
      directHermesWrite["adapterExecuted"] == .bool(true),
      "direct-write Hermes runtime write should execute the adapter")
    try expect(
      objectValue(directHermesWrite["providerResult"])?["postId"] != nil,
      "direct-write Hermes runtime write should return provider post evidence")

    _ = try services.providerActionPolicies.compilePolicyMap(
      context: owner,
      appIdOrSlug: x.id,
      preset: .blocked,
      connectionId: xConnection.id,
      installId: hermesXInstall.id,
      agentId: hermesAgent.id,
      now: fixedDate("2026-01-01T00:00:12Z")
    )
    let refreshedHermesSnapshot = try services.marketplaceRuntimeMounts.snapshot(
      context: member,
      agent: hermesAgent,
      now: fixedDate("2026-01-01T00:00:13Z")
    )
    try expect(
      refreshedHermesSnapshot.fingerprint != hermesSnapshot.fingerprint,
      "policy changes should refresh the next runtime mount fingerprint")
    let blockedX = try unwrap(
      refreshedHermesSnapshot.apps.first { $0.appSlug == "x" },
      "missing blocked X runtime mount app")
    try expect(
      blockedX.policyPreset == .blocked,
      "refreshed runtime mount should reflect the blocked X policy")
    try expect(
      blockedX.tools.isEmpty, "blocked policy should remove X wrapper tools from the agent snapshot"
    )
    try expect(
      refreshedHermesSnapshot.toolCount == hermesSnapshot.toolCount - 4,
      "blocked X policy should leave only Exa, Gmail, LinkedIn, and Notion wrapper tools mounted")
  }

  private static func testExaSearchInstallsRuntimeSkillsAndProfileEnvironments() throws {
    let root = FileManager.default.temporaryDirectory
      .appendingPathComponent("RelayConsoleExaSearchInstallTests", isDirectory: true)
      .appendingPathComponent(UUID().uuidString, isDirectory: true)
    let apiKey = "exa_test_service_secret_123456789"
    let workspaceId: String
    let appId: String

    do {
      let services = try makeServices(root: root)
      let workspace = try unwrap(services.data.getAppState().activeWorkspace, "missing workspace")
      workspaceId = workspace.id
      let owner = Self.context(
        roles: [.owner], workspaceId: workspace.id, correlationId: "exa-search-owner-001")
      let member = Self.context(
        roles: [.member], workspaceId: workspace.id, correlationId: "exa-search-member-001")
      let hermesHarness = try prepareInstalledHarness(services: services, key: .hermes)
      let openClawHarness = try prepareInstalledHarness(services: services, key: .openclaw)
      let hermesHome = root.appendingPathComponent("hermes-profile", isDirectory: true)
      let openClawStateDir = root.appendingPathComponent("openclaw-home", isDirectory: true)
      let openClawAgentDir = openClawStateDir.appendingPathComponent(
        "agents/openclaw-exa-candidate/agent", isDirectory: true)
      let openClawWorkspaceDir = openClawStateDir.appendingPathComponent(
        "workspace-openclaw-exa-candidate", isDirectory: true)
      let hermesAgent = try services.data.createAgent(
        workspaceId: workspace.id,
        name: "Hermes Exa Researcher",
        harnessId: hermesHarness.id,
        externalAgentId: "hermes-exa-researcher",
        hermesProfileSlug: "hermes-exa-researcher",
        hermesHomePath: hermesHome.path,
        hermesIdentityFilePath: hermesHome.appendingPathComponent("identity.json").path
      )
      let openClawAgent = try services.data.createAgent(
        workspaceId: workspace.id,
        name: "OpenClaw Exa Candidate",
        harnessId: openClawHarness.id,
        externalAgentId: "openclaw-exa-candidate",
        workspaceFolderPath: openClawWorkspaceDir.path,
        config: [
          "openclawAgentDir": .string(openClawAgentDir.path),
          "openclawStateDir": .string(openClawStateDir.path),
        ]
      )

      let catalog = try services.applications.catalogSnapshot(
        context: owner, selectedAppId: "exa-search", now: fixedDate("2026-01-01T00:00:00Z"))
      let app = try unwrap(
        catalog.apps.first { $0.slug == "exa-search" }, "missing Exa Search catalog app")
      appId = app.id
      try expect(
        app.runtimeSupport == [.hermes, .openclaw], "Exa Search should support Hermes and OpenClaw")
      let emptyInstallSnapshot = try services.marketplaceInstalls.snapshot(
        context: member, appIdOrSlug: app.id, now: fixedDate("2026-01-01T00:00:01Z"))
      try expect(
        emptyInstallSnapshot.compatibleAgents.contains {
          $0.agentId == hermesAgent.id && $0.status == .compatible
        }, "Hermes agent should be compatible with Exa Search")
      try expect(
        emptyInstallSnapshot.compatibleAgents.contains {
          $0.agentId == openClawAgent.id && $0.status == .compatible
        }, "OpenClaw agent should be compatible with Exa Search")

      let connection = try services.providerConnections.saveExaAPIKeyConnection(
        context: owner,
        appIdOrSlug: app.id,
        apiKey: apiKey,
        validationResult: ExaAPIKeyValidationResult(
          status: .ready, message: "Exa API key verified.", httpStatusCode: 200),
        now: fixedDate("2026-01-01T00:00:02Z")
      )
      try expect(
        connection.secretReferenceIds.count == 1,
        "Exa connection should reference one Keychain secret")
      try expect(
        try services.secrets.getSecretValue(connection.secretReferenceIds[0]) == apiKey,
        "Exa key should be retrievable only through SecretService")

      let install = try services.marketplaceInstalls.createInstall(
        context: owner,
        request: installRequest(
          id: "minreq-exa-search-install-001",
          workspaceId: workspace.id,
          app: app,
          connectionId: connection.id,
          agent: hermesAgent,
          roleId: app.roleManifest.primaryRole,
          selectedCapabilities: app.capabilities,
          riskAcknowledged: false
        ),
        now: fixedDate("2026-01-01T00:00:03Z")
      )
      try expect(install.installStatus == .installed, "Exa install should be marked installed")
      try expect(
        install.metadata["runtimeWritePerformed"] == .bool(true),
        "Exa install should perform runtime writes")
      try expect(
        install.metadata["runtimeWriteDeferred"] == .bool(false),
        "Exa install should not defer runtime writes")
      try expect(
        install.metadata["providerActionFrameworkHydrated"] == .bool(true),
        "Exa install should hydrate provider-action framework metadata")
      try expect(
        install.metadata["providerActionPolicyPreset"]
          == .string(MarketplaceActionPolicyPreset.readOnly.rawValue),
        "Exa install should use read-only provider policy for researcher role")
      try expect(
        install.metadata["providerActionDefinitionCount"] == .number(4),
        "Exa install should hydrate four provider action definitions")
      try expect(
        install.metadata["runtimeInstaller"] == .string("exa-search-hermes-profile-wrapper"),
        "Hermes Exa install should use the brokered Hermes installer")
      try expect(
        install.metadata["credentialEnvWrite"] == .bool(false),
        "Hermes Exa install should not write credentials into agent env")
      let skillURL = hermesHome.appendingPathComponent("skills/research/exa-search/SKILL.md")
      let envURL = hermesHome.appendingPathComponent(".env")
      let skill = try String(contentsOf: skillURL, encoding: .utf8)
      let env =
        FileManager.default.fileExists(atPath: envURL.path)
        ? try String(contentsOf: envURL, encoding: .utf8)
        : ""
      try expect(skill.contains("name: exa-search"), "Exa skill frontmatter should be written")
      try expect(
        skill.contains("Relay provider wrapper tools"),
        "Exa skill should describe brokered provider wrapper tools")
      try expect(
        !skill.contains("EXA_API_KEY"),
        "Exa skill should not tell agents to load raw credential environment variables")
      try expect(!skill.contains(apiKey), "Exa API key should not be written into SKILL.md")
      try expect(
        !env.contains(apiKey), "Exa API key should not be written into the Hermes profile .env")
      try expect(
        !env.contains("EXA_API_KEY="),
        "Hermes Exa install should not leave Exa env keys in agent env")
      let metadataJSON = encodeJSONString(install.metadata) ?? ""
      try expect(!metadataJSON.contains(apiKey), "Exa install metadata should not leak the API key")
      let exaWrapperSurface = try services.providerWrapperTools.compileSurface(
        context: member,
        appIdOrSlug: app.id,
        installId: install.id,
        agentId: hermesAgent.id,
        now: fixedDate("2026-01-01T00:00:03Z")
      )
      try expect(
        exaWrapperSurface.tools.count == 3,
        "Exa install should be wrapper-ready after migration hydration")
      try expect(
        exaWrapperSurface.tools.contains { $0.displayName == "Deep search" && $0.requiresApproval },
        "Exa migration should keep deep search approval-gated")

      let openClawInstall = try services.marketplaceInstalls.createInstall(
        context: owner,
        request: installRequest(
          id: "minreq-exa-search-install-002",
          workspaceId: workspace.id,
          app: app,
          connectionId: connection.id,
          agent: openClawAgent,
          roleId: app.roleManifest.primaryRole,
          selectedCapabilities: app.capabilities,
          riskAcknowledged: false
        ),
        now: fixedDate("2026-01-01T00:00:04Z")
      )
      try expect(
        openClawInstall.installStatus == .installed,
        "OpenClaw Exa install should be marked installed")
      try expect(
        openClawInstall.metadata["runtimeWritePerformed"] == .bool(true),
        "OpenClaw Exa install should perform runtime writes")
      try expect(
        openClawInstall.metadata["runtimeInstaller"]
          == .string("exa-search-openclaw-agent-wrapper"),
        "OpenClaw Exa install should use the brokered OpenClaw installer")
      try expect(
        openClawInstall.metadata["credentialEnvWrite"] == .bool(false),
        "OpenClaw Exa install should not write credentials into agent env")
      try expect(
        openClawInstall.metadata["providerActionFrameworkHydrated"] == .bool(true),
        "OpenClaw Exa install should hydrate provider-action framework metadata")
      let openClawWorkspaceSkillURL = openClawWorkspaceDir.appendingPathComponent(
        "skills/exa-search/SKILL.md")
      let openClawAgentSkillURL = openClawAgentDir.appendingPathComponent(
        "skills/exa-search/SKILL.md")
      let openClawAgentEnvURL = openClawAgentDir.appendingPathComponent(".env")
      let openClawSharedEnvURL = openClawStateDir.appendingPathComponent(".env")
      let openClawSkill = try String(contentsOf: openClawWorkspaceSkillURL, encoding: .utf8)
      let openClawAgentSkill = try String(contentsOf: openClawAgentSkillURL, encoding: .utf8)
      let openClawAgentEnv =
        FileManager.default.fileExists(atPath: openClawAgentEnvURL.path)
        ? try String(contentsOf: openClawAgentEnvURL, encoding: .utf8)
        : ""
      let openClawSharedEnv =
        FileManager.default.fileExists(atPath: openClawSharedEnvURL.path)
        ? try String(contentsOf: openClawSharedEnvURL, encoding: .utf8)
        : ""
      try expect(
        openClawSkill.contains("name: exa-search"),
        "OpenClaw Exa workspace skill frontmatter should be written")
      try expect(
        openClawSkill.contains("Relay provider wrapper tools"),
        "OpenClaw Exa workspace skill should describe brokered provider wrapper tools")
      try expect(
        !openClawSkill.contains("EXA_API_KEY"),
        "OpenClaw Exa workspace skill should not tell agents to load raw credential environment variables"
      )
      try expect(
        openClawAgentSkill.contains("name: exa-search"),
        "OpenClaw Exa agent-state skill frontmatter should be written")
      try expect(
        !openClawSkill.contains(apiKey), "OpenClaw Exa API key should not be written into SKILL.md")
      try expect(
        !openClawAgentEnv.contains(apiKey),
        "Exa API key should not be written into the OpenClaw agent .env")
      try expect(
        !openClawSharedEnv.contains(apiKey),
        "Exa API key should not be written into the OpenClaw shared .env")
      try expect(
        !openClawAgentEnv.contains("EXA_API_KEY="),
        "OpenClaw Exa install should not leave Exa agent env keys")
      try expect(
        !openClawSharedEnv.contains("EXA_API_KEY="),
        "OpenClaw Exa install should not leave Exa shared env keys")
      let openClawMetadataJSON = encodeJSONString(openClawInstall.metadata) ?? ""
      try expect(
        !openClawMetadataJSON.contains(apiKey),
        "OpenClaw Exa install metadata should not leak the API key")
      try expect(
        !openClawMetadataJSON.contains(openClawWorkspaceSkillURL.path),
        "OpenClaw Exa install metadata should not leak the workspace skill path")

      try FileManager.default.removeItem(at: openClawWorkspaceSkillURL)
      let repairedAgent = try services.marketplaceInstalls.repairRuntimeSkillFiles(
        context: owner, installId: openClawInstall.id)
      try expect(
        repairedAgent?.id == openClawAgent.id,
        "OpenClaw Exa repair should report the repaired agent")
      let repairedOpenClawSkill = try String(contentsOf: openClawWorkspaceSkillURL, encoding: .utf8)
      try expect(
        repairedOpenClawSkill.contains("name: exa-search"),
        "OpenClaw Exa repair should restore the workspace skill file")
      let noOpRepair = try services.marketplaceInstalls.repairRuntimeSkillFiles(
        context: owner, installId: openClawInstall.id)
      try expect(
        noOpRepair == nil, "OpenClaw Exa repair should be idempotent once skill files are current")

      let populatedSnapshot = try services.marketplaceInstalls.snapshot(
        context: member, appIdOrSlug: app.id, now: fixedDate("2026-01-01T00:00:05Z"))
      try expect(
        populatedSnapshot.diagnostics.runtimeWriteSummary
          == "Runtime writes performed for supported Marketplace apps.",
        "Exa install snapshot should report performed runtime writes")
      let syncedApp = try unwrap(
        try services.data.getMarketplaceCatalogApp(workspaceId: workspace.id, appIdOrSlug: app.id),
        "missing synced Exa app")
      try expect(syncedApp.installState == .installed, "Exa catalog state should show installed")
      try expect(
        Set(syncedApp.installedAgentIds) == Set([hermesAgent.id, openClawAgent.id]),
        "Exa catalog should record installed Hermes and OpenClaw agents")
    }

    let reopened = try makeServices(root: root)
    let reopenedContext = Self.context(
      roles: [.owner], workspaceId: workspaceId, correlationId: "exa-search-reopen-001")
    let reopenedSnapshot = try reopened.marketplaceInstalls.snapshot(
      context: reopenedContext,
      appIdOrSlug: appId,
      now: fixedDate("2026-01-01T00:00:06Z")
    )
    try expect(reopenedSnapshot.installs.count == 2, "Exa installs should survive relaunch")
    try expect(
      reopenedSnapshot.installs.allSatisfy { $0.metadata["runtimeWritePerformed"] == .bool(true) },
      "Exa runtime write metadata should survive relaunch")
  }

  private static func testNeededToolsRequestsDedupeSummarizeAndDoNotAutoGrant() throws {
    let root = FileManager.default.temporaryDirectory
      .appendingPathComponent("RelayConsoleNeededToolsTests", isDirectory: true)
      .appendingPathComponent(UUID().uuidString, isDirectory: true)
    let workspaceId: String
    let appId: String
    let requestId: String
    let sensitivePath = "/private/tmp/tool-request-sensitive-value"

    do {
      let services = try makeServices(root: root)
      let workspace = try unwrap(services.data.getAppState().activeWorkspace, "missing workspace")
      workspaceId = workspace.id
      let owner = Self.context(
        roles: [.owner], workspaceId: workspace.id, correlationId: "needed-tools-owner-001")
      let admin = Self.context(
        roles: [.admin], workspaceId: workspace.id, correlationId: "needed-tools-admin-001")
      let member = Self.context(
        roles: [.member], workspaceId: workspace.id, correlationId: "needed-tools-member-001")
      let viewer = Self.context(
        roles: [.viewer], workspaceId: workspace.id, correlationId: "needed-tools-viewer-001")
      let operatorContext = Self.context(
        roles: [.operator], workspaceId: workspace.id, correlationId: "needed-tools-operator-001")
      let events = EventCounter()
      _ = services.eventBus.on(.applicationsNeededToolsUpdated) { _ in events.increment() }

      let harness = try prepareInstalledHarness(services: services, key: .hermes)
      let agent = try services.data.createAgent(
        workspaceId: workspace.id,
        name: "Needed Tools Operator",
        harnessId: harness.id,
        externalAgentId: "needed-tools-operator"
      )
      var outlook = marketplaceApp(
        workspaceId: workspace.id,
        slug: "outlook",
        name: "Outlook",
        summary: "Mail provider.",
        category: "Productivity",
        riskLevel: .high,
        connectionState: .none,
        installState: .notInstalled
      )
      outlook.capabilities = ["email_send", "email_draft"]
      var search = marketplaceApp(
        workspaceId: workspace.id,
        slug: "exa-search",
        name: "Exa Search",
        summary: "External search provider.",
        category: "Research",
        riskLevel: .low,
        connectionState: .none,
        installState: .notInstalled
      )
      search.capabilities = ["external_search"]
      let paperclip = marketplaceApp(
        workspaceId: workspace.id,
        slug: "paperclip-local",
        name: "Paperclip Local",
        summary: "Excluded Paperclip provider.",
        category: "Local",
        sourceType: .localAppExcluded,
        riskLevel: .medium,
        availability: .unavailable,
        availabilityReason: "Paperclip is excluded",
        connectionState: .unavailable,
        installState: .unavailable,
        localAppExcluded: true,
        reviewExcluded: true
      )
      _ = try services.applications.saveCatalogApps(
        context: owner, apps: [outlook, search, paperclip])
      appId = outlook.id

      let secret = try services.secrets.set(
        scope: "provider_connection", scopeId: outlook.id, label: "Outlook Client Secret",
        secretValue: "token=tool-request-sensitive-value")
      let savedConnection = try services.providerConnections.saveConnection(
        context: admin,
        connection: providerConnection(
          workspaceId: workspace.id,
          app: outlook,
          status: .connected,
          authorizationState: .completed,
          secretReferenceId: secret.id,
          accountLabel: "Needed Tools account",
          connectedHandle: "needed-tools-handle",
          lastError: nil
        )
      )

      let missingTool = try services.runtimeRecovery.recordMissingTool(
        context: operatorContext,
        toolName: "email.send",
        status: .requested,
        agentId: agent.id,
        request: [
          "path": .string(sensitivePath),
          "credential": .string("token=tool-request-sensitive-value"),
        ],
        now: fixedDate("2026-01-01T00:00:00Z")
      )

      let operatorDeny = try services.permissions.createPolicy(
        context: owner,
        request: PermissionPolicyRequest(
          name: "Block operator Needed Tools report",
          effect: .deny,
          roleTargets: [ServiceRole.operator.rawValue],
          resourceType: "tool_request",
          resourceId: outlook.id,
          action: "report",
          priority: 50,
          reasonCode: .policyBlocked,
          message: "Operator reports for this retained capability are temporarily blocked.",
          metadata: ["source": .string("needed-tools-policy-test")]
        ),
        now: fixedDate("2026-01-01T00:00:00Z")
      )
      do {
        _ = try services.toolRequests.reportMissingTool(
          context: operatorContext,
          requestedCapability: "mail.send",
          appIdOrSlug: outlook.id,
          agentId: agent.id,
          missingToolEventId: missingTool.id,
          relatedRecordId: "needed-tools-policy-denied-001",
          reason: "Policy denies this operator report.",
          requiredAction: "Do not persist policy-denied requests.",
          now: fixedDate("2026-01-01T00:00:00Z")
        )
        throw ServiceTestFailure("policy-denied Needed Tools report unexpectedly persisted")
      } catch let denied as ServiceGuardResult {
        try expect(
          denied.reasonCode == .policyBlocked,
          "policy-denied Needed Tools report should use policy reason")
      }
      try expect(
        try services.data.listToolRequests(workspaceId: workspace.id).isEmpty,
        "permission-denied request mutated persistence")
      _ = try services.permissions.deletePolicy(context: owner, policyId: operatorDeny.id)

      let deniedPersist = try services.toolRequests.reportMissingTool(
        context: operatorContext,
        requestedCapability: "email.send",
        appIdOrSlug: outlook.id,
        agentId: agent.id,
        missingToolEventId: missingTool.id,
        relatedRecordId: "needed-tools-email-001",
        reason: "Policy blocked this missing tool report.",
        requiredAction: "Do not persist policy-denied requests.",
        policyAllowed: false,
        now: fixedDate("2026-01-01T00:00:01Z")
      )
      try expect(deniedPersist == nil, "policy-denied Needed Tools request should not persist")
      try expect(
        try services.data.listToolRequests(workspaceId: workspace.id).isEmpty,
        "policy-denied request mutated persistence")

      do {
        _ = try services.toolRequests.snapshot(context: viewer, appIdOrSlug: outlook.id)
        throw ServiceTestFailure("viewer unexpectedly read Needed Tools")
      } catch let denied as ServiceGuardResult {
        try expect(
          denied.reasonCode == .authorityRoleRequired,
          "viewer Needed Tools read should require workspace access")
      }

      let firstRequest = try unwrap(
        try services.toolRequests.reportMissingTool(
          context: operatorContext,
          requestedCapability: "email.send",
          appIdOrSlug: outlook.id,
          agentId: agent.id,
          missingToolEventId: missingTool.id,
          relatedTaskId: "tsk-needed-tools-001",
          relatedRecordId: "needed-tools-email-001",
          campaign: "Launch mail campaign",
          reason: "Policy allows send mail but the runtime reported no executable tool.",
          requiredAction: "Connect and grant Outlook email_send for the retained agent.",
          evidence: "Runtime evidence at \(sensitivePath) token=tool-request-sensitive-value",
          metadata: ["localPath": .string(sensitivePath), "autoGrantCreated": .bool(false)],
          now: fixedDate("2026-01-01T00:00:02Z")
        ), "missing persisted Needed Tools request")
      requestId = firstRequest.id
      try expect(
        firstRequest.status == .connected,
        "connected provider should derive connected Needed Tools status before install")
      try expect(
        firstRequest.normalizedCapability == "email_send",
        "email.send should normalize to email_send")
      try expect(
        firstRequest.toolConnected && !firstRequest.toolGranted,
        "request should be connected but not granted before install")
      try expect(
        firstRequest.metadata["autoInstallAttempted"] == .bool(false),
        "Needed Tools must not auto-install apps")
      try expect(
        firstRequest.metadata["autoGrantCreated"] == .bool(false),
        "Needed Tools must not create fake grants")
      try expect(
        firstRequest.metadata["localFileAccessAttempted"] == .bool(false),
        "Needed Tools must not access local files")
      try expect(
        firstRequest.metadata["scheduledContinuationStatus"] == .string("waiting_on_capability"),
        "scheduled continuation status should be durable")
      try expect(
        firstRequest.metadata["continuationWaitsOnCapability"] == .string("email_send"),
        "continuation should name normalized capability")
      try expect(
        ToolRequestService.continuationTitle(for: firstRequest).contains("email_send"),
        "Continuation UI helper should expose scheduled note")

      let duplicate = try unwrap(
        try services.toolRequests.reportMissingTool(
          context: operatorContext,
          requestedCapability: "outlook.send",
          appIdOrSlug: outlook.id,
          agentId: agent.id,
          missingToolEventId: missingTool.id,
          relatedTaskId: "tsk-needed-tools-001",
          relatedRecordId: "needed-tools-email-001",
          campaign: "Launch mail campaign",
          reason: "Repeated runtime report for the same missing capability.",
          requiredAction: "Keep one open request for the retained record.",
          evidence: "Duplicate evidence at \(sensitivePath)",
          now: fixedDate("2026-01-01T00:00:03Z")
        ), "missing duplicate Needed Tools request")
      try expect(
        duplicate.id == firstRequest.id,
        "open Needed Tools request should dedupe by capability/app/agent/record")
      try expect(
        try services.data.listToolRequests(workspaceId: workspace.id).count == 1,
        "duplicate request should not create another row")

      _ = try services.marketplaceInstalls.createInstall(
        context: owner,
        request: installRequest(
          workspaceId: workspace.id,
          app: outlook,
          connectionId: savedConnection.id,
          agent: agent,
          roleId: "operator",
          selectedCapabilities: ["email_send"],
          riskAcknowledged: true
        ),
        now: fixedDate("2026-01-01T00:00:04Z")
      )
      let grantedSnapshot = try services.toolRequests.snapshot(
        context: member,
        appIdOrSlug: outlook.id,
        now: fixedDate("2026-01-01T00:00:05Z")
      )
      try expect(
        grantedSnapshot.state == .readOnly, "member Needed Tools snapshot should be read-only")
      try expect(
        grantedSnapshot.summary.openRequestCount == 1,
        "granted open request should remain visible until resolved")
      try expect(
        grantedSnapshot.summary.grantedCount == 1,
        "install grant should update Needed Tools granted count")
      try expect(
        grantedSnapshot.selectedRequest?.status == .granted,
        "snapshot should refresh connected request to granted from real install")
      try expect(
        grantedSnapshot.selectedRequest?.metadata["scheduledContinuationStatus"]
          == .string("waiting_on_capability"), "snapshot should preserve continuation annotation")

      do {
        _ = try services.toolRequests.updateStatus(
          context: member,
          requestId: firstRequest.id,
          status: .resolved,
          resolutionNote: "Member cannot resolve"
        )
        throw ServiceTestFailure("member unexpectedly updated Needed Tools status")
      } catch let denied as ServiceGuardResult {
        try expect(
          denied.reasonCode == .authorityRoleRequired,
          "member Needed Tools mutation should be denied")
      }

      let searchRequest = try unwrap(
        try services.toolRequests.reportMissingTool(
          context: operatorContext,
          requestedCapability: "web.search",
          appIdOrSlug: search.id,
          agentId: agent.id,
          relatedRecordId: "needed-tools-search-001",
          reason: "Policy allows research but external search is not connected.",
          requiredAction: "Connect a retained search provider.",
          evidence: "No connected search tool.",
          now: fixedDate("2026-01-01T00:00:06Z")
        ), "missing search Needed Tools request")
      try expect(
        searchRequest.status == .requested, "unconnected suggested app should remain requested")
      try expect(
        searchRequest.availabilityState == .notConnected,
        "available unconnected provider should derive not_connected")

      let unavailable = try services.toolRequests.updateStatus(
        context: admin,
        requestId: searchRequest.id,
        status: .unavailable,
        resolutionNote: "No approved search provider for this campaign.",
        now: fixedDate("2026-01-01T00:00:07Z")
      )
      try expect(unavailable.status == .unavailable, "admin should mark request unavailable")
      try expect(
        unavailable.availabilityState == .unavailable,
        "unavailable status should update availability")
      let dismissed = try services.toolRequests.updateStatus(
        context: admin,
        requestId: searchRequest.id,
        status: .dismissed,
        resolutionNote: "Dismissed after triage.",
        now: fixedDate("2026-01-01T00:00:08Z")
      )
      try expect(
        dismissed.status == .dismissed && dismissed.resolvedAt != nil,
        "dismiss should close request with timestamp")
      let resolved = try services.toolRequests.updateStatus(
        context: owner,
        requestId: firstRequest.id,
        status: .resolved,
        resolutionNote: "Grant verified from real install.",
        now: fixedDate("2026-01-01T00:00:09Z")
      )
      try expect(
        resolved.status == .resolved && resolved.resolvedAt != nil,
        "owner should resolve granted request")

      do {
        _ = try services.toolRequests.reportMissingTool(
          context: operatorContext,
          requestedCapability: "paperclip.link",
          appIdOrSlug: paperclip.slug,
          agentId: agent.id,
          relatedRecordId: "needed-tools-paperclip-001",
          reason: "Excluded Paperclip link request.",
          requiredAction: "Remain excluded.",
          now: fixedDate("2026-01-01T00:00:10Z")
        )
        throw ServiceTestFailure("Paperclip Needed Tools request unexpectedly persisted")
      } catch let denied as ServiceGuardResult {
        try expect(
          denied.reasonCode == .inputInvalid, "Paperclip Needed Tools state should remain excluded")
      }

      let allSnapshot = try services.toolRequests.snapshot(
        context: owner,
        queryStatus: "all",
        now: fixedDate("2026-01-01T00:00:11Z")
      )
      try expect(
        allSnapshot.summary.resolvedCount >= 1, "all query should summarize resolved requests")
      try expect(
        allSnapshot.summary.dismissedCount >= 1, "all query should summarize dismissed requests")
      try expect(
        try services.runtimeActions.listRuns(context: owner).isEmpty,
        "Needed Tools flow should not execute runtime actions")
      let reportedAudit = try services.auditSecurity.list(
        context: admin,
        query: AuditLogQuery(limit: 20, eventType: "tool_request.reported")
      )
      try expect(
        reportedAudit.records.contains { $0.resourceId == firstRequest.id },
        "reported tool request should be audited")
      let updatedAudit = try services.auditSecurity.list(
        context: admin,
        query: AuditLogQuery(limit: 20, eventType: "tool_request.status_changed")
      )
      try expect(
        updatedAudit.records.contains {
          $0.context["nextStatus"] == .string(ToolRequestStatus.resolved.rawValue)
        }, "status transition should be audited")
      let policyDeniedAudit = try services.auditSecurity.list(
        context: admin,
        query: AuditLogQuery(limit: 20, eventType: "permission.denied")
      )
      try expect(
        policyDeniedAudit.records.contains { $0.resourceType == "tool_request" },
        "permission-denied tool request should mirror into audit log")
      let noPersistAudit = try services.auditSecurity.list(
        context: admin,
        query: AuditLogQuery(limit: 20, eventType: "tool_request.policy_denied")
      )
      try expect(
        noPersistAudit.records.contains {
          $0.context["normalizedCapability"] == .string("email_send")
        }, "policyAllowed=false no-persist request should be audited")
      let securitySummary = try services.auditSecurity.securitySummary(
        context: admin, query: AuditLogQuery(limit: 100))
      try expect(
        securitySummary.toolRequestTransitionCount >= 3,
        "security metrics should count tool request transitions")

      let sqliteDump = try services.database.all(
        """
        SELECT request_json AS value FROM applications_tool_requests
        UNION ALL
        SELECT metadata_json AS value FROM applications_tool_requests
        UNION ALL
        SELECT snapshot_json AS value FROM applications_needed_tools_snapshots
        UNION ALL
        SELECT missing_tool_json AS value FROM runtime_missing_tool_events
        """
      ).compactMap { sqliteText($0["value"]) }.joined(separator: "\n")
      try expect(!sqliteDump.contains(sensitivePath), "Needed Tools storage leaked private path")
      try expect(
        !sqliteDump.contains("tool-request-sensitive-value"),
        "Needed Tools storage leaked sensitive token")
      try expect(
        sqliteDump.contains("[REDACTED]"), "Needed Tools records should persist redacted evidence")
      try expect(
        events.value >= 5, "Needed Tools events should publish for report/update/snapshot changes")
    }

    let reopened = try makeServices(root: root)
    let reopenedContext = Self.context(
      roles: [.owner], workspaceId: workspaceId, correlationId: "needed-tools-reopen-001")
    let reopenedSnapshot = try reopened.toolRequests.snapshot(
      context: reopenedContext,
      appIdOrSlug: appId,
      queryStatus: "all",
      now: fixedDate("2026-01-01T00:00:12Z")
    )
    try expect(
      reopenedSnapshot.requests.contains { $0.id == requestId },
      "Needed Tools requests should survive relaunch")
    try expect(
      reopenedSnapshot.requests.first { $0.id == requestId }?.metadata[
        "scheduledContinuationStatus"] == .string("waiting_on_capability"),
      "continuation annotation should survive relaunch")
    try expect(
      try reopened.toolRequests.latestSnapshot(context: reopenedContext, appId: appId) != nil,
      "latest Needed Tools snapshot should be durable")
  }

  private static func testInsightsReportsDeriveFromLocalRecordsWithoutFabricatedRows() throws {
    let root = FileManager.default.temporaryDirectory
      .appendingPathComponent("RelayConsoleInsightsTests", isDirectory: true)
      .appendingPathComponent(UUID().uuidString, isDirectory: true)
    let workspaceId: String
    var completedReportId = ""
    var failedReportId = ""
    var archivedSnapshotId = ""
    var threadId = ""

    do {
      let services = try makeServices(root: root)
      let workspace = try unwrap(services.data.getAppState().activeWorkspace, "missing workspace")
      workspaceId = workspace.id
      let owner = Self.context(
        roles: [.owner], workspaceId: workspace.id, correlationId: "insights-owner-001")
      let viewer = Self.context(
        roles: [.viewer], workspaceId: workspace.id, correlationId: "insights-viewer-001")
      let events = EventCounter()
      let reportSubscription = services.eventBus.on(.insightsReportsUpdated) { _ in
        events.increment()
      }
      defer {
        services.eventBus.off(.insightsReportsUpdated, id: reportSubscription)
      }

      let empty = try services.insights.reportList(
        context: owner, now: fixedDate("2026-01-01T00:00:00Z"))
      try expect(empty.state == .empty, "empty Insights report list should not invent rows")
      try expect(empty.rows.isEmpty, "empty Insights report list should have no rows")
      try expect(
        empty.emptyReason == "Wrap up a chat to populate the reports centre.",
        "empty Insights copy should match screen contract")

      do {
        _ = try services.insights.saveSnapshot(
          context: viewer,
          title: "Viewer snapshot",
          summary: "Viewer writes should be blocked.",
          snapshotType: "blocked",
          payload: [:]
        )
        throw ServiceTestFailure("viewer Insights snapshot write unexpectedly succeeded")
      } catch let denied as ServiceGuardResult {
        try expect(
          denied.reasonCode == .authorityRoleRequired,
          "viewer Insights write should require member access")
      }

      let agent = try createServiceAgent(services: services, workspaceId: workspace.id)
      let thread = try services.data.createThread(
        workspaceId: workspace.id,
        title: "Insights Source Thread",
        selectedAgentId: agent.id,
        threadType: .direct
      )
      threadId = thread.id
      _ = try services.data.createMessage(
        threadId: thread.id,
        senderType: .user,
        senderName: "You",
        content: "Please summarize the retained cycle."
      )
      _ = try services.data.createMessage(
        threadId: thread.id,
        senderType: .agent,
        senderId: agent.id,
        senderName: agent.name,
        content: "Retained answer for analytics only."
      )

      let completed = try services.data.createThreadWrapUpReport(
        threadId: thread.id,
        sessionId: thread.activeSessionId,
        status: .completed,
        markdown: "# Cycle 1\n\nRetained report markdown.",
        summary: "Retained report summary.",
        metadata: [
          "source": .string("thread_wrap_up_reports"),
          "cycle": .number(1),
          "rawToken": .string("token=insights-sensitive-value"),
          "agentRepeatAnalysis": .object([
            "status": .string("completed"),
            "repeatedAgentMessageCount": .number(1),
            "repeatedCrossAgentMessageCount": .number(1),
            "agentRepeatGroupCount": .number(1),
          ]),
        ],
        messageCount: 2,
        provider: "Hermes",
        model: "local-retained"
      )
      completedReportId = completed.id
      let failed = try services.data.createThreadWrapUpReport(
        threadId: thread.id,
        sessionId: thread.activeSessionId,
        status: .failed,
        title: "Cycle 1 failed report",
        summary: "Retained failed report summary.",
        metadata: ["source": .string("thread_wrap_up_reports")],
        messageCount: 2,
        provider: "Hermes",
        model: "local-retained",
        error: ["code": .string("structured_job_unavailable")]
      )
      failedReportId = failed.id
      let snapshot = try services.insights.saveSnapshot(
        context: owner,
        title: "Weekly report snapshot",
        summary: "Retained local report snapshot.",
        snapshotType: "weekly",
        periodLabel: "Week 1",
        rangeStart: "2026-01-01T00:00:00Z",
        rangeEnd: "2026-01-07T23:59:59Z",
        payload: [
          "threads": .number(1),
          "reports": .number(2),
          "source": .string("insights_report_snapshots"),
        ],
        now: fixedDate("2026-01-01T00:00:01Z")
      )

      let all = try services.insights.reportList(
        context: owner,
        sourceFilter: .all,
        sort: .title,
        selectedReportId: completed.id,
        now: fixedDate("2026-01-01T00:00:02Z")
      )
      try expect(all.state == .ready, "Insights report list should become ready with retained rows")
      try expect(
        all.rows.count == 3, "Insights report list should derive exactly the retained report rows")
      try expect(
        Set(all.rows.map(\.sourceType)) == [.chatReport, .snapshot],
        "Insights rows should identify chat reports and snapshots")
      try expect(
        all.rows.contains {
          $0.id == completed.id && $0.title == "Cycle 1 transcript" && $0.badge == "Chat reports"
        }, "completed wrap-up row should use cycle title and chat report badge")
      try expect(
        all.rows.contains { $0.id == failed.id && $0.statusLabel == "Report failed" },
        "failed wrap-up row should preserve failed status")
      try expect(
        all.rows.contains { $0.id == snapshot.id && $0.badge == "Snapshots" },
        "snapshot row should use snapshot badge")
      try expect(
        all.selectedReportId == completed.id,
        "selected Insights report should resolve to retained id")

      let snapshotsOnly = try services.insights.reportList(context: owner, sourceFilter: .snapshots)
      try expect(
        snapshotsOnly.rows.map(\.id) == [snapshot.id],
        "snapshot filter should show retained snapshots only")
      let chatReportsOnly = try services.insights.reportList(
        context: owner, sourceFilter: .chatReports)
      try expect(
        Set(chatReportsOnly.rows.map(\.id)) == Set([completed.id, failed.id]),
        "chat report filter should show retained wrap-ups only")
      let noMatch = try services.insights.reportList(
        context: owner, searchQuery: "missing-report-query")
      try expect(
        noMatch.state == .noMatch && noMatch.rows.isEmpty,
        "Insights search should return no_match without fabricating rows")
      let persistedState = try services.insights.saveViewState(
        context: owner,
        state: InsightsViewState(
          searchQuery: "token=insights-sensitive-value weekly",
          sourceFilter: .chatReports,
          sort: .title,
          includeArchived: true,
          selectedReportId: completed.id,
          showingAnalytics: true,
          activityGapMinutes: 5000
        ),
        now: fixedDate("2026-01-01T00:00:02Z")
      )
      try expect(
        persistedState.searchQuery.contains("[REDACTED]"),
        "Insights view-state search should be redacted before persistence")
      try expect(
        persistedState.activityGapMinutes == 1440,
        "Insights view-state active gap should clamp to 1440")
      try expect(
        try services.insights.viewState(context: owner).selectedReportId == completed.id,
        "Insights selected report should persist in view state")

      let detail = try services.insights.reportDetail(context: owner, reportId: completed.id)
      try expect(detail.row.id == completed.id, "Insights detail should target retained wrap-up")
      try expect(
        detail.markdown?.contains("Retained report markdown") == true,
        "Insights detail should expose retained markdown")
      try expect(
        detail.structuredData["source"] == .string("thread_wrap_up_reports"),
        "Insights detail should expose retained structured metadata")
      try expect(
        detail.structuredData["rawToken"] == .string("[REDACTED]"),
        "Insights detail should use redacted structured metadata")
      try expect(detail.archiveAvailable, "unarchived Insights detail should allow archive")

      let failedDetail = try services.insights.reportDetail(context: owner, reportId: failed.id)
      try expect(
        failedDetail.retryUnavailableReason == InsightsService.retryUnavailableReason,
        "failed report detail should explain retry unavailability")
      do {
        try services.insights.retryReport(context: owner, reportId: completed.id)
        throw ServiceTestFailure("completed Insights report retry unexpectedly succeeded")
      } catch let denied as ServiceGuardResult {
        try expect(
          denied.reasonCode == .inputInvalid,
          "completed Insights report retry should be denied as invalid")
      }
      do {
        try services.insights.retryReport(context: owner, reportId: failed.id)
        throw ServiceTestFailure(
          "Insights retry unexpectedly succeeded without structured-job support")
      } catch let denied as ServiceGuardResult {
        try expect(
          denied.reasonCode == .featureMissingService,
          "Insights retry should be unavailable until structured-job support exists")
      }
      let generating = try services.data.createThreadWrapUpReport(
        threadId: thread.id,
        sessionId: thread.activeSessionId,
        status: .generating,
        title: "Cycle 1 generating report",
        metadata: ["source": .string("thread_wrap_up_reports")],
        messageCount: 2
      )
      let beforeGeneratingRetryCount = try services.data.listThreadWrapUpReports(
        threadId: thread.id
      ).count
      try services.insights.retryReport(context: owner, reportId: generating.id)
      try expect(
        try services.data.listThreadWrapUpReports(threadId: thread.id).count
          == beforeGeneratingRetryCount, "generating retry should not duplicate reports")

      let analytics = try services.insights.analytics(
        context: owner, threadId: thread.id, activityGapMinutes: 30)
      try expect(analytics.messageCount == 2, "Insights analytics should count retained messages")
      try expect(analytics.sessionCount == 1, "Insights analytics should count retained sessions")
      try expect(
        analytics.senders.count == 2,
        "Insights analytics should derive senders from retained messages")
      try expect(
        analytics.exportAvailable,
        "Insights analytics export should be available for retained messages")
      let analyticsSession = try unwrap(
        analytics.sessions.first, "Insights analytics should expose retained session rows")
      try expect(
        analyticsSession.repeatAnalysisStatus == "completed",
        "source-backed repeat analysis status should derive from report metadata")
      try expect(
        analyticsSession.repeatedAgentMessageCount == 1,
        "repeat analysis repeated count should derive from report metadata")
      try expect(
        analytics.activePeriods.first?.title == "Window 1",
        "Insights analytics should expose active period rows")
      do {
        try services.insights.runRepeatAnalysis(
          context: owner, threadId: thread.id, sessionId: analyticsSession.id)
        throw ServiceTestFailure(
          "Insights repeat analysis unexpectedly succeeded without structured-job support")
      } catch let denied as ServiceGuardResult {
        try expect(
          denied.reasonCode == .featureMissingService,
          "Insights repeat analysis should be unavailable until structured-job support exists")
        try expect(
          denied.message == InsightsService.repeatAnalysisUnavailableReason,
          "Insights repeat analysis should expose stable unavailable reason")
      }
      let postRepeatAttempt = try services.insights.analytics(
        context: owner, threadId: thread.id, activityGapMinutes: 30)
      try expect(
        postRepeatAttempt.sessions.first?.repeatAnalysisStatus == "completed",
        "denied repeat analysis should preserve source-backed results without fabricating new ones")
      let csv = try services.insights.exportAnalyticsCSV(context: owner, threadId: thread.id)
      try expect(
        csv.contains("Messages,2"), "Insights CSV export should include retained message count")
      try expect(
        csv.contains("User messages,1"), "Insights CSV export should include user message count")
      try expect(
        csv.contains("active_period,start,end,messages"),
        "Insights CSV export should include active periods")
      try expect(
        !csv.contains("insights-sensitive-value"),
        "Insights CSV export should not leak sensitive values")
      let json = try services.insights.exportAnalyticsJSON(context: owner, threadId: thread.id)
      try expect(
        json["messageCount"] == .number(2),
        "Insights JSON export should include retained message count")
      try expect(
        json["userMessageCount"] == .number(1),
        "Insights JSON export should include user message count")
      if case .array(let sessions)? = json["sessions"],
        case .object(let firstSession)? = sessions.first
      {
        try expect(
          firstSession["repeatedAgentMessageCount"] == .number(1),
          "Insights JSON export should include source-backed repeat counts")
      } else {
        throw ServiceTestFailure("Insights JSON export should include session rows")
      }

      let archiveDate = fixedDate("2026-01-01T00:00:03Z")
      let expectedArchiveAt = ISO8601DateFormatter.relayConsole.string(from: archiveDate)
      let archived = try services.insights.archiveReport(
        context: owner,
        reportId: snapshot.id,
        now: archiveDate
      )
      archivedSnapshotId = archived.row.id
      try expect(
        archived.row.archivedAt == expectedArchiveAt,
        "archive action should persist archived timestamp")
      let hiddenArchived = try services.insights.reportList(context: owner, includeArchived: false)
      try expect(
        !hiddenArchived.rows.contains { $0.id == snapshot.id },
        "default Insights list should hide archived reports")
      try expect(
        hiddenArchived.archivedCount == 1,
        "default Insights list should still count archived local rows")
      let includedArchived = try services.insights.reportList(context: owner, includeArchived: true)
      try expect(
        includedArchived.rows.contains { $0.id == snapshot.id && $0.archivedAt != nil },
        "archived Insights list should include archived report rows")
      try expect(events.value >= 3, "Insights report mutation events should publish")
    }

    let reopened = try makeServices(root: root)
    let reopenedContext = Self.context(
      roles: [.owner], workspaceId: workspaceId, correlationId: "insights-reopen-001")
    let reopenedList = try reopened.insights.reportList(
      context: reopenedContext, includeArchived: true)
    try expect(
      reopenedList.rows.contains { $0.id == completedReportId },
      "completed Insights report should survive relaunch")
    try expect(
      reopenedList.rows.contains { $0.id == failedReportId && $0.statusLabel == "Report failed" },
      "failed Insights report should survive relaunch")
    try expect(
      reopenedList.rows.contains { $0.id == archivedSnapshotId && $0.archivedAt != nil },
      "archived Insights snapshot should survive relaunch")
    let reopenedState = try reopened.insights.viewState(context: reopenedContext)
    try expect(
      reopenedState.selectedReportId == completedReportId,
      "Insights selected report state should survive relaunch")
    try expect(
      reopenedState.sourceFilter == .chatReports && reopenedState.sort == .title
        && reopenedState.includeArchived,
      "Insights filter sort archive state should survive relaunch")
    try expect(reopenedState.showingAnalytics, "Insights selected tab should survive relaunch")
    try expect(
      reopenedState.activityGapMinutes == 1440, "Insights active gap clamp should survive relaunch")
    let reopenedAnalytics = try reopened.insights.analytics(
      context: reopenedContext, threadId: threadId)
    try expect(
      reopenedAnalytics.messageCount == 2,
      "Insights analytics should derive retained messages after relaunch")
  }

  private static func testFixtureManifestsMatchSchema() throws {
    for path in [
      "Tests/Fixtures/services/baseline/no-fake-bootstrap-001/manifest.md",
      "Tests/Fixtures/services/authority/workspace-owner-admin-member-001/manifest.md",
      "Tests/Fixtures/services/chat/thread-message-archive-read-001/manifest.md",
