      "Tests/Fixtures/services/agents/provisioning-lifecycle-001/manifest.md",
      "Tests/Fixtures/services/agents/org-authority-manager-rules-001/manifest.md",
      "Tests/Fixtures/services/agents/work-dashboard-read-models-001/manifest.md",
      "Tests/Fixtures/services/agentops/live-state-runtime-overview-001/manifest.md",
      "Tests/Fixtures/services/agentops/native-visual-scene-001/manifest.md",
      "Tests/Fixtures/services/runtime/dashboard-snapshot-001/manifest.md",
