      "Tests/Fixtures/services/applications/marketplace-catalog-001/manifest.md",
      "Tests/Fixtures/services/applications/provider-connections-001/manifest.md",
      "Tests/Fixtures/services/applications/install-compatibility-001/manifest.md",
      "Tests/Fixtures/services/applications/needed-tools-001/manifest.md",
      "Tests/Fixtures/services/reports/insights-wrapups-001/manifest.md",
      "Tests/Fixtures/services/authority/permission-policy-local-authority-001/manifest.md",
      "Tests/Fixtures/services/work-safety/audit-security-redaction-001/manifest.md",
      "Tests/Fixtures/services/work-safety/native-file-permissions-001/manifest.md",
      "Tests/Fixtures/services/agents/runtime-workspace-manager-001/manifest.md",
      "Tests/Fixtures/services/work-safety/controlled-actions-001/manifest.md",
      "Tests/Fixtures/services/work-safety/approval-required-block-001/manifest.md",
      "Tests/Fixtures/services/work-safety/task-target-resolution-001/manifest.md",
      "Tests/Fixtures/services/work-safety/approval-authority-001/manifest.md",
      "Tests/Fixtures/services/runtime/dispatch-cancel-failure-001/manifest.md",
    ] {
      let manifest = try readPackageFile(path)
      for field in requiredManifestFields {
        try expect(manifest.contains("\(field):"), "\(path) is missing \(field)")
      }
      try expect(manifest.contains("VC-0102"), "\(path) must link service command id")
      if path.contains("agentops/native-visual-scene") {
        for expected in [
          "ITC-0052",
          "CODE-001-051",
          "bundled_web_agentops_floor_worker_assets",
          "web_default_operations_floor_layout_source_record_backed",
          "sourceRecordIds",
          "visual fallback",
          "status: `verified`",
        ] {
          try expect(
            manifest.contains(expected), "\(path) missing AgentOps visual-scene field \(expected)")
        }
      }
      if path.contains("work-safety") {
        for expected in [
          "ITC-0039",
          "CODE-001-039",
          "Demo 5",
          "standalone Approvals",
          "approval-required",
          "noSimulatedRuntimeOutput:",
          "task execution output",
        ] {
          try expect(
            manifest.contains(expected),
            "\(path) missing work-safety task service field \(expected)")
        }
      }
    }

    let controlledActions = try readPackageFile(
      "Tests/Fixtures/services/work-safety/controlled-actions-001/manifest.md")
    for expected in [
      "ITC-0046",
      "ControlledActionService",
      "controlled_file_write",
      "controlled_provider_write",
      "SAFETY-001",
      "controlled_action.blocked",
      "controlled_action.dry_run_succeeded",
      "writeSideEffect: `false`",
    ] {
      try expect(
        controlledActions.contains(expected), "controlled action fixture missing \(expected)")
    }
  }

  private static func guardedCreateAgent(
    services: RelayConsoleServices,
    workspaceId: String,
    context: ServiceRequestContext
  ) throws -> ServiceGuardResult? {
    if let denied = ServiceGuard.requireAnyRole([.owner, .admin], context: context) {
      _ = try writeDeniedAudit(
        services: services, result: denied, rawDetail: "credential=[REDACTED]")
      return denied
    }
    let harness = try services.data.upsertHarness(
      runtimeType: .hermes,
      displayName: "Hermes Agent",
      mode: .appManaged,
      config: [:]
    )
    _ = try services.data.createAgent(
      workspaceId: workspaceId,
      name: "Service Guard Agent",
      harnessId: harness.id
    )
    return nil
  }

