  private static func prepareInstalledHarness(services: RelayConsoleServices, key: HarnessKey)
    throws -> Harness
  {
    let installPath = services.paths.harnessesDir.appendingPathComponent(
      key == .hermes ? "hermes-agent" : "openclaw", isDirectory: true)
    try FileManager.default.createDirectory(at: installPath, withIntermediateDirectories: true)
    if key == .hermes {
      try "test hermes".write(
        to: installPath.appendingPathComponent("run_agent.py"), atomically: true, encoding: .utf8)
      let python = installPath.appendingPathComponent(".venv/bin/python")
      try FileManager.default.createDirectory(
        at: python.deletingLastPathComponent(), withIntermediateDirectories: true)
      try "test python".write(to: python, atomically: true, encoding: .utf8)
    } else {
      try "test openclaw".write(
        to: installPath.appendingPathComponent("openclaw.mjs"), atomically: true, encoding: .utf8)
      let node = services.paths.openClawToolchainDir.appendingPathComponent("node/bin/node")
      try FileManager.default.createDirectory(
        at: node.deletingLastPathComponent(), withIntermediateDirectories: true)
      try "test node".write(to: node, atomically: true, encoding: .utf8)
    }
    return try services.data.upsertHarness(
      runtimeType: key == .hermes ? .hermes : .openclaw,
      displayName: key == .hermes ? "Hermes Agent" : "OpenClaw",
      mode: .appManaged,
      config: [
        "kind": .string("external_harness_install"),
        "harnessKey": .string(key.rawValue),
        "installPath": .string(installPath.path),
        "source": .string(HarnessInstallSource.managed.rawValue),
        "lifecycleState": .string(HarnessLifecycleState.connected.rawValue),
        "dependencyStatus": .string("installed"),
        "modelAuthStatus": .string(HarnessModelAuthStatus.connected.rawValue),
      ]
    )
  }

