      .appendingPathComponent("agents/\(slug)/agent", isDirectory: true)
      .appendingPathComponent("openclaw-agent.sqlite")
  }

  private static func writeOpenClawAgentDatabase(
    services: RelayConsoleServices,
    slug: String,
    owner: String,
    storeJSON: String
  ) throws {
    let path = openClawAgentDatabasePath(services: services, slug: slug)
    let database = DatabaseService(databasePath: path)
    try database.open()
    defer { database.close() }
    try database.exec(
      """
      CREATE TABLE IF NOT EXISTS schema_meta (
        meta_key TEXT NOT NULL PRIMARY KEY,
        role TEXT NOT NULL,
        schema_version INTEGER NOT NULL,
        agent_id TEXT,
        app_version TEXT,
        created_at INTEGER NOT NULL,
        updated_at INTEGER NOT NULL
      );
      CREATE TABLE IF NOT EXISTS auth_profile_state (
        state_key TEXT NOT NULL PRIMARY KEY,
        state_json TEXT NOT NULL,
        updated_at INTEGER NOT NULL
      );
      CREATE TABLE IF NOT EXISTS auth_profile_store (
        store_key TEXT NOT NULL PRIMARY KEY,
        store_json TEXT NOT NULL,
        updated_at INTEGER NOT NULL
      );
      """)
    try database.run("DELETE FROM schema_meta WHERE meta_key = 'primary'")
    try database.run(
      "INSERT INTO schema_meta (meta_key, role, schema_version, agent_id, app_version, created_at, updated_at) VALUES (?, ?, ?, ?, NULL, ?, ?)",
      [
        .text("primary"), .text("agent"), .integer(1), .text(owner), .integer(1_800_000_000_000),
        .integer(1_800_000_000_000),
      ]
    )
    try database.run(
      "INSERT INTO auth_profile_store (store_key, store_json, updated_at) VALUES (?, ?, ?) ON CONFLICT(store_key) DO UPDATE SET store_json = excluded.store_json, updated_at = excluded.updated_at",
      [.text("primary"), .text(storeJSON), .integer(1_800_000_000_000)]
    )
  }

  private static func readOpenClawAgentDatabaseOwner(_ path: URL) throws -> String? {
    let database = DatabaseService(databasePath: path)
    try database.open()
    defer { database.close() }
    guard
      case .text(let owner)? = try database.get(
        "SELECT agent_id FROM schema_meta WHERE meta_key = 'primary'")?["agent_id"]
    else {
      return nil
    }
    return owner
  }

  private static func readOpenClawAuthProfileStoreJSON(_ path: URL) throws -> String? {
    let database = DatabaseService(databasePath: path)
    try database.open()
    defer { database.close() }
    guard
      case .text(let json)? = try database.get(
        "SELECT store_json FROM auth_profile_store WHERE store_key = 'primary'")?["store_json"]
    else {
      return nil
    }
    return json
  }

