  @discardableResult
  private static func writeDeniedAudit(
    services: RelayConsoleServices,
    result: ServiceGuardResult,
    rawDetail: String
  ) throws -> LogEvent {
    try services.data.log(
      severity: "warning",
      category: "authority",
      message: "Denied action \(rawDetail)",
      correlationId: result.correlationId,
      detail: [
        "stateKind": .string(result.stateKind.rawValue),
        "reasonCode": .string(result.reasonCode.rawValue),
        "auditRequired": .bool(result.auditRequired),
        "rawDetail": .string(rawDetail),
      ]
    )
  }

  private static func makeServices(
    root: URL? = nil,
    runner: CommandRunning = StubCommandRunner(),
    providerActionAdapter: (any MarketplaceProviderActionAdapter)? =
      RoutingMarketplaceProviderActionAdapter(
        xAdapter: XProviderActionAdapter(client: FakeXProviderActionClient())
      ),
    runtimeRunConfirmationEnabled: Bool = false,
    refreshInstalledHarnessesOnLaunch: Bool = false,
    usePublicBetaPolicy: Bool = false,
    seedActiveEntitlement: Bool = true
  ) throws -> RelayConsoleServices {
    let root =
      root
      ?? FileManager.default.temporaryDirectory
      .appendingPathComponent("RelayConsoleServiceTests", isDirectory: true)
      .appendingPathComponent(UUID().uuidString, isDirectory: true)
    var betaPolicy = try ApplicationsBetaPolicy.loadCurrent()
    betaPolicy.approvedSlugs = ApplicationsService.catalogMarketplaceSlugs
    let services = try RelayConsoleServices(
      userDataPath: root,
      appVersion: "test",
      runner: runner,
      secretStore: MemorySecretStore(),
      providerActionAdapter: providerActionAdapter,
      applicationsBetaPolicyOverride: usePublicBetaPolicy ? nil : betaPolicy,
      refreshInstalledHarnessesOnLaunch: refreshInstalledHarnessesOnLaunch,
      openExternal: { _ in }
    )
    try services.data.setAppSetting(
      RuntimeExperienceSettings.runConfirmationEnabledKey,
      value: runtimeRunConfirmationEnabled
    )
    if seedActiveEntitlement {
      try seedPaidEntitlement(services)
    }
    return services
  }

  private static func seedPaidEntitlement(_ services: RelayConsoleServices) throws {
    let privateKey = Curve25519.Signing.PrivateKey()
    let manifestObject: [String: Any] = [
      "deploymentId": "relay-production",
      "deploymentKey": "relay-production",
      "displayName": "Relay",
      "ownershipType": "relay_managed",
      "apiVersion": "v1",
      "syncContractVersion": "2026-07-21.agent-parity.v2",
      "runtimeContractVersion": "bridge.v1",
      "marketplaceContractVersion": "swift-marketplace.v1",
      "minimumClients": [
        "relayConsoleSwift": "0.1.0",
        "ios": "1.0.0",
        "web": "0.0.1",
      ],
      "origins": [
        "api": RelayCloudLaunchContract.apiOrigin,
        "websocket": RelayCloudLaunchContract.websocketOrigin,
      ],
      "features": [String: Any](),
      "connectionDescriptorSigning": [
        "algorithm": "ed25519",
        "keyId": "service-test-v1",
        "publicKey": privateKey.publicKey.rawRepresentation.base64EncodedString(),
      ],
    ]
    let manifest = try JSONDecoder().decode(
      CloudDeploymentManifest.self,
      from: JSONSerialization.data(withJSONObject: manifestObject)
    )
    _ = try services.cloudConnections.saveDeployment(manifest: manifest)
    let accountId = try services.cloudConnections.saveAccount(
      deploymentId: manifest.deploymentId,
      remoteUserId: "remote-user",
      displayName: "Service Test Paid User",
      email: "service-test@example.com",
      accessToken: "service-test-access-token",
      refreshToken: "service-test-refresh-token",
      accessExpiresAt: nil
    )
    let now = Date()
    let workspaceId = "remote-workspace"
    let payload: [String: Any] = [
      "schemaVersion": "relay.entitlements.v1",
      "workspaceId": workspaceId,
      "plan": "relay_connect_monthly",
      "status": "active",
      "mode": "read_write",
      "provider": "stripe",
      "issuedAt": ISO8601DateFormatter.relayConsole.string(from: now),
      "expiresAt": ISO8601DateFormatter.relayConsole.string(
        from: now.addingTimeInterval(5 * 60)
      ),
    ]
    let canonical = try JSONSerialization.data(
      withJSONObject: payload,
      options: [.sortedKeys, .withoutEscapingSlashes]
    )
    let signature = try privateKey.signature(for: canonical)
      .base64EncodedString()
      .replacingOccurrences(of: "+", with: "-")
      .replacingOccurrences(of: "/", with: "_")
      .replacingOccurrences(of: "=", with: "")
    try services.entitlement.recordSignedEntitlement(
      envelope: [
        "payload": payload,
        "signature": signature,
        "algorithm": "ed25519",
        "keyId": "service-test-v1",
      ],
      accountId: accountId,
      workspaceId: workspaceId,
      manifest: manifest,
      now: now
    )
  }

