    let approved = try services.providerActionApprovals.approve(
      context: owner, approvalId: approval.id, approvedPayload: approvedPayload,
      now: fixedDate("2026-01-01T00:30:06Z"))
    let approvedExecution = try services.providerActionBroker.execute(
      context: owner,
      request: MarketplaceProviderActionBrokerRequest(
        appIdOrSlug: app.id, actionKey: "clickup_task_create", payload: approvedPayload,
        installId: install.id, approvalId: approved.id, idempotencyKey: "clickup-approved-execution"
      ), now: fixedDate("2026-01-01T00:30:06Z"))
    try expect(
      approvedExecution.adapterExecuted && approvedExecution.execution.status == .succeeded,
      "Approved ClickUp task creation should execute through the broker")
    _ = try services.providerActionPolicies.compilePolicyMap(
      context: owner, appIdOrSlug: app.id, preset: .allowDirectWrites, acknowledgeDangerousPolicy: true, connectionId: connection.id,
      installId: install.id, agentId: agent.id, now: fixedDate("2026-01-01T00:00:07Z"))
    let direct = try services.providerActionBroker.execute(
      context: owner,
      request: MarketplaceProviderActionBrokerRequest(
        appIdOrSlug: app.id, actionKey: "clickup_task_update",
        payload: ["taskId": .string("task-1"), "status": .string("complete")],
        installId: install.id, idempotencyKey: "clickup-update"),
      now: fixedDate("2026-01-01T00:00:08Z"))
    try expect(
      direct.adapterExecuted && direct.execution.status == .succeeded,
      "Direct rights should broker ClickUp updates")
    let blocked = try services.providerActionBroker.execute(
      context: owner,
      request: MarketplaceProviderActionBrokerRequest(
        appIdOrSlug: app.id, actionKey: "clickup_task_delete",
        payload: ["taskId": .string("task-1")], installId: install.id,
        idempotencyKey: "clickup-delete"), now: fixedDate("2026-01-01T00:00:09Z"))
    try expect(
      !blocked.adapterExecuted && blocked.execution.status == .blocked,
      "ClickUp deletion should remain blocked")
    let persisted = try services.database.all(
      "SELECT connection_json AS value FROM applications_provider_connections UNION ALL SELECT execution_json AS value FROM marketplace_provider_action_executions"
    ).compactMap { sqliteText($0["value"]) }.joined(separator: "\n")
    try expect(!persisted.contains(token), "ClickUp persistence leaked the OAuth token")
  }

