  private static func
    testAirtableProviderIntegrationPreservesBaseSchemaRecordAndCommentSemanticsEndToEnd() throws
  {
    final class StubHTTP: AirtableProviderHTTPClient, @unchecked Sendable {
      var requests: [AirtableProviderHTTPRequest] = []
      func send(_ request: AirtableProviderHTTPRequest) throws -> AirtableProviderHTTPResponse {
        requests.append(request)
        let body =
          #"{"bases":[{"id":"appLive","name":"Launch Data","permissionLevel":"create","workspaceName":"Relay Workspace"}]}"#
          .data(using: .utf8)!
        return AirtableProviderHTTPResponse(statusCode: 200, body: body)
      }
    }
    let root = FileManager.default.temporaryDirectory.appendingPathComponent(
      "RelayConsoleAirtableProviderTests/\(UUID().uuidString)", isDirectory: true)
    let access = "airtable-sensitive-access"
    let refresh = "airtable-sensitive-refresh"
    let services = try makeServices(
      root: root,
      providerActionAdapter: RoutingMarketplaceProviderActionAdapter(
        airtableAdapter: AirtableProviderActionAdapter(client: FakeAirtableProviderActionClient())))
    let workspace = try unwrap(services.data.getAppState().activeWorkspace, "missing workspace")
    let owner = context(roles: [.owner], workspaceId: workspace.id, correlationId: "airtable-owner")
    let agent = try createServiceAgent(services: services, workspaceId: workspace.id)
    var app = marketplaceApp(
      workspaceId: workspace.id, slug: "airtable", name: "Airtable", summary: "Airtable fixture",
      category: "Productivity", riskLevel: .high, connectionState: .none,
      installState: .notInstalled)
    app.authType = "OAuth 2.0 authorization code with PKCE"
    app.connectionType = "Relay-owned Airtable OAuth"
    app.readOnly = false
    _ = try services.applications.saveCatalogApps(context: owner, apps: [app])
    let catalog = try services.applications.catalogSnapshot(context: owner, selectedAppId: app.slug)
    try expect(catalog.selectedApp?.slug == "airtable", "Airtable should be retained")
    app = try unwrap(catalog.selectedApp, "missing canonical Airtable catalog app")
    var connection = try services.providerConnections.saveAirtableRelayOwnedOAuthConnection(
      context: owner, appIdOrSlug: app.id, accessToken: access, refreshToken: refresh,
      userId: "usr-1", userEmail: "relay@example.com", grantId: "grant-1",
      authorizedBaseIds: ["appBase1"], authorizedBaseNames: ["Launch Data"],
      authorizedWorkspaceNames: ["Relay Workspace"], expiresAt: "2026-01-01T01:00:00Z",
      displayName: "Relay Airtable", now: fixedDate("2026-01-01T00:00:00Z"))
    try expect(
      connection.status == .connected
        && connection.requiredScopes == ProviderConnectionService.airtableRelayOwnedOAuthScopes
        && connection.secretReferenceIds.count == 2
        && connection.health.diagnostics["refreshTokenRotation"]
          == .string("single-use-atomic-replacement-required"),
      "Airtable should retain scopes and two secret references")
    let oldRefs = connection.secretReferenceIds
    let storedAccess = try services.secrets.getSecretValue(connection.secretReferenceIds[0])
    let storedRefresh = try services.secrets.getSecretValue(connection.secretReferenceIds[1])
    try expect(
      storedAccess == access && storedRefresh == refresh,
      "Airtable tokens should live in SecretService")
    connection = try services.providerConnections.rotateAirtableOAuthTokens(
      context: owner, connectionId: connection.id, accessToken: "airtable-new-access",
      refreshToken: "airtable-new-refresh", expiresAt: "2026-01-01T02:00:00Z",
      now: fixedDate("2026-01-01T00:30:00Z"))
    try expect(
      connection.secretReferenceIds != oldRefs
        && (try? services.secrets.getSecretValue(oldRefs[0])) == nil
        && (try? services.secrets.getSecretValue(oldRefs[1])) == nil,
      "Airtable rotation should replace then delete old references")
    try expect(
      try services.secrets.getSecretValue(connection.secretReferenceIds[1])
        == "airtable-new-refresh", "Airtable rotation should save the new refresh token")
    let install = try services.marketplaceInstalls.createInstall(
      context: owner,
      request: installRequest(
        id: "minreq-airtable", workspaceId: workspace.id, app: app, connectionId: connection.id,
        agent: agent, roleId: app.roleManifest.primaryRole, selectedCapabilities: app.capabilities,
        riskAcknowledged: true), now: fixedDate("2026-01-01T00:30:01Z"))
    _ = try services.providerActionPolicies.compilePolicyMap(
      context: owner, appIdOrSlug: app.id, preset: .approvalRequired, connectionId: connection.id,
      installId: install.id, agentId: agent.id, now: fixedDate("2026-01-01T00:30:02Z"))
    let surface = try services.providerWrapperTools.compileSurface(
      context: owner, appIdOrSlug: app.id, installId: install.id, agentId: agent.id,
      now: fixedDate("2026-01-01T00:30:03Z"))
    try expect(
      surface.tools.count == 9 && surface.diagnostics.blockedActionCount >= 4
        && !surface.diagnostics.rawProviderToolExposure,
      "Airtable should expose nine wrappers and suppress blocked actions")
    for name in [
      "List Airtable bases", "Get Airtable base schema", "List Airtable table records",
      "Get Airtable record", "List Airtable record comments", "Prepare Airtable record change",
      "Create Airtable record", "Update Airtable record", "Comment on Airtable record",
    ] {
      try expect(
        surface.tools.contains { $0.displayName == name }, "missing Airtable wrapper \(name)")
    }
    let snapshot = try services.marketplaceRuntimeMounts.snapshot(
      context: owner, agent: agent, now: fixedDate("2026-01-01T00:30:04Z"))
    let mounted = try unwrap(
      try services.marketplaceRuntimeMounts.snapshot(
        context: owner, agent: agent, now: fixedDate("2026-01-01T00:30:04Z")
      ).apps.first, "missing Airtable runtime app")
    try expect(
      snapshot.toolCount == 9 && mounted.instructions.contains("table/field/view")
        && mounted.instructions.contains("rotating refresh"),
      "Airtable runtime should mount provider-correct tools")
    let schemaTool = try unwrap(
      mounted.tools.first { $0.displayName == "Get Airtable base schema" }, "missing schema tool")
    let schemaResult = try services.marketplaceRuntimeToolBridge.execute(
      toolName: schemaTool.toolName, payload: ["baseId": .string("appBase1")],
      runtime: MarketplaceRuntimeToolExecutionContext(
        agentId: agent.id, workspaceId: workspace.id, runtimeType: agent.binding.runtimeType,
        dispatchId: "airtable-schema", threadId: "airtable-thread",
        runtimeSessionId: "airtable-session", correlationId: "airtable-schema"),
      now: fixedDate("2026-01-01T00:30:05Z"))
    let provider = try unwrap(objectValue(schemaResult["providerResult"]), "missing schema result")
    let base = try unwrap(objectValue(provider["base"]), "missing base")
    let tables = arrayValue(base["tables"]).compactMap(objectValue)
    try expect(
      provider["semanticReadContract"] == .string("airtable-base-schema-v1")
        && tables.first?["name"] == .string("Tasks")
