            #"{".tag":"file","name":"brief.txt","id":"id:uploaded","path_lower":"/relay/brief.txt","path_display":"/Relay/brief.txt","rev":"rev-upload","size":6,"client_modified":"2026-07-11T00:00:00Z","server_modified":"2026-07-11T00:00:01Z","content_hash":"hash-upload","is_downloadable":true}"#
            .data(using: .utf8)!
