      request: MarketplaceProviderActionAdapterRequest(
        context: owner, app: app, definition: listDefinition, permission: .allowed,
        payload: ["folderId": .string("0"), "maxResults": .number(1)], approvalReference: nil,
        auditIdentity: audit, idempotencyKey: "box-live"))
    try expect(
      http.requests.first?.method == "GET"
        && http.requests.first?.url.path == "/2.0/folders/0/items"
        && http.requests.first?.url.query?.contains("usemarker=true") == true
        && http.requests.first?.headers["Authorization"] == "Bearer box-new-access"
        && liveList.result["nextMarker"] == .string("marker-live"),
      "Box live list should use official marker route and rotated token")
    let uploadDefinition = try unwrap(
      definitions.first { $0.actionKey == "box_text_upload" }, "missing upload definition")
    let upload = try live.executeBoxAction(
      request: MarketplaceProviderActionAdapterRequest(
        context: owner, app: app, definition: uploadDefinition, permission: .autoExecute,
        payload: [
          "parentFolderId": .string("0"), "name": .string("brief.txt"), "text": .string("Launch"),
        ], approvalReference: nil, auditIdentity: audit, idempotencyKey: "box-upload"))
    let uploadRequest = try unwrap(http.requests.last, "missing upload request")
    let body = String(data: uploadRequest.body ?? Data(), encoding: .utf8) ?? ""
    try expect(
      uploadRequest.url.host == "upload.box.com"
        && uploadRequest.url.path == "/api/2.0/files/content"
        && body.range(of: "name=\"attributes\"")?.lowerBound ?? body.endIndex < body.range(
          of: "name=\"file\"")?.lowerBound ?? body.startIndex
        && body.contains("Launch")
        && objectValue(upload.result["item"])?["fileVersionId"] == .string("ver2"),
      "Box multipart upload must put attributes before file and return version metadata")
    let uploadTool = try unwrap(
      mounted.tools.first { $0.displayName == "Upload Box text file" }, "missing upload tool")
    let pending = try services.marketplaceRuntimeToolBridge.execute(
      toolName: uploadTool.toolName,
      payload: [
        "parentFolderId": .string("0"), "name": .string("brief.txt"), "text": .string("Launch"),
      ],
      runtime: MarketplaceRuntimeToolExecutionContext(
        agentId: agent.id, workspaceId: workspace.id, runtimeType: agent.binding.runtimeType,
        dispatchId: "box-pending", threadId: "box-thread", runtimeSessionId: "box-session",
        correlationId: "box-pending"), now: fixedDate("2026-01-01T00:30:06Z"))
    try expect(
      pending["executionStatus"] == .string(ProviderActionExecutionStatus.pendingApproval.rawValue)
        && pending["adapterExecuted"] == .bool(false), "Box upload should await approval")
    _ = try services.providerActionPolicies.compilePolicyMap(
      context: owner, appIdOrSlug: app.id, preset: .allowDirectWrites, acknowledgeDangerousPolicy: true, connectionId: connection.id,
      installId: install.id, agentId: agent.id, now: fixedDate("2026-01-01T00:30:07Z"))
    let direct = try services.providerActionBroker.execute(
      context: owner,
      request: MarketplaceProviderActionBrokerRequest(
        appIdOrSlug: app.id, actionKey: "box_item_move",
        payload: [
          "itemType": .string("file"), "itemId": .string("f1"),
          "destinationFolderId": .string("f2"), "etag": .string("1"),
        ], installId: install.id, idempotencyKey: "box-move"),
      now: fixedDate("2026-01-01T00:30:08Z"))
    try expect(
      direct.adapterExecuted && direct.execution.status == .succeeded,
      "Direct rights should broker Box move")
    let blocked = try services.providerActionBroker.execute(
      context: owner,
      request: MarketplaceProviderActionBrokerRequest(
        appIdOrSlug: app.id, actionKey: "box_item_delete", payload: ["itemId": .string("f1")],
        installId: install.id, idempotencyKey: "box-delete"), now: fixedDate("2026-01-01T00:30:09Z")
    )
    try expect(
      !blocked.adapterExecuted && blocked.execution.status == .blocked,
      "Box deletion should remain blocked")
    let persisted = try services.database.all(
      "SELECT connection_json AS value FROM applications_provider_connections UNION ALL SELECT execution_json AS value FROM marketplace_provider_action_executions"
    ).compactMap { sqliteText($0["value"]) }.joined(separator: "\n")
    for secret in [access, refresh, "box-new-access", "box-new-refresh"] {
      try expect(!persisted.contains(secret), "Box persistence leaked a token")
    }
  }

  private static func
    testCanvaProviderIntegrationPreservesDesignFolderContinuationAndRotatingOAuthSemanticsEndToEnd()
