        ], approvalReference: nil, auditIdentity: audit, idempotencyKey: "canva-live"))
    try expect(
      http.requests.first?.url.path == "/rest/v1/designs"
        && http.requests.first?.url.query?.contains("continuation=current") == true
        && http.requests.first?.headers["Authorization"] == "Bearer canva-new-access"
        && result.result["continuation"] == .string("next-live")
        && String(describing: result.result["designs"] ?? .null).contains("Relay Campaign")
        && !String(describing: result.result).contains("temporary.invalid"),
      "Canva live list should preserve useful metadata and continuation without persisting temporary URLs"
    )
    let createTool = try unwrap(
      mounted.tools.first { $0.displayName == "Create Canva design" }, "missing Canva create tool")
    let pending = try services.marketplaceRuntimeToolBridge.execute(
      toolName: createTool.toolName,
