      now: fixedDate("2026-01-01T00:00:00Z"))
    try expect(
      connection.status == .connected
        && connection.requiredScopes == ["write_products", "write_publications"]
        && connection.secretReferenceIds.count == 2
        && connection.health.diagnostics["refreshTokenRotation"]
          == .string(
            "single-use-serialized-atomic-two-reference-replacement-with-one-hour-retry-window")
        && connection.health.diagnostics["apiVersion"] == .string("2026-07")
        && connection.health.diagnostics["protectedCustomerDataRequested"] == .bool(false)
        && connection.health.diagnostics["atomicProductConcurrencySupported"] == .bool(false)
        && connection.callbackURL?.contains("localhost") != true,
