        && http.requests.last?.url.path == "/v1/payment_intents"
        && http.requests.last?.url.query?.contains("starting_after=pi_cursor123") == true
        && encoded.contains("pi_live123") && encoded.contains("amount_received")
        && !encoded.contains("pi_secret_leak") && !encoded.contains("cus_private")
        && !encoded.contains("pm_private") && !encoded.contains("private@example.com")
        && !encoded.contains("Private order"),
