    _ = try services.providerActionPolicies.compilePolicyMap(
      context: owner, appIdOrSlug: app.id, preset: .approvalRequired, connectionId: connection.id,
      installId: install.id, agentId: agent.id, now: fixedDate("2026-01-01T00:30:02Z"))
    let surface = try services.providerWrapperTools.compileSurface(
      context: owner, appIdOrSlug: app.id, installId: install.id, agentId: agent.id,
      now: fixedDate("2026-01-01T00:30:03Z"))
    try expect(
      surface.tools.count == 5 && surface.diagnostics.blockedActionCount >= 5
        && !surface.diagnostics.rawProviderToolExposure,
      "QuickBooks should expose five read-only wrappers and block broad Accounting, Payroll, and Payments scope surfaces")
    let mounted = try unwrap(
      try services.marketplaceRuntimeMounts.snapshot(
        context: owner, agent: agent, now: fixedDate("2026-01-01T00:30:04Z")
      ).apps.first, "missing QuickBooks runtime app")
    let companyTool = try unwrap(
      mounted.tools.first { $0.displayName == "Get QuickBooks company info" },
      "missing QuickBooks company tool")
    let fake = try services.marketplaceRuntimeToolBridge.execute(
      toolName: companyTool.toolName, payload: [:],
      runtime: MarketplaceRuntimeToolExecutionContext(
        agentId: agent.id, workspaceId: workspace.id, runtimeType: agent.binding.runtimeType,
        dispatchId: "quickbooks-company", threadId: "quickbooks-thread",
        runtimeSessionId: "quickbooks-session", correlationId: "quickbooks-company"),
      now: fixedDate("2026-01-01T00:30:05Z"))
    let fakeProvider = try unwrap(
      objectValue(fake["providerResult"]), "missing QuickBooks fake result")
    try expect(
      fakeProvider["semanticReadContract"] == .string("quickbooks-company-info-v1")
        && String(describing: fakeProvider["companyInfo"] ?? .null).contains("Relay Books Ltd"),
      "QuickBooks fake CompanyInfo should preserve useful exact-realm semantics")
    let definitions = try services.data.listMarketplaceProviderActionDefinitions(
      workspaceId: workspace.id, appId: app.id)
    let listDefinition = try unwrap(
      definitions.first { $0.actionKey == "quickbooks_invoice_list" },
      "missing QuickBooks list definition")
    let http = StubHTTP()
    let live = LiveQuickBooksProviderActionClient(
      data: services.data, secrets: services.secrets, httpClient: http)
    let audit = ProviderExecutionAuditIdentity(
      workspaceId: workspace.id, actorId: owner.actorId, actorRole: "owner", agentId: agent.id,
      appId: app.id, appSlug: app.slug, connectionId: connection.id, installId: install.id,
      approvalId: nil, dispatchId: "quickbooks-live", threadId: "quickbooks-thread",
      source: "quickbooks-live-test", redactionStatus: "private-state-excluded")
    let liveList = try live.executeQuickBooksAction(
      request: MarketplaceProviderActionAdapterRequest(
        context: owner, app: app, definition: listDefinition, permission: .approvalRequired,
        payload: ["startPosition": .number(11), "limit": .number(25)], approvalReference: nil,
        auditIdentity: audit, idempotencyKey: "quickbooks-live-list"))
    let encoded = String(describing: liveList.result)
    let queryItems =
      URLComponents(url: http.requests.last!.url, resolvingAgainstBaseURL: false)?.queryItems ?? []
    try expect(
      http.requests.last?.url.host == "sandbox-quickbooks.api.intuit.com"
        && http.requests.last?.url.path == "/v3/company/\(realm)/query"
        && queryItems.first(where: { $0.name == "minorversion" })?.value == "75"
        && queryItems.first(where: { $0.name == "query" })?.value?.contains(
          "STARTPOSITION 11 MAXRESULTS 25") == true
        && http.requests.last?.headers["Authorization"] == "Bearer quickbooks-new-access"
        && encoded.contains("120.3") && encoded.contains("CustomerId")
        && !encoded.contains("Private Customer") && !encoded.contains("private@example.com")
        && !encoded.contains("Private service") && !encoded.contains("Private note"),
      "QuickBooks Invoice query should use exact realm/environment/minor version and redact private Accounting data"
    )
    let getDefinition = try unwrap(
      definitions.first { $0.actionKey == "quickbooks_invoice_get" },
      "missing QuickBooks get definition")
    do {
      _ = try live.executeQuickBooksAction(
        request: MarketplaceProviderActionAdapterRequest(
          context: owner, app: app, definition: getDefinition, permission: .approvalRequired,
          payload: ["invoiceId": .string("not-numeric")], approvalReference: nil,
          auditIdentity: audit, idempotencyKey: "quickbooks-invalid"))
      throw ServiceTestFailure("Invalid QuickBooks Invoice ID was accepted")
    } catch is MarketplaceProviderActionAdapterFailure {}
    let pendingTool = try unwrap(
      mounted.tools.first { $0.displayName == "List QuickBooks invoices" },
      "missing QuickBooks list tool")
    let pending = try services.marketplaceRuntimeToolBridge.execute(
      toolName: pendingTool.toolName, payload: ["limit": .number(10)],
      runtime: MarketplaceRuntimeToolExecutionContext(
        agentId: agent.id, workspaceId: workspace.id, runtimeType: agent.binding.runtimeType,
        dispatchId: "quickbooks-pending", threadId: "quickbooks-thread",
        runtimeSessionId: "quickbooks-session", correlationId: "quickbooks-pending"),
      now: fixedDate("2026-01-01T00:30:06Z"))
    try expect(
      pending["executionStatus"] == .string(ProviderActionExecutionStatus.pendingApproval.rawValue)
        && pending["adapterExecuted"] == .bool(false),
      "High-risk QuickBooks Invoice reads should await approval")
    for action in [
      "quickbooks_accounting_mutation", "quickbooks_private_accounting_data",
      "quickbooks_broader_accounting", "quickbooks_payments_payroll", "quickbooks_raw_api",
    ] {
      let blocked = try services.providerActionBroker.execute(
        context: owner,
        request: MarketplaceProviderActionBrokerRequest(
          appIdOrSlug: app.id, actionKey: action, payload: [:], installId: install.id,
          idempotencyKey: action), now: fixedDate("2026-01-01T00:30:07Z"))
      try expect(
        !blocked.adapterExecuted && blocked.execution.status == .blocked,
        "QuickBooks blocked action escaped policy: " + action)
    }
    let persisted = try services.database.all(
      "SELECT connection_json AS value FROM applications_provider_connections UNION ALL SELECT execution_json AS value FROM marketplace_provider_action_executions"
    ).compactMap { sqliteText($0["value"]) }.joined(separator: "\n")
    for value in [access, refresh, "quickbooks-new-access", "quickbooks-new-refresh"] {
      try expect(!persisted.contains(value), "QuickBooks persistence leaked a token")
    }
  }

