        requests.append(request)
        let invoice =
          #"{"invoiceid":2201278,"invoice_number":"0005","create_date":"2026-07-01","due_date":"2026-07-31","v3_status":"sent","display_status":"sent","payment_status":"unpaid","amount":{"amount":"800.00","code":"GBP"},"paid":{"amount":"0.00","code":"GBP"},"outstanding":{"amount":"800.00","code":"GBP"},"customerid":58,"fname":"Private","lname":"Client","email":"private@example.com","street":"Private","notes":"Private note","terms":"Private terms","lines":[{"description":"Private service"}],"return_uri":"private"}"#
        if request.url.path.hasSuffix("/users/me") {
