              #"{"response":{"id":712052,"profile":{"first_name":"Private","email":"private@example.com"},"business_memberships":[{"id":111,"role":"owner","business":{"id":240340,"business_uuid":"046cc001-0002-e93e-1db1-1186b2983879","name":"Relay Books Studio","account_id":"ABC123","active":true}}]}}"#
              .data(using: .utf8)!)
        }
        if request.url.path.hasSuffix("/invoices") {
          return FreshBooksProviderHTTPResponse(
            statusCode: 200,
            body: ("{\"response\":{\"result\":{\"invoices\":[" + invoice + "]}}}").data(
