      context: owner, appIdOrSlug: app.id, accessToken: access, refreshToken: refresh,
      businessId: "240340", businessUUID: "046cc001-0002-e93e-1db1-1186b2983879",
      businessName: "Relay Books Studio", accountId: "ABC123", membershipRole: "owner",
      accessExpiresAt: "2026-01-01T12:00:00Z", accessExpiresInSeconds: 43199,
