    let persisted = try services.database.all(
      "SELECT connection_json AS value FROM applications_provider_connections"
    ).compactMap { sqliteText($0["value"]) }.joined()
    for value in [access, refresh, "zendesk-new-access", "zendesk-new-refresh"] {
      try expect(!persisted.contains(value), "Zendesk token persisted")
    }
  }

