          #"{"response_id":"response_789","response_type":"completed","landed_at":"2026-07-11T08:59:00Z","submitted_at":"2026-07-11T09:00:00Z","answers":[{"email":"private@example.com","text":"PRIVATE ANSWER"}],"hidden":{"private":"PRIVATE"},"calculated":{"score":99},"metadata":{"network_id":"PRIVATE"},"token":"PRIVATE"}"#
        let body =
          request.url.path.hasSuffix("/responses")
          ? "{\"items\":[" + response + "]}"
          : request.url.path == "/forms" ? "{\"items\":[" + form + "]}" : form
        return TypeformProviderHTTPResponse(statusCode: 200, body: body.data(using: .utf8)!)
      }
    }
    let root = FileManager.default.temporaryDirectory.appendingPathComponent(
      "RelayConsoleTypeformProviderTests/" + UUID().uuidString, isDirectory: true)
    let a1 = "typeform-access-one"
    let r1 = "typeform-refresh-one"
    let a2 = "typeform-access-two"
    let r2 = "typeform-refresh-two"
    let services = try makeServices(
      root: root,
      providerActionAdapter: RoutingMarketplaceProviderActionAdapter(
        typeformAdapter: TypeformProviderActionAdapter(client: FakeTypeformProviderActionClient())))
    let workspace = try unwrap(services.data.getAppState().activeWorkspace, "missing workspace")
    let owner = context(roles: [.owner], workspaceId: workspace.id, correlationId: "typeform-owner")
    let agent = try createServiceAgent(services: services, workspaceId: workspace.id)
    var app = marketplaceApp(
      workspaceId: workspace.id, slug: "typeform", name: "Typeform", summary: "Typeform fixture",
      category: "Forms", riskLevel: .high, connectionState: .none, installState: .notInstalled)
    app.readOnly = true
    app.runtimeSupport = [.hermes, .openclaw]
    _ = try services.applications.saveCatalogApps(context: owner, apps: [app])
    let catalog = try services.applications.catalogSnapshot(context: owner, selectedAppId: app.slug)
    try expect(catalog.selectedApp?.slug == "typeform", "Typeform should be retained")
    app = try unwrap(catalog.selectedApp, "Typeform should use the canonical catalog app")
    _ = try services.applications.saveCatalogApps(context: owner, apps: [app])
    app = try canonicalMarketplaceApp(services: services, context: owner, app: app)
    let scopes = ProviderConnectionService.typeformRelayOwnedOAuthScopes
    let account = "account_123"
    let workspaceId = "workspace_456"
    for bad in [
      ("bad/account", workspaceId, "https://api.typeform.com", scopes),
      (account, "bad/workspace", "https://api.typeform.com", scopes),
      (account, workspaceId, "https://evil.example", scopes),
      (account, workspaceId, "https://api.typeform.com", ["forms:read"]),
      (account, workspaceId, "https://api.typeform.com", scopes + ["forms:write"]),
    ] {
      do {
        _ = try services.providerConnections.saveTypeformRelayOwnedOAuthConnection(
          context: owner, appIdOrSlug: app.id, accessToken: a1, refreshToken: r1, accountId: bad.0,
          accountLabel: nil, workspaceId: bad.1, workspaceName: nil, apiOrigin: bad.2,
          accessExpiresAt: nil, grantedScopes: bad.3)
        throw ServiceTestFailure("Unsafe Typeform account/workspace/origin/scope accepted")
      } catch is ServiceTestFailure {
        throw ServiceTestFailure("Unsafe Typeform account/workspace/origin/scope accepted")
      } catch {}
    }
    var connection = try services.providerConnections.saveTypeformRelayOwnedOAuthConnection(
      context: owner, appIdOrSlug: app.id, accessToken: a1, refreshToken: r1, accountId: account,
      accountLabel: "Relay Account", workspaceId: workspaceId, workspaceName: "Relay Forms",
      apiOrigin: "https://api.eu.typeform.com", accessExpiresAt: "2026-07-18T12:00:00Z",
      now: fixedDate("2026-07-11T12:00:00Z"))
    let old = connection.secretReferenceIds
    connection = try services.providerConnections.rotateTypeformOAuthTokens(
      context: owner, connectionId: connection.id, accessToken: a2, refreshToken: r2,
      accessExpiresAt: "2026-07-18T13:00:00Z")
    try expect(
      old.allSatisfy { (try? services.secrets.getSecretValue($0)) == nil }
        && Set(connection.secretReferenceIds).isDisjoint(with: Set(old))
        && connection.health.diagnostics["apiOrigin"] == .string("https://api.eu.typeform.com")
        && connection.health.diagnostics["singleUseRefreshToken"] == .bool(true)
        && connection.health.diagnostics["documentedDefaultAccessTokenLifetimeSeconds"]
          == .number(604800)
        && connection.health.diagnostics["accountRateLimitRequestsPerSecond"] == .number(2)
        && connection.callbackURL?.contains("localhost") != true,
      "Typeform token/account/workspace/region contract failed")
    let install = try services.marketplaceInstalls.createInstall(
      context: owner,
      request: installRequest(
        id: "minreq-typeform", workspaceId: workspace.id, app: app, connectionId: connection.id,
        agent: agent, roleId: app.roleManifest.primaryRole, selectedCapabilities: app.capabilities,
        riskAcknowledged: true))
    _ = try services.providerActionPolicies.compilePolicyMap(
      context: owner, appIdOrSlug: app.id, preset: .approvalRequired, connectionId: connection.id,
      installId: install.id, agentId: agent.id)
    let surface = try services.providerWrapperTools.compileSurface(
      context: owner, appIdOrSlug: app.id, installId: install.id, agentId: agent.id)
    try expect(
      surface.tools.count == 3 && surface.diagnostics.blockedActionCount >= 5
        && surface.tools.allSatisfy(\.requiresApproval), "Typeform wrapper budget mismatch")
    let defs = try services.data.listMarketplaceProviderActionDefinitions(
      workspaceId: workspace.id, appId: app.id)
    let list = try unwrap(
      defs.first { $0.actionKey == "typeform_form_list_recent" }, "missing form list")
    let get = try unwrap(defs.first { $0.actionKey == "typeform_form_get" }, "missing form get")
    let responses = try unwrap(
      defs.first { $0.actionKey == "typeform_response_list_recent" }, "missing response list")
    let http = StubHTTP()
    let live = LiveTypeformProviderActionClient(
      data: services.data, secrets: services.secrets, httpClient: http,
      now: { fixedDate("2026-07-11T12:00:00Z") })
    let audit = ProviderExecutionAuditIdentity(
      workspaceId: workspace.id, actorId: owner.actorId, actorRole: "owner", agentId: agent.id,
      appId: app.id, appSlug: app.slug, connectionId: connection.id, installId: install.id,
      approvalId: nil, dispatchId: "typeform-live", threadId: "typeform-thread", source: "test",
      redactionStatus: "respondent-content-excluded")
    let listed = try live.executeTypeformAction(
      request: MarketplaceProviderActionAdapterRequest(
        context: owner, app: app, definition: list, permission: .approvalRequired, payload: [:],
        approvalReference: nil, auditIdentity: audit, idempotencyKey: "typeform-list"))
    let listedText = String(describing: listed.result)
    try expect(
      http.requests.last?.url.absoluteString
        == "https://api.eu.typeform.com/forms?workspace_id=workspace_456&page=1&page_size=25&sort_by=last_updated_at&order_by=desc"
        && listedText.contains("Customer feedback") && !listedText.contains("PRIVATE"),
      "Typeform list/privacy contract failed")
    _ = try live.executeTypeformAction(
      request: MarketplaceProviderActionAdapterRequest(
        context: owner, app: app, definition: get, permission: .approvalRequired,
        payload: ["formId": .string("abcDEF123")], approvalReference: nil, auditIdentity: audit,
        idempotencyKey: "typeform-get"))
    try expect(
      http.requests.last?.url.absoluteString == "https://api.eu.typeform.com/forms/abcDEF123",
      "Typeform exact Form path mismatch")
    let responseResult = try live.executeTypeformAction(
      request: MarketplaceProviderActionAdapterRequest(
        context: owner, app: app, definition: responses, permission: .approvalRequired,
        payload: ["formId": .string("abcDEF123")], approvalReference: nil, auditIdentity: audit,
        idempotencyKey: "typeform-responses"))
    let responseText = String(describing: responseResult.result)
    let query =
      URLComponents(url: http.requests.last!.url, resolvingAgainstBaseURL: false)?.queryItems ?? []
    try expect(
      query == [
        URLQueryItem(name: "since", value: "2026-06-27T12:00:00Z"),
        URLQueryItem(name: "until", value: "2026-07-11T12:00:00Z"),
        URLQueryItem(name: "page_size", value: "25"),
        URLQueryItem(name: "response_type", value: "completed"),
        URLQueryItem(name: "sort", value: "submitted_at,desc"),
      ] && responseText.contains("response_789") && !responseText.contains("PRIVATE")
        && !responseText.contains("private@example.com"),
      "Typeform response privacy/query contract failed")
    for invalid in ["", "bad/id", String(repeating: "a", count: 65)] {
      do {
        _ = try live.executeTypeformAction(
          request: MarketplaceProviderActionAdapterRequest(
            context: owner, app: app, definition: get, permission: .approvalRequired,
            payload: ["formId": .string(invalid)], approvalReference: nil, auditIdentity: audit,
            idempotencyKey: "typeform-invalid"))
        throw ServiceTestFailure("Unsafe Typeform Form ID accepted")
      } catch is ServiceTestFailure {
        throw ServiceTestFailure("Unsafe Typeform Form ID accepted")
      } catch {}
    }
    for action in [
      "typeform_mutation", "typeform_private_response", "typeform_broader_account",
      "typeform_raw_query", "typeform_bulk_export",
    ] {
      let blocked = try services.providerActionBroker.execute(
        context: owner,
        request: MarketplaceProviderActionBrokerRequest(
          appIdOrSlug: app.id, actionKey: action, payload: [:], installId: install.id,
          idempotencyKey: action))
      try expect(
        blocked.execution.status == .blocked && !blocked.adapterExecuted,
        "Typeform blocked action escaped")
    }
    let persisted = try services.database.all(
      "SELECT connection_json AS value FROM applications_provider_connections UNION ALL SELECT execution_json AS value FROM marketplace_provider_action_executions"
    ).compactMap { sqliteText($0["value"]) }.joined()
    for value in [a1, r1, a2, r2] {
      try expect(!persisted.contains(value), "Typeform token persisted")
    }
  }

  private static func
    testSurveyMonkeyProviderIntegrationPreservesExactUserRegionalStaticTokenBoundedSurveyResponseMetadataSemanticsEndToEnd()
    throws
  {
    final class StubHTTP: SurveyMonkeyProviderHTTPClient, @unchecked Sendable {
      var requests: [SurveyMonkeyProviderHTTPRequest] = []

      func send(_ request: SurveyMonkeyProviderHTTPRequest) throws
        -> SurveyMonkeyProviderHTTPResponse
      {
        requests.append(request)
        let survey =
          #"{"id":"123456789","title":"Customer feedback","nickname":"Q3 feedback","language":"en","response_count":42,"date_created":"2026-07-01T09:00:00Z","date_modified":"2026-07-11T09:00:00Z","owner":{"email":"PRIVATE-owner@example.com"},"href":"PRIVATE-HREF","questions":["PRIVATE QUESTION"]}"#
        let response =
          #"{"id":"987654321","response_status":"completed","date_created":"2026-07-11T08:59:00Z","date_modified":"2026-07-11T09:00:00Z","pages":[{"questions":[{"answers":[{"text":"PRIVATE ANSWER"}]}]}],"ip_address":"PRIVATE-IP","recipient_id":"PRIVATE-recipient","custom_variables":{"private":"PRIVATE"},"collector_id":"PRIVATE-collector"}"#
        let body: String
        if request.url.path == "/v3/surveys" {
          body = "{\"data\":[" + survey + "]}"
        } else if request.url.path.hasSuffix("/responses/987654321") {
          body = response
        } else {
          body = #"{"data":[{"id":"987654321","href":"PRIVATE-HREF","pages":["PRIVATE"]}]}"#
        }
        return SurveyMonkeyProviderHTTPResponse(statusCode: 200, body: Data(body.utf8))
      }
    }

    let root = FileManager.default.temporaryDirectory.appendingPathComponent(
      "RelayConsoleSurveyMonkeyProviderTests/" + UUID().uuidString, isDirectory: true)
    let token = "surveymonkey-access-token-private"
    let services = try makeServices(
      root: root,
      providerActionAdapter: RoutingMarketplaceProviderActionAdapter(
        surveyMonkeyAdapter: SurveyMonkeyProviderActionAdapter(
          client: FakeSurveyMonkeyProviderActionClient()))
