    let scopes = ProviderConnectionService.surveyMonkeyRelayOwnedOAuthScopes
    for invalid in [
      ("bad/user", "https://api.surveymonkey.com", scopes),
      ("123456789", "https://evil.example", scopes),
      ("123456789", "https://api.surveymonkey.com", ["users_read", "surveys_read"]),
      ("123456789", "https://api.surveymonkey.com", scopes + ["responses_read_detail"]),
    ] {
