      now: fixedDate("2026-07-11T12:00:00Z")
    )
    try expect(
      connection.secretReferenceIds.count == 1
        && connection.credentialRequirements.first?.fieldKey == "surveymonkey_oauth_access_token"
        && connection.health.diagnostics["accessURL"] == .string("https://api.eu.surveymonkey.com")
        && connection.health.diagnostics["accessTokenCurrentlyExpires"] == .bool(false)
        && connection.health.diagnostics["refreshTokenDocumented"] == .bool(false)
        && connection.health.diagnostics["responseDetailsScopeRequested"] == .bool(false)
        && connection.health.diagnostics["answersReturned"] == .bool(false)
        && connection.health.diagnostics["automaticPaginationAllowed"] == .bool(false)
        && connection.health.diagnostics["rateLimitHeadersAuthoritative"] == .bool(true)
        && connection.callbackURL?.contains("localhost") != true,
      "SurveyMonkey token/user/origin contract failed"
    )

    let install = try services.marketplaceInstalls.createInstall(
      context: owner,
      request: installRequest(
        id: "minreq-surveymonkey", workspaceId: workspace.id, app: app, connectionId: connection.id,
        agent: agent, roleId: app.roleManifest.primaryRole, selectedCapabilities: app.capabilities,
        riskAcknowledged: true))
    _ = try services.providerActionPolicies.compilePolicyMap(
      context: owner, appIdOrSlug: app.id, preset: .approvalRequired, connectionId: connection.id,
      installId: install.id, agentId: agent.id)
    let surface = try services.providerWrapperTools.compileSurface(
      context: owner, appIdOrSlug: app.id, installId: install.id, agentId: agent.id)
    try expect(
      surface.tools.count == 3 && surface.diagnostics.blockedActionCount >= 5
        && surface.tools.allSatisfy(\.requiresApproval), "SurveyMonkey wrapper budget mismatch")
    let mounted = try unwrap(
      try services.marketplaceRuntimeMounts.snapshot(
        context: owner, agent: agent, now: fixedDate("2026-07-11T12:00:01Z")
      ).apps.first, "missing SurveyMonkey runtime app")
    try expect(
      mounted.tools.count == 3 && mounted.instructions.count <= 1200
        && mounted.instructions.contains("Survey")
        && mounted.instructions.contains("response metadata")
        && mounted.instructions.contains("never expose answers"),
      "SurveyMonkey runtime snapshot should expose only concise provider-correct wrappers")
    let runtimeTool = try unwrap(
      mounted.tools.first { $0.displayName == "List recently modified SurveyMonkey Surveys" },
      "missing SurveyMonkey Survey list tool")
    let pending = try services.marketplaceRuntimeToolBridge.execute(
      toolName: runtimeTool.toolName, payload: [:],
      runtime: MarketplaceRuntimeToolExecutionContext(
        agentId: agent.id, workspaceId: workspace.id, runtimeType: agent.binding.runtimeType,
        dispatchId: "surveymonkey-runtime", threadId: "surveymonkey-thread",
        runtimeSessionId: "surveymonkey-session", correlationId: "surveymonkey-runtime"),
      now: fixedDate("2026-07-11T12:00:02Z"))
    try expect(
      pending["executionStatus"] == .string(ProviderActionExecutionStatus.pendingApproval.rawValue)
        && pending["adapterExecuted"] == .bool(false),
      "SurveyMonkey runtime wrapper should remain approval-gated")

    let definitions = try services.data.listMarketplaceProviderActionDefinitions(
      workspaceId: workspace.id, appId: app.id)
    let surveyList = try unwrap(
      definitions.first { $0.actionKey == "surveymonkey_survey_list_recent" }, "missing Survey list"
    )
    let responseList = try unwrap(
      definitions.first { $0.actionKey == "surveymonkey_response_list" }, "missing response list")
    let responseGet = try unwrap(
      definitions.first { $0.actionKey == "surveymonkey_response_get" }, "missing response get")
    let http = StubHTTP()
    let live = LiveSurveyMonkeyProviderActionClient(
      data: services.data, secrets: services.secrets, httpClient: http)
    let audit = ProviderExecutionAuditIdentity(
      workspaceId: workspace.id, actorId: owner.actorId, actorRole: "owner", agentId: agent.id,
      appId: app.id, appSlug: app.slug, connectionId: connection.id, installId: install.id,
      approvalId: nil, dispatchId: "surveymonkey-live", threadId: "surveymonkey-thread",
      source: "test", redactionStatus: "response-content-excluded")
    func request(_ definition: MarketplaceProviderActionDefinition, _ payload: JSONRecord = [:])
      -> MarketplaceProviderActionAdapterRequest
    {
      MarketplaceProviderActionAdapterRequest(
        context: owner, app: app, definition: definition, permission: .approvalRequired,
        payload: payload, approvalReference: nil, auditIdentity: audit,
        idempotencyKey: definition.actionKey)
    }

    let surveys = try live.executeSurveyMonkeyAction(request: request(surveyList))
    try expect(
      http.requests.last?.url.absoluteString
        == "https://api.eu.surveymonkey.com/v3/surveys?page=1&per_page=25&sort_by=date_modified&sort_order=DESC&include=response_count,date_created,date_modified,language"
        && http.requests.last?.headers["Authorization"] == "Bearer " + token
        && String(describing: surveys.result).contains("Customer feedback")
        && !String(describing: surveys.result).contains("PRIVATE"),
      "SurveyMonkey bounded Survey list/privacy contract failed"
    )
    let listed = try live.executeSurveyMonkeyAction(
      request: request(responseList, ["surveyId": .string("123456789")]))
    try expect(
      http.requests.last?.url.absoluteString
        == "https://api.eu.surveymonkey.com/v3/surveys/123456789/responses?page=1&per_page=25"
        && String(describing: listed.result).contains("987654321")
        && !String(describing: listed.result).contains("PRIVATE"),
      "SurveyMonkey response reference contract failed")
    let exact = try live.executeSurveyMonkeyAction(
      request: request(
        responseGet, ["surveyId": .string("123456789"), "responseId": .string("987654321")]))
    let exactText = String(describing: exact.result)
    try expect(
      http.requests.last?.url.absoluteString
        == "https://api.eu.surveymonkey.com/v3/surveys/123456789/responses/987654321"
        && exactText.contains("completed") && !exactText.contains("PRIVATE")
        && !exactText.contains("private"),
      "SurveyMonkey exact response metadata/privacy contract failed")

    for invalid in ["", "0", "bad/id", String(repeating: "1", count: 33)] {
      do {
        _ = try live.executeSurveyMonkeyAction(
          request: request(responseList, ["surveyId": .string(invalid)]))
        throw ServiceTestFailure("Unsafe SurveyMonkey ID accepted")
      } catch is ServiceTestFailure {
        throw ServiceTestFailure("Unsafe SurveyMonkey ID accepted")
      } catch {}
    }
    for action in [
      "surveymonkey_mutation", "surveymonkey_private_response", "surveymonkey_broader_account",
      "surveymonkey_raw_query", "surveymonkey_bulk_export",
    ] {
      let blocked = try services.providerActionBroker.execute(
        context: owner,
        request: MarketplaceProviderActionBrokerRequest(
