    let userId = "aaaaaaaa-bbbb-cccc-dddd-eeeeeeeeeeee"
    let accountId = "11111111-2222-3333-4444-555555555555"
    for bad in [
      ("bad/user", accountId, "https://na3.docusign.net", scopes),
