      (userId, accountId, "https://na3.docusign.net/restapi", scopes),
      (userId, accountId, "https://na3.docusign.net", ["signature"]),
      (userId, accountId, "https://na3.docusign.net", scopes + ["impersonation"]),
    ] {
      do {
        _ = try services.providerConnections.saveDocusignRelayOwnedOAuthConnection(
          context: owner, appIdOrSlug: app.id, accessToken: access1, refreshToken: refresh1,
          userId: bad.0, userName: "Relay User", accountId: bad.1, accountName: "Relay Legal",
          baseURI: bad.2, accessExpiresAt: nil, grantedScopes: bad.3)
        throw ServiceTestFailure("Unsafe Docusign identity, account, base URI, or scope accepted")
      } catch is ServiceTestFailure {
        throw ServiceTestFailure("Unsafe Docusign identity, account, base URI, or scope accepted")
      } catch {}
    }
    var connection = try services.providerConnections.saveDocusignRelayOwnedOAuthConnection(
      context: owner, appIdOrSlug: app.id, accessToken: access1, refreshToken: refresh1,
      userId: userId, userName: "Relay User", accountId: accountId, accountName: "Relay Legal",
      baseURI: "https://na3.docusign.net", accessExpiresAt: "2026-07-11T20:00:00Z",
      grantedScopes: scopes, now: fixedDate("2026-07-11T12:00:00Z"))
    let oldRefs = connection.secretReferenceIds
    connection = try services.providerConnections.rotateDocusignOAuthTokens(
      context: owner, connectionId: connection.id, accessToken: access2, refreshToken: refresh2,
      accessExpiresAt: "2026-07-12T04:00:00Z", now: fixedDate("2026-07-11T20:00:00Z"))
    try expect(
      oldRefs.allSatisfy { (try? services.secrets.getSecretValue($0)) == nil }
        && Set(connection.secretReferenceIds).isDisjoint(with: Set(oldRefs))
        && connection.requiredScopes == scopes
        && connection.health.diagnostics["userId"] == .string(userId)
        && connection.health.diagnostics["accountId"] == .string(accountId)
        && connection.health.diagnostics["baseURI"] == .string("https://na3.docusign.net")
        && connection.health.diagnostics["accessTokenLifetimeSeconds"] == .number(28800)
        && connection.health.diagnostics["refreshTokenLifetimeDays"] == .number(30)
        && connection.health.diagnostics["extendedRefreshLifetimeRenewedOnUse"] == .bool(true)
        && connection.health.diagnostics["exactResourcePollingMinimumSeconds"] == .number(900)
        && connection.callbackURL?.contains("localhost") != true,
      "Docusign exact-user/account/token lifecycle contract failed")
    let install = try services.marketplaceInstalls.createInstall(
      context: owner,
      request: installRequest(
        id: "minreq-docusign", workspaceId: workspace.id, app: app, connectionId: connection.id,
        agent: agent, roleId: app.roleManifest.primaryRole, selectedCapabilities: app.capabilities,
        riskAcknowledged: true))
    _ = try services.providerActionPolicies.compilePolicyMap(
      context: owner, appIdOrSlug: app.id, preset: .approvalRequired, connectionId: connection.id,
      installId: install.id, agentId: agent.id)
    let surface = try services.providerWrapperTools.compileSurface(
      context: owner, appIdOrSlug: app.id, installId: install.id, agentId: agent.id)
    try expect(
      surface.tools.count == 3 && surface.diagnostics.blockedActionCount >= 5
        && surface.tools.allSatisfy(\.requiresApproval)
        && !surface.diagnostics.rawProviderToolExposure, "Docusign wrapper budget mismatch")
    let definitions = try services.data.listMarketplaceProviderActionDefinitions(
      workspaceId: workspace.id, appId: app.id)
    let recent = try unwrap(
      definitions.first { $0.actionKey == "docusign_envelope_list_recent" },
      "missing recent Envelope list")
    let actionRequired = try unwrap(
      definitions.first { $0.actionKey == "docusign_envelope_list_action_required" },
      "missing action-required Envelope list")
    let get = try unwrap(
      definitions.first { $0.actionKey == "docusign_envelope_get" }, "missing exact Envelope get")
    let http = StubHTTP()
    let live = LiveDocusignProviderActionClient(
      data: services.data, secrets: services.secrets, httpClient: http,
      now: { fixedDate("2026-07-11T12:00:00Z") })
    let audit = ProviderExecutionAuditIdentity(
      workspaceId: workspace.id, actorId: owner.actorId, actorRole: "owner", agentId: agent.id,
      appId: app.id, appSlug: app.slug, connectionId: connection.id, installId: install.id,
      approvalId: nil, dispatchId: "docusign-live", threadId: "docusign-thread", source: "test",
      redactionStatus: "private-envelope-state-excluded")
    let recentResult = try live.executeDocusignAction(
      request: MarketplaceProviderActionAdapterRequest(
        context: owner, app: app, definition: recent, permission: .approvalRequired, payload: [:],
        approvalReference: nil, auditIdentity: audit, idempotencyKey: "docusign-recent"))
    let recentText = String(describing: recentResult.result)
    let recentQuery =
      URLComponents(url: http.requests.last!.url, resolvingAgainstBaseURL: false)?.queryItems ?? []
    try expect(
      http.requests.last?.url.path == "/restapi/v2.1/accounts/\(accountId)/envelopes"
        && recentQuery == [
          URLQueryItem(name: "from_date", value: "2026-06-27T12:00:00Z"),
          URLQueryItem(name: "count", value: "25"),
          URLQueryItem(name: "order_by", value: "last_modified"),
          URLQueryItem(name: "order", value: "desc"),
        ] && http.requests.last?.headers["Authorization"] == "Bearer " + access2
        && recentText.contains("Relay agreement") && recentText.contains("LastModifiedDateTime")
        && !recentText.contains("PRIVATE") && !recentText.contains("private@example.com"),
      "Docusign recent Envelope request/privacy contract failed")
    _ = try live.executeDocusignAction(
      request: MarketplaceProviderActionAdapterRequest(
        context: owner, app: app, definition: actionRequired, permission: .approvalRequired,
        payload: [:], approvalReference: nil, auditIdentity: audit,
        idempotencyKey: "docusign-action-required"))
    let requiredQuery =
      URLComponents(url: http.requests.last!.url, resolvingAgainstBaseURL: false)?.queryItems ?? []
    try expect(
      requiredQuery.last == URLQueryItem(name: "folder_ids", value: "awaiting_my_signature")
        && !requiredQuery.contains(where: { $0.name == "include" || $0.name == "start_position" }),
      "Docusign action-required fixed query contract failed")
    _ = try live.executeDocusignAction(
      request: MarketplaceProviderActionAdapterRequest(
        context: owner, app: app, definition: get, permission: .approvalRequired,
        payload: ["envelopeId": .string(accountId)], approvalReference: nil, auditIdentity: audit,
        idempotencyKey: "docusign-get"))
    try expect(
      http.requests.last?.url.absoluteString
        == "https://na3.docusign.net/restapi/v2.1/accounts/\(accountId)/envelopes/\(accountId)",
      "Docusign exact Envelope request mismatch")
    do {
      _ = try live.executeDocusignAction(
        request: MarketplaceProviderActionAdapterRequest(
          context: owner, app: app, definition: get, permission: .approvalRequired,
          payload: ["envelopeId": .string(accountId)], approvalReference: nil, auditIdentity: audit,
          idempotencyKey: "docusign-repeat"))
      throw ServiceTestFailure(
        "Docusign polling guard did not reject a repeated exact Envelope read")
    } catch let failure as MarketplaceProviderActionAdapterFailure {
      try expect(
        failure.code == "docusign_polling_guard",
        "Docusign repeated exact read should fail through polling guard")
    }
    for invalid in [
      "", "bad/id", "11111111-2222-3333-4444-55555555555Z", accountId + "?include=recipients",
    ] {
      do {
        _ = try live.executeDocusignAction(
          request: MarketplaceProviderActionAdapterRequest(
            context: owner, app: app, definition: get, permission: .approvalRequired,
            payload: ["envelopeId": .string(invalid)], approvalReference: nil, auditIdentity: audit,
            idempotencyKey: "docusign-invalid"))
        throw ServiceTestFailure("Unsafe Docusign Envelope ID accepted")
      } catch is ServiceTestFailure {
        throw ServiceTestFailure("Unsafe Docusign Envelope ID accepted")
      } catch {}
    }
    for action in [
      "docusign_mutation", "docusign_private_agreement", "docusign_broader_account",
      "docusign_raw_query", "docusign_bulk_export",
    ] {
      let blocked = try services.providerActionBroker.execute(
        context: owner,
        request: MarketplaceProviderActionBrokerRequest(
          appIdOrSlug: app.id, actionKey: action, payload: [:], installId: install.id,
          idempotencyKey: action))
      try expect(
        blocked.execution.status == .blocked && !blocked.adapterExecuted,
        "Docusign blocked action escaped")
    }
    let persisted = try services.database.all(
      "SELECT connection_json AS value FROM applications_provider_connections UNION ALL SELECT execution_json AS value FROM marketplace_provider_action_executions"
    ).compactMap { sqliteText($0["value"]) }.joined()
    for value in [access1, refresh1, access2, refresh2] {
      try expect(!persisted.contains(value), "Docusign token persisted")
    }
  }

  private static func
    testFilloutProviderIntegrationPreservesGrantBoundRegionalBroadTokenBoundedFormSubmissionMetadataSemanticsEndToEnd()
    throws
  {
    final class StubHTTP: FilloutProviderHTTPClient, @unchecked Sendable {
      var requests: [FilloutProviderHTTPRequest] = []
      func send(_ request: FilloutProviderHTTPRequest) throws -> FilloutProviderHTTPResponse {
        requests.append(request)
        let list =
          #"[{"formId":"form_abc123","name":"Customer intake","PRIVATE":"owner@example.com"}]"#
        let metadata =
          #"{"id":"form_abc123","name":"Customer intake","questions":[{"id":"q1","name":"PRIVATE QUESTION","value":"PRIVATE ANSWER"}],"calculations":[{"name":"PRIVATE CALC"}],"urlParameters":[{"name":"PRIVATE PARAM"}],"scheduling":[{"name":"PRIVATE SCHEDULE"}],"payments":[{"name":"PRIVATE PAYMENT"}],"quiz":{"enabled":true},"design":{"PRIVATE":"value"}}"#
        let submissions =
          #"{"responses":[{"submissionId":"sub_987654","submissionTime":"2026-07-11T09:00:00Z","lastUpdatedAt":"2026-07-11T09:01:00Z","questions":[{"name":"PRIVATE QUESTION","value":"PRIVATE ANSWER"}],"login":{"email":"private@example.com"},"payments":[{"value":{"totalAmount":999,"email":"private@example.com"}}],"editLink":"PRIVATE-LINK"}],"totalResponses":1,"pageCount":1}"#
        let body =
          request.url.path.hasSuffix("/submissions")
          ? submissions : request.url.path == "/v1/api/forms" ? list : metadata
        return FilloutProviderHTTPResponse(statusCode: 200, body: Data(body.utf8))
      }
    }
    let root = FileManager.default.temporaryDirectory.appendingPathComponent(
      "RelayConsoleFilloutProviderTests/" + UUID().uuidString, isDirectory: true)
    let token = "fillout-access-token-private"
    let services = try makeServices(
      root: root,
      providerActionAdapter: RoutingMarketplaceProviderActionAdapter(
        filloutAdapter: FilloutProviderActionAdapter(client: FakeFilloutProviderActionClient())))
    let workspace = try unwrap(services.data.getAppState().activeWorkspace, "missing workspace")
    let owner = context(roles: [.owner], workspaceId: workspace.id, correlationId: "fillout-owner")
    let agent = try createServiceAgent(services: services, workspaceId: workspace.id)
    var app = marketplaceApp(
      workspaceId: workspace.id, slug: "fillout", name: "Fillout", summary: "Fillout fixture",
      category: "Forms & Surveys", riskLevel: .high, connectionState: .none,
      installState: .notInstalled)
    app.readOnly = true
    app.runtimeSupport = [.hermes, .openclaw]
    _ = try services.applications.saveCatalogApps(context: owner, apps: [app])
    let catalog = try services.applications.catalogSnapshot(context: owner, selectedAppId: app.slug)
    try expect(catalog.selectedApp?.slug == "fillout", "Fillout should be retained")
    app = try unwrap(catalog.selectedApp, "Fillout should use the canonical catalog app")
    _ = try services.applications.saveCatalogApps(context: owner, apps: [app])
    app = try canonicalMarketplaceApp(services: services, context: owner, app: app)
    for invalid in [
      ("https://evil.example", ProviderConnectionService.filloutOAuthPermissions),
      ("https://api.fillout.com", ["forms:read"]),
    ] {
      do {
        _ = try services.providerConnections.saveFilloutRelayOwnedOAuthConnection(
          context: owner, appIdOrSlug: app.id, accessToken: token, baseURL: invalid.0,
          authorizationLabel: nil, grantedScopes: invalid.1)
        throw ServiceTestFailure("Unsafe Fillout origin/scope accepted")
      } catch is ServiceTestFailure {
        throw ServiceTestFailure("Unsafe Fillout origin/scope accepted")
      } catch {}
    }
    let connection = try services.providerConnections.saveFilloutRelayOwnedOAuthConnection(
      context: owner, appIdOrSlug: app.id, accessToken: token,
      baseURL: "https://eu-api.fillout.com/", authorizationLabel: "Relay Forms",
      now: fixedDate("2026-07-11T12:00:00Z"))
    try expect(
      connection.secretReferenceIds.count == 1 && connection.grantedScopes.isEmpty
        && connection.health.diagnostics["baseURL"] == .string("https://eu-api.fillout.com")
        && connection.health.diagnostics["oauthScopesDocumented"] == .bool(false)
        && connection.health.diagnostics["accessTokenExpiryDocumented"] == .bool(false)
        && connection.health.diagnostics["refreshTokenDocumented"] == .bool(false)
        && connection.health.diagnostics["identityEndpointDocumented"] == .bool(false)
        && connection.health.diagnostics["broadAuthorizationConfinedLocally"] == .bool(true)
        && connection.health.diagnostics["rateLimitRequestsPerSecond"] == .number(5)
        && connection.callbackURL?.contains("localhost") != true,
      "Fillout OAuth grant contract failed")
    let install = try services.marketplaceInstalls.createInstall(
      context: owner,
      request: installRequest(
        id: "minreq-fillout", workspaceId: workspace.id, app: app, connectionId: connection.id,
        agent: agent, roleId: app.roleManifest.primaryRole, selectedCapabilities: app.capabilities,
        riskAcknowledged: true))
    _ = try services.providerActionPolicies.compilePolicyMap(
      context: owner, appIdOrSlug: app.id, preset: .approvalRequired, connectionId: connection.id,
      installId: install.id, agentId: agent.id)
    let surface = try services.providerWrapperTools.compileSurface(
      context: owner, appIdOrSlug: app.id, installId: install.id, agentId: agent.id)
    try expect(
      surface.tools.count == 3 && surface.diagnostics.blockedActionCount >= 5
        && surface.tools.allSatisfy(\.requiresApproval), "Fillout wrapper budget mismatch")
    let mounted = try unwrap(
      try services.marketplaceRuntimeMounts.snapshot(context: owner, agent: agent).apps.first,
      "missing Fillout runtime app")
    let tool = try unwrap(
      mounted.tools.first { $0.displayName == "List Fillout Forms" },
      "missing Fillout Form list tool")
    let pending = try services.marketplaceRuntimeToolBridge.execute(
      toolName: tool.toolName, payload: [:],
      runtime: MarketplaceRuntimeToolExecutionContext(
        agentId: agent.id, workspaceId: workspace.id, runtimeType: agent.binding.runtimeType,
        dispatchId: "fillout-runtime", threadId: "fillout-thread",
        runtimeSessionId: "fillout-session", correlationId: "fillout-runtime"))
    try expect(
      mounted.tools.count == 3 && mounted.instructions.count <= 1200
        && mounted.instructions.contains("Submission lifecycle")
        && pending["executionStatus"]
          == .string(ProviderActionExecutionStatus.pendingApproval.rawValue),
      "Fillout runtime wrapper contract failed")
    let definitions = try services.data.listMarketplaceProviderActionDefinitions(
      workspaceId: workspace.id, appId: app.id)
    let formList = try unwrap(
      definitions.first { $0.actionKey == "fillout_form_list" }, "missing Form list")
    let formGet = try unwrap(
      definitions.first { $0.actionKey == "fillout_form_get_metadata_summary" }, "missing Form get")
    let submissionList = try unwrap(
      definitions.first { $0.actionKey == "fillout_submission_list_recent" },
      "missing Submission list")
    let http = StubHTTP()
    let live = LiveFilloutProviderActionClient(
      data: services.data, secrets: services.secrets, httpClient: http)
    let audit = ProviderExecutionAuditIdentity(
      workspaceId: workspace.id, actorId: owner.actorId, actorRole: "owner", agentId: agent.id,
      appId: app.id, appSlug: app.slug, connectionId: connection.id, installId: install.id,
      approvalId: nil, dispatchId: "fillout-live", threadId: "fillout-thread", source: "test",
      redactionStatus: "submission-content-excluded")
    func request(_ definition: MarketplaceProviderActionDefinition, _ payload: JSONRecord = [:])
      -> MarketplaceProviderActionAdapterRequest
    {
      MarketplaceProviderActionAdapterRequest(
        context: owner, app: app, definition: definition, permission: .approvalRequired,
        payload: payload, approvalReference: nil, auditIdentity: audit,
        idempotencyKey: definition.actionKey)
    }
    let forms = try live.executeFilloutAction(request: request(formList))
    try expect(
      http.requests.last?.url.absoluteString == "https://eu-api.fillout.com/v1/api/forms"
        && http.requests.last?.headers["Authorization"] == "Bearer " + token
        && String(describing: forms.result).contains("Customer intake")
        && !String(describing: forms.result).contains("PRIVATE"),
      "Fillout Form list/privacy contract failed")
    let metadata = try live.executeFilloutAction(
      request: request(formGet, ["formId": .string("form_abc123")]))
    let metadataText = String(describing: metadata.result)
    try expect(
      http.requests.last?.url.absoluteString
        == "https://eu-api.fillout.com/v1/api/forms/form_abc123"
        && metadataText.contains("QuestionCount") && metadataText.contains("QuizEnabled")
        && !metadataText.contains("PRIVATE"), "Fillout Form metadata/privacy contract failed")
    let submissions = try live.executeFilloutAction(
      request: request(submissionList, ["formId": .string("form_abc123")]))
    let submissionText = String(describing: submissions.result)
    try expect(
      http.requests.last?.url.absoluteString
        == "https://eu-api.fillout.com/v1/api/forms/form_abc123/submissions?limit=25&offset=0&status=finished&includeEditLink=false&includePreview=false&sort=desc"
        && submissionText.contains("sub_987654") && !submissionText.contains("PRIVATE")
        && !submissionText.contains("private@example.com") && !submissionText.contains("999"),
      "Fillout Submission lifecycle/privacy contract failed")
    for invalid in ["", "bad/id", String(repeating: "a", count: 129)] {
      do {
        _ = try live.executeFilloutAction(request: request(formGet, ["formId": .string(invalid)]))
        throw ServiceTestFailure("Unsafe Fillout Form ID accepted")
      } catch is ServiceTestFailure {
        throw ServiceTestFailure("Unsafe Fillout Form ID accepted")
      } catch {}
    }
    for action in [
      "fillout_submission_content", "fillout_submission_mutation", "fillout_webhook_mutation",
      "fillout_raw_query", "fillout_bulk_export",
    ] {
      let blocked = try services.providerActionBroker.execute(
        context: owner,
        request: MarketplaceProviderActionBrokerRequest(
          appIdOrSlug: app.id, actionKey: action, payload: [:], installId: install.id,
          idempotencyKey: action))
      try expect(
        blocked.execution.status == .blocked && !blocked.adapterExecuted,
        "Fillout blocked action escaped")
    }
    let persisted = try services.database.all(
      "SELECT connection_json AS value FROM applications_provider_connections UNION ALL SELECT execution_json AS value FROM marketplace_provider_action_executions"
    ).compactMap { sqliteText($0["value"]) }.joined()
    try expect(!persisted.contains(token), "Fillout token persisted")
  }

  private static func
    testMailchimpProviderIntegrationPreservesExactAccountDataCenterBroadTokenBoundedAudienceCampaignMetadataSemanticsEndToEnd()
    throws
  {
