        requests.append(request)
        let account =
          #"{"account_id":"acct_123","account_name":"Relay Marketing","role":"admin","member_since":"2024-01-01T00:00:00Z","email":"PRIVATE@example.com","username":"PRIVATE","first_name":"PRIVATE"}"#
        let audiences =
          #"{"lists":[{"id":"list_123","name":"Product updates","date_created":"2025-01-01T00:00:00Z","stats":{"member_count":250,"unsubscribe_count":4},"contact":{"company":"PRIVATE"},"members":[{"email_address":"PRIVATE@example.com"}]}],"total_items":1}"#
        let campaigns =
          #"{"campaigns":[{"id":"cmp_123","type":"regular","status":"sent","create_time":"2026-07-10T08:00:00Z","send_time":"2026-07-11T09:00:00Z","settings":{"subject_line":"PRIVATE SUBJECT"},"recipients":{"list_name":"PRIVATE"},"report_summary":{"clicks":999}}],"total_items":1}"#
