    let campaigns = try unwrap(
      defs.first { $0.actionKey == "campaign_monitor_campaign_list_recent_sent" },
      "missing campaigns")
    let summary = try unwrap(
      defs.first { $0.actionKey == "campaign_monitor_campaign_summary_get" }, "missing summary")
    let http = StubHTTP()
    let live = LiveCampaignMonitorProviderActionClient(
      data: services.data, secrets: services.secrets, httpClient: http)
    let audit = ProviderExecutionAuditIdentity(
