    try expect(c.contains("Relay Client") && !c.contains("PRIVATE"), "Client privacy failed")
    let l = String(
      describing: try live.executeCampaignMonitorAction(request: request(campaigns)).result)
    let listURL = http.requests.last?.url.absoluteString ?? ""
    try expect(
      listURL.contains("page=1") && listURL.contains("pagesize=20") && l.contains("bbbbbbbb")
        && !l.contains("PRIVATE") && !l.contains("999"), "Campaign list privacy failed")
    let s = String(
      describing: try live.executeCampaignMonitorAction(
        request: request(summary, ["campaignId": .string("bbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbb")])
      ).result)
    try expect(
      s.contains("1000") && s.contains("345") && !s.contains("PRIVATE"),
      "Campaign summary privacy failed")
    for action in [
      "campaign_monitor_subscriber_private", "campaign_monitor_campaign_content",
      "campaign_monitor_marketing_mutation", "campaign_monitor_raw_query",
      "campaign_monitor_bulk_export",
    ] {
      let blocked = try services.providerActionBroker.execute(
        context: owner,
        request: MarketplaceProviderActionBrokerRequest(
          appIdOrSlug: app.id, actionKey: action, payload: [:], installId: install.id,
          idempotencyKey: action))
      try expect(
        blocked.execution.status == .blocked && !blocked.adapterExecuted,
        "Campaign Monitor block escaped")
    }
    let persisted = try services.database.all(
      "SELECT connection_json AS value FROM applications_provider_connections UNION ALL SELECT execution_json AS value FROM marketplace_provider_action_executions"
    ).compactMap { sqliteText($0["value"]) }.joined()
    try expect(
      !persisted.contains(access) && !persisted.contains(refresh) && !persisted.contains(nextAccess)
        && !persisted.contains(nextRefresh), "Campaign Monitor token persisted")
  }

