  private static func
    testContentfulProviderIntegrationPreservesBoundedLocalizedCompleteFieldVersionedDraftAndPublishSemanticsEndToEnd()
    throws
  {
    final class StubHTTP: ContentfulProviderHTTPClient, @unchecked Sendable {
      var requests: [ContentfulProviderHTTPRequest] = []
      func send(_ request: ContentfulProviderHTTPRequest) throws -> ContentfulProviderHTTPResponse {
        requests.append(request)
        if request.url.path.hasSuffix("/content_types/article") {
          return ContentfulProviderHTTPResponse(
            statusCode: 200,
            body:
              #"{"sys":{"id":"article","version":4},"name":"Article","displayField":"title","description":"Editorial article","fields":[{"id":"title","name":"Title","type":"Symbol","required":true,"localized":true,"disabled":false,"omitted":false},{"id":"body","name":"Body","type":"Text","required":true,"localized":true,"disabled":false,"omitted":false}]}"#
              .data(using: .utf8)!)
        }
        let published = request.url.path.hasSuffix("/published")
        return ContentfulProviderHTTPResponse(
          statusCode: 200,
          body: (#"{"sys":{"id":"entry-live","version":8,"space":{"sys":{"id":"space1"}},"environment":{"sys":{"id":"master"}},"contentType":{"sys":{"id":"article"}}"#
            + (published ? #", "publishedVersion":7"# : "")
            + #"},"fields":{"title":{"en-US":"Relay Launch"},"body":{"en-US":"Complete localized body"}}}"#)
            .data(using: .utf8)!)
      }
    }
    let root = FileManager.default.temporaryDirectory.appendingPathComponent(
      "RelayConsoleContentfulProviderTests/" + UUID().uuidString, isDirectory: true)
    let access = "contentful-sensitive-access"
    let replacement = "contentful-reauthorized-access"
    let services = try makeServices(
      root: root,
      providerActionAdapter: RoutingMarketplaceProviderActionAdapter(
        contentfulAdapter: ContentfulProviderActionAdapter(
          client: FakeContentfulProviderActionClient())))
    let workspace = try unwrap(services.data.getAppState().activeWorkspace, "missing workspace")
    let owner = context(
      roles: [.owner], workspaceId: workspace.id, correlationId: "contentful-owner")
    let agent = try createServiceAgent(services: services, workspaceId: workspace.id)
    var app = marketplaceApp(
      workspaceId: workspace.id, slug: "contentful", name: "Contentful",
      summary: "Contentful fixture", category: "Content Management", riskLevel: .high,
      connectionState: .none, installState: .notInstalled)
    app.authType = "OAuth 2.0 confidential application"
    app.connectionType = "Relay-owned Contentful OAuth via Railway"
    app.readOnly = false
    app.runtimeSupport = [.hermes, .openclaw]
    _ = try services.applications.saveCatalogApps(context: owner, apps: [app])
    let catalog = try services.applications.catalogSnapshot(context: owner, selectedAppId: app.slug)
    try expect(catalog.selectedApp?.slug == "contentful", "Contentful should be retained")
    app = try unwrap(catalog.selectedApp, "Contentful should use the canonical catalog app")
    var connection = try services.providerConnections.saveContentfulRelayOwnedOAuthConnection(
      context: owner, appIdOrSlug: app.id, accessToken: access, authorizedSpaceIds: ["space1"],
      authorizedSpaceNames: ["Relay Editorial"], authorizedEnvironmentIds: ["master"],
      organizationNames: ["Relay"], cmaHost: "https://api.eu.contentful.com", accountLabel: nil,
      now: fixedDate("2026-01-01T00:00:00Z"))
    try expect(
      connection.status == .connected && connection.requiredScopes == ["content_management_manage"]
        && connection.secretReferenceIds.count == 1
        && connection.health.diagnostics["refreshSupported"] == .bool(false)
        && connection.health.diagnostics["coarseManageScopeConstrained"] == .bool(true)
        && connection.health.diagnostics["completeFieldsRequired"] == .bool(true)
        && connection.health.diagnostics["versionHeaderRequired"] == .bool(true)
        && connection.health.diagnostics["cmaHost"] == .string("https://api.eu.contentful.com")
        && connection.callbackURL?.contains("localhost") != true,
      "Contentful connection should preserve one non-refreshable token, exact scope, Railway callback, regional host, and bounded resource contract"
    )
    let oldRef = try unwrap(
      connection.secretReferenceIds.first, "missing Contentful access reference")
    connection = try services.providerConnections.saveContentfulRelayOwnedOAuthConnection(
      context: owner, appIdOrSlug: app.id, accessToken: replacement, authorizedSpaceIds: ["space1"],
      authorizedSpaceNames: ["Relay Editorial"], authorizedEnvironmentIds: ["master"],
      cmaHost: "https://api.eu.contentful.com", accountLabel: nil,
      now: fixedDate("2026-01-01T00:10:00Z"))
    try expect(
      (try? services.secrets.getSecretValue(oldRef)) == nil
        && connection.secretReferenceIds.count == 1
        && connection.secretReferenceIds.first != oldRef,
      "Contentful reauthorization should replace its single access-token reference")
    let install = try services.marketplaceInstalls.createInstall(
      context: owner,
      request: installRequest(
        id: "minreq-contentful", workspaceId: workspace.id, app: app, connectionId: connection.id,
        agent: agent, roleId: app.roleManifest.primaryRole, selectedCapabilities: app.capabilities,
        riskAcknowledged: true), now: fixedDate("2026-01-01T00:30:01Z"))
    _ = try services.providerActionPolicies.compilePolicyMap(
      context: owner, appIdOrSlug: app.id, preset: .approvalRequired, connectionId: connection.id,
      installId: install.id, agentId: agent.id, now: fixedDate("2026-01-01T00:30:02Z"))
    let surface = try services.providerWrapperTools.compileSurface(
      context: owner, appIdOrSlug: app.id, installId: install.id, agentId: agent.id,
      now: fixedDate("2026-01-01T00:30:03Z"))
    try expect(
      surface.tools.count == 11 && surface.diagnostics.blockedActionCount >= 3
        && !surface.diagnostics.rawProviderToolExposure,
      "Contentful should expose eleven bounded wrappers and suppress raw/destructive surfaces")
    let mounted = try unwrap(
      try services.marketplaceRuntimeMounts.snapshot(
        context: owner, agent: agent, now: fixedDate("2026-01-01T00:30:04Z")
      ).apps.first, "missing Contentful runtime app")
    let schemaTool = try unwrap(
      mounted.tools.first { $0.displayName == "Get Contentful content type" },
      "missing Contentful schema tool")
    let fake = try services.marketplaceRuntimeToolBridge.execute(
      toolName: schemaTool.toolName,
      payload: [
        "spaceId": .string("space1"), "environmentId": .string("master"),
        "contentTypeId": .string("article"),
      ],
      runtime: MarketplaceRuntimeToolExecutionContext(
        agentId: agent.id, workspaceId: workspace.id, runtimeType: agent.binding.runtimeType,
        dispatchId: "contentful-schema", threadId: "contentful-thread",
        runtimeSessionId: "contentful-session", correlationId: "contentful-schema"),
