      "Contentful schema should preserve useful typed localized-field semantics")
    let definitions = try services.data.listMarketplaceProviderActionDefinitions(
      workspaceId: workspace.id, appId: app.id)
    let schemaDefinition = try unwrap(
      definitions.first { $0.actionKey == "contentful_content_type_get" },
