    let liveSchema = try live.executeContentfulAction(
      request: MarketplaceProviderActionAdapterRequest(
        context: owner, app: app, definition: schemaDefinition, permission: .allowed,
        payload: [
          "spaceId": .string("space1"), "environmentId": .string("master"),
          "contentTypeId": .string("article"),
        ], approvalReference: nil, auditIdentity: audit, idempotencyKey: "contentful-live-schema"))
    try expect(
      http.requests.last?.method == "GET" && http.requests.last?.url.host == "api.eu.contentful.com"
        && http.requests.last?.url.path
          == "/spaces/space1/environments/master/content_types/article"
        && http.requests.last?.headers["Authorization"] == "Bearer " + replacement
        && String(describing: liveSchema.result["contentType"] ?? .null).contains(
          "Editorial article"),
      "Contentful live schema should use the allowed regional CMA route and bearer token")
    let fields: JSONValue = .object([
      "title": .object(["en-US": .string("Relay Launch")]),
      "body": .object(["en-US": .string("Complete localized body")]),
    ])
    let updatePayload: JSONRecord = [
      "spaceId": .string("space1"), "environmentId": .string("master"),
      "entryId": .string("entry-live"), "expectedVersion": .number(7), "fields": fields,
    ]
    _ = try live.executeContentfulAction(
      request: MarketplaceProviderActionAdapterRequest(
        context: owner, app: app, definition: updateDefinition, permission: .allowed,
        payload: updatePayload, approvalReference: nil, auditIdentity: audit,
        idempotencyKey: "contentful-live-update"))
    let liveUpdate = try unwrap(http.requests.last, "missing Contentful update request")
    let updateBody = String(data: liveUpdate.body ?? Data(), encoding: .utf8) ?? ""
    try expect(
      liveUpdate.method == "PUT"
        && liveUpdate.url.path == "/spaces/space1/environments/master/entries/entry-live"
        && liveUpdate.headers["X-Contentful-Version"] == "7"
        && updateBody.contains("Complete localized body") && updateBody.contains("title"),
      "Contentful update should send exact version and complete localized fields")
    _ = try live.executeContentfulAction(
      request: MarketplaceProviderActionAdapterRequest(
        context: owner, app: app, definition: publishDefinition, permission: .allowed,
        payload: [
          "spaceId": .string("space1"), "environmentId": .string("master"),
          "entryId": .string("entry-live"), "expectedVersion": .number(8),
        ], approvalReference: nil, auditIdentity: audit, idempotencyKey: "contentful-live-publish"))
    try expect(
      http.requests.last?.method == "PUT"
        && http.requests.last?.url.path
          == "/spaces/space1/environments/master/entries/entry-live/published"
        && http.requests.last?.headers["X-Contentful-Version"] == "8",
      "Contentful publication should remain a separate exact-version operation")
    do {
      _ = try live.executeContentfulAction(
        request: MarketplaceProviderActionAdapterRequest(
          context: owner, app: app, definition: schemaDefinition, permission: .allowed,
          payload: [
            "spaceId": .string("space2"), "environmentId": .string("master"),
            "contentTypeId": .string("article"),
          ], approvalReference: nil, auditIdentity: audit,
          idempotencyKey: "contentful-unauthorized-space"))
      throw ServiceTestFailure("Unauthorized Contentful space was accepted")
    } catch let failure as MarketplaceProviderActionAdapterFailure {
      try expect(
        failure.code == "contentful_space_not_authorized",
        "Contentful should reject unauthorized spaces")
    }
    do {
      _ = try live.executeContentfulAction(
        request: MarketplaceProviderActionAdapterRequest(
          context: owner, app: app, definition: schemaDefinition, permission: .allowed,
          payload: [
            "spaceId": .string("space1"), "environmentId": .string("staging"),
            "contentTypeId": .string("article"),
          ], approvalReference: nil, auditIdentity: audit,
          idempotencyKey: "contentful-unauthorized-environment"))
      throw ServiceTestFailure("Unauthorized Contentful environment was accepted")
    } catch let failure as MarketplaceProviderActionAdapterFailure {
      try expect(
        failure.code == "contentful_environment_not_authorized",
        "Contentful should reject unauthorized environments")
    }
    let updateTool = try unwrap(
      mounted.tools.first { $0.displayName == "Update Contentful draft entry" },
      "missing Contentful update tool")
    let pending = try services.marketplaceRuntimeToolBridge.execute(
      toolName: updateTool.toolName, payload: updatePayload,
      runtime: MarketplaceRuntimeToolExecutionContext(
        agentId: agent.id, workspaceId: workspace.id, runtimeType: agent.binding.runtimeType,
        dispatchId: "contentful-pending", threadId: "contentful-thread",
        runtimeSessionId: "contentful-session", correlationId: "contentful-pending"),
      now: fixedDate("2026-01-01T00:30:06Z"))
    try expect(
      pending["executionStatus"] == .string(ProviderActionExecutionStatus.pendingApproval.rawValue)
        && pending["adapterExecuted"] == .bool(false),
      "Contentful draft update should await approval")
    let brokerPending = try services.providerActionBroker.execute(
      context: owner,
      request: MarketplaceProviderActionBrokerRequest(
        appIdOrSlug: app.id, actionKey: "contentful_entry_update_draft", payload: updatePayload,
        installId: install.id, idempotencyKey: "contentful-approved-pending"),
      now: fixedDate("2026-01-01T00:30:07Z"))
    let approval = try unwrap(brokerPending.approval, "missing Contentful approval")
    let approved = try services.providerActionApprovals.approve(
      context: owner, approvalId: approval.id, approvedPayload: updatePayload,
      now: fixedDate("2026-01-01T00:30:08Z"))
    let approvedExecution = try services.providerActionBroker.execute(
      context: owner,
      request: MarketplaceProviderActionBrokerRequest(
        appIdOrSlug: app.id, actionKey: "contentful_entry_update_draft", payload: updatePayload,
        installId: install.id, approvalId: approved.id,
        idempotencyKey: "contentful-approved-execution"), now: fixedDate("2026-01-01T00:30:09Z"))
    try expect(
      approvedExecution.adapterExecuted && approvedExecution.execution.status == .succeeded,
      "Approved Contentful update should execute: \(approvedExecution.execution.status.rawValue) / \(String(describing: approvedExecution.execution.providerError))"
    )
    _ = try services.providerActionPolicies.compilePolicyMap(
      context: owner, appIdOrSlug: app.id, preset: .allowDirectWrites, acknowledgeDangerousPolicy: true, connectionId: connection.id,
      installId: install.id, agentId: agent.id, now: fixedDate("2026-01-01T00:30:10Z"))
    let directUpdate = try services.providerActionBroker.execute(
      context: owner,
      request: MarketplaceProviderActionBrokerRequest(
        appIdOrSlug: app.id, actionKey: "contentful_entry_update_draft", payload: updatePayload,
        installId: install.id, idempotencyKey: "contentful-direct-update"),
      now: fixedDate("2026-01-01T00:30:11Z"))
    let directPublish = try services.providerActionBroker.execute(
      context: owner,
      request: MarketplaceProviderActionBrokerRequest(
        appIdOrSlug: app.id, actionKey: "contentful_entry_publish",
        payload: [
          "spaceId": .string("space1"), "environmentId": .string("master"),
          "entryId": .string("entry-live"), "expectedVersion": .number(8),
        ], installId: install.id, idempotencyKey: "contentful-direct-publish"),
      now: fixedDate("2026-01-01T00:30:12Z"))
    try expect(
      directUpdate.adapterExecuted && directUpdate.execution.status == .succeeded
        && directPublish.adapterExecuted && directPublish.execution.status == .succeeded,
      "Direct rights should preserve distinct Contentful draft-update and explicit-publish operations"
    )
    for action in [
      "contentful_entry_destructive", "contentful_admin_mutation", "contentful_raw_api_call",
    ] {
      let blocked = try services.providerActionBroker.execute(
        context: owner,
        request: MarketplaceProviderActionBrokerRequest(
          appIdOrSlug: app.id, actionKey: action, payload: [:], installId: install.id,
          idempotencyKey: action), now: fixedDate("2026-01-01T00:30:13Z"))
      try expect(
        !blocked.adapterExecuted && blocked.execution.status == .blocked,
        "Contentful blocked action escaped policy: " + action)
    }
    let persisted = try services.database.all(
      "SELECT connection_json AS value FROM applications_provider_connections UNION ALL SELECT execution_json AS value FROM marketplace_provider_action_executions"
    ).compactMap { sqliteText($0["value"]) }.joined(separator: "\n")
    for secret in [access, replacement] {
      try expect(!persisted.contains(secret), "Contentful persistence leaked a token")
    }
  }

  private static func
