    throws
  {
    final class StubHTTP: WebflowProviderHTTPClient, @unchecked Sendable {
      var requests: [WebflowProviderHTTPRequest] = []
      func send(_ request: WebflowProviderHTTPRequest) throws -> WebflowProviderHTTPResponse {
        requests.append(request)
        if request.method == "PATCH" {
          return WebflowProviderHTTPResponse(
            statusCode: 200,
            body:
              #"{"id":"item-live","cmsLocaleId":"locale1","isArchived":false,"isDraft":true,"fieldData":{"name":"Relay Launch","summary":"Reviewed staged change"}}"#
              .data(using: .utf8)!)
        }
        if request.method == "POST" {
          return WebflowProviderHTTPResponse(
            statusCode: 200,
            body: #"{"publishedItemIds":["item-live"],"errors":[]}"#.data(using: .utf8)!)
        }
        if request.url.path.hasSuffix("/items") {
          return WebflowProviderHTTPResponse(
            statusCode: 200,
            body:
              #"{"items":[{"id":"item-live","cmsLocaleId":"locale1","isArchived":false,"isDraft":true,"fieldData":{"name":"Relay Launch","summary":"Useful staged fieldData"}}],"pagination":{"limit":10,"offset":5,"total":1}}"#
              .data(using: .utf8)!)
        }
        return WebflowProviderHTTPResponse(
          statusCode: 200,
          body:
            #"{"id":"collection-live","displayName":"Launch Articles","singularName":"Launch Article","slug":"launch-article","fields":[{"id":"field1","type":"PlainText","displayName":"Summary","slug":"summary","isRequired":false,"isEditable":true}]}"#
            .data(using: .utf8)!)
      }
    }
    let root = FileManager.default.temporaryDirectory.appendingPathComponent(
      "RelayConsoleWebflowProviderTests/" + UUID().uuidString, isDirectory: true)
    let access = "webflow-sensitive-access"
    let replacement = "webflow-reauthorized-access"
