        && connection.secretReferenceIds.count == 1 && connection.credentialRequirements.count == 1
        && connection.health.diagnostics["refreshSupported"] == .bool(false)
        && connection.health.diagnostics["callbackTransport"] == .string("railway-https-only")
        && connection.callbackURL?.contains("localhost") != true,
      "Webflow connection should retain exact scopes, one non-refreshable token reference, and Railway callback semantics"
    )
    let oldRef = try unwrap(
      connection.secretReferenceIds.first, "missing original access reference")
    connection = try services.providerConnections.saveWebflowRelayOwnedOAuthConnection(
