    try expect(
      surface.tools.count == 9 && surface.diagnostics.blockedActionCount >= 3
        && !surface.diagnostics.rawProviderToolExposure,
      "Webflow should expose nine provider-correct wrappers without raw API")
    let mounted = try unwrap(
      try services.marketplaceRuntimeMounts.snapshot(
        context: owner, agent: agent, now: fixedDate("2026-01-01T00:30:04Z")
      ).apps.first, "missing Webflow runtime app")
