        && http.requests.first?.url.query?.contains("limit=10") == true
        && http.requests.first?.url.query?.contains("offset=5") == true
        && http.requests.first?.headers["Authorization"] == "Bearer " + replacement
        && String(describing: liveItems.result["items"] ?? .null).contains(
          "Useful staged fieldData"),
      "Webflow live item list should use the official bounded offset route and useful fieldData")
    let updatePayload: JSONRecord = [
      "collectionId": .string("collection1"), "itemId": .string("item1"),
      "fieldData": .object(["summary": .string("Reviewed staged change")]),
    ]
    let updateTool = try unwrap(
