  private static func
    testWordPressComProviderIntegrationPreservesSitePostDraftPublishStaleWriteAndNonRefreshableOAuthSemanticsEndToEnd()
    throws
  {
    final class StubHTTP: WordPressComProviderHTTPClient, @unchecked Sendable {
      var requests: [WordPressComProviderHTTPRequest] = []
      func send(_ request: WordPressComProviderHTTPRequest) throws
        -> WordPressComProviderHTTPResponse
      {
        requests.append(request)
        let post =
          #"{"ID":42,"site_ID":241031857,"author":{"ID":1,"name":"Relay Editor","login":"relay-editor"},"title":"Relay Launch","content":"Useful editable content","excerpt":"Launch summary","URL":"https://relay.example/relay-launch","short_URL":"https://wp.me/example","status":"draft","type":"post","slug":"relay-launch","date":"2026-07-11T00:00:00Z","modified":"2026-07-11T00:00:01Z","categories":{},"tags":{},"discussion":{"comments_open":false,"comment_count":0},"like_count":0}"#
        if request.method == "POST" {
          let published =
            String(data: request.body ?? Data(), encoding: .utf8)?.contains("status=publish")
            == true
          return WordPressComProviderHTTPResponse(
            statusCode: 200,
            body: post.replacingOccurrences(
              of: #""status":"draft""#,
              with: published ? #""status":"publish""# : #""status":"draft""#
            ).data(using: .utf8)!)
        }
        if request.url.path.hasSuffix("/posts") {
          return WordPressComProviderHTTPResponse(
            statusCode: 200, body: ("{\"found\":1,\"posts\":[" + post + "]}").data(using: .utf8)!)
        }
        return WordPressComProviderHTTPResponse(statusCode: 200, body: post.data(using: .utf8)!)
      }
    }
    let root = FileManager.default.temporaryDirectory.appendingPathComponent(
      "RelayConsoleWordPressComProviderTests/" + UUID().uuidString, isDirectory: true)
    let access = "wordpress-com-sensitive-access"
