      ).apps.first, "missing WordPress.com runtime app")
    let postTool = try unwrap(
      mounted.tools.first { $0.displayName == "Get WordPress.com post" },
      "missing WordPress.com post tool")
    let fake = try services.marketplaceRuntimeToolBridge.execute(
      toolName: postTool.toolName,
      payload: ["siteId": .string("241031857"), "postId": .string("42")],
      runtime: MarketplaceRuntimeToolExecutionContext(
        agentId: agent.id, workspaceId: workspace.id, runtimeType: agent.binding.runtimeType,
        dispatchId: "wordpress-com-post", threadId: "wordpress-com-thread",
        runtimeSessionId: "wordpress-com-session", correlationId: "wordpress-com-post"),
      now: fixedDate("2026-01-01T00:30:05Z"))
    let fakeProvider = try unwrap(
      objectValue(fake["providerResult"]), "missing WordPress.com fake result")
    try expect(
      fakeProvider["semanticReadContract"] == .string("wordpress-com-post-get-v1")
        && String(describing: fakeProvider["post"] ?? .null).contains("modified")
        && String(describing: fakeProvider["post"] ?? .null).contains("Relay Launch"),
      "WordPress.com post result should preserve useful editor semantics")
    let definitions = try services.data.listMarketplaceProviderActionDefinitions(
      workspaceId: workspace.id, appId: app.id)
    let listDefinition = try unwrap(
      definitions.first { $0.actionKey == "wordpress_com_post_list" },
      "missing WordPress.com list definition")
    let updateDefinition = try unwrap(
      definitions.first { $0.actionKey == "wordpress_com_post_update_draft" },
      "missing WordPress.com update definition")
    let http = StubHTTP()
    let live = LiveWordPressComProviderActionClient(
      data: services.data, secrets: services.secrets, httpClient: http)
    let audit = ProviderExecutionAuditIdentity(
      workspaceId: workspace.id, actorId: owner.actorId, actorRole: "owner", agentId: agent.id,
      appId: app.id, appSlug: app.slug, connectionId: connection.id, installId: install.id,
      approvalId: nil, dispatchId: "wordpress-com-live", threadId: "wordpress-com-thread",
      source: "wordpress-com-live-test", redactionStatus: "private-state-excluded")
    let livePosts = try live.executeWordPressComAction(
      request: MarketplaceProviderActionAdapterRequest(
        context: owner, app: app, definition: listDefinition, permission: .allowed,
        payload: ["siteId": .string("241031857"), "maxResults": .number(10), "offset": .number(5)],
        approvalReference: nil, auditIdentity: audit, idempotencyKey: "wordpress-com-live"))
    let firstRequest = try unwrap(http.requests.first, "missing WordPress.com list request")
    try expect(
      firstRequest.url.path == "/rest/v1.1/sites/241031857/posts"
        && firstRequest.url.query?.contains("number=10") == true
        && firstRequest.url.query?.contains("offset=5") == true
        && firstRequest.headers["Authorization"] == "Bearer " + replacement
        && livePosts.result["found"] != nil
        && String(describing: livePosts.result["posts"] ?? .null).contains(
          "Useful editable content"),
      "WordPress.com live list mismatch: \(firstRequest.url.absoluteString)")
    var staleRejected = false
    do {
      _ = try live.executeWordPressComAction(
        request: MarketplaceProviderActionAdapterRequest(
          context: owner, app: app, definition: updateDefinition, permission: .autoExecute,
          payload: [
            "siteId": .string("241031857"), "postId": .string("42"),
            "expectedModified": .string("stale"), "title": .string("Changed"),
          ], approvalReference: nil, auditIdentity: audit, idempotencyKey: "wordpress-com-stale"))
    } catch let error as MarketplaceProviderActionAdapterFailure {
      staleRejected = error.code == "wordpress_com_stale_post"
    }
    try expect(
      staleRejected && http.requests.filter { $0.method == "POST" }.isEmpty,
      "WordPress.com stale update must fail before provider mutation")
    let createPayload: JSONRecord = [
      "siteId": .string("241031857"), "title": .string("Reviewed launch"),
      "content": .string("Draft content"),
    ]
    let createTool = try unwrap(
      mounted.tools.first { $0.displayName == "Create WordPress.com draft" },
      "missing WordPress.com create tool")
    let pending = try services.marketplaceRuntimeToolBridge.execute(
      toolName: createTool.toolName, payload: createPayload,
      runtime: MarketplaceRuntimeToolExecutionContext(
        agentId: agent.id, workspaceId: workspace.id, runtimeType: agent.binding.runtimeType,
        dispatchId: "wordpress-com-pending", threadId: "wordpress-com-thread",
        runtimeSessionId: "wordpress-com-session", correlationId: "wordpress-com-pending"),
      now: fixedDate("2026-01-01T00:30:06Z"))
    try expect(
      pending["executionStatus"] == .string(ProviderActionExecutionStatus.pendingApproval.rawValue)
        && pending["adapterExecuted"] == .bool(false),
      "WordPress.com draft creation should await approval")
    let brokerPending = try services.providerActionBroker.execute(
      context: owner,
      request: MarketplaceProviderActionBrokerRequest(
        appIdOrSlug: app.id, actionKey: "wordpress_com_post_create_draft", payload: createPayload,
        installId: install.id, idempotencyKey: "wordpress-com-approved-pending"),
      now: fixedDate("2026-01-01T00:30:07Z"))
    let approval = try unwrap(brokerPending.approval, "missing WordPress.com approval")
    let approved = try services.providerActionApprovals.approve(
      context: owner, approvalId: approval.id, approvedPayload: createPayload,
      now: fixedDate("2026-01-01T00:30:08Z"))
    let approvedExecution = try services.providerActionBroker.execute(
      context: owner,
      request: MarketplaceProviderActionBrokerRequest(
        appIdOrSlug: app.id, actionKey: "wordpress_com_post_create_draft", payload: createPayload,
        installId: install.id, approvalId: approved.id,
        idempotencyKey: "wordpress-com-approved-execution"), now: fixedDate("2026-01-01T00:30:09Z"))
    try expect(
      approvedExecution.adapterExecuted && approvedExecution.execution.status == .succeeded
        && String(describing: approvedExecution.execution.providerResult ?? [:]).contains("draft"),
      "Approved WordPress.com creation should remain draft")
    _ = try services.providerActionPolicies.compilePolicyMap(
      context: owner, appIdOrSlug: app.id, preset: .allowDirectWrites, acknowledgeDangerousPolicy: true, connectionId: connection.id,
      installId: install.id, agentId: agent.id, now: fixedDate("2026-01-01T00:30:10Z"))
    let directUpdate = try services.providerActionBroker.execute(
      context: owner,
      request: MarketplaceProviderActionBrokerRequest(
        appIdOrSlug: app.id, actionKey: "wordpress_com_post_update_draft",
        payload: [
          "siteId": .string("241031857"), "postId": .string("42"),
          "expectedModified": .string("2026-07-11T00:00:01Z"), "title": .string("Updated draft"),
        ], installId: install.id, idempotencyKey: "wordpress-com-direct-update"),
      now: fixedDate("2026-01-01T00:30:11Z"))
    let directPublish = try services.providerActionBroker.execute(
      context: owner,
      request: MarketplaceProviderActionBrokerRequest(
        appIdOrSlug: app.id, actionKey: "wordpress_com_post_publish",
        payload: [
          "siteId": .string("241031857"), "postId": .string("42"),
          "expectedModified": .string("2026-07-11T00:00:01Z"),
        ], installId: install.id, idempotencyKey: "wordpress-com-direct-publish"),
      now: fixedDate("2026-01-01T00:30:12Z"))
    try expect(
      directUpdate.adapterExecuted && directUpdate.execution.status == .succeeded
        && directPublish.adapterExecuted && directPublish.execution.status == .succeeded,
      "Direct rights should preserve distinct WordPress.com draft update and publish")
    for action in [
      "wordpress_com_destructive_content", "wordpress_com_media_admin",
      "wordpress_com_global_raw_api",
    ] {
      let blocked = try services.providerActionBroker.execute(
        context: owner,
        request: MarketplaceProviderActionBrokerRequest(
          appIdOrSlug: app.id, actionKey: action, payload: [:], installId: install.id,
          idempotencyKey: action), now: fixedDate("2026-01-01T00:30:13Z"))
      try expect(
        !blocked.adapterExecuted && blocked.execution.status == .blocked,
        "WordPress.com blocked action escaped policy: " + action)
    }
    let persisted = try services.database.all(
      "SELECT connection_json AS value FROM applications_provider_connections UNION ALL SELECT execution_json AS value FROM marketplace_provider_action_executions"
    ).compactMap { sqliteText($0["value"]) }.joined(separator: "\n")
    for secret in [access, replacement] {
      try expect(!persisted.contains(secret), "WordPress.com persistence leaked a token")
    }
  }

  private static func
    testMiroProviderIntegrationPreservesBoardItemSpatialAndRotatingOAuthSemanticsEndToEnd() throws
  {
    final class StubHTTP: MiroProviderHTTPClient, @unchecked Sendable {
      var requests: [MiroProviderHTTPRequest] = []
      func send(_ request: MiroProviderHTTPRequest) throws -> MiroProviderHTTPResponse {
        requests.append(request)
        return MiroProviderHTTPResponse(
          statusCode: 200,
          body:
            #"{"data":[{"id":"item-live","type":"sticky_note","data":{"content":"Ship the Relay launch"},"style":{"fillColor":"yellow"},"position":{"x":120,"y":-45,"origin":"center"},"geometry":{"width":240,"height":120,"rotation":0},"parent":{"id":"frame-live"},"createdBy":{"id":"u1","name":"Owner"},"modifiedBy":{"id":"u2","name":"Reviewer"},"createdAt":"2026-07-11T00:00:00Z","modifiedAt":"2026-07-11T00:00:01Z"}],"cursor":"cursor-next"}"#
            .data(using: .utf8)!)
      }
    }
    let root = FileManager.default.temporaryDirectory.appendingPathComponent(
      "RelayConsoleMiroProviderTests/" + UUID().uuidString, isDirectory: true)
    let access = "miro-sensitive-access"
    let refresh = "miro-sensitive-refresh"
    let services = try makeServices(
      root: root,
      providerActionAdapter: RoutingMarketplaceProviderActionAdapter(
        miroAdapter: MiroProviderActionAdapter(client: FakeMiroProviderActionClient())))
    let workspace = try unwrap(services.data.getAppState().activeWorkspace, "missing workspace")
    let owner = context(roles: [.owner], workspaceId: workspace.id, correlationId: "miro-owner")
    let agent = try createServiceAgent(services: services, workspaceId: workspace.id)
    var app = marketplaceApp(
      workspaceId: workspace.id, slug: "miro", name: "Miro", summary: "Miro fixture",
      category: "Collaboration", riskLevel: .high, connectionState: .none,
      installState: .notInstalled)
    app.authType = "OAuth 2.0 authorization code"
    app.connectionType = "Relay-owned Miro OAuth"
    app.readOnly = false
    app.runtimeSupport = [.hermes, .openclaw]
    _ = try services.applications.saveCatalogApps(context: owner, apps: [app])
    let catalog = try services.applications.catalogSnapshot(context: owner, selectedAppId: app.slug)
    try expect(catalog.selectedApp?.slug == "miro", "Miro should be retained")
    app = try unwrap(catalog.selectedApp, "Miro should use the canonical catalog app")
    var connection = try services.providerConnections.saveMiroRelayOwnedOAuthConnection(
      context: owner, appIdOrSlug: app.id, accessToken: access, refreshToken: refresh, userId: "u1",
      teamId: "team1", accountLabel: "Relay Design", expiresAt: "2026-01-01T01:00:00Z",
      now: fixedDate("2026-01-01T00:00:00Z"))
    try expect(
      connection.status == .connected
        && connection.requiredScopes == ProviderConnectionService.miroRelayOwnedOAuthScopes
        && connection.secretReferenceIds.count == 2
        && connection.health.diagnostics["refreshTokenRotation"]
          == .string("serialized-atomic-two-reference-replacement"),
      "Miro connection should retain two scopes and rotating-token contract")
    let oldRefs = connection.secretReferenceIds
    connection = try services.providerConnections.rotateMiroOAuthTokens(
      context: owner, connectionId: connection.id, accessToken: "miro-new-access",
      refreshToken: "miro-new-refresh", expiresAt: "2026-01-01T02:00:00Z",
      now: fixedDate("2026-01-01T00:30:00Z"))
    try expect(
      oldRefs.allSatisfy { (try? services.secrets.getSecretValue($0)) == nil }
        && connection.secretReferenceIds.count == 2
        && Set(connection.secretReferenceIds).isDisjoint(with: Set(oldRefs)),
      "Miro refresh should atomically replace both token references")
    let install = try services.marketplaceInstalls.createInstall(
      context: owner,
      request: installRequest(
        id: "minreq-miro", workspaceId: workspace.id, app: app, connectionId: connection.id,
        agent: agent, roleId: app.roleManifest.primaryRole, selectedCapabilities: app.capabilities,
        riskAcknowledged: true), now: fixedDate("2026-01-01T00:30:01Z"))
    _ = try services.providerActionPolicies.compilePolicyMap(
      context: owner, appIdOrSlug: app.id, preset: .approvalRequired, connectionId: connection.id,
      installId: install.id, agentId: agent.id, now: fixedDate("2026-01-01T00:30:02Z"))
    let surface = try services.providerWrapperTools.compileSurface(
      context: owner, appIdOrSlug: app.id, installId: install.id, agentId: agent.id,
      now: fixedDate("2026-01-01T00:30:03Z"))
    try expect(
      surface.tools.count == 8 && surface.diagnostics.blockedActionCount >= 4
        && !surface.diagnostics.rawProviderToolExposure,
      "Miro should expose eight board/item wrappers without raw API")
    let mounted = try unwrap(
      try services.marketplaceRuntimeMounts.snapshot(
        context: owner, agent: agent, now: fixedDate("2026-01-01T00:30:04Z")
      ).apps.first, "missing Miro runtime app")
    let itemsTool = try unwrap(
      mounted.tools.first { $0.displayName == "List Miro board items" }, "missing item-list tool")
    let fakeResult = try services.marketplaceRuntimeToolBridge.execute(
      toolName: itemsTool.toolName,
      payload: ["boardId": .string("board1"), "maxResults": .number(2)],
      runtime: MarketplaceRuntimeToolExecutionContext(
        agentId: agent.id, workspaceId: workspace.id, runtimeType: agent.binding.runtimeType,
        dispatchId: "miro-fake", threadId: "miro-thread", runtimeSessionId: "miro-session",
        correlationId: "miro-fake"), now: fixedDate("2026-01-01T00:30:05Z"))
    let fakeProvider = try unwrap(objectValue(fakeResult["providerResult"]), "missing fake result")
    try expect(
      fakeProvider["semanticReadContract"] == .string("miro-board-items-v1")
        && String(describing: fakeProvider["items"] ?? .null).contains("position")
        && String(describing: fakeProvider["items"] ?? .null).contains("geometry"),
      "Miro item result should preserve spatial semantics")
    let definitions = try services.data.listMarketplaceProviderActionDefinitions(
      workspaceId: workspace.id, appId: app.id)
    let listDefinition = try unwrap(
      definitions.first { $0.actionKey == "miro_board_items" },
      "missing Miro board-items definition")
    let http = StubHTTP()
    let live = LiveMiroProviderActionClient(
      data: services.data, secrets: services.secrets, httpClient: http)
    let audit = ProviderExecutionAuditIdentity(
      workspaceId: workspace.id, actorId: owner.actorId, actorRole: "owner", agentId: agent.id,
      appId: app.id, appSlug: app.slug, connectionId: connection.id, installId: install.id,
      approvalId: nil, dispatchId: "miro-live", threadId: "miro-thread", source: "miro-live-test",
      redactionStatus: "private-state-excluded")
    let liveItems = try live.executeMiroAction(
      request: MarketplaceProviderActionAdapterRequest(
        context: owner, app: app, definition: listDefinition, permission: .allowed,
        payload: [
          "boardId": .string("board1"), "maxResults": .number(10),
          "cursor": .string("cursor-current"),
        ], approvalReference: nil, auditIdentity: audit, idempotencyKey: "miro-live"))
    try expect(
      http.requests.first?.method == "GET"
        && http.requests.first?.url.path == "/v2/boards/board1/items"
        && http.requests.first?.url.query?.contains("cursor=cursor-current") == true
        && http.requests.first?.headers["Authorization"] == "Bearer miro-new-access"
        && liveItems.result["cursor"] == .string("cursor-next")
        && String(describing: liveItems.result["items"] ?? .null).contains("frame-live"),
      "Miro live item list should use official cursor route and refreshed access token")
    let createTool = try unwrap(
      mounted.tools.first { $0.displayName == "Create Miro sticky note" },
      "missing sticky-note tool")
    let pending = try services.marketplaceRuntimeToolBridge.execute(
      toolName: createTool.toolName,
      payload: ["boardId": .string("board1"), "content": .string("Reviewed note")],
      runtime: MarketplaceRuntimeToolExecutionContext(
        agentId: agent.id, workspaceId: workspace.id, runtimeType: agent.binding.runtimeType,
        dispatchId: "miro-pending", threadId: "miro-thread", runtimeSessionId: "miro-session",
        correlationId: "miro-pending"), now: fixedDate("2026-01-01T00:30:06Z"))
    try expect(
      pending["executionStatus"] == .string(ProviderActionExecutionStatus.pendingApproval.rawValue)
        && pending["adapterExecuted"] == .bool(false),
      "Miro sticky-note creation should await approval")
    _ = try services.providerActionPolicies.compilePolicyMap(
      context: owner, appIdOrSlug: app.id, preset: .allowDirectWrites, acknowledgeDangerousPolicy: true, connectionId: connection.id,
      installId: install.id, agentId: agent.id, now: fixedDate("2026-01-01T00:30:07Z"))
    let direct = try services.providerActionBroker.execute(
      context: owner,
      request: MarketplaceProviderActionBrokerRequest(
        appIdOrSlug: app.id, actionKey: "miro_item_update",
        payload: [
          "boardId": .string("board1"), "itemId": .string("item1"),
          "itemType": .string("sticky_note"), "content": .string("Updated"),
        ], installId: install.id, idempotencyKey: "miro-update"),
      now: fixedDate("2026-01-01T00:30:08Z"))
    try expect(
      direct.adapterExecuted && direct.execution.status == .succeeded,
      "Direct rights should broker Miro item update")
    let blocked = try services.providerActionBroker.execute(
      context: owner,
      request: MarketplaceProviderActionBrokerRequest(
        appIdOrSlug: app.id, actionKey: "miro_item_delete",
        payload: ["boardId": .string("board1"), "itemId": .string("item1")], installId: install.id,
        idempotencyKey: "miro-delete"), now: fixedDate("2026-01-01T00:30:09Z"))
    try expect(
      !blocked.adapterExecuted && blocked.execution.status == .blocked,
      "Miro item deletion should remain blocked")
    let persisted = try services.database.all(
      "SELECT connection_json AS value FROM applications_provider_connections UNION ALL SELECT execution_json AS value FROM marketplace_provider_action_executions"
    ).compactMap { sqliteText($0["value"]) }.joined(separator: "\n")
    for secret in [access, refresh, "miro-new-access", "miro-new-refresh"] {
      try expect(!persisted.contains(secret), "Miro persistence leaked a token")
    }
  }

  private static func
    testFigmaProviderIntegrationPreservesFileNodeTextCommentAndReplySemanticsEndToEnd() throws
  {
    final class StubHTTP: FigmaProviderHTTPClient, @unchecked Sendable {
      var requests: [FigmaProviderHTTPRequest] = []
      func send(_ request: FigmaProviderHTTPRequest) throws -> FigmaProviderHTTPResponse {
        requests.append(request)
        if request.method == "POST" {
          return FigmaProviderHTTPResponse(
            statusCode: 200,
            body:
              #"{"id":"c-live","message":"Looks ready","user":{"id":"u1","handle":"Reviewer"},"created_at":"2026-07-11T00:00:00Z","resolved_at":null,"order_id":"1","parent_id":null,"client_meta":{"node_id":"1:2"}}"#
              .data(using: .utf8)!)
        }
        if request.url.path.hasSuffix("/meta") {
          return FigmaProviderHTTPResponse(
            statusCode: 200,
            body:
              #"{"file":{"name":"Relay UI","folder_name":"Product","last_touched_at":"2026-07-11T00:00:00Z","creator":{"id":"u1","handle":"Designer"},"last_touched_by":{"id":"u2","handle":"Reviewer"},"editorType":"figma","version":"42","role":"editor","link_access":"view","url":"https://www.figma.com/design/file1"}}"#
              .data(using: .utf8)!)
        }
        return FigmaProviderHTTPResponse(
          statusCode: 200,
          body:
            #"{"name":"Relay UI","version":"42","lastModified":"2026-07-11T00:00:00Z","editorType":"figma","document":{"id":"0:0","name":"Document","type":"DOCUMENT","children":[{"id":"1:1","name":"Page","type":"CANVAS","children":[{"id":"1:2","name":"Launch Frame","type":"FRAME","absoluteBoundingBox":{"x":0,"y":0,"width":800,"height":600},"children":[{"id":"1:3","name":"Headline","type":"TEXT","characters":"Ship Relay now"}]}]}]}}"#
            .data(using: .utf8)!)
      }
    }
    let root = FileManager.default.temporaryDirectory.appendingPathComponent(
      "RelayConsoleFigmaProviderTests/" + UUID().uuidString, isDirectory: true)
    let access = "figma-sensitive-access"
    let refresh = "figma-sensitive-refresh"
    let services = try makeServices(
      root: root,
      providerActionAdapter: RoutingMarketplaceProviderActionAdapter(
        figmaAdapter: FigmaProviderActionAdapter(client: FakeFigmaProviderActionClient())))
    let workspace = try unwrap(services.data.getAppState().activeWorkspace, "missing workspace")
    let owner = context(roles: [.owner], workspaceId: workspace.id, correlationId: "figma-owner")
    let agent = try createServiceAgent(services: services, workspaceId: workspace.id)
    var app = marketplaceApp(
      workspaceId: workspace.id, slug: "figma", name: "Figma", summary: "Figma fixture",
      category: "Design", riskLevel: .high, connectionState: .none, installState: .notInstalled)
    app.authType = "OAuth 2.0 authorization code"
    app.connectionType = "Relay-owned Figma OAuth"
    app.readOnly = false
    app.runtimeSupport = [.hermes, .openclaw]
    _ = try services.applications.saveCatalogApps(context: owner, apps: [app])
    let catalog = try services.applications.catalogSnapshot(context: owner, selectedAppId: app.slug)
    try expect(catalog.selectedApp?.slug == "figma", "Figma should be retained")
    app = try unwrap(catalog.selectedApp, "Figma should use the canonical catalog app")
    var connection = try services.providerConnections.saveFigmaRelayOwnedOAuthConnection(
      context: owner, appIdOrSlug: app.id, accessToken: access, refreshToken: refresh, userId: "u1",
      handle: "Designer", email: "relay@example.com", expiresAt: "2026-01-01T01:00:00Z",
      now: fixedDate("2026-01-01T00:00:00Z"))
    try expect(
      connection.status == .connected
        && connection.requiredScopes == ProviderConnectionService.figmaRelayOwnedOAuthScopes
        && connection.secretReferenceIds.count == 2
        && connection.health.diagnostics["projectDiscoverySupported"] == .bool(false),
      "Figma connection should retain granular scopes and file-key limitation")
    let oldAccess = connection.credentialRequirements.first {
      $0.fieldKey == "figma_oauth_access_token"
    }!.secretReferenceId!
    let refreshRef = connection.credentialRequirements.first {
      $0.fieldKey == "figma_oauth_refresh_token"
    }!.secretReferenceId!
    connection = try services.providerConnections.refreshFigmaOAuthAccessToken(
      context: owner, connectionId: connection.id, accessToken: "figma-new-access",
      expiresAt: "2026-01-01T02:00:00Z", now: fixedDate("2026-01-01T00:30:00Z"))
    try expect(
      (try? services.secrets.getSecretValue(oldAccess)) == nil
        && connection.credentialRequirements.first { $0.fieldKey == "figma_oauth_refresh_token" }?
          .secretReferenceId == refreshRef
        && (try services.secrets.getSecretValue(refreshRef)) == refresh,
      "Figma refresh should replace only access reference and retain reusable refresh reference")
    let install = try services.marketplaceInstalls.createInstall(
      context: owner,
      request: installRequest(
        id: "minreq-figma", workspaceId: workspace.id, app: app, connectionId: connection.id,
        agent: agent, roleId: app.roleManifest.primaryRole, selectedCapabilities: app.capabilities,
        riskAcknowledged: true), now: fixedDate("2026-01-01T00:30:01Z"))
    _ = try services.providerActionPolicies.compilePolicyMap(
      context: owner, appIdOrSlug: app.id, preset: .approvalRequired, connectionId: connection.id,
      installId: install.id, agentId: agent.id, now: fixedDate("2026-01-01T00:30:02Z"))
    let surface = try services.providerWrapperTools.compileSurface(
      context: owner, appIdOrSlug: app.id, installId: install.id, agentId: agent.id,
      now: fixedDate("2026-01-01T00:30:03Z"))
    try expect(
      surface.tools.count == 7 && surface.diagnostics.blockedActionCount >= 4
        && !surface.diagnostics.rawProviderToolExposure
        && !surface.tools.contains(where: { $0.toolName.contains("project") }),
      "Figma should expose seven file-key wrappers without project discovery")
    let mounted = try unwrap(
      try services.marketplaceRuntimeMounts.snapshot(
        context: owner, agent: agent, now: fixedDate("2026-01-01T00:30:04Z")
      ).apps.first, "missing Figma runtime app")
    let nodeTool = try unwrap(
      mounted.tools.first { $0.displayName == "Read Figma file nodes" }, "missing node tool")
    let fakeResult = try services.marketplaceRuntimeToolBridge.execute(
      toolName: nodeTool.toolName, payload: ["fileKey": .string("file1"), "depth": .number(3)],
      runtime: MarketplaceRuntimeToolExecutionContext(
        agentId: agent.id, workspaceId: workspace.id, runtimeType: agent.binding.runtimeType,
        dispatchId: "figma-fake", threadId: "figma-thread", runtimeSessionId: "figma-session",
        correlationId: "figma-fake"), now: fixedDate("2026-01-01T00:30:05Z"))
    let fakeProvider = try unwrap(objectValue(fakeResult["providerResult"]), "missing fake result")
    try expect(
      fakeProvider["semanticReadContract"] == .string("figma-file-nodes-v1")
        && String(describing: fakeProvider["nodes"] ?? .null).contains(
          "Ship the new Relay experience"),
      "Figma node result should preserve useful text")
    let definitions = try services.data.listMarketplaceProviderActionDefinitions(
      workspaceId: workspace.id, appId: app.id)
    let nodeDefinition = try unwrap(
      definitions.first { $0.actionKey == "figma_file_nodes" }, "missing node definition")
    let http = StubHTTP()
    let live = LiveFigmaProviderActionClient(
      data: services.data, secrets: services.secrets, httpClient: http)
    let audit = ProviderExecutionAuditIdentity(
      workspaceId: workspace.id, actorId: owner.actorId, actorRole: "owner", agentId: agent.id,
      appId: app.id, appSlug: app.slug, connectionId: connection.id, installId: install.id,
      approvalId: nil, dispatchId: "figma-live", threadId: "figma-thread",
      source: "figma-live-test", redactionStatus: "private-state-excluded")
    let liveNodes = try live.executeFigmaAction(
      request: MarketplaceProviderActionAdapterRequest(
        context: owner, app: app, definition: nodeDefinition, permission: .allowed,
        payload: ["fileKey": .string("file1"), "depth": .number(3), "maxNodes": .number(10)],
        approvalReference: nil, auditIdentity: audit, idempotencyKey: "figma-live"))
    try expect(
      http.requests.first?.method == "GET" && http.requests.first?.url.path == "/v1/files/file1"
        && http.requests.first?.url.query?.contains("depth=3") == true
        && http.requests.first?.headers["Authorization"] == "Bearer figma-new-access"
        && String(describing: liveNodes.result["nodes"] ?? .null).contains("Ship Relay now"),
      "Figma live nodes should use official bounded route and refreshed token")
    let commentTool = try unwrap(
      mounted.tools.first { $0.displayName == "Post Figma comment" }, "missing comment tool")
    let pending = try services.marketplaceRuntimeToolBridge.execute(
      toolName: commentTool.toolName,
      payload: ["fileKey": .string("file1"), "message": .string("Looks ready")],
      runtime: MarketplaceRuntimeToolExecutionContext(
        agentId: agent.id, workspaceId: workspace.id, runtimeType: agent.binding.runtimeType,
        dispatchId: "figma-pending", threadId: "figma-thread", runtimeSessionId: "figma-session",
        correlationId: "figma-pending"), now: fixedDate("2026-01-01T00:30:06Z"))
    try expect(
      pending["executionStatus"] == .string(ProviderActionExecutionStatus.pendingApproval.rawValue)
        && pending["adapterExecuted"] == .bool(false), "Figma comment should await approval")
    _ = try services.providerActionPolicies.compilePolicyMap(
      context: owner, appIdOrSlug: app.id, preset: .allowDirectWrites, acknowledgeDangerousPolicy: true, connectionId: connection.id,
      installId: install.id, agentId: agent.id, now: fixedDate("2026-01-01T00:30:07Z"))
    let direct = try services.providerActionBroker.execute(
      context: owner,
      request: MarketplaceProviderActionBrokerRequest(
        appIdOrSlug: app.id, actionKey: "figma_comment_reply",
        payload: [
          "fileKey": .string("file1"), "parentCommentId": .string("c1"),
          "message": .string("Agreed"),
        ], installId: install.id, idempotencyKey: "figma-reply"),
      now: fixedDate("2026-01-01T00:30:08Z"))
    try expect(
      direct.adapterExecuted && direct.execution.status == .succeeded,
      "Direct rights should broker Figma reply")
    let blocked = try services.providerActionBroker.execute(
      context: owner,
      request: MarketplaceProviderActionBrokerRequest(
        appIdOrSlug: app.id, actionKey: "figma_project_discover", payload: [:],
        installId: install.id, idempotencyKey: "figma-project"),
      now: fixedDate("2026-01-01T00:30:09Z"))
    try expect(
      !blocked.adapterExecuted && blocked.execution.status == .blocked,
      "Figma project discovery should remain blocked")
    let persisted = try services.database.all(
      "SELECT connection_json AS value FROM applications_provider_connections UNION ALL SELECT execution_json AS value FROM marketplace_provider_action_executions"
    ).compactMap { sqliteText($0["value"]) }.joined(separator: "\n")
    for secret in [access, refresh, "figma-new-access"] {
      try expect(!persisted.contains(secret), "Figma persistence leaked a token")
    }
  }

  private static func sqliteText(_ value: SQLiteValue?) -> String? {
    guard case .text(let text)? = value else { return nil }
    return text
  }

  private static func sqliteInteger(_ value: SQLiteValue?) -> Int? {
    guard case .integer(let integer)? = value else { return nil }
    return Int(integer)
  }

  private static func readPackageFile(_ relativePath: String) throws -> String {
    try RelayConsoleSourceTestSupport.read(
      root: URL(fileURLWithPath: FileManager.default.currentDirectoryPath),
      path: relativePath
    )
  }

  private static func expect(_ condition: @autoclosure () throws -> Bool, _ message: String) throws
  {
    guard try condition() else {
      throw ServiceTestFailure(message)
    }
  }

  private static func unwrap<T>(_ value: T?, _ message: String) throws -> T {
    guard let value else {
      throw ServiceTestFailure(message)
    }
    return value
  }

  private static func waitForAsync(_ operation: @escaping () async throws -> Void) -> Result<
    Void, Error
  > {
    let semaphore = DispatchSemaphore(value: 0)
    let box = AsyncResultBox()
    Task {
      do {
        try await operation()
        box.set(.success(()))
      } catch {
        box.set(.failure(error))
      }
      semaphore.signal()
    }
    semaphore.wait()
    return box.value ?? .failure(ServiceTestFailure("async operation did not report a result"))
  }

  private static func awaitResult<T>(_ operation: @escaping () async throws -> T) throws -> T {
    let semaphore = DispatchSemaphore(value: 0)
    let box = AsyncValueBox<T>()
    Task {
      do {
        box.set(.success(try await operation()))
      } catch {
        box.set(.failure(error))
      }
      semaphore.signal()
    }
    semaphore.wait()
    return try box.value?.get()
      ?? {
        throw ServiceTestFailure("async operation did not report a result")
      }()
  }

  private static func waitUntil(
    _ description: String,
    timeout: TimeInterval = 2.0,
    condition: () throws -> Bool
  ) throws {
    let deadline = Date().addingTimeInterval(timeout)
    while Date() < deadline {
      if try condition() {
        return
      }
      Thread.sleep(forTimeInterval: 0.01)
    }
    throw ServiceTestFailure(description)
  }
}

