private final class EventCounter: @unchecked Sendable {
  private let lock = NSLock()
  private var count = 0

  var value: Int {
    lock.lock()
    defer { lock.unlock() }
    return count
  }

  func increment() {
    lock.lock()
    count += 1
    lock.unlock()
  }
}

private final class ChatEventCollector: @unchecked Sendable {
  private let lock = NSLock()
  private var payloads: [ChatEventPayload] = []

  func capture(_ payload: Any) {
    guard let payload = payload as? ChatEventPayload else { return }
    lock.lock()
    payloads.append(payload)
    lock.unlock()
  }

  func payloads(for eventName: RelayEventName) -> [ChatEventPayload] {
    lock.lock()
    defer { lock.unlock() }
    return payloads.filter { $0.eventName == eventName.rawValue }
  }
}

private enum OpenClawAgentsListShape {
  case objectAgents
  case topLevelArray
}

private func configureOpenClawGatewayAuth(
  args: [String],
  options: CommandOptions,
  onTokenConfigured: ((String) -> Void)? = nil
) -> CommandResult {
  guard let setIndex = args.firstIndex(of: "set"),
    args.indices.contains(setIndex + 2)
  else {
    return CommandResult(code: 1, stdout: "", stderr: "invalid OpenClaw config set arguments")
  }
  let key = args[setIndex + 1]
  let value = args[setIndex + 2]
  guard key == "gateway.auth.mode" || key == "gateway.auth.token" else {
    return CommandResult(code: 127, stdout: "", stderr: "unhandled OpenClaw config key: \(key)")
  }
  guard let configPath = options.env["OPENCLAW_CONFIG_PATH"] else {
    return CommandResult(code: 1, stdout: "", stderr: "missing OPENCLAW_CONFIG_PATH")
  }

  let configURL = URL(fileURLWithPath: configPath)
  var config: [String: Any] = [:]
  if let data = try? Data(contentsOf: configURL),
    let parsed = try? JSONSerialization.jsonObject(with: data) as? [String: Any]
  {
    config = parsed
  }
  var gateway = config["gateway"] as? [String: Any] ?? [:]
  var auth = gateway["auth"] as? [String: Any] ?? [:]
  if key == "gateway.auth.mode" {
    auth["mode"] = value
  } else {
    auth["token"] = value
    onTokenConfigured?(value)
  }
  gateway["mode"] = gateway["mode"] ?? "local"
  gateway["auth"] = auth
  config["gateway"] = gateway

  do {
    try FileManager.default.createDirectory(
      at: configURL.deletingLastPathComponent(), withIntermediateDirectories: true)
    let data = try JSONSerialization.data(
      withJSONObject: config, options: [.prettyPrinted, .sortedKeys])
    try (String(data: data, encoding: .utf8) ?? "{}").appending("\n").write(
      to: configURL, atomically: true, encoding: .utf8)
    return CommandResult(code: 0, stdout: #"{"ok":true}"#, stderr: "")
  } catch {
    return CommandResult(code: 1, stdout: "", stderr: error.localizedDescription)
  }
}

private final class OpenClawGatewayLifecycleRunner: CommandRunning, @unchecked Sendable {
  private let queue = DispatchQueue(label: "relay-console-openclaw-gateway-lifecycle-runner")
  private var ready = false
  private var installs = 0
  private var starts = 0
  private var restarts = 0
  private var statuses = 0
  private var configuredToken: String?
  private var installTokens: [String?] = []
  private var startEnvironments: [[String: String]] = []
  private let readinessDelayChecks: Int
  private var remainingReadinessDelayChecks = 0

  init(readinessDelayChecks: Int = 0) {
    self.readinessDelayChecks = readinessDelayChecks
  }

  func gatewayInstallCount() -> Int {
    queue.sync { installs }
  }

  func gatewayStartCount() -> Int {
    queue.sync { starts }
  }

  func gatewayRestartCount() -> Int {
    queue.sync { restarts }
  }

  func gatewayStatusCount() -> Int {
    queue.sync { statuses }
  }

  func latestInstallToken() -> String? {
    queue.sync {
      installTokens.last ?? nil
    }
  }

  func allInstallTokensAreRelayManaged() -> Bool {
    queue.sync {
      !installTokens.isEmpty && installTokens.allSatisfy { $0?.hasPrefix("relay_") == true }
    }
  }

  func latestStartEnvironmentValue(_ key: String) -> String? {
    queue.sync {
      startEnvironments.last?[key]
    }
  }

  func setGatewayReady(_ value: Bool) {
    queue.sync {
      ready = value
    }
  }

  func run(_ command: String, _ args: [String], options: CommandOptions) async -> CommandResult {
    if args.contains("openclaw.mjs"), args.contains("models"), args.contains("auth"),
      args.contains("list")
    {
      return CommandResult(
        code: 0, stdout: #"{"profiles":[{"provider":"openai","type":"oauth"}]}"#, stderr: "")
    }
    if args.contains("openclaw.mjs"), args.contains("config"), args.contains("set") {
      return configureOpenClawGatewayAuth(args: args, options: options) { [self] token in
        self.queue.sync {
          self.configuredToken = token
        }
      }
    }
    if args.contains("openclaw.mjs"), args.contains("gateway"), args.contains("install") {
      let tokenIndex = args.firstIndex(of: "--token")
      let token = tokenIndex.flatMap { index in
        args.indices.contains(index + 1) ? args[index + 1] : nil
      }
      queue.sync {
        installs += 1
        configuredToken = configuredToken ?? token
        installTokens.append(token)
      }
      return CommandResult(code: 0, stdout: "Installed LaunchAgent", stderr: "")
    }
    if args.contains("openclaw.mjs"), args.contains("gateway"), args.contains("start") {
      queue.sync {
        starts += 1
        ready = true
        remainingReadinessDelayChecks = readinessDelayChecks
        startEnvironments.append(options.env)
      }
      return CommandResult(code: 0, stdout: "Started LaunchAgent", stderr: "")
    }
    if args.contains("openclaw.mjs"), args.contains("gateway"), args.contains("restart") {
      queue.sync {
        restarts += 1
        ready = true
        remainingReadinessDelayChecks = readinessDelayChecks
        startEnvironments.append(options.env)
      }
      return CommandResult(code: 0, stdout: "Restarted LaunchAgent", stderr: "")
    }
    if args.contains("openclaw.mjs"), args.contains("agents"), args.contains("list") {
      return CommandResult(code: 0, stdout: #"[]"#, stderr: "")
    }
    if args.contains("openclaw.mjs"), args.contains("gateway"), args.contains("status") {
      let state = queue.sync { () -> (Bool, String?) in
        statuses += 1
        if ready, remainingReadinessDelayChecks > 0 {
          remainingReadinessDelayChecks -= 1
          return (false, configuredToken)
        }
        return (ready, configuredToken)
      }
      let isReady = state.0
      if isReady {
        guard let configuredToken = state.1,
          options.env["OPENCLAW_GATEWAY_TOKEN"] == configuredToken
        else {
          return CommandResult(
            code: 0,
            stdout:
              #"{"rpc":{"ok":false,"error":"device identity required"},"port":{"status":"busy"}}"#,
            stderr: "")
        }
        return CommandResult(
          code: 0, stdout: #"{"rpc":{"ok":true},"port":{"status":"listening"}}"#, stderr: "")
      }
      return CommandResult(
        code: 0,
        stdout:
          #"{"rpc":{"ok":false,"error":"connect ECONNREFUSED 127.0.0.1:18789"},"port":{"status":"free"}}"#,
        stderr: "")
    }
    return CommandResult(
      code: 127, stdout: "",
      stderr: "gateway lifecycle runner did not handle: \(command) \(args.joined(separator: " "))")
  }

  func spawn(_ command: String, _ args: [String], options: CommandOptions, stdin: String?)
    async throws -> (process: Process, result: Task<CommandResult, Never>)
  {
    throw RelayError(
      .internalError,
      "OpenClaw gateway lifecycle should use service install/start, not spawned foreground processes."
    )
  }
}

private final class ExpiredOpenClawAuthRunner: CommandRunning, @unchecked Sendable {
  private let queue = DispatchQueue(label: "relay-console-expired-openclaw-auth-runner")
  private var gatewayStatuses = 0

  func gatewayStatusCount() -> Int {
    queue.sync { gatewayStatuses }
  }

  func run(_ command: String, _ args: [String], options: CommandOptions) async -> CommandResult {
    if args.contains("openclaw.mjs"), args.contains("models"), args.contains("auth"),
      args.contains("list")
    {
      return CommandResult(
        code: 0,
        stdout:
          #"{"profiles":[{"provider":"openai","type":"oauth","expiresAt":"2026-07-05T08:53:10.607Z"}]}"#,
        stderr: ""
      )
    }
    if args.contains("openclaw.mjs"), args.contains("gateway"), args.contains("status") {
      queue.sync { gatewayStatuses += 1 }
      return CommandResult(
        code: 0, stdout: #"{"rpc":{"ok":false},"port":{"status":"free"}}"#, stderr: "")
    }
    return CommandResult(code: 0, stdout: #"{"ok":true}"#, stderr: "")
  }

  func spawn(_ command: String, _ args: [String], options: CommandOptions, stdin: String?)
    async throws -> (process: Process, result: Task<CommandResult, Never>)
  {
    throw RelayError(.internalError, "expired OpenClaw auth should not spawn a gateway")
  }
}

private final class HermesSchedulerIsolationRunner: CommandRunning, @unchecked Sendable {
  private let queue = DispatchQueue(label: "relay-console-hermes-scheduler-isolation-runner")
  private var loadedLabels: Set<String> = []

  func run(_ command: String, _ args: [String], options: CommandOptions) async -> CommandResult {
    guard command == "/bin/launchctl" else {
      return CommandResult(code: 0, stdout: "", stderr: "")
    }
    if args.first == "print", let target = args.dropFirst().first {
      let label = target.components(separatedBy: "/").last ?? target
      return queue.sync {
        loadedLabels.contains(label)
          ? CommandResult(code: 0, stdout: "running", stderr: "")
          : CommandResult(code: 1, stdout: "", stderr: "not loaded")
      }
    }
    if args.first == "bootstrap", let plistPath = args.last {
      let label = URL(fileURLWithPath: plistPath).deletingPathExtension().lastPathComponent
      _ = queue.sync { loadedLabels.insert(label) }
      return CommandResult(code: 0, stdout: "", stderr: "")
    }
    if args.first == "kickstart" {
      return CommandResult(code: 0, stdout: "", stderr: "")
    }
    if args.first == "bootout", let target = args.dropFirst().first {
      let label = target.components(separatedBy: "/").last ?? target
      _ = queue.sync { loadedLabels.remove(label) }
      return CommandResult(code: 0, stdout: "", stderr: "")
    }
    return CommandResult(code: 0, stdout: "", stderr: "")
  }

  func spawn(_ command: String, _ args: [String], options: CommandOptions, stdin: String?)
    async throws -> (process: Process, result: Task<CommandResult, Never>)
  {
    throw RelayError(.internalError, "Hermes scheduler isolation runner does not spawn processes.")
  }
}

private final class ScriptedProvisioningRunner: CommandRunning, @unchecked Sendable {
  private let authConnected: Bool
  private let openClawListShape: OpenClawAgentsListShape
  private let queue = DispatchQueue(label: "relay-console-scripted-provisioning-runner")
  private var openClawAgents: Set<String> = []
  private var openClawAdds: [String] = []
  private var openClawRemoves: [String] = []
  private var openClawAgentRunCwds: [String] = []
  private var openClawAgentRunEnvs: [[String: String]] = []
  private var openClawAgentRunTimeouts: [Int] = []
  private var hermesProvisionScripts: [String] = []
  private var hermesAuthHomes: [String] = []

  init(
    authConnected: Bool = true,
    initialOpenClawAgents: Set<String> = [],
    openClawListShape: OpenClawAgentsListShape = .objectAgents
  ) {
    self.authConnected = authConnected
    self.openClawAgents = initialOpenClawAgents
    self.openClawListShape = openClawListShape
  }

  func openClawAddCount(for slug: String) -> Int {
    queue.sync {
      openClawAdds.filter { $0 == slug }.count
    }
  }

  func openClawRemoveCount(for slug: String) -> Int {
    queue.sync {
      openClawRemoves.filter { $0 == slug }.count
    }
  }

  func openClawAgentRunCwd() -> String? {
    queue.sync {
      openClawAgentRunCwds.last
    }
  }

  func openClawAgentRunEnvValue(_ key: String) -> String? {
    queue.sync {
      openClawAgentRunEnvs.last?[key]
    }
  }

  func openClawAgentRunTimeoutMs() -> Int? {
    queue.sync {
      openClawAgentRunTimeouts.last
    }
  }

  func lastHermesProvisionScript() -> String? {
    queue.sync { hermesProvisionScripts.last }
  }

  func lastHermesAuthHome() -> String? {
    queue.sync { hermesAuthHomes.last }
  }

  func run(_ command: String, _ args: [String], options: CommandOptions) async -> CommandResult {
    if args.first == "-c",
      args.count > 1,
      args[1].contains("get_codex_auth_status"),
      !args[1].contains("_update_config_for_provider")
    {
      queue.sync {
        hermesAuthHomes.append(options.env["HERMES_HOME"] ?? "")
      }
      return authConnected
        ? CommandResult(code: 0, stdout: #"{"logged_in":true}"#, stderr: "")
        : CommandResult(
          code: 0,
          stdout: #"{"logged_in":false,"error":"Connect OpenAI with ChatGPT to continue."}"#,
          stderr: "")
    }

    if args.first == "-c",
      args.count > 1,
      args[1].contains("_update_config_for_provider"),
      args[1].contains("openai-codex")
    {
      return configureHermesOpenAICodexProvider(options: options)
    }

    if args.contains("import run_agent, tui_gateway.entry; print('ok')") {
      return CommandResult(code: 0, stdout: "ok\n", stderr: "")
    }

    if options.env["RELAY_CONSOLE_HERMES_PROFILE_PAYLOAD"] != nil {
      if args.count > 1 {
        queue.sync { hermesProvisionScripts.append(args[1]) }
      }
      return createHermesProfile(options: options)
    }

    if args.contains("openclaw.mjs"), args.contains("models"), args.contains("auth"),
      args.contains("list")
    {
      return authConnected
        ? CommandResult(
          code: 0, stdout: #"{"profiles":[{"provider":"openai","type":"oauth"}]}"#, stderr: "")
        : CommandResult(code: 1, stdout: "", stderr: "Connect OpenAI with ChatGPT to continue.")
    }

    if args.contains("openclaw.mjs"), args.contains("config"), args.contains("set") {
      return configureOpenClawGatewayAuth(args: args, options: options)
    }

    if args.contains("openclaw.mjs"), args.contains("gateway"), args.contains("status") {
      return CommandResult(code: 0, stdout: #"{"status":"ready"}"#, stderr: "")
    }

    if args.contains("openclaw.mjs"), args.contains("agents"), args.contains("list") {
      let agents = queue.sync { openClawAgents.sorted() }
      let body = agents.map { #"{"id":"\#($0)","slug":"\#($0)"}"# }.joined(separator: ",")
      switch openClawListShape {
      case .objectAgents:
        return CommandResult(code: 0, stdout: #"{"agents":[\#(body)]}"#, stderr: "")
      case .topLevelArray:
        return CommandResult(code: 0, stdout: #"[\#(body)]"#, stderr: "")
      }
    }

    if let addIndex = args.firstIndex(of: "add"), args.contains("openclaw.mjs"),
      args.contains("agents")
    {
      let slug = args.indices.contains(addIndex + 1) ? args[addIndex + 1] : "relay-agent"
      if let workspaceFlag = args.firstIndex(of: "--workspace"),
        args.indices.contains(workspaceFlag + 1)
      {
        try? FileManager.default.createDirectory(
          atPath: args[workspaceFlag + 1], withIntermediateDirectories: true)
      }
      queue.sync {
        openClawAdds.append(slug)
        _ = openClawAgents.insert(slug)
      }
      return CommandResult(code: 0, stdout: #"{"slug":"\#(slug)"}"#, stderr: "")
    }

    if args.contains("openclaw.mjs"),
      args.contains("agents"),
      let commandIndex = args.firstIndex(where: { ["remove", "delete", "rm"].contains($0) })
    {
      let slug = args.indices.contains(commandIndex + 1) ? args[commandIndex + 1] : "relay-agent"
      queue.sync {
        openClawRemoves.append(slug)
        openClawAgents.remove(slug)
      }
      return CommandResult(code: 0, stdout: #"{"removed":"\#(slug)"}"#, stderr: "")
    }

    if args.contains("openclaw.mjs"), args.contains("agents"), args.contains("set-identity") {
      return CommandResult(code: 0, stdout: #"{"status":"updated"}"#, stderr: "")
    }

    if args.contains("openclaw.mjs"), args.contains("agent"), !args.contains("agents") {
      let cwd = options.cwd?.path ?? ""
      queue.sync {
        openClawAgentRunCwds.append(cwd)
        openClawAgentRunEnvs.append(options.env)
        openClawAgentRunTimeouts.append(options.timeoutMs)
      }
      guard !cwd.isEmpty,
        FileManager.default.fileExists(
          atPath: URL(fileURLWithPath: cwd).appendingPathComponent("openclaw.mjs").path)
      else {
        return CommandResult(
          code: 1, stdout: "", stderr: "Error: Cannot find module '\(cwd)/openclaw.mjs'")
      }
      return CommandResult(
        code: 0, stdout: #"{"summary":"OpenClaw reply from scripted runner."}"#, stderr: "")
    }

    return CommandResult(
      code: 127, stdout: "",
      stderr:
        "scripted provisioning runner did not handle: \(command) \(args.joined(separator: " "))")
  }

  func spawn(_ command: String, _ args: [String], options: CommandOptions, stdin: String?)
    async throws -> (process: Process, result: Task<CommandResult, Never>)
  {
    throw RelayError(.unsupported, "spawn is not available in provisioning service tests")
  }

  private func createHermesProfile(options: CommandOptions) -> CommandResult {
    guard let payloadText = options.env["RELAY_CONSOLE_HERMES_PROFILE_PAYLOAD"] else {
      return CommandResult(code: 1, stdout: "", stderr: "missing Hermes profile payload")
    }
    let payload = decodeJSONRecord(payloadText)
    let slug = stringValue(payload["profileSlug"]) ?? "relay-agent-profile"
    let hermesHome = URL(
      fileURLWithPath: options.env["HERMES_HOME"] ?? FileManager.default.temporaryDirectory.path)
    let profileHome = hermesHome.appendingPathComponent("profiles/\(slug)", isDirectory: true)
    let identity = profileHome.appendingPathComponent("SOUL.md")
    do {
      try FileManager.default.createDirectory(at: profileHome, withIntermediateDirectories: true)
      let soul = stringValue(payload["soul"]) ?? "Relay identity"
      try soul.write(to: identity, atomically: true, encoding: .utf8)
      return CommandResult(
        code: 0,
        stdout:
          #"{"profileSlug":"\#(slug)","profileHomePath":"\#(profileHome.path)","identityFilePath":"\#(identity.path)"}"#,
        stderr: ""
      )
    } catch {
      return CommandResult(code: 1, stdout: "", stderr: error.localizedDescription)
    }
  }

  private func configureHermesOpenAICodexProvider(options: CommandOptions) -> CommandResult {
    let hermesHome = URL(
      fileURLWithPath: options.env["HERMES_HOME"] ?? FileManager.default.temporaryDirectory.path)
    do {
      try FileManager.default.createDirectory(at: hermesHome, withIntermediateDirectories: true)
      let config = """
        model:
          provider: openai-codex
          default: gpt-5.5
          base_url: https://chatgpt.com/backend-api/codex
        """
      try config.write(
        to: hermesHome.appendingPathComponent("config.yaml"), atomically: true, encoding: .utf8)
      return CommandResult(
        code: 0, stdout: #"{"configured":true,"provider":"openai-codex","model":"gpt-5.5"}"#,
        stderr: "")
    } catch {
      return CommandResult(code: 1, stdout: "", stderr: error.localizedDescription)
    }
  }
}

