private final class ScriptedRuntimeBridge: DesktopRuntimeBridge, @unchecked Sendable {
  let runtimeType: RuntimeType
  let adapterId = "test-scripted-runtime"
  let displayName: String
  private let supportsCancellation: Bool
  private let responseDelayMilliseconds: UInt64
  private let lock = NSLock()
  private var results: [RuntimeDispatchTerminalResult]
  private var requests: [RuntimeDispatchRequest] = []

  init(
    runtimeType: RuntimeType,
    supportsCancellation: Bool,
    results: [RuntimeDispatchTerminalResult],
    responseDelayMilliseconds: UInt64 = 0
  ) {
    self.runtimeType = runtimeType
    self.supportsCancellation = supportsCancellation
    self.responseDelayMilliseconds = responseDelayMilliseconds
    self.results = results
    self.displayName = runtimeLabel(runtimeType)
  }

  func getHealth(harnessId: String, config: JSONRecord) async -> HarnessHealth {
    HarnessHealth(
      harnessId: harnessId,
      runtimeType: runtimeType,
      status: .healthy,
      message: "Healthy scripted runtime.",
      version: "test",
      capabilities: supportsCancellation ? ["dispatch", "cancel"] : ["dispatch"],
      checkedAt: "2026-01-01T00:00:00Z",
      detail: [:]
    )
  }

  func getCapabilities(harnessId: String, config: JSONRecord) async -> RuntimeCapabilities {
    RuntimeCapabilities(
      runtimeType: runtimeType,
      supportsStreaming: runtimeType == .hermes,
      supportsCancellation: supportsCancellation,
      supportsSessions: true,
      supportsTools: true,
      requiresWorkspaceFolder: false,
      requiresSecret: false,
      maxConcurrentDispatches: 1,
      eventTypes: [
        .queued, .started, .status, .thinking, .tool, .delta, .completed, .failed, .cancelled,
      ]
    )
  }

  func dispatchTurn(_ request: RuntimeDispatchRequest, sink: RuntimeEventSink) async
    -> RuntimeDispatchTerminalResult
  {
    record(request)
    await sink.emit(bridgeEvent(request, .queued, status: "Queued"))
    await sink.emit(bridgeEvent(request, .started, status: "\(displayName) running"))
    if responseDelayMilliseconds > 0 {
      try? await Task.sleep(nanoseconds: responseDelayMilliseconds * 1_000_000)
    }
    let result = nextResult()
    switch result.status {
    case "completed":
      if let text = result.finalText {
        await sink.emit(bridgeEvent(request, .delta, text: text, status: "Writing"))
        await sink.emit(bridgeEvent(request, .completed, text: text, status: "Completed"))
      }
    case "cancelled":
      await sink.emit(
        bridgeEvent(request, .cancelled, status: result.error?.message ?? "Cancelled"))
    default:
      await sink.emit(
        bridgeEvent(
          request,
          .failed,
          status: result.error?.message ?? "Dispatch failed.",
          detail: [
            "category": .string(result.error?.category ?? "unknown"),
            "retryable": .bool(result.error?.recoverable ?? true),
          ]
        ))
    }
    return result
  }

  func cancelDispatch(dispatchId: String, correlationId: String) async
    -> CancelRuntimeDispatchResult
  {
    supportsCancellation
      ? CancelRuntimeDispatchResult(status: "cancelled", message: "Cancel requested.")
      : CancelRuntimeDispatchResult(
        status: "not_supported", message: "Cancellation is unavailable.")
  }

  func dispatchCallCount() -> Int {
    lock.lock()
    defer { lock.unlock() }
    return requests.count
  }

  func lastRequest() -> RuntimeDispatchRequest? {
    lock.lock()
    defer { lock.unlock() }
    return requests.last
  }

  func recordedRequests() -> [RuntimeDispatchRequest] {
    lock.lock()
    defer { lock.unlock() }
    return requests
  }

  private func record(_ request: RuntimeDispatchRequest) {
    lock.lock()
    requests.append(request)
    lock.unlock()
  }

  private func nextResult() -> RuntimeDispatchTerminalResult {
    lock.lock()
    defer { lock.unlock() }
    if results.isEmpty {
      return failedResult(
        "script_exhausted", "No scripted runtime result was available.", recoverable: false)
    }
    return results.removeFirst()
  }
}

private final class WaitingRuntimeBridge: DesktopRuntimeBridge, @unchecked Sendable {
  let runtimeType: RuntimeType
  let adapterId = "test-waiting-runtime"
  let displayName: String
  private let supportsCancellation: Bool
  private let lock = NSLock()
  private var cancelledDispatches: Set<String> = []

  init(runtimeType: RuntimeType, supportsCancellation: Bool) {
    self.runtimeType = runtimeType
    self.supportsCancellation = supportsCancellation
    self.displayName = runtimeLabel(runtimeType)
  }

  func getHealth(harnessId: String, config: JSONRecord) async -> HarnessHealth {
    HarnessHealth(
      harnessId: harnessId,
      runtimeType: runtimeType,
      status: .healthy,
      message: "Healthy waiting runtime.",
      version: "test",
      capabilities: supportsCancellation ? ["dispatch", "cancel"] : ["dispatch"],
      checkedAt: "2026-01-01T00:00:00Z",
      detail: [:]
    )
  }

  func getCapabilities(harnessId: String, config: JSONRecord) async -> RuntimeCapabilities {
    RuntimeCapabilities(
      runtimeType: runtimeType,
      supportsStreaming: runtimeType == .hermes,
      supportsCancellation: supportsCancellation,
      supportsSessions: true,
      supportsTools: true,
      requiresWorkspaceFolder: false,
      requiresSecret: false,
      maxConcurrentDispatches: 1,
      eventTypes: [.queued, .started, .cancelled, .failed]
    )
  }

  func dispatchTurn(_ request: RuntimeDispatchRequest, sink: RuntimeEventSink) async
    -> RuntimeDispatchTerminalResult
  {
    await sink.emit(bridgeEvent(request, .queued, status: "Queued"))
    await sink.emit(bridgeEvent(request, .started, status: "\(displayName) running"))
    for _ in 0..<100 {
      if isCancelled(request.dispatchId) {
        await sink.emit(bridgeEvent(request, .cancelled, status: "Dispatch cancelled."))
        return RuntimeDispatchTerminalResult(
          status: "cancelled",
          finalText: nil,
          contentFormat: .plain,
          error: RuntimeBridgeError(
            category: "cancelled", message: "Dispatch cancelled.", recoverable: false, detail: [:]),
          metadata: [:]
        )
      }
      try? await Task.sleep(nanoseconds: 10_000_000)
    }
    return failedResult("timeout", "Waiting runtime did not finish.", recoverable: false)
  }

  func cancelDispatch(dispatchId: String, correlationId: String) async
    -> CancelRuntimeDispatchResult
  {
    guard supportsCancellation else {
      return CancelRuntimeDispatchResult(
        status: "not_supported", message: "Cancellation is unavailable.")
    }
    markCancelled(dispatchId)
    return CancelRuntimeDispatchResult(status: "cancelled", message: "Cancel requested.")
  }

  private func markCancelled(_ dispatchId: String) {
    lock.lock()
    cancelledDispatches.insert(dispatchId)
    lock.unlock()
  }

  private func isCancelled(_ dispatchId: String) -> Bool {
    lock.lock()
    defer { lock.unlock() }
    return cancelledDispatches.contains(dispatchId)
  }
}

