private final class RecordingMarketplaceToolCloudTransport:
  RelayCloudTransport, @unchecked Sendable
{
  struct Request {
    var method: String
    var path: String
    var body: [String: Any]?
    var accessToken: String?
  }

  private let lock = NSLock()
  private var request: Request?

  var lastRequest: Request? {
    lock.withLock { request }
  }

  func send(
    method: String,
    path: String,
    body: [String: Any]?,
    accessToken: String?
  ) async throws -> [String: Any] {
    lock.withLock {
      request = Request(
        method: method,
        path: path,
        body: body,
        accessToken: accessToken
      )
    }
    if method == "GET" {
      return [
        "tools": [[
          "name": "jotform_create_form",
          "functionName": "jotform_create_form",
          "appSlug": "jotform",
          "execution": [
            "transport": "clawchat_bridge_marketplace_tool",
            "endpointBasePath":
              "/api/v1/bridge/agents/{agentId}/marketplace-tools/jotform",
            "requiresBridgeAccessToken": true,
          ] as [String: Any],
        ] as [String: Any]],
      ]
    }
    return [
      "ok": true,
      "provider": "jotform",
    ]
  }
}

private final class RotatingRefreshRelayCloudTransport:
  RelayCloudTransport, @unchecked Sendable
{
  private let lock = NSLock()
  private var count = 0

  func refreshCount() -> Int {
    lock.lock()
    defer { lock.unlock() }
    return count
  }

  private func nextRequestNumber() -> Int {
    lock.lock()
    defer { lock.unlock() }
    count += 1
    return count
  }

  func send(
    method: String,
    path: String,
    body: [String: Any]?,
    accessToken: String?
  ) async throws -> [String: Any] {
    guard method == "POST", path == "auth/refresh", accessToken == nil,
      body?["refreshToken"] as? String == "service-test-refresh-token"
    else {
      throw ServiceTestFailure("token refresh used an unexpected Railway request")
    }
    let requestNumber = nextRequestNumber()
    try await Task.sleep(nanoseconds: 50_000_000)
    guard requestNumber == 1 else {
      throw RelayError(.permissionDenied, "Refresh token already rotated.")
    }
    return [
      "accessToken": "rotated-access-token",
      "refreshToken": "rotated-refresh-token",
      "expiresIn": 900,
    ]
  }
}

private final class AutomaticWorkspaceLinkRelayCloudTransport:
  RelayCloudTransport, @unchecked Sendable
{
  private let lock = NSLock()
  private var paths: [String] = []
  private var bodies: [(path: String, body: [String: Any]?)] = []
  private var workspaceImportFailuresRemaining: Int
  private let changeFeed: [[String: Any]]
  private let canonicalObjectIds: [String: String]
  private var deliveredChangeFeed = false

  init(
    workspaceImportFailures: Int = 0,
    changes: [[String: Any]] = [],
    canonicalObjectIds: [String: String] = [:]
  ) {
    workspaceImportFailuresRemaining = workspaceImportFailures
    changeFeed = changes
    self.canonicalObjectIds = canonicalObjectIds
  }

  func recordedPaths() -> [String] {
    lock.lock()
    defer { lock.unlock() }
    return paths
  }

  func recordedBodies(for path: String) -> [[String: Any]] {
    lock.lock()
    defer { lock.unlock() }
    return bodies.compactMap { $0.path == path ? $0.body : nil }
  }

  private func record(_ path: String, body: [String: Any]?) {
    lock.lock()
    paths.append(path)
    bodies.append((path, body))
    lock.unlock()
  }

  private func shouldFailWorkspaceImport() -> Bool {
    lock.lock()
    defer { lock.unlock() }
    guard workspaceImportFailuresRemaining > 0 else { return false }
    workspaceImportFailuresRemaining -= 1
    return true
  }

  private func nextChanges() -> [[String: Any]] {
    lock.lock()
    defer { lock.unlock() }
    guard !deliveredChangeFeed else { return [] }
    deliveredChangeFeed = true
    return changeFeed
  }

  func send(
    method: String,
    path: String,
    body: [String: Any]?,
    accessToken: String?
  ) async throws -> [String: Any] {
    record(path, body: body)

    guard accessToken == "service-test-access-token" else {
      throw ServiceTestFailure("automatic workspace link omitted the signed-in bearer token")
    }
    switch (method, path) {
    case ("POST", "client-installations"):
      return ["id": "installation-auto"]
    case ("POST", "workspace-sync-links"):
      return ["id": "workspace-link-auto"]
    case ("POST", "workspace-imports"):
      if shouldFailWorkspaceImport() {
        throw RelayError(.internalError, "Simulated interrupted initial import.")
      }
      return ["id": "workspace-import-auto"]
    case ("POST", let value) where value.hasPrefix("workspace-imports/")
      && value.hasSuffix("/batches"):
      let records = body?["records"] as? [[String: Any]] ?? []
      return [
        "outcomes": records.map { record in
          [
            "objectType": record["objectType"] as? String ?? "",
            "objectId": record["objectId"] as? String ?? "",
            "status": "accepted",
            "canonicalObjectId": canonicalObjectIds[record["objectId"] as? String ?? ""]
              ?? record["objectId"] as? String ?? "",
            "serverVersion": "1",
          ]
        }
      ]
    case ("POST", let value) where value.hasSuffix("/mutations"):
      let mutations = body?["mutations"] as? [[String: Any]] ?? []
      return [
        "outcomes": mutations.map { mutation in
          [
            "clientMutationId": mutation["clientMutationId"] as? String ?? "",
            "status": "acknowledged",
            "canonicalObjectId": mutation["objectId"] as? String ?? "",
            "serverVersion": "1",
          ]
        }
      ]
    case ("GET", let value) where value.contains("/changes?"):
      let changes = nextChanges()
      return ["changes": changes, "cursor": "1", "hasMore": false]
    default:
      throw ServiceTestFailure(
        "automatic workspace link used an unexpected Railway route: \(method) \(path)"
      )
    }
  }
}

