private struct SessionSecurityRelayCloudTransport: RelayCloudTransport {
  func send(
    method: String,
    path: String,
    body: [String: Any]?,
    accessToken: String?
  ) async throws -> [String: Any] {
    guard accessToken == "current-cloud-access-token" else {
      throw ServiceTestFailure("Relay Cloud session security omitted the current bearer token")
    }
    switch (method, path) {
    case ("POST", "auth/logout"):
      guard body?.isEmpty == true else {
        throw ServiceTestFailure("Relay Cloud logout sent an unexpected request body")
      }
    case ("POST", "auth/change-password"):
      guard body?["currentPassword"] as? String == "current-password",
            body?["newPassword"] as? String == "new-password",
            body?.count == 2 else {
        throw ServiceTestFailure("Relay Cloud password change sent an unexpected request body")
      }
    case ("DELETE", "auth/sessions/native-session_1"):
      guard body == nil else {
        throw ServiceTestFailure("native session revocation sent an unexpected request body")
      }
    case ("POST", "auth/web/sessions/browser-session_1/revoke"):
      guard body?.isEmpty == true else {
        throw ServiceTestFailure("browser session revocation sent an unexpected request body")
      }
    default:
      throw ServiceTestFailure("Relay Cloud session security used an unexpected route")
    }
    return ["success": true]
  }
}

