private func writeHermesOwnershipMarker(
  profileHome: URL,
  agentId: String,
  profileSlug: String,
  ownershipNonce: String
) throws {
  let object: [String: Any] = [
    "schemaVersion": 2,
    "agentId": agentId,
    "profileSlug": profileSlug,
    "managedBy": "Relay Console",
    "ownershipNonce": ownershipNonce,
  ]
  let data = try JSONSerialization.data(
    withJSONObject: object,
    options: [.prettyPrinted, .sortedKeys]
  )
  try data.write(
    to: profileHome.appendingPathComponent(".relay-console-profile.json"),
    options: .atomic
  )
}

private func expectedHermesProfileSlug(for agent: AgentWithBinding) -> String {
  let raw = agent.binding.externalAgentId ?? agent.name
  let base = raw.trimmingCharacters(in: .whitespacesAndNewlines)
    .lowercased()
    .replacingOccurrences(
      of: #"[^a-z0-9_-]+"#,
      with: "-",
      options: .regularExpression
    )
    .replacingOccurrences(
      of: #"^[^a-z0-9]+"#,
      with: "",
      options: .regularExpression
    )
    .replacingOccurrences(
      of: #"[^a-z0-9]+$"#,
      with: "",
      options: .regularExpression
    )
  let safeBase = String((base.isEmpty ? "agent" : base).prefix(36))
  let suffix = String(
    agent.id.replacingOccurrences(
      of: #"[^a-z0-9]"#,
      with: "",
      options: .regularExpression
    ).suffix(12)
  )
  return String("relay-\(safeBase)-\(suffix.isEmpty ? "profile" : suffix)".prefix(63))
}

private func objectValue(_ value: JSONValue?) -> JSONRecord? {
  if case .object(let object)? = value {
    return object
  }
  return nil
}

private func arrayValue(_ value: JSONValue?) -> [JSONValue] {
  if case .array(let array)? = value {
    return array
  }
  return []
}
